def get_vcpus(env_var: str = "XGB_SEARCH_NJOBS") -> int:
    """Prefer ENV override; else fall back to container vCPU count."""
    val = os.getenv(env_var, "")
    try:
        n = int(val) if val != "" else (os.cpu_count() or 1)
    except Exception:
        n = os.cpu_count() or 1
    return max(1, n)

