def _sys_norm_market(v):
    s = str(v or "").lower().strip()
    if s in {"spread", "spreads", "ats"}:
        return "spreads"
    if s in {"total", "totals", "ou", "o/u", "overunder"}:
        return "totals"
    if s in {"h2h", "ml", "moneyline", "money_line", "headtohead"}:
        return "h2h"
    return s


def _sys_float64_series(values, index) -> pd.Series:
    """Normalize nullable pandas numerics/booleans to plain float64 + np.nan.

    BigQuery DataFrames frequently use pandas nullable Int64/Float64/boolean
    extension dtypes. Comparisons on those dtypes can produce pd.NA, and a later
    .astype("int8") then raises "cannot convert NA to integer". System rules are
    deterministic 0/1 flags, so missing inputs must remain np.nan until the
    DataReady/rule expression explicitly resolves them.
    """
    if isinstance(values, pd.Series):
        numeric = pd.to_numeric(values, errors="coerce")
        try:
            arr = numeric.to_numpy(dtype=np.float64, na_value=np.nan)
        except TypeError:
            arr = np.asarray(numeric.astype("float64"), dtype=np.float64)
        return pd.Series(arr, index=index, dtype="float64")

    numeric = pd.to_numeric(pd.Series(values, index=index), errors="coerce")
    try:
        arr = numeric.to_numpy(dtype=np.float64, na_value=np.nan)
    except TypeError:
        arr = np.asarray(numeric.astype("float64"), dtype=np.float64)
    return pd.Series(arr, index=index, dtype="float64")


def _sys_normalize_nullable_numeric_frame(df: pd.DataFrame) -> pd.DataFrame:
    """Return a copy with nullable numeric/boolean extension dtypes flattened.

    BigQuery commonly yields pandas Int64/Float64/boolean extension columns.
    Those columns propagate pd.NA through comparisons, which can later make a
    deterministic ``.astype("int8")`` fail.  The Pathi/Big Al state builder
    is numeric/boolean by contract, so extension numerics are normalized to
    plain float64 + np.nan before any rule expressions are evaluated.
    Text/datetime/category columns are left untouched.
    """
    if df is None or df.empty:
        return df.copy() if isinstance(df, pd.DataFrame) else df
    out = df.copy()
    for c in out.columns:
        s = out[c]
        try:
            is_ext = pd.api.types.is_extension_array_dtype(s.dtype)
            is_num = pd.api.types.is_numeric_dtype(s.dtype) or pd.api.types.is_bool_dtype(s.dtype)
        except Exception:
            is_ext = False
            is_num = False
        if is_ext and is_num:
            out[c] = _sys_float64_series(s, out.index)
    return out


def _sys_int_flag(values, index, dtype="int8") -> pd.Series:
    """NA/inf-safe deterministic integer flag/count conversion."""
    x = _sys_float64_series(values, index).replace([np.inf, -np.inf], np.nan).fillna(0.0)
    arr = np.rint(x.to_numpy(dtype=np.float64, na_value=np.nan))
    arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
    return pd.Series(arr, index=index).astype(dtype)


def _sys_num_series(df: pd.DataFrame, *names, default=np.nan) -> pd.Series:
    for name in names:
        if name in df.columns:
            return _sys_float64_series(df[name], df.index)
    return pd.Series(default, index=df.index, dtype="float64")


def _sys_bool_series(df: pd.DataFrame, *names, default=np.nan) -> pd.Series:
    for name in names:
        if name in df.columns:
            s = df[name]
            if pd.api.types.is_bool_dtype(s) or pd.api.types.is_numeric_dtype(s):
                return _sys_float64_series(s, df.index)
            t = s.astype("string").str.lower().str.strip()
            out = pd.Series(np.nan, index=df.index, dtype="float64")
            out[t.isin(["1", "true", "yes", "y", "t"])] = 1.0
            out[t.isin(["0", "false", "no", "n", "f"])] = 0.0
            return out
    return pd.Series(default, index=df.index, dtype="float64")


def _sys_text_series(df: pd.DataFrame, *names, default="") -> pd.Series:
    for name in names:
        if name in df.columns:
            return df[name].astype(str).replace({"nan": "", "None": ""})
    return pd.Series(default, index=df.index, dtype="object")


def _sys_amer_prob(s: pd.Series) -> pd.Series:
    x = pd.to_numeric(s, errors="coerce")
    p = np.where(
        x > 0,
        100.0 / (x + 100.0),
        np.where(x < 0, (-x) / ((-x) + 100.0), np.nan),
    )
    return pd.Series(p, index=s.index, dtype="float64")


def _sys_consecutive_prior(g: pd.DataFrame, col: str, grp_cols: list[str]) -> pd.Series:
    """Count consecutive TRUE results immediately before each row, leakage-safe.

    pandas ``GroupBy.indices`` returns *positional* row locations, not index
    labels.  Training slices can retain a sparse/non-RangeIndex, so using
    ``.loc`` with those positions can raise KeyError.  Work positionally in
    NumPy and restore the original index only on the returned Series.
    """
    if g is None or g.empty:
        return pd.Series(index=getattr(g, "index", None), dtype="int16")

    prev = g.groupby(grp_cols, sort=False, dropna=False)[col].shift(1)
    prev_vals = prev.fillna(False).astype(bool).to_numpy(copy=False)
    out_vals = np.zeros(len(g), dtype=np.int16)

    for positions in g.groupby(grp_cols, sort=False, dropna=False).indices.values():
        pos = np.asarray(positions, dtype=np.intp)
        vals = prev_vals[pos]
        run = 0
        for j, v in enumerate(vals):
            run = (run + 1) if bool(v) else 0
            out_vals[pos[j]] = run

    return pd.Series(out_vals, index=g.index, dtype="int16")


def _sys_pick_market_rows(df: pd.DataFrame, market: str) -> pd.DataFrame:
    """One representative row per game/outcome, sharp-book-first and latest."""
    if df is None or df.empty:
        return pd.DataFrame()
    d = df[df["Market"].eq(market)].copy()
    if d.empty:
        return d
    d["__sharp"] = d.get("Bookmaker", "").astype(str).str.lower().isin(set(SHARP_BOOKS)).astype(int)
    if "Snapshot_Timestamp" in d.columns:
        d["Snapshot_Timestamp"] = pd.to_datetime(d["Snapshot_Timestamp"], errors="coerce", utc=True)
        d = d.sort_values(["__sharp", "Snapshot_Timestamp"], ascending=[False, False])
    else:
        d = d.sort_values(["__sharp"], ascending=[False])
    d = d.drop_duplicates(["Game_Key", "Outcome_Norm"], keep="first")
    return d.drop(columns=["__sharp"], errors="ignore")



# Narrow source contract for the Pathi/Big Al state engine.  The training view is
# snapshot/book grained and can be very wide; carrying the whole frame into the
# state builder can add many GiB.  Keep only fields the deterministic rules use.
_PATHI_BIGAL_SYSTEM_SOURCE_COLS = [
    "Sport", "Market", "Outcome", "Outcome_Norm", "Bookmaker", "Book",
    "Value", "Odds_Price", "First_Odds", "First_Odds_Price", "Open_Odds", "Old_Odds",
    "First_Line_Value", "Opening_Line", "Open_Value",
    "Snapshot_Timestamp", "Game_Start", "feat_Game_Start", "Commence_Hour",
    "Merge_Key_Short", "Game_Key", "Home_Team_Norm", "Away_Team_Norm", "Home_Team", "Away_Team",
    "SHARP_HIT_BOOL", "ATS_Cover_Margin",
    "Season", "Week", "Week_Number", "Game_Week", "Season_Type", "Game_Type",
    "Is_Preseason", "Is_Postseason", "Is_Playoffs", "Is_Regular_Season", "Is_Finals",
    "Is_Conference_Game", "Home_Conference", "Away_Conference",
    "Season_Stage", "Tournament_Type", "Round_Name",
    "Is_Cup", "Is_PlayIn", "Is_Bowl", "Is_Conference_Tournament", "Is_Neutral_Site",
    "Is_Division_Game", "Home_Division", "Away_Division",
    "Home_Subdivision", "Away_Subdivision", "Home_League_Group", "Away_League_Group",
    "Regular_Season_Final_Week",
    "Home_Is_Defending_Champion", "Away_Is_Defending_Champion",
    "Home_Prior_Season_Playoff", "Away_Prior_Season_Playoff",
    "Home_Is_Final_Home_Game", "Away_Is_Final_Home_Game", "Is_Final_Home_Game",
    "Home_Eliminated_With_Loss", "Away_Eliminated_With_Loss",
    "Home_Would_Be_Eliminated_With_Loss", "Away_Would_Be_Eliminated_With_Loss",
    "Series_Game_Number", "Home_Series_Wins", "Away_Series_Wins", "Revenge_Flag",
]



BIGAL_CONTEXT_VIEW = "sharplogger.sharp_data.bigal_game_context_enriched"

_BIGAL_CONTEXT_COLUMNS = [
    "Merge_Key_Short", "Sport", "Season", "Game_Start",
    "Home_Team_Norm", "Away_Team_Norm",
    "Home_Context_Team_Norm", "Away_Context_Team_Norm",
    "Is_Neutral_Site",
    "Home_Use_For_Context", "Away_Use_For_Context",
    "Home_Conference", "Home_Division", "Home_Subdivision", "Home_League_Group",
    "Away_Conference", "Away_Division", "Away_Subdivision", "Away_League_Group",
    "Is_Conference_Game", "Is_Division_Game",
    "Week_Number",
]

_BIGAL_CONTEXT_SCHEMA_CACHE = None

def enrich_bigal_context_from_bq(df_rows: pd.DataFrame) -> pd.DataFrame:
    """Fill Big Al schedule/team context from the optional BigQuery context view.

    Existing non-null row values always win.  The helper is fail-open so the
    model still trains/scores before the reference tables are populated.
    """
    global _BIGAL_CONTEXT_SCHEMA_CACHE
    if df_rows is None or df_rows.empty:
        return df_rows.copy()
    out = df_rows.copy()
    if "Merge_Key_Short" not in out.columns:
        return out

    keys = (
        out["Merge_Key_Short"].astype("string").str.lower().str.strip()
    )
    valid_keys = sorted({
        str(x) for x in keys.dropna().tolist()
        if str(x).strip() and str(x).lower() not in {"nan", "none", "<na>"}
    })
    if not valid_keys:
        return out

    try:
        if _BIGAL_CONTEXT_SCHEMA_CACHE is None:
            _BIGAL_CONTEXT_SCHEMA_CACHE = {f.name for f in bq_client.get_table(BIGAL_CONTEXT_VIEW).schema}
        present = set(_BIGAL_CONTEXT_SCHEMA_CACHE)
        wanted = [c for c in _BIGAL_CONTEXT_COLUMNS if c in present]
        if "Merge_Key_Short" not in wanted:
            return out

        # Key-based lookup is exact and cheap for live batches.  Chunk large
        # training sets to stay comfortably below query-parameter limits.
        parts = []
        chunk_size = 5000
        for start in range(0, len(valid_keys), chunk_size):
            chunk = valid_keys[start:start + chunk_size]
            sql = (
                "SELECT " + ", ".join(f"`{c}`" for c in wanted) +
                f" FROM `{BIGAL_CONTEXT_VIEW}` "
                "WHERE LOWER(TRIM(CAST(Merge_Key_Short AS STRING))) IN UNNEST(@keys)"
            )
            cfg = bigquery.QueryJobConfig(query_parameters=[
                bigquery.ArrayQueryParameter("keys", "STRING", chunk)
            ])
            part = bq_client.query(sql, job_config=cfg).to_dataframe(create_bqstorage_client=True)
            if part is not None and not part.empty:
                parts.append(part)
        if not parts:
            return out

        ctx = pd.concat(parts, ignore_index=True, sort=False)
        ctx["Merge_Key_Short"] = ctx["Merge_Key_Short"].astype("string").str.lower().str.strip()
        ctx = ctx.sort_values("Game_Start" if "Game_Start" in ctx.columns else "Merge_Key_Short")
        ctx = ctx.drop_duplicates("Merge_Key_Short", keep="last")

        # Merge with suffix and use BQ context only to fill missing values.
        before = len(out)
        out["Merge_Key_Short"] = keys
        payload = [c for c in wanted if c not in {"Merge_Key_Short", "Sport", "Game_Start"}]
        merge_cols = ["Merge_Key_Short"] + payload
        out = out.merge(ctx[merge_cols], on="Merge_Key_Short", how="left", suffixes=("", "__bigalctx"), validate="many_to_one")
        if len(out) != before:
            raise RuntimeError(f"BigAl context merge changed row count {before}->{len(out)}")
        for c in payload:
            alt = c + "__bigalctx"
            if alt not in out.columns:
                continue
            if c in out.columns:
                base = out[c]
                # blank strings are missing context too.
                if pd.api.types.is_object_dtype(base) or pd.api.types.is_string_dtype(base):
                    missing = base.isna() | base.astype("string").str.strip().isin(["", "nan", "None", "<NA>"])
                    out.loc[missing, c] = out.loc[missing, alt]
                else:
                    out[c] = base.combine_first(out[alt])
            else:
                out[c] = out[alt]
            out.drop(columns=[alt], inplace=True, errors="ignore")
        return out
    except Exception as e:
        logging.info("BigAl context view unavailable/incomplete; using row-local context: %s", e)
        return out


def prepare_pathi_bigal_training_source_lowmem(
    df_rows: pd.DataFrame,
    df_results: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Build a narrow one-row-per-game/market/outcome state source for training.

    Important:
      * Uses Merge_Key_Short as the physical Game_Key for system history.
      * Prefers feat_Game_Start on view-backed training data.
      * Reduces snapshot/book history BEFORE the expensive team-state expansion.
      * Adds final scores by indexed maps rather than merging wide frames.
    """
    if df_rows is None or df_rows.empty:
        return pd.DataFrame()

    keep = [c for c in _PATHI_BIGAL_SYSTEM_SOURCE_COLS if c in df_rows.columns]
    src = df_rows.loc[:, keep].copy()

    # View tables use feat_Game_Start as the canonical event timestamp.
    if "feat_Game_Start" in src.columns:
        src["Game_Start"] = pd.to_datetime(src["feat_Game_Start"], errors="coerce", utc=True)
    elif "Game_Start" in src.columns:
        src["Game_Start"] = pd.to_datetime(src["Game_Start"], errors="coerce", utc=True)
    elif "Commence_Hour" in src.columns:
        src["Game_Start"] = pd.to_datetime(src["Commence_Hour"], errors="coerce", utc=True)
    else:
        src["Game_Start"] = pd.NaT

    if "Snapshot_Timestamp" in src.columns:
        src["Snapshot_Timestamp"] = pd.to_datetime(src["Snapshot_Timestamp"], errors="coerce", utc=True)

    # Normalize the physical-game key.  Never use the market/outcome Game_Key for
    # historical streaks/rematches because it fragments one game into many rows.
    if "Merge_Key_Short" in src.columns:
        src["Merge_Key_Short"] = src["Merge_Key_Short"].astype("string").str.lower().str.strip()
    else:
        src["Merge_Key_Short"] = pd.Series(pd.NA, index=src.index, dtype="string")

    if {"Home_Team_Norm", "Away_Team_Norm"}.issubset(src.columns):
        h = src["Home_Team_Norm"].astype("string").str.lower().str.strip()
        a = src["Away_Team_Norm"].astype("string").str.lower().str.strip()
        hour = src["Game_Start"].dt.floor("h").dt.strftime("%Y-%m-%dT%H:00Z")
        fallback = h.where(h <= a, a).fillna("") + "_" + a.where(h <= a, h).fillna("") + "_" + hour.fillna("")
        bad = src["Merge_Key_Short"].isna() | src["Merge_Key_Short"].isin(["", "nan", "none", "<na>"])
        src.loc[bad, "Merge_Key_Short"] = fallback.loc[bad]

    src = src[src["Merge_Key_Short"].notna()].copy()
    src["Game_Key"] = src["Merge_Key_Short"].astype("string").str.lower().str.strip()
    src["Sport"] = src.get("Sport", "").astype("string").str.upper().str.strip()
    src["Market"] = src.get("Market", "").astype("string").map(_sys_norm_market)
    src["Outcome"] = src.get("Outcome", "").astype("string").str.lower().str.strip()
    src["Bookmaker"] = src.get("Bookmaker", src.get("Book", "")).astype("string").str.lower().str.strip()

    # Optional metadata-heavy Big Al context from BigQuery reference tables.
    src = enrich_bigal_context_from_bq(src)

    # Pick one representative market row before the state builder.  This converts
    # potentially millions of snapshot/book rows into roughly 6 rows per game.
    src["__sharp"] = src["Bookmaker"].isin(set(SHARP_BOOKS)).astype("int8")
    sort_cols = ["Game_Key", "Market", "Outcome", "__sharp"]
    ascending = [True, True, True, False]
    if "Snapshot_Timestamp" in src.columns:
        sort_cols.append("Snapshot_Timestamp")
        ascending.append(False)
    src.sort_values(sort_cols, ascending=ascending, inplace=True, kind="mergesort")
    src.drop_duplicates(["Game_Key", "Market", "Outcome"], keep="first", inplace=True)
    src.drop(columns=["__sharp"], inplace=True, errors="ignore")

    # Score enrichment by maps avoids a wide DataFrame merge and another large
    # temporary allocation. game_scores_final legitimately uses Game_Start.
    if df_results is not None and not df_results.empty and "Merge_Key_Short" in df_results.columns:
        rcols = [c for c in ["Merge_Key_Short", "Score_Home_Score", "Score_Away_Score"] if c in df_results.columns]
        if len(rcols) >= 2:
            rs = df_results.loc[:, rcols].copy()
            rs["Merge_Key_Short"] = rs["Merge_Key_Short"].astype("string").str.lower().str.strip()
            rs.drop_duplicates("Merge_Key_Short", keep="last", inplace=True)
            rs.set_index("Merge_Key_Short", inplace=True)
            keys = src["Merge_Key_Short"]
            for c in ("Score_Home_Score", "Score_Away_Score"):
                if c in rs.columns:
                    mapped = pd.to_numeric(keys.map(rs[c]), errors="coerce")
                    if c in src.columns:
                        src[c] = pd.to_numeric(src[c], errors="coerce").combine_first(mapped)
                    else:
                        src[c] = mapped
            del rs

    # Downcast state-source numerics immediately.  Team-state calculations can
    # upcast locally where necessary, but the retained source stays compact.
    for c in src.select_dtypes(include=["float64"]).columns:
        src[c] = pd.to_numeric(src[c], errors="coerce", downcast="float")
    for c in src.select_dtypes(include=["int64"]).columns:
        src[c] = pd.to_numeric(src[c], errors="coerce", downcast="integer")

    return src.reset_index(drop=True)


def attach_pathi_bigal_training_features_lowmem(
    df_rows: pd.DataFrame,
    state: pd.DataFrame,
) -> pd.DataFrame:
    """Attach only model-eligible system columns using the physical-game key.

    The training view's Game_Key is market/outcome-specific, while the state engine
    is intentionally keyed by Merge_Key_Short.  Temporarily physicalize Game_Key,
    attach, restore the original line key, and discard non-model state payload.
    """
    if df_rows is None or df_rows.empty:
        return df_rows
    if state is None or state.empty:
        return add_pathi_football_key_features(df_rows)
    if "Merge_Key_Short" not in df_rows.columns:
        return attach_pathi_bigal_features_to_market_rows(df_rows, state)

    original_cols = set(df_rows.columns)
    df_rows["__Training_Line_Game_Key"] = df_rows["Game_Key"].astype("string")
    df_rows["Game_Key"] = df_rows["Merge_Key_Short"].astype("string").str.lower().str.strip()

    enriched = attach_pathi_bigal_features_to_market_rows(df_rows, state)
    if "__Training_Line_Game_Key" in enriched.columns:
        enriched["Game_Key"] = enriched["__Training_Line_Game_Key"].astype("string")
        enriched.drop(columns=["__Training_Line_Game_Key"], inplace=True, errors="ignore")

    # Training only needs auditable numeric system features.  Discard human text
    # and state-helper payload that would otherwise be repeated on every book row.
    added = [c for c in enriched.columns if c not in original_cols]
    keep_added = {
        c for c in added
        if ((str(c).startswith(("Pathi_", "BigAl_", "System_")) and c != "System_Signals_Text")
            or c in PATHI_BIGAL_ADDITIONAL_MODEL_FEATURES)
    }
    drop_added = [c for c in added if c not in keep_added and c not in {"Game_Key"}]
    if drop_added:
        enriched.drop(columns=drop_added, inplace=True, errors="ignore")
    enriched.drop(columns=["System_Signals_Text", "Pathi_Active_Text", "BigAl_Active_Text", "Team"], inplace=True, errors="ignore")

    # Compact deterministic features immediately.
    for c in keep_added:
        if c not in enriched.columns:
            continue
        if pd.api.types.is_float_dtype(enriched[c]):
            enriched[c] = pd.to_numeric(enriched[c], errors="coerce").astype("float32")
        elif pd.api.types.is_integer_dtype(enriched[c]) or pd.api.types.is_bool_dtype(enriched[c]):
            vals = pd.to_numeric(enriched[c], errors="coerce")
            if vals.dropna().isin([0, 1]).all():
                enriched[c] = vals.fillna(0).astype("int8")
            else:
                enriched[c] = vals.fillna(0).astype("int16")
    return enriched



def build_30min_line_timing_features(snapshot_rows: pd.DataFrame, sharp_books=None) -> pd.DataFrame:
    """Leakage-safe 30/60/120-minute market-path features at book/outcome grain."""
    keys = ["Game_Key", "Market", "Outcome", "Bookmaker"]
    out_cols = keys + [
        "Line_Move_30m","Line_Move_60m","Line_Move_120m","Line_Move_Last30m","Line_Move_Last60m",
        "Line_Move_From_Open","Line_Move_Velocity_60m","Line_Move_Velocity_120m","Direction_Changes_Count",
        "Max_Line_Seen","Min_Line_Seen","Current_vs_Best_Line","Current_vs_Worst_Line",
        "Sharp_Book_Move_30m","Sharp_Book_Move_60m","Sharp_Move_Before_Market","Sharp_Lead_Time_Minutes",
        "Sharp_Soft_Divergence","Sharp_Consensus_Direction","Crossed_Key_3_Last60m","Crossed_Key_7_Last60m",
        "Crossed_Key_10_Last60m","Crossed_Key_14_Last60m","Minutes_Since_Key_Cross",
        "Key_Cross_Confirmed_By_Sharp_Books","Key_Cross_Reversed","Key_Cross_Persistence",
    ]
    if snapshot_rows is None or snapshot_rows.empty or not all(k in snapshot_rows.columns for k in keys):
        return pd.DataFrame(columns=out_cols)
    if "Snapshot_Timestamp" not in snapshot_rows.columns:
        return pd.DataFrame(columns=out_cols)
    s = snapshot_rows[[c for c in keys + ["Snapshot_Timestamp","Value","Odds_Price"] if c in snapshot_rows.columns]].copy()
    for k in keys:
        s[k] = s[k].astype(str).str.lower().str.strip()
    s["Snapshot_Timestamp"] = pd.to_datetime(s["Snapshot_Timestamp"], utc=True, errors="coerce")
    s["Value"] = pd.to_numeric(s.get("Value"), errors="coerce")
    s["Odds_Price"] = pd.to_numeric(s.get("Odds_Price"), errors="coerce")
    s = s.dropna(subset=["Snapshot_Timestamp"])
    if s.empty:
        return pd.DataFrame(columns=out_cols)
    sharp = {str(x).lower().strip() for x in (sharp_books or globals().get("SHARP_BOOKS", []))}

    def amer_prob(x):
        x = float(x)
        if not np.isfinite(x) or x == 0: return np.nan
        return 100.0/(x+100.0) if x > 0 else (-x)/((-x)+100.0)

    records=[]
    # market-wide reference is computed from book-level normalized paths below.
    book_paths={}
    for name,g in s.groupby(keys, sort=False, observed=True):
        g=g.sort_values("Snapshot_Timestamp").drop_duplicates("Snapshot_Timestamp", keep="last")
        market=str(name[1])
        raw = g["Odds_Price"].map(amer_prob) if market == "h2h" else g["Value"]
        arr=pd.to_numeric(raw, errors="coerce")
        valid=arr.notna()
        if valid.sum()<1: continue
        gg=g.loc[valid].copy(); vals=arr.loc[valid].to_numpy(float); times=gg["Snapshot_Timestamp"].to_list()
        current=float(vals[-1]); openv=float(vals[0]); tcur=times[-1]
        def at_before(mins):
            target=tcur-pd.Timedelta(minutes=mins)
            ix=np.where(np.array([pd.Timestamp(x).value for x in times], dtype=np.int64) <= target.value)[0]
            return float(vals[ix[-1]]) if len(ix) else float(vals[0])
        v30,v60,v120=at_before(30),at_before(60),at_before(120)
        dif=np.diff(vals)
        signs=np.sign(dif[np.abs(dif)>1e-12])
        changes=int(np.sum(signs[1:] != signs[:-1])) if len(signs)>1 else 0
        best=float(np.nanmax(vals)); worst=float(np.nanmin(vals))
        # Team-specific spread: numerically lower is a better/stronger line signal; h2h uses probability.
        rec=dict(zip(keys,name))
        rec.update({
            "Line_Move_30m":current-v30,"Line_Move_60m":current-v60,"Line_Move_120m":current-v120,
            "Line_Move_Last30m":current-v30,"Line_Move_Last60m":current-v60,"Line_Move_From_Open":current-openv,
            "Line_Move_Velocity_60m":current-v60,"Line_Move_Velocity_120m":(current-v120)/2.0,
            "Direction_Changes_Count":changes,"Max_Line_Seen":best,"Min_Line_Seen":worst,
            "Current_vs_Best_Line":current-best,"Current_vs_Worst_Line":current-worst,
        })
        # Football key crossing is spread-only, sign-aware around ±3/7/10/14.
        for key in (3,7,10,14):
            crossed=0
            if market in ("spread","spreads"):
                for kv in (-float(key), float(key)):
                    if (v60-kv)*(current-kv) <= 0 and abs(current-v60)>1e-12 and not (v60==current==kv): crossed=1
            rec[f"Crossed_Key_{key}_Last60m"]=crossed
        last_cross=np.nan; reversed_flag=0; persistence=0.0
        if market in ("spread","spreads") and len(vals)>=2:
            cross_events=[]
            for j in range(1,len(vals)):
                for key in (3,7,10,14):
                    for kv in (-float(key),float(key)):
                        if (vals[j-1]-kv)*(vals[j]-kv)<=0 and vals[j-1]!=vals[j]: cross_events.append(j)
            if cross_events:
                j=cross_events[-1]; last_cross=(tcur-times[j]).total_seconds()/60.0
                post=vals[j:]
                persistence=float(np.mean(np.sign(post-vals[j-1]) == np.sign(vals[j]-vals[j-1]))) if len(post) else 0.0
                reversed_flag=int(np.sign(current-vals[j-1]) != np.sign(vals[j]-vals[j-1]))
        rec["Minutes_Since_Key_Cross"]=last_cross
        rec["Key_Cross_Reversed"]=reversed_flag
        rec["Key_Cross_Persistence"]=persistence
        records.append(rec)
        book_paths[name]=(tcur,current,v30,v60,openv)
    if not records: return pd.DataFrame(columns=out_cols)
    r=pd.DataFrame(records)
    # Cross-book sharp vs soft context at game/market/outcome grain.
    base=["Game_Key","Market","Outcome"]
    r["__sharp"] = r["Bookmaker"].isin(sharp).astype(int)
    r["__m30"] = r["Line_Move_30m"]
    r["__m60"] = r["Line_Move_60m"]
    for _,idx in r.groupby(base, sort=False, observed=True).groups.items():
        ix=list(idx); z=r.loc[ix]; sh=z[z["__sharp"].eq(1)]; sf=z[z["__sharp"].eq(0)]
        sh30=float(sh["__m30"].mean()) if not sh.empty else np.nan; sh60=float(sh["__m60"].mean()) if not sh.empty else np.nan
        soft60=float(sf["__m60"].mean()) if not sf.empty else np.nan
        cons=float(np.sign(sh["__m60"]).replace(0,np.nan).mean()) if not sh.empty else np.nan
        divergence=sh60-soft60 if np.isfinite(sh60) and np.isfinite(soft60) else np.nan
        lead=int(np.isfinite(sh60) and abs(sh60)>1e-12 and (not np.isfinite(soft60) or abs(soft60)<abs(sh60)*0.5))
        leadmins=30.0 if lead else 0.0
        confirm=int((z[[f"Crossed_Key_{k}_Last60m" for k in (3,7,10,14)]].max(axis=1)>0).loc[sh.index].sum() >= 2) if len(sh)>=2 else 0
        r.loc[ix,"Sharp_Book_Move_30m"]=sh30; r.loc[ix,"Sharp_Book_Move_60m"]=sh60
        r.loc[ix,"Sharp_Move_Before_Market"]=lead; r.loc[ix,"Sharp_Lead_Time_Minutes"]=leadmins
        r.loc[ix,"Sharp_Soft_Divergence"]=divergence; r.loc[ix,"Sharp_Consensus_Direction"]=cons
        r.loc[ix,"Key_Cross_Confirmed_By_Sharp_Books"]=confirm
    r.drop(columns=["__sharp","__m30","__m60"], inplace=True, errors="ignore")
    for c in r.columns:
        if c not in keys: r[c]=pd.to_numeric(r[c],errors="coerce").astype("float32")
    return r

def build_pathi_bigal_team_game_state(df_in: pd.DataFrame) -> pd.DataFrame:
    """
    Build leakage-safe team/game state from historical or historical+upcoming rows.

    The output is one row per (Sport, Game_Key, Team) and contains:
      * exact consecutive SU/ATS streaks BEFORE the game
      * previous 1/2/3 game results, scores, ATS margins, roles and prices
      * current ML/spread/total roles and opening/current prices
      * opponent mirrors of the prior-state fields
      * H2H meeting state and schedule-density fields
      * deterministic Pathi and Big Al rule flags

    Rows without a completed score can be appended for upcoming games. Their prior
    state remains leakage-safe because all historical calculations use shift(1).
    """
    if df_in is None or df_in.empty:
        return pd.DataFrame(columns=["Sport", "Game_Key", "Team"])

    d = df_in.copy()
    d.columns = [str(c).strip() for c in d.columns]
    # V12.0.2: flatten nullable BigQuery numerics before any rule/state math.
    d = _sys_normalize_nullable_numeric_frame(d)

    required = ["Game_Key", "Market", "Outcome"]
    if any(c not in d.columns for c in required):
        return pd.DataFrame(columns=["Sport", "Game_Key", "Team"])

    d["Sport"] = d.get("Sport", "").astype(str).str.upper().str.strip()
    d["Game_Key"] = d["Game_Key"].astype(str).str.lower().str.strip()
    d["Market"] = d["Market"].astype(str).map(_sys_norm_market)
    d["Outcome_Norm"] = d["Outcome"].astype(str).str.lower().str.strip()
    d["Home_Team_Norm"] = d.get("Home_Team_Norm", d.get("Home_Team", "")).astype(str).str.lower().str.strip()
    d["Away_Team_Norm"] = d.get("Away_Team_Norm", d.get("Away_Team", "")).astype(str).str.lower().str.strip()
    d["Game_Start"] = pd.to_datetime(d.get("Game_Start"), errors="coerce", utc=True)
    if "Snapshot_Timestamp" in d.columns:
        d["Snapshot_Timestamp"] = pd.to_datetime(d["Snapshot_Timestamp"], errors="coerce", utc=True)

    # Normalize outcome aliases to actual team names when the source uses home/away.
    d["Outcome_Team"] = np.where(
        d["Outcome_Norm"].eq("home"), d["Home_Team_Norm"],
        np.where(d["Outcome_Norm"].eq("away"), d["Away_Team_Norm"], d["Outcome_Norm"])
    )

    # ------------------------------------------------------------------
    # Game-level scaffold + optional metadata.
    # ------------------------------------------------------------------
    score_home = _sys_num_series(d, "Score_Home_Score", "Home_Score", "Score_Home")
    score_away = _sys_num_series(d, "Score_Away_Score", "Away_Score", "Score_Away")
    d["__Score_Home"] = score_home
    d["__Score_Away"] = score_away

    meta_candidates = [
        "Week", "Week_Number", "Game_Week", "Season", "Season_Type", "Game_Type",
        "Is_Preseason", "Is_Postseason", "Is_Playoffs", "Is_Regular_Season", "Is_Finals",
        "Is_Conference_Game", "Home_Conference", "Away_Conference",
    "Season_Stage", "Tournament_Type", "Round_Name",
    "Is_Cup", "Is_PlayIn", "Is_Bowl", "Is_Conference_Tournament", "Is_Neutral_Site",
    "Is_Division_Game", "Home_Division", "Away_Division",
    "Home_Subdivision", "Away_Subdivision", "Home_League_Group", "Away_League_Group",
    "Regular_Season_Final_Week",
        "Home_Is_Defending_Champion", "Away_Is_Defending_Champion",
        "Home_Prior_Season_Playoff", "Away_Prior_Season_Playoff",
        "Home_Is_Final_Home_Game", "Away_Is_Final_Home_Game", "Is_Final_Home_Game",
        "Home_Eliminated_With_Loss", "Away_Eliminated_With_Loss",
        "Home_Would_Be_Eliminated_With_Loss", "Away_Would_Be_Eliminated_With_Loss",
        "Series_Game_Number", "Home_Series_Wins", "Away_Series_Wins",
        "Revenge_Flag",
    ]
    game_cols = ["Sport", "Game_Key", "Game_Start", "Home_Team_Norm", "Away_Team_Norm", "__Score_Home", "__Score_Away"]
    game_cols += [c for c in meta_candidates if c in d.columns and c not in game_cols]
    games = (
        d[game_cols]
        .sort_values("Game_Start")
        .drop_duplicates("Game_Key", keep="last")
        .copy()
    )
    games["Season"] = _sys_num_series(games, "Season", default=np.nan).replace([np.inf, -np.inf], np.nan)
    # Sport-aware season fallback. Calendar-year grouping breaks NBA/NCAAB and
    # January NFL/NCAAF games when an explicit Season field is unavailable.
    _yr = games["Game_Start"].dt.year.astype("float64")
    _mo = games["Game_Start"].dt.month.astype("float64")
    _sp = games["Sport"].astype(str).str.upper()
    _season_fallback = _yr.copy()
    _season_fallback = np.where(_sp.isin(["NBA", "NCAAB", "NHL"]) & _mo.le(6), _yr - 1, _season_fallback)
    _season_fallback = np.where(_sp.isin(["NFL", "NCAAF"]) & _mo.le(3), _yr - 1, _season_fallback)
    _season_safe = games["Season"].fillna(pd.Series(_season_fallback, index=games.index)).replace([np.inf, -np.inf], np.nan)
    games["Season"] = _sys_float64_series(_season_safe.round(), games.index)
    games["Week_Number"] = _sys_num_series(games, "Week_Number", "Week", "Game_Week")

    # Combine all stage descriptors.  Explicit Boolean fields always win; text is
    # only a fallback.  The BigQuery season calendar should populate the exact
    # flags because boundary months (NBA/NCAAB April, WNBA September, etc.) overlap.
    _stage_parts = []
    for _c in ("Season_Type", "Game_Type", "Season_Stage", "Tournament_Type", "Round_Name"):
        if _c in games.columns:
            _stage_parts.append(games[_c].astype("string").fillna(""))
    if _stage_parts:
        stage_text = pd.concat(_stage_parts, axis=1).agg(" ".join, axis=1).str.lower()
    else:
        stage_text = pd.Series("", index=games.index, dtype="string")

    games["Is_Preseason"] = _sys_bool_series(games, "Is_Preseason")
    games["Is_Postseason"] = _sys_bool_series(games, "Is_Postseason", "Is_Playoffs")
    games["Is_Regular_Season"] = _sys_bool_series(games, "Is_Regular_Season")
    games["Is_Finals"] = _sys_bool_series(games, "Is_Finals")
    games["Is_Cup"] = _sys_bool_series(games, "Is_Cup")
    games["Is_PlayIn"] = _sys_bool_series(games, "Is_PlayIn")
    games["Is_Bowl"] = _sys_bool_series(games, "Is_Bowl")
    games["Is_Conference_Tournament"] = _sys_bool_series(games, "Is_Conference_Tournament")
    games["Is_Neutral_Site"] = _sys_bool_series(games, "Is_Neutral_Site")

    games.loc[games["Is_Preseason"].isna(), "Is_Preseason"] = stage_text.str.contains("preseason|exhibition", regex=True, na=False).astype(float)
    games.loc[games["Is_Cup"].isna(), "Is_Cup"] = stage_text.str.contains(r"\bcup\b", regex=True, na=False).astype(float)
    games.loc[games["Is_PlayIn"].isna(), "Is_PlayIn"] = stage_text.str.contains("play[- ]?in", regex=True, na=False).astype(float)
    games.loc[games["Is_Bowl"].isna(), "Is_Bowl"] = stage_text.str.contains(r"\bbowl\b|\bcfp\b", regex=True, na=False).astype(float)
    games.loc[games["Is_Conference_Tournament"].isna(), "Is_Conference_Tournament"] = stage_text.str.contains("conference tournament", regex=False, na=False).astype(float)
    games.loc[games["Is_Finals"].isna(), "Is_Finals"] = stage_text.str.contains(r"\bfinals\b|championship series", regex=True, na=False).astype(float)

    _post_from_text = (
        stage_text.str.contains("playoff|postseason|play[- ]?in|conference tournament", regex=True, na=False)
        | games["Is_Bowl"].fillna(0).eq(1)
    )
    games.loc[games["Is_Postseason"].isna(), "Is_Postseason"] = _post_from_text.astype(float)
    games.loc[games["Is_Regular_Season"].isna(), "Is_Regular_Season"] = (
        (games["Is_Preseason"].fillna(0) == 0) &
        (games["Is_Postseason"].fillna(0) == 0)
    ).astype(float)

    # Conference/division/subdivision can be supplied explicitly or inferred from
    # the team-season reference table exposed through the Big Al context view.
    games["Is_Conference_Game"] = _sys_bool_series(games, "Is_Conference_Game")
    if "Home_Conference" in games.columns and "Away_Conference" in games.columns:
        hc = games["Home_Conference"].astype("string").fillna("").str.lower().str.strip()
        ac = games["Away_Conference"].astype("string").fillna("").str.lower().str.strip()
        inf = hc.ne("") & ac.ne("") & hc.ne("nan") & ac.ne("nan")
        games.loc[games["Is_Conference_Game"].isna() & inf, "Is_Conference_Game"] = hc.eq(ac).astype(float)

    games["Is_Division_Game"] = _sys_bool_series(games, "Is_Division_Game")
    if "Home_Division" in games.columns and "Away_Division" in games.columns:
        hd = games["Home_Division"].astype("string").fillna("").str.lower().str.strip()
        ad = games["Away_Division"].astype("string").fillna("").str.lower().str.strip()
        infd = hd.ne("") & ad.ne("") & hd.ne("nan") & ad.ne("nan")
        games.loc[games["Is_Division_Game"].isna() & infd, "Is_Division_Game"] = hd.eq(ad).astype(float)

    if "Home_Subdivision" in games.columns and "Away_Subdivision" in games.columns:
        hs = games["Home_Subdivision"].astype("string").fillna("").str.lower().str.strip()
        ass = games["Away_Subdivision"].astype("string").fillna("").str.lower().str.strip()
        _sub_known = hs.ne("") & ass.ne("") & hs.ne("nan") & ass.ne("nan") & hs.ne("<na>") & ass.ne("<na>")
        games["Same_Subdivision"] = np.where(
            _sub_known,
            hs.eq(ass).astype(float),
            np.nan,
        )
    else:
        games["Same_Subdivision"] = np.nan
        _sub_known = pd.Series(False, index=games.index)

    if "Home_League_Group" in games.columns and "Away_League_Group" in games.columns:
        hlg = games["Home_League_Group"].astype("string").fillna("").str.lower().str.strip()
        alg = games["Away_League_Group"].astype("string").fillna("").str.lower().str.strip()
        _lg_known = hlg.ne("") & alg.ne("") & hlg.ne("nan") & alg.ne("nan") & hlg.ne("<na>") & alg.ne("<na>")
        games["Same_League_Group"] = np.where(
            _lg_known,
            hlg.eq(alg).astype(float),
            np.nan,
        )
    else:
        games["Same_League_Group"] = np.nan
        _lg_known = pd.Series(False, index=games.index)

    # Explicit readiness lets the learned model distinguish "different" from
    # "alignment unavailable" without treating missing metadata as a negative.
    games["Conference_Context_Known"] = pd.to_numeric(
        games.get("Is_Conference_Game"), errors="coerce"
    ).notna().astype("int8")
    games["Division_Context_Known"] = pd.to_numeric(
        games.get("Is_Division_Game"), errors="coerce"
    ).notna().astype("int8")
    games["Subdivision_Context_Known"] = pd.Series(_sub_known, index=games.index).astype("int8")
    games["League_Group_Context_Known"] = pd.Series(_lg_known, index=games.index).astype("int8")

    games["Actual_Game_Total"] = games["__Score_Home"] + games["__Score_Away"]
    games["Pair_Key"] = games.apply(
        lambda r: "|".join(sorted([str(r.get("Home_Team_Norm", "")), str(r.get("Away_Team_Norm", ""))])), axis=1
    )
    games = games.sort_values(["Sport", "Season", "Pair_Key", "Game_Start", "Game_Key"])
    # V12.0.4: pandas GroupBy drops NA keys by default.  Rows whose Season
    # cannot be inferred (for example a malformed/upcoming row with no usable
    # Game_Start) therefore receive NaN from cumcount(), and a direct int16
    # cast raises IntCastingNaNError.  Keep the unknown-season group in the
    # operation and still pass the count through the shared NA/inf-safe caster.
    games["Season_H2H_Meeting_Number"] = _sys_int_flag(
        games.groupby(["Sport", "Season", "Pair_Key"], sort=False, dropna=False).cumcount() + 1,
        games.index,
        "int16",
    )
    first_total = games.groupby(
        ["Sport", "Season", "Pair_Key"], sort=False, dropna=False
    )["Actual_Game_Total"].transform("first")
    games["First_Meeting_Actual_Total_Prior"] = np.where(
        games["Season_H2H_Meeting_Number"] >= 2, first_total, np.nan
    )

    # ------------------------------------------------------------------
    # Long team/game scaffold.
    # ------------------------------------------------------------------
    common_cols = [c for c in games.columns if c not in ["Home_Team_Norm", "Away_Team_Norm"]]
    home = games[common_cols + ["Home_Team_Norm", "Away_Team_Norm"]].copy()
    home["Team"] = home["Home_Team_Norm"]
    home["Opponent"] = home["Away_Team_Norm"]
    home["Is_Home"] = 1
    home["Points_For"] = home["__Score_Home"]
    home["Points_Against"] = home["__Score_Away"]

    away = games[common_cols + ["Home_Team_Norm", "Away_Team_Norm"]].copy()
    away["Team"] = away["Away_Team_Norm"]
    away["Opponent"] = away["Home_Team_Norm"]
    away["Is_Home"] = 0
    away["Points_For"] = away["__Score_Away"]
    away["Points_Against"] = away["__Score_Home"]

    tg = pd.concat([home, away], ignore_index=True)
    tg = _sys_normalize_nullable_numeric_frame(tg)
    tg["SU_Margin"] = tg["Points_For"] - tg["Points_Against"]
    tg["SU_Win"] = np.where(tg["SU_Margin"].notna(), (tg["SU_Margin"] > 0).astype(float), np.nan)
    tg["SU_Loss"] = np.where(tg["SU_Margin"].notna(), (tg["SU_Margin"] < 0).astype(float), np.nan)

    # Team-specific optional metadata from home/away fields.
    tg["Team_Is_Defending_Champion"] = np.where(
        tg["Is_Home"].eq(1),
        _sys_bool_series(tg, "Home_Is_Defending_Champion"),
        _sys_bool_series(tg, "Away_Is_Defending_Champion"),
    )
    tg["Opponent_Is_Defending_Champion"] = np.where(
        tg["Is_Home"].eq(1),
        _sys_bool_series(tg, "Away_Is_Defending_Champion"),
        _sys_bool_series(tg, "Home_Is_Defending_Champion"),
    )
    tg["Team_Prior_Season_Playoff"] = np.where(
        tg["Is_Home"].eq(1),
        _sys_bool_series(tg, "Home_Prior_Season_Playoff"),
        _sys_bool_series(tg, "Away_Prior_Season_Playoff"),
    )
    tg["Opponent_Prior_Season_Playoff"] = np.where(
        tg["Is_Home"].eq(1),
        _sys_bool_series(tg, "Away_Prior_Season_Playoff"),
        _sys_bool_series(tg, "Home_Prior_Season_Playoff"),
    )
    tg["Is_Final_Home_Game"] = _sys_bool_series(tg, "Is_Final_Home_Game")
    if "Home_Is_Final_Home_Game" in tg.columns:
        tg.loc[tg["Is_Home"].eq(1), "Is_Final_Home_Game"] = _sys_bool_series(tg, "Home_Is_Final_Home_Game")
    tg["Team_Eliminated_With_Loss"] = np.where(
        tg["Is_Home"].eq(1),
        _sys_bool_series(tg, "Home_Eliminated_With_Loss", "Home_Would_Be_Eliminated_With_Loss"),
        _sys_bool_series(tg, "Away_Eliminated_With_Loss", "Away_Would_Be_Eliminated_With_Loss"),
    )
    tg["Opponent_Eliminated_With_Loss"] = np.where(
        tg["Is_Home"].eq(1),
        _sys_bool_series(tg, "Away_Eliminated_With_Loss", "Away_Would_Be_Eliminated_With_Loss"),
        _sys_bool_series(tg, "Home_Eliminated_With_Loss", "Home_Would_Be_Eliminated_With_Loss"),
    )
    tg["Team_Series_Wins"] = np.where(
        tg["Is_Home"].eq(1), _sys_num_series(tg, "Home_Series_Wins"), _sys_num_series(tg, "Away_Series_Wins")
    )
    tg["Opp_Series_Wins"] = np.where(
        tg["Is_Home"].eq(1), _sys_num_series(tg, "Away_Series_Wins"), _sys_num_series(tg, "Home_Series_Wins")
    )

    # ------------------------------------------------------------------
    # Big Al conference/week context.
    #
    # Public Big Al material repeatedly treats week/game number, home/road,
    # conference/non-conference and division relationships as meaningful
    # situational dimensions.  These are generic, leakage-safe model features;
    # they do NOT claim to reproduce proprietary Big Al formulas.
    # ------------------------------------------------------------------
    _wk = pd.to_numeric(tg.get("Week_Number"), errors="coerce")
    _conf = pd.to_numeric(tg.get("Is_Conference_Game"), errors="coerce")
    _div = pd.to_numeric(tg.get("Is_Division_Game"), errors="coerce")
    _same_sub = pd.to_numeric(tg.get("Same_Subdivision"), errors="coerce")
    _same_lg = pd.to_numeric(tg.get("Same_League_Group"), errors="coerce")
    _home_ctx = pd.to_numeric(tg.get("Is_Home"), errors="coerce")
    _neutral_ctx = pd.to_numeric(tg.get("Is_Neutral_Site"), errors="coerce")

    _week_known = _wk.notna()
    _conf_known = _conf.notna()
    _div_known = _div.notna()
    _sub_known_tg = _same_sub.notna()
    _lg_known_tg = _same_lg.notna()

    tg["BigAl_Context_Week_Number"] = _wk.astype("float32")
    tg["BigAl_Context_Week_Known"] = _week_known.astype("int8")
    tg["BigAl_Context_Week_1"] = (_week_known & _wk.eq(1)).astype("int8")
    tg["BigAl_Context_Week_2"] = (_week_known & _wk.eq(2)).astype("int8")
    tg["BigAl_Context_Week_3_4"] = (_week_known & _wk.between(3, 4)).astype("int8")
    tg["BigAl_Context_Week_5_8"] = (_week_known & _wk.between(5, 8)).astype("int8")
    tg["BigAl_Context_Week_9_Plus"] = (_week_known & _wk.ge(9)).astype("int8")

    tg["BigAl_Context_Conference_Known"] = _conf_known.astype("int8")
    tg["BigAl_Context_Is_Conference_Game"] = (_conf_known & _conf.eq(1)).astype("int8")
    tg["BigAl_Context_Is_NonConference_Game"] = (_conf_known & _conf.eq(0)).astype("int8")
    tg["BigAl_Context_Division_Known"] = _div_known.astype("int8")
    tg["BigAl_Context_Is_Division_Game"] = (_div_known & _div.eq(1)).astype("int8")
    tg["BigAl_Context_Same_Conference_Different_Division"] = (
        _conf_known & _conf.eq(1) & _div_known & _div.eq(0)
    ).astype("int8")

    tg["BigAl_Context_Subdivision_Known"] = _sub_known_tg.astype("int8")
    tg["BigAl_Context_Same_Subdivision"] = (_sub_known_tg & _same_sub.eq(1)).astype("int8")
    tg["BigAl_Context_Cross_Subdivision"] = (_sub_known_tg & _same_sub.eq(0)).astype("int8")

    tg["BigAl_Context_League_Group_Known"] = _lg_known_tg.astype("int8")
    tg["BigAl_Context_Same_League_Group"] = (_lg_known_tg & _same_lg.eq(1)).astype("int8")
    tg["BigAl_Context_Cross_League_Group"] = (_lg_known_tg & _same_lg.eq(0)).astype("int8")

    tg["BigAl_Context_Is_Neutral_Site"] = (
        _neutral_ctx.notna() & _neutral_ctx.eq(1)
    ).astype("int8")
    tg["BigAl_Context_Is_Home"] = (_home_ctx.eq(1)).astype("int8")
    tg["BigAl_Context_Is_Away"] = (_home_ctx.eq(0)).astype("int8")

    # Relationship x location interactions.
    tg["BigAl_Context_Conference_Home"] = (
        _conf_known & _conf.eq(1) & _home_ctx.eq(1)
    ).astype("int8")
    tg["BigAl_Context_Conference_Away"] = (
        _conf_known & _conf.eq(1) & _home_ctx.eq(0)
    ).astype("int8")
    tg["BigAl_Context_NonConference_Home"] = (
        _conf_known & _conf.eq(0) & _home_ctx.eq(1)
    ).astype("int8")
    tg["BigAl_Context_NonConference_Away"] = (
        _conf_known & _conf.eq(0) & _home_ctx.eq(0)
    ).astype("int8")
    tg["BigAl_Context_Division_Home"] = (
        _div_known & _div.eq(1) & _home_ctx.eq(1)
    ).astype("int8")
    tg["BigAl_Context_Division_Away"] = (
        _div_known & _div.eq(1) & _home_ctx.eq(0)
    ).astype("int8")

    # Week x relationship/location interactions.  Week 1/2 are explicit because
    # Big Al's public football systems frequently isolate those schedule spots.
    _w1 = _week_known & _wk.eq(1)
    _w2 = _week_known & _wk.eq(2)
    _early = _week_known & _wk.between(1, 4)

    tg["BigAl_Context_Week1_Home"] = (_w1 & _home_ctx.eq(1)).astype("int8")
    tg["BigAl_Context_Week2_Home"] = (_w2 & _home_ctx.eq(1)).astype("int8")
    tg["BigAl_Context_Week1_Conference"] = (_w1 & _conf_known & _conf.eq(1)).astype("int8")
    tg["BigAl_Context_Week2_Conference"] = (_w2 & _conf_known & _conf.eq(1)).astype("int8")
    tg["BigAl_Context_Week1_NonConference"] = (_w1 & _conf_known & _conf.eq(0)).astype("int8")
    tg["BigAl_Context_Week2_NonConference"] = (_w2 & _conf_known & _conf.eq(0)).astype("int8")
    tg["BigAl_Context_Week2_NonConference_Home"] = (
        _w2 & _conf_known & _conf.eq(0) & _home_ctx.eq(1)
    ).astype("int8")
    tg["BigAl_Context_Early_Conference"] = (_early & _conf_known & _conf.eq(1)).astype("int8")
    tg["BigAl_Context_Early_NonConference"] = (_early & _conf_known & _conf.eq(0)).astype("int8")

    # ------------------------------------------------------------------
    # Attach current/opening market roles.
    # ------------------------------------------------------------------
    h2h = _sys_pick_market_rows(d, "h2h")
    if not h2h.empty:
        h2h["Team"] = h2h["Outcome_Team"]
        h2h["ML_Odds"] = _sys_num_series(h2h, "Odds_Price")
        h2h["Opening_ML_Odds"] = _sys_num_series(h2h, "First_Odds", "First_Odds_Price", "Open_Odds", "Old_Odds")
        h2h["ML_Imp_Prob"] = _sys_amer_prob(h2h["ML_Odds"])
        h2h["Opening_ML_Imp_Prob"] = _sys_amer_prob(h2h["Opening_ML_Odds"])
        denom = h2h.groupby("Game_Key")["ML_Imp_Prob"].transform("sum")
        denom0 = h2h.groupby("Game_Key")["Opening_ML_Imp_Prob"].transform("sum")
        h2h["ML_Fair_Prob"] = h2h["ML_Imp_Prob"] / denom.replace(0, np.nan)
        h2h["Opening_ML_Fair_Prob"] = h2h["Opening_ML_Imp_Prob"] / denom0.replace(0, np.nan)
        h2h["Is_ML_Dog"] = np.where(
            h2h["ML_Fair_Prob"].notna(),
            (h2h["ML_Fair_Prob"] < 0.5).astype(float),
            np.where(h2h["ML_Odds"].notna(), (h2h["ML_Odds"] > 0).astype(float), np.nan),
        )
        h2h["Is_ML_Favorite"] = np.where(
            h2h["ML_Fair_Prob"].notna(),
            (h2h["ML_Fair_Prob"] > 0.5).astype(float),
            np.where(h2h["ML_Odds"].notna(), (h2h["ML_Odds"] < 0).astype(float), np.nan),
        )
        h2h["Opening_Is_ML_Dog"] = np.where(
            h2h["Opening_ML_Fair_Prob"].notna(),
            (h2h["Opening_ML_Fair_Prob"] < 0.5).astype(float),
            np.where(h2h["Opening_ML_Odds"].notna(), (h2h["Opening_ML_Odds"] > 0).astype(float), np.nan),
        )
        h2h_cols = [
            "Game_Key", "Team", "ML_Odds", "Opening_ML_Odds", "ML_Fair_Prob",
            "Opening_ML_Fair_Prob", "Is_ML_Dog", "Is_ML_Favorite", "Opening_Is_ML_Dog"
        ]
        tg = tg.merge(h2h[h2h_cols], on=["Game_Key", "Team"], how="left", validate="1:1")
    else:
        for c in ["ML_Odds", "Opening_ML_Odds", "ML_Fair_Prob", "Opening_ML_Fair_Prob", "Is_ML_Dog", "Is_ML_Favorite", "Opening_Is_ML_Dog"]:
            tg[c] = np.nan

    spr = _sys_pick_market_rows(d, "spreads")
    if not spr.empty:
        spr["Team"] = spr["Outcome_Team"]
        spr["Spread_Value"] = _sys_num_series(spr, "Value")
        spr["Opening_Spread"] = _sys_num_series(spr, "First_Line_Value", "Opening_Line", "Open_Value")
        spr["Spread_Odds"] = _sys_num_series(spr, "Odds_Price")
        spr["ATS_Hit_Raw"] = _sys_num_series(spr, "SHARP_HIT_BOOL")
        spr["ATS_Cover_Margin"] = _sys_num_series(spr, "ATS_Cover_Margin")
        spr_cols = ["Game_Key", "Team", "Spread_Value", "Opening_Spread", "Spread_Odds", "ATS_Hit_Raw", "ATS_Cover_Margin"]
        tg = tg.merge(spr[spr_cols], on=["Game_Key", "Team"], how="left", validate="1:1")
    else:
        for c in ["Spread_Value", "Opening_Spread", "Spread_Odds", "ATS_Hit_Raw", "ATS_Cover_Margin"]:
            tg[c] = np.nan


    # Big Al relationship x current spread role.  PickDawgz/BigAl public titles
    # repeatedly segment plays by conference/division and favorite/underdog role.
    # Keep the ingredients explicit and let the model learn weights.
    _ctx_spread = pd.to_numeric(tg.get("Spread_Value"), errors="coerce")
    _ctx_dog = _ctx_spread.gt(0)
    _ctx_fav = _ctx_spread.lt(0)
    _ctx_pick = _ctx_spread.eq(0)
    _ctx_conf = pd.to_numeric(tg.get("Is_Conference_Game"), errors="coerce")
    _ctx_div = pd.to_numeric(tg.get("Is_Division_Game"), errors="coerce")
    _ctx_home = pd.to_numeric(tg.get("Is_Home"), errors="coerce")

    tg["BigAl_Context_Conference_Dog"] = (
        _ctx_conf.eq(1) & _ctx_dog
    ).astype("int8")
    tg["BigAl_Context_Conference_Favorite"] = (
        _ctx_conf.eq(1) & _ctx_fav
    ).astype("int8")
    tg["BigAl_Context_Conference_Pickem"] = (
        _ctx_conf.eq(1) & _ctx_pick
    ).astype("int8")
    tg["BigAl_Context_Conference_Home_Dog"] = (
        _ctx_conf.eq(1) & _ctx_home.eq(1) & _ctx_dog
    ).astype("int8")
    tg["BigAl_Context_Conference_Home_Favorite"] = (
        _ctx_conf.eq(1) & _ctx_home.eq(1) & _ctx_fav
    ).astype("int8")

    tg["BigAl_Context_Division_Dog"] = (
        _ctx_div.eq(1) & _ctx_dog
    ).astype("int8")
    tg["BigAl_Context_Division_Favorite"] = (
        _ctx_div.eq(1) & _ctx_fav
    ).astype("int8")
    tg["BigAl_Context_Division_Home_Dog"] = (
        _ctx_div.eq(1) & _ctx_home.eq(1) & _ctx_dog
    ).astype("int8")
    tg["BigAl_Context_Division_Home_Favorite"] = (
        _ctx_div.eq(1) & _ctx_home.eq(1) & _ctx_fav
    ).astype("int8")

    tg["BigAl_Context_NonConference_Dog"] = (
        _ctx_conf.eq(0) & _ctx_dog
    ).astype("int8")
    tg["BigAl_Context_NonConference_Favorite"] = (
        _ctx_conf.eq(0) & _ctx_fav
    ).astype("int8")

    # If ATS cover margin was not stored, calculate team score margin + spread.
    calc_ats_margin = tg["SU_Margin"] + tg["Spread_Value"]
    tg["ATS_Cover_Margin"] = pd.to_numeric(tg["ATS_Cover_Margin"], errors="coerce").where(lambda s: s.notna(), calc_ats_margin)
    tg["ATS_Win"] = np.where(
        tg["ATS_Hit_Raw"].notna(),
        (tg["ATS_Hit_Raw"] > 0.5).astype(float),
        np.where(tg["ATS_Cover_Margin"].notna(), (tg["ATS_Cover_Margin"] > 0).astype(float), np.nan),
    )
    tg["ATS_Loss"] = np.where(
        tg["ATS_Cover_Margin"].notna(), (tg["ATS_Cover_Margin"] < 0).astype(float),
        np.where(tg["ATS_Win"].notna(), (tg["ATS_Win"] < 0.5).astype(float), np.nan),
    )

    tot = _sys_pick_market_rows(d, "totals")
    if not tot.empty:
        over = tot[tot["Outcome_Norm"].eq("over")].copy()
        if over.empty:
            over = tot.sort_values("Game_Key").drop_duplicates("Game_Key", keep="first")
        over["Current_Total"] = _sys_num_series(over, "Value")
        over["Opening_Total"] = _sys_num_series(over, "First_Line_Value", "Opening_Line", "Open_Value")
        tot_map = over[["Game_Key", "Current_Total", "Opening_Total"]].drop_duplicates("Game_Key")
        tg = tg.merge(tot_map, on="Game_Key", how="left", validate="many_to_one")
    else:
        tg["Current_Total"] = np.nan
        tg["Opening_Total"] = np.nan

    # Carry current revenge flag if it exists at team/outcome grain.
    if "Revenge_Flag" in d.columns:
        side = d[d["Market"].isin(["h2h", "spreads"])].copy()
        side["Team"] = side["Outcome_Team"]
        side["Revenge_Flag_Current"] = _sys_num_series(side, "Revenge_Flag")
        side = side.sort_values("Snapshot_Timestamp" if "Snapshot_Timestamp" in side.columns else "Game_Start").drop_duplicates(["Game_Key", "Team"], keep="last")
        tg = tg.merge(side[["Game_Key", "Team", "Revenge_Flag_Current"]], on=["Game_Key", "Team"], how="left", validate="1:1")
    else:
        tg["Revenge_Flag_Current"] = np.nan

    # ------------------------------------------------------------------
    # Prior-only chronological state.
    # ------------------------------------------------------------------
    tg = tg.sort_values(["Sport", "Season", "Team", "Game_Start", "Game_Key"]).reset_index(drop=True)
    grp = ["Sport", "Season", "Team"]
    tg["Team_Game_Number"] = _sys_int_flag(
        tg.groupby(grp, sort=False, dropna=False).cumcount() + 1, tg.index, "int16"
    )

    # MMI-only schedule-position state. These fields are strictly prior-only and
    # are explicitly blocked from Core. They let the research engine test Big Al-
    # style filters such as first road game / first home game without reconstructing
    # season chronology from repeated market snapshots.
    _mmi_home_now = pd.to_numeric(tg.get("Is_Home"), errors="coerce").fillna(-1)
    _mmi_home_flag = _mmi_home_now.eq(1).astype("int16")
    _mmi_road_flag = _mmi_home_now.eq(0).astype("int16")
    _mmi_prior_home = (
        _mmi_home_flag.groupby([tg[c] for c in grp], sort=False, dropna=False).cumsum() - _mmi_home_flag
    )
    _mmi_prior_road = (
        _mmi_road_flag.groupby([tg[c] for c in grp], sort=False, dropna=False).cumsum() - _mmi_road_flag
    )
    tg["MMI_Prior_Home_Games_System"] = _mmi_prior_home.astype("int16")
    tg["MMI_Prior_Road_Games_System"] = _mmi_prior_road.astype("int16")
    tg["MMI_First_Home_Game_System"] = (_mmi_home_flag.eq(1) & _mmi_prior_home.eq(0)).astype("int8")
    tg["MMI_First_Road_Game_System"] = (_mmi_road_flag.eq(1) & _mmi_prior_road.eq(0)).astype("int8")

    # Team game number is more robust than calendar week when byes exist.  The
    # public Big Al NCAA Week-2 example is explicitly a team's second game.
    _tgn = pd.to_numeric(tg.get("Team_Game_Number"), errors="coerce")
    _wk_ctx = pd.to_numeric(tg.get("Week_Number"), errors="coerce")
    _conf_ctx = pd.to_numeric(tg.get("Is_Conference_Game"), errors="coerce")
    _home_ctx2 = pd.to_numeric(tg.get("Is_Home"), errors="coerce")

    tg["BigAl_Context_Team_Game_Number"] = _tgn.astype("float32")
    tg["BigAl_Context_Team_Game_1"] = _tgn.eq(1).astype("int8")
    tg["BigAl_Context_Team_Game_2"] = _tgn.eq(2).astype("int8")
    tg["BigAl_Context_Team_Game_3_4"] = _tgn.between(3, 4).astype("int8")
    tg["BigAl_Context_Team_Game_5_Plus"] = _tgn.ge(5).astype("int8")

    _week_game_gap = _wk_ctx - _tgn
    tg["BigAl_Context_Week_Game_Gap"] = _week_game_gap.astype("float32")
    tg["BigAl_Context_Had_Bye_Proxy"] = (
        _week_game_gap.notna() & _week_game_gap.ge(1)
    ).astype("int8")

    tg["BigAl_Context_Game2_NonConference_Home"] = (
        _tgn.eq(2) & _conf_ctx.eq(0) & _home_ctx2.eq(1)
    ).astype("int8")
    tg["BigAl_Context_Game2_Conference_Home"] = (
        _tgn.eq(2) & _conf_ctx.eq(1) & _home_ctx2.eq(1)
    ).astype("int8")

    prior_n = tg.groupby(grp, sort=False, dropna=False).cumcount().astype(float)
    prior_wins = tg["SU_Win"].fillna(0).groupby([tg[c] for c in grp], sort=False, dropna=False).cumsum() - tg["SU_Win"].fillna(0)
    tg["WinPct_Prior_System"] = prior_wins / prior_n.replace(0, np.nan)

    # MMI-only generic ATS record entering the game. Unlike role-specific Pathi
    # rates, this is an all-spread prior record and is used only by research rules.
    _mmi_ats = pd.to_numeric(tg.get("ATS_Win"), errors="coerce")
    _mmi_ats_played = _mmi_ats.notna().astype(float)
    _mmi_ats_wins = _mmi_ats.fillna(0.0)
    _mmi_prior_ats_n = (
        _mmi_ats_played.groupby([tg[c] for c in grp], sort=False, dropna=False).cumsum() - _mmi_ats_played
    )
    _mmi_prior_ats_w = (
        _mmi_ats_wins.groupby([tg[c] for c in grp], sort=False, dropna=False).cumsum() - _mmi_ats_wins
    )
    tg["MMI_ATS_WinPct_Prior_System"] = (_mmi_prior_ats_w / _mmi_prior_ats_n.replace(0, np.nan)).astype("float32")
    tg["MMI_ATS_Games_Prior_System"] = _mmi_prior_ats_n.astype("float32")

    # Big Al ALL Access research (DB-only proxy):
    # In the 6/23/25 Arizona/Chicago ALL Access discussion, Big Al emphasized
    # recent form improving materially versus full-season form.  The public
    # discussion used pitcher metrics that are not in this database, so we do
    # NOT recreate those metrics.  Instead, expose the same *concept* at the
    # team level using strictly prior SU results already stored in our scores.
    # This is an ENHANCER/proxy, never labeled as an exact Big Al system.
    _su_numeric = pd.to_numeric(tg["SU_Win"], errors="coerce")
    _recent5_su = (
        _su_numeric.groupby([tg[c] for c in grp], sort=False, dropna=False)
        .transform(lambda x: x.shift(1).rolling(5, min_periods=3).mean())
    )
    _is_mlb_state = tg["Sport"].astype(str).str.upper().eq("MLB")
    _season_prior = pd.to_numeric(tg["WinPct_Prior_System"], errors="coerce")
    _recent_delta = _recent5_su - _season_prior

    tg["BigAl_MLB_Recent5_SU_WinPct_Prior"] = _recent5_su.where(_is_mlb_state).astype("float32")
    tg["BigAl_MLB_Recent_vs_Season_WinPct_Delta"] = _recent_delta.where(_is_mlb_state).astype("float32")

    tg["Days_Since_Last_Game_System"] = (
        tg.groupby(grp, sort=False, dropna=False)["Game_Start"].diff().dt.total_seconds().div(86400.0)
    )

    # Canonical leakage-safe schedule-density state at physical team-game grain.
    # This belongs here (rather than market/book grain) so every team row has a
    # true opponent-comparable schedule state. Counts include PRIOR games only.
    for _sched_days in (2, 4, 7):
        _sched_col = f"Games_Last_{_sched_days}_Days_System"
        _sched_counts = np.zeros(len(tg), dtype=np.int16)
        for _, _idx_arr in tg.groupby(grp, sort=False, dropna=False).indices.items():
            _idx_arr = np.asarray(_idx_arr, dtype=np.int64)
            _times = pd.to_datetime(tg.loc[_idx_arr, "Game_Start"], errors="coerce", utc=True)
            _t_ns = _times.astype("int64").to_numpy()
            _valid = _times.notna().to_numpy()
            if not _valid.any():
                continue
            # Group is already chronological. Invalid timestamps remain zero.
            _cut = _t_ns - np.int64(_sched_days) * np.int64(86400 * 1_000_000_000)
            _left = np.searchsorted(_t_ns, _cut, side="left")
            _pos = np.arange(len(_idx_arr), dtype=np.int64)
            _cnt = (_pos - _left).astype(np.int16)
            _cnt[~_valid] = 0
            _sched_counts[_idx_arr] = _cnt
        tg[_sched_col] = _sched_counts.astype("int16")

    tg["Is_B2B_System"] = (
        pd.to_numeric(tg["Days_Since_Last_Game_System"], errors="coerce").le(1.0)
        & pd.to_numeric(tg["Days_Since_Last_Game_System"], errors="coerce").notna()
    ).astype("int8")
    tg["Is_3in4_System"] = (
        pd.to_numeric(tg["Games_Last_4_Days_System"], errors="coerce").ge(2)
    ).astype("int8")

    # Canonical RECENT bye/extra-rest state.  The older BigAl_Context_Had_Bye_Proxy
    # is cumulative after a missed scheduled week (Week_Number - Team_Game_Number)
    # and therefore is useful as broad historical context but is not a valid
    # "coming off a bye" vote.  This field is one-game-local and prior-only.
    _week_gap_now = (
        pd.to_numeric(tg.get("Week_Number"), errors="coerce")
        - pd.to_numeric(tg.get("Team_Game_Number"), errors="coerce")
    )
    _week_gap_prev = _week_gap_now.groupby([tg[c] for c in grp], sort=False, dropna=False).shift(1)
    _days_rest_sched = pd.to_numeric(tg["Days_Since_Last_Game_System"], errors="coerce")
    _football_sched = tg["Sport"].astype(str).str.upper().isin(["NFL", "NCAAF", "CFL"])
    tg["Had_Bye_Last_Game_System"] = (
        _football_sched
        & (
            (_week_gap_now.notna() & _week_gap_prev.notna() & _week_gap_now.gt(_week_gap_prev))
            | _days_rest_sched.ge(10.0)
        )
    ).astype("int8")

    # Exact consecutive streaks, not rolling counts.
    tg["SU_Win_Streak_Prior"] = _sys_consecutive_prior(tg, "SU_Win", grp)
    tg["SU_Loss_Streak_Prior"] = _sys_consecutive_prior(tg, "SU_Loss", grp)
    tg["ATS_Win_Streak_Prior"] = _sys_consecutive_prior(tg, "ATS_Win", grp)
    tg["ATS_Loss_Streak_Prior"] = _sys_consecutive_prior(tg, "ATS_Loss", grp)

    # Big Al CBB streak-fade needs the winning streak that existed ENTERING
    # the team's previous game.  This remains strictly prior-only.
    tg["SU_Win_Streak_Entering_Previous_Game"] = (
        tg.groupby(grp, sort=False, dropna=False)["SU_Win_Streak_Prior"].shift(1)
    )

    # Pathi football role/trend state. These are prior-only and leakage-safe.
    _sv = pd.to_numeric(tg.get("Spread_Value"), errors="coerce")
    tg["__fb_spread_dog"] = np.where(_sv.notna(), (_sv > 0).astype(float), np.nan)
    tg["__fb_spread_fav"] = np.where(_sv.notna(), (_sv < 0).astype(float), np.nan)

    def _prior_cond_rate(mask: pd.Series, window: int | None = None) -> pd.Series:
        tmp = pd.to_numeric(tg["ATS_Win"], errors="coerce").where(mask)
        if window is None:
            return tmp.groupby([tg[c] for c in grp], sort=False, dropna=False).transform(
                lambda s: s.shift(1).expanding(min_periods=1).mean()
            )
        return tmp.groupby([tg[c] for c in grp], sort=False, dropna=False).transform(
            lambda s: s.shift(1).rolling(window, min_periods=1).mean()
        )

    _dog = pd.Series(tg["__fb_spread_dog"], index=tg.index).eq(1)
    _fav = pd.Series(tg["__fb_spread_fav"], index=tg.index).eq(1)
    _home = pd.to_numeric(tg["Is_Home"], errors="coerce").eq(1)
    _road = pd.to_numeric(tg["Is_Home"], errors="coerce").eq(0)

    tg["Pathi_FB_Team_ATS_As_Dog"] = _prior_cond_rate(_dog)
    tg["Pathi_FB_Team_ATS_As_Favorite"] = _prior_cond_rate(_fav)
    tg["Pathi_FB_Team_ATS_Home_Dog"] = _prior_cond_rate(_dog & _home)
    tg["Pathi_FB_Team_ATS_Road_Dog"] = _prior_cond_rate(_dog & _road)
    tg["Pathi_FB_Team_ATS_Home_Favorite"] = _prior_cond_rate(_fav & _home)
    tg["Pathi_FB_Team_ATS_Road_Favorite"] = _prior_cond_rate(_fav & _road)

    _dog5, _fav5 = _prior_cond_rate(_dog, 5), _prior_cond_rate(_fav, 5)
    _dog10, _fav10 = _prior_cond_rate(_dog, 10), _prior_cond_rate(_fav, 10)
    tg["Pathi_FB_Team_Role_ATS_Last5"] = np.where(_dog, _dog5, np.where(_fav, _fav5, np.nan))
    tg["Pathi_FB_Team_Role_ATS_Last10"] = np.where(_dog, _dog10, np.where(_fav, _fav10, np.nan))
    tg["Pathi_FB_Team_Role_ATS_Season"] = np.where(
        _dog, tg["Pathi_FB_Team_ATS_As_Dog"],
        np.where(_fav, tg["Pathi_FB_Team_ATS_As_Favorite"], np.nan)
    )
    tg["Pathi_FB_RoleTrend_DataReady"] = (
        tg["Sport"].astype(str).str.upper().isin(["NFL", "NCAAF"]) &
        _sv.notna() & pd.to_numeric(tg["Pathi_FB_Team_Role_ATS_Season"], errors="coerce").notna()
    ).astype("int8")

    # Previous-game fields.
    prev_base = [
        "Opponent", "SU_Win", "SU_Loss", "SU_Margin", "Points_For", "Points_Against",
        "ATS_Win", "ATS_Loss", "ATS_Cover_Margin", "ML_Odds", "Is_ML_Dog", "Is_ML_Favorite",
        "Spread_Value", "Is_Home", "Opponent_Is_Defending_Champion",
    ]
    for lag in (1, 2, 3):
        for col in prev_base:
            if col in tg.columns:
                name = f"Prev{'' if lag == 1 else lag}_{col}"
                tg[name] = tg.groupby(grp, sort=False, dropna=False)[col].shift(lag)

    tg["Prev_Is_Road_Favorite"] = (
        (pd.to_numeric(tg.get("Prev_Is_Home"), errors="coerce") == 0) &
        (pd.to_numeric(tg.get("Prev_Is_ML_Favorite"), errors="coerce") == 1)
    ).astype("int8")
    tg["Prev_Is_Road_Dog_9Plus"] = (
        (pd.to_numeric(tg.get("Prev_Is_Home"), errors="coerce") == 0) &
        (pd.to_numeric(tg.get("Prev_Spread_Value"), errors="coerce") >= 9.0)
    ).astype("int8")

    # Rolling / expanding profile statistics prior to current game.
    def _prior_roll_mean(col, window):
        return tg.groupby(grp, sort=False, dropna=False)[col].transform(
            lambda s: pd.to_numeric(s, errors="coerce").shift(1).rolling(window, min_periods=1).mean()
        )

    tg["Dog_Rate_Last10_Prior"] = _prior_roll_mean("Is_ML_Dog", 10)
    _dog_rate = pd.to_numeric(tg["Dog_Rate_Last10_Prior"], errors="coerce")
    _cur_spread = pd.to_numeric(tg.get("Spread_Value"), errors="coerce")
    # "Usually" threshold is our engineering definition (70% of last 10 roles), not a Pathi quote.
    tg["Pathi_FB_Usually_Dog_Now_Favorite"] = ((_dog_rate >= 0.70) & (_cur_spread < 0)).astype("int8")
    tg["Pathi_FB_Usually_Favorite_Now_Dog"] = ((_dog_rate <= 0.30) & (_cur_spread > 0)).astype("int8")
    tg["Pathi_FB_Dog_Rate_Last10_Prior"] = _dog_rate.astype("float32")
    tg["Avg_Points_For_Prior"] = tg.groupby(grp, sort=False, dropna=False)["Points_For"].transform(
        lambda s: pd.to_numeric(s, errors="coerce").shift(1).expanding(min_periods=1).mean()
    )

    # Road-favorite unit ROI prior (one unit risked per qualifying game).
    odds = pd.to_numeric(tg["ML_Odds"], errors="coerce")
    payout = np.where(odds > 0, odds / 100.0, np.where(odds < 0, 100.0 / np.abs(odds), np.nan))
    rf = (tg["Is_Home"].eq(0) & pd.to_numeric(tg["Is_ML_Favorite"], errors="coerce").eq(1))
    unit_profit = np.where(tg["SU_Win"].eq(1), payout, np.where(tg["SU_Loss"].eq(1), -1.0, np.nan))
    tg["__rf_game"] = rf.astype(float)
    tg["__rf_profit"] = np.where(rf, unit_profit, 0.0)
    rf_games_cum = tg["__rf_game"].groupby([tg[c] for c in grp], sort=False, dropna=False).cumsum() - tg["__rf_game"]
    rf_profit_cum = tg["__rf_profit"].groupby([tg[c] for c in grp], sort=False, dropna=False).cumsum() - tg["__rf_profit"]
    tg["Road_Favorite_ROI_Prior"] = rf_profit_cum / rf_games_cum.replace(0, np.nan)
    tg.drop(columns=["__rf_game", "__rf_profit"], inplace=True, errors="ignore")


    # Additional Pathi/Big Al model state: price normalization, role ROI, revenge depth, ATS extremes.
    mlp = _sys_amer_prob(pd.to_numeric(tg.get("ML_Odds"), errors="coerce"))
    tg["__ml_imp_prob_hist"] = mlp
    def _prior_roll(col, window, stat="mean"):
        def fn(s):
            x=pd.to_numeric(s, errors="coerce").shift(1).rolling(window, min_periods=1)
            return getattr(x, stat)()
        return tg.groupby(grp, sort=False, dropna=False)[col].transform(fn)
    tg["Current_ImpliedProb_vs_Last10_Avg"] = mlp - _prior_roll("__ml_imp_prob_hist",10,"mean")
    tg["Current_ImpliedProb_vs_Last10_Median"] = mlp - _prior_roll("__ml_imp_prob_hist",10,"median")
    tg["Role_Price_Shift"] = tg["Current_ImpliedProb_vs_Last10_Avg"]
    _mu = _prior_roll("__ml_imp_prob_hist",10,"mean"); _sd = _prior_roll("__ml_imp_prob_hist",10,"std")
    tg["ML_Price_ZScore_vs_TeamHistory"] = (mlp-_mu)/_sd.replace(0,np.nan)

    # One-unit moneyline ROI, always prior-only.
    _od = pd.to_numeric(tg.get("ML_Odds"), errors="coerce")
    _pay = np.where(_od>0,_od/100.0,np.where(_od<0,100.0/np.abs(_od),np.nan))
    _profit = pd.Series(np.where(tg["SU_Win"].eq(1),_pay,np.where(tg["SU_Loss"].eq(1),-1.0,np.nan)), index=tg.index)
    tg["__ml_profit"]=_profit
    def _prior_roi(mask, window=None):
        p=tg["__ml_profit"].where(mask); played=p.notna().astype(float)
        if window is None:
            ps=p.fillna(0).groupby([tg[c] for c in grp],sort=False,dropna=False).cumsum()-p.fillna(0)
            ns=played.groupby([tg[c] for c in grp],sort=False,dropna=False).cumsum()-played
        else:
            ps=p.fillna(0).groupby([tg[c] for c in grp],sort=False,dropna=False).transform(lambda s:s.shift(1).rolling(window,min_periods=1).sum())
            ns=played.groupby([tg[c] for c in grp],sort=False,dropna=False).transform(lambda s:s.shift(1).rolling(window,min_periods=1).sum())
        return ps/ns.replace(0,np.nan)
    _all=pd.Series(True,index=tg.index); _favml=pd.to_numeric(tg.get("Is_ML_Favorite"),errors="coerce").eq(1); _dogml=pd.to_numeric(tg.get("Is_ML_Dog"),errors="coerce").eq(1)
    tg["Team_ML_ROI_Season"]=_prior_roi(_all)
    tg["Team_Fav_ROI_Season"]=_prior_roi(_favml)
    tg["Team_Dog_ROI_Season"]=_prior_roi(_dogml)
    tg["Team_Fav_ROI_Last10"]=_prior_roi(_favml,10)
    tg["Team_Dog_ROI_Last10"]=_prior_roi(_dogml,10)
    tg.drop(columns=["__ml_profit","__ml_imp_prob_hist"],inplace=True,errors="ignore")

    # H2H streak/depth state before current meeting.
    pair_grp=["Sport","Team","Opponent"]
    tg["H2H_Consecutive_Wins_Prior"]=_sys_consecutive_prior(tg,"SU_Win",pair_grp)
    tg["H2H_Consecutive_Losses_Prior"]=_sys_consecutive_prior(tg,"SU_Loss",pair_grp)
    tg["Revenge_Depth"]=tg["H2H_Consecutive_Losses_Prior"]

    # Same-season H2H state for published Big Al rematch/revenge systems.
    # Every field is shifted/prior-only, so no current-game result can leak.
    season_pair_grp=["Sport","Season","Team","Opponent"]
    tg["Season_H2H_Consecutive_Losses_Prior"]=_sys_consecutive_prior(tg,"SU_Loss",season_pair_grp)
    tg["Season_H2H_Last_SU_Win_Prior"] = tg.groupby(season_pair_grp, sort=False, dropna=False)["SU_Win"].shift(1)
    tg["Season_H2H_Last_SU_Margin_Prior"] = tg.groupby(season_pair_grp, sort=False, dropna=False)["SU_Margin"].shift(1)
    tg["Season_H2H_Last_Points_Against_Prior"] = tg.groupby(season_pair_grp, sort=False, dropna=False)["Points_Against"].shift(1)
    tg["Season_H2H_Last_Spread_Prior"] = tg.groupby(season_pair_grp, sort=False, dropna=False)["Spread_Value"].shift(1)
    tg["Season_H2H_Last_Is_Home_Prior"] = tg.groupby(season_pair_grp, sort=False, dropna=False)["Is_Home"].shift(1)
    tg["Season_H2H_Days_Since_Last_Matchup_Prior"] = (
        tg.groupby(season_pair_grp, sort=False, dropna=False)["Game_Start"].diff().dt.total_seconds().div(86400.0)
    )
    def _prior_last_loss_margin(s):
        vals=[]; last=np.nan
        for x in pd.to_numeric(s,errors="coerce"):
            vals.append(last)
            if pd.notna(x) and x<0: last=float(x)
        return pd.Series(vals,index=s.index)
    tg["H2H_Last_Loss_Margin"] = tg.groupby(pair_grp,sort=False,group_keys=False)["SU_Margin"].apply(_prior_last_loss_margin).reindex(tg.index)
    def _meetings_since_win(s):
        out=[]; n=np.nan
        for x in pd.to_numeric(s,errors="coerce"):
            out.append(n)
            if pd.isna(x): continue
            if x>=0.5: n=0.0
            elif pd.notna(n): n+=1.0
        return pd.Series(out,index=s.index)
    tg["H2H_Meetings_Since_Last_Win"] = tg.groupby(pair_grp,sort=False,group_keys=False)["SU_Win"].apply(_meetings_since_win).reindex(tg.index)

    # Explicit ATS aliases + compact last-three summary.
    tg["Prev_ATS_Margin"] = pd.to_numeric(tg.get("Prev_ATS_Cover_Margin"),errors="coerce")
    tg["Prev2_ATS_Margin"] = pd.to_numeric(tg.get("Prev2_ATS_Cover_Margin"),errors="coerce")
    tg["Prev3_ATS_Margin"] = pd.to_numeric(tg.get("Prev3_ATS_Cover_Margin"),errors="coerce")
    _ats3=pd.concat([tg["Prev_ATS_Margin"],tg["Prev2_ATS_Margin"],tg["Prev3_ATS_Margin"]],axis=1)
    tg["ATS_Margin_Max_Last3"]=_ats3.max(axis=1,skipna=True)
    tg["ATS_Margin_Min_Last3"]=_ats3.min(axis=1,skipna=True)
    tg["ATS_Margin_Mean_Last3"]=_ats3.mean(axis=1,skipna=True)

    # Immediate rematch and pair-level prior state.
    tg["Immediate_Rematch_Flag"] = (tg["Prev_Opponent"].astype(str) == tg["Opponent"].astype(str)).astype("int8")
    pair_grp = ["Sport", "Team", "Opponent"]
    tg["Days_Since_Last_Matchup_System"] = (
        tg.groupby(pair_grp, sort=False)["Game_Start"].diff().dt.total_seconds().div(86400.0)
    )
    tg["Last_Matchup_SU_Win_System"] = tg.groupby(pair_grp, sort=False)["SU_Win"].shift(1)
    tg["Last_Matchup_SU_Margin_System"] = tg.groupby(pair_grp, sort=False)["SU_Margin"].shift(1)
    tg["Last_Matchup_Season_System"] = tg.groupby(pair_grp, sort=False)["Season"].shift(1)
    tg["MMI_Last_Matchup_Is_Home_System"] = tg.groupby(pair_grp, sort=False)["Is_Home"].shift(1)
    tg["MMI_Last_Matchup_Points_For_System"] = tg.groupby(pair_grp, sort=False)["Points_For"].shift(1)

    # If the source does not explicitly provide a revenge flag, infer the common
    # historical meaning: the team lost its previous meeting with this opponent.
    _last_h2h_win = pd.to_numeric(tg.get("Last_Matchup_SU_Win_System"), errors="coerce")
    _rev = pd.to_numeric(tg.get("Revenge_Flag_Current"), errors="coerce")
    _rev_infer = np.where(
        _last_h2h_win.notna(),
        (_last_h2h_win < 0.5).astype(float),
        np.nan,
    )
    tg["Revenge_Flag_Current"] = _rev.combine_first(pd.Series(_rev_infer, index=tg.index, dtype="float64"))

    # CF1-specific revenge horizon.  Big Al's published 2025 CF1 card includes
    # Louisville/JMU, Florida/USF and BYU/Stanford even though those opponents had
    # lost the prior H2H in 2022.  Therefore an arbitrary all-history H2H loss is
    # too broad for this rule.  Treat only current-season or immediately-prior-
    # season H2H losses as revenge; an older/no prior meeting is no revenge.
    _cur_season = pd.to_numeric(tg.get("Season"), errors="coerce")
    _last_h2h_season = pd.to_numeric(tg.get("Last_Matchup_Season_System"), errors="coerce")
    _season_gap = _cur_season - _last_h2h_season
    _recent_h2h = _last_h2h_season.notna() & _season_gap.ge(0) & _season_gap.le(1)
    _rev_recent = pd.Series(np.nan, index=tg.index, dtype="float64")
    _season_known = _cur_season.notna()
    _rev_recent.loc[_season_known & ~_recent_h2h] = 0.0
    _recent_known = _season_known & _recent_h2h & _last_h2h_win.notna()
    _rev_recent.loc[_recent_known] = (_last_h2h_win.loc[_recent_known] < 0.5).astype(float)
    _existing_recent = (
        pd.to_numeric(tg.get("Revenge_Flag_CurrentOrPriorSeason"), errors="coerce")
        if "Revenge_Flag_CurrentOrPriorSeason" in tg.columns
        else pd.Series(np.nan, index=tg.index, dtype="float64")
    )
    tg["Revenge_Flag_CurrentOrPriorSeason"] = _existing_recent.combine_first(_rev_recent)

    # Final-two regular-season window. Exact Week data wins; team-game proxy is explicit.
    tg["Final_Two_Regular_Season_Proxy"] = (
        tg["Sport"].eq("NFL") & tg["Is_Regular_Season"].fillna(1).eq(1) & (tg["Team_Game_Number"] >= 16)
    ).astype("int8")
    _final_week = (
        pd.to_numeric(tg["Regular_Season_Final_Week"], errors="coerce")
        if "Regular_Season_Final_Week" in tg.columns
        else pd.Series(np.nan, index=tg.index, dtype="float64")
    )
    _exact_final_two = (
        tg["Week_Number"].notna() & _final_week.notna() &
        (tg["Week_Number"] >= (_final_week - 1))
    )
    _legacy_week_final_two = tg["Week_Number"].notna() & _final_week.isna() & (tg["Week_Number"] >= 17)
    tg["Final_Two_Regular_Season"] = np.where(
        _exact_final_two | _legacy_week_final_two,
        1,
        np.where(tg["Week_Number"].notna() & _final_week.notna(), 0, tg["Final_Two_Regular_Season_Proxy"]),
    ).astype("int8")

    # Opponent mirrors of current roles + prior state.
    mirror_cols = [
        "Is_Home", "ML_Odds", "Is_ML_Dog", "Is_ML_Favorite", "Spread_Value", "Opening_Spread",
        "WinPct_Prior_System", "SU_Win_Streak_Prior", "SU_Loss_Streak_Prior",
        "SU_Win_Streak_Entering_Previous_Game",
        "ATS_Win_Streak_Prior", "ATS_Loss_Streak_Prior", "Days_Since_Last_Game_System",
        "Games_Last_2_Days_System", "Games_Last_4_Days_System", "Games_Last_7_Days_System",
        "Is_B2B_System", "Is_3in4_System", "Had_Bye_Last_Game_System", "BigAl_Context_Had_Bye_Proxy",
        "Prev_SU_Win", "Prev_SU_Loss", "Prev_SU_Margin", "Prev_Points_For", "Prev_Points_Against", "Prev_Spread_Value",
        "Prev_ATS_Win", "Prev_ATS_Loss", "Prev_ATS_Cover_Margin", "Prev2_SU_Win", "Prev2_SU_Loss",
        "Prev2_ATS_Win", "Prev2_ATS_Loss", "Prev2_ATS_Cover_Margin",
        "Prev3_SU_Win", "Prev3_SU_Loss", "Prev3_ATS_Win", "Prev3_ATS_Loss", "Prev3_ATS_Cover_Margin",
        "Prev_Is_ML_Dog", "Prev_Is_ML_Favorite", "Prev_Is_Road_Favorite", "Prev_Is_Road_Dog_9Plus",
        "Prev_Opponent_Is_Defending_Champion", "Dog_Rate_Last10_Prior", "Avg_Points_For_Prior",
        "Road_Favorite_ROI_Prior", "Team_Game_Number", "Revenge_Flag_Current", "Revenge_Flag_CurrentOrPriorSeason",
        "MMI_ATS_WinPct_Prior_System", "MMI_ATS_Games_Prior_System",
        "Pathi_FB_Team_Role_ATS_Last5", "Pathi_FB_Team_Role_ATS_Last10", "Pathi_FB_Team_Role_ATS_Season",
        "Team_Is_Defending_Champion", "Team_Prior_Season_Playoff", "Is_Final_Home_Game",
        "Team_Eliminated_With_Loss", "Team_Series_Wins", "Opp_Series_Wins",
    ]
    mirror_cols = [c for c in mirror_cols if c in tg.columns]
    opp = tg[["Sport", "Game_Key", "Team"] + mirror_cols].copy()
    opp = opp.rename(columns={"Team": "Opponent", **{c: f"Opp_{c}" for c in mirror_cols}})
    tg = tg.merge(opp, on=["Sport", "Game_Key", "Opponent"], how="left", validate="1:1")
    if "Opp_MMI_ATS_WinPct_Prior_System" in tg.columns:
        tg["MMI_Opp_ATS_WinPct_Prior_System"] = pd.to_numeric(tg["Opp_MMI_ATS_WinPct_Prior_System"], errors="coerce").astype("float32")
    if "Opp_MMI_ATS_Games_Prior_System" in tg.columns:
        tg["MMI_Opp_ATS_Games_Prior_System"] = pd.to_numeric(tg["Opp_MMI_ATS_Games_Prior_System"], errors="coerce").astype("float32")

    # Big Al hoops revenge-context family (DB-only, regular-season, prior-only).
    # Big Al's public revenge methodology evaluates more than a one-bit revenge
    # flag: prior site, spread, team-strength differential, loss magnitude and
    # points allowed.  These are raw context features, not named systems and do
    # not increment BigAl_System_Count or BigAl_Enhancer_Count.
    _hoops_revenge_sport = tg["Sport"].astype(str).str.upper().isin(["NBA", "NCAAB"])
    _hoops_regular = pd.to_numeric(tg.get("Is_Regular_Season"), errors="coerce").fillna(1).eq(1)
    _season_last_win = pd.to_numeric(tg.get("Season_H2H_Last_SU_Win_Prior"), errors="coerce")
    _hoops_revenge_active = _hoops_revenge_sport & _hoops_regular & _season_last_win.eq(0)
    tg["BigAl_Hoops_Revenge_Context_Active"] = _hoops_revenge_active.astype("int8")

    _season_last_margin = pd.to_numeric(tg.get("Season_H2H_Last_SU_Margin_Prior"), errors="coerce")
    _season_last_spread = pd.to_numeric(tg.get("Season_H2H_Last_Spread_Prior"), errors="coerce")
    _season_last_pa = pd.to_numeric(tg.get("Season_H2H_Last_Points_Against_Prior"), errors="coerce")
    _season_last_home = pd.to_numeric(tg.get("Season_H2H_Last_Is_Home_Prior"), errors="coerce")
    _season_days = pd.to_numeric(tg.get("Season_H2H_Days_Since_Last_Matchup_Prior"), errors="coerce")
    _cur_home = pd.to_numeric(tg.get("Is_Home"), errors="coerce")
    _team_wp = pd.to_numeric(tg.get("WinPct_Prior_System"), errors="coerce")
    _opp_wp = pd.to_numeric(tg.get("Opp_WinPct_Prior_System"), errors="coerce")

    tg["BigAl_Hoops_Revenge_LastMeeting_LossMargin"] = (-_season_last_margin).where(_hoops_revenge_active).astype("float32")
    tg["BigAl_Hoops_Revenge_LastMeeting_Spread"] = _season_last_spread.where(_hoops_revenge_active).astype("float32")
    tg["BigAl_Hoops_Revenge_LastMeeting_PointsAllowed"] = _season_last_pa.where(_hoops_revenge_active).astype("float32")
    tg["BigAl_Hoops_Revenge_DaysSinceLastMeeting"] = _season_days.where(_hoops_revenge_active).astype("float32")
    tg["BigAl_Hoops_Revenge_WinPctGap_Prior"] = (_team_wp - _opp_wp).where(_hoops_revenge_active).astype("float32")
    tg["BigAl_Hoops_Revenge_LastMeeting_SiteFlip"] = (
        _hoops_revenge_active & _season_last_home.notna() & _cur_home.notna() & _season_last_home.ne(_cur_home)
    ).astype("int8")
    tg["BigAl_Hoops_Revenge_Context_DataReady"] = (
        _hoops_revenge_sport & _hoops_regular & _season_last_win.notna() &
        _season_last_margin.notna() & _season_last_spread.notna() & _season_last_pa.notna()
    ).astype("int8")

    # Pathi football opponent role trends + regime aliases.
    for _n in ("Last5", "Last10", "Season"):
        _src = f"Opp_Pathi_FB_Team_Role_ATS_{_n}"
        tg[f"Pathi_FB_Opp_Role_ATS_{_n}"] = pd.to_numeric(tg.get(_src), errors="coerce")
    tg["Pathi_FB_Is_Postseason"] = pd.to_numeric(tg.get("Is_Postseason"), errors="coerce").fillna(0).astype("int8")
    tg["Pathi_FB_Is_Regular_Season"] = pd.to_numeric(tg.get("Is_Regular_Season"), errors="coerce").fillna(0).astype("int8")

    # Standard current aliases used by the rule engine.
    tg["Is_Road"] = (tg["Is_Home"] == 0).astype("int8")
    tg["Is_Plus_Money"] = (
        _sys_float64_series(tg["ML_Odds"], tg.index).gt(0)
    ).fillna(False).astype("int8")
    tg["Role_Flip_Dog_To_Favorite"] = (
        _sys_float64_series(tg["Opening_Is_ML_Dog"], tg.index).eq(1) &
        _sys_float64_series(tg["Is_ML_Favorite"], tg.index).eq(1)
    ).fillna(False).astype("int8")

    tg.drop(columns=["__fb_spread_dog", "__fb_spread_fav"], inplace=True, errors="ignore")
    tg = _sys_normalize_nullable_numeric_frame(tg)
    tg = add_pathi_bigal_rule_flags(tg)
    return tg




def add_pathi_bigal_rule_flags(state: pd.DataFrame) -> pd.DataFrame:
    """Apply named Pathi / Big Al systems to one-row-per-team-game state."""
    if state is None or state.empty:
        return state.copy()
    s = _sys_normalize_nullable_numeric_frame(state)
    sport = s["Sport"].astype(str).str.upper()

    def n(name, default=np.nan):
        # Always return plain float64. This prevents nullable BooleanArray values
        # from carrying pd.NA into deterministic .astype("int8") rule flags.
        if name in s.columns:
            return _sys_float64_series(s[name], s.index)
        return pd.Series(default, index=s.index, dtype="float64")

    def ready(*names):
        if not names:
            return pd.Series(True, index=s.index)
        out = pd.Series(True, index=s.index)
        for name in names:
            out &= n(name).notna()
        return out

    def flag_sum(cols, dtype="int16"):
        """NA/inf-safe sum of deterministic 0/1 system flags."""
        cols = [c for c in cols if c in s.columns]
        if not cols:
            return pd.Series(0, index=s.index, dtype=dtype)
        arrays = [
            _sys_float64_series(s[c], s.index).to_numpy(dtype=np.float64, na_value=np.nan)
            for c in cols
        ]
        a = np.column_stack(arrays)
        a = np.nan_to_num(a, nan=0.0, posinf=0.0, neginf=0.0)
        vals = np.rint(a.sum(axis=1))
        return _sys_int_flag(pd.Series(vals, index=s.index), s.index, dtype=dtype)

    is_mlb = sport.eq("MLB")
    is_nfl = sport.eq("NFL")
    is_ncaaf = sport.eq("NCAAF")
    is_nba = sport.eq("NBA")
    is_wnba = sport.eq("WNBA")
    is_ncaab = sport.isin(["NCAAB", "NCAAM"])
    is_cfl = sport.eq("CFL")

    # Regular-season-only guard for all new ALL Access / ingredient enhancers.
    # Missing explicit regular-season flags are allowed only when neither
    # preseason nor postseason is identified by the state builder.
    _regular_only = (
        n("Is_Preseason").fillna(0).ne(1)
        & n("Is_Postseason").fillna(0).ne(1)
        & n("Is_Playoffs").fillna(0).ne(1)
        & n("Is_Regular_Season").fillna(1).eq(1)
    )

    # ------------------------------------------------------------------
    # Eric Pathi - MLB mechanical systems / screens.
    # ------------------------------------------------------------------
    s["Pathi_M1_DogThatWon_DataReady"] = ready("Is_ML_Dog", "Prev_Is_ML_Dog", "Prev_SU_Win").astype("int8")
    s["Pathi_M1_DogThatWon"] = (
        is_mlb & n("Is_ML_Dog").eq(1) & n("Prev_Is_ML_Dog").eq(1) & n("Prev_SU_Win").eq(1)
    ).astype("int8")

    s["Pathi_M8_DogWon_BetterPrice_DataReady"] = ready("ML_Odds", "Prev_ML_Odds").astype("int8")
    s["Pathi_M8_DogWon_BetterPrice"] = (
        s["Pathi_M1_DogThatWon"].eq(1) & n("ML_Odds").gt(n("Prev_ML_Odds")) & n("ML_Odds").gt(0)
    ).astype("int8")

    s["Pathi_M2_HomeDog_DataReady"] = ready("ML_Odds", "Is_Home").astype("int8")
    s["Pathi_M2_HomeDog"] = (
        is_mlb & n("Is_Home").eq(1) & n("ML_Odds").gt(0)
    ).astype("int8")

    s["Pathi_M3_Rule10_LosingStreak_DataReady"] = ready("SU_Loss_Streak_Prior").astype("int8")
    s["Pathi_M3_Rule10_LosingStreak"] = (
        is_mlb & n("SU_Loss_Streak_Prior").between(7, 10, inclusive="both")
    ).astype("int8")
    s["Pathi_M3_Rule10_PlusMoney"] = (
        s["Pathi_M3_Rule10_LosingStreak"].eq(1) & n("ML_Odds").gt(0)
    ).astype("int8")

    # Flag is on the recommended opponent side, not on the hot favorite being faded.
    s["Pathi_M4_ExtendedWinStreakFade_DataReady"] = ready("Opp_SU_Win_Streak_Prior", "Opp_Is_ML_Favorite", "Is_ML_Dog").astype("int8")
    s["Pathi_M4_ExtendedWinStreakFade"] = (
        is_mlb & n("Opp_SU_Win_Streak_Prior").ge(6) & n("Opp_Is_ML_Favorite").eq(1) & n("Is_ML_Dog").eq(1)
    ).astype("int8")

    s["Pathi_M5_TravelOffDayFreeze_DataReady"] = ready("Opp_SU_Win_Streak_Prior", "Opp_Days_Since_Last_Game_System", "Opp_Is_ML_Favorite").astype("int8")
    s["Pathi_M5_TravelOffDayFreeze"] = (
        is_mlb & n("Opp_SU_Win_Streak_Prior").ge(5) & n("Opp_Days_Since_Last_Game_System").ge(2.0) &
        n("Opp_Is_ML_Favorite").eq(1) & n("Is_ML_Dog").eq(1)
    ).astype("int8")

    # M6 wording is qualitative, so this is deliberately labeled a Screen.
    s["Pathi_M6_WeakTeamNewChalk_Screen_DataReady"] = ready("Opp_Is_ML_Favorite", "Opp_Prev_Is_ML_Dog", "Opp_Dog_Rate_Last10_Prior", "Opp_WinPct_Prior_System").astype("int8")
    s["Pathi_M6_WeakTeamNewChalk_Screen"] = (
        is_mlb & n("Opp_Is_ML_Favorite").eq(1) & n("Opp_Prev_Is_ML_Dog").eq(1) &
        n("Opp_Dog_Rate_Last10_Prior").ge(PATHI_PRIOR_DOG_RATE_MIN) &
        n("Opp_WinPct_Prior_System").le(PATHI_WEAK_TEAM_MAX_WIN_PCT) & n("Is_ML_Dog").eq(1)
    ).astype("int8")

    s["Pathi_M7_BadRoadFavoriteProfile_DataReady"] = ready("Opp_Is_Home", "Opp_Is_ML_Favorite", "Opp_Road_Favorite_ROI_Prior").astype("int8")
    s["Pathi_M7_BadRoadFavoriteProfile"] = (
        is_mlb & n("Opp_Is_Home").eq(0) & n("Opp_Is_ML_Favorite").eq(1) &
        n("Opp_Road_Favorite_ROI_Prior").lt(0) & n("Is_ML_Dog").eq(1)
    ).astype("int8")

    s["Pathi_M9_Plus15_PlusMoney_DataReady"] = ready("Spread_Value", "Spread_Odds").astype("int8")
    s["Pathi_M9_Plus15_PlusMoney"] = (
        is_mlb & np.isclose(n("Spread_Value"), 1.5, atol=0.01) & n("Spread_Odds").gt(0)
    ).astype("int8")

    s["Pathi_RoleFlip_DogToFavorite_Cancel_DataReady"] = ready("Opening_Is_ML_Dog", "Is_ML_Favorite").astype("int8")
    s["Pathi_RoleFlip_DogToFavorite_Cancel"] = (
        is_mlb & n("Opening_Is_ML_Dog").eq(1) & n("Is_ML_Favorite").eq(1)
    ).astype("int8")

    # Additional diagnostic requested in the review: prior road favorite lost and is chalk again.
    # This is a screen, not a sourced Pathi mechanical threshold.
    s["Pathi_RoadFavLost_StillFavorite_Screen"] = (
        is_mlb & n("Opp_Prev_Is_Road_Favorite").eq(1) & n("Opp_Prev_SU_Loss").eq(1) &
        n("Opp_Is_ML_Favorite").eq(1) & n("Is_ML_Dog").eq(1)
    ).astype("int8")

    # ------------------------------------------------------------------
    # Big Al - exact systems where inputs exist; metadata-heavy systems
    # expose DataReady flags instead of manufacturing missing context.
    # ------------------------------------------------------------------
    # NFL 1 - Week 1: fade prior-year playoff team; flag play-on side.
    _nfl_week1 = n("Week_Number").eq(1) | (n("Week_Number").isna() & n("Team_Game_Number").eq(1))
    s["BigAl_NFL1_Week1FadePlayoffTeam_DataReady"] = (
        ready("Team_Prior_Season_Playoff", "Opponent_Prior_Season_Playoff") &
        (n("Week_Number").notna() | n("Team_Game_Number").notna())
    ).astype("int8")
    s["BigAl_NFL1_Week1FadePlayoffTeam"] = (
        is_nfl & n("Is_Regular_Season").eq(1) & _nfl_week1 & n("Team_Prior_Season_Playoff").eq(0) & n("Opponent_Prior_Season_Playoff").eq(1)
    ).astype("int8")
    s["BigAl_NFL1_HomeTightener"] = (s["BigAl_NFL1_Week1FadePlayoffTeam"].eq(1) & n("Is_Home").eq(1)).astype("int8")

    # NFL 2 - final two regular-season weeks home dog off two losses vs <=.500 opponent.
    s["BigAl_NFL2_LateSeasonHomeDog_DataReady"] = ready("Final_Two_Regular_Season", "SU_Loss_Streak_Prior", "Opp_WinPct_Prior_System", "Spread_Value").astype("int8")
    s["BigAl_NFL2_LateSeasonHomeDog"] = (
        is_nfl & n("Final_Two_Regular_Season").eq(1) & n("Is_Home").eq(1) & n("Spread_Value").gt(0) &
        n("SU_Loss_Streak_Prior").ge(2) & n("Opp_WinPct_Prior_System").le(0.500)
    ).astype("int8")
    s["BigAl_NFL2_OppOffATSLoss_Tightener"] = (
        s["BigAl_NFL2_LateSeasonHomeDog"].eq(1) & n("Opp_Prev_ATS_Loss").eq(1)
    ).astype("int8")

    # NFL 3 - flag is on opponent of high-scoring prior winner.
    s["BigAl_NFL3_PlayoffHighScoreFade_DataReady"] = ready("Is_Postseason", "Opp_Is_Home", "Opp_Prev_SU_Win", "Opp_Prev_Points_For", "Prev_Points_For").astype("int8")
    s["BigAl_NFL3_PlayoffHighScoreFade"] = (
        is_nfl & n("Is_Postseason").eq(1) & n("Opp_Is_Home").eq(0) & n("Opp_Prev_SU_Win").eq(1) &
        n("Opp_Prev_Points_For").ge(35) & n("Prev_Points_For").lt(35)
    ).astype("int8")

    # NFL 4 - preseason play-on team getting >=1.5 more spread points at close than at open.
    # Example: -2.5 -> +1.5 qualifies because current - opening = +4.0.
    s["BigAl_NFL4_PreseasonContrarianMove_DataReady"] = ready("Is_Preseason", "Spread_Value", "Opening_Spread").astype("int8")
    s["BigAl_NFL4_PreseasonContrarianMove"] = (
        is_nfl & n("Is_Preseason").eq(1) & ((n("Spread_Value") - n("Opening_Spread")) >= 1.5)
    ).astype("int8")

    # NFL 5 - game-level OVER condition; same flag on both team-state rows.
    s["BigAl_NFL5_PreseasonLowOffenseOver_DataReady"] = ready("Is_Preseason", "Avg_Points_For_Prior", "Opp_Avg_Points_For_Prior").astype("int8")
    low_pair = (
        (n("Avg_Points_For_Prior").lt(10) & n("Opp_Avg_Points_For_Prior").lt(19)) |
        (n("Opp_Avg_Points_For_Prior").lt(10) & n("Avg_Points_For_Prior").lt(19))
    )
    s["BigAl_NFL5_PreseasonLowOffenseOver"] = (is_nfl & n("Is_Preseason").eq(1) & low_pair).astype("int8")
    s["BigAl_NFL5_TotalUnder40_Tightener"] = (
        s["BigAl_NFL5_PreseasonLowOffenseOver"].eq(1) & n("Current_Total").lt(40)
    ).astype("int8")

    # College football 1 - Week 2 home off 42+ win, nonconference, opponent no revenge.
    # Published condition is the team's second game; use Team_Game_Number rather than
    # calendar Week_Number so a bye does not misclassify the system.
    # V13.2.3 uses current/prior-season revenge when that state exists because Big
    # Al's published 2025 examples show that a 2022 H2H loss does not disqualify a
    # 2025 opponent.  Older artifacts can still fall back to the legacy field.
    _cf1_opp_revenge_field = (
        "Opp_Revenge_Flag_CurrentOrPriorSeason"
        if (
            "Opp_Revenge_Flag_CurrentOrPriorSeason" in s.columns
            and pd.to_numeric(s["Opp_Revenge_Flag_CurrentOrPriorSeason"],errors="coerce").notna().any()
        )
        else "Opp_Revenge_Flag_Current"
    )
    s["BigAl_CF1_Week2Home42Win_DataReady"] = ready("Team_Game_Number", "Prev_SU_Win", "Prev_Points_For", "Is_Conference_Game", _cf1_opp_revenge_field).astype("int8")
    s["BigAl_CF1_Week2Home42Win"] = (
        is_ncaaf & n("Team_Game_Number").eq(2) & n("Is_Home").eq(1) & n("Prev_SU_Win").eq(1) &
        n("Prev_Points_For").gt(42) & n("Is_Conference_Game").eq(0) & n(_cf1_opp_revenge_field).eq(0)
    ).astype("int8")

    # College football 2 - regular season game 9+, revenge dog, prior 50+ points.
    s["BigAl_CF2_LateSeasonRevengeDog_DataReady"] = ready("Team_Game_Number", "Revenge_Flag_Current", "Prev_Points_For", "Spread_Value").astype("int8")
    s["BigAl_CF2_LateSeasonRevengeDog"] = (
        is_ncaaf & n("Is_Regular_Season").fillna(1).eq(1) & n("Team_Game_Number").ge(9) &
        n("Revenge_Flag_Current").eq(1) & n("Spread_Value").gt(0) & n("Prev_Points_For").gt(50)
    ).astype("int8")
    s["BigAl_CF2_Away_Tightener"] = (s["BigAl_CF2_LateSeasonRevengeDog"].eq(1) & n("Is_Home").eq(0)).astype("int8")

    # User-provided Big Al NCAAF system (2026-09-11): fade a team in its next game
    # after it was favored by 19+ points and lost outright.  Flags are always placed
    # on the recommended PLAY-ON side, so this checks the current opponent's prior
    # game state rather than flagging the team being faded.
    s["BigAl_CF3_Fade19PlusFavoriteUpsetLoss_DataReady"] = (
        is_ncaaf & ready("Opp_Prev_Spread_Value", "Opp_Prev_SU_Loss")
    ).astype("int8")
    s["BigAl_CF3_Fade19PlusFavoriteUpsetLoss"] = (
        is_ncaaf & n("Is_Regular_Season").fillna(1).eq(1) &
        n("Opp_Prev_Spread_Value").le(-19.0) & n("Opp_Prev_SU_Loss").eq(1)
    ).astype("int8")

    # NBA 1 - consecutive-game rematch, double-digit road dog lost SU and ATS prior meeting.
    s["BigAl_NBA1_B2BRematchRoadDog_DataReady"] = ready("Immediate_Rematch_Flag", "Spread_Value", "Prev_SU_Loss", "Prev_ATS_Loss").astype("int8")
    s["BigAl_NBA1_B2BRematchRoadDog"] = (
        is_nba & n("Is_Regular_Season").fillna(1).eq(1) & n("Immediate_Rematch_Flag").eq(1) &
        n("Is_Home").eq(0) & n("Spread_Value").ge(10) & n("Prev_SU_Loss").eq(1) & n("Prev_ATS_Loss").eq(1)
    ).astype("int8")
    s["BigAl_NBA1_PriorLoss25_Tightener"] = (
        s["BigAl_NBA1_B2BRematchRoadDog"].eq(1) & n("Prev_SU_Margin").le(-25)
    ).astype("int8")

    # NBA 2 - previous three covers by >=16 points each; current not road.
    s["BigAl_NBA2_ThreeMassiveCovers_DataReady"] = ready("Prev_ATS_Cover_Margin", "Prev2_ATS_Cover_Margin", "Prev3_ATS_Cover_Margin").astype("int8")
    s["BigAl_NBA2_ThreeMassiveCovers"] = (
        is_nba & n("Is_Home").eq(1) & n("Prev_ATS_Cover_Margin").ge(16) &
        n("Prev2_ATS_Cover_Margin").ge(16) & n("Prev3_ATS_Cover_Margin").ge(16)
    ).astype("int8")

    # NBA 3 - flag play-on opponent of home team returning from 9+ road-dog upset over defending champ.
    s["BigAl_NBA3_FadeHomeAfterChampUpset_DataReady"] = ready("Opp_Is_Home", "Opp_Prev_SU_Win", "Opp_Prev_Is_Road_Dog_9Plus", "Opp_Prev_Opponent_Is_Defending_Champion").astype("int8")
    s["BigAl_NBA3_FadeHomeAfterChampUpset"] = (
        is_nba & n("Opp_Is_Home").eq(1) & n("Opp_Prev_SU_Win").eq(1) &
        n("Opp_Prev_Is_Road_Dog_9Plus").eq(1) & n("Opp_Prev_Opponent_Is_Defending_Champion").eq(1)
    ).astype("int8")
    s["BigAl_NBA3_WinPct572_Tightener"] = (
        s["BigAl_NBA3_FadeHomeAfterChampUpset"].eq(1) & n("Opp_WinPct_Prior_System").gt(0.572)
    ).astype("int8")

    # NBA 4 - final home game, favorite >5, revenge.
    s["BigAl_NBA4_FinalHomeFavRevenge_DataReady"] = ready("Is_Final_Home_Game", "Spread_Value", "Revenge_Flag_Current").astype("int8")
    s["BigAl_NBA4_FinalHomeFavRevenge"] = (
        is_nba & n("Is_Regular_Season").eq(1) & n("Is_Final_Home_Game").eq(1) & n("Is_Home").eq(1) & n("Spread_Value").lt(-5) & n("Revenge_Flag_Current").eq(1)
    ).astype("int8")
    s["BigAl_NBA4_NotOffSUATSLoss_Tightener"] = (
        s["BigAl_NBA4_FinalHomeFavRevenge"].eq(1) & ~(n("Prev_SU_Loss").eq(1) & n("Prev_ATS_Loss").eq(1))
    ).astype("int8")

    # NBA 5 - winning road team +10 vs defending champion in playoffs.
    s["BigAl_NBA5_PlayoffBigDogVsChamp_DataReady"] = ready("Is_Postseason", "WinPct_Prior_System", "Spread_Value", "Opponent_Is_Defending_Champion").astype("int8")
    s["BigAl_NBA5_PlayoffBigDogVsChamp"] = (
        is_nba & n("Is_Postseason").eq(1) & n("WinPct_Prior_System").gt(0.5) & n("Is_Home").eq(0) &
        n("Spread_Value").gt(10) & n("Opponent_Is_Defending_Champion").eq(1)
    ).astype("int8")
    s["BigAl_NBA5_ChampOffSUWin_Tightener"] = (
        s["BigAl_NBA5_PlayoffBigDogVsChamp"].eq(1) & n("Opp_Prev_SU_Win").eq(1)
    ).astype("int8")

    # NBA 6 - Finals Game 4 road team down 2-1, off road win, .625+, <=4-point favorite.
    s["BigAl_NBA6_FinalsGame4_DataReady"] = ready("Is_Finals", "Series_Game_Number", "Team_Series_Wins", "Opp_Series_Wins", "Prev_SU_Win", "Prev_Is_Home", "WinPct_Prior_System", "Spread_Value").astype("int8")
    s["BigAl_NBA6_FinalsGame4"] = (
        is_nba & n("Is_Finals").eq(1) & n("Series_Game_Number").eq(4) & n("Is_Home").eq(0) &
        n("Team_Series_Wins").eq(1) & n("Opp_Series_Wins").eq(2) & n("Prev_SU_Win").eq(1) &
        n("Prev_Is_Home").eq(0) & n("WinPct_Prior_System").ge(0.625) & n("Spread_Value").ge(-4)
    ).astype("int8")

    # NBA 7 - both teams would be eliminated with a loss => UNDER.
    s["BigAl_NBA7_TwoTeamEliminationUnder_DataReady"] = ready("Team_Eliminated_With_Loss", "Opponent_Eliminated_With_Loss").astype("int8")
    s["BigAl_NBA7_TwoTeamEliminationUnder"] = (
        is_nba & n("Team_Eliminated_With_Loss").eq(1) & n("Opponent_Eliminated_With_Loss").eq(1)
    ).astype("int8")

    # NBA 8 - published 3/17/24 regular-season revenge system.  Go against
    # the current favorite/PK that scored 145+ in winning the season's prior
    # meeting; this row is the revenge/play-on side.  Winning record is the
    # explicitly published tightener.
    s["BigAl_NBA8_Revenge145FadeFavorite_DataReady"] = ready(
        "Spread_Value", "Season_H2H_Last_SU_Win_Prior", "Season_H2H_Last_Points_Against_Prior"
    ).astype("int8")
    s["BigAl_NBA8_Revenge145FadeFavorite"] = (
        is_nba & _regular_only & n("Spread_Value").ge(0) &
        n("Season_H2H_Last_SU_Win_Prior").lt(0.5) &
        n("Season_H2H_Last_Points_Against_Prior").ge(145)
    ).astype("int8")
    s["BigAl_NBA8_WinningRecord_Tightener"] = (
        s["BigAl_NBA8_Revenge145FadeFavorite"].eq(1) & n("WinPct_Prior_System").gt(0.500)
    ).astype("int8")

    # NCAAB - dog/PK off two SU+ATS losses by >20; opponent not off two losses.
    s["BigAl_CBB1_UglyDog20Losses_DataReady"] = ready(
        "Spread_Value", "Prev_SU_Margin", "Prev_ATS_Cover_Margin", "Prev2_SU_Margin", "Prev2_ATS_Cover_Margin",
        "Opp_Prev_SU_Loss", "Opp_Prev2_SU_Loss"
    ).astype("int8")
    s["BigAl_CBB1_UglyDog20Losses"] = (
        is_ncaab & n("Spread_Value").ge(0) &
        n("Prev_SU_Margin").lt(-20) & n("Prev_ATS_Cover_Margin").lt(-20) &
        n("Prev2_SU_Margin").lt(-20) & n("Prev2_ATS_Cover_Margin").lt(-20) &
        ~(n("Opp_Prev_SU_Loss").eq(1) & n("Opp_Prev2_SU_Loss").eq(1))
    ).astype("int8")
    s["BigAl_CBB1_ThreeLoss_Tightener"] = (
        s["BigAl_CBB1_UglyDog20Losses"].eq(1) & n("Prev3_SU_Margin").lt(-20) & n("Prev3_ATS_Cover_Margin").lt(-20)
    ).astype("int8")

    # NCAAB 2 - fade a favorite laying 6+ immediately after a SU loss when it
    # entered that loss on a 10+ game winning streak; play-on opponent must NOT
    # be off a combined SU + ATS win.  Public Big Al system, regular season only.
    s["BigAl_CBB2_Fade10WinStreakFavorite_DataReady"] = ready(
        "Is_Regular_Season", "Spread_Value", "Opp_Prev_SU_Loss",
        "Opp_SU_Win_Streak_Entering_Previous_Game", "Prev_SU_Win", "Prev_ATS_Win"
    ).astype("int8")
    s["BigAl_CBB2_Fade10WinStreakFavorite"] = (
        is_ncaab & n("Is_Regular_Season").eq(1) & n("Spread_Value").ge(6) &
        n("Opp_Prev_SU_Loss").eq(1) & n("Opp_SU_Win_Streak_Entering_Previous_Game").ge(10) &
        ~(n("Prev_SU_Win").eq(1) & n("Prev_ATS_Win").eq(1))
    ).astype("int8")

    # NCAAB 3 - winning home team in regular season seeking revenge for a 27+
    # point loss in an earlier meeting. Tightener: dog >2 and off a SU loss.
    s["BigAl_CBB3_HomeRevenge27_DataReady"] = ready(
        "Is_Regular_Season", "Is_Home", "WinPct_Prior_System", "H2H_Last_Loss_Margin"
    ).astype("int8")
    s["BigAl_CBB3_HomeRevenge27"] = (
        is_ncaab & n("Is_Regular_Season").eq(1) & n("Is_Home").eq(1) &
        n("WinPct_Prior_System").gt(0.500) & n("H2H_Last_Loss_Margin").le(-27)
    ).astype("int8")
    s["BigAl_CBB3_DogOffLoss_Tightener"] = (
        s["BigAl_CBB3_HomeRevenge27"].eq(1) & n("Spread_Value").gt(2) & n("Prev_SU_Loss").eq(1)
    ).astype("int8")

    # CFL 1 - second meeting after 63+ first meeting => UNDER; total >51 tightener.
    s["BigAl_CFL1_SecondMeetingUnder_DataReady"] = ready("Season_H2H_Meeting_Number", "First_Meeting_Actual_Total_Prior").astype("int8")
    s["BigAl_CFL1_SecondMeetingUnder"] = (
        is_cfl & n("Season_H2H_Meeting_Number").eq(2) & n("First_Meeting_Actual_Total_Prior").ge(63)
    ).astype("int8")
    s["BigAl_CFL1_TotalAbove51_Tightener"] = (
        s["BigAl_CFL1_SecondMeetingUnder"].eq(1) & n("Current_Total").gt(51)
    ).astype("int8")

    # CFL 2 - fade elite dog >3 after Game 7; flag play-on opponent.
    s["BigAl_CFL2_EliteDogFade_DataReady"] = ready("Opp_Team_Game_Number", "Opp_WinPct_Prior_System", "Opp_Spread_Value").astype("int8")
    s["BigAl_CFL2_EliteDogFade"] = (
        is_cfl & n("Opp_Team_Game_Number").ge(7) & n("Opp_WinPct_Prior_System").ge(0.820) & n("Opp_Spread_Value").gt(3)
    ).astype("int8")

    # CFL 3 - disclosed 8/20/26 situational system: in the season's third
    # meeting, play the away underdog after it lost the first two meetings.
    s["BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo_DataReady"] = ready(
        "Season_H2H_Meeting_Number", "Is_Home", "Spread_Value", "Season_H2H_Consecutive_Losses_Prior"
    ).astype("int8")
    s["BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo"] = (
        is_cfl & _regular_only & n("Season_H2H_Meeting_Number").eq(3) &
        n("Is_Home").eq(0) & n("Spread_Value").gt(0) &
        n("Season_H2H_Consecutive_Losses_Prior").ge(2)
    ).astype("int8")

    # ------------------------------------------------------------------
    # Big Al readiness + partial-match layer.
    # DataReady is explicitly sport-gated and requires every input used by the
    # exact rule. Match_Ratio is leakage-safe: it measures how much of the
    # published setup is present BEFORE the game, without using the result.
    # ------------------------------------------------------------------
    _bigal_specs = {
        "BigAl_NFL1_Week1FadePlayoffTeam": (is_nfl, ["Is_Regular_Season", "Team_Prior_Season_Playoff", "Opponent_Prior_Season_Playoff"]),
        "BigAl_NFL2_LateSeasonHomeDog": (is_nfl, ["Final_Two_Regular_Season", "Is_Home", "Spread_Value", "SU_Loss_Streak_Prior", "Opp_WinPct_Prior_System"]),
        "BigAl_NFL3_PlayoffHighScoreFade": (is_nfl, ["Is_Postseason", "Opp_Is_Home", "Opp_Prev_SU_Win", "Opp_Prev_Points_For", "Prev_Points_For"]),
        "BigAl_NFL4_PreseasonContrarianMove": (is_nfl, ["Is_Preseason", "Spread_Value", "Opening_Spread"]),
        "BigAl_NFL5_PreseasonLowOffenseOver": (is_nfl, ["Is_Preseason", "Avg_Points_For_Prior", "Opp_Avg_Points_For_Prior"]),
        "BigAl_CF1_Week2Home42Win": (is_ncaaf, ["Team_Game_Number", "Is_Home", "Prev_SU_Win", "Prev_Points_For", "Is_Conference_Game", _cf1_opp_revenge_field]),
        "BigAl_CF2_LateSeasonRevengeDog": (is_ncaaf, ["Is_Regular_Season", "Team_Game_Number", "Revenge_Flag_Current", "Spread_Value", "Prev_Points_For"]),
        "BigAl_CF3_Fade19PlusFavoriteUpsetLoss": (is_ncaaf, ["Is_Regular_Season", "Opp_Prev_Spread_Value", "Opp_Prev_SU_Loss"]),
        "BigAl_NBA1_B2BRematchRoadDog": (is_nba, ["Is_Regular_Season", "Immediate_Rematch_Flag", "Is_Home", "Spread_Value", "Prev_SU_Loss", "Prev_ATS_Loss"]),
        "BigAl_NBA2_ThreeMassiveCovers": (is_nba, ["Is_Home", "Prev_ATS_Cover_Margin", "Prev2_ATS_Cover_Margin", "Prev3_ATS_Cover_Margin"]),
        "BigAl_NBA3_FadeHomeAfterChampUpset": (is_nba, ["Opp_Is_Home", "Opp_Prev_SU_Win", "Opp_Prev_Is_Road_Dog_9Plus", "Opp_Prev_Opponent_Is_Defending_Champion"]),
        "BigAl_NBA4_FinalHomeFavRevenge": (is_nba, ["Is_Regular_Season", "Is_Final_Home_Game", "Is_Home", "Spread_Value", "Revenge_Flag_Current"]),
        "BigAl_NBA5_PlayoffBigDogVsChamp": (is_nba, ["Is_Postseason", "WinPct_Prior_System", "Is_Home", "Spread_Value", "Opponent_Is_Defending_Champion"]),
        "BigAl_NBA6_FinalsGame4": (is_nba, ["Is_Finals", "Series_Game_Number", "Team_Series_Wins", "Opp_Series_Wins", "Is_Home", "Prev_SU_Win", "Prev_Is_Home", "WinPct_Prior_System", "Spread_Value"]),
        "BigAl_NBA7_TwoTeamEliminationUnder": (is_nba, ["Team_Eliminated_With_Loss", "Opponent_Eliminated_With_Loss"]),
        "BigAl_NBA8_Revenge145FadeFavorite": (is_nba, ["Spread_Value", "Season_H2H_Last_SU_Win_Prior", "Season_H2H_Last_Points_Against_Prior"]),
        "BigAl_CBB1_UglyDog20Losses": (is_ncaab, ["Spread_Value", "Prev_SU_Margin", "Prev_ATS_Cover_Margin", "Prev2_SU_Margin", "Prev2_ATS_Cover_Margin", "Opp_Prev_SU_Loss", "Opp_Prev2_SU_Loss"]),
        "BigAl_CBB2_Fade10WinStreakFavorite": (is_ncaab, ["Is_Regular_Season", "Spread_Value", "Opp_Prev_SU_Loss", "Opp_SU_Win_Streak_Entering_Previous_Game", "Prev_SU_Win", "Prev_ATS_Win"]),
        "BigAl_CBB3_HomeRevenge27": (is_ncaab, ["Is_Regular_Season", "Is_Home", "WinPct_Prior_System", "H2H_Last_Loss_Margin"]),
        "BigAl_CFL1_SecondMeetingUnder": (is_cfl, ["Season_H2H_Meeting_Number", "First_Meeting_Actual_Total_Prior"]),
        "BigAl_CFL2_EliteDogFade": (is_cfl, ["Opp_Team_Game_Number", "Opp_WinPct_Prior_System", "Opp_Spread_Value"]),
        "BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo": (is_cfl, ["Season_H2H_Meeting_Number", "Is_Home", "Spread_Value", "Season_H2H_Consecutive_Losses_Prior"]),
    }
    for _name, (_sport_mask, _reqs) in _bigal_specs.items():
        s[_name + "_DataReady"] = (_sport_mask & ready(*_reqs)).astype("int8")
    s["BigAl_NFL1_Week1FadePlayoffTeam_DataReady"] = (
        is_nfl & ready("Is_Regular_Season", "Team_Prior_Season_Playoff", "Opponent_Prior_Season_Playoff") &
        (n("Week_Number").notna() | n("Team_Game_Number").notna())
    ).astype("int8")

    def _set_bigal_match(name, sport_mask, conditions):
        dr = pd.to_numeric(s.get(name + "_DataReady"), errors="coerce").fillna(0).eq(1)
        vals = []
        for cond in conditions:
            vals.append(pd.Series(cond, index=s.index).astype(float))
        ratio = pd.concat(vals, axis=1).mean(axis=1) if vals else pd.Series(np.nan, index=s.index)
        s[name + "_Match_Ratio"] = ratio.where(sport_mask & dr, np.nan).astype("float32")

    _set_bigal_match("BigAl_NFL1_Week1FadePlayoffTeam", is_nfl, [
        n("Is_Regular_Season").eq(1), _nfl_week1,
        n("Team_Prior_Season_Playoff").eq(0), n("Opponent_Prior_Season_Playoff").eq(1),
    ])
    _set_bigal_match("BigAl_NFL2_LateSeasonHomeDog", is_nfl, [
        n("Final_Two_Regular_Season").eq(1), n("Is_Home").eq(1), n("Spread_Value").gt(0),
        n("SU_Loss_Streak_Prior").ge(2), n("Opp_WinPct_Prior_System").le(0.500),
    ])
    _set_bigal_match("BigAl_NFL3_PlayoffHighScoreFade", is_nfl, [
        n("Is_Postseason").eq(1), n("Opp_Is_Home").eq(0), n("Opp_Prev_SU_Win").eq(1),
        n("Opp_Prev_Points_For").ge(35), n("Prev_Points_For").lt(35),
    ])
    _set_bigal_match("BigAl_NFL4_PreseasonContrarianMove", is_nfl, [
        n("Is_Preseason").eq(1), (n("Spread_Value") - n("Opening_Spread")).ge(1.5),
    ])
    _set_bigal_match("BigAl_NFL5_PreseasonLowOffenseOver", is_nfl, [
        n("Is_Preseason").eq(1), low_pair,
    ])
    _set_bigal_match("BigAl_CF1_Week2Home42Win", is_ncaaf, [
        n("Team_Game_Number").eq(2), n("Is_Home").eq(1), n("Prev_SU_Win").eq(1),
        n("Prev_Points_For").gt(42), n("Is_Conference_Game").eq(0), n(_cf1_opp_revenge_field).eq(0),
    ])
    _set_bigal_match("BigAl_CF2_LateSeasonRevengeDog", is_ncaaf, [
        n("Is_Regular_Season").eq(1), n("Team_Game_Number").ge(9), n("Revenge_Flag_Current").eq(1),
        n("Spread_Value").gt(0), n("Prev_Points_For").gt(50),
    ])
    _set_bigal_match("BigAl_CF3_Fade19PlusFavoriteUpsetLoss", is_ncaaf, [
        n("Is_Regular_Season").eq(1), n("Opp_Prev_Spread_Value").le(-19.0), n("Opp_Prev_SU_Loss").eq(1),
    ])
    _set_bigal_match("BigAl_NBA1_B2BRematchRoadDog", is_nba, [
        n("Is_Regular_Season").eq(1), n("Immediate_Rematch_Flag").eq(1), n("Is_Home").eq(0),
        n("Spread_Value").ge(10), n("Prev_SU_Loss").eq(1), n("Prev_ATS_Loss").eq(1),
    ])
    _set_bigal_match("BigAl_NBA2_ThreeMassiveCovers", is_nba, [
        n("Is_Home").eq(1), n("Prev_ATS_Cover_Margin").ge(16),
        n("Prev2_ATS_Cover_Margin").ge(16), n("Prev3_ATS_Cover_Margin").ge(16),
    ])
    _set_bigal_match("BigAl_NBA3_FadeHomeAfterChampUpset", is_nba, [
        n("Opp_Is_Home").eq(1), n("Opp_Prev_SU_Win").eq(1),
        n("Opp_Prev_Is_Road_Dog_9Plus").eq(1), n("Opp_Prev_Opponent_Is_Defending_Champion").eq(1),
    ])
    _set_bigal_match("BigAl_NBA4_FinalHomeFavRevenge", is_nba, [
        n("Is_Regular_Season").eq(1), n("Is_Final_Home_Game").eq(1), n("Is_Home").eq(1),
        n("Spread_Value").lt(-5), n("Revenge_Flag_Current").eq(1),
    ])
    _set_bigal_match("BigAl_NBA5_PlayoffBigDogVsChamp", is_nba, [
        n("Is_Postseason").eq(1), n("WinPct_Prior_System").gt(0.5), n("Is_Home").eq(0),
        n("Spread_Value").gt(10), n("Opponent_Is_Defending_Champion").eq(1),
    ])
    _set_bigal_match("BigAl_NBA6_FinalsGame4", is_nba, [
        n("Is_Finals").eq(1), n("Series_Game_Number").eq(4), n("Is_Home").eq(0),
        n("Team_Series_Wins").eq(1), n("Opp_Series_Wins").eq(2), n("Prev_SU_Win").eq(1),
        n("Prev_Is_Home").eq(0), n("WinPct_Prior_System").ge(0.625), n("Spread_Value").ge(-4),
    ])
    _set_bigal_match("BigAl_NBA7_TwoTeamEliminationUnder", is_nba, [
        n("Team_Eliminated_With_Loss").eq(1), n("Opponent_Eliminated_With_Loss").eq(1),
    ])
    _set_bigal_match("BigAl_NBA8_Revenge145FadeFavorite", is_nba, [
        _regular_only, n("Spread_Value").ge(0),
        n("Season_H2H_Last_SU_Win_Prior").lt(0.5),
        n("Season_H2H_Last_Points_Against_Prior").ge(145),
    ])
    _set_bigal_match("BigAl_CBB1_UglyDog20Losses", is_ncaab, [
        n("Spread_Value").ge(0), n("Prev_SU_Margin").lt(-20), n("Prev_ATS_Cover_Margin").lt(-20),
        n("Prev2_SU_Margin").lt(-20), n("Prev2_ATS_Cover_Margin").lt(-20),
        ~(n("Opp_Prev_SU_Loss").eq(1) & n("Opp_Prev2_SU_Loss").eq(1)),
    ])
    _set_bigal_match("BigAl_CBB2_Fade10WinStreakFavorite", is_ncaab, [
        n("Is_Regular_Season").eq(1), n("Spread_Value").ge(6), n("Opp_Prev_SU_Loss").eq(1),
        n("Opp_SU_Win_Streak_Entering_Previous_Game").ge(10),
        ~(n("Prev_SU_Win").eq(1) & n("Prev_ATS_Win").eq(1)),
    ])
    _set_bigal_match("BigAl_CBB3_HomeRevenge27", is_ncaab, [
        n("Is_Regular_Season").eq(1), n("Is_Home").eq(1), n("WinPct_Prior_System").gt(0.500),
        n("H2H_Last_Loss_Margin").le(-27),
    ])
    _set_bigal_match("BigAl_CFL1_SecondMeetingUnder", is_cfl, [
        n("Season_H2H_Meeting_Number").eq(2), n("First_Meeting_Actual_Total_Prior").ge(63),
    ])
    _set_bigal_match("BigAl_CFL2_EliteDogFade", is_cfl, [
        n("Opp_Team_Game_Number").ge(7), n("Opp_WinPct_Prior_System").ge(0.820), n("Opp_Spread_Value").gt(3),
    ])
    _set_bigal_match("BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo", is_cfl, [
        _regular_only, n("Season_H2H_Meeting_Number").eq(3), n("Is_Home").eq(0),
        n("Spread_Value").gt(0), n("Season_H2H_Consecutive_Losses_Prior").ge(2),
    ])

    # Signed total-system direction for the canonical Over training row:
    # +1 = Big Al says OVER; -1 = Big Al says UNDER.
    # Regular-season-only total direction. Preseason/postseason systems are
    # deliberately excluded so retired context cannot leak into new artifacts.
    s["BigAl_Total_System_Signed"] = (
        -s["BigAl_CFL1_SecondMeetingUnder"].astype(float)
    ).astype("float32")

    # ------------------------------------------------------------------
    # Big Al DB-supported ENHANCERS.
    #
    # SYSTEM     = exact published/recoverable mechanical formula.
    # TIGHTENER  = explicit published additional condition.
    # ENHANCER   = a broader, DB-computable ingredient/proxy supported by
    #              Big Al's disclosed handicapping logic.  Enhancers NEVER
    #              increment BigAl_System_Count/System_Signal_Count.
    #
    # No preseason/postseason enhancer is permitted here.
    # ------------------------------------------------------------------

    # MLB ALL Access proxy: recent team form materially better than season form.
    # The source discussion used pitcher ERA/venue history, which we do not have.
    # This therefore captures only the database-supported recent-vs-season idea.
    _mlb_recent_delta = n("BigAl_MLB_Recent_vs_Season_WinPct_Delta")
    s["BigAl_MLB_Enhancer_RecentFormAboveSeason"] = (
        is_mlb & _regular_only
        & _mlb_recent_delta.notna()
        & _mlb_recent_delta.gt(0)
    ).astype("int8")
    s["BigAl_MLB_Enhancer_RecentFormFavorite"] = (
        s["BigAl_MLB_Enhancer_RecentFormAboveSeason"].eq(1)
        & n("Is_ML_Favorite").eq(1)
    ).astype("int8")

    # Ingredient-level enhancers behind existing exact Big Al systems.
    # They let AutoFS learn whether the broader situation has value even when
    # every exact system condition is not present.
    s["BigAl_NFL_Enhancer_LateHomeDog"] = (
        is_nfl & _regular_only
        & n("Final_Two_Regular_Season").eq(1)
        & n("Is_Home").eq(1)
        & n("Spread_Value").gt(0)
    ).astype("int8")

    # Published 12/26/2022 database ingredient: next-to-last regular-season week,
    # very poor team (<= .250 prior SU win pct) off a SU win.  Exact week metadata
    # is required; do not approximate this with team-game number.
    _nfl_penultimate_exact = (
        n("Week_Number").notna()
        & n("Regular_Season_Final_Week").notna()
        & n("Week_Number").eq(n("Regular_Season_Final_Week") - 1)
    )
    s["BigAl_NFL_Enhancer_PenultimateBadTeamOffWin"] = (
        is_nfl & _regular_only & _nfl_penultimate_exact
        & n("WinPct_Prior_System").le(0.250)
        & n("Prev_SU_Win").eq(1)
    ).astype("int8")

    s["BigAl_CF_Enhancer_RevengeDog"] = (
        is_ncaaf & _regular_only
        & n("Revenge_Flag_Current").eq(1)
        & n("Spread_Value").gt(0)
    ).astype("int8")

    s["BigAl_NBA_Enhancer_ImmediateRematchDog"] = (
        is_nba & _regular_only
        & n("Immediate_Rematch_Flag").eq(1)
        & n("Spread_Value").gt(0)
    ).astype("int8")

    s["BigAl_CBB_Enhancer_HomeRevengeWinning"] = (
        is_ncaab & _regular_only
        & n("Is_Home").eq(1)
        & n("Revenge_Flag_Current").eq(1)
        & n("WinPct_Prior_System").gt(0.500)
    ).astype("int8")

    # WNBA public-selection disclosure (8/19/26): winning home teams in
    # double-revenge; the home-underdog form was the stronger subset.
    s["BigAl_WNBA_Enhancer_WinningHomeDoubleRevenge"] = (
        is_wnba & _regular_only & n("Is_Home").eq(1) &
        n("WinPct_Prior_System").gt(0.500) &
        n("Season_H2H_Consecutive_Losses_Prior").ge(2)
    ).astype("int8")
    s["BigAl_WNBA_Enhancer_WinningHomeDoubleRevengeDog"] = (
        s["BigAl_WNBA_Enhancer_WinningHomeDoubleRevenge"].eq(1) & n("Spread_Value").gt(0)
    ).astype("int8")

    # CFL public-selection disclosure (8/20/26): winless revenge-minded
    # teams were strongest as underdogs of +9 or more.
    s["BigAl_CFL_Enhancer_WinlessRevengeBigDog"] = (
        is_cfl & _regular_only & n("WinPct_Prior_System").eq(0) &
        n("Revenge_Flag_Current").eq(1) & n("Spread_Value").ge(9)
    ).astype("int8")

    _bigal_enhancer_flags = [c for c in BIGAL_ENHANCER_COLS if c in s.columns]
    s["BigAl_Enhancer_Count"] = flag_sum(_bigal_enhancer_flags, "int16")
    s["BigAl_Enhancer_Active"] = (pd.to_numeric(s["BigAl_Enhancer_Count"], errors="coerce").fillna(0) > 0).astype("int8")

    # ------------------------------------------------------------------
    # Aggregate counts + human-readable audit string.
    # ------------------------------------------------------------------
    pathi_signal_cols = [c for c in PATHI_EXACT_SIGNAL_COLS if c in s.columns]
    bigal_base_cols = [
        "BigAl_NFL1_Week1FadePlayoffTeam", "BigAl_NFL2_LateSeasonHomeDog", "BigAl_NFL3_PlayoffHighScoreFade",
        "BigAl_NFL4_PreseasonContrarianMove", "BigAl_NFL5_PreseasonLowOffenseOver",
        "BigAl_CF1_Week2Home42Win", "BigAl_CF2_LateSeasonRevengeDog", "BigAl_CF3_Fade19PlusFavoriteUpsetLoss",
        "BigAl_NBA1_B2BRematchRoadDog", "BigAl_NBA2_ThreeMassiveCovers", "BigAl_NBA3_FadeHomeAfterChampUpset",
        "BigAl_NBA4_FinalHomeFavRevenge", "BigAl_NBA5_PlayoffBigDogVsChamp", "BigAl_NBA6_FinalsGame4",
        "BigAl_NBA7_TwoTeamEliminationUnder", "BigAl_NBA8_Revenge145FadeFavorite", "BigAl_CBB1_UglyDog20Losses",
        "BigAl_CBB2_Fade10WinStreakFavorite", "BigAl_CBB3_HomeRevenge27",
        "BigAl_CFL1_SecondMeetingUnder", "BigAl_CFL2_EliteDogFade",
        "BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo",
    ]
    bigal_base_cols = [c for c in bigal_base_cols if not _is_retired_bigal_feature_name(c)]
    tight_cols = [
        c for c in s.columns
        if c.startswith("BigAl_")
        and c.endswith("_Tightener")
        and not _is_retired_bigal_feature_name(c)
    ]
    s["Pathi_System_Count"] = flag_sum(pathi_signal_cols, "int16")
    s["BigAl_System_Count"] = flag_sum(bigal_base_cols, "int16")
    s["BigAl_Tightener_Count"] = flag_sum(tight_cols, "int16")
    s["System_Signal_Count"] = flag_sum(
        ["Pathi_System_Count", "BigAl_System_Count", "BigAl_Tightener_Count"], "int16"
    )
    # BigAl_Enhancer_Count is intentionally excluded: enhancer != exact system signal.

    # Regular-season Big Al market family indicators.  Aggregate features are
    # intentionally not duplicates of the component systems; they identify the
    # active recommendation family for the learned/meta layers.
    _ba_total_base_names = [c for c in ["BigAl_CFL1_SecondMeetingUnder"] if c in s.columns]
    _ba_spread_base_names = [c for c in bigal_base_cols if c not in _ba_total_base_names and c in s.columns]
    _ba_total_tight_names = [c for c in tight_cols if c.startswith("BigAl_CFL1_")]
    _ba_spread_tight_names = [c for c in tight_cols if c not in _ba_total_tight_names]
    s["BigAl_Spread_System_Count"] = flag_sum(_ba_spread_base_names, "int16")
    s["BigAl_Total_System_Count"] = flag_sum(_ba_total_base_names, "int16")
    s["BigAl_Spread_Tightener_Count"] = flag_sum(_ba_spread_tight_names, "int16")
    s["BigAl_Total_Tightener_Count"] = flag_sum(_ba_total_tight_names, "int16")
    s["BigAl_Spread_Active"] = (s["BigAl_Spread_System_Count"] > 0).astype("int8")
    s["BigAl_Total_Active"] = (s["BigAl_Total_System_Count"] > 0).astype("int8")
    _ba_signed_state = pd.to_numeric(s.get("BigAl_Total_System_Signed"), errors="coerce").fillna(0)
    s["BigAl_Total_Over_Active"] = (_ba_signed_state > 0).astype("int8")
    s["BigAl_Total_Under_Active"] = (_ba_signed_state < 0).astype("int8")

    label_map = {
        "Pathi_M1_DogThatWon": "PATHI M1 Dog That Won",
        "Pathi_M8_DogWon_BetterPrice": "PATHI M8 Better Price",
        "Pathi_M2_HomeDog": "PATHI M2 Home Dog",
        "Pathi_M3_Rule10_LosingStreak": "PATHI M3 Rule of 10",
        "Pathi_M3_Rule10_PlusMoney": "PATHI M3 +Money",
        "Pathi_M4_ExtendedWinStreakFade": "PATHI M4 Fade Hot Favorite",
        "Pathi_M5_TravelOffDayFreeze": "PATHI M5 Off-Day Freeze",
        "Pathi_M6_WeakTeamNewChalk_Screen": "PATHI M6 New Chalk Screen",
        "Pathi_M7_BadRoadFavoriteProfile": "PATHI M7 Bad Road Favorite",
        "Pathi_M9_Plus15_PlusMoney": "PATHI M9 +1.5 Plus Money",
        "Pathi_RoleFlip_DogToFavorite_Cancel": "PATHI CANCEL: Dog->Favorite",
        "BigAl_NFL1_Week1FadePlayoffTeam": "BIG AL NFL1 Week 1 Fade",
        "BigAl_NFL1_HomeTightener": "BIG AL NFL1 Home Tightener",
        "BigAl_NFL2_LateSeasonHomeDog": "BIG AL NFL2 Late Home Dog",
        "BigAl_NFL2_OppOffATSLoss_Tightener": "BIG AL NFL2 Tightener",
        "BigAl_NFL3_PlayoffHighScoreFade": "BIG AL NFL3 Playoff Fade",
        "BigAl_NFL4_PreseasonContrarianMove": "BIG AL NFL4 Preseason RLM",
        "BigAl_NFL5_PreseasonLowOffenseOver": "BIG AL NFL5 OVER",
        "BigAl_CF1_Week2Home42Win": "BIG AL CF1 Week 2",
        "BigAl_CF2_LateSeasonRevengeDog": "BIG AL CF2 Revenge Dog",
        "BigAl_CF3_Fade19PlusFavoriteUpsetLoss": "BIG AL CF3 Fade 19+ Fav Upset Loss",
        "BigAl_NBA1_B2BRematchRoadDog": "BIG AL NBA1 Rematch Dog",
        "BigAl_NBA1_PriorLoss25_Tightener": "BIG AL NBA1 25+ Tightener",
        "BigAl_NBA2_ThreeMassiveCovers": "BIG AL NBA2 3 Massive Covers",
        "BigAl_NBA3_FadeHomeAfterChampUpset": "BIG AL NBA3 Champ-Upset Fade",
        "BigAl_NBA4_FinalHomeFavRevenge": "BIG AL NBA4 Final Home Revenge",
        "BigAl_NBA5_PlayoffBigDogVsChamp": "BIG AL NBA5 Playoff Big Dog",
        "BigAl_NBA6_FinalsGame4": "BIG AL NBA6 Finals G4",
        "BigAl_NBA7_TwoTeamEliminationUnder": "BIG AL NBA7 UNDER",
        "BigAl_NBA8_Revenge145FadeFavorite": "BIG AL NBA8 Revenge 145+ Fade",
        "BigAl_NBA8_WinningRecord_Tightener": "BIG AL NBA8 Winning Record Tightener",
        "BigAl_CBB1_UglyDog20Losses": "BIG AL CBB1 Ugly Dog",
        "BigAl_CBB1_ThreeLoss_Tightener": "BIG AL CBB1 3-Loss Tightener",
        "BigAl_CBB2_Fade10WinStreakFavorite": "BIG AL CBB2 Fade 10-Win-Streak Favorite",
        "BigAl_CBB3_HomeRevenge27": "BIG AL CBB3 Home Revenge 27+",
        "BigAl_CBB3_DogOffLoss_Tightener": "BIG AL CBB3 Dog + Off Loss Tightener",
        "BigAl_CFL1_SecondMeetingUnder": "BIG AL CFL1 UNDER",
        "BigAl_CFL1_TotalAbove51_Tightener": "BIG AL CFL1 >51 Tightener",
        "BigAl_CFL2_EliteDogFade": "BIG AL CFL2 Fade Elite Dog",
        "BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo": "BIG AL CFL3 3rd Meeting Road Dog",
    }

    label_map = {k: v for k, v in label_map.items() if not _is_retired_bigal_feature_name(k)}

    def _labels(row):
        parts = [label for col, label in label_map.items() if col in row.index and pd.to_numeric(row[col], errors="coerce") == 1]
        return " | ".join(parts) if parts else "—"

    s["System_Signals_Text"] = s.apply(_labels, axis=1)
    # Per-game side-system convergence. A flag on this team is support; a flag on
    # the opponent is conflict. Tighteners/DataReady/total-only rules are excluded.
    side_flags = [c for c in (
        [x for x in pathi_signal_cols if x != "Pathi_RoadFavLost_StillFavorite_Screen"] +
        [x for x in bigal_base_cols if x not in {"BigAl_NFL5_PreseasonLowOffenseOver", "BigAl_NBA7_TwoTeamEliminationUnder", "BigAl_CFL1_SecondMeetingUnder"}]
    ) if c in s.columns]
    if side_flags:
        own=(s[side_flags].fillna(0)>0).sum(axis=1).astype(float)
        s["System_Side_Consensus_Count"]=own
        oppmap=s[["Sport","Game_Key","Team"]].copy(); oppmap["__opp_support"]=own.to_numpy()
        oppmap=oppmap.rename(columns={"Team":"Opponent"})
        tmp=s[["Sport","Game_Key","Opponent"]].merge(oppmap,on=["Sport","Game_Key","Opponent"],how="left")
        conflict=pd.to_numeric(tmp["__opp_support"],errors="coerce").fillna(0).to_numpy()
        s["System_Side_Conflict_Count"]=conflict
        s["System_Net_Signal"]=own.to_numpy()-conflict
        denom=own.to_numpy()+conflict
        _ratio=np.full(len(denom),np.nan,dtype=float)
        np.divide(own.to_numpy(dtype=float),denom,out=_ratio,where=np.asarray(denom)>0)
        s["System_Consensus_Ratio"]=_ratio
    else:
        for c in ("System_Side_Consensus_Count","System_Side_Conflict_Count","System_Net_Signal","System_Consensus_Ratio"):
            s[c]=0.0

    # Big-Al-only convergence, kept separate from Pathi so the meta/situation head
    # can learn whether Big Al is agreeing with or opposing the selected side.
    _bigal_side_bases = [
        c for c in bigal_base_cols
        if c not in {"BigAl_NFL5_PreseasonLowOffenseOver", "BigAl_NBA7_TwoTeamEliminationUnder", "BigAl_CFL1_SecondMeetingUnder"}
        and c in s.columns
    ]
    if _bigal_side_bases:
        _ba_own = (s[_bigal_side_bases].fillna(0) > 0).sum(axis=1).astype(float)
        _ba_map = s[["Sport", "Game_Key", "Team"]].copy()
        _ba_map["__bigal_opp_support"] = _ba_own.to_numpy()
        _ba_map = _ba_map.rename(columns={"Team": "Opponent"})
        _ba_tmp = s[["Sport", "Game_Key", "Opponent"]].merge(
            _ba_map, on=["Sport", "Game_Key", "Opponent"], how="left"
        )
        _ba_conflict = pd.to_numeric(_ba_tmp["__bigal_opp_support"], errors="coerce").fillna(0).to_numpy()
        s["BigAl_Side_Support_Count"] = _ba_own
        s["BigAl_Side_Conflict_Count"] = _ba_conflict
        s["BigAl_Side_Net_Signal"] = _ba_own.to_numpy() - _ba_conflict
        _ba_num = _ba_own.to_numpy(dtype=float, copy=False)
        _ba_den = _ba_num + np.asarray(_ba_conflict, dtype=float)
        _ba_ratio = np.full(len(_ba_den), np.nan, dtype=float)
        # np.where evaluates both branches first, so x / 0 still emitted RuntimeWarning.
        # np.divide(where=...) genuinely skips zero-denominator divisions.
        np.divide(_ba_num, _ba_den, out=_ba_ratio, where=np.isfinite(_ba_den) & (_ba_den > 0))
        s["BigAl_Side_Consensus_Ratio"] = _ba_ratio
    else:
        for _c in ("BigAl_Side_Support_Count", "BigAl_Side_Conflict_Count", "BigAl_Side_Net_Signal", "BigAl_Side_Consensus_Ratio"):
            s[_c] = 0.0


    # ------------------------------------------------------------------
    # Living system reliability / decay (prior-only).
    # This evaluates the historical performance of rows where at least one
    # named Pathi/Big Al SIDE system supported the selected team.  H2H uses
    # SU outcome; spreads use ATS outcome.  Current/upcoming rows have no
    # result, so they inherit the state accumulated strictly before them.
    # ------------------------------------------------------------------
    _rel_cols = [
        "System_Reliability_Sample_Prior",
        "System_Reliability_LongTerm_HitRate_Prior",
        "System_Reliability_Recent50_HitRate_Prior",
        "System_Reliability_RecentVsLongTerm_Delta",
        "System_Reliability_Shrunk_HitRate_Prior",
        "System_Reliability_Stability_Score",
        "System_Reliability_GE25",
        "System_Reliability_GE50",
        "System_Reliability_GE100",
    ]
    for _c in _rel_cols:
        s[_c] = np.nan
    try:
        _mrel = s.get("Market", pd.Series("", index=s.index)).astype(str).map(_sys_norm_market)
        _su = pd.to_numeric(s.get("SU_Win", np.nan), errors="coerce")
        _ats = pd.to_numeric(s.get("ATS_Win", np.nan), errors="coerce")
        _target = pd.Series(np.nan, index=s.index, dtype="float64")
        _target.loc[_mrel.eq("h2h")] = _su.loc[_mrel.eq("h2h")]
        _target.loc[_mrel.eq("spreads")] = _ats.loc[_mrel.eq("spreads")]
        _active = pd.to_numeric(s.get("System_Side_Consensus_Count", 0), errors="coerce").fillna(0).gt(0)
        _tsrel = pd.to_datetime(s.get("Game_Start"), errors="coerce", utc=True)
        _rel = pd.DataFrame({
            "__idx": np.arange(len(s), dtype=np.int64),
            "Sport": s.get("Sport", "").astype(str).str.upper().str.strip(),
            "Market": _mrel,
            "Game_Start": _tsrel,
            "Target": _target,
            "Active": _active,
        }).sort_values(["Sport", "Market", "Game_Start", "__idx"], kind="mergesort")
        _out = {c: np.full(len(s), np.nan, dtype=np.float64) for c in _rel_cols}
        for (_sp, _mk), _g in _rel.groupby(["Sport", "Market"], sort=False, observed=True):
            _hist = []
            for _i, _tgt, _act in _g[["__idx", "Target", "Active"]].itertuples(index=False, name=None):
                _i = int(_i)
                _n = len(_hist)
                _long = float(np.mean(_hist)) if _n else np.nan
                _recent = float(np.mean(_hist[-50:])) if _n else np.nan
                # Beta(25,25) shrinkage toward 50%; small samples cannot look extreme.
                _wins = float(np.sum(_hist)) if _n else 0.0
                _shr = (_wins + 25.0) / (_n + 50.0)
                _stab = (1.0 - min(1.0, abs(_recent - _long) / 0.20)) if (_n and np.isfinite(_recent) and np.isfinite(_long)) else np.nan
                _out["System_Reliability_Sample_Prior"][_i] = float(_n)
                _out["System_Reliability_LongTerm_HitRate_Prior"][_i] = _long
                _out["System_Reliability_Recent50_HitRate_Prior"][_i] = _recent
                _out["System_Reliability_RecentVsLongTerm_Delta"][_i] = (_recent - _long) if (_n and np.isfinite(_recent) and np.isfinite(_long)) else np.nan
                _out["System_Reliability_Shrunk_HitRate_Prior"][_i] = _shr
                _out["System_Reliability_Stability_Score"][_i] = _stab
                _out["System_Reliability_GE25"][_i] = float(_n >= 25)
                _out["System_Reliability_GE50"][_i] = float(_n >= 50)
                _out["System_Reliability_GE100"][_i] = float(_n >= 100)
                if bool(_act) and np.isfinite(_tgt):
                    _hist.append(float(_tgt))
        for _c, _arr in _out.items():
            s[_c] = pd.Series(_arr, index=s.index, dtype="float32")
        for _c in ("System_Reliability_GE25", "System_Reliability_GE50", "System_Reliability_GE100"):
            s[_c] = pd.to_numeric(s[_c], errors="coerce").fillna(0).astype("int8")
    except Exception:
        # Feature engineering is fail-open; legacy system features remain usable.
        for _c in _rel_cols:
            if _c not in s.columns:
                s[_c] = np.nan

    return s




def attach_pathi_bigal_features_to_market_rows(df_rows: pd.DataFrame, state: pd.DataFrame) -> pd.DataFrame:
    """Broadcast team/game Pathi-BigAl state to book/outcome rows without row growth."""
    if df_rows is None or df_rows.empty:
        return df_rows.copy()
    if state is None or state.empty:
        return add_pathi_football_key_features(df_rows.copy())
    out = df_rows.copy()
    out["Sport"] = out.get("Sport", "").astype(str).str.upper().str.strip()
    out["Game_Key"] = out["Game_Key"].astype(str).str.lower().str.strip()
    out["Market"] = out["Market"].astype(str).map(_sys_norm_market)
    out["Outcome_Norm"] = out.get("Outcome", "").astype(str).str.lower().str.strip()
    out["Home_Team_Norm"] = out.get("Home_Team_Norm", out.get("Home_Team", "")).astype(str).str.lower().str.strip()
    out["Away_Team_Norm"] = out.get("Away_Team_Norm", out.get("Away_Team", "")).astype(str).str.lower().str.strip()
    is_tot = out["Market"].eq("totals")
    out["Team"] = np.where(
        is_tot,
        out["Home_Team_Norm"],
        np.where(out["Outcome_Norm"].eq("home"), out["Home_Team_Norm"],
                 np.where(out["Outcome_Norm"].eq("away"), out["Away_Team_Norm"], out["Outcome_Norm"]))
    )
    out["Team"] = pd.Series(out["Team"], index=out.index).astype(str).str.lower().str.strip()

    keep = ["Sport", "Game_Key", "Team"] + [
        c for c in state.columns
        if c not in {"Sport", "Game_Key", "Team", "Opponent", "Game_Start", "Home_Team_Norm", "Away_Team_Norm"}
        and (c.startswith("Pathi_") or c.startswith("BigAl_") or c.startswith("System_") or c in {
            "ML_Odds", "Opening_ML_Odds", "ML_Fair_Prob", "Opening_ML_Fair_Prob",
            "Is_ML_Dog", "Is_ML_Favorite", "Opening_Is_ML_Dog",
            "Spread_Value", "Opening_Spread", "Spread_Odds", "Current_Total", "Opening_Total",
            "SU_Win_Streak_Prior", "SU_Loss_Streak_Prior", "ATS_Win_Streak_Prior", "ATS_Loss_Streak_Prior",
            "WinPct_Prior_System", "Team_Game_Number", "Immediate_Rematch_Flag", "Season_H2H_Meeting_Number",
            "First_Meeting_Actual_Total_Prior", "Dog_Rate_Last10_Prior", "Road_Favorite_ROI_Prior",
            "Revenge_Flag_Current",
            "Days_Since_Last_Game_System", "Opp_Days_Since_Last_Game_System",
            "Games_Last_2_Days_System", "Opp_Games_Last_2_Days_System",
            "Games_Last_4_Days_System", "Opp_Games_Last_4_Days_System",
            "Games_Last_7_Days_System", "Opp_Games_Last_7_Days_System",
            "Is_B2B_System", "Opp_Is_B2B_System",
            "Is_3in4_System", "Opp_Is_3in4_System",
            "Had_Bye_Last_Game_System", "Opp_Had_Bye_Last_Game_System",
            "Opp_BigAl_Context_Had_Bye_Proxy",
            *PATHI_BIGAL_ADDITIONAL_MODEL_FEATURES,
        })
    ]
    stmap = state[keep].drop_duplicates(["Sport", "Game_Key", "Team"], keep="last")

    # The training view can already contain older Pathi/BigAl/System columns.
    # Never let pandas create stale *_x/*_y copies: the freshly rebuilt state above
    # is the canonical leakage-safe version (all historical result state is shifted/prior-only).
    _join_keys = {"Sport", "Game_Key", "Team"}
    _state_payload = [c for c in stmap.columns if c not in _join_keys]
    _overlap_payload = [c for c in _state_payload if c in out.columns]
    if _overlap_payload:
        out.drop(columns=_overlap_payload, inplace=True, errors="ignore")

    before = len(out)
    out = out.merge(stmap, on=["Sport", "Game_Key", "Team"], how="left", validate="many_to_one")
    if len(out) != before:
        raise RuntimeError(f"Pathi/BigAl merge changed row count {before} -> {len(out)}")

    # V11.5.4 schedule robustness: remap the opponent's canonical physical
    # team-game schedule state directly from STATE rather than relying only on
    # pre-mirrored Opp_* payloads.  This survives one-sided market slices and
    # prevents missing opponent state from being silently interpreted as zero.
    _sched_src_cols = [
        "Days_Since_Last_Game_System",
        "Games_Last_2_Days_System", "Games_Last_4_Days_System", "Games_Last_7_Days_System",
        "Is_B2B_System", "Is_3in4_System", "Had_Bye_Last_Game_System",
    ]
    _sched_src_cols = [c for c in _sched_src_cols if c in state.columns]
    if _sched_src_cols:
        _opp_sched = (
            state[["Sport", "Game_Key", "Team"] + _sched_src_cols]
            .drop_duplicates(["Sport", "Game_Key", "Team"], keep="last")
            .rename(columns={
                "Team": "__Schedule_Opponent",
                **{c: f"__opp_sched__{c}" for c in _sched_src_cols},
            })
        )
        _team_now = out["Team"].astype(str).str.lower().str.strip()
        _home_now = out["Home_Team_Norm"].astype(str).str.lower().str.strip()
        _away_now = out["Away_Team_Norm"].astype(str).str.lower().str.strip()
        out["__Schedule_Opponent"] = np.where(_team_now.eq(_home_now), _away_now, _home_now)
        _before_sched = len(out)
        out = out.merge(
            _opp_sched,
            on=["Sport", "Game_Key", "__Schedule_Opponent"],
            how="left",
            validate="many_to_one",
        )
        if len(out) != _before_sched:
            raise RuntimeError(
                f"Opponent schedule merge changed row count {_before_sched} -> {len(out)}"
            )
        for _c in _sched_src_cols:
            _dst = f"Opp_{_c}"
            _tmp = f"__opp_sched__{_c}"
            _newv = pd.to_numeric(out.get(_tmp), errors="coerce")
            if _dst in out.columns:
                _oldv = pd.to_numeric(out[_dst], errors="coerce")
                out[_dst] = _oldv.combine_first(_newv)
            else:
                out[_dst] = _newv
        out.drop(
            columns=["__Schedule_Opponent"] + [f"__opp_sched__{c}" for c in _sched_src_cols],
            inplace=True,
            errors="ignore",
        )

    # Keep each named system on the market it actually recommends. This avoids,
    # for example, feeding an MLB moneyline system into the run-line model or
    # displaying an UNDER system on a side row.
    _m = out["Market"].astype(str).map(_sys_norm_market)

    # Spread-role context is meaningful only for spread rows.  Generic
    # conference/division/week fields remain available to every market.
    _bigal_spread_context = [
        "BigAl_Context_Conference_Dog",
        "BigAl_Context_Conference_Favorite",
        "BigAl_Context_Conference_Pickem",
        "BigAl_Context_Conference_Home_Dog",
        "BigAl_Context_Conference_Home_Favorite",
        "BigAl_Context_Division_Dog",
        "BigAl_Context_Division_Favorite",
        "BigAl_Context_Division_Home_Dog",
        "BigAl_Context_Division_Home_Favorite",
        "BigAl_Context_NonConference_Dog",
        "BigAl_Context_NonConference_Favorite",
        "BigAl_Hoops_Revenge_Context_Active",
        "BigAl_Hoops_Revenge_LastMeeting_LossMargin",
        "BigAl_Hoops_Revenge_LastMeeting_Spread",
        "BigAl_Hoops_Revenge_LastMeeting_PointsAllowed",
        "BigAl_Hoops_Revenge_DaysSinceLastMeeting",
        "BigAl_Hoops_Revenge_WinPctGap_Prior",
        "BigAl_Hoops_Revenge_LastMeeting_SiteFlip",
        "BigAl_Hoops_Revenge_Context_DataReady",
    ]
    for _c in _bigal_spread_context:
        if _c in out.columns:
            out.loc[~_m.eq("spreads"), _c] = 0

    # DB-only Big Al enhancers are market-specific just like exact systems.
    _bigal_spread_enhancers = [
        "BigAl_NFL_Enhancer_LateHomeDog",
        "BigAl_NFL_Enhancer_PenultimateBadTeamOffWin",
        "BigAl_CF_Enhancer_RevengeDog",
        "BigAl_NBA_Enhancer_ImmediateRematchDog",
        "BigAl_CBB_Enhancer_HomeRevengeWinning",
        "BigAl_WNBA_Enhancer_WinningHomeDoubleRevenge",
        "BigAl_WNBA_Enhancer_WinningHomeDoubleRevengeDog",
        "BigAl_CFL_Enhancer_WinlessRevengeBigDog",
    ]
    _bigal_h2h_enhancers = [
        "BigAl_MLB_Recent5_SU_WinPct_Prior",
        "BigAl_MLB_Recent_vs_Season_WinPct_Delta",
        "BigAl_MLB_Enhancer_RecentFormAboveSeason",
        "BigAl_MLB_Enhancer_RecentFormFavorite",
    ]
    for _c in _bigal_spread_enhancers:
        if _c in out.columns:
            out.loc[~_m.eq("spreads"), _c] = 0
    for _c in _bigal_h2h_enhancers:
        if _c in out.columns:
            out.loc[~_m.eq("h2h"), _c] = 0

    _pathi_ml = [
        "Pathi_M1_DogThatWon", "Pathi_M8_DogWon_BetterPrice", "Pathi_M2_HomeDog",
        "Pathi_M3_Rule10_LosingStreak", "Pathi_M3_Rule10_PlusMoney",
        "Pathi_M4_ExtendedWinStreakFade", "Pathi_M5_TravelOffDayFreeze",
        "Pathi_M6_WeakTeamNewChalk_Screen", "Pathi_M7_BadRoadFavoriteProfile",
        "Pathi_RoadFavLost_StillFavorite_Screen", "Pathi_RoleFlip_DogToFavorite_Cancel",
    ]
    _pathi_spread = ["Pathi_M9_Plus15_PlusMoney", "Pathi_FB_Dog_TotalSpread_Gap_LE10"]
    _bigal_side = [
        "BigAl_NFL1_Week1FadePlayoffTeam", "BigAl_NFL1_HomeTightener",
        "BigAl_NFL2_LateSeasonHomeDog", "BigAl_NFL2_OppOffATSLoss_Tightener",
        "BigAl_NFL3_PlayoffHighScoreFade", "BigAl_NFL4_PreseasonContrarianMove",
        "BigAl_CF1_Week2Home42Win", "BigAl_CF2_LateSeasonRevengeDog", "BigAl_CF2_Away_Tightener", "BigAl_CF3_Fade19PlusFavoriteUpsetLoss",
        "BigAl_NBA1_B2BRematchRoadDog", "BigAl_NBA1_PriorLoss25_Tightener",
        "BigAl_NBA2_ThreeMassiveCovers", "BigAl_NBA3_FadeHomeAfterChampUpset",
        "BigAl_NBA3_WinPct572_Tightener", "BigAl_NBA4_FinalHomeFavRevenge",
        "BigAl_NBA4_NotOffSUATSLoss_Tightener", "BigAl_NBA5_PlayoffBigDogVsChamp",
        "BigAl_NBA5_ChampOffSUWin_Tightener", "BigAl_NBA6_FinalsGame4",
        "BigAl_NBA8_Revenge145FadeFavorite", "BigAl_NBA8_WinningRecord_Tightener",
        "BigAl_CBB1_UglyDog20Losses", "BigAl_CBB1_ThreeLoss_Tightener",
        "BigAl_CBB2_Fade10WinStreakFavorite",
        "BigAl_CBB3_HomeRevenge27", "BigAl_CBB3_DogOffLoss_Tightener",
        "BigAl_CFL2_EliteDogFade", "BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo",
    ]
    _bigal_total = [
        "BigAl_NFL5_PreseasonLowOffenseOver", "BigAl_NFL5_TotalUnder40_Tightener",
        "BigAl_NBA7_TwoTeamEliminationUnder",
        "BigAl_CFL1_SecondMeetingUnder", "BigAl_CFL1_TotalAbove51_Tightener",
        "BigAl_Total_System_Signed",
    ]

    for _c in _pathi_ml:
        if _c in out.columns:
            out.loc[~_m.eq("h2h"), _c] = 0
    for _c in _pathi_spread + _bigal_side:
        if _c in out.columns:
            out.loc[~_m.eq("spreads"), _c] = 0
    for _c in _bigal_total:
        if _c in out.columns:
            out.loc[~_m.eq("totals"), _c] = 0

    # Market-mask the ENTIRE named Big Al family, including DataReady and
    # Match_Ratio fields.  Previously those suffix features could cross from a
    # totals system into a spreads model (or vice versa).
    _bigal_side_prefixes = (
        "BigAl_NFL1_", "BigAl_NFL2_", "BigAl_NFL3_", "BigAl_NFL4_",
        "BigAl_CF1_", "BigAl_CF2_",
        "BigAl_NBA1_", "BigAl_NBA2_", "BigAl_NBA3_", "BigAl_NBA4_", "BigAl_NBA5_", "BigAl_NBA6_", "BigAl_NBA8_",
        "BigAl_CBB1_", "BigAl_CBB2_", "BigAl_CBB3_", "BigAl_CFL2_", "BigAl_CFL3_",
    )
    _bigal_total_prefixes = ("BigAl_NFL5_", "BigAl_NBA7_", "BigAl_CFL1_")
    for _c in [c for c in out.columns if str(c).startswith(_bigal_side_prefixes)]:
        out.loc[~_m.eq("spreads"), _c] = 0
    for _c in [c for c in out.columns if str(c).startswith(_bigal_total_prefixes)]:
        out.loc[~_m.eq("totals"), _c] = 0
    if "BigAl_Total_System_Signed" in out.columns:
        out.loc[~_m.eq("totals"), "BigAl_Total_System_Signed"] = 0

    _pathi_count = [c for c in (_pathi_ml + _pathi_spread) if c in out.columns and not c.endswith("Cancel")]
    _bigal_bases = [
        c for c in (_bigal_side + _bigal_total)
        if c in out.columns and not c.endswith("_Tightener") and c != "BigAl_Total_System_Signed"
        and not _is_retired_bigal_feature_name(c)
    ]
    _tight = [
        c for c in out.columns
        if c.startswith("BigAl_") and c.endswith("_Tightener")
        and not _is_retired_bigal_feature_name(c)
    ]
    out["Pathi_System_Count"] = out[_pathi_count].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16") if _pathi_count else 0
    out["BigAl_System_Count"] = out[_bigal_bases].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16") if _bigal_bases else 0
    out["BigAl_Tightener_Count"] = out[_tight].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16") if _tight else 0
    out["System_Signal_Count"] = (out["Pathi_System_Count"] + out["BigAl_System_Count"] + out["BigAl_Tightener_Count"]).astype("int16")

    # Enhancers are intentionally tracked separately and never promoted to an
    # exact System_Signal_Count.
    _ba_enhancer_flags = [c for c in BIGAL_ENHANCER_COLS if c in out.columns]
    out["BigAl_Enhancer_Count"] = (
        out[_ba_enhancer_flags].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16")
        if _ba_enhancer_flags else 0
    )
    out["BigAl_Enhancer_Active"] = (out["BigAl_Enhancer_Count"] > 0).astype("int8")

    # Explicit Big Al market-family indicators for model/UI auditability.
    _ba_spread_bases = [c for c in _bigal_side if c in out.columns and not c.endswith("_Tightener") and not _is_retired_bigal_feature_name(c)]
    _ba_total_bases = [c for c in _bigal_total if c in out.columns and not c.endswith("_Tightener") and c != "BigAl_Total_System_Signed" and not _is_retired_bigal_feature_name(c)]
    _ba_spread_tight = [c for c in _bigal_side if c in out.columns and c.endswith("_Tightener") and not _is_retired_bigal_feature_name(c)]
    _ba_total_tight = [c for c in _bigal_total if c in out.columns and c.endswith("_Tightener") and not _is_retired_bigal_feature_name(c)]
    out["BigAl_Spread_System_Count"] = out[_ba_spread_bases].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16") if _ba_spread_bases else 0
    out["BigAl_Total_System_Count"] = out[_ba_total_bases].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16") if _ba_total_bases else 0
    out["BigAl_Spread_Tightener_Count"] = out[_ba_spread_tight].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16") if _ba_spread_tight else 0
    out["BigAl_Total_Tightener_Count"] = out[_ba_total_tight].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16") if _ba_total_tight else 0
    out["BigAl_Spread_Active"] = (out["BigAl_Spread_System_Count"] > 0).astype("int8")
    out["BigAl_Total_Active"] = (out["BigAl_Total_System_Count"] > 0).astype("int8")
    _ba_signed = pd.to_numeric(out.get("BigAl_Total_System_Signed"), errors="coerce").fillna(0)
    out["BigAl_Total_Over_Active"] = (_ba_signed > 0).astype("int8")
    out["BigAl_Total_Under_Active"] = (_ba_signed < 0).astype("int8")

    _ba_ready_cols = [
        c for c in out.columns if c.startswith("BigAl_") and c.endswith("_DataReady")
        and not _is_retired_bigal_feature_name(c)
    ]
    _ba_ratio_cols = [
        c for c in out.columns if c.startswith("BigAl_") and c.endswith("_Match_Ratio")
        and not _is_retired_bigal_feature_name(c)
    ]
    out["BigAl_DataReady_Count"] = (
        out[_ba_ready_cols].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1).astype("int16")
        if _ba_ready_cols else 0
    )
    if _ba_ratio_cols:
        _ba_rat = out[_ba_ratio_cols].apply(pd.to_numeric, errors="coerce").replace(0.0, np.nan)
        out["BigAl_Max_Match_Ratio"] = _ba_rat.max(axis=1, skipna=True).astype("float32")
        out["BigAl_Mean_Match_Ratio"] = _ba_rat.mean(axis=1, skipna=True).astype("float32")
    else:
        out["BigAl_Max_Match_Ratio"] = np.nan
        out["BigAl_Mean_Match_Ratio"] = np.nan
    out["BigAl_Active_System_Count"] = out["BigAl_System_Count"].astype("int16")
    out["BigAl_Active_Tightener_Count"] = out["BigAl_Tightener_Count"].astype("int16")

    _labels = {
        "Pathi_M1_DogThatWon": "PATHI M1 Dog That Won",
        "Pathi_M8_DogWon_BetterPrice": "PATHI M8 Better Price",
        "Pathi_M2_HomeDog": "PATHI M2 Home Dog",
        "Pathi_M3_Rule10_LosingStreak": "PATHI M3 Rule of 10",
        "Pathi_M3_Rule10_PlusMoney": "PATHI M3 +Money",
        "Pathi_M4_ExtendedWinStreakFade": "PATHI M4 Fade Hot Favorite",
        "Pathi_M5_TravelOffDayFreeze": "PATHI M5 Off-Day Freeze",
        "Pathi_M6_WeakTeamNewChalk_Screen": "PATHI M6 New Chalk Screen",
        "Pathi_M7_BadRoadFavoriteProfile": "PATHI M7 Bad Road Favorite",
        "Pathi_M9_Plus15_PlusMoney": "PATHI M9 +1.5 Plus Money",
        "Pathi_RoleFlip_DogToFavorite_Cancel": "PATHI CANCEL Dog->Favorite",
        "BigAl_NFL1_Week1FadePlayoffTeam": "BIG AL NFL1 Week 1 Fade",
        "BigAl_NFL2_LateSeasonHomeDog": "BIG AL NFL2 Late Home Dog",
        "BigAl_NFL3_PlayoffHighScoreFade": "BIG AL NFL3 Playoff Fade",
        "BigAl_NFL4_PreseasonContrarianMove": "BIG AL NFL4 Preseason RLM",
        "BigAl_NFL5_PreseasonLowOffenseOver": "BIG AL NFL5 OVER",
        "BigAl_CF1_Week2Home42Win": "BIG AL CF1 Week 2",
        "BigAl_CF2_LateSeasonRevengeDog": "BIG AL CF2 Revenge Dog",
        "BigAl_CF3_Fade19PlusFavoriteUpsetLoss": "BIG AL CF3 Fade 19+ Fav Upset Loss",
        "BigAl_NBA1_B2BRematchRoadDog": "BIG AL NBA1 Rematch Dog",
        "BigAl_NBA2_ThreeMassiveCovers": "BIG AL NBA2 3 Massive Covers",
        "BigAl_NBA3_FadeHomeAfterChampUpset": "BIG AL NBA3 Champ-Upset Fade",
        "BigAl_NBA4_FinalHomeFavRevenge": "BIG AL NBA4 Final Home Revenge",
        "BigAl_NBA5_PlayoffBigDogVsChamp": "BIG AL NBA5 Playoff Big Dog",
        "BigAl_NBA6_FinalsGame4": "BIG AL NBA6 Finals G4",
        "BigAl_NBA7_TwoTeamEliminationUnder": "BIG AL NBA7 UNDER",
        "BigAl_NBA8_Revenge145FadeFavorite": "BIG AL NBA8 Revenge 145+ Fade",
        "BigAl_CBB1_UglyDog20Losses": "BIG AL CBB1 Ugly Dog",
        "BigAl_CBB2_Fade10WinStreakFavorite": "BIG AL CBB2 Fade 10-Win-Streak Favorite",
        "BigAl_CBB3_HomeRevenge27": "BIG AL CBB3 Home Revenge 27+",
        "BigAl_CFL1_SecondMeetingUnder": "BIG AL CFL1 UNDER",
        "BigAl_CFL2_EliteDogFade": "BIG AL CFL2 Fade Elite Dog",
        "BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo": "BIG AL CFL3 3rd Meeting Road Dog",
    }
    _tight_labels = {c: c.replace("BigAl_", "BIG AL ").replace("_", " ") for c in _tight}
    _labels.update(_tight_labels)
    def _row_labels(r):
        vals=[]
        for c,label in _labels.items():
            if c in r.index and pd.to_numeric(r[c], errors="coerce") == 1:
                vals.append(label)
        return " | ".join(vals) if vals else "—"
    out["System_Signals_Text"] = out.apply(_row_labels, axis=1)

    # Separate UI audit strings: Pathi and Big Al are never merged/double-counted.
    _pathi_ui_labels = {c: label.replace("PATHI ", "") for c, label in _labels.items() if c.startswith("Pathi_")}
    _bigal_ui_labels = {c: label.replace("BIG AL ", "") for c, label in _labels.items() if c.startswith("BigAl_") and not _is_retired_bigal_feature_name(c)}

    def _ui_active_text(r, family):
        if family == "pathi":
            vals = [lab for c, lab in _pathi_ui_labels.items() if c in r.index and pd.to_numeric(r[c], errors="coerce") == 1]
            return " | ".join(vals) if vals else "—"

        vals = [lab for c, lab in _bigal_ui_labels.items() if c in r.index and pd.to_numeric(r[c], errors="coerce") == 1]
        mk = _sys_norm_market(r.get("Market", ""))
        if vals:
            if mk == "totals":
                signed = pd.to_numeric(pd.Series([r.get("BigAl_Total_System_Signed", 0)]), errors="coerce").fillna(0).iloc[0]
                direction = "OVER" if signed > 0 else ("UNDER" if signed < 0 else "TOTAL")
                return f"TOTAL · {direction} · " + " | ".join(vals)
            if mk == "spreads":
                return "SPREAD SIGNAL · " + " | ".join(vals)
            return "BIG AL SIGNAL · " + " | ".join(vals)

        # No exact system/tightener: show DB-supported enhancer(s) next.
        # Enhancers are deliberately suppressed when an exact system fires so
        # a parent system and its broader ingredient are not visually doubled.
        _enhancer_ui_labels = {
            "BigAl_MLB_Enhancer_RecentFormFavorite": "Improving Form Favorite",
            "BigAl_MLB_Enhancer_RecentFormAboveSeason": "Recent Form > Season",
            "BigAl_NFL_Enhancer_LateHomeDog": "Late-Season Home Dog",
            "BigAl_NFL_Enhancer_PenultimateBadTeamOffWin": "Penultimate Bad Team off Win",
            "BigAl_CF_Enhancer_RevengeDog": "NCAAF Revenge Dog",
            "BigAl_NBA_Enhancer_ImmediateRematchDog": "Immediate-Rematch Dog",
            "BigAl_CBB_Enhancer_HomeRevengeWinning": "Winning Home Revenge",
            "BigAl_WNBA_Enhancer_WinningHomeDoubleRevengeDog": "WNBA Winning Home Double-Revenge Dog",
            "BigAl_WNBA_Enhancer_WinningHomeDoubleRevenge": "WNBA Winning Home Double-Revenge",
            "BigAl_CFL_Enhancer_WinlessRevengeBigDog": "CFL Winless Revenge +9 Dog",
        }
        enh = []
        for c, lab in _enhancer_ui_labels.items():
            if c in r.index and pd.to_numeric(r[c], errors="coerce") == 1 and lab not in enh:
                enh.append(lab)
            if len(enh) >= 2:
                break
        if enh:
            if mk == "h2h":
                return "ML ENHANCER · " + " | ".join(enh)
            if mk == "spreads":
                return "SPREAD ENHANCER · " + " | ".join(enh)
            if mk == "totals":
                return "TOTAL ENHANCER · " + " | ".join(enh)
            return "BIG AL ENHANCER · " + " | ".join(enh)

        # No exact system or enhancer: show a concise, non-duplicative context summary.
        context_priority = [
            ("BigAl_Hoops_Revenge_Context_Active", "Same-Season Revenge"),
            ("BigAl_Hoops_Revenge_LastMeeting_SiteFlip", "Revenge Site Flip"),
            ("BigAl_Context_Game2_NonConference_Home", "Game 2 Non-Conf Home"),
            ("BigAl_Context_Conference_Home_Dog", "Conference Home Dog"),
            ("BigAl_Context_Division_Home_Dog", "Division Home Dog"),
            ("BigAl_Context_Conference_Home_Favorite", "Conference Home Favorite"),
            ("BigAl_Context_Division_Home_Favorite", "Division Home Favorite"),
            ("BigAl_Context_Is_Division_Game", "Division Game"),
            ("BigAl_Context_Is_Conference_Game", "Conference Game"),
            ("BigAl_Context_Is_NonConference_Game", "Non-Conference"),
            ("BigAl_Context_Week_1", "Week 1"),
            ("BigAl_Context_Week_2", "Week 2"),
            ("BigAl_Context_Week_9_Plus", "Week 9+"),
            ("BigAl_Context_Had_Bye_Proxy", "Post-Bye"),
        ]
        ctx=[]
        for c, lab in context_priority:
            if c in r.index and pd.to_numeric(r[c], errors="coerce") == 1 and lab not in ctx:
                ctx.append(lab)
            if len(ctx) >= 3:
                break
        if not ctx:
            return "—"
        prefix = "TOTAL CONTEXT" if mk == "totals" else ("SPREAD CONTEXT" if mk == "spreads" else "CONTEXT")
        return prefix + " · " + " | ".join(ctx)

    out["Pathi_Active_Text"] = out.apply(lambda r: _ui_active_text(r, "pathi"), axis=1)
    out["BigAl_Active_Text"] = out.apply(lambda r: _ui_active_text(r, "bigal"), axis=1)
    out = add_pathi_football_key_features(out)
    return out



def log_bigal_training_coverage(df_market: pd.DataFrame, sport: str, market: str) -> None:
    """Compact audit of Big Al readiness, fires and realized historical hit rate."""
    if df_market is None or df_market.empty:
        return
    m = _sys_norm_market(market)
    base_map = {
        # Regular-season only. Retired preseason/postseason/championship systems
        # are intentionally excluded from coverage diagnostics.
        "BigAl_NFL2_LateSeasonHomeDog": "spreads",
        "BigAl_CF1_Week2Home42Win": "spreads",
        "BigAl_CF2_LateSeasonRevengeDog": "spreads",
        "BigAl_NBA1_B2BRematchRoadDog": "spreads",
        "BigAl_NBA2_ThreeMassiveCovers": "spreads",
        "BigAl_NBA8_Revenge145FadeFavorite": "spreads",
        "BigAl_CBB1_UglyDog20Losses": "spreads",
        "BigAl_CBB2_Fade10WinStreakFavorite": "spreads",
        "BigAl_CBB3_HomeRevenge27": "spreads",
        "BigAl_CFL1_SecondMeetingUnder": "totals",
        "BigAl_CFL2_EliteDogFade": "spreads",
        "BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo": "spreads",
    }
    sport_prefix = {
        "NFL": "BigAl_NFL", "NCAAF": "BigAl_CF", "NBA": "BigAl_NBA",
        "NCAAB": "BigAl_CBB", "NCAAM": "BigAl_CBB", "CFL": "BigAl_CFL",
    }.get(str(sport).upper().strip())
    if not sport_prefix:
        return
    grain = [c for c in ("Merge_Key_Short", "Outcome") if c in df_market.columns]
    d = df_market.copy()
    if grain:
        sortc = "Snapshot_Timestamp" if "Snapshot_Timestamp" in d.columns else None
        if sortc:
            d = d.sort_values(sortc)
        d = d.drop_duplicates(grain, keep="last")
    target = pd.to_numeric(d.get("SHARP_HIT_BOOL"), errors="coerce")
    outn = d.get("Outcome", pd.Series("", index=d.index)).astype(str).str.lower().str.strip()
    rows = []
    for base, bmkt in base_map.items():
        if bmkt != m or not base.startswith(sport_prefix) or base not in d.columns:
            continue
        drc = base + "_DataReady"
        ready_n = int(pd.to_numeric(d.get(drc, 0), errors="coerce").fillna(0).eq(1).sum()) if drc in d.columns else 0
        fire = pd.to_numeric(d[base], errors="coerce").fillna(0).eq(1)
        if m == "totals":
            desired = "over" if base == "BigAl_NFL5_PreseasonLowOffenseOver" else "under"
            fire &= outn.eq(desired)
        fire_n = int(fire.sum())
        valid = fire & target.notna()
        hit = float(target.loc[valid].mean()) if valid.any() else np.nan
        rows.append(f"{base}: ready={ready_n} fires={fire_n} hit={hit:.3f}" if np.isfinite(hit)
                    else f"{base}: ready={ready_n} fires={fire_n} hit=NA")
    if rows:
        print(f"[BIGAL-COVERAGE:{str(sport).upper()}:{m}] " + " | ".join(rows))




def add_ai_betting_brain_features(df: pd.DataFrame) -> pd.DataFrame:
    """Leakage-safe expert-state / meta-brain features.

    V11.2 separates each expert family into:
      * Active    -- does this family have a real opinion/evidence now?
      * Direction -- +1 supports this row/outcome, -1 opposes it, 0 neutral/unknown
      * Intensity -- unsigned strength of the currently active evidence (0..1)

    Credibility/trust is intentionally NOT hard-coded here.  That later layer must
    be learned from historical out-of-sample outcome/CLV performance by regime.
    """
    if df is None or df.empty:
        return df.copy() if df is not None else df
    out = df.copy()
    idx = out.index

    def num(*names, default=np.nan):
        s = pd.Series(np.nan, index=idx, dtype='float64')
        for name in names:
            if name in out.columns:
                s = s.where(s.notna(), pd.to_numeric(out[name], errors='coerce'))
        if not (isinstance(default, float) and np.isnan(default)):
            s = s.fillna(default)
        return s

    def flag(name):
        return num(name, default=0).fillna(0).gt(0).astype('int8')

    def sgn(s, eps=1e-12):
        z = pd.to_numeric(s, errors='coerce').fillna(0.0)
        return pd.Series(np.where(z > eps, 1, np.where(z < -eps, -1, 0)), index=idx, dtype='int8')

    def install_expert(name, active, direction, intensity):
        a = pd.Series(active, index=idx).fillna(False).astype(bool)
        d = pd.Series(direction, index=idx).fillna(0).astype('int8')
        inten = pd.to_numeric(pd.Series(intensity, index=idx), errors='coerce').fillna(0.0).clip(0, 1)
        # No phantom expert: inactive means neutral and zero intensity.
        d = d.where(a, 0).astype('int8')
        inten = inten.where(a, 0.0).astype('float32')
        out[f'Brain_Expert_{name}_Active'] = a.astype('int8')
        out[f'Brain_Expert_{name}_Direction'] = d
        out[f'Brain_Expert_{name}_Intensity'] = inten
        # Preserve V11 names so existing model contracts do not break.
        out[f'Brain_Expert_{name}_Strength'] = inten

    sport = out.get('Sport', pd.Series('', index=idx)).astype(str).str.upper().str.strip()
    market = out.get('Market', pd.Series('', index=idx)).astype(str).str.lower().str.strip()

    # ------------------------------------------------------------------
    # 1) Mutually-exclusive season regime detection.
    # ------------------------------------------------------------------
    game_no = num('BigAl_Context_Team_Game_Number', 'Team_Game_Number')
    week = num('Week_Number', 'BigAl_Context_Week_Number')
    known_stage = game_no.notna() | week.notna()
    early_raw = ((game_no.notna() & game_no.le(4)) | (week.notna() & week.le(4)))
    late_raw = (
        flag('Final_Two_Regular_Season').eq(1)
        | num('BigAl_Context_Week_9_Plus', default=0).eq(1)
        | (game_no.notna() & game_no.ge(12))
    )
    is_early = known_stage & early_raw
    is_late = known_stage & late_raw & ~is_early
    is_mature = known_stage & ~is_early & ~is_late
    out['Brain_Regime_EarlySeason'] = is_early.astype('int8')
    out['Brain_Regime_MatureSeason'] = is_mature.astype('int8')
    out['Brain_Regime_LateSeason'] = is_late.astype('int8')

    # ------------------------------------------------------------------
    # 2) Market state built from fields that are already populated in this model.
    # ------------------------------------------------------------------
    line_move = num('Abs_Line_Move_From_Opening', 'Line_Move_From_Open', 'Sharp_Line_Magnitude', default=0).abs()
    sharp_line_mag = num('Sharp_Line_Magnitude', default=0).abs()
    velocity = pd.concat([
        num('Line_Move_Velocity_60m', default=0).abs(),
        num('Line_Move_Velocity_120m', default=0).abs(),
    ], axis=1).max(axis=1)
    books_align = num('Pct_Books_Aligned', default=0).clip(0, 1)
    sharp_gap = num('Sharp_Rec_Prob_Gap', default=0).abs()
    sharp_odds_mag = num('SharpMove_Odds_Mag', default=0).abs()
    limit_mag = num('LimitProtect_SharpMag', default=0).abs()
    sharp_signal = flag('Sharp_Move_Signal')
    leader = flag('Market_Leader')
    reversal = (flag('Value_Reversal_Flag').eq(1) | flag('Odds_Reversal_Flag').eq(1)).astype('int8')
    toward = flag('Line_Moved_Toward_Team')
    away = flag('Line_Moved_Away_From_Team')

    market_intensity_raw = (
        0.24*np.tanh(line_move/1.25)
        + 0.16*np.tanh(sharp_line_mag/0.75)
        + 0.12*np.tanh(velocity/0.50)
        + 0.16*books_align
        + 0.10*np.tanh(sharp_gap/0.025)
        + 0.08*np.tanh(sharp_odds_mag/12.0)
        + 0.05*np.tanh(limit_mag/0.75)
        + 0.05*sharp_signal.astype(float)
        + 0.02*leader.astype(float)
        + 0.02*reversal.astype(float)
    ).clip(0, 1)

    market_dir_primary = toward.astype(int) - away.astype(int)
    market_dir_gap = sgn(num('Sharp_Rec_Prob_Gap', default=0), eps=0.0025)
    market_direction = pd.Series(
        np.where(market_dir_primary != 0, np.sign(market_dir_primary), market_dir_gap),
        index=idx, dtype='int8'
    )
    market_active = (
        market_dir_primary.ne(0)
        | sharp_signal.eq(1)
        | reversal.eq(1)
        | line_move.ge(0.25)
        | sharp_line_mag.ge(0.15)
        | sharp_gap.ge(0.0025)
        | sharp_odds_mag.gt(0)
    )
    market_intensity = market_intensity_raw.where(market_active, 0.0)

    out['Brain_Regime_ActiveMarket'] = market_active.astype('int8')
    out['Brain_Regime_QuietMarket'] = (~market_active).astype('int8')
    steam = (
        market_active
        & (sharp_signal.eq(1) | sharp_line_mag.ge(0.5) | line_move.ge(1.0))
        & (books_align.ge(0.60) | sharp_gap.ge(0.01) | leader.eq(1))
    )
    out['Brain_Regime_SteamMarket'] = steam.astype('int8')

    key_market = (
        flag('Pathi_FB_On_Key_3').eq(1) | flag('Pathi_FB_On_Key_7').eq(1)
        | flag('Pathi_FB_Moved_Through_Key').eq(1) | flag('Crossed_Key_3').eq(1)
        | flag('Crossed_Key_7').eq(1)
    ) & sport.isin(['NFL','NCAAF']) & market.eq('spreads')
    out['Brain_Regime_KeyNumberMarket'] = key_market.astype('int8')

    # ------------------------------------------------------------------
    # 3) BIG AL expert state.
    # ------------------------------------------------------------------
    bigal_exact = num('BigAl_System_Count', 'BigAl_Active_System_Count', default=0)
    bigal_tight = num('BigAl_Tightener_Count', 'BigAl_Active_Tightener_Count', default=0)
    bigal_enh = num('BigAl_Enhancer_Count', default=0)
    bigal_ready = num('BigAl_DataReady_Count', default=0)
    bigal_active = (bigal_exact + bigal_tight + bigal_enh).gt(0)
    bigal_intensity = np.tanh((1.00*bigal_exact + 0.55*bigal_tight + 0.25*bigal_enh) / 2.0)
    bigal_side_net = num('BigAl_Side_Net_Signal', default=0)
    bigal_total_signed = num('BigAl_Total_System_Signed', default=0)
    bigal_dir = pd.Series(0, index=idx, dtype='int8')
    is_total = market.eq('totals')
    bigal_dir.loc[is_total] = sgn(bigal_total_signed).loc[is_total]
    bigal_dir.loc[~is_total] = sgn(bigal_side_net).loc[~is_total]
    # Big Al enhancers in this build are play-on-current-row ingredients. If no
    # exact directional system is active, let a live enhancer express +1.
    bigal_dir = bigal_dir.where(~(bigal_dir.eq(0) & bigal_enh.gt(0)), 1).astype('int8')
    install_expert('BigAl', bigal_active, bigal_dir, bigal_intensity)
    out['Brain_Expert_BigAl_Readiness'] = (bigal_ready / (bigal_ready + 5.0)).fillna(0).astype('float32')

    # ------------------------------------------------------------------
    # 4) PATHI expert state. DataReady alone no longer creates phantom strength.
    # ------------------------------------------------------------------
    pathi_count = num('Pathi_System_Count', default=0)
    system_net = num('System_Net_Signal', default=0)
    pathi_net = system_net - bigal_side_net
    key_toward = flag('Pathi_FB_Crossed_Key_Toward_Team')
    key_away = flag('Pathi_FB_Crossed_Key_Away_From_Team')
    key_dir = key_toward.astype(int) - key_away.astype(int)
    pathi_dir = sgn(pathi_net)
    pathi_dir = pathi_dir.where(~pathi_dir.eq(0), sgn(key_dir)).astype('int8')

    # Symmetric key events are useful regime/context information, but they are not
    # a side pick.  V12.0.7 incorrectly let them manufacture Pathi activity/strength.
    pathi_context_events = (
        flag('Pathi_FB_Moved_Through_Key').astype(float)
        + flag('Pathi_FB_Moved_Onto_Key').astype(float)
        + flag('Pathi_FB_Moved_Off_Key').astype(float)
        + flag('Pathi_FB_On_Key_3').astype(float)
        + flag('Pathi_FB_On_Key_7').astype(float)
        + flag('Pathi_FB_On_Key_10').astype(float)
        + flag('Pathi_FB_On_Key_14').astype(float)
    )
    pathi_directional_evidence = key_toward.astype(float) + key_away.astype(float)
    pathi_active = (pathi_count.gt(0) | key_dir.ne(0)) & pathi_dir.ne(0)
    pathi_intensity = np.tanh((pathi_count + 0.75*pathi_directional_evidence) / 2.0)
    install_expert('Pathi', pathi_active, pathi_dir, pathi_intensity)
    out['Brain_Pathi_Context_Event_Count'] = pathi_context_events.astype('float32')

    # ------------------------------------------------------------------
    # 5) MARKET expert state.
    # ------------------------------------------------------------------
    install_expert('Market', market_active, market_direction, market_intensity)

    # ------------------------------------------------------------------
    # 6) POWER expert state.
    # ------------------------------------------------------------------
    power_gap = num('PR_Rating_Diff', 'Power_Rating_Diff')
    power_active = power_gap.notna() & power_gap.abs().ge(0.50)
    power_direction = sgn(power_gap, eps=0.50)
    power_intensity = np.tanh(power_gap.abs().fillna(0)/7.0)
    install_expert('Power', power_active, power_direction, power_intensity)

    # ------------------------------------------------------------------
    # 7) FORM expert state: deviation from neutral, not raw win pct magnitude.
    # ------------------------------------------------------------------
    form_components = pd.concat([
        (num('Team_Recent_Cover_Rate') - 0.50),
        (num('WinPct_Prior_System') - 0.50),
        num('BigAl_MLB_Recent_vs_Season_WinPct_Delta'),
    ], axis=1)
    form_signed = form_components.mean(axis=1, skipna=True)
    form_obs = form_components.notna().sum(axis=1)
    form_active = form_obs.gt(0) & form_signed.abs().ge(0.025)
    form_direction = sgn(form_signed, eps=0.025)
    form_intensity = np.tanh(form_signed.abs().fillna(0)*4.0)
    install_expert('Form', form_active, form_direction, form_intensity)

    # ------------------------------------------------------------------
    # 8) SCHEDULE expert state: symmetric current-vs-opponent rest/stress.
    #
    # +1 = schedule/rest edge supports the current row/team
    # -1 = schedule/rest edge hurts the current row/team
    #  0 = no meaningful schedule opinion
    #
    # Opponent state is recovered from the paired team rows for the same game.
    # This keeps the expert two-sided without inventing unavailable travel data.
    # ------------------------------------------------------------------
    # FINAL/FROZEN CONTRACT: Schedule may vote only from genuinely paired,
    # two-sided current-vs-opponent evidence.  One-sided proxies (notably the
    # BigAl bye proxy) remain available as raw context but cannot manufacture a
    # directional expert vote.
    # Prefer canonical physical team-game schedule state built by
    # build_pathi_bigal_team_game_state(). Fall back to legacy market-grain
    # schedule fields only when the canonical fields are unavailable.
    days_rest = num('Days_Since_Last_Game_System')
    if days_rest.isna().all():
        days_rest = num('Days_Since_Last_Game')

    b2b_raw = num('Is_B2B_System')
    if b2b_raw.isna().all():
        b2b_raw = num('Is_B2B')
    three4_raw = num('Is_3in4_System')
    if three4_raw.isna().all():
        three4_raw = num('Is_3in4')
    bye_raw = num('Had_Bye_Last_Game_System')
    if bye_raw.isna().all():
        # Legacy context fallback is deliberately non-directional unless
        # an opponent value is also genuinely present.
        bye_raw = num('BigAl_Context_Had_Bye_Proxy')

    def _opp_metric_from_team_rows(col, agg='median'):
        """Return opponent's same-game team metric while preserving row count/index."""
        if col not in out.columns or not {'Sport','Game_Key','Team','Opponent'}.issubset(out.columns):
            return pd.Series(np.nan, index=idx, dtype='float64')
        base = out[['Sport','Game_Key','Team',col]].copy()
        base[col] = pd.to_numeric(base[col], errors='coerce')
        if agg == 'max':
            base = base.groupby(['Sport','Game_Key','Team'], dropna=False, as_index=False)[col].max()
        else:
            base = base.groupby(['Sport','Game_Key','Team'], dropna=False, as_index=False)[col].median()
        base = base.rename(columns={'Team':'Opponent', col:'__opp_metric'})
        left = out[['Sport','Game_Key','Opponent']].copy()
        left['__row_order'] = np.arange(len(left))
        merged = left.merge(base, on=['Sport','Game_Key','Opponent'], how='left', sort=False)
        merged = merged.sort_values('__row_order', kind='stable')
        return pd.Series(pd.to_numeric(merged['__opp_metric'], errors='coerce').to_numpy(), index=idx, dtype='float64')

    # Canonical opponent mirrors are attached directly by the team-game state
    # builder. Use those first; self-join fallback is retained for backward
    # compatibility with older saved feature frames.
    opp_days_rest = num('Opp_Days_Since_Last_Game_System')
    if opp_days_rest.isna().all():
        opp_days_rest = _opp_metric_from_team_rows('Days_Since_Last_Game_System', agg='median')
        if opp_days_rest.isna().all():
            opp_days_rest = _opp_metric_from_team_rows('Days_Since_Last_Game', agg='median')

    opp_b2b_raw = num('Opp_Is_B2B_System')
    if opp_b2b_raw.isna().all():
        opp_b2b_raw = _opp_metric_from_team_rows('Is_B2B_System', agg='max')
        if opp_b2b_raw.isna().all():
            opp_b2b_raw = _opp_metric_from_team_rows('Is_B2B', agg='max')

    opp_three4_raw = num('Opp_Is_3in4_System')
    if opp_three4_raw.isna().all():
        opp_three4_raw = _opp_metric_from_team_rows('Is_3in4_System', agg='max')
        if opp_three4_raw.isna().all():
            opp_three4_raw = _opp_metric_from_team_rows('Is_3in4', agg='max')

    opp_bye_raw = num('Opp_Had_Bye_Last_Game_System')
    if opp_bye_raw.isna().all():
        opp_bye_raw = _opp_metric_from_team_rows('Had_Bye_Last_Game_System', agg='max')
    if opp_bye_raw.isna().all():
        opp_bye_raw = num('Opp_BigAl_Context_Had_Bye_Proxy')
        if opp_bye_raw.isna().all():
            opp_bye_raw = _opp_metric_from_team_rows('BigAl_Context_Had_Bye_Proxy', agg='max')

    rest_pair_ready = days_rest.notna() & opp_days_rest.notna()
    b2b_pair_ready = b2b_raw.notna() & opp_b2b_raw.notna()
    three4_pair_ready = three4_raw.notna() & opp_three4_raw.notna()
    bye_pair_ready = bye_raw.notna() & opp_bye_raw.notna()

    rest_diff = (days_rest - opp_days_rest).where(rest_pair_ready)
    b2b_diff = (opp_b2b_raw - b2b_raw).where(b2b_pair_ready)
    three4_diff = (opp_three4_raw - three4_raw).where(three4_pair_ready)
    bye_diff = (bye_raw - opp_bye_raw).where(bye_pair_ready)

    # Positive signed value favors the current row/team. Football is driven
    # primarily by rest/bye differential; high-frequency sports also use B2B
    # and 3-in-4 stress. Missing opponent evidence contributes nothing.
    rest_component = rest_diff.clip(-4, 4).fillna(0.0) * 0.25
    stress_component = b2b_diff.fillna(0.0) + 0.75 * three4_diff.fillna(0.0)
    bye_component = bye_diff.fillna(0.0) * 1.00
    sched_signed = rest_component + stress_component + bye_component

    paired_directional_evidence = (
        (rest_pair_ready & rest_diff.abs().ge(1))
        | (b2b_pair_ready & b2b_diff.abs().ge(1))
        | (three4_pair_ready & three4_diff.abs().ge(1))
        | (bye_pair_ready & bye_diff.abs().ge(1))
    )
    sched_direction = sgn(sched_signed, eps=0.10)
    sched_active = paired_directional_evidence & sched_direction.ne(0)
    sched_intensity = np.tanh(sched_signed.abs())
    install_expert('Schedule', sched_active, sched_direction, sched_intensity)

    # Audit/context fields. ByeProxy is now symmetric because the canonical
    # team-game state carries the opponent mirror directly.
    out['Brain_Schedule_Rest_Diff_Days'] = rest_diff.astype('float32')
    out['Brain_Schedule_Current_B2B'] = b2b_raw.fillna(0).gt(0).astype('int8')
    out['Brain_Schedule_Opp_B2B'] = opp_b2b_raw.fillna(0).gt(0).astype('int8')
    out['Brain_Schedule_Current_3in4'] = three4_raw.fillna(0).gt(0).astype('int8')
    out['Brain_Schedule_Opp_3in4'] = opp_three4_raw.fillna(0).gt(0).astype('int8')
    out['Brain_Schedule_Current_ByeProxy'] = bye_raw.fillna(0).gt(0).astype('int8')
    out['Brain_Schedule_Opp_ByeProxy'] = opp_bye_raw.fillna(0).gt(0).astype('int8')

    # ------------------------------------------------------------------
    # 9) PRICE/VALUE expert state. Direction comes from explicit mispricing.
    # ------------------------------------------------------------------
    mispricing = num('Market_Mispricing')
    if mispricing.isna().all():
        # Secondary leak-safe fallback: sharp-vs-rec probability gap is relative to
        # the current outcome and therefore has a clear sign.
        mispricing = num('Sharp_Rec_Prob_Gap')
    price_mag = pd.concat([
        num('Current_vs_Best_Line').abs(), num('Current_vs_Worst_Line').abs(),
        num('ML_Price_ZScore_vs_TeamHistory').abs(), num('Role_Price_Shift').abs(),
        num('Implied_Prob_Shift').abs()*10.0,
    ], axis=1).mean(axis=1, skipna=True).fillna(0)
    price_active = mispricing.notna() & mispricing.abs().ge(0.01)
    price_direction = sgn(mispricing, eps=0.01)
    price_intensity = np.maximum(np.tanh(price_mag), np.tanh(mispricing.abs().fillna(0)*8.0))
    install_expert('Price', price_active, price_direction, price_intensity)


    # ------------------------------------------------------------------
    # 10) HISTORICAL expert state.
    # Historical credibility is learned upstream from protected temporal OOF/shadow
    # performance. This layer only exposes state; it never changes deterministic
    # Pathi/Big Al rule definitions.
    # ------------------------------------------------------------------
    hist_prob = num('Historical_Core_Prob')
    hist_base = num('Historical_Core_Market_Baseline_Prob', default=0.5).fillna(0.5)
    hist_edge = num('Historical_Core_Edge')
    hist_edge = hist_edge.where(hist_edge.notna(), hist_prob - hist_base)
    hist_trust = num('Historical_Core_Trust', default=0).fillna(0).clip(0, 1)
    hist_active = num('Historical_Core_Active', default=0).fillna(0).eq(1) & hist_edge.notna() & hist_edge.abs().ge(0.0025) & hist_trust.gt(0)
    hist_direction = sgn(hist_edge, eps=0.0025)
    hist_intensity = (np.tanh(hist_edge.abs().fillna(0) * 8.0) * hist_trust).clip(0, 1)
    install_expert('Historical', hist_active, hist_direction, hist_intensity)
    out['Brain_Expert_Historical_Prob'] = hist_prob.astype('float32')
    out['Brain_Expert_Historical_Trust'] = hist_trust.astype('float32')
    out['Brain_Expert_Historical_Edge'] = hist_edge.astype('float32')
    out['Brain_Historical_Drift_Similarity'] = num('Historical_Core_Drift_Similarity', default=1).fillna(1).clip(0,1).astype('float32')
    out['Brain_Historical_Recency_Factor'] = num('Historical_Core_Recency_Factor', default=1).fillna(1).clip(0,1).astype('float32')
    out['Brain_Historical_Horizon_Agreement'] = num('Historical_Core_Horizon_Agreement', default=1).fillna(1).clip(0,1).astype('float32')
    out['Brain_Historical_Uncertainty'] = num('Historical_Core_Uncertainty', default=1).fillna(1).clip(0,1).astype('float32')
    # Named-system historical memory is exposed separately and may be learned by
    # Outcome AutoFS. It does not turn a system on/off and does not flip direction.
    for _fam in ('BigAl', 'Pathi'):
        out[f'Brain_{_fam}_Historical_Posterior_Prob'] = num(f'{_fam}_Historical_Posterior_Prob', default=0.5).fillna(0.5).astype('float32')
        out[f'Brain_{_fam}_Historical_Trust'] = num(f'{_fam}_Historical_Trust', default=0).fillna(0).clip(0,1).astype('float32')
        out[f'Brain_{_fam}_Historical_Sample'] = num(f'{_fam}_Historical_Sample', default=0).fillna(0).astype('float32')

    # ------------------------------------------------------------------
    # 11) NCAAF STATISTICAL expert state (V12).
    # Structural efficiency model is independently shadow-gated upstream.
    # ------------------------------------------------------------------
    stat_prob = num('NCAAF_Stat_Prob')
    stat_base = num('NCAAF_Stat_Market_Baseline_Prob', default=0.5).fillna(0.5)
    stat_edge = num('NCAAF_Stat_Edge')
    stat_edge = stat_edge.where(stat_edge.notna(), stat_prob - stat_base)
    stat_trust = num('NCAAF_Stat_Trust', default=0).fillna(0).clip(0,1)
    stat_active = num('NCAAF_Stat_Active', default=0).fillna(0).eq(1) & stat_edge.notna() & stat_edge.abs().ge(0.0025) & stat_trust.gt(0)
    stat_direction = sgn(stat_edge, eps=0.0025)
    stat_intensity = (np.tanh(stat_edge.abs().fillna(0)*10.0)*stat_trust).clip(0,1)
    install_expert('NCAAFStat', stat_active, stat_direction, stat_intensity)
    out['Brain_Expert_NCAAFStat_Prob'] = stat_prob.astype('float32')
    out['Brain_Expert_NCAAFStat_Trust'] = stat_trust.astype('float32')
    out['Brain_Expert_NCAAFStat_Edge'] = stat_edge.astype('float32')

    # ------------------------------------------------------------------
    # 12) Expert ensemble summaries from real active states only.
    # ------------------------------------------------------------------
    expert_names = ['BigAl','Pathi','Market','Power','Form','Schedule','Price','Historical']
    intensity_cols = [f'Brain_Expert_{n}_Intensity' for n in expert_names]
    active_cols = [f'Brain_Expert_{n}_Active' for n in expert_names]
    ex = out[intensity_cols].apply(pd.to_numeric, errors='coerce').fillna(0.0)
    ac = out[active_cols].apply(pd.to_numeric, errors='coerce').fillna(0).gt(0)
    # IMPORTANT: active and intensity frames have different column names.
    # Mask positionally, not by label, otherwise pandas aligns mismatched labels
    # and turns the entire active-intensity matrix into NaN.
    ex_active = ex.where(ac.to_numpy())
    out['Brain_Expert_Mean_Strength'] = ex_active.mean(axis=1, skipna=True).fillna(0).astype('float32')
    out['Brain_Expert_Max_Strength'] = ex.where(ac.to_numpy(), 0.0).max(axis=1).astype('float32')
    out['Brain_Expert_Dispersion'] = ex_active.std(axis=1, ddof=0, skipna=True).fillna(0).astype('float32')
    out['Brain_Expert_Active_Count'] = ac.sum(axis=1).astype('int8')

    # ------------------------------------------------------------------
    # 11) Directional agreement / disagreement (requires BOTH experts active).
    # ------------------------------------------------------------------
    def pair_state(a, b):
        aa = out[f'Brain_Expert_{a}_Active'].eq(1)
        bb = out[f'Brain_Expert_{b}_Active'].eq(1)
        da = pd.to_numeric(out[f'Brain_Expert_{a}_Direction'], errors='coerce').fillna(0)
        db = pd.to_numeric(out[f'Brain_Expert_{b}_Direction'], errors='coerce').fillna(0)
        eligible = aa & bb & da.ne(0) & db.ne(0)
        agree = (eligible & da.eq(db)).astype('int8')
        conflict = (eligible & da.eq(-db)).astype('int8')
        return eligible.astype('int8'), agree, conflict

    bp_elig, bp_agree, bp_conf = pair_state('BigAl','Pathi')
    bm_elig, bm_agree, bm_conf = pair_state('BigAl','Market')
    pm_elig, pm_agree, pm_conf = pair_state('Pathi','Market')
    bh_elig, bh_agree, bh_conf = pair_state('BigAl','Historical')
    ph_elig, ph_agree, ph_conf = pair_state('Pathi','Historical')
    mh_elig, mh_agree, mh_conf = pair_state('Market','Historical')
    out['Brain_BigAl_Pathi_Agreement'] = bp_agree
    out['Brain_BigAl_Pathi_Conflict'] = bp_conf
    out['Brain_BigAl_Market_Agreement'] = bm_agree
    out['Brain_BigAl_Market_Conflict'] = bm_conf
    out['Brain_Pathi_Market_Agreement'] = pm_agree
    out['Brain_Pathi_Market_Conflict'] = pm_conf
    out['Brain_BigAl_Historical_Agreement'] = bh_agree
    out['Brain_BigAl_Historical_Conflict'] = bh_conf
    out['Brain_Pathi_Historical_Agreement'] = ph_agree
    out['Brain_Pathi_Historical_Conflict'] = ph_conf
    out['Brain_Market_Historical_Agreement'] = mh_agree
    out['Brain_Market_Historical_Conflict'] = mh_conf
    # Backward-compatible 3-expert agreement remains unchanged.
    out['Brain_AllIndependent_Agree'] = (
        bp_elig.eq(1) & bm_elig.eq(1) & pm_elig.eq(1)
        & bp_agree.eq(1) & bm_agree.eq(1) & pm_agree.eq(1)
    ).astype('int8')
    out['Brain_AllCoreExperts_Agree'] = (
        out['Brain_AllIndependent_Agree'].eq(1)
        & bh_elig.eq(1) & ph_elig.eq(1) & mh_elig.eq(1)
        & bh_agree.eq(1) & ph_agree.eq(1) & mh_agree.eq(1)
    ).astype('int8')
    _pair_conf = [bp_conf,bm_conf,pm_conf,bh_conf,ph_conf,mh_conf]
    _pair_elig = [bp_elig,bm_elig,pm_elig,bh_elig,ph_elig,mh_elig]
    _pair_ag = [bp_agree,bm_agree,pm_agree,bh_agree,ph_agree,mh_agree]
    out['Brain_Conflict_Count'] = pd.concat(_pair_conf, axis=1).sum(axis=1).astype('int8')
    pair_eligible_count = pd.concat(_pair_elig, axis=1).sum(axis=1).astype(float)
    pair_agree_count = pd.concat(_pair_ag, axis=1).sum(axis=1).astype(float)
    out['Brain_Directional_Pair_Count'] = pair_eligible_count.astype('int8')
    out['Brain_Directional_Agreement_Rate'] = np.where(
        pair_eligible_count > 0, pair_agree_count/pair_eligible_count, np.nan
    ).astype('float32')

    # ------------------------------------------------------------------
    # 13) Uncertainty, durability, readiness. No inactive-family free credit.
    # ------------------------------------------------------------------
    active_count = out['Brain_Expert_Active_Count'].astype(float)
    data_ready = np.clip(active_count / 6.0, 0, 1)
    agree_rate = pd.to_numeric(out['Brain_Directional_Agreement_Rate'], errors='coerce')
    agreement = agree_rate.fillna(0.0).clip(0,1)
    conflict_rate = np.where(pair_eligible_count > 0,
                             out['Brain_Conflict_Count'].astype(float)/pair_eligible_count,
                             0.0)
    uncertainty = np.clip(
        0.45*out['Brain_Expert_Dispersion'].astype(float)
        + 0.35*(1.0-data_ready)
        + 0.20*np.asarray(conflict_rate, dtype=float), 0, 1
    )
    durability = 100.0*np.clip(
        0.25*agreement
        + 0.25*data_ready
        + 0.20*out['Brain_Expert_Market_Intensity'].astype(float)
        + 0.20*out['Brain_Expert_Max_Strength'].astype(float)
        + 0.10*np.clip(1.0-np.asarray(conflict_rate, dtype=float),0,1)
        - 0.30*uncertainty,
        0, 1,
    )
    out['Brain_Uncertainty_Proxy'] = pd.Series(uncertainty, index=idx).astype('float32')
    out['Brain_Edge_Durability'] = pd.Series(durability, index=idx).astype('float32')
    out['Brain_Decision_Readiness'] = np.clip(
        (durability/100.0) * data_ready * (1.0-0.5*uncertainty), 0, 1
    ).astype('float32')

    # Current implied probability, useful for future close/value meta heads.
    odds = num('Odds_Price')
    cur_ip = pd.Series(np.nan, index=idx, dtype='float64')
    pos = odds >= 0
    cur_ip.loc[pos & odds.notna()] = 100.0/(odds.loc[pos & odds.notna()] + 100.0)
    neg = odds < 0
    cur_ip.loc[neg & odds.notna()] = (-odds.loc[neg & odds.notna()])/((-odds.loc[neg & odds.notna()]) + 100.0)
    out['Brain_Current_Implied_Prob'] = cur_ip.astype('float32')

    return out

