def _system_feature_valid_for_sport(col: str, sport: str) -> bool:

    s = str(sport).upper().strip()

    c = str(col)

    # Postseason/championship/finals/elimination/final-home features are retired
    # from the learned Big Al contract. Legacy model bundles remain scoreable
    # because the prediction matrix already fills missing requested columns with 0.
    if _is_retired_bigal_feature_name(c):
        return False

    # Pathi legacy M1-M9 / road-favorite named systems are MLB-only.
    # They must never appear as zero-sample NCAAF/NFL historical systems.
    if c.startswith("Pathi_M") or c == "Pathi_RoadFavLost_StillFavorite_Screen":
        return s == "MLB"

    # Pathi football-only features
    if c.startswith("Pathi_FB_") or c == "Football_Key_Position_Bucket":
        return s in ("NFL", "NCAAF")

    # Big Al sport-specific systems

    if c.startswith("BigAl_NFL"):

        return s == "NFL"

    # IMPORTANT: test CFL before CF because "BigAl_CFL" also starts with "BigAl_CF".
    if c.startswith("BigAl_CFL"):

        return s == "CFL"

    if c.startswith("BigAl_CF"):

        return s == "NCAAF"

    if c.startswith("BigAl_CBB"):

        return s in ("NCAAB", "NCAAM")

    if c.startswith("BigAl_NBA"):

        return s == "NBA"

    if c.startswith("BigAl_MLB"):

        return s == "MLB"

    if c.startswith("BigAl_WNBA"):

        return s == "WNBA"

    if c.startswith("BigAl_Hoops_Revenge"):

        return s in ("NBA", "NCAAB", "NCAAM")

    # Generic BigAl_Context_* fields remain eligible across sports.
    # Everything else stays eligible

    return True

def safe_row_entropy(W: np.ndarray, eps: float = 1e-12) -> np.ndarray:
    """
    Row-wise Shannon entropy for nonnegative weights matrix W (n_rows x n_cols).
    - Handles rows with zero total mass safely (entropy -> 0).
    - Avoids NaN/inf and broadcasting issues.
    """
    W = np.asarray(W, dtype=np.float32)
    # sanitize inputs
    W = np.nan_to_num(W, nan=0.0, posinf=0.0, neginf=0.0)
    W = np.maximum(W, 0.0)

    row_sum = W.sum(axis=1, keepdims=True)             # shape (n, 1)
    # probability rows; where sum==0 produce zeros
    P = np.divide(W, np.maximum(row_sum, eps), out=np.zeros_like(W), where=row_sum > 0)

    # entropy per row: -sum(p*log p)
    # compute only where p>0 to avoid log(0)
    _plogp=np.zeros_like(P,dtype=np.float32)
    _pmask=P>0
    _plogp[_pmask]=P[_pmask]*np.log(P[_pmask])
    ent = -_plogp.sum(axis=1).astype(np.float32)
    return ent

