from sklearn.base import clone
from sklearn.metrics import roc_auc_score, log_loss

# =========================
# Hard leakage contract for learned heads.
# These fields contain the current game's realized result, score, or a target built
# from it.  Prior/lagged variants (e.g. Prev_ATS_Margin, Last_Matchup_Result) are NOT
# blocked here because they are known before the current game.
# =========================
_HARD_LEAK_EXACT = {
    "SHARP_HIT_BOOL", "SHARP_COVER_RESULT",
    "TARGET_OUTCOME_BOOL", "TARGET_SITUATION_BOOL",
    "TARGET_VALUE_BOOL", "TARGET_VALUE_REG",
    "EDGE_TARGET", "EDGE_CLASS",
    "Score_Home_Score", "Score_Away_Score", "Home_Score", "Away_Score",
    "Actual_Game_Total", "TOT_Actual_Total",
    "SU_Win", "SU_Loss", "SU_Margin",
    "ATS_Win", "ATS_Loss", "ATS_Cover_Margin",
    "Points_For", "Points_Against",
}

_VALUE_TARGET_DERIVED_EXACT = {
    # Direct outputs/ingredients of compute_ev_features_sharp_vs_rec.  They are
    # available pregame, but feeding them to the value regressor/classifier would
    # let the model reconstruct its own synthetic EV target rather than learn a
    # generalizable market-value relationship.
    "Truth_Fair_Prob_at_SharpLine", "Truth_Margin_Mu", "Truth_Sigma",
    "Truth_Fair_Prob_at_RecLine", "Rec_Implied_Prob",
    "EV_Sh_vs_Rec_Prob", "EV_Sh_vs_Rec_Dollar", "Kelly_Fraction",
}

def _is_hard_leak_feature(col: str) -> bool:
    """Central result/future-target leakage guard used by every learned lane.

    Brain_Target_* fields are explicitly future-market labels created for oracle/
    diagnostic work.  They must never be eligible predictors, including inside the
    V13 specialist overlay layer.
    """
    s = str(col)
    if s in _HARD_LEAK_EXACT:
        return True
    if s.startswith(("TARGET_", "Brain_Target_")):
        return True
    return s in {
        "Score_Home", "Score_Away", "Team_Score", "Opponent_Score",
        "Cover_Margin", "Raw_ATS", "__ATS", "__ATS_Current",
        "__Current_ATS_Margin", "Scored",
    }

def _head_forbidden_feature(col: str, head_name: str | None = None) -> bool:
    s = str(col)
    if _is_hard_leak_feature(s):
        return True
    if str(head_name or "").lower() == "value" and s in _VALUE_TARGET_DERIVED_EXACT:
        return True
    return False


# =========================
# Head-specific feature-family contract.
# Outcome remains broad except for raw Pathi/Big Al system state. Situation is intentionally restricted to prior/history/
# role/system context. Value is intentionally restricted to market price, line,
# movement, timing, liquidity, and book-consensus context.
#
# These are permissive family rules rather than a fixed list so newly-added
# Pathi/BigAl/history or market-microstructure features automatically route to the
# appropriate specialist without making all heads copies of the outcome model.
# =========================
def _is_raw_pathi_bigal_state_feature(col: str) -> bool:
    """Raw named-handicapper/system state. These fields belong only to the
    validation-gated V13.2 rule-expert layer, never to Core heads.
    """
    s = str(col or "")
    return s.lower().startswith(("pathi_", "bigal_", "system_"))


# Brain aggregates below are contaminated by Big Al / Pathi expert state because
# they are computed across the full expert ensemble.  Keeping them in Core would
# create a hidden second route even when the specialist gate is closed.
_HANDICAPPER_CONTAMINATED_BRAIN_EXACT = {
    "Brain_Expert_Mean_Strength", "Brain_Expert_Max_Strength",
    "Brain_Expert_Dispersion", "Brain_Expert_Active_Count",
    "Brain_Conflict_Count", "Brain_Directional_Pair_Count",
    "Brain_Directional_Agreement_Rate", "Brain_Uncertainty_Proxy",
    "Brain_Edge_Durability", "Brain_Decision_Readiness",
    "Brain_AllIndependent_Agree", "Brain_AllCoreExperts_Agree",
    "Brain_Overlay_Trust_Score", "Brain_Overlay_Trust_Active_Count",
    "Brain_Overlay_Raw_Active_Count", "Brain_Overlay_Exact_Active_Count",
    "Brain_Overlay_Tightener_Active_Count", "Brain_Overlay_Enhancer_Active_Count",
}

def _is_handicapper_core_forbidden_feature(col: str) -> bool:
    """True when a feature carries named Big Al/Pathi/system information.

    Generic football context remains legal in Core (rest, revenge, ATS history,
    key-number geometry, market movement, etc.).  Exact named systems, their
    historical memories, expert-state derivatives, cross-expert agreement fields,
    and ensemble summaries contaminated by those experts are specialist-only.
    """
    s = str(col or "")
    sl = s.lower()
    if sl.startswith(("pathi_", "bigal_", "system_", "mmi_", "opp_mmi_")):
        return True
    if s.startswith(("Brain_Expert_Pathi", "Brain_Expert_BigAl", "Brain_Pathi_", "Brain_BigAl_")):
        return True
    if s in _HANDICAPPER_CONTAMINATED_BRAIN_EXACT:
        return True
    if s.startswith("Brain_Overlay_"):
        return True
    # Any remaining Brain field explicitly naming either handicapper is derived
    # from that specialist and therefore cannot enter a supposedly pure Core.
    if s.startswith("Brain_") and ("BigAl" in s or "Pathi" in s):
        return True
    return False


def _head_feature_family_allowed(col: str, head_name: str | None = None) -> bool:
    s = str(col)
    sl = s.lower()
    head = str(head_name or "outcome").lower().strip()

    # V13.2.13 hard boundary: named Big Al / Pathi information is never a Core
    # predictor in Outcome, Situation, Value, or any future head.  It is evaluated
    # only by the source-backed per-system specialist engine.
    if _is_handicapper_core_forbidden_feature(s):
        return False

    if head == "outcome":
        # Statistical Brain probability state is also evaluated through its own
        # validation-gated residual route, never as a global AutoFS input.
        if s.startswith("NCAAF_Stat_") or s.startswith("Brain_Expert_NCAAFStat_"):
            return False
        return True

    if head == "situation":
        # Keep generic market-microstructure variables out of the situation head,
        # even when their names contain words such as H2H or role.
        situation_market_exclusions = (
            "prob_gap", "probgap", "sharp_", "rec_", "book_",
            "odds", "price_shift", "implied", "line_move", "line_std",
            "line_diff", "limit", "juice", "hold", "outlier",
            "marketleader", "crossmarket", "hybrid_", "clv",
            "liquidity", "booklift", "pctrank", "max_line", "min_line",
            "current_vs_",
        )
        if any(tok in sl for tok in situation_market_exclusions):
            return False

        # Prior/history/team-role/schedule families.  These tokens intentionally
        # favor information known before the current game and exclude generic
        # live market microstructure such as Sharp_Rec_Prob_Gap.
        situation_tokens = (
            "streak", "cover_rate", "cover_games", "cover_margin",
            "ats_", "_ats", "h2h_", "revenge", "last_matchup",
            "winpct", "loss_pct", "lossrate", "win_rate",
            "role_", "_role", "as_dog", "as_favorite",
            "home_dog", "road_dog", "home_favorite", "road_favorite",
            "usually_dog", "usually_favorite",
            "prev_", "prior", "last5", "last10", "season_rate",
            "days_since", "rest_", "is_b2b", "is_3in4", "games_last_",
            "schedule", "travel", "off_day",
            "postseason", "regular_season", "playoff", "preseason",
            "week_number", "game_week", "game_number", "final_two_",
            "conference", "series_", "defending_champion",
            "eliminated", "final_home_game",
            "after_win", "after_loss", "off_win", "off_loss",
            "on_cover_streak", "team_recent_", "opp_recent_",
            "team_fav_roi", "team_dog_roi", "road_favorite_roi",
            "dog_rate_", "favorite_rate_", "su_win", "su_loss",
        )
        return any(tok in sl for tok in situation_tokens)

    if head == "value":
        # Named handicapper systems were already excluded globally above; Value
        # remains an independent market/microstructure head.
        # Market/value/microstructure feature families.  The direct synthetic EV
        # target ingredients remain blocked separately by _head_forbidden_feature.
        value_prefixes = (
            "sharp_", "rec_", "book_", "marketleader_", "crossmarket_",
            "hybrid_", "line_", "odds_", "implied_", "impprob_",
            "spread_", "total_", "limit_", "clv_", "edge_", "value_",
            "steam_", "key_cross_", "crossed_key_", "current_vs_",
        )
        if sl.startswith(value_prefixes):
            return True

        value_tokens = (
            "sharp", "book", "odds", "price", "implied",
            "recskew", "_rec_", "vs_rec", "rec_line", "rec_odds",
            "prob_gap", "probgap", "hold", "juice", "vig",
            "line_move", "line_diff", "line_std", "line_totalmag",
            "line_phasemag", "opening_line", "open_line",
            "spread_gap", "total_gap", "market_gap", "crossmarket",
            "consensus", "outlier", "pctrank", "liquidity", "limit",
            "clv", "fair_line", "fair_odds", "edge_proxy",
            "timing", "late_share", "early_share", "midmag",
            "earlymag", "latemag", "velocity", "direction_changes",
            "max_line", "min_line", "best_line", "worst_line",
            "key_cross", "crossed_key", "dist_to_", "corridor",
            "resist", "reversal", "booklift", "rev_x_booklift",
            "role_price_shift", "ml_price_zscore",
            "current_impliedprob", "first_odds", "open_odds",
            "delta_limit", "delta_vs_sharp",
        )
        return any(tok in sl for tok in value_tokens)

    # Unknown specialist heads default to broad rather than silently deleting data.
    return True

# =========================
# =========================
# 1) CV EVAL BLOCK (OLD/FAST interface, backend-safe)
#    ✅ patched fallback to not throw away sparse "signal #1" features
# =========================
def _cv_auc_for_feature_set(
    model_proto, X, y, folds, feature_list, *,
    log_func=print,
    debug=False,
    return_oof=True,

    enable_feature_flips=False,
    max_feature_flips=0,
    orient_features=False,
    orient_passes=1,

    auc_weight=1.0,
    ll_weight=0.15,
    brier_weight=0.10,
    eps=1e-6,

    cv_mode: str = "full",
    quick_folds_n: int = 10,
    compute_ll_brier: bool = True,
    max_folds: int | None = None,

    abort_if_cannot_beat_score=None,
    abort_margin=0.0,

    game_keys=None,
    enforce_no_game_overlap=True,
    leak_col_patterns=None,
    drop_forbidden_features=True,
    fallback_to_all_available_features=True,
    require_numeric_features=True,
    min_non_nan_frac=0.001,
    sample_weight=None,

    # backward compat
    **_ignored_kwargs,
):
    """
    OLD/FAST behavior:
      - Numeric conversion once (cached)
      - XGB native fast path when possible
      - cv_mode="quick" uses first quick_folds_n folds
      - Full metrics only if compute_ll_brier=True and return_oof available
      - Optional greedy feature flips (bounded)
    """

    from sklearn.base import clone
    from sklearn.metrics import roc_auc_score, log_loss

    # -----------------------------
    # sparse whitelist (for fallback "all usable features")
    # -----------------------------
    def _is_sparse_ok_name(c: str) -> bool:
        s = str(c)
        return (
            s.startswith("Steam_") or
            s.startswith("SharpMove_") or
            s.startswith("OddsMove_") or
            ("Reversal" in s) or
            ("Resistance" in s)
        )

    # -----------------------------
    # normalize y + folds
    # -----------------------------
    y = np.asarray(y, int).reshape(-1)
    n = int(len(y))
    sw = np.ones(n, dtype=np.float64) if sample_weight is None else np.asarray(sample_weight, dtype=np.float64).reshape(-1)
    if len(sw) != n:
        raise ValueError(f"sample_weight length mismatch: {len(sw)} != {n}")
    sw[~np.isfinite(sw)] = 0.0
    if float(sw.sum()) <= 0:
        sw[:] = 1.0

    if folds is None:
        folds_list = []
    elif isinstance(folds, (list, tuple)) and len(folds) > 0:
        folds_list = list(folds)
    elif hasattr(folds, "split"):
        idx = np.zeros((n, 1), dtype=np.float32)
        folds_list = []
        for tr, va in folds.split(idx, y):
            folds_list.append((tr, va))
    else:
        folds_list = []

    folds_list = [(np.asarray(tr, np.int64), np.asarray(va, np.int64)) for tr, va in folds_list]
    if max_folds is not None and folds_list:
        folds_list = folds_list[: int(max_folds)]
    if cv_mode == "quick" and folds_list:
        folds_list = folds_list[: max(1, int(quick_folds_n))]

    if not folds_list:
        return {
            "feature_list": list(feature_list or []),
            "oof_proba": (np.full(n, np.nan, dtype=float) if return_oof else None),
            "auc": float("nan"),
            "logloss": float("nan"),
            "brier": float("nan"),
            "score": float("-inf"),
            "aborted": False,
        }

    # -----------------------------
    # leak guard
    # -----------------------------
    if leak_col_patterns is None:
        leak_col_patterns = ["SHARP_COVER_RESULT"]

    def _is_forbidden(col: str) -> bool:
        s = str(col)
        return _is_hard_leak_feature(s) or any(p in s for p in leak_col_patterns)

    # -----------------------------
    # matrix cache (keyed by df identity + manager identity)
    # -----------------------------
    # -----------------------------
    # matrix cache (keyed by df identity + manager identity)
    # -----------------------------
    _MAT_CACHE = getattr(_cv_auc_for_feature_set, "_MAT_CACHE", {})
    mgr_id = id(getattr(X, "_mgr", X))
    cols_sig = (len(X.columns), hash(tuple(map(str, X.columns))))
    sig = (id(X), mgr_id, X.shape, cols_sig, bool(require_numeric_features))
    
    if sig in _MAT_CACHE:
        X_all_mat, col_ix, nn_frac_raw, var_raw = _MAT_CACHE[sig]
    else:
        if require_numeric_features:
            X_num_all = X.apply(pd.to_numeric, errors="coerce")
        else:
            X_num_all = X.copy()
    
        # Replace inf first
        X_num_all = X_num_all.replace([np.inf, -np.inf], np.nan)
    
        # --- compute raw presence/variance BEFORE fill ---
        X_raw_mat = X_num_all.to_numpy(dtype=np.float32, copy=False)
        finite_raw = np.isfinite(X_raw_mat)
        nn_frac_raw = finite_raw.mean(axis=0)
    
        with np.errstate(invalid="ignore"):
            X_tmp = np.where(finite_raw, X_raw_mat, np.nan)
            var_raw = np.nanvar(X_tmp, axis=0)
    
        # --- now fill for selection-time stability ---
        X_num_all = X_num_all.fillna(0.0)
    
        # final cached matrix used for modeling
        X_all_mat = X_num_all.to_numpy(dtype=np.float32, copy=False)
        col_ix = {c: i for i, c in enumerate(X_num_all.columns)}
    
        # keep cache bounded
        if len(_MAT_CACHE) > 8:
            _MAT_CACHE.clear()
    
        _MAT_CACHE[sig] = (X_all_mat, col_ix, nn_frac_raw, var_raw)
        _cv_auc_for_feature_set._MAT_CACHE = _MAT_CACHE

    # -----------------------------
    # sanitize feature list
    # -----------------------------
    feats = [f for f in (feature_list or []) if f in col_ix]

    forbidden = [f for f in feats if _is_forbidden(f)]
    if forbidden:
        msg = f"[LEAK-GUARD] Forbidden feature(s) present: {forbidden[:50]}{'...' if len(forbidden)>50 else ''}"
        if drop_forbidden_features:
            if debug:
                log_func(msg + " (dropping)")
            feats = [f for f in feats if f not in forbidden]
        else:
            raise RuntimeError(msg)

    if (not feats) and fallback_to_all_available_features:
        nn_frac = nn_frac_raw
        var = var_raw

        cols_list = list(col_ix.keys())
        sparse_ok = np.fromiter((_is_sparse_ok_name(c) for c in cols_list), dtype=bool, count=len(cols_list))

        # two-tier presence: keep dense cols normally; allow sparse signal cols at lower floor
        usable = ((nn_frac >= float(min_non_nan_frac)) | (sparse_ok & (nn_frac >= 0.005))) & (var > 0.0)

        feats = [c for c, j in col_ix.items() if usable[j] and (not _is_forbidden(c))]

    if not feats:
        return {
            "feature_list": [],
            "oof_proba": (np.full(n, np.nan, dtype=float) if return_oof else None),
            "auc": float("nan"),
            "logloss": float("nan"),
            "brier": float("nan"),
            "score": float("-inf"),
            "aborted": False,
        }

    feats = list(dict.fromkeys(feats))
    cols_idx = [col_ix[f] for f in feats]
    X_mat = np.take(X_all_mat, cols_idx, axis=1).astype(np.float32, copy=False)

    # -----------------------------
    # no-overlap guard
    # -----------------------------
    def _assert_no_game_overlap(tr_idx, va_idx):
        if not enforce_no_game_overlap or game_keys is None:
            return
        g = np.asarray(game_keys)
        inter = set(map(str, g[tr_idx])) & set(map(str, g[va_idx]))
        if inter:
            raise RuntimeError(f"[LEAK] Game overlap between train/val: {len(inter)} games. Sample={list(inter)[:10]}")

    # -----------------------------
    # xgb detection + params
    # -----------------------------
    try:
        use_xgb = bool(_is_xgb_classifier(model_proto))
    except Exception:
        use_xgb = False

    xgb_params = None
    xgb_num_round = None
    if use_xgb:
        import xgboost as xgb  # noqa
        xgb_params, xgb_num_round = _xgb_params_from_proto(model_proto)
        xgb_params = dict(xgb_params or {})
        if "nthread" not in xgb_params and "n_jobs" not in xgb_params:
            xgb_params["nthread"] = 0

    # -----------------------------
    # core eval
    # -----------------------------
    def _safe_predict_proba_pos(mdl, Xv):
        p = mdl.predict_proba(Xv)
        return p[:, 1] if getattr(p, "ndim", 1) == 2 else np.asarray(p).ravel()

    def _oof_eval(X_local):
        oof = np.full(n, np.nan, dtype=np.float32) if (return_oof or compute_ll_brier) else None
        auc_fold_vals = []
        do_abort = abort_if_cannot_beat_score is not None and np.isfinite(abort_if_cannot_beat_score)
        n_folds = len(folds_list)

        if use_xgb:
            import xgboost as xgb  # noqa
            d_all = xgb.DMatrix(np.ascontiguousarray(X_local, dtype=np.float32), label=y, weight=sw)

            def _fit_predict(tr_idx, va_idx):
                d_tr = d_all.slice(tr_idx)
                d_va = d_all.slice(va_idx)
                booster = xgb.train(
                    xgb_params,
                    d_tr,
                    num_boost_round=int(xgb_num_round),
                    evals=[(d_va, "val")],
                    # Generic CV evaluator intentionally keeps historical/final validation
                    # semantics unchanged. AutoFS candidate evaluators below use real
                    # early stopping for speed; this outer evaluator is also used by
                    # final/diagnostic CV paths where fold-selected stopping would alter
                    # the benchmark contract.
                    early_stopping_rounds=None,
                    verbose_eval=False,
                )
                if hasattr(booster, "best_iteration") and booster.best_iteration is not None:
                    try:
                        return booster.predict(d_va, iteration_range=(0, int(booster.best_iteration) + 1))
                    except TypeError:
                        ntl = int(getattr(booster, "best_ntree_limit", 0) or 0)
                        return booster.predict(d_va, ntree_limit=ntl if ntl > 0 else None)
                return booster.predict(d_va)

        else:
            def _fit_predict(tr_idx, va_idx):
                mdl = clone(model_proto)
                try:
                    mdl.fit(X_local[tr_idx, :], y[tr_idx], sample_weight=sw[tr_idx])
                except TypeError:
                    mdl.fit(X_local[tr_idx, :], y[tr_idx])
                return _safe_predict_proba_pos(mdl, X_local[va_idx, :])

        for tr_idx, va_idx in folds_list:
            _assert_no_game_overlap(tr_idx, va_idx)
            proba = np.asarray(_fit_predict(tr_idx, va_idx), float).ravel()
            proba = np.clip(proba, eps, 1.0 - eps)

            if oof is not None:
                oof[va_idx] = proba.astype(np.float32, copy=False)

            try:
                auc_fold = roc_auc_score(y[va_idx], proba, sample_weight=sw[va_idx])
                if not np.isfinite(auc_fold):
                    auc_fold = 0.5
            except Exception:
                auc_fold = 0.5
            auc_fold_vals.append(float(auc_fold))

            if do_abort:
                left = n_folds - len(auc_fold_vals)
                best_possible_auc = (sum(auc_fold_vals) + left * 1.0) / float(n_folds)
                best_possible_score = float(auc_weight) * float(best_possible_auc)
                if best_possible_score < float(abort_if_cannot_beat_score) + float(abort_margin):
                    return {
                        "oof": (oof if (oof is not None) else None),
                        "auc": float("nan"),
                        "logloss": float("nan"),
                        "brier": float("nan"),
                        "score": float("-inf"),
                        "aborted": True,
                        "auc_fold_mean": float("nan"),
                    }

        auc_fold_mean = float(np.mean(auc_fold_vals)) if auc_fold_vals else float("nan")

        if cv_mode == "quick":
            auc_used = auc_fold_mean
        else:
            if oof is None:
                auc_used = auc_fold_mean
            else:
                valid = np.isfinite(oof)
                y_v = y[valid]
                p_v = np.clip(oof[valid].astype(float), eps, 1.0 - eps)
                w_v = sw[valid]
                auc_used = roc_auc_score(y_v, p_v, sample_weight=w_v) if (len(y_v) >= 2 and len(np.unique(y_v)) >= 2) else float("nan")

        if compute_ll_brier and (oof is not None):
            valid = np.isfinite(oof)
            y_v = y[valid]
            p_v = np.clip(oof[valid].astype(float), eps, 1.0 - eps)
            w_v = sw[valid]
            ll = log_loss(y_v, p_v, labels=[0, 1], sample_weight=w_v)
            br = float(np.average((p_v - y_v) ** 2, weights=w_v))
        else:
            ll = float("nan")
            br = float("nan")

        score = float("-inf")
        if np.isfinite(auc_used):
            score = float(auc_weight) * float(auc_used)
            if compute_ll_brier and np.isfinite(ll) and np.isfinite(br):
                score = score - (float(ll_weight) * float(ll)) - (float(brier_weight) * float(br))

        return {
            "oof": (oof if oof is not None else None),
            "auc": float(auc_used),
            "auc_fold_mean": float(auc_fold_mean),
            "logloss": float(ll),
            "brier": float(br),
            "score": float(score),
            "aborted": False,
        }

    base = _oof_eval(X_mat)
    best = dict(base)
    flip_map = {}

    # -----------------------------
    # OPTIONAL flips/orientation (unchanged)
    # -----------------------------
    def _auto_flip_mode(arr1d):
        arr1d = np.asarray(arr1d, dtype=np.float32)
        if not np.isfinite(arr1d).any():
            return "none"
        x_nan = np.where(np.isfinite(arr1d), arr1d, np.nan)
        mn = np.nanmin(x_nan)
        mx = np.nanmax(x_nan)
        return "one_minus" if (mn >= -1e-3 and mx <= 1.0 + 1e-3) else "negate"

    def _apply_flip_inplace(col, mode: str):
        if mode == "one_minus":
            np.subtract(np.float32(1.0), col, out=col)
        elif mode == "negate":
            np.negative(col, out=col)

    if (enable_feature_flips or orient_features) and max_feature_flips and X_mat.shape[1] > 0 and np.isfinite(best.get("score", np.nan)):
        X_try = X_mat.copy()
        chosen = 0
        cand_js = list(range(X_try.shape[1]))

        for _pass in range(int(max(1, orient_passes))):
            if chosen >= int(max_feature_flips):
                break

            best_gain = 0.0
            best_j = None
            best_mode = None
            best_res = None

            for j in cand_js:
                col = X_try[:, j]
                orig = col.copy()

                mode = _auto_flip_mode(orig)
                if mode == "none":
                    continue

                _apply_flip_inplace(col, mode)
                res = _oof_eval(X_try)
                col[:] = orig

                if res.get("aborted", False):
                    continue

                gain = float(res.get("score", -1e18)) - float(best.get("score", -1e18))
                if gain > best_gain + 1e-12:
                    best_gain = gain
                    best_j = j
                    best_mode = mode
                    best_res = res

            if best_j is None:
                break

            _apply_flip_inplace(X_try[:, best_j], best_mode)
            feat_name = feats[best_j]
            flip_map[feat_name] = {"flipped": True, "mode": best_mode}
            best = dict(best_res)
            chosen += 1

            if debug:
                log_func(f"[CV-FLIP] ✅ flip {feat_name} mode={best_mode} Δscore={best_gain:+.6f}")

    out = dict(best)
    out["feature_list"] = list(feats)
    out["flip_map"] = dict(flip_map)
    out["oof_proba"] = (best.get("oof").astype(float) if (return_oof and best.get("oof") is not None) else None)

    # legacy aliases
    out["oof_auc_best"] = float(out.get("auc", float("nan")))
    out["oof_logloss_best"] = float(out.get("logloss", float("nan")))
    out["oof_brier_best"] = float(out.get("brier", float("nan")))
    out["oof_score_best"] = float(out.get("score", float("-inf")))

    out["oof_auc"] = out["oof_auc_best"]
    out["oof_logloss"] = out["oof_logloss_best"]
    out["oof_brier"] = out["oof_brier_best"]
    out["oof_score"] = out["oof_score_best"]

    if debug:
        log_func(
            f"[CV] k={len(out['feature_list'])} auc={out.get('auc', float('nan')):.6f} "
            f"auc_fold_mean={out.get('auc_fold_mean', float('nan')):.6f} "
            f"ll={out.get('logloss', float('nan')):.6f} brier={out.get('brier', float('nan')):.6f} "
            f"score={out.get('score', float('nan')):.6f} cv_mode={cv_mode}"
        )

    return out

# =========================
# 2) AUTO SELECT BLOCK (OLD/FAST matrix-backed forward selection)
#    ✅ patched to accept more tiny-lift signal features early (still fast)
# =========================
def _auto_select_k_by_auc(
    model_proto, X, y, folds, ordered_features, *,
    min_k=None,
    max_k=None,

    # --- MORE SIGNAL defaults ---
    patience=200,                 # was 160 (stops later → finds weaker features)
    min_improve=1e-5,              # was 1e-7 (allow tiny lifts; rely on LL/Brier + CV)

    verbose=False,
    log_func=print,
    debug=False,
    debug_every=25,

    # --- loosen calibration guards a bit (still protects you) ---
    max_ll_increase=0.05,         # stability guard: reject large calibration degradation
    max_brier_increase=0.02,      # stability guard: reject large probability-error degradation

    orient_features=False,
    enable_feature_flips=False,
    max_feature_flips=None,
    orient_passes=1,

    force_full_scan=True, 

    fallback_to_all_available_features=True,
    require_present_in_X=True,

    accept_metric: str = "auc",
    flips_after_selection: bool = True,

    allow_candidate_flip: bool = True,
    flip_gain_min: float = 0.0,

    must_keep: list[str] | None = None,
    baseline_feats: list[str] | None = None,

    # --- speed knobs ---
    quick_screen: bool = True,
    quick_folds: int = 3,          # fast triage; full time-forward CV still decides acceptance
    quick_accept: float = 0.0,    # kept for compat (unused)
    quick_drop: float = 0.0,      # kept for compat (unused)
    score_quick_tolerance: float = 0.004,  # generous 3-fold triage; full score still decides

    abort_margin_cv: float = -1e-6,  # was 0.0 (more permissive; abort less)

    time_budget_s: float = 1e21,
    resume_state: dict | None = None,
    max_total_evals: int | None = None,

    psi_fn=None,
    psi_max: float | None = None,
    sample_weight=None,

    # backward compat
    **_ignored_kwargs,
):
    """
    OLD/FAST forward selection (tuned for MORE SIGNAL):
      - less aggressive quick gating (more quick folds, more permissive abort)
      - less aggressive reject margins
      - near-miss throttling disabled (was skipping 2/3 of near-misses)
      - selection-time XGB regularization no longer tightened (was suppressing weak signals)
    """
    import time

    from sklearn.base import clone
    from sklearn.metrics import roc_auc_score, log_loss

    t0 = time.time()
    y_arr = np.asarray(y, int).reshape(-1)
    n = int(len(y_arr))
    sw = np.ones(n, dtype=np.float64) if sample_weight is None else np.asarray(sample_weight, dtype=np.float64).reshape(-1)
    if len(sw) != n:
        raise ValueError(f"sample_weight length mismatch: {len(sw)} != {n}")
    sw[~np.isfinite(sw)] = 0.0
    if float(sw.sum()) <= 0:
        sw[:] = 1.0
    if n == 0:
        return [], None, {"done": True, "reason": "empty_y"}

    # -------------------------
    # normalize folds
    # -------------------------
    if folds is None:
        folds_list = []
    elif isinstance(folds, (list, tuple)) and len(folds) > 0:
        folds_list = list(folds)
    elif hasattr(folds, "split"):
        idx = np.zeros((n, 1), dtype=np.float32)
        folds_list = []
        for tr, va in folds.split(idx, y_arr):
            folds_list.append((tr, va))
    else:
        folds_list = []

    folds_list = [(np.asarray(tr, np.int64), np.asarray(va, np.int64)) for tr, va in folds_list]
    if not folds_list:
        return [], None, {"done": True, "reason": "no_folds"}

    # -------------------------
    # candidate list
    # -------------------------
    ordered = list(ordered_features) if ordered_features is not None else []
    if require_present_in_X and hasattr(X, "columns"):
        ordered = [f for f in ordered if f in X.columns]
    if (not ordered) and fallback_to_all_available_features and hasattr(X, "columns"):
        ordered = list(X.columns)
    if not ordered:
        return [], None, {"done": True, "reason": "no_candidates"}

    must_keep = must_keep or []
    mk = [m for m in must_keep if (not hasattr(X, "columns")) or (m in X.columns)]
    ordered = list(dict.fromkeys(mk + ordered))

    if max_k is None:
        max_k = len(ordered)
    max_k = int(min(max_k, len(ordered)))

    if min_k is None:
        min_k = len(mk)
    min_k = int(max(len(mk), min(int(min_k), max_k)))

    if verbose:
        log_func(f"[AUTO-FEAT] seed(min_k)={min_k} must_keep={len(mk)} max_k={max_k} candidates={len(ordered)}")

    # -------------------------
    # evaluate ALL + baseline (for signal sanity)
    # -------------------------
    all_feats = list(ordered)
    all_res = _cv_auc_for_feature_set(
        model_proto, X, y_arr, folds_list, all_feats,
        log_func=log_func,
        debug=True,
        return_oof=False,
        orient_features=False,
        enable_feature_flips=False,
        cv_mode="full",
        sample_weight=sw,
    )
    if verbose and isinstance(all_res, dict):
        log_func(
            f"[ALL-FEATS CV] auc={all_res.get('auc', float('nan')):.4f} "
            f"ll={all_res.get('logloss', float('nan')):.4f} "
            f"brier={all_res.get('brier', float('nan')):.4f} "
            f"score={all_res.get('score', float('nan')):.4f} "
            f"n_feats={len(all_feats)}"
        )

    if baseline_feats is None:
        baseline_feats = mk
    base_feats = [f for f in (baseline_feats or []) if (not hasattr(X, "columns")) or (f in X.columns)]
    if base_feats:
        base_res = _cv_auc_for_feature_set(
            model_proto, X, y_arr, folds_list, base_feats,
            log_func=log_func,
            debug=True,
            return_oof=False,
            cv_mode="full",
            sample_weight=sw,
        )
        if verbose and isinstance(base_res, dict):
            lift_auc = float(all_res.get("auc", 0.5)) - float(base_res.get("auc", 0.5))
            lift_ll  = float(base_res.get("logloss", float("nan"))) - float(all_res.get("logloss", float("nan")))
            log_func(
                f"[SIGNAL CHECK] baseline_auc={base_res.get('auc', float('nan')):.4f} "
                f"all_auc={all_res.get('auc', float('nan')):.4f} "
                f"Δauc={lift_auc:+.4f} | "
                f"baseline_ll={base_res.get('logloss', float('nan')):.4f} "
                f"all_ll={all_res.get('logloss', float('nan')):.4f} "
                f"Δll={lift_ll:+.4f}"
            )

    # -------------------------
    # helpers
    # -------------------------
    accept_metric = str(accept_metric or "auc").lower()
    if accept_metric not in {"auc", "score"}:
        accept_metric = "auc"

    def _metric(res):
        if res is None:
            return float("-inf") if accept_metric == "score" else float("nan")
        return float(res.get("score", float("-inf"))) if accept_metric == "score" else float(res.get("auc", float("nan")))

    def _accept_ok(val_try, best_val, ll_try, best_ll, br_try, best_br, *, min_improve_eff: float):
        ll_ok = (not np.isfinite(ll_try)) or (not np.isfinite(best_ll)) or (ll_try <= float(best_ll) + float(max_ll_increase))
        br_ok = (not np.isfinite(br_try)) or (not np.isfinite(best_br)) or (br_try <= float(best_br) + float(max_brier_increase))
        if not (ll_ok and br_ok):
            return False
        if not np.isfinite(val_try):
            return False
        if not np.isfinite(best_val):
            return True
        return bool(val_try >= float(best_val) + float(min_improve_eff))

    # quick folds subset
    qn = int(max(1, quick_folds)) if (quick_screen and len(folds_list) > 1) else len(folds_list)
    folds_quick = folds_list[:qn]
    folds_full = folds_list

    # numeric matrix once

    X_num_all = X.apply(pd.to_numeric, errors="coerce")
    X_num_all = X_num_all.replace([np.inf, -np.inf], np.nan).fillna(0.0)
    # Match production scoring exactly: missing features are neutral zero.
    # This avoids train/deploy preprocessing drift and uses no future covariate
    # distribution information.
    X_all_mat = X_num_all.to_numpy(dtype=np.float32, copy=False)
    col_ix = {c: i for i, c in enumerate(X_num_all.columns)}


    # xgb config
    try:
        use_xgb = bool(_is_xgb_classifier(model_proto))
    except Exception:
        use_xgb = False

    xgb_params = None
    xgb_num_round = None
    if use_xgb:
        import xgboost as xgb  # noqa
        xgb_params, xgb_num_round = _xgb_params_from_proto(model_proto)
        xgb_params = dict(xgb_params or {})
        # AutoFS evaluates folds sequentially, so let each XGBoost fit use a small
        # CPU pool instead of inheriting the search estimator's n_jobs=1.
        try:
            _autofs_threads=int(os.getenv("AUTOFS_XGB_THREADS",str(min(4,os.cpu_count() or 1))))
        except Exception:
            _autofs_threads=min(4,os.cpu_count() or 1)
        xgb_params["nthread"]=max(1,int(_autofs_threads))

        # A monotonic sign flip contains no new information for a tree model:
        # XGBoost can split either direction on the same variable.  Avoid up to
        # two additional CV passes per candidate.
        allow_candidate_flip=False
        flips_after_selection=False
        orient_features=False
        enable_feature_flips=False

        # --- MORE SIGNAL: do NOT tighten regularization during selection ---
        # (the old *1.5 lambda + min_child_weight>=2 suppresses weak/rare signal)
        xgb_params["reg_lambda"] = float(xgb_params.get("reg_lambda", 1.0)) * 1.0
        xgb_params["min_child_weight"] = max(float(xgb_params.get("min_child_weight", 1.0)), 1.0)

        if "max_leaves" in xgb_params:
            xgb_params["max_leaves"] = int(xgb_params["max_leaves"])

    # flip helpers
    def _auto_flip_mode(arr1d):
        arr1d = np.asarray(arr1d, dtype=np.float32)
        if not np.isfinite(arr1d).any():
            return "none"
        x_nan = np.where(np.isfinite(arr1d), arr1d, np.nan)
        mn = np.nanmin(x_nan)
        mx = np.nanmax(x_nan)
        return "one_minus" if (mn >= -1e-3 and mx <= 1.0 + 1e-3) else "negate"

    def _apply_flip_inplace(col, mode: str):
        if mode == "one_minus":
            np.subtract(np.float32(1.0), col, out=col)
        elif mode == "negate":
            np.negative(col, out=col)

    flip_mode_cache = {}
    if allow_candidate_flip:
        for f in ordered:
            if f in col_ix:
                flip_mode_cache[f] = _auto_flip_mode(X_all_mat[:, col_ix[f]])

    # -------------------------
    # evaluators
    # -------------------------
    def _cv_eval_auc_only(X_mat, folds_use, *, abort_best_auc=None, early_stop_rounds=None):
        eps2 = 1e-7
        auc_fold_vals = []
        n_folds = len(folds_use)
        do_abort = (abort_best_auc is not None) and np.isfinite(abort_best_auc)

        if use_xgb:
            import xgboost as xgb  # noqa
            d_all = xgb.DMatrix(np.ascontiguousarray(X_mat, dtype=np.float32), label=y_arr, weight=sw)

            def _fit_predict(tr_idx, va_idx):
                d_tr = d_all.slice(tr_idx)
                d_va = d_all.slice(va_idx)
                booster = xgb.train(
                    xgb_params,
                    d_tr,
                    num_boost_round=int(xgb_num_round),
                    evals=[(d_va, "val")],
                    early_stopping_rounds=(int(early_stop_rounds) if early_stop_rounds else None),
                    verbose_eval=False,
                )
                if hasattr(booster, "best_iteration") and booster.best_iteration is not None:
                    try:
                        return booster.predict(d_va, iteration_range=(0, int(booster.best_iteration) + 1))
                    except TypeError:
                        ntl = int(getattr(booster, "best_ntree_limit", 0) or 0)
                        return booster.predict(d_va, ntree_limit=ntl if ntl > 0 else None)
                return booster.predict(d_va)
        else:
            def _fit_predict(tr_idx, va_idx):
                mdl = clone(model_proto)
                try:
                    mdl.fit(X_mat[tr_idx, :], y_arr[tr_idx], sample_weight=sw[tr_idx])
                except TypeError:
                    mdl.fit(X_mat[tr_idx, :], y_arr[tr_idx])
                p = mdl.predict_proba(X_mat[va_idx, :])
                return p[:, 1] if getattr(p, "ndim", 1) == 2 else np.asarray(p).ravel()

        for tr_idx, va_idx in folds_use:
            proba = np.asarray(_fit_predict(tr_idx, va_idx), float).ravel()
            proba = np.clip(proba, eps2, 1 - eps2)

            try:
                auc_fold = roc_auc_score(y_arr[va_idx], proba, sample_weight=sw[va_idx])
                if not np.isfinite(auc_fold):
                    auc_fold = 0.5
            except Exception:
                auc_fold = 0.5
            auc_fold_vals.append(float(auc_fold))

            if do_abort:
                left = n_folds - len(auc_fold_vals)
                best_possible_auc = (sum(auc_fold_vals) + left * 1.0) / float(n_folds)
                if best_possible_auc < float(abort_best_auc) + float(abort_margin_cv):
                    return {"auc": float("nan"), "aborted": True, "auc_fold_mean": float("nan")}

        auc_fold_mean = float(np.mean(auc_fold_vals)) if auc_fold_vals else float("nan")
        return {"auc": auc_fold_mean, "aborted": False, "auc_fold_mean": auc_fold_mean}

    def _cv_eval_full_metrics(X_mat, folds_use, *, early_stop_rounds=None):
        eps2 = 1e-7
        oof = np.full(n, np.nan, dtype=np.float32)
        fold_aucs, fold_lls, fold_briers, fold_scores = [], [], [], []

        if use_xgb:
            import xgboost as xgb  # noqa
            d_all = xgb.DMatrix(np.ascontiguousarray(X_mat, dtype=np.float32), label=y_arr, weight=sw)

            def _fit_predict(tr_idx, va_idx):
                d_tr = d_all.slice(tr_idx)
                d_va = d_all.slice(va_idx)
                booster = xgb.train(
                    xgb_params,
                    d_tr,
                    num_boost_round=int(xgb_num_round),
                    evals=[(d_va, "val")],
                    early_stopping_rounds=(int(early_stop_rounds) if early_stop_rounds else None),
                    verbose_eval=False,
                )
                if hasattr(booster, "best_iteration") and booster.best_iteration is not None:
                    try:
                        return booster.predict(d_va, iteration_range=(0, int(booster.best_iteration) + 1))
                    except TypeError:
                        ntl = int(getattr(booster, "best_ntree_limit", 0) or 0)
                        return booster.predict(d_va, ntree_limit=ntl if ntl > 0 else None)
                return booster.predict(d_va)
        else:
            def _fit_predict(tr_idx, va_idx):
                mdl = clone(model_proto)
                try:
                    mdl.fit(X_mat[tr_idx, :], y_arr[tr_idx], sample_weight=sw[tr_idx])
                except TypeError:
                    mdl.fit(X_mat[tr_idx, :], y_arr[tr_idx])
                p = mdl.predict_proba(X_mat[va_idx, :])
                return p[:, 1] if getattr(p, "ndim", 1) == 2 else np.asarray(p).ravel()

        for tr_idx, va_idx in folds_use:
            proba = np.asarray(_fit_predict(tr_idx, va_idx), float).ravel()
            proba = np.clip(proba, eps2, 1 - eps2)
            oof[va_idx] = proba.astype(np.float32, copy=False)
            yy = y_arr[va_idx]
            if len(yy) >= 2 and np.unique(yy).size >= 2:
                _wv = sw[va_idx]
                fa = float(roc_auc_score(yy, proba, sample_weight=_wv))
                fl = float(log_loss(yy, proba, labels=[0, 1], sample_weight=_wv))
                fb = float(np.average((proba - yy) ** 2, weights=_wv))
                fs = fa - (0.15 * fl) - (0.10 * fb)
                fold_aucs.append(fa); fold_lls.append(fl); fold_briers.append(fb); fold_scores.append(fs)

        # Selection is based on the MEAN OF TIME-FOLD METRICS, not pooled OOF AUC.
        # Pooling different future blocks can create artificial ranking from regime
        # base-rate shifts even when a feature is not consistently useful within folds.
        auc = float(np.mean(fold_aucs)) if fold_aucs else np.nan
        ll = float(np.mean(fold_lls)) if fold_lls else np.nan
        br = float(np.mean(fold_briers)) if fold_briers else np.nan
        score = float(np.mean(fold_scores)) if fold_scores else float("-inf")
        return {
            "auc": auc, "logloss": ll, "brier": br, "score": score,
            "fold_aucs": list(fold_aucs), "fold_scores": list(fold_scores),
            "aborted": False,
        }

    # -------------------------
    # selection state
    # -------------------------
    accepted = list(mk)
    accepted_set = set(accepted)
    flip_map = {}
    # Keep a complete machine-readable audit without flooding Cloud Logging.
    # This is persisted through select_features_auto() for post-run inspection.
    feature_audit = [
        {"feature": str(f), "status": "SEED", "reason": "must_keep"}
        for f in accepted
    ]
    rejected_total = 0

    def _audit_feature(feat, status, reason, **extra):
        rec={"feature":str(feat),"status":str(status),"reason":str(reason)}
        for k0,v0 in extra.items():
            try:
                if isinstance(v0,(np.floating,float)):
                    rec[k0]=None if not np.isfinite(v0) else float(v0)
                elif isinstance(v0,(np.integer,int)):
                    rec[k0]=int(v0)
                else:
                    rec[k0]=v0
            except Exception:
                rec[k0]=str(v0)
        feature_audit.append(rec)

    X_work = np.empty((n, max_k), dtype=np.float32)
    k = 0

    def _put_feat_into_col(feat: str, j: int):
        X_work[:, j] = X_all_mat[:, col_ix[feat]]

    for f in accepted:
        _put_feat_into_col(f, k)
        k += 1

    if verbose:
        log_func(f"[AUTO-FEAT] seed accepted (k={k}): {accepted}")

    if k > 0:
        best_res = _cv_eval_full_metrics(X_work[:, :k], folds_full, early_stop_rounds=500)
    else:
        # Neutral inner-CV baseline.  The legacy selector treated best=None as
        # "accept the first finite feature", so one candidate was forced into
        # every model even if it did not beat a no-feature forecast.
        _oof0 = np.full(n, np.nan, dtype=np.float64)
        _fa0, _fl0, _fb0, _fs0 = [], [], [], []
        for _tr0, _va0 in folds_full:
            _base_rate = float(np.average(y_arr[_tr0], weights=sw[_tr0])) if len(_tr0) else float(np.average(y_arr, weights=sw))
            _pred0 = np.full(len(_va0), np.clip(_base_rate, 1e-6, 1.0 - 1e-6), dtype=float)
            _oof0[_va0] = _pred0
            _yy0 = y_arr[_va0]
            if len(_yy0) >= 2 and np.unique(_yy0).size >= 2:
                _wv0 = sw[_va0]
                _a0 = float(roc_auc_score(_yy0, _pred0, sample_weight=_wv0))
                _l0 = float(log_loss(_yy0, _pred0, labels=[0, 1], sample_weight=_wv0))
                _b0 = float(np.average((_pred0 - _yy0) ** 2, weights=_wv0))
                _s0 = _a0 - (0.15 * _l0) - (0.10 * _b0)
                _fa0.append(_a0); _fl0.append(_l0); _fb0.append(_b0); _fs0.append(_s0)
        _auc0 = float(np.mean(_fa0)) if _fa0 else 0.5
        _ll0 = float(np.mean(_fl0)) if _fl0 else float("nan")
        _br0 = float(np.mean(_fb0)) if _fb0 else float("nan")
        _score0 = float(np.mean(_fs0)) if _fs0 else float("-inf")
        best_res = {
            "auc": _auc0, "logloss": _ll0, "brier": _br0, "score": _score0,
            "fold_aucs": list(_fa0), "fold_scores": list(_fs0), "aborted": False,
        }
        if verbose:
            log_func(
                f"[AUTO-FEAT] neutral baseline: auc={_auc0:.6f} ll={_ll0:.6f} "
                f"brier={_br0:.6f} score={_score0:.6f}"
            )

    best_val = _metric(best_res)
    best_ll  = float(best_res.get("logloss", np.nan)) if isinstance(best_res, dict) else float("nan")
    best_br  = float(best_res.get("brier", np.nan)) if isinstance(best_res, dict) else float("nan")

    # Normal training uses accept_metric="score". V13.0.15 therefore skipped the
    # existing AUC quick-screen entirely and full-CV fit every candidate. Build a
    # 3-fold score baseline once so SCORE mode can cheaply reject obvious losers.
    best_quick_score = float("-inf")
    if accept_metric == "score" and quick_screen and len(folds_quick) < len(folds_full) and k > 0:
        try:
            _qbase = _cv_eval_full_metrics(X_work[:, :k], folds_quick, early_stop_rounds=25)
            best_quick_score = float(_qbase.get("score", float("-inf")))
        except Exception:
            best_quick_score = float("-inf")

    if verbose and isinstance(best_res, dict):
        log_func(
            f"[AUTO-FEAT] seed metrics: "
            f"auc={best_res.get('auc', float('nan')):.6f} "
            f"ll={best_res.get('logloss', float('nan')):.6f} "
            f"brier={best_res.get('brier', float('nan')):.6f} "
            f"score={best_res.get('score', float('nan')):.6f}"
        )

    evals_done = 0
    rejects_in_row = 0

    # -------------------------
    # main scan
    # -------------------------
    min_improve_eff = float(min_improve)
    for i, feat in enumerate(ordered):
        if (not verbose) and (i == 0 or ((i + 1) % 25 == 0)):
            log_func(
                f"[AUTOFS-PROGRESS] tested={i}/{len(ordered)} accepted={len(accepted)} "
                f"rejected={rejected_total} evals={evals_done}"
            )
        if max_total_evals is not None and evals_done >= int(max_total_evals):
            break
        if (time.time() - t0) >= float(time_budget_s):
            break
        if feat in accepted_set:
            continue
        if max_k is not None and len(accepted) >= int(max_k):
            break
        if (not force_full_scan) and (len(accepted) >= min_k) and (rejects_in_row >= int(patience)):
            break

        # put candidate
        _put_feat_into_col(feat, k)

        # k-adaptive thresholds (MORE SIGNAL = more forgiving rej_margin)
        if k < max(12, min_k):
            rej_margin = 0.0001
        elif k < 40:
            rej_margin = 0.00015
        else:
            rej_margin = 0.0002

        quick_margin_auc = rej_margin
        flip_close_margin = rej_margin

        best_trial_flip = False
        best_trial_flip_mode = None
        best_trial_auc = float("nan")

        # -------------------------
        # AUC MODE
        # -------------------------
        if accept_metric == "auc":
            # 1) quick gate
            if quick_screen and len(folds_quick) < len(folds_full):
                res_q = _cv_eval_auc_only(
                    X_work[:, :k+1], folds_quick,
                    abort_best_auc=(best_val if np.isfinite(best_val) else None),
                    early_stop_rounds=25,
                )
                evals_done += 1
                m_q = float(res_q.get("auc", np.nan))
                if np.isfinite(best_val) and (not np.isfinite(m_q) or (m_q < float(best_val) - float(quick_margin_auc))):
                    rejects_in_row += 1; rejected_total += 1
                    _audit_feature(feat,"REJECT","quick_auc",quick_auc=m_q,best_value=best_val)
                    continue

            # 2) full AUC-only gate
            res_norm_auc = _cv_eval_auc_only(
                X_work[:, :k+1], folds_full,
                abort_best_auc=(best_val if np.isfinite(best_val) else None),
                early_stop_rounds=60,
            )
            evals_done += 1
            m_norm = float(res_norm_auc.get("auc", np.nan))

            # --- MORE SIGNAL: disable near-miss throttling (was skipping 2/3) ---
            # near_miss = (
            #     np.isfinite(m_norm) and np.isfinite(best_val) and
            #     (m_norm >= float(best_val) - float(rej_margin)) and
            #     (m_norm <  float(best_val) + float(min_improve_eff)) and
            #     (rejects_in_row >= 25)
            # )
            # if near_miss and (i % 3 != 0):
            #     rejects_in_row += 1
            #     continue

            if (not np.isfinite(m_norm)) or (np.isfinite(best_val) and (m_norm < float(best_val) - float(rej_margin))):
                rejects_in_row += 1; rejected_total += 1
                _audit_feature(feat,"REJECT","full_auc",full_auc=m_norm,best_value=best_val)
                continue

            best_trial_auc = float(m_norm) if np.isfinite(m_norm) else float("nan")

            # 3) flip test (AUC mode only)
            if allow_candidate_flip and np.isfinite(m_norm):
                if (not np.isfinite(best_val)) or (m_norm >= float(best_val) - float(flip_close_margin)):
                    col = X_work[:, k]
                    orig = col.copy()

                    fm = flip_mode_cache.get(feat) or _auto_flip_mode(orig)
                    _apply_flip_inplace(col, fm)

                    ok_to_full_flip = True
                    if quick_screen and len(folds_quick) < len(folds_full):
                        res_fq = _cv_eval_auc_only(
                            X_work[:, :k+1], folds_quick,
                            abort_best_auc=None,
                            early_stop_rounds=60,
                        )
                        evals_done += 1
                        mfq = float(res_fq.get("auc", np.nan))
                        ok_to_full_flip = np.isfinite(mfq) and (mfq >= m_norm + float(flip_gain_min))

                    if ok_to_full_flip:
                        res_flip_auc = _cv_eval_auc_only(
                            X_work[:, :k+1], folds_full,
                            abort_best_auc=None,
                            early_stop_rounds=40,
                        )
                        evals_done += 1
                        m_flip = float(res_flip_auc.get("auc", np.nan))
                        if np.isfinite(m_flip) and (m_flip > m_norm + float(flip_gain_min)):
                            best_trial_flip = True
                            best_trial_flip_mode = fm
                            best_trial_auc = float(m_flip)

                    col[:] = orig

            # 4) full metrics only if AUC acceptable
            if np.isfinite(best_trial_auc) and (not np.isfinite(best_val) or (best_trial_auc >= float(best_val) + float(min_improve_eff))):
                col = X_work[:, k]
                orig = col.copy()
                if best_trial_flip:
                    _apply_flip_inplace(col, best_trial_flip_mode)

                res_try = _cv_eval_full_metrics(X_work[:, :k+1], folds_full, early_stop_rounds=500)
                evals_done += 1
                col[:] = orig
            else:
                rejects_in_row += 1; rejected_total += 1
                _audit_feature(feat,"REJECT","auc_no_incremental_gain",trial_auc=best_trial_auc,best_value=best_val)
                continue

        else:
            # -------------------------
            # SCORE MODE
            # -------------------------
            _score_quick = float("nan")
            if quick_screen and len(folds_quick) < len(folds_full):
                _res_sq = _cv_eval_full_metrics(X_work[:, :k+1], folds_quick, early_stop_rounds=25)
                evals_done += 1
                _score_quick = float(_res_sq.get("score", np.nan))
                # Deliberately generous tolerance: this stage only removes obvious
                # losers. Full time-forward LL/Brier/AUC + fold consistency still
                # determine every accepted feature.
                if (not np.isfinite(_score_quick)) or (
                    np.isfinite(best_quick_score) and best_quick_score > -np.inf
                    and _score_quick < best_quick_score - float(score_quick_tolerance)
                ):
                    rejects_in_row += 1; rejected_total += 1
                    _audit_feature(feat,"REJECT","quick_score",quick_score=_score_quick,best_quick_score=best_quick_score)
                    continue

            res_try = _cv_eval_full_metrics(X_work[:, :k+1], folds_full, early_stop_rounds=60)
            evals_done += 1
            m_norm = float(res_try.get("score", np.nan))

            best_trial_flip = False
            best_trial_flip_mode = None
            best_trial_score = float(m_norm) if np.isfinite(m_norm) else float("nan")

            if allow_candidate_flip and np.isfinite(m_norm):
                if (not np.isfinite(best_val)) or (m_norm >= float(best_val) - float(flip_close_margin)):
                    col = X_work[:, k]
                    orig = col.copy()

                    fm = flip_mode_cache.get(feat) or _auto_flip_mode(orig)
                    if fm != "none":
                        _apply_flip_inplace(col, fm)

                        ok_to_full_flip = True
                        if quick_screen and len(folds_quick) < len(folds_full):
                            res_fq = _cv_eval_full_metrics(X_work[:, :k+1], folds_quick, early_stop_rounds=500)
                            evals_done += 1
                            m_fq = float(res_fq.get("score", np.nan))
                            ok_to_full_flip = np.isfinite(m_fq) and (m_fq >= m_norm + float(flip_gain_min))

                        if ok_to_full_flip:
                            res_flip_full = _cv_eval_full_metrics(X_work[:, :k+1], folds_full, early_stop_rounds=500)
                            evals_done += 1
                            m_flip = float(res_flip_full.get("score", np.nan))

                            if np.isfinite(m_flip) and (m_flip > m_norm + float(flip_gain_min)):
                                best_trial_flip = True
                                best_trial_flip_mode = fm
                                best_trial_score = float(m_flip)
                                res_try = res_flip_full

                    col[:] = orig

        # -------------------------
        # accept check
        # -------------------------
        val_try = _metric(res_try)
        ll_try  = float(res_try.get("logloss", np.nan))
        br_try  = float(res_try.get("brier", np.nan))

        _fold_consistency_ok = True
        _fold_positive_frac = float("nan")
        try:
            _try_fs = np.asarray(res_try.get("fold_scores", []), dtype=float)
            _best_fs = np.asarray(best_res.get("fold_scores", []), dtype=float) if isinstance(best_res, dict) else np.asarray([], dtype=float)
            if len(_try_fs) >= 3 and len(_try_fs) == len(_best_fs):
                _fd = _try_fs - _best_fs
                _fold_positive_frac = float(np.mean(_fd > 0.0))
                _fold_consistency_ok = bool(_fold_positive_frac >= 0.49)
        except Exception:
            _fold_consistency_ok = True

        if _accept_ok(val_try, best_val, ll_try, best_ll, br_try, best_br, min_improve_eff=min_improve_eff) and _fold_consistency_ok:
            accepted.append(feat)
            accepted_set.add(feat)
            k += 1

            best_res = res_try
            best_val = float(val_try)
            if np.isfinite(ll_try): best_ll = float(ll_try)
            if np.isfinite(br_try): best_br = float(br_try)
            rejects_in_row = 0
            if accept_metric == "score" and np.isfinite(locals().get("_score_quick", np.nan)):
                best_quick_score = float(_score_quick)
            _audit_feature(
                feat,"ACCEPT","incremental_full_cv",
                metric=val_try,logloss=ll_try,brier=br_try,
                fold_positive_frac=_fold_positive_frac,k=len(accepted)
            )

            if best_trial_flip:
                flip_map[feat] = {"flipped": True, "mode": best_trial_flip_mode}
                if verbose:
                    log_func(f"[AUTO-FEAT] 🔁 flip accepted for {feat} mode={best_trial_flip_mode}")

            if verbose:
                tag = " (flipped)" if (accept_metric == "auc" and best_trial_flip) else ""
                log_func(f"[AUTO-FEAT] ✅ accept +{feat}{tag} -> {accept_metric}={best_val:.6f} k={len(accepted)}")
        else:
            rejects_in_row += 1; rejected_total += 1
            _reject_reason = "fold_consistency" if (np.isfinite(_fold_positive_frac) and not _fold_consistency_ok) else "no_incremental_full_cv_gain"
            _audit_feature(feat,"REJECT",_reject_reason,metric=val_try,logloss=ll_try,brier=br_try,fold_positive_frac=_fold_positive_frac)
            if verbose and np.isfinite(_fold_positive_frac) and not _fold_consistency_ok:
                log_func(
                    f"[AUTO-FEAT] reject +{feat}: fold-consistency={_fold_positive_frac:.0%} < 49%"
                )

        if debug and (i % int(max(1, debug_every)) == 0):
            log_func(f"[AUTO-FEAT][DBG] i={i} k={len(accepted)} best_{accept_metric}={best_val:.6f}")

    # -------------------------
    # FINAL orientation/flips (optional)
    # -------------------------
    final_res = None
    if flips_after_selection and accepted:
        final_res = _cv_auc_for_feature_set(
            model_proto, X, y_arr, folds_full, list(accepted),
            log_func=log_func,
            debug=False,
            return_oof=True,
            orient_features=bool(orient_features),
            enable_feature_flips=bool(enable_feature_flips),
            max_feature_flips=int(max_feature_flips),
            orient_passes=int(orient_passes),
            cv_mode="full",
        )
        if verbose and isinstance(final_res, dict):
            log_func(f"[AUTO-FEAT] Final accepted set: k={len(accepted)} auc={final_res.get('auc', float('nan')):.6f}")

    log_func(
        f"[AUTOFS-SUMMARY] candidates={len(ordered)} accepted={len(accepted)} "
        f"evals={evals_done} xgb_threads={(xgb_params or {}).get('nthread') if use_xgb else 'NA'} "
        f"quick_folds={min(int(max(1,quick_folds)),len(folds_list))} "
        f"candidate_flips={'OFF_XGB' if use_xgb else bool(allow_candidate_flip)}"
    )
    state = {
        "done": True,
        "accepted": list(accepted),
        "best_res": (final_res if isinstance(final_res, dict) else best_res),
        "flip_map": dict(flip_map),
        "evals_done": int(evals_done),
        "feature_audit": list(feature_audit),
        "rejected_total": int(rejected_total),
        "score_quick_tolerance": float(score_quick_tolerance),
    }
    return list(accepted), (final_res if isinstance(final_res, dict) else best_res), state

# =========================
# 3) SELECT FEATURES AUTO (OLD/FAST preselect + prune + forward-select)
#    ✅ patched to pick up more sparse "signal #1" features WITHOUT slowing down
# =========================
def select_features_auto(
    model_proto,
    X_df_train: "pd.DataFrame",
    y_train: "np.ndarray",
    folds,
    *,
    sport_key: str = "NFL",
    must_keep: list[str] | None = None,

    # keep old knobs (won't break your call)
    corr_within: float = 0.90,
    corr_global: float = 0.97,
    max_feats_major: int = 220,
    max_feats_small: int = 160,
    topk_per_fold: int = 200,
    min_presence: float = 0.49,
    sign_flip_max: float = 0.35,
    shap_cv_max: float = 1.00,

    # selection knobs
    use_auc_auto: bool = True,
    auc_min_k: int | None = None,
    auc_patience: int = 400,
    auc_min_improve: float = 1e-7,
    accept_metric: str = "auc",
    auc_verbose: bool = False,

    baseline_feats: list[str] | None = None,

    allow_candidate_flip: bool = True,
    flip_gain_min: float = 5e-5,

    final_orient: bool = True,
    sample_weight=None,
    log_func=print,

    # backward compat
    **_ignored_kwargs,
):


    if X_df_train is None or X_df_train.empty:
        return [], pd.DataFrame(columns=["selected", "flipped", "flip_mode"])

    # -----------------------------
    # helpers (family + sparse whitelist)
    # -----------------------------
    def _feat_family(name: str) -> str:
        s = str(name)
        for pref in (
            "SharpMove_", "OddsMove_", "Hybrid_", "Steam_", "Resistance_",
            "Market_Mispricing", "Book_", "CrossMarket_", "PR_", "ATS_", "Team_",
        ):
            if s.startswith(pref):
                return pref
        return s.split("_", 1)[0] if "_" in s else "misc"

    def _is_sparse_ok_name(c: str) -> bool:
        s = str(c)
        return (
            s.startswith("Steam_") or
            s.startswith("SharpMove_") or
            s.startswith("OddsMove_") or
            ("Reversal" in s) or
            ("Resistance" in s)
        )

    must_keep = must_keep or []
    y_arr = np.asarray(y_train, dtype=np.int8).reshape(-1)
    mk_in = [m for m in must_keep if m in X_df_train.columns]

    # -----------------------------
    # 0) leak guard + column list
    # -----------------------------
    leak_patterns = ("SHARP_COVER_RESULT",)

    def _is_forbidden(c: str) -> bool:
        s = str(c)
        return _is_hard_leak_feature(s) or any(p in s for p in leak_patterns)

    cols = [c for c in X_df_train.columns if (c in mk_in) or (not _is_forbidden(c))]
    if not cols:
        return [], pd.DataFrame(columns=["selected", "flipped", "flip_mode"])

    # -----------------------------
    # 1) numeric once (float32)
    # -----------------------------
    X_num = X_df_train[cols].apply(pd.to_numeric, errors="coerce")
    X_mat = X_num.to_numpy(dtype=np.float32, copy=False)
    del X_num

    n, p = X_mat.shape
    if p == 0:
        return [], pd.DataFrame(columns=["selected", "flipped", "flip_mode"])

    finite = np.isfinite(X_mat)
    nn_frac = finite.mean(axis=0)
    with np.errstate(invalid="ignore"):
        var = np.nanvar(X_mat, axis=0)
        var = np.where(np.isfinite(var), var, 0.0)

    # -----------------------------
    # 2) usable mask (two-tier presence floor)
    # -----------------------------
    min_non_nan_dense = 0.0001
    min_non_nan_sparse = max(50 / n, 0.00002) 

    name_arr = np.asarray(cols, dtype=object)
    sparse_ok = np.fromiter((_is_sparse_ok_name(c) for c in name_arr), dtype=bool, count=len(cols))
    usable = ((nn_frac >= float(min_non_nan_dense)) | (sparse_ok & (nn_frac >= float(min_non_nan_sparse)))) & (var > 0.0)

    # Detect accidental target copies / near-copies before AutoFS.  In a sports
    # outcome model, a single feature with oriented AUC ~1.0 is overwhelmingly more
    # likely to be a leaked current-result field than a real pregame edge.  We only
    # auto-drop at an intentionally extreme threshold so legitimate strong signals
    # are retained and merely show up in normal diagnostics.
    _target_copy_drop = []
    if np.unique(y_arr).size >= 2:
        for _j, _c in enumerate(cols):
            if not usable[_j] or _c in mk_in:
                continue
            _x = X_mat[:, _j]
            _m = np.isfinite(_x) & np.isfinite(y_arr)
            if int(_m.sum()) < 100 or np.unique(_x[_m]).size < 2:
                continue
            try:
                _auc = float(roc_auc_score(y_arr[_m], _x[_m]))
                _auc_oriented = max(_auc, 1.0 - _auc)
            except Exception:
                continue
            if np.isfinite(_auc_oriented) and _auc_oriented >= 0.995:
                usable[_j] = False
                _target_copy_drop.append((_c, _auc_oriented))

    if _target_copy_drop:
        log_func(
            "[LEAK-GUARD] dropped near-target-copy features: " +
            ", ".join(f"{c} (oriented_auc={a:.4f})" for c, a in _target_copy_drop[:20])
        )

    # always keep must_keep
    if mk_in:
        mk_set = set(mk_in)
        mk_idx = np.fromiter((i for i, c in enumerate(cols) if c in mk_set), dtype=int)
        if mk_idx.size:
            usable[mk_idx] = True

    usable_idx = np.flatnonzero(usable)
    if usable_idx.size == 0:
        keep_order = list(dict.fromkeys(mk_in))
        return keep_order, pd.DataFrame({"selected": True}, index=pd.Index(keep_order, name="feature"))

    # -----------------------------
    # 3) cheap univariate screen (corr proxy)
    # -----------------------------
    # -----------------------------
    # 3) cheap univariate screen (corr proxy)  ✅ FIXED
    #   - normalize by effective count to avoid sparse inflation
    #   - compute a true-ish correlation proxy using only finite entries
    #   - add light shrinkage for very low-count features
    # -----------------------------
    y_f = y_arr.astype(np.float32)
    sw_all = np.ones(n, dtype=np.float32) if sample_weight is None else np.asarray(sample_weight, dtype=np.float32).reshape(-1)
    if len(sw_all) != n:
        raise ValueError(f"select_features_auto sample_weight mismatch {len(sw_all)} != {n}")
    sw_all[~np.isfinite(sw_all)] = 0.0
    if float(sw_all.sum()) <= 0:
        sw_all[:] = 1.0
    y_mu_w = float(np.average(y_f, weights=sw_all))
    y_c = y_f - y_mu_w
    y_sd = float(np.sqrt(np.average(y_c**2, weights=sw_all)) + 1e-12)

    X_u   = X_mat[:, usable_idx]
    fin_u = finite[:, usable_idx]
    w2 = sw_all[:, None]
    wfin = np.where(fin_u, w2, 0.0).astype(np.float32, copy=False)
    cntw = np.maximum(wfin.sum(axis=0), 1e-8)
    x0 = np.where(fin_u, X_u, 0.0).astype(np.float32, copy=False)
    mu = (x0 * w2).sum(axis=0) / cntw
    xc = np.where(fin_u, X_u - mu, 0.0).astype(np.float32, copy=False)
    varw = (w2 * (xc**2)).sum(axis=0) / cntw
    sd = np.sqrt(np.maximum(varw, 1e-12)).astype(np.float32, copy=False)
    cov = (w2 * xc * y_c[:,None]).sum(axis=0) / cntw
    score_uni = np.abs(cov) / np.maximum(sd,1e-12) / y_sd

    # Reliability shrinkage uses effective weighted support.
    cnt = fin_u.sum(axis=0).astype(np.float32, copy=False)
    cnt_safe = np.maximum(cnt, 1.0)
    k_shrink = max(50.0, 0.0005 * float(n))
    shrink = np.sqrt(cnt_safe / (cnt_safe + k_shrink)).astype(np.float32, copy=False)
    score_uni *= shrink
    score_uni = np.where(np.isfinite(score_uni), score_uni, 0.0).astype(np.float32, copy=False)

    is_small = str(sport_key).upper() in {"WNBA", "CFL", "MLS", "NHL"}
    max_pre = int(max_feats_small if is_small else max_feats_major)
    
    # keep ~3x final budget for interactions
    pre_budget = int(min(len(usable_idx), max(max_pre * 3, len(mk_in) + 50)))
    # -----------------------------
    # 3c) Fold voting filter ✅ uses topk_per_fold / min_presence / sign_flip_max
    #   IMPORTANT: must run BEFORE building reserved/cand/order
    # -----------------------------
    folds_list = []
    if hasattr(folds, "split"):
        idx_dummy = np.zeros((len(y_arr), 1), dtype=np.float32)
        for tr, va in folds.split(idx_dummy, y_arr):
            folds_list.append((np.asarray(tr, np.int64), np.asarray(va, np.int64)))
    else:
        folds_list = [(np.asarray(tr, np.int64), np.asarray(va, np.int64)) for tr, va in (folds or [])]
    
    F = len(folds_list)
    if F >= 2 and int(topk_per_fold) > 0:
        if auc_verbose:
            log_func(
                f"[FOLD-PRESENCE-CONTRACT] folds={F} min_presence={float(min_presence):.2f} "
                "(features at 50% presence remain eligible)"
            )
        K = int(max(10, topk_per_fold))
        votes = np.zeros(len(usable_idx), dtype=np.int16)
        pos   = np.zeros(len(usable_idx), dtype=np.int16)
        neg   = np.zeros(len(usable_idx), dtype=np.int16)
    
        y_full = y_arr.astype(np.float32)
    
        for tr, _va in folds_list:
            y_tr = y_full[tr]
            w_tr = sw_all[tr].astype(np.float32, copy=False)
            y_mu_tr = float(np.average(y_tr, weights=w_tr)) if float(w_tr.sum()) > 0 else float(np.mean(y_tr))
            y_tc = y_tr - y_mu_tr
            y_sd_tr = float(np.sqrt(np.average(y_tc**2, weights=np.maximum(w_tr,1e-12))) + 1e-12)

            X_tr = X_mat[tr][:, usable_idx]
            fin_tr = np.isfinite(X_tr)
            wtr2 = w_tr[:,None]
            wf = np.where(fin_tr, wtr2, 0.0).astype(np.float32, copy=False)
            swf = np.maximum(wf.sum(axis=0), 1e-8)
            x0tr = np.where(fin_tr, X_tr, 0.0).astype(np.float32, copy=False)
            mu_tr = (x0tr*wtr2).sum(axis=0)/swf
            xc = np.where(fin_tr, X_tr-mu_tr, 0.0).astype(np.float32, copy=False)
            var_tr=(wtr2*(xc**2)).sum(axis=0)/swf
            sd_tr=np.sqrt(np.maximum(var_tr,1e-12))
            cov_tr=(wtr2*xc*y_tc[:,None]).sum(axis=0)/swf
            score_tr=np.abs(cov_tr)/np.maximum(sd_tr,1e-12)/y_sd_tr
    
            kk = min(K, score_tr.size)
            if kk <= 0:
                continue
            topk_loc = np.argpartition(-score_tr, kk - 1)[:kk]
    
            votes[topk_loc] += 1
            pos[topk_loc] += (cov_tr[topk_loc] > 0).astype(np.int16)
            neg[topk_loc] += (cov_tr[topk_loc] < 0).astype(np.int16)
    
        presence = votes.astype(np.float32) / float(max(F, 1))
        flip_rate = np.minimum(pos, neg).astype(np.float32) / np.maximum((pos + neg).astype(np.float32), 1.0)
    
        keep_mask = (presence >= float(min_presence)) & (flip_rate <= float(sign_flip_max))
    
        # always keep must_keep
        if mk_in:
            mk_set = set(mk_in)
            for loc, col_j in enumerate(usable_idx):
                if cols[int(col_j)] in mk_set:
                    keep_mask[loc] = True
    
        usable_idx = usable_idx[keep_mask]
        score_uni  = score_uni[keep_mask]
    
    # Recompute pre_budget AFTER fold voting (pool may shrink)
    is_small = str(sport_key).upper() in {"WNBA", "CFL", "MLS", "NHL"}
    max_pre = int(max_feats_small if is_small else max_feats_major)
    pre_budget = int(min(len(usable_idx), max(max_pre * 3, len(mk_in) + 50)))
    
    # -----------------------------
    # 3b) family-aware reserve ✅ now operates on fold-filtered usable_idx
    # -----------------------------
    reserve_per_family = 40
    max_families = 100
    
    rank_local = np.argsort(-score_uni)               # indices into usable_idx space
    usable_ranked_cols = usable_idx[rank_local]       # column indices in X_mat
    usable_ranked_names = [cols[j] for j in usable_ranked_cols]
    
    family_counts = {}
    reserved = []
    for j_idx, fname in zip(usable_ranked_cols, usable_ranked_names):
        fam = _feat_family(fname)
        if len(family_counts) >= max_families and fam not in family_counts:
            continue
        c = family_counts.get(fam, 0)
        if c < reserve_per_family:
            reserved.append(int(j_idx))
            family_counts[fam] = c + 1
    
    reserved = np.array(reserved, dtype=int)
    
    need = max(0, pre_budget - reserved.size)
    if need > 0:
        top_global = usable_ranked_cols[:need]
        cand_idx = np.unique(np.concatenate([reserved, top_global])).astype(int)
    else:
        cand_idx = np.unique(reserved).astype(int)
    
    # order candidates by score_uni (build fresh mapping after fold voting)
    idx_to_local = {int(col_j): int(loc_j) for loc_j, col_j in enumerate(usable_idx)}
    cand_scores = np.array([score_uni[idx_to_local[int(j)]] for j in cand_idx], dtype=np.float32)
    order = cand_idx[np.argsort(-cand_scores)]  
       

   
    # -----------------------------
    # 4) cheap correlation pruning (less destructive within signal families)
    # -----------------------------
    corr_thr_global = float(corr_global if corr_global is not None else 0.92)
    corr_thr_within = float(corr_within if corr_within is not None else 0.90)
    signal_fams = {"SharpMove_", "OddsMove_", "Hybrid_", "Steam_", "Resistance_"}
    
    def _corr_thr_for_pair(a: str, b: str) -> float:
        fa = _feat_family(a)
        fb = _feat_family(b)
        if fa == fb:
            # within-family pruning
            thr = corr_thr_within
            # for signal families, be less destructive (keep more variants)
            if fa in signal_fams:
                thr = max(thr, 0.975)
            return thr
        # across-family pruning
        return corr_thr_global

    keep = [cols.index(m) for m in mk_in if m in cols]
    kept_set = set(keep)

    z_cache = {}

    def _std_col(j):
        x = X_mat[:, j]
        m = np.nanmean(x)
        s = np.nanstd(x)
        if not np.isfinite(s) or s < 1e-12:
            return None
        z = (np.where(np.isfinite(x), x, m) - m) / s
        return z.astype(np.float32, copy=False)

    for j in order:
        j = int(j)
        if j in kept_set:
            continue
        if len(keep) >= pre_budget:
            break

        zj = _std_col(j)
        if zj is None:
            continue

        ok = True
        to_check = keep[-min(len(keep), 100):]
        for kidx in to_check:
            zk = z_cache.get(kidx)
            if zk is None:
                zk = _std_col(int(kidx))
                if zk is None:
                    continue
                if len(z_cache) < 128:
                    z_cache[kidx] = zk
            c = float(np.mean(zj * zk))
            thr = _corr_thr_for_pair(cols[j], cols[int(kidx)])
            if np.isfinite(c) and abs(c) >= thr:
                ok = False
                break

        if ok:
            keep.append(j)
            kept_set.add(j)

    keep_order = list(dict.fromkeys([cols[i] for i in keep]))

    if auc_verbose:
        log_func(f"[AUTO-FEAT] usable={int(usable.sum())}/{p} -> preselect={len(keep_order)} (budget={pre_budget})")

    if not keep_order:
        return [], pd.DataFrame(columns=["selected", "flipped", "flip_mode"])

    # min_k should never be < must_keep size
    min_k_eff = len(mk_in) if (auc_min_k is None) else int(max(len(mk_in), auc_min_k))

    flip_map = {}

    # -----------------------------
    # 5) forward-select on reduced set
    # -----------------------------
    if use_auc_auto and keep_order:
        accepted_feats, best_res, state = _auto_select_k_by_auc(
            model_proto, X_df_train, y_arr, folds, keep_order,
            min_k=min_k_eff,
            max_k=len(keep_order),
            patience=int(auc_patience),
            min_improve=float(auc_min_improve),
            verbose=bool(auc_verbose),
            log_func=log_func,
            accept_metric=str(accept_metric),
            must_keep=mk_in,
            baseline_feats=baseline_feats if baseline_feats is not None else mk_in,

            allow_candidate_flip=bool(allow_candidate_flip),
            flip_gain_min=float(flip_gain_min),

            flips_after_selection=bool(final_orient),
            orient_features=True if final_orient else False,
            enable_feature_flips=True if final_orient else False,
            max_feature_flips=100,
            orient_passes=1,

            quick_screen=True,
            quick_folds=3,
            abort_margin_cv=-1e-6,
            force_full_scan=False,
            time_budget_s=1e18,
            resume_state=None,
            max_total_evals=None,
            sample_weight=sample_weight,
        )
        feature_cols = list(accepted_feats or [])
        flip_map = (state or {}).get("flip_map", {}) or {}
    else:
        feature_cols = keep_order

    # -----------------------------
    # 6) summary
    # -----------------------------
    flipped = np.fromiter(
        (bool(flip_map.get(f, {}).get("flipped", False)) for f in feature_cols),
        dtype=bool,
        count=len(feature_cols),
    )
    flip_mode = np.fromiter(
        ((flip_map.get(f, {}).get("mode", "") or "") for f in feature_cols),
        dtype=object,
        count=len(feature_cols),
    )

    summary = pd.DataFrame(
        {"selected": np.ones(len(feature_cols), dtype=bool), "flipped": flipped, "flip_mode": flip_mode},
        index=pd.Index(np.asarray(feature_cols, dtype=object), name="feature"),
    )

    if use_auc_auto and keep_order:
        try:
            summary.attrs["autofs_feature_audit"] = list((state or {}).get("feature_audit", []))
            summary.attrs["autofs_evals_done"] = int((state or {}).get("evals_done", 0))
            summary.attrs["autofs_rejected_total"] = int((state or {}).get("rejected_total", 0))
        except Exception:
            pass

    if auc_verbose:
        log_func(f"[AUTO-FEAT] final selected: {len(feature_cols)} feats (from {X_df_train.shape[1]})")

    return feature_cols, summary


