def _fresh_unique_side_frame(rows: pd.DataFrame, y, value_cols):
    """Collapse repeated books/snapshots to one leakage-safe physical team-side.

    The prediction columns are aggregated by median.  The label is the majority
    side result; exact 50/50 disagreements (possible around line differences) are
    excluded.  This is diagnostic/gating grain only and never fabricates rows.
    """
    if rows is None or len(rows) == 0:
        return pd.DataFrame()
    d = rows.copy().reset_index(drop=True)
    yy = pd.to_numeric(pd.Series(np.asarray(y).reshape(-1)), errors="coerce")
    if len(yy) != len(d):
        return pd.DataFrame()
    d["__fresh_y"] = yy.to_numpy()
    side_col = None
    for c in ("Outcome_Norm", "Outcome", "Team_Norm", "Team"):
        if c in d.columns:
            side_col = c
            break
    if "Game_Key" in d.columns and side_col is not None:
        keys = ["Game_Key", side_col]
    elif "Game_Key" in d.columns:
        keys = ["Game_Key"]
    elif "_SOURCE_ROW_ID" in d.columns:
        keys = ["_SOURCE_ROW_ID"]
    else:
        d["__fresh_row"] = np.arange(len(d), dtype=np.int64)
        keys = ["__fresh_row"]

    agg = {"__fresh_y": "mean"}
    for c in value_cols:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors="coerce")
            agg[c] = "median"
    if "Game_Start" in d.columns:
        d["__fresh_game_start"] = pd.to_datetime(d["Game_Start"], errors="coerce", utc=True)
        agg["__fresh_game_start"] = "max"
    g = d.groupby(keys, dropna=False, sort=False).agg(agg).reset_index()
    # A side should have a stable binary result across repeated quotes.  If line
    # differences create a true 50/50 split, do not let that side decide the gate.
    g = g.loc[g["__fresh_y"].notna() & ~np.isclose(g["__fresh_y"], 0.5, atol=1e-12)].copy()
    g["__fresh_y"] = (g["__fresh_y"] > 0.5).astype("int8")
    return g.reset_index(drop=True)


def _fresh_prob_metrics(y, p):
    yy = np.asarray(y, dtype=int).reshape(-1)
    pp = np.asarray(p, dtype=float).reshape(-1)
    ok = np.isfinite(pp) & np.isfinite(yy)
    yy = yy[ok]; pp = np.clip(pp[ok], 1e-6, 1-1e-6)
    if len(yy) < 2 or np.unique(yy).size < 2:
        return {"n": int(len(yy)), "auc": np.nan, "logloss": np.nan, "brier": np.nan}
    try: auc = float(roc_auc_score(yy, pp))
    except Exception: auc = np.nan
    try: ll = float(log_loss(yy, pp, labels=[0,1]))
    except Exception: ll = np.nan
    try: br = float(brier_score_loss(yy, pp))
    except Exception: br = np.nan
    return {"n": int(len(yy)), "auc": auc, "logloss": ll, "brier": br}


def _evaluate_ncaaf_stat_fresh_gate(rows: pd.DataFrame, y, market: str, *, core_prob=None, log_func=print):
    """Require current-season Stat state and paired incremental skill over the Core."""
    info = {"version":NCAAF_STAT_PROTECTED_ROUTE_VERSION,"gate_pass":False,"status":"not_applicable",
            "n_unique_sides":0,"effective_edge_weight":0.0,"orientation":"UNTESTED"}
    if rows is None or _sys_norm_market(market)!="spreads": return info
    cols=["NCAAF_Stat_Active","NCAAF_Stat_Trust","NCAAF_Stat_Prob","NCAAF_Stat_Market_Baseline_Prob"]
    if not all(c in rows.columns for c in cols): info["status"]="missing_columns"; return info
    d=rows.copy().reset_index(drop=True)
    yy_all=np.asarray(y).reshape(-1)
    if len(yy_all)!=len(d): info["status"]="shape_mismatch"; return info
    if core_prob is not None:
        cp=np.asarray(core_prob,dtype=float).reshape(-1)
        if len(cp)!=len(d): info["status"]="core_shape_mismatch"; return info
        d["__Core_Prob"]=cp
    active=pd.to_numeric(d["NCAAF_Stat_Active"],errors="coerce").fillna(0).eq(1)
    trust=pd.to_numeric(d["NCAAF_Stat_Trust"],errors="coerce").fillna(0)
    select=active & trust.ge(NCAAF_STAT_PROTECTED_MIN_TRUST)
    season_num=pd.to_numeric(d.get("Season"),errors="coerce") if "Season" in d.columns else pd.Series(np.nan,index=d.index)
    derived=_ncaaf_season_from_timestamp(d.get("Game_Start",pd.Series(pd.NaT,index=d.index)))
    season_num=pd.Series(season_num,index=d.index).where(pd.Series(season_num,index=d.index).notna(),derived)
    known=season_num.loc[select & season_num.notna()]
    season_used=int(known.max()) if len(known) else None
    if season_used is not None: select &= season_num.eq(season_used)

    src=pd.to_numeric(d.get("NCAAF_Stat_Source_Season"),errors="coerce") if "NCAAF_Stat_Source_Season" in d.columns else pd.Series(np.nan,index=d.index)
    cur_games=pd.to_numeric(d.get("NCAAF_Stat_Current_Season_Games"),errors="coerce").fillna(0) if "NCAAF_Stat_Current_Season_Games" in d.columns else pd.Series(0,index=d.index,dtype=float)
    current_state = select & src.eq(season_num) & cur_games.gt(0)
    prior_only = bool(select.any() and not current_state.any())

    dsel=d.loc[select].copy(); ysel=yy_all[select.to_numpy(dtype=bool)]
    vals=["NCAAF_Stat_Prob","NCAAF_Stat_Market_Baseline_Prob","NCAAF_Stat_Trust","NCAAF_Stat_Source_Season","NCAAF_Stat_Current_Season_Games"]
    if core_prob is not None: vals.append("__Core_Prob")
    g=_fresh_unique_side_frame(dsel,ysel,vals)
    if g.empty:
        info["status"]="waiting_for_postcutoff_graded_sides"
        if log_func: log_func(f"[NCAAF-STAT-FRESH-GATE] status={info['status']} n=0 gate=CLOSED")
        return info
    p=pd.to_numeric(g["NCAAF_Stat_Prob"],errors="coerce").to_numpy(dtype=float)
    b=pd.to_numeric(g["NCAAF_Stat_Market_Baseline_Prob"],errors="coerce").fillna(.5).to_numpy(dtype=float)
    yv=g["__fresh_y"].to_numpy(dtype=int)
    direct=_fresh_prob_metrics(yv,p); inverse=_fresh_prob_metrics(yv,1-p); market=_fresh_prob_metrics(yv,b)
    inv_better=bool(np.isfinite(inverse["logloss"]) and np.isfinite(direct["logloss"]) and inverse["logloss"]<direct["logloss"]-.001 and np.isfinite(inverse["auc"]) and inverse["auc"]>=.52)
    orientation="INVERSION_SUSPECT" if inv_better else ("DIRECT" if np.isfinite(direct["auc"]) and direct["auc"]>=.5 else "AMBIGUOUS")

    best_weight=0.0; core_metrics=None; trial_metrics=None; ll_imp=np.nan; br_imp=np.nan
    if core_prob is not None and "__Core_Prob" in g.columns:
        core=pd.to_numeric(g["__Core_Prob"],errors="coerce").fillna(.5).clip(.01,.99).to_numpy(dtype=float)
        core_metrics=_fresh_prob_metrics(yv,core)
        edge=p-b
        best_score=np.inf
        for w in (0.05,0.10,0.15,0.20,0.25):
            trial=np.clip(core+np.clip(w*edge,-NCAAF_STAT_PROTECTED_MAX_ABS_CORRECTION,NCAAF_STAT_PROTECTED_MAX_ABS_CORRECTION),.01,.99)
            met=_fresh_prob_metrics(yv,trial)
            if np.isfinite(met["logloss"]) and np.isfinite(met["brier"]):
                score=met["logloss"]+0.50*met["brier"]
                if score<best_score: best_score=score; best_weight=w; trial_metrics=met
        if trial_metrics is not None:
            ll_imp=float(core_metrics["logloss"]-trial_metrics["logloss"])
            br_imp=float(core_metrics["brier"]-trial_metrics["brier"])
    else:
        core_metrics=market; trial_metrics=direct
        ll_imp=float(market["logloss"]-direct["logloss"]) if np.isfinite(market["logloss"]) and np.isfinite(direct["logloss"]) else np.nan
        br_imp=float(market["brier"]-direct["brier"]) if np.isfinite(market["brier"]) and np.isfinite(direct["brier"]) else np.nan
        best_weight=NCAAF_STAT_PROTECTED_MAX_EDGE_WEIGHT

    n=int(direct["n"])
    freshness_ok=not prior_only and bool(current_state.any())
    gate=bool(n>=NCAAF_STAT_FRESH_GATE_MIN_SIDES and freshness_ok and orientation=="DIRECT" and
              np.isfinite(ll_imp) and ll_imp>=NCAAF_STAT_FRESH_GATE_MIN_LL_IMPROVEMENT and
              np.isfinite(br_imp) and br_imp>=NCAAF_STAT_FRESH_GATE_MIN_BRIER_IMPROVEMENT and best_weight>0)
    weight=0.0
    if gate:
        sf=float(np.clip((n-NCAAF_STAT_FRESH_GATE_MIN_SIDES)/max(NCAAF_STAT_FRESH_GATE_FULL_WEIGHT_SIDES-NCAAF_STAT_FRESH_GATE_MIN_SIDES,1),.25,1.0))
        weight=float(best_weight*sf)
    unique_games=int(g["Game_Key"].nunique()) if "Game_Key" in g.columns else n
    dmin=g["__fresh_game_start"].min() if "__fresh_game_start" in g.columns else pd.NaT; dmax=g["__fresh_game_start"].max() if "__fresh_game_start" in g.columns else pd.NaT
    status="PASS" if gate else ("PRIOR_SEASON_ONLY" if prior_only else ("INVERSION_SUSPECT" if inv_better else "WAIT_OR_FAIL"))
    info.update({"gate_pass":gate,"status":status,"n_unique_sides":n,"n_unique_games":unique_games,"season_used":season_used,
                 "game_date_min":None if pd.isna(dmin) else str(dmin),"game_date_max":None if pd.isna(dmax) else str(dmax),
                 "effective_edge_weight":weight,"best_tested_edge_weight":best_weight,"orientation":orientation,"direct":direct,"inverse":inverse,
                 "market_baseline":market,"core_baseline":core_metrics,"incremental_trial":trial_metrics,
                 "logloss_improvement_vs_core":ll_imp,"brier_improvement_vs_core":br_imp,
                 "current_state_rows":int(current_state.sum()),"prior_season_only":prior_only})
    if log_func:
        core_ll=(core_metrics or {}).get("logloss",np.nan); trial_ll=(trial_metrics or {}).get("logloss",np.nan)
        log_func(f"[NCAAF-STAT-FRESH-GATE] season={season_used} games={unique_games} n={n} freshness={status if prior_only else 'CURRENT'} current_state_rows={int(current_state.sum())} "
                 f"direct_auc={direct['auc']:.4f} core_ll={core_ll:.6f} trial_ll={trial_ll:.6f} ll_improve={ll_imp:+.6f} brier_improve={br_imp:+.6f} "
                 f"orientation={orientation} gate={'PASS' if gate else 'CLOSED'} weight={weight:.4f}")
    return info

def _apply_ncaaf_stat_protected_route(base_prob, rows: pd.DataFrame, market: str, *, log_func=None, config=None, return_info=False):
    """Apply Stat Brain only after its current-season unique-side gate passes."""
    p=np.asarray(base_prob,dtype=np.float64).reshape(-1)
    info={"source_active":0,"eligible":0,"applied":0,"rows":len(p),"status":"disabled"}
    if rows is None or len(rows)!=len(p) or _sys_norm_market(market)!="spreads":
        info["status"]="shape_or_market_mismatch"; return (p,info) if return_info else p
    cfg=config or {}
    if not bool(cfg.get("enabled",True)):
        return (p,info) if return_info else p
    def _rcol(name,default):
        src=rows[name] if name in rows.columns else pd.Series(default,index=rows.index)
        return pd.to_numeric(src,errors="coerce")
    active=_rcol("NCAAF_Stat_Active",0).fillna(0).eq(1).to_numpy(dtype=bool)
    trust=_rcol("NCAAF_Stat_Trust",0).fillna(0).to_numpy(dtype=float)
    sp=_rcol("NCAAF_Stat_Prob",np.nan).to_numpy(dtype=float)
    sb=_rcol("NCAAF_Stat_Market_Baseline_Prob",0.5).fillna(0.5).to_numpy(dtype=float)
    min_trust=float(cfg.get("min_row_trust",NCAAF_STAT_PROTECTED_MIN_TRUST))
    # V13.2.5 contract semantics: source wiring and deployment eligibility are
    # different questions.  An active row with finite Stat probability/baseline/
    # trust proves the protected route is wired even when its trust is below the
    # deployment threshold.  The old contract incorrectly raised in that normal
    # low-trust state, preventing the model from training at all.
    source_wired=active & np.isfinite(sp) & np.isfinite(sb) & np.isfinite(trust)
    eligible=source_wired & (trust>=min_trust)
    n_active=int(active.sum()); n_wired=int(source_wired.sum()); n_eligible=int(eligible.sum())
    info.update({
        "source_active":n_active,
        "source_wired":n_wired,
        "eligible":n_eligible,
        "trust_blocked":int(max(n_wired-n_eligible,0)),
        "min_row_trust":float(min_trust),
    })
    strict_contract=bool(cfg.get("strict_source_contract",False))
    if n_active>0 and n_wired==0:
        info["status"]="FAIL_source_active_but_not_wired"
        msg=(f"[NCAAF-STAT-PROTECTED-CONTRACT] FAIL source_active={n_active} "
             f"source_wired=0 eligible={n_eligible} rows={len(p)} "
             f"route={NCAAF_STAT_PROTECTED_ROUTE_VERSION}")
        if log_func is not None: log_func(msg)
        if strict_contract: raise RuntimeError(msg)
        return (p,info) if return_info else p
    if n_active>0 and n_eligible==0 and log_func is not None:
        log_func(
            f"[NCAAF-STAT-PROTECTED-CONTRACT] PASS source_active={n_active} "
            f"source_wired={n_wired} eligible=0 trust_blocked={int(max(n_wired-n_eligible,0))} "
            f"min_trust={min_trust:.4f} note=SOURCE_WIRED_DEPLOYMENT_TRUST_BELOW_MIN "
            f"route={NCAAF_STAT_PROTECTED_ROUTE_VERSION}"
        )
    # A strict source-contract call is a wiring dry run, not a deployment test.
    # Once finite source outputs exist, return unchanged probabilities and let the
    # real freshness/trust gate be evaluated later on graded unique game-sides.
    if strict_contract:
        info["status"]="source_contract_pass" if n_active>0 else "source_contract_no_active_rows"
        return (p,info) if return_info else p
    gate_pass=bool(cfg.get("deployment_gate_pass",False))
    weight=float(cfg.get("effective_edge_weight",cfg.get("edge_weight",0.0))) if gate_pass else 0.0
    if not gate_pass or weight<=0:
        info.update({"status":"deployment_gate_closed","effective_edge_weight":0.0})
        if log_func is not None:
            log_func(f"[NCAAF-STAT-PROTECTED] source_active={int(active.sum())} eligible={int(eligible.sum())}/{len(p)} gate=CLOSED weight=0 route={NCAAF_STAT_PROTECTED_ROUTE_VERSION}")
        return (p,info) if return_info else p
    cap=float(cfg.get("max_abs_correction",NCAAF_STAT_PROTECTED_MAX_ABS_CORRECTION))
    correction=np.zeros(len(p),dtype=np.float64)
    correction[eligible]=np.clip(weight*(sp[eligible]-sb[eligible]),-cap,cap)
    out=np.clip(p+correction,0.01,0.99)
    applied=int((np.abs(correction)>0).sum())
    info.update({"status":"ok","applied":applied,"effective_edge_weight":weight,"mean_abs_correction":float(np.mean(np.abs(correction[eligible]))) if eligible.any() else 0.0,"max_abs_correction":float(np.max(np.abs(correction[eligible]))) if eligible.any() else 0.0})
    if log_func is not None:
        log_func(f"[NCAAF-STAT-PROTECTED] source_active={int(active.sum())} eligible={int(eligible.sum())}/{len(p)} gate=PASS edge_weight={weight:.4f} mean_abs_corr={info['mean_abs_correction']:.5f} max_abs_corr={info['max_abs_correction']:.5f} route={NCAAF_STAT_PROTECTED_ROUTE_VERSION}")
    return (out,info) if return_info else out


# V13.2.13 cleanup: legacy _apply_system_memory_protected_route removed.
# The current rule engine owns all Pathi/BigAl probability authority.

_NCAAF_STAT_METRICS = (
    # Core efficiency / finishing proxies available in the historical box-score feed.
    "Off_YPP", "Off_Pass_YPA", "Off_Rush_YPA", "Off_Completion_Rate",
    "Off_Points_Per_Play", "Off_Turnover_Rate", "Off_FirstDown_Rate",
    # Tempo / play-mix / passing-efficiency candidates.  These are calculated for
    # every game but are not automatically admitted to the fitted Statistical Brain.
    "Off_Plays_Per_Game", "Off_Pass_Rate", "Off_Rush_Rate", "Off_Yards_Per_Completion",
    # Defensive mirrors, obtained from the opponent's same-game offense and shifted
    # before they can be used as predictors.
    "Def_YPP_Allowed", "Def_Pass_YPA_Allowed", "Def_Rush_YPA_Allowed",
    "Def_Points_Per_Play_Allowed", "Def_Takeaway_Rate",
    "Def_Plays_Faced", "Def_Pass_Rate_Faced", "Def_Rush_Rate_Faced",
    "Def_Yards_Per_Completion_Allowed",
)

_NCAAF_STAT_ADJ_METRICS = (
    "GameAdj_Off_YPP", "GameAdj_Def_YPP",
    "GameAdj_Off_Pass_YPA", "GameAdj_Def_Pass_YPA",
    "GameAdj_Off_Rush_YPA", "GameAdj_Def_Rush_YPA",
    "GameAdj_Off_Points_Per_Play", "GameAdj_Def_Points_Per_Play",
)
_NCAAF_STAT_PROFILE_METRICS = _NCAAF_STAT_METRICS + _NCAAF_STAT_ADJ_METRICS


_NCAAF_STAT_MATCHUP_PAIRS = (
    ("YPP", "Off_YPP", "Def_YPP_Allowed"),
    ("Pass_YPA", "Off_Pass_YPA", "Def_Pass_YPA_Allowed"),
    ("Rush_YPA", "Off_Rush_YPA", "Def_Rush_YPA_Allowed"),
    ("Points_Per_Play", "Off_Points_Per_Play", "Def_Points_Per_Play_Allowed"),
    ("Turnover_Pressure", "Off_Turnover_Rate", "Def_Takeaway_Rate"),
    # V13.0.5 handicap candidate expansion.  These all use pre-existing,
    # leakage-safe profile metrics; the qualification gate can reject every one.
    ("Yards_Per_Completion", "Off_Yards_Per_Completion", "Def_Yards_Per_Completion_Allowed"),
    ("Pass_Rate", "Off_Pass_Rate", "Def_Pass_Rate_Faced"),
    ("Rush_Rate", "Off_Rush_Rate", "Def_Rush_Rate_Faced"),
    ("Pace", "Off_Plays_Per_Game", "Def_Plays_Faced"),
)


def _ncaaf_season_from_timestamp(values):
    """NCAAF season year from kickoff time; January games belong to the prior season."""
    ts = pd.to_datetime(values, errors="coerce", utc=True)
    if isinstance(ts, pd.Series):
        season = ts.dt.year.astype("float64")
        season = season.where(ts.dt.month.ne(1), season - 1.0)
        return season
    idx = getattr(values, "index", None)
    s = pd.Series(ts, index=idx)
    season = s.dt.year.astype("float64")
    return season.where(s.dt.month.ne(1), season - 1.0)



def _ncaaf_stat_add_pair_features(frame: pd.DataFrame):
    """Create matchup/total candidates without altering observed team performance.

    ``RawSeason`` and ``RawRecent3`` are direct leakage-safe summaries of games
    actually played. ``State`` and ``Recent3`` are stabilized latent estimates kept
    as separate candidates. Feature qualification/regularization decides which
    representation matters; the preprocessing layer never replaces a raw statistic
    with a shrunken value.
    """
    out = frame.copy()
    derived = {}
    for prefix in ("RawSeason", "RawRecent3", "State", "Recent3"):
        for metric in _NCAAF_STAT_PROFILE_METRICS:
            ac = f"A_{prefix}_{metric}"; bc = f"B_{prefix}_{metric}"
            if ac not in out.columns or bc not in out.columns:
                continue
            a = pd.to_numeric(out[ac], errors="coerce")
            b = pd.to_numeric(out[bc], errors="coerce")
            derived[f"Sum_{prefix}_{metric}"] = (a + b).astype("float64")
            derived[f"Mean_{prefix}_{metric}"] = ((a + b) / 2.0).astype("float64")

        for label, off_metric, def_metric in _NCAAF_STAT_MATCHUP_PAIRS:
            ao=f"A_{prefix}_{off_metric}"; bo=f"B_{prefix}_{off_metric}"
            ad=f"A_{prefix}_{def_metric}"; bd=f"B_{prefix}_{def_metric}"
            if not all(c in out.columns for c in (ao,bo,ad,bd)):
                continue
            ma = pd.to_numeric(out[ao], errors="coerce") - pd.to_numeric(out[bd], errors="coerce")
            mb = pd.to_numeric(out[bo], errors="coerce") - pd.to_numeric(out[ad], errors="coerce")
            derived[f"Matchup_A_{prefix}_{label}"] = ma.astype("float64")
            derived[f"Matchup_B_{prefix}_{label}"] = mb.astype("float64")
            derived[f"Matchup_Diff_{prefix}_{label}"] = (ma-mb).astype("float64")
            derived[f"Matchup_Sum_{prefix}_{label}"] = (ma+mb).astype("float64")
    if derived:
        out = pd.concat([out, pd.DataFrame(derived, index=out.index)], axis=1, copy=False)
    return out.replace([np.inf,-np.inf],np.nan), list(derived.keys())


def _ncaaf_stat_safe_ratio(num, den):
    n = pd.to_numeric(num, errors="coerce").astype("float64")
    d = pd.to_numeric(den, errors="coerce").astype("float64")
    return (n / d.where(d.abs() > 1e-9)).replace([np.inf, -np.inf], np.nan)


def _ncaaf_stat_empirical_prob_gt(threshold, residuals):
    """P(residual > threshold) using a saved time-forward OOF residual sample."""
    thr = np.asarray(threshold, dtype=float)
    r = np.asarray(residuals if residuals is not None else [], dtype=float)
    r = np.sort(r[np.isfinite(r)])
    out = np.full(thr.shape, np.nan, dtype=float)
    if r.size < 30:
        return out
    ok = np.isfinite(thr)
    pos = np.searchsorted(r, thr[ok], side="right")
    out[ok] = 1.0 - (pos.astype(float) / float(r.size))
    # avoid exact 0/1 from a finite empirical sample
    eps = 0.5 / float(r.size + 1)
    return np.clip(out, eps, 1.0 - eps)


def _ncaaf_stat_logloss(y, p):
    from sklearn.metrics import log_loss
    y = np.asarray(y, dtype=int)
    p = np.asarray(p, dtype=float)
    ok = np.isfinite(p)
    if ok.sum() < 20 or np.unique(y[ok]).size < 2:
        return np.nan
    return float(log_loss(y[ok], np.clip(p[ok], 1e-5, 1-1e-5), labels=[0,1]))


def _ncaaf_stat_auc(y, p):
    from sklearn.metrics import roc_auc_score
    y = np.asarray(y, dtype=int)
    p = np.asarray(p, dtype=float)
    ok = np.isfinite(p)
    if ok.sum() < 20 or np.unique(y[ok]).size < 2:
        return np.nan
    try:
        return float(roc_auc_score(y[ok], p[ok]))
    except Exception:
        return np.nan


def _ncaaf_stat_brier(y, p):
    y = np.asarray(y, dtype=float); p = np.asarray(p, dtype=float)
    ok = np.isfinite(y) & np.isfinite(p)
    return float(np.mean((p[ok]-y[ok])**2)) if ok.sum() else np.nan


def _ncaaf_stat_new_margin_models():
    from sklearn.pipeline import Pipeline
    from sklearn.impute import SimpleImputer
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import Ridge
    from sklearn.ensemble import HistGradientBoostingRegressor
    linear = Pipeline([
        ("imputer", SimpleImputer(strategy="median", add_indicator=True)),
        ("scale", StandardScaler()),
        ("ridge", Ridge(alpha=20.0)),
    ])
    nonlinear = Pipeline([
        ("imputer", SimpleImputer(strategy="median", add_indicator=False)),
        ("hgb", HistGradientBoostingRegressor(
            loss="squared_error", learning_rate=0.04, max_iter=140,
            max_leaf_nodes=15, max_depth=3, min_samples_leaf=25,
            l2_regularization=2.0, random_state=42,
        )),
    ])
    return linear, nonlinear


def _ncaaf_stat_blend_predict(models, X, linear_weight=0.75):
    lin, nonlin = models
    p1 = np.asarray(lin.predict(X), dtype=float)
    p2 = np.asarray(nonlin.predict(X), dtype=float)
    w = float(np.clip(linear_weight, 0.0, 1.0))
    return w*p1 + (1.0-w)*p2


# -----------------------------------------------------------------------------
# V12.1 Statistical Brain feature qualification
# -----------------------------------------------------------------------------
# All candidate football statistics are still calculated.  Admission to the
# production structural model is earned separately for margin and total using
# chronological, season-forward validation that excludes the latest protected
# shadow season.  A synthetic intercept column lets every real feature be rejected
# if it fails to add out-of-sample value.
_NCAAF_STAT_INTERCEPT_FEATURE = "Context_Intercept"
_NCAAF_STAT_QUAL_MIN_TRAIN_ROWS = 450
_NCAAF_STAT_QUAL_MIN_VALID_ROWS = 75
_NCAAF_STAT_QUAL_MIN_RMSE_GAIN = 0.010       # points; deliberately small but non-zero
_NCAAF_STAT_QUAL_MAX_MAE_GIVEBACK = 0.005   # do not buy RMSE with material MAE damage
_NCAAF_STAT_QUAL_MIN_POSITIVE_FOLD_FRAC = 0.50
_NCAAF_STAT_QUAL_MAX_FEATURES_PER_TARGET = 48


def _ncaaf_stat_new_qualification_model():
    """Fast regularized model used only to decide whether a candidate earns entry."""
    from sklearn.pipeline import Pipeline
    from sklearn.impute import SimpleImputer
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import Ridge
    return Pipeline([
        ("imputer", SimpleImputer(strategy="median", add_indicator=True)),
        ("scale", StandardScaler()),
        ("ridge", Ridge(alpha=24.0)),
    ])


def _ncaaf_stat_feature_family(feature_name: str) -> str:
    """Readable family label for diagnostics; does not control acceptance."""
    c = str(feature_name or "")
    if c.startswith("Matchup_"):
        return "matchup"
    if c.startswith("Sum_") or c.startswith("Mean_"):
        return "total_combination"
    if c.startswith("Context_"):
        return "context"
    for prefix in ("A_RawSeason_", "B_RawSeason_", "Diff_RawSeason_", "A_RawRecent3_", "B_RawRecent3_", "Diff_RawRecent3_", "A_State_", "B_State_", "Diff_State_", "A_Recent3_", "B_Recent3_", "Diff_Recent3_"):
        if c.startswith(prefix):
            metric = c[len(prefix):]
            if metric.startswith("GameAdj_"):
                return "opponent_adjusted"
            if "Plays" in metric or "Pass_Rate" in metric or "Rush_Rate" in metric:
                return "tempo_play_mix"
            if "Pass" in metric or "Completion" in metric:
                return "passing"
            if "Rush" in metric:
                return "rushing"
            if "Turnover" in metric or "Takeaway" in metric:
                return "turnovers"
            if "FirstDown" in metric:
                return "down_conversion_proxy"
            if "YPP" in metric or "Points_Per_Play" in metric:
                return "efficiency"
            return "other_stat"
    return "other"


def _ncaaf_stat_qualification_eval(
    games: pd.DataFrame,
    feature_cols,
    target_col: str,
    market_col: str,
    qualification_seasons,
    *,
    market_weight: float = 0.15,
):
    """Chronological OOF evaluation for one candidate feature set.

    The latest season is never supplied here.  Each validation season is predicted
    only by a Ridge model fit on strictly earlier seasons.  The score is evaluated
    after the same market shrinkage used by the production Statistical Brain.
    """
    cols = list(dict.fromkeys([c for c in feature_cols if c in games.columns]))
    if not cols:
        cols = [_NCAAF_STAT_INTERCEPT_FEATURE]
    season = pd.to_numeric(games.get("Season"), errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    y_all = pd.to_numeric(games.get(target_col), errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    market_all = pd.to_numeric(games.get(market_col), errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    pred_all = np.full(len(games), np.nan, dtype=float)
    fold_rows = []

    for val_season in qualification_seasons:
        tr = np.isfinite(season) & (season < float(val_season)) & np.isfinite(y_all)
        va = np.isfinite(season) & (season == float(val_season)) & np.isfinite(y_all)
        if int(tr.sum()) < _NCAAF_STAT_QUAL_MIN_TRAIN_ROWS or int(va.sum()) < _NCAAF_STAT_QUAL_MIN_VALID_ROWS:
            continue
        model = _ncaaf_stat_new_qualification_model()
        try:
            model.fit(games.loc[tr, cols], y_all[tr])
            structural = np.asarray(model.predict(games.loc[va, cols]), dtype=float)
        except Exception:
            continue
        mv = market_all[va]
        blended = np.where(np.isfinite(mv), (1.0-market_weight)*mv + market_weight*structural, structural)
        idx = np.where(va)[0]
        pred_all[idx] = blended
        ok = np.isfinite(blended) & np.isfinite(y_all[idx])
        if int(ok.sum()) < 20:
            continue
        err = y_all[idx][ok] - blended[ok]
        market_ok = np.isfinite(mv[ok])
        market_rmse = float(np.sqrt(np.mean((y_all[idx][ok][market_ok] - mv[ok][market_ok])**2))) if market_ok.any() else np.nan
        market_mae = float(np.mean(np.abs(y_all[idx][ok][market_ok] - mv[ok][market_ok]))) if market_ok.any() else np.nan
        fold_rows.append({
            "season": int(val_season),
            "n": int(ok.sum()),
            "rmse": float(np.sqrt(np.mean(err**2))),
            "mae": float(np.mean(np.abs(err))),
            "market_rmse": market_rmse,
            "market_mae": market_mae,
        })

    ok = np.isfinite(pred_all) & np.isfinite(y_all)
    if int(ok.sum()) < 50:
        return {"n": int(ok.sum()), "rmse": np.nan, "mae": np.nan, "folds": fold_rows}
    err = y_all[ok] - pred_all[ok]
    return {
        "n": int(ok.sum()),
        "rmse": float(np.sqrt(np.mean(err**2))),
        "mae": float(np.mean(np.abs(err))),
        "folds": fold_rows,
    }


def _ncaaf_stat_feature_qualifies(base_eval: dict, trial_eval: dict):
    br = float(base_eval.get("rmse", np.nan)); tr = float(trial_eval.get("rmse", np.nan))
    bm = float(base_eval.get("mae", np.nan)); tm = float(trial_eval.get("mae", np.nan))
    if not np.isfinite(br) or not np.isfinite(tr) or not np.isfinite(bm) or not np.isfinite(tm):
        return False, {"rmse_gain": np.nan, "mae_gain": np.nan, "positive_fold_frac": 0.0}
    rmse_gain = br - tr
    mae_gain = bm - tm
    bf = {int(x.get("season")): x for x in base_eval.get("folds", []) if np.isfinite(x.get("rmse", np.nan))}
    tf = {int(x.get("season")): x for x in trial_eval.get("folds", []) if np.isfinite(x.get("rmse", np.nan))}
    common = sorted(set(bf).intersection(tf))
    fold_gains = [float(bf[s]["rmse"] - tf[s]["rmse"]) for s in common]
    positive_frac = float(np.mean(np.asarray(fold_gains) > 0.0)) if fold_gains else 0.0
    # One usable fold needs a little more absolute evidence.  With two or more,
    # require at least half of chronological folds to agree on direction.
    min_gain = _NCAAF_STAT_QUAL_MIN_RMSE_GAIN * (2.0 if len(common) <= 1 else 1.0)
    fold_ok = bool(fold_gains) and (positive_frac >= (1.0 if len(common) <= 1 else _NCAAF_STAT_QUAL_MIN_POSITIVE_FOLD_FRAC))
    ok = (
        rmse_gain >= min_gain
        and mae_gain >= -_NCAAF_STAT_QUAL_MAX_MAE_GIVEBACK
        and fold_ok
    )
    return bool(ok), {
        "rmse_gain": float(rmse_gain),
        "mae_gain": float(mae_gain),
        "positive_fold_frac": float(positive_frac),
        "fold_gains": fold_gains,
    }


def _ncaaf_stat_qualify_features(
    games: pd.DataFrame,
    candidate_feature_cols,
    target_col: str,
    market_col: str,
    seasons,
    *,
    market_weight: float,
    label: str,
    log_func=print,
    qual_seasons_override=None,
):
    """Greedy chronological admission test; every accepted real feature adds OOS skill."""
    seasons = [int(s) for s in seasons]
    latest = max(seasons)
    if qual_seasons_override is None:
        qual_seasons = [s for s in seasons[1:] if s < latest]
        # If history is only three seasons, there is still one pre-shadow validation season.
        if not qual_seasons and len(seasons) >= 2:
            qual_seasons = [seasons[-2]]
    else:
        # V13 nested/as-of research path: feature admission itself may only use
        # validation seasons that occurred strictly before the season being predicted.
        qual_seasons = sorted({int(s) for s in qual_seasons_override if int(s) in set(seasons)})

    baseline_cols = [_NCAAF_STAT_INTERCEPT_FEATURE]
    base_eval = _ncaaf_stat_qualification_eval(
        games, baseline_cols, target_col, market_col, qual_seasons, market_weight=market_weight
    )
    diagnostics = {}
    ranked = []
    candidates = [
        c for c in list(dict.fromkeys(candidate_feature_cols))
        if c in games.columns and c != _NCAAF_STAT_INTERCEPT_FEATURE
    ]

    # Fast individual screen against the same intercept-only chronological baseline.
    for feat in candidates:
        trial = _ncaaf_stat_qualification_eval(
            games, baseline_cols + [feat], target_col, market_col, qual_seasons, market_weight=market_weight
        )
        ok, delta = _ncaaf_stat_feature_qualifies(base_eval, trial)
        diagnostics[feat] = {
            "family": _ncaaf_stat_feature_family(feat),
            "screen_pass": bool(ok),
            "screen_rmse": float(trial.get("rmse", np.nan)),
            "screen_mae": float(trial.get("mae", np.nan)),
            **delta,
        }
        if ok:
            ranked.append((float(delta.get("rmse_gain", -np.inf)), feat))
    ranked.sort(reverse=True)

    accepted = list(baseline_cols)
    current_eval = base_eval
    for _, feat in ranked:
        if len(accepted) - 1 >= _NCAAF_STAT_QUAL_MAX_FEATURES_PER_TARGET:
            diagnostics[feat]["accepted"] = False
            diagnostics[feat]["reject_reason"] = "feature_cap"
            continue
        trial = _ncaaf_stat_qualification_eval(
            games, accepted + [feat], target_col, market_col, qual_seasons, market_weight=market_weight
        )
        ok, delta = _ncaaf_stat_feature_qualifies(current_eval, trial)
        diagnostics[feat]["incremental_rmse_gain"] = float(delta.get("rmse_gain", np.nan))
        diagnostics[feat]["incremental_mae_gain"] = float(delta.get("mae_gain", np.nan))
        diagnostics[feat]["incremental_positive_fold_frac"] = float(delta.get("positive_fold_frac", 0.0))
        diagnostics[feat]["accepted"] = bool(ok)
        if ok:
            accepted.append(feat)
            current_eval = trial
        else:
            diagnostics[feat]["reject_reason"] = "no_incremental_oos_gain"

    for feat in candidates:
        diagnostics.setdefault(feat, {"family": _ncaaf_stat_feature_family(feat)})
        diagnostics[feat].setdefault("accepted", False)
        if not diagnostics[feat].get("screen_pass", False):
            diagnostics[feat].setdefault("reject_reason", "failed_individual_oos_screen")

    accepted_real = [c for c in accepted if c != _NCAAF_STAT_INTERCEPT_FEATURE]
    rejected = [c for c in candidates if c not in set(accepted_real)]
    family_counts = {}
    for c in accepted_real:
        fam = _ncaaf_stat_feature_family(c)
        family_counts[fam] = family_counts.get(fam, 0) + 1
    _br=float(base_eval.get("rmse",np.nan)); _fr=float(current_eval.get("rmse",np.nan))
    _bm=float(base_eval.get("mae",np.nan)); _fm=float(current_eval.get("mae",np.nan))
    log_func(
        f"[NCAAF-STAT-FEATURE-GATE] target={label} qual_seasons={qual_seasons} "
        f"candidates={len(candidates)} accepted={len(accepted_real)} rejected={len(rejected)} "
        f"baseline_rmse={_br:.4f} final_rmse={_fr:.4f} rmse_gain={_br-_fr:+.4f} "
        f"baseline_mae={_bm:.4f} final_mae={_fm:.4f} mae_gain={_bm-_fm:+.4f} families={family_counts}"
    )
    if accepted_real:
        log_func(f"[NCAAF-STAT-FEATURE-GATE] target={label} accepted_cols={accepted_real}")
        for _c in accepted_real:
            _d=diagnostics.get(_c,{})
            log_func(
                f"[NCAAF-STAT-FEATURE-ACCEPT] target={label} feature={_c} family={_d.get('family')} "
                f"screen_gain={float(_d.get('rmse_gain',np.nan)):+.4f} "
                f"incremental_gain={float(_d.get('incremental_rmse_gain',np.nan)):+.4f} "
                f"mae_gain={float(_d.get('incremental_mae_gain',np.nan)):+.4f} "
                f"fold_positive={float(_d.get('incremental_positive_fold_frac',0.0)):.0%}"
            )
    return accepted, {
        "target": label,
        "qualification_seasons": qual_seasons,
        "candidate_count": len(candidates),
        "accepted": accepted_real,
        "rejected": rejected,
        "baseline_eval": base_eval,
        "final_eval": current_eval,
        "family_counts": family_counts,
        "diagnostics": diagnostics,
        "rules": {
            "min_train_rows": _NCAAF_STAT_QUAL_MIN_TRAIN_ROWS,
            "min_valid_rows": _NCAAF_STAT_QUAL_MIN_VALID_ROWS,
            "min_rmse_gain": _NCAAF_STAT_QUAL_MIN_RMSE_GAIN,
            "max_mae_giveback": _NCAAF_STAT_QUAL_MAX_MAE_GIVEBACK,
            "min_positive_fold_frac": _NCAAF_STAT_QUAL_MIN_POSITIVE_FOLD_FRAC,
            "max_features": _NCAAF_STAT_QUAL_MAX_FEATURES_PER_TARGET,
            "latest_shadow_excluded": True,
        },
    }


def _ncaaf_stat_build_game_frame(raw: pd.DataFrame):
    """Create one leakage-safe structural row per physical historical game."""
    if raw is None or raw.empty:
        return pd.DataFrame(), [], pd.DataFrame()
    r = raw.copy()
    r.columns = [str(c).strip() for c in r.columns]
    r["Game_Date"] = pd.to_datetime(r.get("Game_Date"), errors="coerce", utc=True)
    r["Season"] = pd.to_numeric(r.get("Season"), errors="coerce")
    r["Team_Norm"] = r.get("Team_Norm", r.get("Team", "")).astype(str).str.lower().str.strip()
    r["Opponent_Norm"] = r.get("Opponent_Norm", r.get("Opponent", "")).astype(str).str.lower().str.strip()
    r["Source_Game_ID"] = r.get("Source_Game_ID", "").astype(str)

    numeric_cols = [
        "Is_Home","Is_Away","Is_Neutral","Team_Score","Opponent_Score",
        "Consensus_Open_Spread","Consensus_Open_Total","Consensus_Open_Moneyline",
        "Postgame_First_Downs","Postgame_Total_Yards","Postgame_Total_Plays",
        "Postgame_Pass_Comp","Postgame_Pass_Att","Postgame_Pass_Yards",
        "Postgame_Rush_Att","Postgame_Rush_Yards","Postgame_Turnovers",
        "Q1_Points","Q2_Points","Q3_Points",
    ]
    for c in numeric_cols:
        if c not in r.columns: r[c] = np.nan
        r[c] = pd.to_numeric(r[c], errors="coerce").astype("float64")

    r["Off_YPP"] = _ncaaf_stat_safe_ratio(r["Postgame_Total_Yards"], r["Postgame_Total_Plays"])
    r["Off_Pass_YPA"] = _ncaaf_stat_safe_ratio(r["Postgame_Pass_Yards"], r["Postgame_Pass_Att"])
    r["Off_Rush_YPA"] = _ncaaf_stat_safe_ratio(r["Postgame_Rush_Yards"], r["Postgame_Rush_Att"])
    r["Off_Completion_Rate"] = _ncaaf_stat_safe_ratio(r["Postgame_Pass_Comp"], r["Postgame_Pass_Att"])
    r["Off_Points_Per_Play"] = _ncaaf_stat_safe_ratio(r["Team_Score"], r["Postgame_Total_Plays"])
    r["Off_Turnover_Rate"] = _ncaaf_stat_safe_ratio(r["Postgame_Turnovers"], r["Postgame_Total_Plays"])
    r["Off_FirstDown_Rate"] = _ncaaf_stat_safe_ratio(r["Postgame_First_Downs"], r["Postgame_Total_Plays"])
    r["Off_Plays_Per_Game"] = pd.to_numeric(r["Postgame_Total_Plays"], errors="coerce")
    r["Off_Pass_Rate"] = _ncaaf_stat_safe_ratio(r["Postgame_Pass_Att"], r["Postgame_Total_Plays"])
    r["Off_Rush_Rate"] = _ncaaf_stat_safe_ratio(r["Postgame_Rush_Att"], r["Postgame_Total_Plays"])
    r["Off_Yards_Per_Completion"] = _ncaaf_stat_safe_ratio(r["Postgame_Pass_Yards"], r["Postgame_Pass_Comp"])

    # Current-game opponent offense is used only to define this game's defensive
    # performance. Every defensive predictor below is subsequently shifted.
    off_cols = [c for c in _NCAAF_STAT_METRICS if c.startswith("Off_")]
    opp_actual = r[["Season","Source_Game_ID","Team_Norm"] + off_cols].copy()
    opp_actual = opp_actual.rename(columns={"Team_Norm":"Opponent_Norm", **{c:f"__OppActual_{c}" for c in off_cols}})
    r = r.merge(opp_actual, on=["Season","Source_Game_ID","Opponent_Norm"], how="left", validate="many_to_one")
    r["Def_YPP_Allowed"] = r["__OppActual_Off_YPP"]
    r["Def_Pass_YPA_Allowed"] = r["__OppActual_Off_Pass_YPA"]
    r["Def_Rush_YPA_Allowed"] = r["__OppActual_Off_Rush_YPA"]
    r["Def_Points_Per_Play_Allowed"] = r["__OppActual_Off_Points_Per_Play"]
    r["Def_Takeaway_Rate"] = r["__OppActual_Off_Turnover_Rate"]
    r["Def_Plays_Faced"] = r["__OppActual_Off_Plays_Per_Game"]
    r["Def_Pass_Rate_Faced"] = r["__OppActual_Off_Pass_Rate"]
    r["Def_Rush_Rate_Faced"] = r["__OppActual_Off_Rush_Rate"]
    r["Def_Yards_Per_Completion_Allowed"] = r["__OppActual_Off_Yards_Per_Completion"]

    r = r.sort_values(["Team_Norm","Season","Game_Date","Source_Game_ID"], kind="stable").reset_index(drop=True)
    grp_keys = [r["Season"], r["Team_Norm"]]
    r["__Games_Prior"] = r.groupby(["Season","Team_Norm"], sort=False).cumcount().astype(float)

    # V13.0.16 early-season situational state.  These fields are all shifted
    # within team-season, so the current game's result can never enter its own
    # prediction.  The continuous prior margins let the model learn recency/
    # overreaction effects; the threshold flags are low-dimensional expert
    # hypotheses that remain gated by season-forward OOS proper scores.
    _cur_su = pd.to_numeric(r["Team_Score"], errors="coerce") - pd.to_numeric(r["Opponent_Score"], errors="coerce")
    _cur_sp = pd.to_numeric(r["Consensus_Open_Spread"], errors="coerce")
    _cur_ats = _cur_su + _cur_sp
    # Series expressions do not have a stable source-column name, so shift the
    # derived values explicitly through temporary columns.
    r["__Current_SU_Margin"] = _cur_su.astype("float64")
    r["__Current_ATS_Margin"] = _cur_ats.astype("float64")
    r["Pregame_Prev_SU_Margin"] = r.groupby(["Season","Team_Norm"], sort=False)["__Current_SU_Margin"].shift(1)
    r["Pregame_Prev_ATS_Margin"] = r.groupby(["Season","Team_Norm"], sort=False)["__Current_ATS_Margin"].shift(1)
    r["Pregame_Prev_Points_For"] = r.groupby(["Season","Team_Norm"], sort=False)["Team_Score"].shift(1)
    r["Pregame_Prev_Points_Against"] = r.groupby(["Season","Team_Norm"], sort=False)["Opponent_Score"].shift(1)
    _psu = pd.to_numeric(r["Pregame_Prev_SU_Margin"], errors="coerce")
    _pats = pd.to_numeric(r["Pregame_Prev_ATS_Margin"], errors="coerce")
    r["Pregame_Prev_BigWin21"] = np.where(_psu.notna(), (_psu >= 21).astype(float), np.nan)
    r["Pregame_Prev_BigLoss21"] = np.where(_psu.notna(), (_psu <= -21).astype(float), np.nan)
    r["Pregame_Prev_BigCover10"] = np.where(_pats.notna(), (_pats >= 10).astype(float), np.nan)
    r["Pregame_Prev_BigMiss10"] = np.where(_pats.notna(), (_pats <= -10).astype(float), np.nan)

    # Prior-season profile and national prior for early-season stabilization.
    summaries = r.groupby(["Season","Team_Norm"], as_index=False)[list(_NCAAF_STAT_METRICS)].mean()
    prev = summaries.copy(); prev["Season"] = prev["Season"] + 1
    prev = prev.rename(columns={c:f"__PrevSeason_{c}" for c in _NCAAF_STAT_METRICS})
    r = r.merge(prev, on=["Season","Team_Norm"], how="left", validate="many_to_one")
    nat = summaries.groupby("Season", as_index=False)[list(_NCAAF_STAT_METRICS)].mean()
    nat["Season"] = nat["Season"] + 1
    nat = nat.rename(columns={c:f"__PrevNat_{c}" for c in _NCAAF_STAT_METRICS})
    r = r.merge(nat, on="Season", how="left", validate="many_to_one")

    state_cols=[]
    for c in _NCAAF_STAT_METRICS:
        season_prior = r.groupby(["Season","Team_Norm"], sort=False)[c].transform(
            lambda s: pd.to_numeric(s, errors="coerce").shift(1).expanding(min_periods=1).mean()
        )
        recent3 = r.groupby(["Season","Team_Norm"], sort=False)[c].transform(
            lambda s: pd.to_numeric(s, errors="coerce").shift(1).rolling(3, min_periods=1).mean()
        )
        prev_team = pd.to_numeric(r.get(f"__PrevSeason_{c}"), errors="coerce")
        prev_nat = pd.to_numeric(r.get(f"__PrevNat_{c}"), errors="coerce")
        preseason = (0.72*prev_team + 0.28*prev_nat).where(prev_team.notna(), prev_nat)
        n = r["__Games_Prior"].clip(lower=0)
        # Raw observed summaries are never shrunk.  They are the literal prior-only
        # season-to-date and recent-3 performance.  Stabilized State/Recent3 remain
        # separate latent candidates so ML can decide whether stabilization helps.
        r[f"RawSeason_{c}"] = season_prior.astype("float64")
        r[f"RawRecent3_{c}"] = recent3.astype("float64")
        blended = (3.0*preseason.fillna(season_prior) + n*season_prior.fillna(preseason)) / (3.0+n).replace(0,np.nan)
        blended = blended.combine_first(season_prior).combine_first(preseason)
        r[f"State_{c}"] = blended.astype("float64")
        r[f"Recent3_{c}"] = recent3.combine_first(blended).astype("float64")
        state_cols += [f"RawSeason_{c}", f"RawRecent3_{c}", f"State_{c}", f"Recent3_{c}"]

    # -----------------------------------------------------------------
    # Opponent-adjusted efficiency residuals.
    # A game performance is measured against what that opponent had allowed/
    # produced BEFORE the game.  The residual itself is then shifted into future
    # games, so current-game statistics never leak into the current prediction.
    # Q3/final blowout context is retained as diagnostic metadata only.  V13.2.5
    # does not rewrite the observed box-score performance; ML may learn whether
    # competitive-game context changes the predictive value of those observations.
    # -----------------------------------------------------------------
    opp_preg_cols = [
        "State_Def_YPP_Allowed","State_Def_Pass_YPA_Allowed","State_Def_Rush_YPA_Allowed",
        "State_Def_Points_Per_Play_Allowed","State_Off_YPP","State_Off_Pass_YPA",
        "State_Off_Rush_YPA","State_Off_Points_Per_Play",
        "Q1_Points","Q2_Points","Q3_Points",
    ]
    opp_preg = r[["Season","Source_Game_ID","Team_Norm"] + [c for c in opp_preg_cols if c in r.columns]].copy()
    opp_preg = opp_preg.rename(columns={"Team_Norm":"Opponent_Norm", **{c:f"__OppPreg_{c}" for c in opp_preg_cols if c in r.columns}})
    r = r.merge(opp_preg, on=["Season","Source_Game_ID","Opponent_Norm"], how="left", validate="many_to_one")

    q3_team = pd.to_numeric(r.get("Q1_Points"),errors="coerce").fillna(0) + pd.to_numeric(r.get("Q2_Points"),errors="coerce").fillna(0) + pd.to_numeric(r.get("Q3_Points"),errors="coerce").fillna(0)
    q3_opp = pd.to_numeric(r.get("__OppPreg_Q1_Points"),errors="coerce").fillna(0) + pd.to_numeric(r.get("__OppPreg_Q2_Points"),errors="coerce").fillna(0) + pd.to_numeric(r.get("__OppPreg_Q3_Points"),errors="coerce").fillna(0)
    q3_margin = (q3_team-q3_opp).abs()
    final_margin = (pd.to_numeric(r["Team_Score"],errors="coerce")-pd.to_numeric(r["Opponent_Score"],errors="coerce")).abs()
    comp_w = pd.Series(np.where(q3_margin.ge(28),0.65,np.where(final_margin.ge(28),0.80,1.0)),index=r.index,dtype="float64")
    r["Competitive_Game_Weight"] = comp_w

    adj_defs = {
        "GameAdj_Off_YPP": ("Off_YPP","__OppPreg_State_Def_YPP_Allowed",+1),
        "GameAdj_Def_YPP": ("__OppPreg_State_Off_YPP","Def_YPP_Allowed",+1),
        "GameAdj_Off_Pass_YPA": ("Off_Pass_YPA","__OppPreg_State_Def_Pass_YPA_Allowed",+1),
        "GameAdj_Def_Pass_YPA": ("__OppPreg_State_Off_Pass_YPA","Def_Pass_YPA_Allowed",+1),
        "GameAdj_Off_Rush_YPA": ("Off_Rush_YPA","__OppPreg_State_Def_Rush_YPA_Allowed",+1),
        "GameAdj_Def_Rush_YPA": ("__OppPreg_State_Off_Rush_YPA","Def_Rush_YPA_Allowed",+1),
        "GameAdj_Off_Points_Per_Play": ("Off_Points_Per_Play","__OppPreg_State_Def_Points_Per_Play_Allowed",+1),
        "GameAdj_Def_Points_Per_Play": ("__OppPreg_State_Off_Points_Per_Play","Def_Points_Per_Play_Allowed",+1),
    }
    for name,(lhs,rhs,_) in adj_defs.items():
        lv=pd.to_numeric(r.get(lhs),errors="coerce"); rv=pd.to_numeric(r.get(rhs),errors="coerce")
        # Preserve the observed opponent-adjusted performance exactly. Competitive
        # game weight is retained as context/diagnostic metadata; it no longer
        # rewrites the team's measured performance before ML sees it.
        r[name]=(lv-rv).astype("float64")

    adj_summaries = r.groupby(["Season","Team_Norm"],as_index=False)[list(_NCAAF_STAT_ADJ_METRICS)].mean()
    adj_prev=adj_summaries.copy(); adj_prev["Season"]=adj_prev["Season"]+1
    adj_prev=adj_prev.rename(columns={c:f"__PrevSeason_{c}" for c in _NCAAF_STAT_ADJ_METRICS})
    r=r.merge(adj_prev,on=["Season","Team_Norm"],how="left",validate="many_to_one")
    adj_nat=adj_summaries.groupby("Season",as_index=False)[list(_NCAAF_STAT_ADJ_METRICS)].mean(); adj_nat["Season"]=adj_nat["Season"]+1
    adj_nat=adj_nat.rename(columns={c:f"__PrevNat_{c}" for c in _NCAAF_STAT_ADJ_METRICS})
    r=r.merge(adj_nat,on="Season",how="left",validate="many_to_one")
    for c in _NCAAF_STAT_ADJ_METRICS:
        season_prior=r.groupby(["Season","Team_Norm"],sort=False)[c].transform(lambda s: pd.to_numeric(s,errors="coerce").shift(1).expanding(min_periods=1).mean())
        recent3=r.groupby(["Season","Team_Norm"],sort=False)[c].transform(lambda s: pd.to_numeric(s,errors="coerce").shift(1).rolling(3,min_periods=1).mean())
        prev_team=pd.to_numeric(r.get(f"__PrevSeason_{c}"),errors="coerce"); prev_nat=pd.to_numeric(r.get(f"__PrevNat_{c}"),errors="coerce")
        preseason=(0.72*prev_team+0.28*prev_nat).where(prev_team.notna(),prev_nat)
        n=r["__Games_Prior"].clip(lower=0)
        r[f"RawSeason_{c}"]=season_prior.astype("float64")
        r[f"RawRecent3_{c}"]=recent3.astype("float64")
        blended=(3.0*preseason.fillna(season_prior)+n*season_prior.fillna(preseason))/(3.0+n).replace(0,np.nan)
        blended=blended.combine_first(season_prior).combine_first(preseason)
        r[f"State_{c}"]=blended.astype("float64"); r[f"Recent3_{c}"]=recent3.combine_first(blended).astype("float64")
        state_cols += [f"RawSeason_{c}",f"RawRecent3_{c}",f"State_{c}",f"Recent3_{c}"]

    # One anchor side per game. Home side when known; deterministic first side for neutral games.
    r["__HomeRank"] = np.where(r["Is_Home"].eq(1), 0, np.where(r["Is_Neutral"].eq(1), 1, 2))
    r = r.sort_values(["Season","Source_Game_ID","__HomeRank","Team_Norm"], kind="stable")
    anchor = r.drop_duplicates(["Season","Source_Game_ID"], keep="first").copy()

    _early_side_cols=[
        "__Games_Prior","Pregame_Prev_SU_Margin","Pregame_Prev_ATS_Margin",
        "Pregame_Prev_Points_For","Pregame_Prev_Points_Against",
        "Pregame_Prev_BigWin21","Pregame_Prev_BigLoss21",
        "Pregame_Prev_BigCover10","Pregame_Prev_BigMiss10",
    ]
    opp_state = r[["Season","Source_Game_ID","Team_Norm"] + state_cols + ["Consensus_Open_Moneyline"] + [c for c in _early_side_cols if c in r.columns]].copy()
    opp_state = opp_state.rename(columns={
        "Team_Norm":"Opponent_Norm", "Consensus_Open_Moneyline":"Opp_Consensus_Open_Moneyline",
        **{c:f"Opp_{c}" for c in state_cols}, **{c:f"Opp_{c}" for c in _early_side_cols if c in r.columns}
    })
    anchor = anchor.merge(opp_state, on=["Season","Source_Game_ID","Opponent_Norm"], how="left", validate="one_to_one")

    feature_cols=[]
    for c in state_cols:
        a = pd.to_numeric(anchor[c], errors="coerce")
        b = pd.to_numeric(anchor[f"Opp_{c}"], errors="coerce")
        if c.startswith("RawSeason_"):
            prefix="RawSeason"; base=c[len("RawSeason_"):]
        elif c.startswith("RawRecent3_"):
            prefix="RawRecent3"; base=c[len("RawRecent3_"):]
        elif c.startswith("State_"):
            prefix="State"; base=c[len("State_"):]
        else:
            prefix="Recent3"; base=c[len("Recent3_"): ]
        for nm, val in ((f"A_{prefix}_{base}",a),(f"B_{prefix}_{base}",b),(f"Diff_{prefix}_{base}",a-b)):
            anchor[nm] = val.astype("float64")
            feature_cols.append(nm)

    anchor[_NCAAF_STAT_INTERCEPT_FEATURE] = 0.0
    anchor["Context_Is_Neutral"] = pd.to_numeric(anchor["Is_Neutral"], errors="coerce").fillna(0).astype(float)
    anchor["Context_Week"] = pd.to_numeric(anchor.get("Week"), errors="coerce").astype(float)
    anchor["Context_A_FBS"] = anchor.get("Subdivision", pd.Series("",index=anchor.index)).astype(str).str.upper().eq("FBS").astype(float)
    anchor["Context_B_FBS"] = anchor.get("Opponent_Subdivision", pd.Series("",index=anchor.index)).astype(str).str.upper().eq("FBS").astype(float)
    anchor["Context_Cross_Subdivision"] = anchor["Context_A_FBS"].ne(anchor["Context_B_FBS"]).astype(float)

    # Games-played maturity is authoritative for V13 early-season handling.
    # Calendar week is retained only as a diagnostic because Week 0/Week 1 feeds
    # can legitimately number the opening full slate differently.
    anchor["Context_Team_Games_Prior"] = pd.to_numeric(anchor.get("__Games_Prior"), errors="coerce")
    anchor["Context_Opp_Games_Prior"] = pd.to_numeric(anchor.get("Opp___Games_Prior"), errors="coerce")
    anchor["Context_Min_Games_Prior"] = pd.concat([anchor["Context_Team_Games_Prior"],anchor["Context_Opp_Games_Prior"]],axis=1).min(axis=1,skipna=True)
    anchor["Context_Early_FirstTwo"] = anchor["Context_Min_Games_Prior"].le(1).astype(float).where(anchor["Context_Min_Games_Prior"].notna(),np.nan)
    anchor["Context_Prev_SU_Margin"] = pd.to_numeric(anchor.get("Pregame_Prev_SU_Margin"),errors="coerce")
    anchor["Context_Opp_Prev_SU_Margin"] = pd.to_numeric(anchor.get("Opp_Pregame_Prev_SU_Margin"),errors="coerce")
    anchor["Context_Prev_ATS_Margin"] = pd.to_numeric(anchor.get("Pregame_Prev_ATS_Margin"),errors="coerce")
    anchor["Context_Opp_Prev_ATS_Margin"] = pd.to_numeric(anchor.get("Opp_Pregame_Prev_ATS_Margin"),errors="coerce")
    for _nm in ("BigWin21","BigLoss21","BigCover10","BigMiss10"):
        anchor[f"Context_Prev_{_nm}"] = pd.to_numeric(anchor.get(f"Pregame_Prev_{_nm}"),errors="coerce")
        anchor[f"Context_Opp_Prev_{_nm}"] = pd.to_numeric(anchor.get(f"Opp_Pregame_Prev_{_nm}"),errors="coerce")
    _conf = anchor.get("Conference",pd.Series("",index=anchor.index)).astype(str).str.strip().str.lower()
    _oppconf = anchor.get("Opponent_Conference",pd.Series("",index=anchor.index)).astype(str).str.strip().str.lower()
    _conf_known=_conf.ne("")&_oppconf.ne("")
    anchor["Context_Is_NonConference"] = np.where(_conf_known,_conf.ne(_oppconf).astype(float),np.nan)
    feature_cols += [
        _NCAAF_STAT_INTERCEPT_FEATURE,"Context_Is_Neutral","Context_Week","Context_A_FBS","Context_B_FBS","Context_Cross_Subdivision",
        "Context_Team_Games_Prior","Context_Opp_Games_Prior","Context_Min_Games_Prior","Context_Early_FirstTwo",
    ]

    # V12.2: totals need combinations; spreads need explicit offense-vs-defense matchups.
    anchor, _derived_pair_cols = _ncaaf_stat_add_pair_features(anchor)
    feature_cols += _derived_pair_cols

    anchor["Actual_Margin"] = pd.to_numeric(anchor["Team_Score"],errors="coerce") - pd.to_numeric(anchor["Opponent_Score"],errors="coerce")
    anchor["Actual_Total"] = pd.to_numeric(anchor["Team_Score"],errors="coerce") + pd.to_numeric(anchor["Opponent_Score"],errors="coerce")
    anchor["Market_Open_Margin"] = -pd.to_numeric(anchor["Consensus_Open_Spread"], errors="coerce")
    anchor["Market_Open_Total"] = pd.to_numeric(anchor["Consensus_Open_Total"], errors="coerce")

    # opening ML fair probability for anchor side when both prices exist
    def _amer(o):
        o=pd.to_numeric(o,errors="coerce"); p=pd.Series(np.nan,index=o.index,dtype=float)
        neg=o<0; pos=o>0
        p.loc[neg]=(-o.loc[neg])/((-o.loc[neg])+100.0); p.loc[pos]=100.0/(o.loc[pos]+100.0)
        return p
    pa=_amer(anchor["Consensus_Open_Moneyline"]); pb=_amer(anchor["Opp_Consensus_Open_Moneyline"]); den=pa+pb
    anchor["Market_Open_H2H_Fair"]=(pa/den.where(den>0)).clip(0.01,0.99)

    # Latest loaded-season profile saved for the NEXT game. It mirrors the
    # historical three-pseudo-game prior-season shrinkage, so serving and training
    # use the same transition when partial current-season box scores are loaded.
    max_season = int(pd.to_numeric(r["Season"], errors="coerce").dropna().max())
    last = r.loc[pd.to_numeric(r["Season"],errors="coerce").eq(max_season)].copy()
    prof_rows=[]
    for team, g in last.groupby("Team_Norm", sort=False):
        g=g.sort_values(["Game_Date","Source_Game_ID"],kind="stable")
        rec={"Team_Norm":team,"Profile_Season":max_season,"Profile_Games":int(len(g))}
        n_games=float(len(g))
        for c in _NCAAF_STAT_PROFILE_METRICS:
            vals=pd.to_numeric(g[c],errors="coerce")
            cur=float(vals.mean()) if vals.notna().any() else np.nan
            prev_team=pd.to_numeric(g.get(f"__PrevSeason_{c}"),errors="coerce") if f"__PrevSeason_{c}" in g.columns else pd.Series(np.nan,index=g.index)
            prev_nat=pd.to_numeric(g.get(f"__PrevNat_{c}"),errors="coerce") if f"__PrevNat_{c}" in g.columns else pd.Series(np.nan,index=g.index)
            pt=float(prev_team.dropna().iloc[-1]) if prev_team.notna().any() else np.nan
            pn=float(prev_nat.dropna().iloc[-1]) if prev_nat.notna().any() else np.nan
            preseason=(0.72*pt+0.28*pn) if np.isfinite(pt) and np.isfinite(pn) else (pt if np.isfinite(pt) else pn)
            if np.isfinite(cur) and np.isfinite(preseason):
                nxt=(3.0*preseason+n_games*cur)/(3.0+n_games)
            elif np.isfinite(cur): nxt=cur
            else: nxt=preseason
            rec3=float(vals.tail(3).mean()) if vals.tail(3).notna().any() else np.nan
            # Preserve observed current-season performance separately from latent
            # stabilization. Missing raw state remains missing; the model receives
            # Profile_Games so it can learn how much evidence exists.
            rec[f"Profile_RawSeason_{c}"]=cur
            rec[f"Profile_RawRecent3_{c}"]=rec3
            rec[f"Profile_{c}"]=nxt
            rec[f"Profile_Recent3_{c}"]=rec3 if np.isfinite(rec3) else nxt
        prof_rows.append(rec)
    latest_profiles=pd.DataFrame(prof_rows)

    anchor = anchor.replace([np.inf,-np.inf],np.nan)
    return anchor.reset_index(drop=True), list(dict.fromkeys(feature_cols)), latest_profiles


# ============================================================================
# V13 NCAAF VALUE ARCHITECTURE — TRAINING / SHADOW RESEARCH
# ============================================================================
def _ncaaf_v13_norm_team_series(values):
    return (pd.Series(values).astype(str).str.lower().str.strip()
            .str.replace(".","",regex=False).str.replace("&","and",regex=False))

def _ncaaf_v13_pair_key(season, team_a, team_b):
    ss=pd.to_numeric(pd.Series(season),errors="coerce").round().astype("Int64").astype(str)
    aa=_ncaaf_v13_norm_team_series(team_a); bb=_ncaaf_v13_norm_team_series(team_b)
    lo=np.where(aa.to_numpy()<=bb.to_numpy(),aa.to_numpy(),bb.to_numpy())
    hi=np.where(aa.to_numpy()<=bb.to_numpy(),bb.to_numpy(),aa.to_numpy())
    return ss+"|"+pd.Series(lo,index=aa.index)+"|"+pd.Series(hi,index=aa.index)

def _ncaaf_v13_matchup_key(season, game_date, team_a, team_b):
    dd=pd.to_datetime(pd.Series(game_date),errors="coerce",utc=True).dt.strftime("%Y-%m-%d")
    return _ncaaf_v13_pair_key(season,team_a,team_b)+"|"+dd.fillna("")



def _ncaaf_v13_fundamental_feature_cols(games: pd.DataFrame):
    """Football representation with raw observations and latent estimates separated.

    RawSeason/RawRecent3 are literal prior-game aggregates. State/Recent3 are
    stabilized latent alternatives. Both are offered to chronological feature
    qualification; no preprocessing weight decides their importance in advance.
    """
    context = [
        "Context_Is_Neutral", "Context_Week", "Context_A_FBS", "Context_B_FBS", "Context_Cross_Subdivision",
        "Context_Team_Games_Prior", "Context_Opp_Games_Prior", "Context_Min_Games_Prior", "Context_Early_FirstTwo",
    ]
    margin = [c for c in context if c in games.columns]
    total = [c for c in context if c in games.columns]

    # Let ML choose raw observed state vs stabilized latent state.  Difference and
    # matchup families are suitable for margin; sum/mean and matchup-sum families
    # are suitable for totals. Power remains a separate leakage-safe candidate.
    for c in games.columns:
        s=str(c)
        if s.startswith(("Diff_RawSeason_","Diff_RawRecent3_","Matchup_Diff_RawSeason_","Matchup_Diff_RawRecent3_",
                         "Diff_State_","Diff_Recent3_","Matchup_Diff_State_","Matchup_Diff_Recent3_")):
            margin.append(s)
        if s.startswith(("Sum_RawSeason_","Mean_RawSeason_","Sum_RawRecent3_","Mean_RawRecent3_",
                         "Matchup_Sum_RawSeason_","Matchup_Sum_RawRecent3_",
                         "Sum_State_","Mean_State_","Sum_Recent3_","Mean_Recent3_",
                         "Matchup_Sum_State_","Matchup_Sum_Recent3_")):
            total.append(s)
    if "Power_Rating_Diff" in games.columns:
        margin.append("Power_Rating_Diff")
    return list(dict.fromkeys(margin)), list(dict.fromkeys(total))


def _ncaaf_v13_new_regressors():
    """Stable linear core plus shallow nonlinear residual capacity."""
    from sklearn.pipeline import Pipeline
    from sklearn.impute import SimpleImputer
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import Ridge
    from sklearn.ensemble import HistGradientBoostingRegressor
    linear = Pipeline([
        ("imputer", SimpleImputer(strategy="median", add_indicator=True)),
        ("scale", StandardScaler()),
        ("ridge", Ridge(alpha=24.0)),
    ])
    nonlinear = Pipeline([
        ("imputer", SimpleImputer(strategy="median", add_indicator=False)),
        ("hgb", HistGradientBoostingRegressor(
            loss="squared_error", learning_rate=0.035, max_iter=120,
            max_leaf_nodes=12, max_depth=3, min_samples_leaf=30,
            l2_regularization=4.0, random_state=1300,
        )),
    ])
    return linear, nonlinear



def _ncaaf_v13_new_robust_regressor():
    """Research-only robust margin candidate; never receives authority automatically."""
    from sklearn.pipeline import Pipeline
    from sklearn.impute import SimpleImputer
    from sklearn.ensemble import HistGradientBoostingRegressor
    return Pipeline([
        ("imputer", SimpleImputer(strategy="median", add_indicator=False)),
        ("hgb", HistGradientBoostingRegressor(
            loss="absolute_error", learning_rate=0.035, max_iter=120,
            max_leaf_nodes=12, max_depth=3, min_samples_leaf=30,
            l2_regularization=4.0, random_state=1308,
        )),
    ])

def _ncaaf_v13_fit_regression_pair(X, y):
    models = _ncaaf_v13_new_regressors()
    yy = pd.to_numeric(pd.Series(y), errors="coerce")
    good = yy.notna().to_numpy()
    models[0].fit(X.loc[good], yy.loc[good].to_numpy(dtype=float))
    models[1].fit(X.loc[good], yy.loc[good].to_numpy(dtype=float))
    return models


def _ncaaf_v13_regression_predict(models, X, linear_weight=0.80):
    p1 = np.asarray(models[0].predict(X), dtype=float)
    p2 = np.asarray(models[1].predict(X), dtype=float)
    w = float(np.clip(linear_weight, 0.0, 1.0))
    return w * p1 + (1.0 - w) * p2


def _ncaaf_v13_rmse(y, p):
    y=np.asarray(y,dtype=float); p=np.asarray(p,dtype=float); ok=np.isfinite(y)&np.isfinite(p)
    return float(np.sqrt(np.mean((y[ok]-p[ok])**2))) if ok.any() else np.nan


def _ncaaf_v13_mae(y, p):
    y=np.asarray(y,dtype=float); p=np.asarray(p,dtype=float); ok=np.isfinite(y)&np.isfinite(p)
    return float(np.mean(np.abs(y[ok]-p[ok]))) if ok.any() else np.nan

def _ncaaf_v13_bootstrap_regression_skill(actual, baseline, candidate, groups=None, reps=800, seed=1303):
    """Paired bootstrap skill using the same physical observations on both forecasts.

    Positive skill means candidate is better than baseline.  If groups are supplied,
    whole groups are resampled together (used for game-horizon Market Intelligence).
    """
    a=np.asarray(actual,dtype=float); b=np.asarray(baseline,dtype=float); c=np.asarray(candidate,dtype=float)
    ok=np.isfinite(a)&np.isfinite(b)&np.isfinite(c)
    if int(ok.sum()) < 50:
        return {"n":int(ok.sum()),"groups":0,"rmse_skill":np.nan,"mae_skill":np.nan,"rmse_skill_ci95":[np.nan,np.nan],"mae_skill_ci95":[np.nan,np.nan]}
    a=a[ok]; b=b[ok]; c=c[ok]
    if groups is None:
        g=np.arange(len(a)).astype(str)
    else:
        gg=np.asarray(groups,dtype=object)[ok]
        g=np.asarray([str(x) for x in gg],dtype=object)
    uniq=np.unique(g)
    if len(uniq) < 20:
        return {"n":len(a),"groups":len(uniq),"rmse_skill":np.nan,"mae_skill":np.nan,"rmse_skill_ci95":[np.nan,np.nan],"mae_skill_ci95":[np.nan,np.nan]}
    idx_by={u:np.flatnonzero(g==u) for u in uniq}
    rng=np.random.default_rng(seed)
    rm=[]; ma=[]
    for _ in range(int(reps)):
        draw=rng.choice(uniq,size=len(uniq),replace=True)
        idx=np.concatenate([idx_by[u] for u in draw])
        aa=a[idx]; bb=b[idx]; cc=c[idx]
        rm.append(_ncaaf_v13_rmse(aa,bb)-_ncaaf_v13_rmse(aa,cc))
        ma.append(_ncaaf_v13_mae(aa,bb)-_ncaaf_v13_mae(aa,cc))
    rm=np.asarray(rm,dtype=float); ma=np.asarray(ma,dtype=float)
    return {
        "n":int(len(a)),"groups":int(len(uniq)),
        "rmse_skill":float(_ncaaf_v13_rmse(a,b)-_ncaaf_v13_rmse(a,c)),
        "mae_skill":float(_ncaaf_v13_mae(a,b)-_ncaaf_v13_mae(a,c)),
        "rmse_skill_ci95":[float(np.quantile(rm,0.025)),float(np.quantile(rm,0.975))],
        "mae_skill_ci95":[float(np.quantile(ma,0.025)),float(np.quantile(ma,0.975))],
    }



def _ncaaf_v13_add_power_features(games: pd.DataFrame, bq=None, log_func=print):
    """Attach leakage-safe as-of NCAAF power rating difference when available.

    Ratings are fetched strictly before each game using the existing ratings-history
    as-of enrichment.  Missing ratings leave the candidate absent/neutral; they are
    never backfilled from future observations.
    """
    d = games.copy()
    if d.empty or bq is None:
        return d
    try:
        is_home = pd.to_numeric(d.get("Is_Home"), errors="coerce").eq(1)
        is_away = pd.to_numeric(d.get("Is_Away"), errors="coerce").eq(1)
        team = d["Team_Norm"].astype(str)
        opp = d["Opponent_Norm"].astype(str)
        home = pd.Series(np.where(is_home, team, np.where(is_away, opp, team)), index=d.index)
        away = pd.Series(np.where(is_home, opp, np.where(is_away, team, opp)), index=d.index)
        base = pd.DataFrame({
            "Sport": "NCAAF",
            "Home_Team_Norm": home,
            "Away_Team_Norm": away,
            "Game_Start": pd.to_datetime(d["Game_Date"], errors="coerce", utc=True),
        }, index=d.index)
        enriched = enrich_power_for_training_lowmem(
            base, bq=bq, table_history=RATINGS_HISTORY_TABLE,
            pad_days=35, rating_lag_hours=12.0, debug_asof_cols=False,
            strict_method=True,
        )
        pr = pd.to_numeric(enriched.get("Power_Rating_Diff"), errors="coerce")
        # The fundamental row is home-oriented whenever a home side exists.  For
        # neutral rows the synthetic home side above is the anchor team, so the
        # same sign remains correct.
        d["Power_Rating_Diff"] = pr.to_numpy(dtype=float, na_value=np.nan)
        coverage = float(d["Power_Rating_Diff"].notna().mean()) if len(d) else 0.0
        log_func(f"[V13-POWER] candidate=Power_Rating_Diff coverage={coverage:.1%} source={RATINGS_HISTORY_TABLE} asof_lag_hours=12")
    except Exception as e:
        log_func(f"[V13-POWER] unavailable: {e}")
    return d


def _ncaaf_v13_edge_beta(x, y, alpha=NCAAF_V13_EDGE_RIDGE_ALPHA):
    """Non-negative ridge shrinkage for incremental fundamental disagreement.

    x = raw fundamental fair value - market value
    y = actual result - market value
    A negative historical relationship is not inverted; it is assigned zero
    tradable authority.  This preserves the structural orientation and fails closed.
    """
    xx = np.asarray(x, dtype=float); yy = np.asarray(y, dtype=float)
    ok = np.isfinite(xx) & np.isfinite(yy)
    if int(ok.sum()) < NCAAF_V13_MIN_EDGE_TRAIN_GAMES:
        return 0.0, int(ok.sum())
    xx = xx[ok]; yy = yy[ok]
    den = float(np.dot(xx, xx) + float(alpha))
    beta = float(np.dot(xx, yy) / den) if den > 0 else 0.0
    return float(np.clip(beta, 0.0, 1.0)), int(ok.sum())


def _ncaaf_v13_closer_bucket_rows(actual, market, raw, tradable=None):
    """Summarize whether V13 is closer to the realized margin than the market.

    Buckets are based on the absolute RAW independent disagreement versus market.
    This directly answers the research question: when V13 differs from the market
    by 1.5, 2, 3+ points, is V13 more often closer to the actual game margin?
    """
    a=np.asarray(actual,dtype=float); m=np.asarray(market,dtype=float); r=np.asarray(raw,dtype=float)
    t=np.asarray(tradable,dtype=float) if tradable is not None else np.full(len(a),np.nan,dtype=float)
    ok=np.isfinite(a)&np.isfinite(m)&np.isfinite(r)
    if not ok.any():
        return []
    edge=np.abs(r-m)
    market_err=np.abs(a-m); raw_err=np.abs(a-r)
    trad_err=np.abs(a-t)
    specs=[
        ("lt_0.5",0.0,0.5),
        ("0.5_to_1.5",0.5,1.5),
        ("1.5_to_2.5",1.5,2.5),
        ("2.5_to_3.5",2.5,3.5),
        ("3.5_plus",3.5,np.inf),
    ]
    rows=[]
    for label,lo,hi in specs:
        sel=ok&(edge>=lo)&(edge<hi)
        n=int(sel.sum())
        if n==0:
            continue
        raw_imp=market_err[sel]-raw_err[sel]
        raw_closer=float(np.mean(raw_imp>0.0))
        raw_tie=float(np.mean(np.isclose(raw_imp,0.0,atol=1e-12)))
        signed=(r[sel]-m[sel])*(a[sel]-m[sel])
        direction=float(np.mean(signed>0.0)) if len(signed) else np.nan
        trad_ok=sel&np.isfinite(t)
        if trad_ok.any():
            trad_imp=market_err[trad_ok]-trad_err[trad_ok]
            trad_closer=float(np.mean(trad_imp>0.0))
            trad_avg=float(np.mean(trad_imp))
        else:
            trad_closer=np.nan; trad_avg=np.nan
        rows.append({
            "bucket":label,"n":n,
            "raw_closer_rate":raw_closer,"raw_tie_rate":raw_tie,
            "raw_avg_abs_error_improvement":float(np.mean(raw_imp)),
            "raw_median_abs_error_improvement":float(np.median(raw_imp)),
            "edge_direction_accuracy":direction,
            "tradable_closer_rate":trad_closer,
            "tradable_avg_abs_error_improvement":trad_avg,
        })
    return rows


def _ncaaf_v13_log_closer_buckets(actual, market, raw, tradable, *, season_label, log_func=print):
    rows=_ncaaf_v13_closer_bucket_rows(actual,market,raw,tradable)
    for rec in rows:
        tc=rec["tradable_closer_rate"]; ta=rec["tradable_avg_abs_error_improvement"]
        tc_txt=f"{tc:.1%}" if np.isfinite(tc) else "NA"
        ta_txt=f"{ta:+.3f}" if np.isfinite(ta) else "NA"
        log_func(
            f"[V13-CLOSER-BUCKET] season={season_label} bucket={rec['bucket']} n={rec['n']} "
            f"raw_closer={rec['raw_closer_rate']:.1%} raw_tie={rec['raw_tie_rate']:.1%} "
            f"raw_avg_improve={rec['raw_avg_abs_error_improvement']:+.3f} "
            f"raw_median_improve={rec['raw_median_abs_error_improvement']:+.3f} "
            f"edge_direction={rec['edge_direction_accuracy']:.1%} "
            f"tradable_closer={tc_txt} tradable_avg_improve={ta_txt}"
        )
    return rows




def _ncaaf_v13_log_tail_audit(games, actual, market, raw, tradable, linear=None, nonlinear=None, robust=None, season_label="POOLED", log_func=print):
    """Diagnose why large independent disagreements underperform.

    Purely diagnostic in V13.0.9.  No subgroup result is used to alter predictions,
    feature admission, edge shrinkage, Cover, or EV.
    """
    g=games.copy().reset_index(drop=True)
    a=np.asarray(actual,dtype=float); m=np.asarray(market,dtype=float); r=np.asarray(raw,dtype=float)
    t=np.asarray(tradable,dtype=float)
    n=min(len(g),len(a),len(m),len(r),len(t))
    if n<=0: return []
    g=g.iloc[:n].copy(); a=a[:n];m=m[:n];r=r[:n];t=t[:n]
    edge=r-m
    base=np.isfinite(a)&np.isfinite(m)&np.isfinite(r)&(np.abs(edge)>=3.5)
    if not base.any(): return []
    market_err=np.abs(a-m); raw_err=np.abs(a-r); trad_err=np.abs(a-t)
    rows=[]

    def emit(dim,bucket,mask):
        sel=base & np.asarray(mask,dtype=bool)
        nn=int(sel.sum())
        if nn<20: return
        signed=edge[sel]*(a[sel]-m[sel])
        raw_imp=market_err[sel]-raw_err[sel]
        tok=sel&np.isfinite(t)
        trad_cl=float(np.mean((market_err[tok]-trad_err[tok])>0)) if tok.any() else np.nan
        trad_avg=float(np.mean(market_err[tok]-trad_err[tok])) if tok.any() else np.nan
        rec={"dimension":dim,"bucket":bucket,"n":nn,
             "direction":float(np.mean(signed>0)),
             "raw_closer":float(np.mean(raw_imp>0)),
             "raw_avg_improve":float(np.mean(raw_imp)),
             "tradable_closer":trad_cl,"tradable_avg_improve":trad_avg}
        rows.append(rec)
        log_func(
            f"[V13-TAIL-AUDIT] season={season_label} dimension={dim} bucket={bucket} n={nn} "
            f"direction={rec['direction']:.1%} raw_closer={rec['raw_closer']:.1%} "
            f"raw_avg_improve={rec['raw_avg_improve']:+.3f} "
            f"tradable_closer={trad_cl:.1%} tradable_avg_improve={trad_avg:+.3f}"
            if np.isfinite(trad_cl) else
            f"[V13-TAIL-AUDIT] season={season_label} dimension={dim} bucket={bucket} n={nn} "
            f"direction={rec['direction']:.1%} raw_closer={rec['raw_closer']:.1%} "
            f"raw_avg_improve={rec['raw_avg_improve']:+.3f} tradable_closer=NA tradable_avg_improve=NA"
        )

    ae=np.abs(edge)
    for label,lo,hi in [("3.5_to_5",3.5,5),("5_to_7",5,7),("7_to_10",7,10),("10_to_14",10,14),("14_plus",14,np.inf)]:
        emit("edge_size",label,(ae>=lo)&(ae<hi))

    am=np.abs(m)
    for label,lo,hi in [("market_lt_3.5",0,3.5),("market_3.5_to_7",3.5,7),("market_7_to_14",7,14),("market_14_plus",14,np.inf)]:
        emit("market_spread",label,(am>=lo)&(am<hi))

    # Direction of the disagreement itself.
    emit("edge_direction","V13_HIGHER_THAN_MARKET",edge>0)
    emit("edge_direction","V13_LOWER_THAN_MARKET",edge<0)

    if "Context_Week" in g.columns:
        wk=pd.to_numeric(g["Context_Week"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
        emit("season_stage","week_1_to_4",np.isfinite(wk)&(wk<=4))
        emit("season_stage","week_5_to_9",np.isfinite(wk)&(wk>=5)&(wk<=9))
        emit("season_stage","week_10_plus",np.isfinite(wk)&(wk>=10))

    if "Context_Cross_Subdivision" in g.columns:
        cs=pd.to_numeric(g["Context_Cross_Subdivision"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
        emit("subdivision","FBS_vs_FCS",cs==1)
        emit("subdivision","same_subdivision",cs==0)

    # Market orientation; margin is home-oriented in the physical game frame.
    emit("market_side","HOME_FAVORITE",m>0)
    emit("market_side","HOME_UNDERDOG",m<0)
    emit("market_side","PICKEM",np.isclose(m,0,atol=.25))

    if linear is not None and nonlinear is not None:
        pl=np.asarray(linear,dtype=float)[:n]; pn=np.asarray(nonlinear,dtype=float)[:n]
        md=np.abs(pl-pn)
        for label,lo,hi in [("components_lt_2",0,2),("components_2_to_5",2,5),("components_5_plus",5,np.inf)]:
            emit("component_disagreement",label,np.isfinite(md)&(md>=lo)&(md<hi))
        good=base&np.isfinite(pl)&np.isfinite(pn)
        if good.any():
            msg=(f"[V13-FUNDAMENTAL-COMPONENT] season={season_label} scope=TAIL_3.5_PLUS n={int(good.sum())} "
                 f"linear_rmse={_ncaaf_v13_rmse(a[good],pl[good]):.3f} "
                 f"hgb_rmse={_ncaaf_v13_rmse(a[good],pn[good]):.3f} "
                 f"blend_rmse={_ncaaf_v13_rmse(a[good],r[good]):.3f}")
            if robust is not None:
                pr=np.asarray(robust,dtype=float)[:n]
                rg=good&np.isfinite(pr)
                if rg.any():
                    msg += f" robust_abs_loss_rmse={_ncaaf_v13_rmse(a[rg],pr[rg]):.3f}"
            log_func(msg)

    return rows


def _ncaaf_v13_log_blend_grid(actual, market, linear, nonlinear, season_label="POOLED", log_func=print):
    """Counterfactual OOS blend audit only; fixed production blend is unchanged."""
    a=np.asarray(actual,dtype=float); m=np.asarray(market,dtype=float)
    pl=np.asarray(linear,dtype=float); pn=np.asarray(nonlinear,dtype=float)
    ok=np.isfinite(a)&np.isfinite(m)&np.isfinite(pl)&np.isfinite(pn)
    if int(ok.sum())<200: return []
    rows=[]
    for w in (0.50,0.60,0.70,0.80,0.90,1.00):
        p=w*pl+(1-w)*pn
        tail=ok&(np.abs(p-m)>=3.5)
        rec={"linear_weight":w,"n":int(ok.sum()),"rmse":_ncaaf_v13_rmse(a[ok],p[ok]),"mae":_ncaaf_v13_mae(a[ok],p[ok]),
             "tail_n":int(tail.sum()),"tail_rmse":_ncaaf_v13_rmse(a[tail],p[tail]) if tail.any() else np.nan,
             "tail_direction":float(np.mean(((p[tail]-m[tail])*(a[tail]-m[tail]))>0)) if tail.any() else np.nan}
        rows.append(rec)
        log_func(
            f"[V13-BLEND-DIAGNOSTIC] season={season_label} used_in_predictions=FALSE linear_weight={w:.2f} n={rec['n']} "
            f"rmse={rec['rmse']:.3f} mae={rec['mae']:.3f} tail_n={rec['tail_n']} "
            f"tail_rmse={rec['tail_rmse']:.3f} tail_direction={rec['tail_direction']:.1%}"
        )
    return rows


def _ncaaf_v13_contextual_trust_candidate(games, actual, market, raw, tradable, linear, nonlinear, log_func=print):
    """Research-only as-of candidate for context-dependent Fundamental trust.

    The architecture remains Market + beta * (RawFair-Market), but this tests
    whether beta should vary with uncertainty/regime rather than be one global
    scalar.  Every validation season is fit only from earlier seasons.  Candidate
    predictions are sign-preserving and capped at 40% of the raw disagreement.
    Nothing here alters Raw Fair, Tradable Fair, Cover, or EV in V13.0.9.
    """
    from sklearn.pipeline import Pipeline
    from sklearn.impute import SimpleImputer
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import Ridge

    g=games.copy().reset_index(drop=True)
    a=np.asarray(actual,dtype=float); m=np.asarray(market,dtype=float); r=np.asarray(raw,dtype=float)
    t=np.asarray(tradable,dtype=float); pl=np.asarray(linear,dtype=float); pn=np.asarray(nonlinear,dtype=float)
    n=min(len(g),len(a),len(m),len(r),len(t),len(pl),len(pn))
    g=g.iloc[:n].copy(); a=a[:n];m=m[:n];r=r[:n];t=t[:n];pl=pl[:n];pn=pn[:n]
    season=pd.to_numeric(g.get("Season"),errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    edge=r-m; abs_edge=np.abs(edge); comp=np.abs(pl-pn); abs_market=np.abs(m)
    week=pd.to_numeric(g.get("Context_Week",np.nan),errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    cross=pd.to_numeric(g.get("Context_Cross_Subdivision",0.0),errors="coerce").fillna(0).to_numpy(dtype=float)
    early=np.where(np.isfinite(week)&(week<=4),1.0,0.0)
    maturity=np.where(np.isfinite(week),np.clip((week-4.0)/8.0,0.0,1.0),0.0)
    edge_tail=np.clip((abs_edge-3.5)/10.5,0.0,1.0)
    comp_scaled=np.clip(np.nan_to_num(comp,nan=0.0)/5.0,0.0,2.0)
    market_scaled=np.clip(np.nan_to_num(abs_market,nan=0.0)/14.0,0.0,2.0)
    lower=(edge<0).astype(float)
    # All columns are edge interactions so zero disagreement implies zero adjustment.
    X=np.column_stack([
        edge,
        edge*edge_tail,
        edge*early,
        edge*maturity,
        edge*cross,
        edge*comp_scaled,
        edge*market_scaled,
        edge*lower,
    ])
    names=["edge","edge_x_tail","edge_x_early","edge_x_maturity","edge_x_cross_subdivision",
           "edge_x_component_disagreement","edge_x_market_magnitude","edge_x_v13_lower"]
    y=a-m
    pred=np.full(n,np.nan,dtype=float); rows=[]
    seasons=sorted(int(x) for x in pd.Series(season).dropna().unique())
    for val in seasons:
        tr=(season<float(val))&np.isfinite(y)&np.isfinite(edge)&np.isfinite(X).all(axis=1)
        va=(season==float(val))&np.isfinite(y)&np.isfinite(edge)&np.isfinite(X).all(axis=1)
        if int(tr.sum())<500 or int(va.sum())<150:
            continue
        model=Pipeline([
            ("imputer",SimpleImputer(strategy="median")),
            ("scale",StandardScaler(with_mean=False)),
            ("ridge",Ridge(alpha=60.0,fit_intercept=False)),
        ])
        model.fit(X[tr],y[tr])
        pr=np.asarray(model.predict(X[va]),dtype=float)
        ev=edge[va]
        same=(np.sign(pr)==np.sign(ev)) & np.isfinite(pr) & np.isfinite(ev)
        capped=np.where(same,np.sign(ev)*np.minimum(np.abs(pr),0.40*np.abs(ev)),0.0)
        idx=np.where(va)[0]; pred[idx]=m[idx]+capped
        market_rmse=_ncaaf_v13_rmse(a[idx],m[idx]); cand_rmse=_ncaaf_v13_rmse(a[idx],pred[idx])
        global_rmse=_ncaaf_v13_rmse(a[idx],t[idx])
        market_mae=_ncaaf_v13_mae(a[idx],m[idx]); cand_mae=_ncaaf_v13_mae(a[idx],pred[idx]); global_mae=_ncaaf_v13_mae(a[idx],t[idx])
        rec={"season":val,"n":int(va.sum()),"market_rmse":market_rmse,"candidate_rmse":cand_rmse,"global_rmse":global_rmse,
             "market_mae":market_mae,"candidate_mae":cand_mae,"global_mae":global_mae}
        rows.append(rec)
        log_func(
            f"[V13-TRUST-CANDIDATE] season={val} used_in_predictions=FALSE n={rec['n']} features={names} "
            f"market_rmse={market_rmse:.3f} global_tradable_rmse={global_rmse:.3f} candidate_rmse={cand_rmse:.3f} "
            f"gain_vs_market={market_rmse-cand_rmse:+.3f} gain_vs_global={global_rmse-cand_rmse:+.3f} "
            f"market_mae={market_mae:.3f} global_mae={global_mae:.3f} candidate_mae={cand_mae:.3f}"
        )
    ok=np.isfinite(pred)&np.isfinite(a)&np.isfinite(m)&np.isfinite(t)
    if int(ok.sum())>=300:
        groups=g.loc[ok,"V13_Matchup_Key"].astype(str).to_numpy(dtype=object) if "V13_Matchup_Key" in g.columns else None
        bm=_ncaaf_v13_bootstrap_regression_skill(a[ok],m[ok],pred[ok],groups=groups,reps=700,seed=13091)
        cg=_ncaaf_v13_rmse(a[ok],t[ok])-_ncaaf_v13_rmse(a[ok],pred[ok])
        cm=_ncaaf_v13_mae(a[ok],t[ok])-_ncaaf_v13_mae(a[ok],pred[ok])
        log_func(
            f"[V13-TRUST-CANDIDATE] season=POOLED_FORWARD used_in_predictions=FALSE n={int(ok.sum())} "
            f"rmse_gain_vs_market={bm.get('rmse_skill',np.nan):+.4f} rmse_ci95={bm.get('rmse_skill_ci95')} "
            f"mae_gain_vs_market={bm.get('mae_skill',np.nan):+.4f} mae_ci95={bm.get('mae_skill_ci95')} "
            f"rmse_gain_vs_global={cg:+.4f} mae_gain_vs_global={cm:+.4f}"
        )
    return {"pred_oof":pred,"season_metrics":rows,"used_in_predictions":False}

def _ncaaf_v13_result_profile(actual, market, raw, tradable, groups=None, reps=500, seed=1304):
    """Build an OOS result-accuracy profile separate from market-value calibration.

    RAW fair margin is judged only on proximity to the realized game margin.
    TRADABLE fair margin is judged as a conservative betting estimate relative to
    the market.  This profile is diagnostic in V13.0.5 and is NOT an input to EV.
    """
    a=np.asarray(actual,dtype=float); m=np.asarray(market,dtype=float)
    r=np.asarray(raw,dtype=float); t=np.asarray(tradable,dtype=float)
    ok=np.isfinite(a)&np.isfinite(m)&np.isfinite(r)&np.isfinite(t)
    if not ok.any():
        return {"n":0,"buckets":[],"used_in_ev":False}
    a=a[ok];m=m[ok];r=r[ok];t=t[ok]
    if groups is None:
        g=np.arange(len(a)).astype(str)
    else:
        gg=np.asarray(groups,dtype=object)
        g=gg[ok].astype(str)
    market_err=np.abs(a-m); raw_err=np.abs(a-r); trad_err=np.abs(a-t)
    raw_imp=market_err-raw_err; trad_imp=market_err-trad_err
    edge=(r-m); result_resid=(a-m)
    overall={
        "n":int(len(a)),
        "raw_rmse":_ncaaf_v13_rmse(a,r),"market_rmse":_ncaaf_v13_rmse(a,m),"tradable_rmse":_ncaaf_v13_rmse(a,t),
        "raw_mae":_ncaaf_v13_mae(a,r),"market_mae":_ncaaf_v13_mae(a,m),"tradable_mae":_ncaaf_v13_mae(a,t),
        "raw_closer_rate":float(np.mean(raw_imp>0)),"tradable_closer_rate":float(np.mean(trad_imp>0)),
        "raw_avg_error_improvement":float(np.mean(raw_imp)),"tradable_avg_error_improvement":float(np.mean(trad_imp)),
        "edge_direction_accuracy":float(np.mean((edge*result_resid)>0)),
        "used_in_ev":False,
    }
    specs=[("lt_0.5",0.0,0.5),("0.5_to_1.5",0.5,1.5),("1.5_to_2.5",1.5,2.5),("2.5_to_3.5",2.5,3.5),("3.5_plus",3.5,np.inf)]
    uniq=np.unique(g)
    rng=np.random.default_rng(seed)
    buckets=[]
    for bi,(label,lo,hi) in enumerate(specs):
        sel=(np.abs(edge)>=lo)&(np.abs(edge)<hi)
        if not sel.any():
            continue
        ri=raw_imp[sel]; ti=trad_imp[sel]; ed=edge[sel]; rr=result_resid[sel]; gs=g[sel]
        rec={
            "bucket":label,"n":int(sel.sum()),
            "raw_closer_rate":float(np.mean(ri>0)),"tradable_closer_rate":float(np.mean(ti>0)),
            "raw_avg_error_improvement":float(np.mean(ri)),"tradable_avg_error_improvement":float(np.mean(ti)),
            "edge_direction_accuracy":float(np.mean((ed*rr)>0)),
        }
        ug=np.unique(gs)
        boot_close=[];boot_imp=[];boot_dir=[]
        if len(ug)>=20 and reps>0:
            by={u:np.where(gs==u)[0] for u in ug}
            for _ in range(int(reps)):
                samp=rng.choice(ug,size=len(ug),replace=True)
                idx=np.concatenate([by[u] for u in samp])
                if len(idx)==0: continue
                boot_close.append(float(np.mean(ti[idx]>0)))
                boot_imp.append(float(np.mean(ti[idx])))
                boot_dir.append(float(np.mean((ed[idx]*rr[idx])>0)))
        if boot_close:
            rec["tradable_closer_ci95"]=[float(np.quantile(boot_close,.025)),float(np.quantile(boot_close,.975))]
            rec["tradable_avg_error_improvement_ci95"]=[float(np.quantile(boot_imp,.025)),float(np.quantile(boot_imp,.975))]
            rec["edge_direction_ci95"]=[float(np.quantile(boot_dir,.025)),float(np.quantile(boot_dir,.975))]
        else:
            rec["tradable_closer_ci95"]=[np.nan,np.nan]
            rec["tradable_avg_error_improvement_ci95"]=[np.nan,np.nan]
            rec["edge_direction_ci95"]=[np.nan,np.nan]
        buckets.append(rec)
    overall["buckets"]=buckets
    return overall


def _ncaaf_v13_result_bucket_label(abs_edge):
    x=np.asarray(abs_edge,dtype=float)
    out=np.full(len(x),"UNAVAILABLE",dtype=object)
    ok=np.isfinite(x)
    out[ok&(x<0.5)]="lt_0.5"
    out[ok&(x>=0.5)&(x<1.5)]="0.5_to_1.5"
    out[ok&(x>=1.5)&(x<2.5)]="1.5_to_2.5"
    out[ok&(x>=2.5)&(x<3.5)]="2.5_to_3.5"
    out[ok&(x>=3.5)]="3.5_plus"
    return out

def _ncaaf_v13_learn_tradable_edges(games, raw_margin_oof, raw_total_oof, *, log_func=print):
    """Learn how much independent V13 disagreement deserves tradable authority.

    All beta estimates are season-forward.  For validation season S, beta is fit
    only from earlier OOF seasons, never from S.  The final beta is fit from all
    completed historical OOF seasons before the current live season.
    """
    d = games.copy()
    season = pd.to_numeric(d["Season"], errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    actual_m = pd.to_numeric(d["Actual_Margin"], errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    market_m = pd.to_numeric(d["Market_Open_Margin"], errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    actual_t = pd.to_numeric(d["Actual_Total"], errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    market_t = pd.to_numeric(d["Market_Open_Total"], errors="coerce").to_numpy(dtype=float, na_value=np.nan)
    raw_m = np.asarray(raw_margin_oof, dtype=float); raw_t = np.asarray(raw_total_oof, dtype=float)
    trad_m = np.full(len(d), np.nan, dtype=float); trad_t = np.full(len(d), np.nan, dtype=float)
    metrics = []
    closer_metrics = []
    seasons = sorted(int(x) for x in pd.Series(season).dropna().unique())

    for val in seasons:
        va = np.isfinite(season) & (season == float(val))
        trm = np.isfinite(season) & (season < float(val)) & np.isfinite(raw_m) & np.isfinite(market_m) & np.isfinite(actual_m)
        trt = np.isfinite(season) & (season < float(val)) & np.isfinite(raw_t) & np.isfinite(market_t) & np.isfinite(actual_t)
        bm, nm = _ncaaf_v13_edge_beta(raw_m[trm]-market_m[trm], actual_m[trm]-market_m[trm])
        bt, nt = _ncaaf_v13_edge_beta(raw_t[trt]-market_t[trt], actual_t[trt]-market_t[trt])
        if nm >= NCAAF_V13_MIN_EDGE_TRAIN_GAMES:
            ok = va & np.isfinite(raw_m) & np.isfinite(market_m)
            trad_m[ok] = market_m[ok] + bm*(raw_m[ok]-market_m[ok])
        if nt >= NCAAF_V13_MIN_EDGE_TRAIN_GAMES:
            ok = va & np.isfinite(raw_t) & np.isfinite(market_t)
            trad_t[ok] = market_t[ok] + bt*(raw_t[ok]-market_t[ok])
        vm = va & np.isfinite(actual_m) & np.isfinite(raw_m) & np.isfinite(market_m)
        vt = va & np.isfinite(actual_t) & np.isfinite(raw_t) & np.isfinite(market_t)
        if vm.sum() >= NCAAF_V13_MIN_VALID_GAMES:
            x = raw_m[vm]-market_m[vm]; y = actual_m[vm]-market_m[vm]
            dir_acc = float(np.mean((x*y) > 0)) if np.any(np.isfinite(x*y)) else np.nan
            rec = {
                "season": int(val), "n": int(vm.sum()), "margin_beta": bm, "margin_beta_train_n": nm,
                "raw_margin_rmse": _ncaaf_v13_rmse(actual_m[vm], raw_m[vm]),
                "market_margin_rmse": _ncaaf_v13_rmse(actual_m[vm], market_m[vm]),
                "tradable_margin_rmse": _ncaaf_v13_rmse(actual_m[vm], trad_m[vm]),
                "raw_margin_mae": _ncaaf_v13_mae(actual_m[vm], raw_m[vm]),
                "market_margin_mae": _ncaaf_v13_mae(actual_m[vm], market_m[vm]),
                "tradable_margin_mae": _ncaaf_v13_mae(actual_m[vm], trad_m[vm]),
                "edge_direction_accuracy": dir_acc,
                "total_beta": bt, "total_beta_train_n": nt,
                "raw_total_rmse": _ncaaf_v13_rmse(actual_t[vt], raw_t[vt]) if vt.any() else np.nan,
                "market_total_rmse": _ncaaf_v13_rmse(actual_t[vt], market_t[vt]) if vt.any() else np.nan,
                "tradable_total_rmse": _ncaaf_v13_rmse(actual_t[vt], trad_t[vt]) if vt.any() else np.nan,
            }
            metrics.append(rec)
            gain = rec["market_margin_rmse"] - rec["tradable_margin_rmse"] if np.isfinite(rec["tradable_margin_rmse"]) else np.nan
            log_func(
                f"[V13-FUNDAMENTAL-EDGE] season={val} n={rec['n']} beta={bm:.4f} beta_train_n={nm} "
                f"raw_rmse={rec['raw_margin_rmse']:.3f} market_rmse={rec['market_margin_rmse']:.3f} "
                f"tradable_rmse={rec['tradable_margin_rmse']:.3f} gain_vs_market={gain:+.3f} "
                f"edge_direction={dir_acc:.1%} total_beta={bt:.4f}"
            )
            _market_err=np.abs(actual_m[vm]-market_m[vm])
            _raw_imp=_market_err-np.abs(actual_m[vm]-raw_m[vm])
            _trad_valid=np.isfinite(trad_m[vm])
            _trad_imp=_market_err[_trad_valid]-np.abs(actual_m[vm][_trad_valid]-trad_m[vm][_trad_valid]) if _trad_valid.any() else np.asarray([],dtype=float)
            log_func(
                f"[V13-RESULT-SCORECARD] season={val} n={rec['n']} target=ACTUAL_FINAL_MARGIN "
                f"raw_closer={float(np.mean(_raw_imp>0)):.1%} raw_avg_error_improve={float(np.mean(_raw_imp)):+.3f} "
                f"tradable_closer={(float(np.mean(_trad_imp>0)) if len(_trad_imp) else np.nan):.1%} "
                f"tradable_avg_error_improve={(float(np.mean(_trad_imp)) if len(_trad_imp) else np.nan):+.3f} "
                f"market_role=MARKET_CLEARING_BENCHMARK raw_role=RESULT_FORECAST tradable_role=BETTING_ESTIMATE"
            )
            _buckets=_ncaaf_v13_log_closer_buckets(
                actual_m[vm], market_m[vm], raw_m[vm], trad_m[vm],
                season_label=int(val), log_func=log_func,
            )
            for _b in _buckets:
                closer_metrics.append({"season":int(val), **_b})

    # Current NCAA season rows are state/evaluation rows, not coefficient-fitting
    # rows.  Final beta is learned from completed prior-season OOF evidence only.
    now_season = int(_ncaaf_season_from_timestamp(pd.Series([pd.Timestamp.now(tz="UTC")])).iloc[0])
    fit_hist = np.isfinite(season) & (season < float(now_season))
    bm, nm = _ncaaf_v13_edge_beta(
        (raw_m-market_m)[fit_hist], (actual_m-market_m)[fit_hist]
    )
    bt, nt = _ncaaf_v13_edge_beta(
        (raw_t-market_t)[fit_hist], (actual_t-market_t)[fit_hist]
    )
    # Pooled *forward* diagnostic uses only season-forward tradable predictions,
    # so every market/tradable comparison is on the identical observations and
    # each beta was learned strictly from earlier seasons.
    pooled_forward = fit_hist & np.isfinite(actual_m) & np.isfinite(market_m) & np.isfinite(raw_m) & np.isfinite(trad_m)
    if pooled_forward.any():
        pooled_buckets = _ncaaf_v13_log_closer_buckets(
            actual_m[pooled_forward], market_m[pooled_forward], raw_m[pooled_forward], trad_m[pooled_forward],
            season_label="POOLED_FORWARD", log_func=log_func,
        )
        for _b in pooled_buckets:
            closer_metrics.append({"season":"POOLED_FORWARD", **_b})

    # V13.0.5 keeps a distinct result-accuracy scorecard.  This asks whether the
    # raw football opinion (and separately the tradable line) was closer to the
    # realized final margin than the market.  It is OOS diagnostic evidence only
    # and does not alter cover probability or EV.
    result_profile={"n":0,"buckets":[],"used_in_ev":False}
    if pooled_forward.any():
        _grp=d.loc[pooled_forward,"V13_Matchup_Key"].astype(str).to_numpy() if "V13_Matchup_Key" in d.columns else None
        result_profile=_ncaaf_v13_result_profile(
            actual_m[pooled_forward],market_m[pooled_forward],raw_m[pooled_forward],trad_m[pooled_forward],
            groups=_grp,reps=500,seed=1304,
        )
        log_func(
            f"[V13-RESULT-ACCURACY] scope=POOLED_FORWARD n={result_profile.get('n',0)} "
            f"raw_rmse={result_profile.get('raw_rmse',np.nan):.3f} market_rmse={result_profile.get('market_rmse',np.nan):.3f} "
            f"tradable_rmse={result_profile.get('tradable_rmse',np.nan):.3f} "
            f"raw_closer={result_profile.get('raw_closer_rate',np.nan):.1%} "
            f"tradable_closer={result_profile.get('tradable_closer_rate',np.nan):.1%} "
            f"edge_direction={result_profile.get('edge_direction_accuracy',np.nan):.1%} used_in_ev=FALSE"
        )
        for _rp in result_profile.get("buckets",[]):
            log_func(
                f"[V13-RESULT-PROFILE] bucket={_rp['bucket']} n={_rp['n']} "
                f"raw_closer={_rp['raw_closer_rate']:.1%} tradable_closer={_rp['tradable_closer_rate']:.1%} "
                f"tradable_closer_ci95={_rp.get('tradable_closer_ci95')} "
                f"direction={_rp['edge_direction_accuracy']:.1%} direction_ci95={_rp.get('edge_direction_ci95')} "
                f"tradable_avg_error_improve={_rp['tradable_avg_error_improvement']:+.3f} "
                f"improve_ci95={_rp.get('tradable_avg_error_improvement_ci95')} used_in_ev=FALSE"
            )

    # Final-beta pooled view is retained only as a deployment diagnostic, never as
    # an OOS performance claim.
    pooled_mask = fit_hist & np.isfinite(actual_m) & np.isfinite(market_m) & np.isfinite(raw_m)
    if pooled_mask.any():
        pooled_trad = market_m[pooled_mask] + bm*(raw_m[pooled_mask]-market_m[pooled_mask])
        _ncaaf_v13_log_closer_buckets(
            actual_m[pooled_mask], market_m[pooled_mask], raw_m[pooled_mask], pooled_trad,
            season_label="POOLED_FINAL_BETA_DIAGNOSTIC", log_func=log_func,
        )
    log_func(f"[V13-EDGE-SHRINK] final_margin_beta={bm:.4f} n={nm} final_total_beta={bt:.4f} n_total={nt} coefficient_season_max={now_season-1}")
    return {
        "margin_beta": bm, "margin_beta_train_n": nm,
        "total_beta": bt, "total_beta_train_n": nt,
        "season_metrics": metrics,
        "closer_bucket_metrics": closer_metrics,
        "result_profile": result_profile,
        "tradable_margin_oof": trad_m,
        "tradable_total_oof": trad_t,
        "coefficient_season_max": now_season-1,
        "policy": "nonnegative_ridge_incremental_market_residual__season_forward__current_season_excluded",
    }


def _ncaaf_v13_log_stat_provenance(raw: pd.DataFrame, log_func=print):
    if raw is None or raw.empty:
        return {}
    s = pd.to_numeric(raw.get("Season"), errors="coerce")
    if not s.notna().any():
        return {}
    latest = int(s.max())
    g = raw.loc[s.eq(latest)].copy()
    dt = pd.to_datetime(g.get("Game_Date"), errors="coerce", utc=True)
    if "Source_Game_ID" in g.columns:
        ng = int(g["Source_Game_ID"].astype(str).nunique())
    else:
        ng = int(len(g)//2)
    info = {
        "season": latest, "rows": int(len(g)), "games": ng,
        "min_date": None if dt.dropna().empty else str(dt.min()),
        "max_date": None if dt.dropna().empty else str(dt.max()),
        "source_table": NCAAF_STAT_RAW_TABLE,
    }
    role = "CURRENT_SEASON_STATE_ONLY" if latest == int(_ncaaf_season_from_timestamp(pd.Series([pd.Timestamp.now(tz="UTC")])).iloc[0]) else "HISTORICAL"
    info["role"] = role
    log_func(f"[V13-STAT-SOURCE] season={latest} rows={len(g)} games={ng} min_date={info['min_date']} max_date={info['max_date']} source_table={NCAAF_STAT_RAW_TABLE} role={role}")
    return info


def _ncaaf_v13_build_fundamental(raw: pd.DataFrame, bq=None, log_func=print):
    games, _, latest_profiles = _ncaaf_stat_build_game_frame(raw)
    if games.empty:
        return None
    games = _ncaaf_v13_add_power_features(games, bq=bq, log_func=log_func)
    candidate_margin, candidate_total = _ncaaf_v13_fundamental_feature_cols(games)
    if len(candidate_margin) < 15 or len(candidate_total) < 12:
        log_func(f"[V13-FUNDAMENTAL] insufficient compact candidates margin={len(candidate_margin)} total={len(candidate_total)}")
        return None

    games=games.copy()
    games["V13_Pair_Key"]=_ncaaf_v13_pair_key(games["Season"],games["Team_Norm"],games["Opponent_Norm"])
    games["V13_Matchup_Key"]=_ncaaf_v13_matchup_key(games["Season"],games["Game_Date"],games["Team_Norm"],games["Opponent_Norm"])
    seasons=sorted(int(x) for x in pd.to_numeric(games["Season"],errors="coerce").dropna().unique())
    if len(seasons) < 3:
        return None

    # V13.0.3 independent qualification contract.  IMPORTANT: the inherited
    # qualification helper names this argument `market_weight`, but internally it
    # is the STRUCTURAL-model weight in:
    #     blended = (1 - structural_weight) * market + structural_weight * structural
    # Therefore structural_weight=1.0 is the only correct setting for V13's
    # independent football line (0% market contribution).  Keep this explicit so
    # a future refactor cannot accidentally reintroduce the V13.0.1 inversion bug.
    v13_structural_weight = 1.0
    log_func(
        f"[V13-FUNDAMENTAL-QUAL-CONTRACT] structural_weight={v13_structural_weight:.3f} "
        f"market_contribution={1.0-v13_structural_weight:.3f} current_season_excluded=TRUE"
    )
    margin_cols, margin_qual = _ncaaf_stat_qualify_features(
        games, candidate_margin, "Actual_Margin", "Market_Open_Margin", seasons,
        market_weight=v13_structural_weight, label="v13_margin_independent", log_func=log_func,
    )
    total_cols, total_qual = _ncaaf_stat_qualify_features(
        games, candidate_total, "Actual_Total", "Market_Open_Total", seasons,
        market_weight=v13_structural_weight, label="v13_total_independent", log_func=log_func,
    )
    if len(margin_cols) < 2 or len(total_cols) < 2:
        log_func(f"[V13-FUNDAMENTAL] qualification left too few features margin={margin_cols} total={total_cols}")
        return None

    season_arr=pd.to_numeric(games["Season"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    ym=pd.to_numeric(games["Actual_Margin"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    yt=pd.to_numeric(games["Actual_Total"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    oof_m=np.full(len(games),np.nan); oof_t=np.full(len(games),np.nan)
    oof_m_linear=np.full(len(games),np.nan); oof_m_hgb=np.full(len(games),np.nan); oof_m_robust=np.full(len(games),np.nan)
    fold_metrics=[]
    fold_feature_sets={}
    for val in seasons[1:]:
        tr=np.isfinite(season_arr)&(season_arr<float(val))&np.isfinite(ym)&np.isfinite(yt)
        va=np.isfinite(season_arr)&(season_arr==float(val))&np.isfinite(ym)&np.isfinite(yt)
        if int(tr.sum())<NCAAF_V13_MIN_TRAIN_GAMES or int(va.sum())<NCAAF_V13_MIN_VALID_GAMES:
            continue

        # Fully as-of feature admission: a 2024 prediction cannot use evidence from
        # 2024/2025 to decide which columns are good.  The first OOF season uses the
        # predeclared candidate set as a warm-up; later folds earn features only on
        # earlier validation seasons.
        prior_qual=[s for s in seasons[1:] if s < int(val)]
        if prior_qual:
            fold_margin_cols,_=_ncaaf_stat_qualify_features(
                games,candidate_margin,"Actual_Margin","Market_Open_Margin",seasons,
                market_weight=1.0,label=f"v13_margin_asof_{int(val)}",log_func=log_func,
                qual_seasons_override=prior_qual,
            )
            fold_total_cols,_=_ncaaf_stat_qualify_features(
                games,candidate_total,"Actual_Total","Market_Open_Total",seasons,
                market_weight=1.0,label=f"v13_total_asof_{int(val)}",log_func=log_func,
                qual_seasons_override=prior_qual,
            )
        else:
            fold_margin_cols=[_NCAAF_STAT_INTERCEPT_FEATURE]+list(candidate_margin)
            fold_total_cols=[_NCAAF_STAT_INTERCEPT_FEATURE]+list(candidate_total)
            log_func(f"[V13-FUNDAMENTAL-ASOF] season={int(val)} policy=PREDECLARED_CANDIDATE_WARMUP margin={len(fold_margin_cols)-1} total={len(fold_total_cols)-1}")
        if len(fold_margin_cols)<2 or len(fold_total_cols)<2:
            log_func(f"[V13-FUNDAMENTAL-ASOF] season={int(val)} insufficient_features margin={len(fold_margin_cols)-1} total={len(fold_total_cols)-1}")
            continue
        fold_feature_sets[int(val)]={"margin":list(fold_margin_cols),"total":list(fold_total_cols),"qualification_seasons":list(prior_qual)}
        mm=_ncaaf_v13_fit_regression_pair(games.loc[tr,fold_margin_cols],ym[tr])
        tm=_ncaaf_v13_fit_regression_pair(games.loc[tr,fold_total_cols],yt[tr])
        _xm=games.loc[va,fold_margin_cols]
        p_lin=np.asarray(mm[0].predict(_xm),dtype=float)
        p_hgb=np.asarray(mm[1].predict(_xm),dtype=float)
        pm=0.80*p_lin+0.20*p_hgb
        pt=_ncaaf_v13_regression_predict(tm,games.loc[va,fold_total_cols],0.80)
        idx=np.where(va)[0]; oof_m[idx]=pm; oof_t[idx]=pt
        oof_m_linear[idx]=p_lin; oof_m_hgb[idx]=p_hgb
        # Research-only robust candidate.  It is logged OOS but does not affect
        # Raw Fair, Tradable Fair, feature admission, Cover, or EV in V13.0.9.
        try:
            _rob=_ncaaf_v13_new_robust_regressor()
            _rob.fit(games.loc[tr,fold_margin_cols],ym[tr])
            oof_m_robust[idx]=np.asarray(_rob.predict(_xm),dtype=float)
        except Exception as _e:
            log_func(f"[V13-ROBUST-CANDIDATE] season={int(val)} unavailable={_e}")
        log_func(f"[V13-FUNDAMENTAL-ASOF] season={int(val)} qual_seasons={prior_qual} margin_features={len(fold_margin_cols)-1} total_features={len(fold_total_cols)-1}")
        market_m=pd.to_numeric(games.loc[va,"Market_Open_Margin"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
        market_t=pd.to_numeric(games.loc[va,"Market_Open_Total"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
        rec={
            "season":int(val),"n":int(va.sum()),
            "margin_rmse":_ncaaf_v13_rmse(ym[idx],pm),"margin_mae":_ncaaf_v13_mae(ym[idx],pm),
            "market_margin_rmse":_ncaaf_v13_rmse(ym[idx],market_m),"market_margin_mae":_ncaaf_v13_mae(ym[idx],market_m),
            "total_rmse":_ncaaf_v13_rmse(yt[idx],pt),"total_mae":_ncaaf_v13_mae(yt[idx],pt),
            "market_total_rmse":_ncaaf_v13_rmse(yt[idx],market_t),"market_total_mae":_ncaaf_v13_mae(yt[idx],market_t),
        }
        fold_metrics.append(rec)
        log_func(
            f"[V13-FUNDAMENTAL-SEASON] season={val} n={rec['n']} "
            f"raw_margin_rmse={rec['margin_rmse']:.3f} market={rec['market_margin_rmse']:.3f} "
            f"raw_total_rmse={rec['total_rmse']:.3f} market={rec['market_total_rmse']:.3f}"
        )

    valid_oof=np.isfinite(oof_m)&np.isfinite(oof_t)
    if int(valid_oof.sum()) < 500:
        log_func(f"[V13-FUNDAMENTAL] insufficient season-forward OOF rows={int(valid_oof.sum())}")
        return None

    edge = _ncaaf_v13_learn_tradable_edges(games, oof_m, oof_t, log_func=log_func)
    trad_m = np.asarray(edge["tradable_margin_oof"], dtype=float)
    trad_t = np.asarray(edge["tradable_total_oof"], dtype=float)

    # Coefficients are fit on completed prior seasons only.  Current-season box
    # scores (2026 Week 1 here) update latest_profiles/state for future games, but
    # do not refit structural coefficients mid-season.
    now_season = int(_ncaaf_season_from_timestamp(pd.Series([pd.Timestamp.now(tz="UTC")])).iloc[0])
    coefficient_mask = np.isfinite(ym) & (season_arr < float(now_season))
    if int(coefficient_mask.sum()) < NCAAF_V13_MIN_TRAIN_GAMES:
        coefficient_mask = np.isfinite(ym)
    final_margin=_ncaaf_v13_fit_regression_pair(games.loc[coefficient_mask,margin_cols],ym[coefficient_mask])
    final_total=_ncaaf_v13_fit_regression_pair(games.loc[coefficient_mask,total_cols],yt[coefficient_mask])

    # V13.0.12 prospective replay.  The structural coefficients and admitted
    # feature set are frozen on seasons strictly before the current season.  We
    # may therefore score completed current-season games for research without
    # lowering the historical >=100-game OOF gate or refitting on 2026 results.
    prospective_frame=pd.DataFrame()
    _pros_mask=np.isfinite(ym)&np.isfinite(yt)&(season_arr==float(now_season))
    if int(_pros_mask.sum())>0:
        try:
            _pxm=games.loc[_pros_mask,margin_cols]
            _pxt=games.loc[_pros_mask,total_cols]
            _p_lin=np.asarray(final_margin[0].predict(_pxm),dtype=float)
            _p_hgb=np.asarray(final_margin[1].predict(_pxm),dtype=float)
            _p_raw=0.80*_p_lin+0.20*_p_hgb
            _p_tot=_ncaaf_v13_regression_predict(final_total,_pxt,0.80)
            _pmkt=pd.to_numeric(games.loc[_pros_mask,"Market_Open_Margin"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
            _ptotmkt=pd.to_numeric(games.loc[_pros_mask,"Market_Open_Total"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
            _mb=float(edge.get("margin_beta",0.0)); _tb=float(edge.get("total_beta",0.0))
            _p_trad=_pmkt+_mb*(_p_raw-_pmkt)
            _p_trad_t=_ptotmkt+_tb*(_p_tot-_ptotmkt)
            _base_cols=["Season","Game_Date","Source_Game_ID","V13_Pair_Key","V13_Matchup_Key","Team_Norm","Opponent_Norm","Actual_Margin","Actual_Total","Market_Open_Margin","Market_Open_Total"]
            prospective_frame=games.loc[_pros_mask,_base_cols].copy().reset_index(drop=True)
            prospective_frame["V13_Raw_Fair_Margin_OOF"]=_p_raw
            prospective_frame["V13_Tradable_Fair_Margin_OOF"]=_p_trad
            prospective_frame["V13_Raw_Fair_Total_OOF"]=_p_tot
            prospective_frame["V13_Tradable_Fair_Total_OOF"]=_p_trad_t
            prospective_frame["V13_Linear_Fair_Margin_OOF"]=_p_lin
            prospective_frame["V13_HGB_Fair_Margin_OOF"]=_p_hgb
            for _c in (
                "Context_Week","Context_Cross_Subdivision","Context_Is_Neutral",
                "Context_Team_Games_Prior","Context_Opp_Games_Prior","Context_Min_Games_Prior","Context_Early_FirstTwo",
                "Context_Is_NonConference","Context_Prev_SU_Margin","Context_Opp_Prev_SU_Margin",
                "Context_Prev_ATS_Margin","Context_Opp_Prev_ATS_Margin",
                "Context_Prev_BigWin21","Context_Prev_BigLoss21","Context_Prev_BigCover10","Context_Prev_BigMiss10",
                "Context_Opp_Prev_BigWin21","Context_Opp_Prev_BigLoss21","Context_Opp_Prev_BigCover10","Context_Opp_Prev_BigMiss10",
                "Power_Rating_Diff",
            ):
                if _c in games.columns:
                    prospective_frame[_c]=pd.to_numeric(games.loc[_pros_mask,_c],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
            prospective_frame["V13_Eval_Mode"]="PROSPECTIVE_REPLAY_FROZEN_PRIOR_SEASONS"
            _pa=ym[_pros_mask]
            _pr_skill=_ncaaf_v13_bootstrap_regression_skill(_pa,_pmkt,_p_trad,reps=600,seed=13180)
            log_func(
                f"[V13-PROSPECTIVE-FUND] season={now_season} n={len(prospective_frame)} "
                f"raw_rmse={_ncaaf_v13_rmse(_pa,_p_raw):.3f} market_rmse={_ncaaf_v13_rmse(_pa,_pmkt):.3f} "
                f"tradable_rmse={_ncaaf_v13_rmse(_pa,_p_trad):.3f} rmse_gain={_pr_skill.get('rmse_skill',np.nan):+.4f} "
                f"mae_gain={_pr_skill.get('mae_skill',np.nan):+.4f} frozen_through={now_season-1} authority=RESEARCH_ONLY"
            )
        except Exception as _e:
            log_func(f"[V13-PROSPECTIVE-FUND] unavailable={_e}")
            prospective_frame=pd.DataFrame()

    residual_margin=(ym-trad_m)[np.isfinite(ym)&np.isfinite(trad_m)]
    residual_total=(yt-trad_t)[np.isfinite(yt)&np.isfinite(trad_t)]
    out=games[["Season","Game_Date","Source_Game_ID","V13_Pair_Key","V13_Matchup_Key","Team_Norm","Opponent_Norm","Actual_Margin","Actual_Total","Market_Open_Margin","Market_Open_Total"]].copy()
    out["V13_Raw_Fair_Margin_OOF"]=oof_m
    out["V13_Tradable_Fair_Margin_OOF"]=trad_m
    out["V13_Raw_Fair_Total_OOF"]=oof_t
    out["V13_Tradable_Fair_Total_OOF"]=trad_t
    # Preserve OOS component disagreement/context for probability calibration and
    # uncertainty diagnostics. These are predictions/state known before the result.
    out["V13_Linear_Fair_Margin_OOF"]=oof_m_linear
    out["V13_HGB_Fair_Margin_OOF"]=oof_m_hgb
    for _c in (
        "Context_Week","Context_Cross_Subdivision","Context_Is_Neutral",
        "Context_Team_Games_Prior","Context_Opp_Games_Prior","Context_Min_Games_Prior","Context_Early_FirstTwo",
        "Context_Is_NonConference","Context_Prev_SU_Margin","Context_Opp_Prev_SU_Margin",
        "Context_Prev_ATS_Margin","Context_Opp_Prev_ATS_Margin",
        "Context_Prev_BigWin21","Context_Prev_BigLoss21","Context_Prev_BigCover10","Context_Prev_BigMiss10",
        "Context_Opp_Prev_BigWin21","Context_Opp_Prev_BigLoss21","Context_Opp_Prev_BigCover10","Context_Opp_Prev_BigMiss10",
        "Power_Rating_Diff",
    ):
        if _c in games.columns:
            out[_c]=pd.to_numeric(games[_c],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    # Backward aliases for older V13 readers.
    out["V13_Fair_Margin_OOF"]=oof_m
    out["V13_Fair_Total_OOF"]=oof_t

    bundle={
        "margin_features":margin_cols,"total_features":total_cols,
        "margin_candidate_features":candidate_margin,"total_candidate_features":candidate_total,
        "margin_qualification":margin_qual,"total_qualification":total_qual,
        "margin_models":final_margin,"total_models":final_total,"linear_weight":0.80,
        "latest_profiles":latest_profiles,
        "residual_margin":np.asarray(residual_margin,dtype=np.float32),
        "residual_total":np.asarray(residual_total,dtype=np.float32),
        "season_metrics":fold_metrics,"seasons":seasons,"fold_feature_sets":fold_feature_sets,
        "edge_shrinkage":{k:v for k,v in edge.items() if not str(k).startswith("tradable_")},
        "result_profile":edge.get("result_profile",{}),
        "margin_edge_beta":float(edge.get("margin_beta",0.0)),
        "total_edge_beta":float(edge.get("total_beta",0.0)),
        "coefficient_season_max":int(edge.get("coefficient_season_max",now_season-1)),
        "current_season_state_loaded":bool(max(seasons) == now_season),
        "historical_max_date":pd.Timestamp(games["Game_Date"].max()).isoformat(),
        "historical_max_season":max(seasons),
        "oof_frame":out,
        "prospective_frame":prospective_frame,
    }
    pooled_rmse=_ncaaf_v13_rmse(ym,oof_m)
    market_all=pd.to_numeric(games["Market_Open_Margin"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    common=np.isfinite(ym)&np.isfinite(oof_m)&np.isfinite(market_all)&np.isfinite(trad_m)
    oos_skill=_ncaaf_v13_bootstrap_regression_skill(ym[common],market_all[common],trad_m[common],reps=800,seed=13031) if common.any() else {}
    bundle["paired_oos_skill"]=oos_skill
    common_raw=_ncaaf_v13_rmse(ym[common],oof_m[common]) if common.any() else np.nan
    common_market=_ncaaf_v13_rmse(ym[common],market_all[common]) if common.any() else np.nan
    common_trad=_ncaaf_v13_rmse(ym[common],trad_m[common]) if common.any() else np.nan
    log_func(
        "[V13-RESULT-CONTRACT] raw_fair_target=ACTUAL_FINAL_MARGIN raw_market_input=NONE "
        "market_role=MARKET_CLEARING_BENCHMARK tradable_role=MARKET_PLUS_VALIDATED_FUNDAMENTAL_RESIDUAL "
        "result_profile_used_in_ev=FALSE"
    )
    log_func(
        f"[V13-FUNDAMENTAL-OOS] n={int(common.sum())} raw_rmse={common_raw:.3f} market_rmse={common_market:.3f} "
        f"tradable_rmse={common_trad:.3f} rmse_gain={oos_skill.get('rmse_skill',np.nan):+.4f} "
        f"rmse_ci95={oos_skill.get('rmse_skill_ci95')} mae_gain={oos_skill.get('mae_skill',np.nan):+.4f} "
        f"mae_ci95={oos_skill.get('mae_skill_ci95')} comparison=PAIRED_NESTED_ASOF_SEASON_FORWARD"
    )
    log_func(
        f"[V13-FUNDAMENTAL] games={len(games)} qualified_margin={len(margin_cols)-1} qualified_total={len(total_cols)-1} "
        f"raw_oof_rmse_all={pooled_rmse:.3f} paired_market_rmse={common_market:.3f} paired_tradable_rmse={common_trad:.3f} "
        f"margin_beta={bundle['margin_edge_beta']:.4f} coefficient_season_max={bundle['coefficient_season_max']} independent_market_contribution=0.000"
    )

    # V13.0.9 tail research: diagnose pooled and by season before changing trust.
    # Contextual trust is a strict season-forward candidate only; it has no runtime
    # authority until it beats the existing global-beta tradable line OOS.
    try:
        bundle["tail_audit"]=_ncaaf_v13_log_tail_audit(
            games,ym,market_all,oof_m,trad_m,
            linear=oof_m_linear,nonlinear=oof_m_hgb,robust=oof_m_robust,season_label="POOLED",log_func=log_func,
        )
        bundle["blend_diagnostic"]=_ncaaf_v13_log_blend_grid(
            ym,market_all,oof_m_linear,oof_m_hgb,season_label="POOLED",log_func=log_func,
        )
        for _sv in sorted(int(x) for x in pd.Series(season_arr).dropna().unique()):
            _sm=(season_arr==float(_sv))&np.isfinite(ym)&np.isfinite(market_all)&np.isfinite(oof_m)
            if int(_sm.sum())<150:
                continue
            _ncaaf_v13_log_tail_audit(
                games.loc[_sm].reset_index(drop=True),ym[_sm],market_all[_sm],oof_m[_sm],trad_m[_sm],
                linear=oof_m_linear[_sm],nonlinear=oof_m_hgb[_sm],robust=oof_m_robust[_sm],
                season_label=int(_sv),log_func=log_func,
            )
            _ncaaf_v13_log_blend_grid(
                ym[_sm],market_all[_sm],oof_m_linear[_sm],oof_m_hgb[_sm],season_label=int(_sv),log_func=log_func,
            )
        bundle["contextual_trust_candidate"]=_ncaaf_v13_contextual_trust_candidate(
            games,ym,market_all,oof_m,trad_m,oof_m_linear,oof_m_hgb,log_func=log_func,
        )
        rg=np.isfinite(ym)&np.isfinite(oof_m_robust)
        if int(rg.sum())>=200:
            tail=rg&np.isfinite(market_all)&(np.abs(oof_m-market_all)>=3.5)
            _rr=_ncaaf_v13_rmse(ym[rg],oof_m_robust[rg]); _rm=_ncaaf_v13_mae(ym[rg],oof_m_robust[rg])
            _base=_ncaaf_v13_rmse(ym[rg],oof_m[rg])
            log_func(
                f"[V13-ROBUST-CANDIDATE] used_in_predictions=FALSE decision={'REJECT_FOR_NOW' if _rr>=_base else 'RETEST'} n={int(rg.sum())} "
                f"rmse={_rr:.3f} baseline_rmse={_base:.3f} mae={_rm:.3f} "
                f"tail_n={int(tail.sum())} tail_rmse={_ncaaf_v13_rmse(ym[tail],oof_m_robust[tail]) if tail.any() else np.nan:.3f}"
            )
    except Exception as _e:
        log_func(f"[V13-TAIL-AUDIT] unavailable={_e}")

    return bundle


def _ncaaf_v13_fetch_spread_snapshots(log_func=print):
    """Discover the deepest genuine repeated historical NCAAF spread stream.

    V13.0.9 treats scores_with_features as the authoritative historical market
    training/backtest source. It already persists completed/scored historical
    market rows with the feature pipeline's canonical game metadata. The recent
    moves_with_features_merged view and raw/generic market tables are fallbacks
    only. Every candidate must still prove repeated pre-kick observations and
    genuine calendar-2025 coverage before the Market Brain can use it.
    """
    try:
        bq,bqs=get_bq_clients()
    except Exception as e:
        log_func(f"[V13-MARKET] clients unavailable: {e}")
        return pd.DataFrame()

    aliases = {
        "sport": ("Sport","sport","Sport_Key","sport_key"),
        "market": ("Market","market","Market_Key","market_key"),
        "snap": (
            "Snapshot_Timestamp","snapshot_timestamp","Time","Observed_At","Captured_At","Scraped_At",
            "Timestamp","Insert_Timestamp","Inserted_Timestamp","Inserted_At","Created_At","Updated_At"
        ),
        "game": ("Game_Start","feat_Game_Start","Commence_Hour","Commence_Time","commence_time"),
        "book": ("Bookmaker","Book","bookmaker","Bookmaker_Norm","Book_Norm"),
        "value": ("Value","Line","Spread","Line_Value"),
        "odds": ("Odds_Price","Price","Odds"),
        "outcome": ("Outcome_Norm","Outcome","Team_Norm","Team","feat_Team"),
        "home": ("Home_Team_Norm","Home_Team","feat_Home_Team_Norm","feat_Home_Team","home_team"),
        "away": ("Away_Team_Norm","Away_Team","feat_Away_Team_Norm","feat_Away_Team","away_team"),
        "key": ("Merge_Key_Short","Game_Key","feat_Game_Key","Event_ID","event_id","Game_ID","game_key_clean"),
        "open": ("First_Line_Value","Open_Value","Opening_Line","Opening_Spread","Opening_Value"),
    }
    sport_vals=[str(x).upper().strip() for x in _aliases_for("NCAAF")]
    sport_in=",".join("'"+x.replace("'","''")+"'" for x in sport_vals)

    def schema_for(table):
        try: return {f.name for f in bq.get_table(table).schema}
        except Exception as e:
            log_func(f"[V13-MARKET-SCHEMA] source={table} unavailable={e}")
            return set()
    def pick(schema, kind): return next((x for x in aliases[kind] if x in schema),None)
    def cast_str(alias, field): return f"CAST({alias}.`{field}` AS STRING)" if field else "CAST(NULL AS STRING)"
    def cast_float(alias, field): return f"SAFE_CAST({alias}.`{field}` AS FLOAT64)" if field else "CAST(NULL AS FLOAT64)"
    def ts(alias, field): return f"SAFE_CAST({alias}.`{field}` AS TIMESTAMP)"
    def source_guard(table, schema, alias="s"):
        """Source-specific history guard; never substitutes ingestion time for event time."""
        if table == SCORES_FEATURES_TABLE:
            if "SHARP_HIT_BOOL" in schema:
                return f"{alias}.`SHARP_HIT_BOOL` IS NOT NULL"
            if "Scored" in schema:
                return f"COALESCE(SAFE_CAST({alias}.`Scored` AS BOOL), FALSE)"
        return "TRUE"

    tables=[]
    # V13.0.9 source lineage contract:
    #   scores_with_features       = authoritative completed historical market history
    #   moves_with_features_merged = recent/current enriched market fallback
    #   sharp_moves_master         = raw market fallback / metadata source
    #   generic archive tables     = last-resort fallbacks only
    for table in (SCORES_FEATURES_TABLE,MOVES_FEATURES_TABLE,BQ_FULL_TABLE,LINE_HISTORY_TABLE,SNAPSHOTS_TABLE):
        if table and table not in tables: tables.append(table)
    schemas={table:schema_for(table) for table in tables}
    meta_schema=schemas.get(BQ_FULL_TABLE,set())
    specs=[]; attempts=[]

    def _record_profile(table,route,snap_col,game_col,row,key_col=None,meta=None):
        try:
            valid=int(row.get("prekick_36h_rows") or 0)
            games_n=int(row.get("distinct_games") or 0)
            mn=pd.to_datetime(row.get("min_valid_snapshot"),errors="coerce",utc=True)
            mx=pd.to_datetime(row.get("max_valid_snapshot"),errors="coerce",utc=True)
            min_game=pd.to_datetime(row.get("min_valid_game"),errors="coerce",utc=True)
            max_game=pd.to_datetime(row.get("max_valid_game"),errors="coerce",utc=True)
            rows_2025=int(row.get("valid_2025_rows") or 0)
            games_2025=int(row.get("valid_2025_games") or 0)
            # Verification means actual valid pre-kick snapshot observations occurred
            # in calendar 2025; a min/max range spanning 2025 is not sufficient.
            covers_2025=bool(rows_2025>0 and games_2025>0)
            year_span=int(max(0,(mx.year-mn.year))) if pd.notna(mn) and pd.notna(mx) else 0
            log_func(
                f"[V13-MARKET-PROFILE] source={table} route={route} snap_col={snap_col} game_col={game_col} "
                f"prekick36={valid} games={games_n} rows_2025={rows_2025} games_2025={games_2025} "
                f"snapshot_range={mn}..{mx} game_range={min_game}..{max_game} covers_2025={covers_2025}"
            )
            if valid>0 and games_n>0 and pd.notna(mn) and pd.notna(mx):
                specs.append({"table":table,"route":route,"snap":snap_col,"game":game_col,"key":key_col,
                              "meta":meta,"valid":valid,"games":games_n,"rows_2025":rows_2025,"games_2025":games_2025,
                              "min_snapshot":mn,"max_snapshot":mx,
                              "min_game":min_game,"max_game":max_game,"covers_2025":covers_2025,"year_span":year_span})
        except Exception as e:
            attempts.append((table,f"profile_parse_error:{e}"))

    # Direct sources: profile every plausible snapshot-time x game-time pair.
    for table in tables:
        sch=schemas.get(table,set())
        if not sch: continue
        f={k:pick(sch,k) for k in aliases}
        snap_candidates=[x for x in aliases["snap"] if x in sch]
        if table == SCORES_FEATURES_TABLE:
            # Persisted scored history uses Snapshot_Timestamp as the market observation
            # time. Still profile every available time field so the contract is verified.
            snap_candidates=sorted(
                snap_candidates,
                key=lambda x:(0 if x == "Snapshot_Timestamp" else 1 if x == "Time" else 2, aliases["snap"].index(x))
            )
        elif table == MOVES_FEATURES_TABLE:
            # Existing recent/live pregame logic uses Game_Start - Time.
            snap_candidates=sorted(
                snap_candidates,
                key=lambda x:(0 if x == "Time" else 1 if x == "Snapshot_Timestamp" else 2, aliases["snap"].index(x))
            )
        game_candidates=[x for x in aliases["game"] if x in sch]
        if table == SCORES_FEATURES_TABLE:
            # scores_with_features is a view-style historical source; feat_Game_Start
            # is the canonical event timestamp when present.
            game_candidates=sorted(
                game_candidates,
                key=lambda x:(0 if x == "feat_Game_Start" else 1 if x == "Game_Start" else 2, aliases["game"].index(x))
            )
        quote_ok=all(f.get(k) for k in ("book","value","outcome"))
        direct_meta=all(f.get(k) for k in ("sport","market","home","away"))
        if quote_ok and direct_meta and snap_candidates and game_candidates:
            key_expr=cast_str('s',f.get('key')) if f.get('key') else "CONCAT(COALESCE(CAST(s.`%s` AS STRING),''),'|',COALESCE(CAST(s.`%s` AS STRING),''),'|',CAST(%s AS STRING))"%(f['home'],f['away'],ts('s',game_candidates[0]))
            for sf in snap_candidates:
                for gf in game_candidates:
                    guard=source_guard(table,sch,'s')
                    cond=(f"{guard} AND UPPER(TRIM(CAST(s.`{f['sport']}` AS STRING))) IN ({sport_in}) AND "
                          f"LOWER(TRIM(CAST(s.`{f['market']}` AS STRING))) IN ('spread','spreads') AND "
                          f"{ts('s',sf)} IS NOT NULL AND {ts('s',gf)} IS NOT NULL AND {ts('s',sf)} < {ts('s',gf)} AND "
                          f"{ts('s',sf)} >= TIMESTAMP_SUB({ts('s',gf)}, INTERVAL 36 HOUR)")
                    kexpr=cast_str('s',f.get('key')) if f.get('key') else f"CONCAT(CAST(s.`{f['home']}` AS STRING),'|',CAST(s.`{f['away']}` AS STRING),'|',CAST({ts('s',gf)} AS STRING))"
                    sql=f"""
                      SELECT COUNTIF({cond}) AS prekick_36h_rows,
                             COUNT(DISTINCT IF({cond},{kexpr},NULL)) AS distinct_games,
                             COUNTIF(({cond}) AND EXTRACT(YEAR FROM {ts('s',sf)})=2025) AS valid_2025_rows,
                             COUNT(DISTINCT IF(({cond}) AND EXTRACT(YEAR FROM {ts('s',sf)})=2025,{kexpr},NULL)) AS valid_2025_games,
                             MIN(IF({cond},{ts('s',sf)},NULL)) AS min_valid_snapshot,
                             MAX(IF({cond},{ts('s',sf)},NULL)) AS max_valid_snapshot,
                             MIN(IF({cond},{ts('s',gf)},NULL)) AS min_valid_game,
                             MAX(IF({cond},{ts('s',gf)},NULL)) AS max_valid_game
                      FROM `{table}` s
                    """
                    try:
                        pr=bq.query(sql).to_dataframe()
                        if not pr.empty: _record_profile(table,"direct",sf,gf,pr.iloc[0].to_dict(),key_col=f.get('key'))
                    except Exception as e: attempts.append((table,f"direct_profile_{sf}_{gf}:{e}"))

        # Key-join archive sources: use sharp_moves_master only for game metadata.
        if table!=BQ_FULL_TABLE and quote_ok and f.get('key') and meta_schema and snap_candidates:
            mf={k:pick(meta_schema,k) for k in aliases}
            common_key=next((kc for kc in aliases['key'] if kc in sch and kc in meta_schema),None)
            meta_games=[x for x in aliases['game'] if x in meta_schema]
            if common_key and all(mf.get(k) for k in ("sport","market","home","away")) and meta_games:
                for sf in snap_candidates:
                    for mg in meta_games:
                        guard=source_guard(table,sch,'s')
                        cond=(f"{guard} AND {ts('s',sf)} IS NOT NULL AND m.Game_Start IS NOT NULL AND {ts('s',sf)} < m.Game_Start AND "
                              f"{ts('s',sf)} >= TIMESTAMP_SUB(m.Game_Start, INTERVAL 36 HOUR)")
                        sql=f"""
                          WITH meta AS (
                            SELECT CAST(`{common_key}` AS STRING) AS __join_key,
                                   MAX(SAFE_CAST(`{mg}` AS TIMESTAMP)) AS Game_Start
                            FROM `{BQ_FULL_TABLE}`
                            WHERE UPPER(TRIM(CAST(`{mf['sport']}` AS STRING))) IN ({sport_in})
                              AND LOWER(TRIM(CAST(`{mf['market']}` AS STRING))) IN ('spread','spreads')
                            GROUP BY __join_key
                          )
                          SELECT COUNTIF({cond}) AS prekick_36h_rows,
                                 COUNT(DISTINCT IF({cond},CAST(s.`{common_key}` AS STRING),NULL)) AS distinct_games,
                                 COUNTIF(({cond}) AND EXTRACT(YEAR FROM {ts('s',sf)})=2025) AS valid_2025_rows,
                                 COUNT(DISTINCT IF(({cond}) AND EXTRACT(YEAR FROM {ts('s',sf)})=2025,CAST(s.`{common_key}` AS STRING),NULL)) AS valid_2025_games,
                                 MIN(IF({cond},{ts('s',sf)},NULL)) AS min_valid_snapshot,
                                 MAX(IF({cond},{ts('s',sf)},NULL)) AS max_valid_snapshot,
                                 MIN(IF({cond},m.Game_Start,NULL)) AS min_valid_game,
                                 MAX(IF({cond},m.Game_Start,NULL)) AS max_valid_game
                          FROM `{table}` s JOIN meta m ON CAST(s.`{common_key}` AS STRING)=m.__join_key
                        """
                        try:
                            pr=bq.query(sql).to_dataframe()
                            if not pr.empty: _record_profile(table,"key_join",sf,mg,pr.iloc[0].to_dict(),key_col=common_key,meta=BQ_FULL_TABLE)
                        except Exception as e: attempts.append((table,f"key_profile_{sf}_{mg}:{e}"))

    viable=[s for s in specs if s['valid']>=50 and s['games']>=20]
    if not viable:
        log_func(f"[V13-MARKET] no viable historical snapshot stream attempts={attempts[:20]}")
        return pd.DataFrame()
    # Prefer genuine 2025 coverage. scores_with_features is authoritative by
    # lineage; other objects are fallback sources only if the primary cannot prove
    # a usable repeated historical stream.
    source_priority={SCORES_FEATURES_TABLE:4,MOVES_FEATURES_TABLE:3,BQ_FULL_TABLE:2,LINE_HISTORY_TABLE:1,SNAPSHOTS_TABLE:0}
    def _score(s):
        depth_days=(pd.Timestamp.now(tz='UTC')-s['min_snapshot']).total_seconds()/86400.0 if pd.notna(s['min_snapshot']) else 0.0
        return (1 if s['covers_2025'] else 0, source_priority.get(s['table'],-1), depth_days, s['games'], s['valid'])
    best=max(viable,key=_score)
    log_func(
        f"[V13-MARKET-AUTHORITY] authoritative={SCORES_FEATURES_TABLE} "
        f"selected={best['table']} fallback_used={'FALSE' if best['table']==SCORES_FEATURES_TABLE else 'TRUE'}"
    )
    log_func(
        f"[V13-MARKET-PRIMARY] preferred={SCORES_FEATURES_TABLE} selected={best['table']} "
        f"selected_snap={best['snap']} selected_game={best['game']} verified_2025={best['covers_2025']}"
    )
    log_func(
        f"[V13-MARKET-HISTORY-VERIFY] expected_start_year=2025 verified={'TRUE' if best['covers_2025'] else 'FALSE'} "
        f"source={best['table']} route={best['route']} snap_col={best['snap']} game_col={best['game']} "
        f"snapshot_range={best['min_snapshot']}..{best['max_snapshot']} games={best['games']} rows={best['valid']} "
        f"rows_2025={best.get('rows_2025',0)} games_2025={best.get('games_2025',0)}"
    )

    table=best['table']; sch=schemas[table]; f={k:pick(sch,k) for k in aliases}; sf=best['snap']; gf=best['game']
    if best['route']=='direct':
        sql=f"""
          SELECT {cast_str('s',f.get('key'))} AS Game_Key,
                 {ts('s',sf)} AS Snapshot_Timestamp,
                 {ts('s',gf)} AS Game_Start,
                 {cast_str('s',f.get('book'))} AS Bookmaker,
                 {cast_float('s',f.get('value'))} AS Value,
                 {cast_float('s',f.get('odds'))} AS Odds_Price,
                 {cast_float('s',f.get('open'))} AS Open_Value,
                 {cast_str('s',f.get('outcome'))} AS Outcome,
                 {cast_str('s',f.get('home'))} AS Home_Team_Norm,
                 {cast_str('s',f.get('away'))} AS Away_Team_Norm
          FROM `{table}` s
          WHERE {source_guard(table,sch,'s')}
            AND UPPER(TRIM(CAST(s.`{f['sport']}` AS STRING))) IN ({sport_in})
            AND LOWER(TRIM(CAST(s.`{f['market']}` AS STRING))) IN ('spread','spreads')
            AND {ts('s',sf)} IS NOT NULL AND {ts('s',gf)} IS NOT NULL
            AND {ts('s',gf)} >= TIMESTAMP('2022-01-01') AND {ts('s',gf)} < CURRENT_TIMESTAMP()
            AND {ts('s',sf)} < {ts('s',gf)}
            AND {ts('s',sf)} >= TIMESTAMP_SUB({ts('s',gf)}, INTERVAL 36 HOUR)
        """
    else:
        mf={k:pick(meta_schema,k) for k in aliases}; common_key=best['key']; mg=best['game']
        sql=f"""
          WITH meta AS (
            SELECT CAST(`{common_key}` AS STRING) AS __join_key,
                   ANY_VALUE(CAST(`{mf['sport']}` AS STRING)) AS Sport,
                   ANY_VALUE(CAST(`{mf['market']}` AS STRING)) AS Market,
                   MAX(SAFE_CAST(`{mg}` AS TIMESTAMP)) AS Game_Start,
                   ANY_VALUE(CAST(`{mf['home']}` AS STRING)) AS Home_Team_Norm,
                   ANY_VALUE(CAST(`{mf['away']}` AS STRING)) AS Away_Team_Norm
            FROM `{BQ_FULL_TABLE}`
            WHERE UPPER(TRIM(CAST(`{mf['sport']}` AS STRING))) IN ({sport_in})
              AND LOWER(TRIM(CAST(`{mf['market']}` AS STRING))) IN ('spread','spreads')
            GROUP BY __join_key
          )
          SELECT CAST(s.`{common_key}` AS STRING) AS Game_Key,
                 {ts('s',sf)} AS Snapshot_Timestamp,m.Game_Start,
                 {cast_str('s',f.get('book'))} AS Bookmaker,
                 {cast_float('s',f.get('value'))} AS Value,
                 {cast_float('s',f.get('odds'))} AS Odds_Price,
                 {cast_float('s',f.get('open'))} AS Open_Value,
                 {cast_str('s',f.get('outcome'))} AS Outcome,
                 m.Home_Team_Norm,m.Away_Team_Norm
          FROM `{table}` s JOIN meta m ON CAST(s.`{common_key}` AS STRING)=m.__join_key
          WHERE {source_guard(table,sch,'s')} AND {ts('s',sf)} IS NOT NULL AND {ts('s',sf)} < m.Game_Start
            AND m.Game_Start >= TIMESTAMP('2022-01-01') AND m.Game_Start < CURRENT_TIMESTAMP()
            AND {ts('s',sf)} >= TIMESTAMP_SUB(m.Game_Start, INTERVAL 36 HOUR)
        """
    try:
        df=bq.query(sql).to_dataframe(bqstorage_client=bqs)
    except Exception as e:
        log_func(f"[V13-MARKET] selected source query failed: {e}")
        return pd.DataFrame()
    if df.empty:
        log_func("[V13-MARKET] selected historical source returned zero rows")
        return df
    reps=np.nan
    if 'Game_Key' in df.columns and df['Game_Key'].notna().any():
        reps=(df.groupby('Game_Key',dropna=False)['Snapshot_Timestamp'].nunique()>=2).mean()
    role=("AUTHORITATIVE_SCORED_HISTORY" if table==SCORES_FEATURES_TABLE else
          "RECENT_ENRICHED_FALLBACK" if table==MOVES_FEATURES_TABLE else
          "RAW_FALLBACK" if table==BQ_FULL_TABLE else "ARCHIVE_FALLBACK")
    log_func(f"[V13-MARKET-SOURCE] source={table} source_role={role} join_mode={best['route']} rows={len(df)} snap_col={sf} game_col={gf} repeated_game_frac={reps if np.isfinite(reps) else 'NA'}")
    df.attrs['v13_market_source']={"source":table,"source_role":role,"authoritative_source":SCORES_FEATURES_TABLE,
        "fallback_used":bool(table!=SCORES_FEATURES_TABLE),"join_mode":best['route'],"snapshot_col":sf,"game_col":gf,
        "rows":int(len(df)),"covers_2025":bool(best['covers_2025']),"rows_2025":int(best.get('rows_2025',0)),
        "games_2025":int(best.get('games_2025',0)),"min_snapshot":str(best['min_snapshot']),"max_snapshot":str(best['max_snapshot'])}
    return df


def _ncaaf_v13_build_market_horizons(snaps: pd.DataFrame, log_func=print):
    """Build leak-safe 24h/6h/1h market states from irregular historical snapshots.

    V13.0.9 keeps the fixed decision-horizon architecture, but no longer requires a
    quote to land in an unrealistically narrow clock window.  At horizon H we use
    only observations timestamped at or BEFORE Game_Start-H and carry the most
    recent one forward within a predeclared staleness cap.  Staleness is exposed
    to the model as a feature and logged explicitly; no future quote is ever used.
    """
    if snaps is None or snaps.empty:
        return pd.DataFrame(), []
    d=snaps.copy()
    d["Snapshot_Timestamp"]=pd.to_datetime(d["Snapshot_Timestamp"],errors="coerce",utc=True)
    d["Game_Start"]=pd.to_datetime(d["Game_Start"],errors="coerce",utc=True)
    for c in ("Bookmaker","Outcome","Home_Team_Norm","Away_Team_Norm"):
        d[c]=d[c].astype(str).str.lower().str.strip()
    d["Value"]=pd.to_numeric(d["Value"],errors="coerce")
    d["Open_Value"]=pd.to_numeric(d.get("Open_Value"),errors="coerce")
    d["Odds_Price"]=pd.to_numeric(d.get("Odds_Price"),errors="coerce")
    is_home=d["Outcome"].eq(d["Home_Team_Norm"])|d["Outcome"].eq("home")
    is_away=d["Outcome"].eq(d["Away_Team_Norm"])|d["Outcome"].eq("away")
    d["Home_Spread"]=np.where(is_home,d["Value"],np.where(is_away,-d["Value"],np.nan))
    d["Open_Home_Spread"]=np.where(is_home,d["Open_Value"],np.where(is_away,-d["Open_Value"],np.nan))
    d=d.loc[
        np.isfinite(pd.to_numeric(d["Home_Spread"],errors="coerce"))
        & d["Snapshot_Timestamp"].notna()
        & d["Game_Start"].notna()
        & d["Snapshot_Timestamp"].lt(d["Game_Start"])
    ].copy()
    d["Season"]=_ncaaf_season_from_timestamp(d["Game_Start"])
    d["V13_Pair_Key"]=_ncaaf_v13_pair_key(d["Season"],d["Home_Team_Norm"],d["Away_Team_Norm"])
    d["V13_Matchup_Key"]=_ncaaf_v13_matchup_key(d["Season"],d["Game_Start"],d["Home_Team_Norm"],d["Away_Team_Norm"])
    d["__sharp"]=d["Bookmaker"].isin({str(x).lower().strip() for x in SHARP_BOOKS})
    d["__rec"]=d["Bookmaker"].isin({str(x).lower().strip() for x in REC_BOOKS})
    d["__age_h"]=(d["Game_Start"]-d["Snapshot_Timestamp"]).dt.total_seconds().div(3600.0)
    d=d.loc[pd.to_numeric(d["__age_h"],errors="coerce").between(0,36,inclusive="both")].copy()

    # Source cadence audit.  Many rows can be simultaneous bookmaker/outcome
    # observations rather than distinct time snapshots, so report physical-game
    # temporal repetition rather than raw row density.
    if not d.empty:
        per_game=(d.groupby("V13_Matchup_Key",sort=False)["Snapshot_Timestamp"].nunique())
        repeated=float((per_game>=2).mean()) if len(per_game) else np.nan
        ages=pd.to_numeric(d["__age_h"],errors="coerce").dropna()
        q=ages.quantile([.10,.25,.50,.75,.90]).to_dict() if len(ages) else {}
        log_func(
            f"[V13-MARKET-CADENCE] rows={len(d)} games={d['V13_Matchup_Key'].nunique()} "
            f"repeat_physical_game_frac={repeated:.3f} unique_snapshots_median={float(per_game.median()) if len(per_game) else np.nan:.2f} "
            f"age_h_p10={q.get(.10,np.nan):.2f} p25={q.get(.25,np.nan):.2f} p50={q.get(.50,np.nan):.2f} "
            f"p75={q.get(.75,np.nan):.2f} p90={q.get(.90,np.nan):.2f}"
        )

    # final pre-kick snapshot per book -> sharp consensus close target
    last=(d.sort_values("Snapshot_Timestamp").groupby(["V13_Matchup_Key","Bookmaker"],sort=False,as_index=False).tail(1))
    last["__close_age_h"]=(last["Game_Start"]-last["Snapshot_Timestamp"]).dt.total_seconds().div(3600.0)
    def close_agg(g):
        near=g.loc[g["__sharp"] & pd.to_numeric(g["__close_age_h"],errors="coerce").between(0,2,inclusive="both")]
        sharp_src=near if not near.empty else g.loc[g["__sharp"]]
        sharp=(-pd.to_numeric(sharp_src["Home_Spread"],errors="coerce")).median()
        allv=(-pd.to_numeric(g["Home_Spread"],errors="coerce")).median()
        close_age=float(pd.to_numeric(sharp_src.get("__close_age_h"),errors="coerce").median()) if not sharp_src.empty else np.nan
        return pd.Series({"Sharp_Close_Margin":sharp if np.isfinite(sharp) else allv,"Sharp_Close_Age_Hours":close_age})
    close=last.groupby("V13_Matchup_Key",sort=False).apply(close_agg).reset_index()

    frames=[]
    feature_cols=[
        "Current_Margin","Open_Margin","Sharp_Current_Margin","Rec_Current_Margin",
        "SharpMinusRec","Move_From_Open","Sharp_Move_From_Open","Rec_Move_From_Open",
        "Book_Dispersion","Book_Count","Sharp_Book_Count","Rec_Book_Count","Horizon_Hours",
        "Snapshot_Age_Hours","Snapshot_Staleness_Hours","Snapshot_Freshness_Weight",
        "Dist_to_Key_3","Dist_to_Key_7","Dist_to_Key_10","Dist_to_Key_14",
        "Abs_Move_From_Open","Abs_SharpMinusRec","Current_vs_Sharp","SharpRec_Move_Agreement",
        "Sharp_Book_Fraction","Rec_Book_Fraction","Consensus_Tightness","Nearest_Key_Distance",
        "Key_Cross_3","Key_Cross_7","Key_Cross_10","Key_Cross_14",
    ]

    # Predeclared operational staleness caps.  These are coverage/semantics rules,
    # not outcome-tuned parameters.  They preserve "as of H hours" while allowing
    # irregular historical capture cadence.
    staleness_caps={24.0:12.0, 6.0:12.0, 1.0:5.0}
    old_tols={24.0:12.0,6.0:3.0,1.0:1.0}

    for h in NCAAF_V13_HORIZONS_HOURS:
        h=float(h)
        cap=float(staleness_caps.get(h,max(3.0,h/2.0)))
        narrow=float(old_tols.get(h,max(1.0,h/2.0)))

        # Age >= h guarantees the quote existed by the decision time.
        narrow_mask=pd.to_numeric(d["__age_h"],errors="coerce").between(h,h+narrow,inclusive="both")
        eligible_mask=pd.to_numeric(d["__age_h"],errors="coerce").between(h,h+cap,inclusive="both")
        narrow_games=int(d.loc[narrow_mask,"V13_Matchup_Key"].nunique())
        eligible=d.loc[eligible_mask].copy()
        if eligible.empty:
            log_func(f"[V13-MARKET-HORIZON-COVERAGE] horizon={h:.0f}h narrow_games={narrow_games} asof_games=0 staleness_cap_h={cap:.1f}")
            continue

        cur=(eligible.sort_values("Snapshot_Timestamp")
             .groupby(["V13_Matchup_Key","Bookmaker"],sort=False,as_index=False).tail(1))

        def agg(g):
            margins=-pd.to_numeric(g["Home_Spread"],errors="coerce")
            sm=-pd.to_numeric(g.loc[g["__sharp"],"Home_Spread"],errors="coerce")
            rm=-pd.to_numeric(g.loc[g["__rec"],"Home_Spread"],errors="coerce")
            om=-pd.to_numeric(g["Open_Home_Spread"],errors="coerce")
            ages=pd.to_numeric(g["__age_h"],errors="coerce")
            current=float(margins.median()) if margins.notna().any() else np.nan
            op=float(om.median()) if om.notna().any() else current
            sharp=float(sm.median()) if sm.notna().any() else current
            rec=float(rm.median()) if rm.notna().any() else current
            age=float(ages.median()) if ages.notna().any() else np.nan
            stale=max(0.0,age-h) if np.isfinite(age) else np.nan
            one=g.sort_values("Snapshot_Timestamp").iloc[-1]
            out={
                "Season":float(one["Season"]),"Game_Start":one["Game_Start"],
                "Home_Team_Norm":one["Home_Team_Norm"],"Away_Team_Norm":one["Away_Team_Norm"],
                "Current_Margin":current,"Open_Margin":op,"Sharp_Current_Margin":sharp,"Rec_Current_Margin":rec,
                "SharpMinusRec":sharp-rec,"Move_From_Open":current-op,"Sharp_Move_From_Open":sharp-op,
                "Rec_Move_From_Open":rec-op,"Book_Dispersion":float(margins.std(ddof=0)) if margins.notna().sum()>1 else 0.0,
                "Book_Count":float(g["Bookmaker"].nunique()),"Sharp_Book_Count":float(g.loc[g["__sharp"],"Bookmaker"].nunique()),
                "Rec_Book_Count":float(g.loc[g["__rec"],"Bookmaker"].nunique()),"Horizon_Hours":h,
                "Snapshot_Age_Hours":age,"Snapshot_Staleness_Hours":stale,
                "Snapshot_Freshness_Weight":float(np.exp(-stale/max(cap,1.0))) if np.isfinite(stale) else np.nan,
            }
            for key in (3,7,10,14):
                out[f"Dist_to_Key_{key}"]=abs(abs(current)-float(key)) if np.isfinite(current) else np.nan
                if np.isfinite(current) and np.isfinite(op):
                    a0=abs(op)-float(key); a1=abs(current)-float(key)
                    out[f"Key_Cross_{key}"]=float((a0*a1)<=0 and not np.isclose(op,current,atol=1e-9))
                else:
                    out[f"Key_Cross_{key}"]=np.nan
            out["Abs_Move_From_Open"]=abs(current-op) if np.isfinite(current) and np.isfinite(op) else np.nan
            out["Abs_SharpMinusRec"]=abs(sharp-rec) if np.isfinite(sharp) and np.isfinite(rec) else np.nan
            out["Current_vs_Sharp"]=current-sharp if np.isfinite(current) and np.isfinite(sharp) else np.nan
            smove=sharp-op if np.isfinite(sharp) and np.isfinite(op) else np.nan
            rmove=rec-op if np.isfinite(rec) and np.isfinite(op) else np.nan
            out["SharpRec_Move_Agreement"]=float(np.sign(smove)*np.sign(rmove)) if np.isfinite(smove) and np.isfinite(rmove) else np.nan
            bc=max(float(out["Book_Count"]),1.0)
            out["Sharp_Book_Fraction"]=float(out["Sharp_Book_Count"])/bc
            out["Rec_Book_Fraction"]=float(out["Rec_Book_Count"])/bc
            out["Consensus_Tightness"]=1.0/(1.0+max(float(out["Book_Dispersion"]),0.0)) if np.isfinite(out["Book_Dispersion"]) else np.nan
            _ds=[out[f"Dist_to_Key_{k}"] for k in (3,7,10,14) if np.isfinite(out[f"Dist_to_Key_{k}"])]
            out["Nearest_Key_Distance"]=min(_ds) if _ds else np.nan
            return pd.Series(out)

        a=cur.groupby("V13_Matchup_Key",sort=False).apply(agg).reset_index()
        a["V13_Pair_Key"]=_ncaaf_v13_pair_key(a["Season"],a["Home_Team_Norm"],a["Away_Team_Norm"])
        a=a.merge(close,on="V13_Matchup_Key",how="left",validate="one_to_one")
        frames.append(a)

        stale=pd.to_numeric(a["Snapshot_Staleness_Hours"],errors="coerce").dropna()
        log_func(
            f"[V13-MARKET-HORIZON-COVERAGE] horizon={h:.0f}h narrow_games={narrow_games} "
            f"asof_games={a['V13_Matchup_Key'].nunique()} staleness_cap_h={cap:.1f} "
            f"median_staleness_h={float(stale.median()) if len(stale) else np.nan:.2f} "
            f"p90_staleness_h={float(stale.quantile(.90)) if len(stale) else np.nan:.2f}"
        )

    out=pd.concat(frames,ignore_index=True) if frames else pd.DataFrame()
    out=out.replace([np.inf,-np.inf],np.nan)
    log_func(f"[V13-MARKET-HORIZONS] rows={len(out)} games={out['V13_Matchup_Key'].nunique() if not out.empty else 0} horizons={sorted(out['Horizon_Hours'].dropna().unique().tolist()) if not out.empty else []}")
    return out, feature_cols



def _ncaaf_v13_fit_market_intelligence(frame: pd.DataFrame, feature_cols, log_func=print):
    """Chronological OOS Market Brain using residual-to-close learning.

    Predicting the absolute close forces a small-sample model to relearn the identity
    Current_Line -> Close.  V13.0.9 instead predicts the *remaining move* from the
    current as-of consensus to the sharp close, then reconstructs:
        Predicted_Close = Current_Margin + Predicted_Close_Move.
    The no-move benchmark is therefore exactly delta=0.  Architecture is unchanged:
    the Market Brain still predicts the future sharp consensus close and must beat
    the no-move current-line baseline OOS before it receives any authority.
    """
    if frame is None or frame.empty:
        return None
    d=frame.copy()
    d["Game_Start"]=pd.to_datetime(d["Game_Start"],errors="coerce",utc=True)
    y_close=pd.to_numeric(d["Sharp_Close_Margin"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    cur_all=pd.to_numeric(d["Current_Margin"],errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    y_move=y_close-cur_all
    oof=np.full(len(d),np.nan); oof_move=np.full(len(d),np.nan); metrics=[]
    # Small-sample challenger: a compact Ridge-only residual model.  The full
    # Market Brain currently exposes 32 correlated features to early folds with
    # roughly 90-130 physical games, so this candidate tests whether lower variance
    # beats complexity. It is research-only and cannot open the production gate.
    lite_cols=[c for c in [
        "Current_Margin","Move_From_Open","SharpMinusRec","Book_Dispersion",
        "Sharp_Book_Fraction","Horizon_Hours","Snapshot_Staleness_Hours",
        "Nearest_Key_Distance","Sharp_Move_From_Open"
    ] if c in d.columns]
    oof_lite=np.full(len(d),np.nan)

    game_clock=(d.loc[d["Game_Start"].notna(),["V13_Matchup_Key","Game_Start"]]
                  .drop_duplicates("V13_Matchup_Key")
                  .sort_values("Game_Start",kind="stable")
                  .reset_index(drop=True))
    n_games=len(game_clock)
    log_func(f"[V13-MARKET-COMPLEXITY] physical_games={n_games} full_features={len(feature_cols)} lite_features={len(lite_cols)} candidate=RIDGE_ONLY_RESEARCH")
    if n_games < 160:
        log_func(f"[V13-MARKET] insufficient physical games after horizon construction n_games={n_games}")
        return None

    # With sparse irregular snapshots, rows-per-game is near one.  Build enough
    # expanding folds to evaluate the archive instead of requiring 200+ rows before
    # the first prediction.  The performance gate remains clustered and fail-closed.
    min_train_games=max(90,min(140,int(n_games*0.35)))
    remaining=max(n_games-min_train_games,0)
    val_games=max(30,min(50,int(max(remaining,1)/4)))
    log_func(
        f"[V13-MARKET-FOLD-CONTRACT] physical_games={n_games} min_train_games={min_train_games} "
        f"validation_block_games={val_games} features={len(feature_cols)} grouping=PHYSICAL_GAME chronological=TRUE "
        f"target=CLOSE_MOVE_RESIDUAL"
    )

    folds=[]; cursor=min_train_games
    while cursor<n_games and len(folds)<6:
        stop=min(n_games,cursor+val_games)
        va_slice=game_clock.iloc[cursor:stop]
        if len(va_slice)<25: break
        va_keys=set(va_slice["V13_Matchup_Key"].astype(str))
        tr_keys=set(game_clock.iloc[:cursor]["V13_Matchup_Key"].astype(str))
        folds.append((tr_keys,va_keys,va_slice["Game_Start"].min(),va_slice["Game_Start"].max()))
        cursor=stop

    min_train_rows=max(100,3*max(1,len(feature_cols)))
    for j,(tr_keys,va_keys,vmin,vmax) in enumerate(folds,1):
        tr=d["V13_Matchup_Key"].astype(str).isin(tr_keys).to_numpy() & np.isfinite(y_move)
        va=d["V13_Matchup_Key"].astype(str).isin(va_keys).to_numpy() & np.isfinite(y_move)
        if len(tr_keys)<min_train_games or int(tr.sum())<min_train_rows or int(va.sum())<25:
            log_func(
                f"[V13-MARKET-PERIOD-SKIP] fold={j} train_games={len(tr_keys)} train_rows={int(tr.sum())} "
                f"valid_games={len(va_keys)} valid_rows={int(va.sum())} "
                f"requirements=train_games>={min_train_games},train_rows>={min_train_rows},valid_rows>=25"
            )
            continue
        model=_ncaaf_v13_fit_regression_pair(d.loc[tr,feature_cols],y_move[tr])
        move_pred=_ncaaf_v13_regression_predict(model,d.loc[va,feature_cols],0.75)
        idx=np.where(va)[0]
        pred=cur_all[idx]+move_pred
        oof[idx]=pred; oof_move[idx]=move_pred
        if len(lite_cols)>=3:
            try:
                _lm=_ncaaf_stat_new_qualification_model(); _lm.fit(d.loc[tr,lite_cols],y_move[tr])
                _lmove=np.asarray(_lm.predict(d.loc[va,lite_cols]),dtype=float)
                oof_lite[idx]=cur_all[idx]+_lmove
            except Exception as _e:
                log_func(f"[V13-MARKET-LITE] fold={j} unavailable={_e}")
        actual_move=y_move[idx]
        rec={"fold":j,"n":int(va.sum()),"games":int(len(va_keys)),"valid_start":str(vmin),"valid_end":str(vmax),
             "rmse":_ncaaf_v13_rmse(y_close[idx],pred),"mae":_ncaaf_v13_mae(y_close[idx],pred),
             "no_move_rmse":_ncaaf_v13_rmse(y_close[idx],cur_all[idx]),"no_move_mae":_ncaaf_v13_mae(y_close[idx],cur_all[idx]),
             "move_rmse":_ncaaf_v13_rmse(actual_move,move_pred),"zero_move_rmse":_ncaaf_v13_rmse(actual_move,np.zeros_like(actual_move))}
        rec["rmse_gain_vs_current"]=rec["no_move_rmse"]-rec["rmse"]
        rec["mae_gain_vs_current"]=rec["no_move_mae"]-rec["mae"]
        metrics.append(rec)
        log_func(
            f"[V13-MARKET-PERIOD] fold={j} games={rec['games']} rows={rec['n']} window={vmin}..{vmax} "
            f"close_rmse={rec['rmse']:.3f} current_line={rec['no_move_rmse']:.3f} rmse_gain={rec['rmse_gain_vs_current']:+.3f} "
            f"close_mae={rec['mae']:.3f} current_mae={rec['no_move_mae']:.3f} mae_gain={rec['mae_gain_vs_current']:+.3f} "
            f"move_rmse={rec['move_rmse']:.3f} zero_move_rmse={rec['zero_move_rmse']:.3f}"
        )

    good=np.isfinite(oof)&np.isfinite(y_close)&np.isfinite(cur_all)
    good_games=int(d.loc[good,"V13_Matchup_Key"].nunique()) if good.any() else 0
    # The archive has only 246 horizon-eligible physical games.  Require a broad
    # majority of the usable chronological holdout while letting clustered CIs,
    # not an arbitrary row-count impossible for this grain, decide authority.
    if int(good.sum())<120 or good_games<100:
        log_func(f"[V13-MARKET] insufficient OOF rows={int(good.sum())} games={good_games} requirements=rows>=120,games>=100")
        return None

    groups=d.loc[good,"V13_Matchup_Key"].astype(str).to_numpy(dtype=object)
    boot=_ncaaf_v13_bootstrap_regression_skill(y_close[good],cur_all[good],oof[good],groups=groups,reps=800,seed=13039)
    positive_periods=sum(1 for r in metrics if r.get("rmse_gain_vs_current",0)>0 and r.get("mae_gain_vs_current",0)>0)
    needed=max(1,int(np.ceil(len(metrics)*0.5))) if metrics else 1
    rm_low=float((boot.get("rmse_skill_ci95") or [np.nan,np.nan])[0]); ma_low=float((boot.get("mae_skill_ci95") or [np.nan,np.nan])[0])
    gate=bool(np.isfinite(rm_low) and np.isfinite(ma_low) and rm_low>0 and ma_low>0 and positive_periods>=needed)
    log_func(
        f"[V13-MARKET-GATE] target=CLOSE_MOVE_RESIDUAL oof_n={int(good.sum())} games={boot.get('groups',0)} "
        f"rmse_gain={boot.get('rmse_skill',np.nan):+.4f} rmse_ci95={boot.get('rmse_skill_ci95')} "
        f"mae_gain={boot.get('mae_skill',np.nan):+.4f} mae_ci95={boot.get('mae_skill_ci95')} "
        f"positive_periods={positive_periods}/{len(metrics)} gate={'PASS' if gate else 'CLOSED'}"
    )
    lite_boot={}
    lite_good=np.isfinite(oof_lite)&np.isfinite(y_close)&np.isfinite(cur_all)
    if int(lite_good.sum())>=120 and int(d.loc[lite_good,"V13_Matchup_Key"].nunique())>=100:
        lite_groups=d.loc[lite_good,"V13_Matchup_Key"].astype(str).to_numpy(dtype=object)
        lite_boot=_ncaaf_v13_bootstrap_regression_skill(y_close[lite_good],cur_all[lite_good],oof_lite[lite_good],groups=lite_groups,reps=800,seed=13040)
        log_func(f"[V13-MARKET-LITE-GATE] authority=RESEARCH_ONLY model=RIDGE target=CLOSE_MOVE_RESIDUAL oof_n={int(lite_good.sum())} games={lite_boot.get('groups',0)} rmse_gain={lite_boot.get('rmse_skill',np.nan):+.4f} rmse_ci95={lite_boot.get('rmse_skill_ci95')} mae_gain={lite_boot.get('mae_skill',np.nan):+.4f} mae_ci95={lite_boot.get('mae_skill_ci95')}")
    all_good=np.isfinite(y_move)
    final=_ncaaf_v13_fit_regression_pair(d.loc[all_good,feature_cols],y_move[all_good])
    d["V13_Pred_Close_OOF"]=oof
    d["V13_Pred_Close_Move_OOF"]=oof_move
    d["V13_Pred_Close_Lite_OOF"]=oof_lite
    return {"feature_cols":feature_cols,"models":final,"linear_weight":0.75,"period_metrics":metrics,"season_metrics":metrics,
            "oof_frame":d,"bootstrap":boot,"research_gate_pass":gate,"positive_periods":int(positive_periods),
            "market_lite":{"feature_cols":lite_cols,"bootstrap":lite_boot,"authority":"RESEARCH_ONLY"},
            "target_mode":"CLOSE_MOVE_RESIDUAL","baseline":"CURRENT_LINE_NO_MOVE"}

def _ncaaf_v13_new_cover_model():
    from sklearn.pipeline import Pipeline
    from sklearn.impute import SimpleImputer
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import LogisticRegression
    return Pipeline([
        ("imputer",SimpleImputer(strategy="median",add_indicator=True)),
        ("scale",StandardScaler()),
        ("logit",LogisticRegression(C=0.35,solver="lbfgs",max_iter=1000,random_state=1300)),
    ])


def _ncaaf_v13_cover_metrics(y,p):
    from sklearn.metrics import roc_auc_score, log_loss, brier_score_loss
    y=np.asarray(y,dtype=int); p=np.asarray(p,dtype=float); ok=np.isfinite(p)
    if ok.sum()<20 or np.unique(y[ok]).size<2: return {"n":int(ok.sum()),"auc":np.nan,"logloss":np.nan,"brier":np.nan}
    return {"n":int(ok.sum()),"auc":float(roc_auc_score(y[ok],p[ok])),"logloss":float(log_loss(y[ok],np.clip(p[ok],1e-6,1-1e-6),labels=[0,1])),"brier":float(brier_score_loss(y[ok],p[ok]))}


def _ncaaf_v13_cluster_bootstrap_skill(frame, y, p, reps=300, seed=1300):
    """95% CI for proper-score skill, resampling physical game+horizon clusters."""
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float)
    ok=np.isfinite(pp)
    if int(ok.sum())<200:
        return {"clusters":0,"ll_skill_ci95":[np.nan,np.nan],"brier_skill_ci95":[np.nan,np.nan]}
    f=frame.loc[ok,["V13_Matchup_Key","Horizon_Hours"]].copy().reset_index(drop=True)
    yy=yy[ok]; pp=np.clip(pp[ok],1e-6,1-1e-6)
    # Treat all decision horizons from one physical game as one bootstrap cluster.
    f["__cluster"]=f["V13_Matchup_Key"].astype(str)
    groups=[np.asarray(ix,dtype=int) for _,ix in f.groupby("__cluster",sort=False).groups.items()]
    if len(groups)<80:
        return {"clusters":len(groups),"ll_skill_ci95":[np.nan,np.nan],"brier_skill_ci95":[np.nan,np.nan]}
    rng=np.random.default_rng(seed); ll_skill=[]; br_skill=[]
    for _ in range(int(reps)):
        picks=rng.integers(0,len(groups),size=len(groups))
        ix=np.concatenate([groups[j] for j in picks])
        yb=yy[ix]; pb=pp[ix]
        model_ll=float(-np.mean(yb*np.log(pb)+(1-yb)*np.log(1-pb)))
        base_ll=float(-np.mean(yb*np.log(0.5)+(1-yb)*np.log(0.5)))
        model_br=float(np.mean((pb-yb)**2)); base_br=float(np.mean((0.5-yb)**2))
        ll_skill.append(base_ll-model_ll); br_skill.append(base_br-model_br)
    return {
        "clusters":len(groups),
        "ll_skill_ci95":[float(np.quantile(ll_skill,0.025)),float(np.quantile(ll_skill,0.975))],
        "brier_skill_ci95":[float(np.quantile(br_skill,0.025)),float(np.quantile(br_skill,0.975))],
    }



def _ncaaf_v13_fundamental_cover_frame(fundamental: dict) -> pd.DataFrame:
    """One physical game per row, leakage-safe V13 Fundamental cover features."""
    if not isinstance(fundamental,dict) or not isinstance(fundamental.get("oof_frame"),pd.DataFrame):
        return pd.DataFrame()
    z=fundamental["oof_frame"].copy()
    raw=pd.to_numeric(z.get("V13_Raw_Fair_Margin_OOF"),errors="coerce")
    trad=pd.to_numeric(z.get("V13_Tradable_Fair_Margin_OOF"),errors="coerce")
    mkt=pd.to_numeric(z.get("Market_Open_Margin"),errors="coerce")
    actual=pd.to_numeric(z.get("Actual_Margin"),errors="coerce")
    z["Raw_Fundamental_Edge"]=raw-mkt
    z["Fundamental_Edge"]=trad-mkt
    z["Abs_Raw_Fundamental_Edge"]=z["Raw_Fundamental_Edge"].abs()
    z["Fair_Total"]=pd.to_numeric(z.get("V13_Tradable_Fair_Total_OOF"),errors="coerce")
    z["Market_Magnitude"]=mkt.abs()
    # The generic clustered proper-score bootstrap accepts a horizon column; the
    # Fundamental-only calibrator is one observation per game, so use a constant.
    z["Horizon_Hours"]=0.0
    lin=pd.to_numeric(z.get("V13_Linear_Fair_Margin_OOF"),errors="coerce")
    hgb=pd.to_numeric(z.get("V13_HGB_Fair_Margin_OOF"),errors="coerce")
    z["Component_Disagreement"]=(lin-hgb).abs()
    z["Context_Week"]=pd.to_numeric(z.get("Context_Week"),errors="coerce")
    z["Context_Cross_Subdivision"]=pd.to_numeric(z.get("Context_Cross_Subdivision"),errors="coerce").fillna(0.0)
    for k in (3,7,10,14):
        z[f"Dist_to_Key_{k}"]=(z["Market_Magnitude"]-float(k)).abs()
    z["Edge_x_LogAbsRaw"]=z["Fundamental_Edge"]*np.log1p(z["Abs_Raw_Fundamental_Edge"].clip(lower=0))
    z["Edge_x_Component_Disagreement"]=z["Fundamental_Edge"]*z["Component_Disagreement"].clip(lower=0)
    z["Edge_x_Early"]=z["Fundamental_Edge"]*z["Context_Week"].le(4).astype(float)
    z["Edge_x_Cross_Subdivision"]=z["Fundamental_Edge"]*z["Context_Cross_Subdivision"]
    z["Edge_x_MarketMagnitude"]=z["Fundamental_Edge"]*np.log1p(z["Market_Magnitude"].clip(lower=0))
    cover_margin=actual-mkt
    z["Cover_Margin"]=cover_margin
    z=z.loc[cover_margin.notna() & ~np.isclose(cover_margin,0.0,atol=1e-9)].copy()
    z["Cover"]=(pd.to_numeric(z["Cover_Margin"],errors="coerce")>0).astype("int8")
    return z.replace([np.inf,-np.inf],np.nan).reset_index(drop=True)


def _ncaaf_v13_fundamental_cover_feature_sets():
    # CORE is deliberately small and architecture-derived.  ENHANCED is a
    # research-only uncertainty/trust candidate and is never allowed to alter the
    # primary V12-vs-V13 comparison or runtime authority in V13.0.10.
    core=[
        "Fundamental_Edge","Abs_Raw_Fundamental_Edge","Fair_Total","Market_Magnitude",
        "Dist_to_Key_3","Dist_to_Key_7","Dist_to_Key_10","Dist_to_Key_14",
    ]
    enhanced=core+[
        "Component_Disagreement","Context_Week","Context_Cross_Subdivision",
        "Edge_x_LogAbsRaw","Edge_x_Component_Disagreement","Edge_x_Early",
        "Edge_x_Cross_Subdivision","Edge_x_MarketMagnitude",
    ]
    return core, enhanced


def _ncaaf_v13_fit_fundamental_cover_calibrator(fundamental: dict, log_func=print):
    """Season-forward Fundamental-only cover probability; no Market Brain input."""
    z=_ncaaf_v13_fundamental_cover_frame(fundamental)
    if z.empty: return None
    core_cols,enh_cols=_ncaaf_v13_fundamental_cover_feature_sets()
    seasons=sorted(int(x) for x in pd.to_numeric(z.get("Season"),errors="coerce").dropna().unique())
    season_arr=pd.to_numeric(z.get("Season"),errors="coerce").to_numpy(dtype=float,na_value=np.nan)
    y=z["Cover"].to_numpy(dtype=int)
    _meta_ready=(
        pd.to_numeric(z.get("Fundamental_Edge"),errors="coerce").notna()
        & pd.to_numeric(z.get("Abs_Raw_Fundamental_Edge"),errors="coerce").notna()
        & pd.to_numeric(z.get("Fair_Total"),errors="coerce").notna()
    ).to_numpy(dtype=bool)
    log_func(f"[V13-FUND-COVER-STACK-CONTRACT] rows={len(z)} meta_ready={int(_meta_ready.sum())} first_ready_season={int(np.nanmin(season_arr[_meta_ready])) if _meta_ready.any() else 'NA'} base_predictions_required=TRUE")
    oof_core=np.full(len(z),np.nan); oof_enh=np.full(len(z),np.nan)
    fold_models={}; enhanced_fold_models={}; folds=[]; enhanced_folds=[]
    for val in seasons[1:]:
        tr=np.isfinite(season_arr)&(season_arr<float(val))&_meta_ready; va=np.isfinite(season_arr)&(season_arr==float(val))&_meta_ready
        if int(tr.sum())<500 or int(va.sum())<75 or np.unique(y[tr]).size<2: continue
        m=_ncaaf_v13_new_cover_model(); m.fit(z.loc[tr,core_cols],y[tr]); p=m.predict_proba(z.loc[va,core_cols])[:,1]
        idx=np.where(va)[0]; oof_core[idx]=p; met=_ncaaf_v13_cover_metrics(y[idx],p); base=_ncaaf_v13_cover_metrics(y[idx],np.full(len(idx),0.5))
        met.update({"season":int(val),"baseline_logloss":base["logloss"],"baseline_brier":base["brier"]}); folds.append(met); fold_models[int(val)]=m
        log_func(f"[V13-FUND-COVER-SEASON] model=CORE season={val} n={met['n']} auc={met['auc']:.4f} ll={met['logloss']:.6f} brier={met['brier']:.6f} ll_skill_vs50={base['logloss']-met['logloss']:+.6f} brier_skill_vs50={base['brier']-met['brier']:+.6f}")
        try:
            me=_ncaaf_v13_new_cover_model(); me.fit(z.loc[tr,enh_cols],y[tr]); pe=me.predict_proba(z.loc[va,enh_cols])[:,1]; oof_enh[idx]=pe
            mete=_ncaaf_v13_cover_metrics(y[idx],pe); enhanced_folds.append({**mete,"season":int(val)}); enhanced_fold_models[int(val)]=me
            log_func(f"[V13-FUND-COVER-SEASON] model=ENHANCED_RESEARCH_ONLY season={val} n={mete['n']} auc={mete['auc']:.4f} ll={mete['logloss']:.6f} brier={mete['brier']:.6f}")
        except Exception as e:
            log_func(f"[V13-FUND-COVER] enhanced season={val} unavailable={e}")
    valid=np.isfinite(oof_core)
    if int(valid.sum())<500: return None
    pooled=_ncaaf_v13_cover_metrics(y[valid],oof_core[valid]); base=_ncaaf_v13_cover_metrics(y[valid],np.full(int(valid.sum()),0.5))
    boot=_ncaaf_v13_cluster_bootstrap_skill(z,y,oof_core,reps=500,seed=13010)
    positive=sum(1 for r in folds if (r["baseline_logloss"]-r["logloss"]>0 and r["baseline_brier"]-r["brier"]>0))
    ll_low=float((boot.get("ll_skill_ci95") or [np.nan,np.nan])[0]); br_low=float((boot.get("brier_skill_ci95") or [np.nan,np.nan])[0])
    gate=bool(np.isfinite(ll_low) and np.isfinite(br_low) and ll_low>0 and br_low>0 and positive>=max(1,int(np.ceil(len(folds)*2/3))))
    final=_ncaaf_v13_new_cover_model(); final.fit(z.loc[_meta_ready,core_cols],y[_meta_ready])
    log_func(f"[V13-FUND-COVER] model=CORE oof_n={pooled['n']} auc={pooled['auc']:.4f} ll={pooled['logloss']:.6f} brier={pooled['brier']:.6f} ll_skill_vs50={base['logloss']-pooled['logloss']:+.6f} brier_skill_vs50={base['brier']-pooled['brier']:+.6f} ll_ci95={boot.get('ll_skill_ci95')} brier_ci95={boot.get('brier_skill_ci95')} positive_seasons={positive}/{len(folds)} gate={'PASS' if gate else 'CLOSED'} authority=SHADOW_ONLY")
    return {
        "feature_cols":core_cols,"enhanced_feature_cols":enh_cols,"model":final,
        "fold_models":fold_models,"enhanced_fold_models":enhanced_fold_models,
        "season_metrics":folds,"enhanced_season_metrics":enhanced_folds,
        "oof_metrics":pooled,"baseline_metrics":base,"bootstrap":boot,
        "research_gate_pass":gate,"oof_frame":z.assign(V13_Fund_Cover_Prob_OOF=oof_core,V13_Fund_Cover_Prob_Enhanced_OOF=oof_enh),
        "comparison_contract":"fundamental_only__season_forward__one_physical_game_per_row__market_brain_excluded",
    }


def _ncaaf_v13_weighted_metrics(y,p,groups):
    from sklearn.metrics import roc_auc_score
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float); gg=np.asarray(groups,dtype=object)
    ok=np.isfinite(pp)
    yy=yy[ok]; pp=np.clip(pp[ok],1e-6,1-1e-6); gg=gg[ok]
    if len(yy)<20: return {"n":len(yy),"games":len(pd.unique(gg)),"auc":np.nan,"logloss":np.nan,"brier":np.nan,"accuracy":np.nan}
    cnt=pd.Series(gg).groupby(pd.Series(gg),sort=False).transform("count").to_numpy(dtype=float)
    w=1.0/np.maximum(cnt,1.0)
    ll=float(np.average(-(yy*np.log(pp)+(1-yy)*np.log(1-pp)),weights=w))
    br=float(np.average((pp-yy)**2,weights=w))
    acc=float(np.average((pp>=0.5)==yy,weights=w))
    auc=float(roc_auc_score(yy,pp,sample_weight=w)) if np.unique(yy).size==2 else np.nan
    ece=0.0; total=float(np.sum(w))
    bins=np.linspace(0.0,1.0,11)
    for bi in range(10):
        bm=(pp>=bins[bi])&(pp<(bins[bi+1] if bi<9 else bins[bi+1]+1e-12))
        if not bm.any(): continue
        wb=w[bm]; mass=float(np.sum(wb))/max(total,1e-12)
        ece+=mass*abs(float(np.average(pp[bm],weights=wb))-float(np.average(yy[bm],weights=wb)))
    return {"n":int(len(yy)),"games":int(len(pd.unique(gg))),"auc":auc,"logloss":ll,"brier":br,"accuracy":acc,"ece":float(ece)}


def _ncaaf_v13_weighted_calibration_diagnostics(y,p,groups,bins=10):
    """Game-balanced calibration diagnostics, including a smooth quantile-bin ICI."""
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float); gg=np.asarray(groups,dtype=object)
    ok=np.isfinite(pp); yy=yy[ok]; pp=np.clip(pp[ok],1e-6,1-1e-6); gg=gg[ok]
    if len(yy)<50 or np.unique(yy).size<2:
        return {"n":int(len(yy)),"ece":np.nan,"ici_smooth":np.nan,"reliability":np.nan,"resolution":np.nan,
                "uncertainty":np.nan,"brier_reconstructed":np.nan,"calibration_intercept":np.nan,"calibration_slope":np.nan}
    cnt=pd.Series(gg).groupby(pd.Series(gg),sort=False).transform("count").to_numpy(dtype=float)
    w=1.0/np.maximum(cnt,1.0); total=float(np.sum(w)); base=float(np.average(yy,weights=w)); unc=base*(1.0-base)
    ece=0.0; rel=0.0; res=0.0; edges=np.linspace(0.0,1.0,int(bins)+1)
    for bi in range(int(bins)):
        hi=edges[bi+1]+(1e-12 if bi==int(bins)-1 else 0.0); bm=(pp>=edges[bi])&(pp<hi)
        if not bm.any(): continue
        wb=w[bm]; mass=float(np.sum(wb))/max(total,1e-12); pbar=float(np.average(pp[bm],weights=wb)); ybar=float(np.average(yy[bm],weights=wb))
        ece+=mass*abs(pbar-ybar); rel+=mass*(pbar-ybar)**2; res+=mass*(ybar-base)**2
    # Smooth calibration error: equal-weight quantile bins, then interpolate the observed
    # rate across probability. This avoids relying on one fixed set of 0.1-wide bins.
    ici=np.nan
    try:
        order=np.argsort(pp); ps=pp[order]; ys=yy[order]; ws=w[order]
        chunks=np.array_split(np.arange(len(ps)),min(20,max(5,len(pd.unique(gg))//10)))
        xp=[]; yp=[]
        for ch in chunks:
            if len(ch)<2 or float(np.sum(ws[ch]))<=0: continue
            xp.append(float(np.average(ps[ch],weights=ws[ch]))); yp.append(float(np.average(ys[ch],weights=ws[ch])))
        if len(xp)>=3:
            xp=np.asarray(xp); yp=np.asarray(yp); oo=np.argsort(xp); xp=xp[oo]; yp=yp[oo]
            smooth=np.interp(pp,xp,yp,left=yp[0],right=yp[-1]); ici=float(np.average(np.abs(pp-smooth),weights=w))
    except Exception: pass
    intercept=slope=np.nan
    try:
        from sklearn.linear_model import LogisticRegression
        x=np.log(pp/(1.0-pp)).reshape(-1,1); mdl=LogisticRegression(C=1e6,solver="lbfgs",max_iter=1000).fit(x,yy,sample_weight=w)
        intercept=float(mdl.intercept_[0]); slope=float(mdl.coef_[0,0])
    except Exception: pass
    return {"n":int(len(yy)),"ece":float(ece),"ici_smooth":float(ici) if np.isfinite(ici) else np.nan,"reliability":float(rel),"resolution":float(res),
            "uncertainty":float(unc),"brier_reconstructed":float(rel-res+unc),"calibration_intercept":intercept,"calibration_slope":slope}


def _ncaaf_v13_paired_model_bootstrap(y,p12,p13,groups,reps=800,seed=13100):
    """Physical-game clustered paired bootstrap for proper scores and calibration deltas."""
    yy=np.asarray(y,dtype=int); a=np.asarray(p12,dtype=float); b=np.asarray(p13,dtype=float); gg=np.asarray(groups,dtype=object)
    ok=np.isfinite(a)&np.isfinite(b); yy=yy[ok]; a=np.clip(a[ok],1e-6,1-1e-6); b=np.clip(b[ok],1e-6,1-1e-6); gg=gg[ok]
    uniq=pd.unique(gg); rng=np.random.default_rng(seed); ll=[]; br=[]; ece=[]; ici=[]; rel=[]; slope=[]; intercept=[]; by={g:np.where(gg==g)[0] for g in uniq}
    for _ in range(int(reps)):
        picks=rng.integers(0,len(uniq),size=len(uniq)); ix=[]; wg=[]; bg=[]
        for jj,j in enumerate(picks):
            ids=by[uniq[j]]; ix.extend(ids.tolist()); wg.extend((np.ones(len(ids))/max(1,len(ids))).tolist()); bg.extend([f'b{jj}']*len(ids))
        ix=np.asarray(ix,dtype=int); w=np.asarray(wg,dtype=float); bg=np.asarray(bg,dtype=object)
        l12=-(yy[ix]*np.log(a[ix])+(1-yy[ix])*np.log(1-a[ix])); l13=-(yy[ix]*np.log(b[ix])+(1-yy[ix])*np.log(1-b[ix]))
        ll.append(float(np.average(l12-l13,weights=w))); br.append(float(np.average((a[ix]-yy[ix])**2-(b[ix]-yy[ix])**2,weights=w)))
        ca=_ncaaf_v13_weighted_calibration_diagnostics(yy[ix],a[ix],bg); cb=_ncaaf_v13_weighted_calibration_diagnostics(yy[ix],b[ix],bg)
        ece.append(float(ca.get('ece',np.nan)-cb.get('ece',np.nan))); ici.append(float(ca.get('ici_smooth',np.nan)-cb.get('ici_smooth',np.nan)))
        rel.append(float(ca.get('reliability',np.nan)-cb.get('reliability',np.nan)))
        slope.append(float(abs(ca.get('calibration_slope',np.nan)-1)-abs(cb.get('calibration_slope',np.nan)-1)))
        intercept.append(float(abs(ca.get('calibration_intercept',np.nan))-abs(cb.get('calibration_intercept',np.nan))))
    def ci(x):
        q=np.asarray(x,dtype=float); q=q[np.isfinite(q)]; return [float(np.quantile(q,.025)),float(np.quantile(q,.975))] if len(q)>=20 else [np.nan,np.nan]
    return {"games":int(len(uniq)),"ll_improvement_ci95":ci(ll),"brier_improvement_ci95":ci(br),"ece_improvement_ci95":ci(ece),
            "ici_improvement_ci95":ci(ici),"reliability_improvement_ci95":ci(rel),"slope_closeness_improvement_ci95":ci(slope),
            "intercept_closeness_improvement_ci95":ci(intercept)}



