def _v13_log_exception(log_func, prefix: str, exc: Exception, limit: int = 8):
    """Emit a compact one-record traceback so Cloud logs retain the failing line."""
    try:
        import traceback
        tb = traceback.format_exc(limit=int(limit)).strip().replace("\n", " | ")
    except Exception:
        tb = "traceback_unavailable"
    try:
        log_func(f"{prefix}={type(exc).__name__}: {exc} traceback={tb}")
    except Exception:
        pass


def _v13_logit(p):
    a=np.clip(np.asarray(p,dtype=float),1e-5,1-1e-5)
    return np.log(a/(1.0-a))


def _v13_sigmoid(z):
    z=np.clip(np.asarray(z,dtype=float),-20.0,20.0)
    return 1.0/(1.0+np.exp(-z))


def _ncaaf_v13_specialist_family(feature: str):
    """Route an existing engineered feature into exactly one V13 specialist family.

    Keep the statistical/history core out of the overlays so it is not counted twice.
    Explicitly preserve the useful non-prefixed Pathi/BigAl engineered features from
    the legacy AutoFS pool; generic System_* consensus fields stay outside the family
    models because they mix the named systems and are better represented by the final
    validation-gated combiner.
    """
    s=str(feature); sl=s.lower()
    if s.startswith(("Pathi_","Brain_Expert_Pathi","Brain_Pathi_")) or "pathi_historical_" in sl:
        return "Pathi"
    if s.startswith(("BigAl_","Brain_Expert_BigAl","Brain_BigAl_")) or "bigal_historical_" in sl:
        return "BigAl"
    if s.startswith(("NCAAF_Stat_","Historical_Core_","Brain_Historical_")):
        return None  # statistical/history core is already represented in the V13 foundation

    # V13.2 attribution contract. Price, implied-probability and ROI variables
    # are MARKET/PRICE evidence even when they were originally researched while
    # building Pathi screens. Broad ATS/revenge context is generic Situation data,
    # not a Big Al system. Big Al authority comes only from named BigAl_* triggers.
    price_explicit={
        "role_price_shift","current_impliedprob_vs_last10_avg","current_impliedprob_vs_last10_median",
        "ml_price_zscore_vs_teamhistory","team_ml_roi_season","team_fav_roi_season","team_dog_roi_season",
        "team_fav_roi_last10","team_dog_roi_last10",
    }
    generic_situation={
        "h2h_consecutive_losses_prior","h2h_consecutive_wins_prior","revenge_depth","h2h_last_loss_margin",
        "h2h_meetings_since_last_win","prev_ats_margin","prev2_ats_margin","prev3_ats_margin",
        "ats_margin_max_last3","ats_margin_min_last3","ats_margin_mean_last3",
    }
    if sl in price_explicit:
        return "Market"
    if sl in generic_situation:
        return None
    if sl.startswith("system_"):
        return None

    if s.startswith("Brain_Expert_Price") or s.startswith("Brain_Expert_Market") or s=="Brain_Current_Implied_Prob":
        return "Market"
    market_tokens=(
        "sharp","market","line_move","line_moved","odds_move","odds_","book_","bookmaker",
        "clv","steam","reversal","resistance","implied_prob","impliedprob","crossed_key",
        "dist_to_key","dist_to_","key_cross","limit","liquidity","overmove","move_from_open",
        "current_vs_best","current_vs_worst","pct_books","juice","breakeven","marketleader",
        "market_leader","hybrid_line","hybrid_odds","corridor","booklift","sharp_rec",
        "sharp_vs_rec","line_mean","line_std","line_delta","odds_shift","first_odds",
        "opening_spread","opening_line","spread_value","value_reversal"
    )
    if any(tok in sl for tok in market_tokens):
        return "Market"
    return None


def _ncaaf_v13_specialist_feature_safe(feature: str, family: str, source: str = "X_train") -> bool:
    """Return True only for predictors that can exist at the live prediction instant.

    Market specialists are deliberately restricted to the already-vetted deployment
    matrix (X_train). Pathi/BigAl may additionally use their raw deterministic
    pregame signals from train_rows, but never future targets, OOF-only columns, or
    current-game result/closing fields.
    """
    s=str(feature or ""); sl=s.lower()
    if not s or _is_hard_leak_feature(s):
        return False
    if s.startswith("Brain_Target_") or sl.startswith("target_"):
        return False
    # OOF values are training diagnostics, not live predictors.
    if sl.endswith("_oof") or "_oof_" in sl:
        return False

    # Explicit current-game/future-market fields. Prior/previous/history variants
    # remain legal because they are known before the game.
    priorish=any(tok in sl for tok in ("prior","prev","previous","historical","history","last","rolling"))
    unsafe_exact={
        "closing_spread_for_team","consensus_close_spread_audit","sharp_close_margin",
        "pinn_prob_final","brain_target_positive_clv","brain_target_future_best_value",
        "brain_target_action_oracle","outcome_result","su_result","cover_margin",
        "raw_ats","score_home","score_away","team_score","opponent_score",
    }
    if sl in unsafe_exact and not priorish:
        return False
    unsafe_tokens=(
        "brain_target_","target_close_","future_best","positive_clv","action_oracle",
        "actual_final","actual_game","realized_result","current_ats_margin",
    )
    if any(tok in sl for tok in unsafe_tokens) and not priorish:
        return False

    # Market may only learn from columns already admitted to the leakage-safe
    # production feature matrix. This is the key HF2 source-boundary contract.
    if str(family)=="Market" and str(source)!="X_train":
        return False
    return True


def _ncaaf_v13_oriented_univariate_auc(x, y, weights=None):
    """Leakage-sanity statistic; direction is irrelevant, only separability matters."""
    from sklearn.metrics import roc_auc_score
    xx=pd.to_numeric(pd.Series(x),errors="coerce").to_numpy(dtype=float)
    yy=np.asarray(y,dtype=int)
    ww=np.ones(len(yy),dtype=float) if weights is None else np.asarray(weights,dtype=float)
    ok=np.isfinite(xx)&np.isfinite(ww)&(ww>0)
    if int(ok.sum())<50 or np.unique(yy[ok]).size<2 or np.nanstd(xx[ok])<=1e-12:
        return np.nan
    try:
        a=float(roc_auc_score(yy[ok],xx[ok],sample_weight=ww[ok]))
        return float(max(a,1.0-a))
    except Exception:
        return np.nan


def _ncaaf_v13_apply_temperature(p, temperature: float):
    """Binary temperature scaling in logit space; T=1 is identity."""
    t=max(float(temperature or 1.0),1e-6)
    return np.clip(_v13_sigmoid(_v13_logit(p)/t),0.01,0.99)


def _ncaaf_v13_calibration_noninferior(base_metrics: dict, candidate_metrics: dict,
                                           max_ece_increase: float = V13_SPECIALIST_MAX_ECE_INCREASE,
                                           max_reliability_increase: float = V13_SPECIALIST_MAX_RELIABILITY_INCREASE) -> bool:
    """Fail closed when an overlay materially worsens probability reliability."""
    try:
        be=float(base_metrics.get("ece",np.nan)); ce=float(candidate_metrics.get("ece",np.nan))
        br=float(base_metrics.get("reliability",np.nan)); cr=float(candidate_metrics.get("reliability",np.nan))
        return bool(np.isfinite(be) and np.isfinite(ce) and ce <= be + float(max_ece_increase)
                    and np.isfinite(br) and np.isfinite(cr) and cr <= br + float(max_reliability_increase))
    except Exception:
        return False


def _ncaaf_v13_choose_softening_temperature(y, p, weights=None):
    """Choose a conservative T>=1 on selection data, never sharpening probabilities."""
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float)
    ww=np.ones(len(yy),dtype=float) if weights is None else np.asarray(weights,dtype=float)
    base=_ncaaf_v13_specialist_metrics(yy,pp,ww)
    best_t=1.0; best=base
    for t in V13_SPECIALIST_TEMPERATURE_GRID:
        cand=_ncaaf_v13_specialist_metrics(yy,_ncaaf_v13_apply_temperature(pp,t),ww)
        if not np.isfinite(cand.get("objective",np.inf)):
            continue
        # Reliability-first: proper scores may improve, but not at the cost of
        # materially worse calibration. Identity always remains a valid fallback.
        cal_ok=(
            cand.get("ece",np.inf) <= base.get("ece",np.inf) + 0.002
            and cand.get("reliability",np.inf) <= base.get("reliability",np.inf) + 0.0005
        )
        proper_ok=(
            cand.get("logloss",np.inf) <= base.get("logloss",np.inf) + 1e-12
            and cand.get("brier",np.inf) <= base.get("brier",np.inf) + 1e-12
        )
        if cal_ok and proper_ok and cand["objective"] < best["objective"] - 1e-12:
            best_t=float(t); best=cand
    return best_t,best,base


def _ncaaf_v13_preoverlay_oof_for_rows(rows: pd.DataFrame, bundle: dict, return_diagnostics: bool = False):
    """Reconstruct the as-of V13 base probability at each offered spread.

    HF3 uses hierarchical physical-game matching because the quote-level outer
    holdout can lack the exact V13 matchup key even though the underlying game is
    present in the historical fundamental OOF frame. Match order is intentionally
    conservative: exact matchup key -> Source_Game_ID -> normalized team pair/date
    -> unique pair within +/-1 day. Ambiguous fallbacks are never used.
    """
    n=0 if rows is None else len(rows)
    out=np.full(n,np.nan,dtype=float); buckets=np.full(n,"UNKNOWN",dtype=object)
    diag={"rows":int(n),"match_counts":{},"reference_rows":0}
    if rows is None or n==0 or not isinstance(bundle,dict):
        return (out,buckets,diag) if return_diagnostics else (out,buckets)
    fund=bundle.get("fundamental") or {}
    cal=(((bundle.get("stability_research") or {}).get("promoted_calibration") or {}))
    ref=fund.get("comparison_oof_frame")
    if not isinstance(ref,pd.DataFrame) or ref.empty:
        return (out,buckets,diag) if return_diagnostics else (out,buckets)
    diag["reference_rows"]=int(len(ref))

    d=rows.copy().reset_index(drop=True)
    d["__v13_row"]=np.arange(len(d),dtype=int)

    def _num_col(name: str, fallback: str | None = None) -> pd.Series:
        if name in d.columns:
            src=d[name]
        elif fallback is not None and fallback in d.columns:
            src=d[fallback]
        else:
            return pd.Series(np.nan,index=d.index,dtype="float64")
        z=pd.to_numeric(src,errors="coerce")
        if not isinstance(z,pd.Series): z=pd.Series(z,index=d.index,dtype="float64")
        return z.reindex(d.index)

    def _date_series(frame: pd.DataFrame) -> pd.Series:
        if "Game_Start" in frame.columns:
            z=pd.to_datetime(frame["Game_Start"],errors="coerce",utc=True)
        elif "feat_Game_Start" in frame.columns:
            z=pd.to_datetime(frame["feat_Game_Start"],errors="coerce",utc=True)
        elif "Game_Date" in frame.columns:
            z=pd.to_datetime(frame["Game_Date"],errors="coerce",utc=True)
        else:
            z=pd.Series(pd.NaT,index=frame.index,dtype="datetime64[ns, UTC]")
        if "Game_Date" in frame.columns:
            gd=pd.to_datetime(frame["Game_Date"],errors="coerce",utc=True)
            z=pd.Series(z,index=frame.index).where(pd.Series(z,index=frame.index).notna(),gd)
        return pd.Series(z,index=frame.index).dt.normalize()

    for c in ("Home_Team_Norm","Away_Team_Norm"):
        if c not in d.columns:
            src="Home_Team" if c.startswith("Home") else "Away_Team"
            d[c]=d[src] if src in d.columns else pd.Series("",index=d.index,dtype=object)
        d[c]=_ncaaf_v13_norm_team_series(d[c]).to_numpy()
    row_date=_date_series(d)
    gs_src=d["Game_Start"] if "Game_Start" in d.columns else (d["feat_Game_Start"] if "feat_Game_Start" in d.columns else row_date)
    gs=pd.to_datetime(gs_src,errors="coerce",utc=True)
    season=pd.to_numeric(d["Season"],errors="coerce") if "Season" in d.columns else pd.Series(np.nan,index=d.index)
    season=pd.Series(season,index=d.index).where(pd.Series(season,index=d.index).notna(),_ncaaf_season_from_timestamp(gs))
    d["__Row_Season"]=season
    d["V13_Matchup_Key"]=_ncaaf_v13_matchup_key(season,gs,d["Home_Team_Norm"],d["Away_Team_Norm"]).to_numpy()
    d["__Pair"]=["|".join(sorted((str(a),str(b)))) for a,b in zip(d["Home_Team_Norm"],d["Away_Team_Norm"])]
    d["__Date"]=[x.strftime("%Y-%m-%d") if pd.notna(x) else "" for x in row_date]
    d["__PairDate"]=d["__Pair"].astype(str)+"|"+d["__Date"].astype(str)

    r=ref.copy().reset_index(drop=True)
    if "Team_Norm" not in r.columns or "Opponent_Norm" not in r.columns or "V13_Raw_Fair_Margin_OOF" not in r.columns:
        return (out,buckets,diag) if return_diagnostics else (out,buckets)
    r["Team_Norm"]=_ncaaf_v13_norm_team_series(r["Team_Norm"]).to_numpy()
    r["Opponent_Norm"]=_ncaaf_v13_norm_team_series(r["Opponent_Norm"]).to_numpy()
    ref_date=_date_series(r)
    r["__Pair"]=["|".join(sorted((str(a),str(b)))) for a,b in zip(r["Team_Norm"],r["Opponent_Norm"])]
    r["__Date"]=[x.strftime("%Y-%m-%d") if pd.notna(x) else "" for x in ref_date]
    r["__PairDate"]=r["__Pair"].astype(str)+"|"+r["__Date"].astype(str)
    if "V13_Matchup_Key" not in r.columns:
        r["V13_Matchup_Key"]=""

    target_cols={
        "Season":"__Ref_Season","Source_Game_ID":"__Ref_Source_Game_ID",
        "Team_Norm":"__Anchor_Team","Opponent_Norm":"__Anchor_Opp",
        "V13_Raw_Fair_Margin_OOF":"__Raw_Fair_Anchor",
        "Market_Open_Margin":"__Open_Margin_Anchor",
        "Context_Min_Games_Prior":"__Context_Min_Games_Prior",
    }
    for dst in target_cols.values(): d[dst]=np.nan if dst not in ("__Anchor_Team","__Anchor_Opp","__Ref_Source_Game_ID") else ""
    match_method=np.full(n,"UNMATCHED",dtype=object)

    def _fill_lookup(row_key: pd.Series, ref_key: str, label: str, only_unique: bool=False):
        nonlocal d,match_method
        if ref_key not in r.columns: return
        rq=r.loc[r[ref_key].astype(str).ne("")].copy()
        if rq.empty: return
        if only_unique:
            counts=rq.groupby(ref_key,dropna=False).size()
            keep=set(counts[counts==1].index.astype(str))
            rq=rq[rq[ref_key].astype(str).isin(keep)]
        else:
            rq=rq.drop_duplicates(ref_key,keep="last")
        if rq.empty: return
        rk=rq[ref_key].astype(str)
        maps={dst:pd.Series(rq[src].to_numpy(),index=rk).to_dict() for src,dst in target_cols.items() if src in rq.columns}
        keys=pd.Series(row_key,index=d.index).astype(str)
        miss=pd.to_numeric(d["__Raw_Fair_Anchor"],errors="coerce").isna()
        available=keys.isin(set(rk)) & miss
        if not available.any(): return
        for dst,mp in maps.items():
            vals=keys.map(mp)
            d.loc[available,dst]=vals.loc[available]
        ok=available & pd.to_numeric(d["__Raw_Fair_Anchor"],errors="coerce").notna()
        match_method[ok.to_numpy()]=label

    _fill_lookup(d["V13_Matchup_Key"],"V13_Matchup_Key","MATCHUP_KEY")
    if "Source_Game_ID" in d.columns and "Source_Game_ID" in r.columns:
        _fill_lookup(d["Source_Game_ID"].astype(str),"Source_Game_ID","SOURCE_GAME_ID")
    _fill_lookup(d["__PairDate"],"__PairDate","PAIR_DATE")

    # Last-resort date tolerance for UTC/date-boundary inconsistencies.  Use only a
    # unique physical team pair/date reference so this cannot choose between games.
    still=pd.to_numeric(d["__Raw_Fair_Anchor"],errors="coerce").isna()
    if still.any():
        for delta,label in ((-1,"PAIR_DATE_MINUS1"),(1,"PAIR_DATE_PLUS1")):
            alt_date=row_date+pd.to_timedelta(delta,unit="D")
            alt=pd.Series([
                f"{pair}|{dt.strftime('%Y-%m-%d') if pd.notna(dt) else ''}"
                for pair,dt in zip(d["__Pair"],alt_date)
            ],index=d.index)
            _fill_lookup(alt,"__PairDate",label,only_unique=True)

    anchor=_ncaaf_v13_norm_team_series(d["__Anchor_Team"])
    opp=_ncaaf_v13_norm_team_series(d["__Anchor_Opp"])
    outcome_src=d["Outcome_Norm"] if "Outcome_Norm" in d.columns else (d["Outcome"] if "Outcome" in d.columns else pd.Series("",index=d.index))
    outcome=_ncaaf_v13_norm_team_series(outcome_src)
    outcome=pd.Series(np.where(outcome.eq("home"),d["Home_Team_Norm"],np.where(outcome.eq("away"),d["Away_Team_Norm"],outcome)),index=d.index)
    side_sign=np.where(outcome.eq(anchor),1.0,np.where(outcome.eq(opp),-1.0,np.nan))
    raw_anchor=_num_col("__Raw_Fair_Anchor").to_numpy(dtype=float,na_value=np.nan)
    raw_side=raw_anchor*side_sign

    offered_spread=_num_col("Value")
    offered_margin=-offered_spread.to_numpy(dtype=float,na_value=np.nan)
    open_anchor=_num_col("__Open_Margin_Anchor").to_numpy(dtype=float,na_value=np.nan)
    offered_margin=np.where(np.isfinite(offered_margin),offered_margin,open_anchor*side_sign)
    gp=_num_col("__Context_Min_Games_Prior").to_numpy(dtype=float,na_value=np.nan)
    buckets=np.asarray([_ncaaf_v13_games_prior_bucket(v) for v in gp],dtype=object)
    row_season=_num_col("__Ref_Season","__Row_Season").to_numpy(dtype=float,na_value=np.nan)

    asof_betas=cal.get("asof_maturity_betas") or {}
    asof_pools=cal.get("asof_residual_pools") or {}
    beta=np.full(n,np.nan,dtype=float)
    for i,(sv,bk) in enumerate(zip(row_season,buckets)):
        if not np.isfinite(sv): continue
        rec=asof_betas.get(str(int(sv)),asof_betas.get(int(sv),{}))
        if isinstance(rec,dict):
            try: beta[i]=float(rec.get(str(bk),rec.get("UNKNOWN",np.nan)))
            except Exception: pass
    fallback_beta=float(fund.get("margin_edge_beta",0.0) or 0.0)
    beta=np.where(np.isfinite(beta),np.clip(beta,0.0,1.0),fallback_beta)
    trad_side=offered_margin+beta*(raw_side-offered_margin)
    threshold=offered_margin-trad_side

    for sv in sorted(set(int(v) for v in row_season[np.isfinite(row_season)])):
        rr=np.asarray(asof_pools.get(str(sv),asof_pools.get(sv,[])),dtype=float)
        rr=rr[np.isfinite(rr)]
        if len(rr)<100: continue
        sm=np.isfinite(row_season)&(row_season==float(sv))&np.isfinite(threshold)&np.isfinite(side_sign)
        pos=sm&(side_sign>0); neg=sm&(side_sign<0)
        if pos.any(): out[pos]=_ncaaf_v13_weighted_tail_probability(rr,threshold[pos],weights=None)[0]
        if neg.any(): out[neg]=_ncaaf_v13_weighted_tail_probability(-rr,threshold[neg],weights=None)[0]

    early_active=cal.get("early_active_by_season") or {}
    early=((bundle.get("stability_research") or {}).get("early_situational") or {})
    ef=early.get("oof_frame") if isinstance(early,dict) else None
    early_map={}
    if isinstance(ef,pd.DataFrame) and not ef.empty:
        for _,r0 in ef.iterrows():
            try: early_map[(int(float(r0.get("Season"))),str(r0.get("Source_Game_ID")),str(r0.get("Team_Norm")))] = float(r0.get("V13_Early_Situational_Prob_OOF"))
            except Exception: pass
    srcid=d["__Ref_Source_Game_ID"].astype(str) if "__Ref_Source_Game_ID" in d.columns else pd.Series("",index=d.index)
    for i in range(n):
        if buckets[i] != "FIRST_TWO_GAMES" or not np.isfinite(row_season[i]): continue
        sv=int(row_season[i]); is_active=bool(early_active.get(str(sv),early_active.get(sv,False)))
        if not is_active: continue
        ep=early_map.get((sv,str(srcid.iloc[i]),str(outcome.iloc[i])),np.nan)
        if np.isfinite(ep): out[i]=float(np.clip(ep,0.01,0.99))

    # Compatibility fallback to stored pre-overlay OOF probability when the richer
    # reconstruction metadata is unavailable.  Orientation remains explicit.
    ff=cal.get("oof_frame")
    if isinstance(ff,pd.DataFrame) and not ff.empty and "V13_PreOverlay_Prob_OOF" in ff.columns:
        fq=ff[[c for c in ("V13_Matchup_Key","Team_Norm","V13_PreOverlay_Prob_OOF","V13_Maturity_Bucket") if c in ff.columns]].copy()
        if "V13_Matchup_Key" in fq.columns and "Team_Norm" in fq.columns:
            fq=fq.rename(columns={"Team_Norm":"__Fallback_Anchor","V13_PreOverlay_Prob_OOF":"__Fallback_P"}).drop_duplicates("V13_Matchup_Key",keep="last")
            zz=d[["V13_Matchup_Key"]].merge(fq,on="V13_Matchup_Key",how="left")
            fa=_ncaaf_v13_norm_team_series(zz.get("__Fallback_Anchor",pd.Series("",index=zz.index)))
            fp=pd.to_numeric(zz.get("__Fallback_P"),errors="coerce").to_numpy(dtype=float,na_value=np.nan)
            sign=np.where(outcome.eq(fa),1.0,-1.0); fside=np.where(sign>0,fp,1.0-fp)
            miss=~np.isfinite(out)&np.isfinite(fside); out[miss]=fside[miss]

    diag["match_counts"]={str(k):int(v) for k,v in pd.Series(match_method).value_counts(dropna=False).to_dict().items()}
    diag["reference_match_rate"]=float(np.mean(match_method!="UNMATCHED")) if n else 0.0
    diag["probability_coverage"]=float(np.mean(np.isfinite(out))) if n else 0.0

    # Canonical game-union audit: historical/stat and market-rich sources are two
    # information layers for one physical game when their season+pair+date match.
    # Quote/snapshot multiplicity cannot increase sample size.
    try:
        _rich_keys=set()
        for sv,pdkey in zip(pd.to_numeric(d["__Row_Season"],errors="coerce"),d["__PairDate"].astype(str)):
            if np.isfinite(sv) and pdkey and not pdkey.endswith("|"):
                _rich_keys.add(f"{int(sv)}|{pdkey}")
        _ref_season=pd.to_numeric(r.get("Season"),errors="coerce") if "Season" in r.columns else pd.Series(np.nan,index=r.index)
        if _ref_season.isna().any():
            _drv=pd.Series([x.year if pd.notna(x) else np.nan for x in ref_date],index=r.index,dtype="float64")
            _ref_season=_ref_season.where(_ref_season.notna(),_drv)
        _hist_keys=set()
        for sv,pdkey in zip(_ref_season,r["__PairDate"].astype(str)):
            if np.isfinite(sv) and pdkey and not pdkey.endswith("|"):
                _hist_keys.add(f"{int(sv)}|{pdkey}")
        _overlap=_hist_keys&_rich_keys; _union=_hist_keys|_rich_keys
        _by={}
        for _key in _union:
            _yr=_key.split("|",1)[0]; _rec=_by.setdefault(_yr,{"history":0,"rich":0,"overlap":0,"unique":0})
            _rec["history"]+=int(_key in _hist_keys); _rec["rich"]+=int(_key in _rich_keys); _rec["overlap"]+=int(_key in _overlap); _rec["unique"]+=1
        diag["canonical_game_union"]={"history_unique":len(_hist_keys),"rich_unique":len(_rich_keys),"overlap":len(_overlap),"history_only":len(_hist_keys-_overlap),"rich_only":len(_rich_keys-_overlap),"unique_union":len(_union),"double_counted":0,"by_season":_by}
    except Exception as _e:
        diag["canonical_game_union"]={"error":str(_e),"double_counted":0}

    result=np.asarray(np.clip(out,0.01,0.99),dtype=float)
    return (result,buckets,diag) if return_diagnostics else (result,buckets)

def _ncaaf_v13_specialist_metrics(y,p,weights=None):
    from sklearn.metrics import roc_auc_score
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float)
    ww=np.ones(len(yy),dtype=float) if weights is None else np.asarray(weights,dtype=float)
    ok=np.isfinite(pp)&np.isfinite(ww)&(ww>0)
    if int(ok.sum())<20 or np.unique(yy[ok]).size<2:
        return {"n":int(ok.sum()),"auc":np.nan,"logloss":np.nan,"brier":np.nan,
                "ece":np.nan,"reliability":np.nan,"resolution":np.nan,"objective":np.inf}
    yy=yy[ok]; pp=np.clip(pp[ok],1e-6,1-1e-6); ww=ww[ok]
    ll=float(np.average(-(yy*np.log(pp)+(1-yy)*np.log(1-pp)),weights=ww))
    br=float(np.average((pp-yy)**2,weights=ww))
    auc=float(roc_auc_score(yy,pp,sample_weight=ww))
    total=float(np.sum(ww)); base=float(np.average(yy,weights=ww))
    ece=0.0; rel=0.0; res=0.0
    edges=np.linspace(0.0,1.0,11)
    for bi in range(10):
        hi=edges[bi+1]+(1e-12 if bi==9 else 0.0)
        bm=(pp>=edges[bi])&(pp<hi)
        if not bm.any(): continue
        wb=ww[bm]; mass=float(np.sum(wb))/max(total,1e-12)
        pbar=float(np.average(pp[bm],weights=wb)); ybar=float(np.average(yy[bm],weights=wb))
        ece += mass*abs(pbar-ybar)
        rel += mass*(pbar-ybar)**2
        res += mass*(ybar-base)**2
    return {"n":int(len(yy)),"auc":auc,"logloss":ll,"brier":br,
            "ece":float(ece),"reliability":float(rel),"resolution":float(res),
            "objective":ll+0.50*br}


def _ncaaf_v131_calibration_metrics(y,p,weights=None):
    """Calibration-detail wrapper; kept out of generic specialist hot loops."""
    met=dict(_ncaaf_v13_specialist_metrics(y,p,weights))
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float)
    ww=np.ones(len(yy),dtype=float) if weights is None else np.asarray(weights,dtype=float)
    ok=np.isfinite(pp)&np.isfinite(ww)&(ww>0)
    if int(ok.sum())<20 or np.unique(yy[ok]).size<2:
        met.update({"ici_smooth":np.nan,"calibration_intercept":np.nan,"calibration_slope":np.nan})
        return met
    yy=yy[ok]; pp=np.clip(pp[ok],1e-6,1-1e-6); ww=ww[ok]
    ici=np.nan
    try:
        order=np.argsort(pp); ps=pp[order]; ys=yy[order]; ws=ww[order]
        cw=np.cumsum(ws); tw=float(cw[-1]); nb=max(5,min(20,int(round(np.sqrt(max(25,len(ps)))))))
        cuts=np.linspace(0.0,tw,nb+1); xp=[]; yp=[]
        for j in range(nb):
            lo,hi=cuts[j],cuts[j+1]
            m=(cw>lo)&(cw<=hi if j<nb-1 else cw<=hi+1e-12)
            if int(m.sum())<2 or float(np.sum(ws[m]))<=0: continue
            xp.append(float(np.average(ps[m],weights=ws[m]))); yp.append(float(np.average(ys[m],weights=ws[m])))
        if len(xp)>=3:
            xp=np.asarray(xp,dtype=float); yp=np.asarray(yp,dtype=float); oo=np.argsort(xp); xp=xp[oo]; yp=yp[oo]
            cal=np.interp(pp,xp,yp,left=yp[0],right=yp[-1]); ici=float(np.average(np.abs(pp-cal),weights=ww))
    except Exception: pass
    intercept=slope=np.nan
    try:
        from sklearn.linear_model import LogisticRegression
        x=np.log(pp/(1.0-pp)).reshape(-1,1)
        mdl=LogisticRegression(C=1e6,solver="lbfgs",max_iter=1000).fit(x,yy,sample_weight=ww)
        intercept=float(mdl.intercept_[0]); slope=float(mdl.coef_[0,0])
    except Exception: pass
    met.update({"ici_smooth":float(ici) if np.isfinite(ici) else np.nan,
                "calibration_intercept":intercept,"calibration_slope":slope})
    return met

def _ncaaf_v13_game_balanced_weights(rows: pd.DataFrame, base_weights=None):
    """Equalize aggregate weight by physical game while preserving row reliability weights."""
    n=0 if rows is None else len(rows)
    if n==0:
        return np.asarray([],dtype=float),np.asarray([],dtype=object)
    if base_weights is None:
        w=np.ones(n,dtype=float)
    else:
        w=np.asarray(base_weights,dtype=float).reshape(-1)
        if len(w)!=n: w=np.ones(n,dtype=float)
    w=np.where(np.isfinite(w)&(w>0),w,0.0)
    if "Merge_Key_Short" in rows.columns:
        groups=rows["Merge_Key_Short"].astype(str).str.lower().str.strip().to_numpy(dtype=object)
    elif "Game_Key" in rows.columns:
        groups=rows["Game_Key"].astype(str).str.lower().str.strip().to_numpy(dtype=object)
    else:
        groups=np.asarray([f"row_{i}" for i in range(n)],dtype=object)
    counts=pd.Series(groups).groupby(pd.Series(groups),sort=False).transform("count").to_numpy(dtype=float)
    out=w/np.maximum(counts,1.0)
    if float(np.sum(out))>0 and float(np.sum(w))>0:
        out*=float(np.sum(w))/float(np.sum(out))
    return out,groups



def _ncaaf_v131_calibration_proper_noninferior(base: dict, cand: dict,
                                                   ll_tol: float = V13_CORE_CALIBRATION_MAX_LL_WORSEN,
                                                   brier_tol: float = V13_CORE_CALIBRATION_MAX_BRIER_WORSEN) -> bool:
    try:
        return bool(np.isfinite(cand.get("logloss",np.nan)) and np.isfinite(cand.get("brier",np.nan))
                    and cand["logloss"] <= float(base.get("logloss",np.inf)) + float(ll_tol)
                    and cand["brier"] <= float(base.get("brier",np.inf)) + float(brier_tol))
    except Exception: return False


def _ncaaf_v131_calibration_rank(m: dict):
    """Reliability-first rank after proper-score noninferiority has passed."""
    def f(v,default):
        try:
            x=float(v); return x if np.isfinite(x) else float(default)
        except Exception: return float(default)
    ici=f(m.get("ici_smooth"),f(m.get("ece"),9.0)); ece=f(m.get("ece"),9.0); rel=f(m.get("reliability"),9.0)
    slope=f(m.get("calibration_slope"),1.0); intercept=f(m.get("calibration_intercept"),0.0); obj=f(m.get("objective"),99.0)
    return (ici,ece,rel,abs(slope-1.0),abs(intercept),obj)


def _ncaaf_v131_calibration_is_better(base: dict, cand: dict, eps: float = 1e-6) -> bool:
    rb=_ncaaf_v131_calibration_rank(base); rc=_ncaaf_v131_calibration_rank(cand)
    for a,b in zip(rc,rb):
        if a < b-float(eps): return True
        if a > b+float(eps): return False
    return False


def _ncaaf_v13210_calibration_material_gain(base: dict, cand: dict) -> bool:
    """Require a real probability-quality gain, not merely a cosmetic map.

    Proper-score safety is handled separately.  This test lets a monotone
    calibrator correct severe under/over-confidence even when log loss/Brier move
    by only a few 1e-5 inside the explicit noninferiority budget.
    """
    def _f(d,k,default=np.nan):
        try:
            v=float((d or {}).get(k,default)); return v if np.isfinite(v) else float(default)
        except Exception:
            return float(default)
    ece_gain=_f(base,"ece")-_f(cand,"ece")
    ici_gain=_f(base,"ici_smooth")-_f(cand,"ici_smooth")
    rel_gain=_f(base,"reliability")-_f(cand,"reliability")
    bs=_f(base,"calibration_slope"); cs=_f(cand,"calibration_slope")
    slope_gain=(abs(bs-1.0)-abs(cs-1.0)) if np.isfinite(bs) and np.isfinite(cs) else -np.inf
    strict_proper=bool(
        _f(cand,"logloss",np.inf) <= _f(base,"logloss",np.inf)+1e-12 and
        _f(cand,"brier",np.inf) <= _f(base,"brier",np.inf)+1e-12
    )
    return bool(
        strict_proper or
        (np.isfinite(ece_gain) and ece_gain>=V13_CORE_CALIBRATION_MIN_ECE_GAIN) or
        (np.isfinite(ici_gain) and ici_gain>=V13_CORE_CALIBRATION_MIN_ICI_GAIN) or
        (np.isfinite(rel_gain) and rel_gain>=V13_CORE_CALIBRATION_MIN_RELIABILITY_GAIN) or
        (np.isfinite(slope_gain) and slope_gain>=V13_CORE_CALIBRATION_MIN_SLOPE_CLOSENESS_GAIN)
    )


def _ncaaf_v131_calibration_fold_support(base: dict, cand: dict) -> bool:
    if not _ncaaf_v131_calibration_proper_noninferior(base,cand): return False
    if not _ncaaf_v13_calibration_noninferior(base,cand,V13_CORE_CALIBRATION_MAX_ECE_INCREASE,V13_CORE_CALIBRATION_MAX_RELIABILITY_INCREASE): return False
    return bool(_ncaaf_v13210_calibration_material_gain(base,cand))


def _ncaaf_v131_calibration_gate(base: dict, cand: dict) -> bool:
    """V13.2.13 probability-calibration admission.

    The previous gate required *both* LogLoss and Brier to be exactly non-worse.
    That rejected a temperature map that cut ECE roughly in half while costing only
    a few millionths of proper score.  Calibration now uses the already-declared
    tiny noninferiority budget, requires a material reliability gain, and still
    leaves the untouched outer champion/promotion gate fully strict.
    """
    if not _ncaaf_v131_calibration_proper_noninferior(base,cand): return False
    if not _ncaaf_v13_calibration_noninferior(base,cand,V13_CORE_CALIBRATION_MAX_ECE_INCREASE,V13_CORE_CALIBRATION_MAX_RELIABILITY_INCREASE): return False
    return bool(_ncaaf_v13210_calibration_material_gain(base,cand))


def _ncaaf_v131_fit_calibration_params(method: str, p, y, weights=None):
    """Fit a compact probability calibrator and return pickle-safe parameters only."""
    method=str(method or "identity").lower().strip()
    pp=np.asarray(p,dtype=float).reshape(-1)
    yy=np.asarray(y,dtype=int).reshape(-1)
    ww=np.ones(len(yy),dtype=float) if weights is None else np.asarray(weights,dtype=float).reshape(-1)
    ok=np.isfinite(pp)&np.isfinite(ww)&(ww>0)
    if int(ok.sum())<V13_CORE_CALIBRATION_MIN_FIT_ROWS or np.unique(yy[ok]).size<2:
        return {"method":"identity"}
    pp=np.clip(pp[ok],1e-5,1-1e-5); yy=yy[ok]; ww=ww[ok]
    if method=="identity":
        return {"method":"identity"}
    if method=="temperature":
        base_met=_ncaaf_v131_calibration_metrics(yy,pp,ww); best_t=1.0; best_met=base_met
        for t in V13_CORE_CALIBRATION_T_GRID:
            cand=np.clip(_v13_sigmoid(_v13_logit(pp)/float(t)),0.01,0.99); met=_ncaaf_v131_calibration_metrics(yy,cand,ww)
            if _ncaaf_v131_calibration_gate(base_met,met) and _ncaaf_v131_calibration_rank(met)<_ncaaf_v131_calibration_rank(best_met):
                best_t=float(t); best_met=met
        return {"method":"temperature","temperature":best_t}
    try:
        from sklearn.linear_model import LogisticRegression
        if method=="platt":
            X=np.asarray(_v13_logit(pp),dtype=float).reshape(-1,1)
            mdl=LogisticRegression(C=0.50,solver="lbfgs",max_iter=2000,random_state=13101)
            mdl.fit(X,yy,sample_weight=ww)
            return {"method":"platt","intercept":float(mdl.intercept_[0]),"coef":[float(mdl.coef_[0,0])]}
        if method=="beta":
            X=np.column_stack([np.log(pp),-np.log1p(-pp)])
            mdl=LogisticRegression(C=0.50,solver="lbfgs",max_iter=2000,random_state=13102)
            mdl.fit(X,yy,sample_weight=ww)
            return {"method":"beta","intercept":float(mdl.intercept_[0]),
                    "coef":[float(mdl.coef_[0,0]),float(mdl.coef_[0,1])]}
    except Exception:
        return {"method":"identity"}
    return {"method":"identity"}


def _ncaaf_v131_apply_calibration_params(p, params: dict):
    """Apply V13.1 core calibration with exact side-complement symmetry.

    Platt/Beta are symmetrized as 0.5*(f(p) + 1-f(1-p)). This preserves
    f_sym(1-p)=1-f_sym(p), matching the canonical/inverse deployment contract.
    Identity is the fail-closed default.
    """
    pp=np.asarray(p,dtype=float).reshape(-1)
    out=pp.copy(); ok=np.isfinite(pp)
    if not ok.any(): return out
    rec=params if isinstance(params,dict) else {"method":"identity"}
    method=str(rec.get("method","identity") or "identity").lower().strip()

    def _raw_map(q):
        q=np.clip(np.asarray(q,dtype=float),1e-5,1-1e-5)
        if method=="temperature":
            t=max(float(rec.get("temperature",1.0) or 1.0),1e-6)
            return _v13_sigmoid(_v13_logit(q)/t)
        if method=="platt":
            c=list(rec.get("coef") or [1.0])
            return _v13_sigmoid(float(rec.get("intercept",0.0) or 0.0)+float(c[0])*_v13_logit(q))
        if method=="beta":
            c=list(rec.get("coef") or [1.0,1.0])
            if len(c)<2: c=[1.0,1.0]
            z=(float(rec.get("intercept",0.0) or 0.0)+float(c[0])*np.log(q)+float(c[1])*(-np.log1p(-q)))
            return _v13_sigmoid(z)
        return q

    q=np.clip(pp[ok],1e-5,1-1e-5)
    try:
        fq=np.asarray(_raw_map(q),dtype=float)
        if method in {"platt","beta"}:
            f_inv=np.asarray(_raw_map(1.0-q),dtype=float)
            fq=0.5*(fq+(1.0-f_inv))
        out[ok]=fq
    except Exception:
        out[ok]=q
    return np.clip(out,0.01,0.99)


def _ncaaf_v131_row_dates(rows: pd.DataFrame) -> pd.Series:
    """Best available pregame date for chronological calibration/weighting."""
    n=0 if rows is None else len(rows)
    if rows is None or n==0:
        return pd.Series(dtype="datetime64[ns, UTC]")
    for c in ("Game_Start","feat_Game_Start","Game_Date","Snapshot_Timestamp"):
        if c in rows.columns:
            z=pd.to_datetime(rows[c],errors="coerce",utc=True)
            if pd.Series(z).notna().any():
                return pd.Series(z,index=rows.index)
    return pd.Series(pd.NaT,index=rows.index,dtype="datetime64[ns, UTC]")


def _ncaaf_v131_calibration_specs():
    specs=[{"name":"identity_global","method":"identity","scope":"global"}]
    # V13.2.13 fixed-temperature candidates: the exact same T is applied to every
    # chronological validation fold.  This tests transportability of the map itself
    # instead of letting each fold independently choose an aggressive temperature.
    for t in V13_CORE_CALIBRATION_FIXED_T_GRID:
        tag=str(int(round(float(t)*100))).zfill(3)
        specs.append({"name":f"temperature_fixed{tag}","method":"temperature","scope":"global",
                      "fixed_temperature":float(t),"require_fold_stability":True})
    # Keep adaptive forms as challengers; they still must survive catastrophe and
    # the untouched later transfer lane before receiving production authority.
    for method in ("temperature","platt","beta"):
        specs.append({"name":f"{method}_global","method":method,"scope":"global"})
        for ng in V13_CORE_CALIBRATION_RECENT_GAME_WINDOWS:
            specs.append({"name":f"{method}_recent{int(ng)}","method":method,"scope":"recent","recent_games":int(ng)})
        for hl in V13_CORE_CALIBRATION_HALF_LIFE_DAYS:
            specs.append({"name":f"{method}_halflife{int(hl)}d","method":method,"scope":"halflife","half_life_days":float(hl)})
    return specs


def _ncaaf_v13213_calibration_params_for_spec(spec: dict, p, y, weights=None):
    """Return frozen params for a calibration spec without leaking validation rows.

    Fixed-temperature specs have no fitted parameter: the declared T is used
    unchanged in selection folds, the chronological transfer lane, and production.
    Other calibration forms retain the existing training-side fitting behavior.
    """
    rec=spec if isinstance(spec,dict) else {"method":"identity"}
    method=str(rec.get("method","identity") or "identity").lower().strip()
    if method=="temperature" and rec.get("fixed_temperature") is not None:
        try:
            t=float(rec.get("fixed_temperature"))
        except Exception:
            t=1.0
        if np.isfinite(t) and t>0:
            return {"method":"temperature","temperature":float(t),"fixed":True}
        return {"method":"identity"}
    if method=="identity":
        return {"method":"identity"}
    return _ncaaf_v131_fit_calibration_params(method,p,y,weights)


def _ncaaf_v131_calibration_fit_scope(idx, spec: dict, groups, dates: pd.Series, base_weights):
    """Apply only training-side scope restrictions; validation rows never influence scope."""
    idx=np.asarray(idx,dtype=int)
    if len(idx)==0:
        return idx,np.asarray([],dtype=float)
    scope=str((spec or {}).get("scope","global"))
    fit=idx.copy()
    if scope=="recent":
        ng=int((spec or {}).get("recent_games",0) or 0)
        if ng>0:
            g=np.asarray(groups,dtype=object)
            d=pd.to_datetime(pd.Series(dates),errors="coerce",utc=True)
            tmp=pd.DataFrame({"idx":fit,"grp":g[fit],"date":d.iloc[fit].to_numpy()})
            # Last observation is a deterministic fallback when date is missing.
            by=tmp.groupby("grp",sort=False).agg(date=("date","max"),last=("idx","max")).reset_index()
            by["date_ord"]=pd.to_datetime(by["date"],errors="coerce",utc=True)
            by=by.sort_values(["date_ord","last"],kind="stable",na_position="first")
            keep=set(by.tail(ng)["grp"].astype(str))
            fit=np.asarray([i for i in fit if str(g[i]) in keep],dtype=int)
    w=np.asarray(base_weights,dtype=float)[fit].copy()
    if scope=="halflife" and len(fit):
        hl=float((spec or {}).get("half_life_days",0.0) or 0.0)
        if hl>0:
            dd=pd.to_datetime(pd.Series(dates).iloc[fit],errors="coerce",utc=True)
            ref=dd.max()
            if pd.notna(ref):
                age=(ref-dd).dt.total_seconds().div(86400.0).clip(lower=0).fillna(0.0).to_numpy(dtype=float)
                w*=np.power(0.5,age/hl)
    return fit,w


def _ncaaf_v131_apply_core_calibration_bundle(p, art: dict, maturity=None):
    """Apply frozen global core calibration plus only validated maturity temperatures."""
    raw=np.asarray(p,dtype=float).reshape(-1)
    rec=(art or {}) if isinstance(art,dict) else {}
    out=_ncaaf_v131_apply_calibration_params(raw,rec.get("params") or {"method":"identity"})
    temps=rec.get("maturity_temperatures") or {}
    buckets=np.asarray(maturity if maturity is not None else ["UNKNOWN"]*len(out),dtype=object)
    if isinstance(temps,dict) and temps:
        for b,t in temps.items():
            try: tv=float(t)
            except Exception: continue
            if not np.isfinite(tv) or abs(tv-1.0)<1e-12: continue
            m=(buckets.astype(str)==str(b))&np.isfinite(out)
            if m.any(): out[m]=_ncaaf_v13_apply_temperature(out[m],tv)
    return np.clip(out,0.01,0.99)


def _ncaaf_v131_numeric_series(rows: pd.DataFrame, names, default=np.nan) -> pd.Series:
    n=0 if rows is None else len(rows)
    if rows is None:
        return pd.Series(dtype=float)
    for c in names:
        if c in rows.columns:
            z=pd.to_numeric(rows[c],errors="coerce")
            if isinstance(z,pd.Series): return z.reindex(rows.index)
    return pd.Series(default,index=rows.index,dtype=float)


def _ncaaf_v131_family_regime_labels(rows: pd.DataFrame, family: str, maturity=None):
    """Small, predeclared deployment-identifiable regimes; no result fields are used."""
    n=0 if rows is None else len(rows)
    if n==0: return np.asarray([],dtype=object)
    fam=str(family)
    mat=np.asarray(maturity if maturity is not None else ["UNKNOWN"]*n,dtype=object)
    if fam=="Fundamental":
        return mat.astype(object)

    spread=_ncaaf_v131_numeric_series(rows,("Value","Spread_Value","Current_Spread","Opening_Spread"))
    sv=spread.to_numpy(dtype=float,na_value=np.nan)
    a=np.abs(sv)
    key=np.zeros(n,dtype=bool)
    for k in (3.0,7.0,10.0,14.0): key |= np.isfinite(a)&(np.abs(a-k)<=0.75)
    # Explicit pregame key-state flags supplement spread proximity.
    for c in ("Crossed_Key_3","Crossed_Key_7","Crossed_Key_10","Crossed_Key_14",
              "Pathi_FB_Moved_Through_Key","Pathi_FB_Crossed_Key_Toward_Team","Pathi_FB_Crossed_Key_Away_From_Team",
              "Pathi_FB_Moved_Onto_Key","Pathi_FB_Moved_Off_Key"):
        if c in rows.columns:
            key |= pd.to_numeric(rows[c],errors="coerce").fillna(0).to_numpy(dtype=float)>0

    if fam=="Market":
        move=np.zeros(n,dtype=bool)
        for c in ("Line_Move_30m","Line_Move_60m","Line_Move_120m","Line_Move_Last30m","Line_Move_Last60m",
                  "Line_Move_From_Open","Sharp_Book_Move_30m","Sharp_Book_Move_60m","Sharp_Move_Before_Market",
                  "Sharp_Soft_Divergence","OddsMove_Magnitude","SharpMove_Magnitude"):
            if c in rows.columns:
                z=pd.to_numeric(rows[c],errors="coerce").fillna(0).to_numpy(dtype=float)
                move |= np.abs(z)>1e-6
        lab=np.full(n,"QUIET",dtype=object)
        lab[move]="ACTIVE_MOVE"; lab[key]="KEY_ZONE"; lab[key&move]="KEY_MOVE"
        return lab

    if fam=="Pathi":
        active=np.zeros(n,dtype=bool)
        for c in rows.columns:
            sl=str(c).lower()
            if not sl.startswith("pathi_"): continue
            if not any(tok in sl for tok in ("cross","key","hook","dog","favorite","role","protected","move")): continue
            z=pd.to_numeric(rows[c],errors="coerce")
            if isinstance(z,pd.Series): active |= z.fillna(0).abs().to_numpy(dtype=float)>1e-9
        lab=np.full(n,"OTHER",dtype=object); lab[active]="SYSTEM_ACTIVE"; lab[key]="KEY_NUMBER"
        return lab

    if fam=="BigAl":
        conf=np.zeros(n,dtype=bool)
        if "BigAl_Context_Conference_Home_Dog" in rows.columns:
            conf=pd.to_numeric(rows["BigAl_Context_Conference_Home_Dog"],errors="coerce").fillna(0).to_numpy(dtype=float)>0
        home=_ncaaf_v131_numeric_series(rows,("Is_Home","Is_Home_Team_Bet"),default=0).fillna(0).to_numpy(dtype=float)>0.5
        fav=_ncaaf_v131_numeric_series(rows,("Is_Favorite_Bet","Is_Favorite_Context"),default=np.nan).to_numpy(dtype=float,na_value=np.nan)
        isfav=np.where(np.isfinite(fav),fav>0.5,np.isfinite(sv)&(sv<0)); dog=np.isfinite(sv)&(sv>0)
        exact=np.zeros(n,dtype=bool)
        for c in BIGAL_EXACT_SIGNAL_COLS:
            if c in rows.columns:
                exact |= pd.to_numeric(rows[c],errors="coerce").fillna(0).abs().to_numpy(dtype=float)>1e-9
        lab=np.full(n,"OTHER",dtype=object)
        lab[isfav]="FAVORITE"; lab[dog&~home]="ROAD_DOG"; lab[dog&home]="HOME_DOG"; lab[conf]="CONFERENCE_HOME_DOG"; lab[exact]="SYSTEM_ACTIVE"
        return lab
    return np.full(n,"OTHER",dtype=object)

def _ncaaf_v131_fit_core_calibration(bundle: dict, train_rows: pd.DataFrame, y_train, core_oof,
                                      folds, shadow_folds=None, sample_weight=None, log_func=print):
    """V13.2.13 leakage-safe calibration with an actual chronological transfer lane.

    Candidate calibration is learned only from Core OOF predictions.  If the
    supplied specialist shadow has no finite Core OOF predictions (the V13.2.9
    failure mode), the latest available Core OOF fold is reserved as a transfer
    fold and is excluded from calibration recipe selection.  After transfer passes,
    the selected method is refit on all available pre-outer-holdout Core OOF rows
    for production.  The untouched outer champion holdout is never used to choose
    the calibrator.
    """
    y=np.asarray(y_train,dtype=int).reshape(-1); raw=np.asarray(core_oof,dtype=float).reshape(-1)
    if train_rows is None or len(y)!=len(train_rows) or len(raw)!=len(y):
        art={"version":V13_CORE_CALIBRATION_VERSION,"core_ready":False,"status":"ROW_ALIGNMENT_MISMATCH",
             "selected_method":"identity","active_method":"identity","selected_spec":"identity_global",
             "params":{"method":"identity"},"maturity_temperatures":{}}
        if isinstance(bundle,dict): bundle["core_calibration"]=art
        return bundle,raw

    sw,groups=_ncaaf_v13_game_balanced_weights(train_rows,sample_weight)
    dates=_ncaaf_v131_row_dates(train_rows).reset_index(drop=True)
    all_folds=list(folds or []); supplied_shadow=list(shadow_folds or [])
    all_selection_mask=np.zeros(len(y),dtype=bool); supplied_shadow_mask=np.zeros(len(y),dtype=bool)
    for _,va in all_folds: all_selection_mask[np.asarray(va,dtype=int)]=True
    for _,va in supplied_shadow: supplied_shadow_mask[np.asarray(va,dtype=int)]=True
    supplied_shadow_ok=supplied_shadow_mask&np.isfinite(raw)

    cal_folds=list(all_folds); cal_select_mask=all_selection_mask.copy(); cal_shadow_mask=supplied_shadow_mask.copy()
    transfer_source="SUPPLIED_SHADOW"
    if int(supplied_shadow_ok.sum()) < V13_CORE_CALIBRATION_TRANSFER_MIN_ROWS and len(all_folds)>=3:
        # Reserve the latest Core OOF validation fold.  This fixes the old shadow_n=0
        # path without creating new model predictions or touching the outer holdout.
        transfer_va=np.asarray(all_folds[-1][1],dtype=int)
        cal_folds=list(all_folds[:-1])
        cal_select_mask=np.zeros(len(y),dtype=bool)
        for _,va in cal_folds: cal_select_mask[np.asarray(va,dtype=int)]=True
        cal_shadow_mask=np.zeros(len(y),dtype=bool); cal_shadow_mask[transfer_va]=True
        transfer_source="LATEST_CORE_OOF_FOLD"

    select_ok=cal_select_mask&np.isfinite(raw); shadow_ok_mask=cal_shadow_mask&np.isfinite(raw)
    base_sel=_ncaaf_v131_calibration_metrics(y[select_ok],raw[select_ok],sw[select_ok])
    base_shadow=_ncaaf_v131_calibration_metrics(y[shadow_ok_mask],raw[shadow_ok_mask],sw[shadow_ok_mask])
    log_func(f"[V13.2.13-CAL-SPLIT] source={transfer_source} selection_rows={int(select_ok.sum())} transfer_rows={int(shadow_ok_mask.sum())} all_core_oof_rows={int((all_selection_mask&np.isfinite(raw)).sum())} outer_holdout_used=FALSE")

    if int(select_ok.sum())<V13_CORE_CALIBRATION_MIN_OOF_ROWS:
        art={"version":V13_CORE_CALIBRATION_VERSION,"core_ready":False,"status":"INSUFFICIENT_OOF",
             "selected_method":"identity","active_method":"identity","selected_spec":"identity_global",
             "params":{"method":"identity"},"maturity_temperatures":{},
             "selection_base_metrics":base_sel,"shadow_base_metrics":base_shadow,"transfer_source":transfer_source}
        bundle["core_calibration"]=art
        log_func(f"[V13.2.13-CORE-CAL] status=CLOSED reason=INSUFFICIENT_OOF rows={int(select_ok.sum())}")
        return bundle,raw

    specs=_ncaaf_v131_calibration_specs(); results={}
    for spec in specs:
        name=spec["name"]; method=spec["method"]
        pred=np.full(len(y),np.nan,dtype=float); prior=[]; records=[]
        _fixed_t=spec.get("fixed_temperature") if isinstance(spec,dict) else None
        _is_fixed=bool(method=="temperature" and _fixed_t is not None)
        _require_stability=bool((spec or {}).get("require_fold_stability",False))
        for fi,(_tr,va) in enumerate(cal_folds):
            va=np.asarray(va,dtype=int); v=va[np.isfinite(raw[va])]
            fit=np.asarray(prior,dtype=int); fit=fit[np.isfinite(raw[fit])] if len(fit) else np.asarray([],dtype=int)
            fit,wfit=_ncaaf_v131_calibration_fit_scope(fit,spec,groups,dates,sw)
            ready=(method=="identity") or _is_fixed or (len(fit)>=V13_CORE_CALIBRATION_MIN_FIT_ROWS and np.unique(y[fit]).size>=2)
            params=_ncaaf_v13213_calibration_params_for_spec(spec,raw[fit],y[fit],wfit) if ready else {"method":"identity"}
            if len(v):
                pred[v]=_ncaaf_v131_apply_calibration_params(raw[v],params)
                bm=_ncaaf_v131_calibration_metrics(y[v],raw[v],sw[v]); cm=_ncaaf_v131_calibration_metrics(y[v],pred[v],sw[v])
                records.append({"fold":int(fi),"n":int(cm["n"]),"fit_rows":int(len(fit)),"ready":bool(ready),"candidate":name,
                    "fixed_temperature":bool(_is_fixed),"temperature":float(_fixed_t) if _is_fixed else np.nan,
                    "ll_gain":float(bm["logloss"]-cm["logloss"]),"brier_gain":float(bm["brier"]-cm["brier"]),"ece_gain":float(bm["ece"]-cm["ece"]),
                    "ici_gain":float(bm.get("ici_smooth",np.nan)-cm.get("ici_smooth",np.nan)),
                    "reliability_gain":float(bm.get("reliability",np.nan)-cm.get("reliability",np.nan)),
                    "support":bool(_ncaaf_v131_calibration_fold_support(bm,cm))})
            prior.extend(va.tolist())
        ok=cal_select_mask&np.isfinite(raw)&np.isfinite(pred)
        met=_ncaaf_v131_calibration_metrics(y[ok],pred[ok],sw[ok])
        rr=[r for r in records if r["ready"] and r["n"]>=20 and (method=="identity" or r.get("fixed_temperature",False) or r["fit_rows"]>=V13_CORE_CALIBRATION_MIN_FIT_ROWS)]
        positive=sum(1 for r in rr if bool(r.get("support",False)))
        need=max(1,int(np.ceil(V13_CORE_CALIBRATION_MIN_POSITIVE_FOLD_FRAC*len(rr)))) if rr else 0
        catastrophic=any((r.get("ll_gain",0.0)<-V13_CORE_CALIBRATION_MAX_FOLD_LL_WORSEN or r.get("brier_gain",0.0)<-V13_CORE_CALIBRATION_MAX_FOLD_BRIER_WORSEN) for r in rr)
        fold_stability=bool((not _require_stability) or (len(rr)>=2 and positive>=need))
        # V13.2.13: fixed T must work consistently across chronological folds.
        # Adaptive maps retain the prior aggregate+catastrophe rule and still face
        # the completely later transfer fold. Identity always remains available.
        valid=(method=="identity") or bool(len(rr)>=2 and not catastrophic and fold_stability and _ncaaf_v131_calibration_gate(base_sel,met))
        results[name]={"spec":dict(spec),"oof":pred,"metrics":met,"fold_records":records,
                       "positive_folds":int(positive),"required_positive_folds":int(need),"catastrophic_fold":bool(catastrophic),
                       "fold_stability_pass":bool(fold_stability),"selection_gate_pass":bool(valid)}
        _ftxt=(f" fixed_T={float(_fixed_t):.2f}" if _is_fixed else "")
        log_func(f"[V13.2.13-CAL-CANDIDATE] name={name}{_ftxt} gate={'PASS' if valid else 'CLOSED'} n={met['n']} "
                 f"ll={met.get('logloss',np.nan):.6f} brier={met.get('brier',np.nan):.6f} ece={met.get('ece',np.nan):.4f} ici={met.get('ici_smooth',np.nan):.4f} "
                 f"rel={met.get('reliability',np.nan):.6f} slope={met.get('calibration_slope',np.nan):.3f} intercept={met.get('calibration_intercept',np.nan):+.3f} "
                 f"support_folds={positive}/{len(rr)} required={need} fold_stability={fold_stability} catastrophic={catastrophic} "
                 f"proper_budget={'PASS' if _ncaaf_v131_calibration_proper_noninferior(base_sel,met) else 'CLOSED'}")

    selected="identity_global"; selected_rec=results[selected]
    for name,rec in results.items():
        if name==selected or not rec.get("selection_gate_pass",False): continue
        if _ncaaf_v131_calibration_rank(rec["metrics"]) < _ncaaf_v131_calibration_rank(selected_rec["metrics"]):
            selected=name; selected_rec=rec

    selected_spec=selected_rec.get("spec") or {"name":"identity_global","method":"identity","scope":"global"}
    method=str(selected_spec.get("method","identity"))
    transfer_fit_idx=np.flatnonzero(select_ok)
    transfer_fit_idx,wfit=_ncaaf_v131_calibration_fit_scope(transfer_fit_idx,selected_spec,groups,dates,sw)
    transfer_params=_ncaaf_v13213_calibration_params_for_spec(selected_spec,raw[transfer_fit_idx],y[transfer_fit_idx],wfit)
    sh_pred=_ncaaf_v131_apply_calibration_params(raw[shadow_ok_mask],transfer_params) if shadow_ok_mask.any() else np.asarray([])
    sh_met=_ncaaf_v131_calibration_metrics(y[shadow_ok_mask],sh_pred,sw[shadow_ok_mask]) if shadow_ok_mask.any() else _ncaaf_v131_calibration_metrics([],[])
    _shadow_proper=bool(_ncaaf_v131_calibration_proper_noninferior(base_shadow,sh_met))
    _shadow_cal_ok=bool(_ncaaf_v13_calibration_noninferior(base_shadow,sh_met,V13_CORE_CALIBRATION_MAX_ECE_INCREASE,V13_CORE_CALIBRATION_MAX_RELIABILITY_INCREASE))
    _shadow_material=bool(_ncaaf_v13210_calibration_material_gain(base_shadow,sh_met))
    shadow_transfer=(method=="identity") or bool(sh_met.get("n",0)>=V13_CORE_CALIBRATION_TRANSFER_MIN_ROWS and _shadow_proper and _shadow_cal_ok and _shadow_material)

    try:
        _fd=dates.iloc[transfer_fit_idx] if len(transfer_fit_idx) else pd.Series([],dtype="datetime64[ns, UTC]")
        _fit_min=None if len(_fd)==0 or pd.isna(_fd.min()) else str(_fd.min()); _fit_max=None if len(_fd)==0 or pd.isna(_fd.max()) else str(_fd.max())
        _wf=np.asarray(wfit,dtype=float); _ess=float((_wf.sum()**2)/np.square(_wf).sum()) if len(_wf) and np.square(_wf).sum()>0 else 0.0
    except Exception:
        _fit_min=_fit_max=None; _ess=0.0
    log_func(
        f"[V13.2.13-CAL-TRANSFER] source={transfer_source} selected={selected} method={method} fit_rows={len(transfer_fit_idx)} ess={_ess:.1f} "
        f"fit_date_min={_fit_min} fit_date_max={_fit_max} params={transfer_params} "
        f"transfer_n={int(sh_met.get('n',0) or 0)} base_ll={base_shadow.get('logloss',np.nan):.6f} cand_ll={sh_met.get('logloss',np.nan):.6f} "
        f"base_br={base_shadow.get('brier',np.nan):.6f} cand_br={sh_met.get('brier',np.nan):.6f} "
        f"base_ece={base_shadow.get('ece',np.nan):.4f} cand_ece={sh_met.get('ece',np.nan):.4f} base_ici={base_shadow.get('ici_smooth',np.nan):.4f} cand_ici={sh_met.get('ici_smooth',np.nan):.4f} "
        f"material_gain={_shadow_material} transfer={'PASS' if shadow_transfer else 'CLOSED'}"
    )

    active_spec=selected_spec if shadow_transfer else {"name":"identity_global","method":"identity","scope":"global"}
    active_method=str(active_spec.get("method","identity"))
    # Refit the accepted calibration form on every available Core OOF selection row
    # for production.  The outer champion holdout remains untouched.
    production_fit_idx=np.flatnonzero(all_selection_mask&np.isfinite(raw))
    production_fit_idx,production_w=_ncaaf_v131_calibration_fit_scope(production_fit_idx,active_spec,groups,dates,sw)
    active_params=_ncaaf_v13213_calibration_params_for_spec(active_spec,raw[production_fit_idx],y[production_fit_idx],production_w)

    crossfit=np.asarray(raw,dtype=float).copy()
    if active_method!="identity":
        chosen_oof=np.asarray(selected_rec.get("oof"),dtype=float)
        use=cal_select_mask&np.isfinite(chosen_oof); crossfit[use]=chosen_oof[use]
        if shadow_ok_mask.any(): crossfit[shadow_ok_mask]=sh_pred

    # Optional maturity temperature remains a second-stage, forward-validated map.
    try:
        _,maturity,_diag=_ncaaf_v13_preoverlay_oof_for_rows(train_rows,bundle,return_diagnostics=True)
    except Exception:
        maturity=np.full(len(y),"UNKNOWN",dtype=object)
    maturity=np.asarray(maturity,dtype=object); maturity_temperatures={}; maturity_results={}
    for bucket in V13_FUNDAMENTAL_REGIMES:
        bmask=(maturity.astype(str)==str(bucket)); sel=cal_select_mask&bmask&np.isfinite(crossfit); sh=cal_shadow_mask&bmask&np.isfinite(crossfit)
        if int(sel.sum())<V13_CORE_MATURITY_CAL_MIN_FIT_ROWS or int(sh.sum())<V13_CORE_MATURITY_CAL_MIN_VALID_ROWS:
            maturity_results[bucket]={"gate_pass":False,"reason":"INSUFFICIENT_ROWS","selection_rows":int(sel.sum()),"shadow_rows":int(sh.sum())}; continue
        sel_idx=np.flatnonzero(sel); base_m=_ncaaf_v131_calibration_metrics(y[sel_idx],crossfit[sel_idx],sw[sel_idx]); best_t=1.0; best_m=base_m
        for temp in V13_CORE_CALIBRATION_T_GRID:
            pp=_ncaaf_v13_apply_temperature(crossfit[sel_idx],temp); mm=_ncaaf_v131_calibration_metrics(y[sel_idx],pp,sw[sel_idx])
            if _ncaaf_v131_calibration_gate(base_m,mm) and _ncaaf_v131_calibration_rank(mm)<_ncaaf_v131_calibration_rank(best_m): best_t=float(temp); best_m=mm
        sh_idx=np.flatnonzero(sh); sb=_ncaaf_v131_calibration_metrics(y[sh_idx],crossfit[sh_idx],sw[sh_idx]); sp=_ncaaf_v13_apply_temperature(crossfit[sh_idx],best_t); sf=_ncaaf_v131_calibration_metrics(y[sh_idx],sp,sw[sh_idx])
        gate=bool(best_t!=1.0 and _ncaaf_v131_calibration_gate(base_m,best_m) and _ncaaf_v131_calibration_gate(sb,sf))
        if gate: maturity_temperatures[bucket]=float(best_t); crossfit[sh_idx]=sp
        maturity_results[bucket]={"gate_pass":gate,"selected_temperature":float(best_t),"selection_rows":int(sel.sum()),"shadow_rows":int(sh.sum()),
            "selection_ll_gain":float(base_m.get('logloss',np.nan)-best_m.get('logloss',np.nan)),"selection_brier_gain":float(base_m.get('brier',np.nan)-best_m.get('brier',np.nan)),
            "shadow_ll_gain":float(sb.get('logloss',np.nan)-sf.get('logloss',np.nan)),"shadow_brier_gain":float(sb.get('brier',np.nan)-sf.get('brier',np.nan))}
        log_func(f"[V13.2.13-CAL-REGIME] bucket={bucket} gate={'PASS' if gate else 'CLOSED'} T={best_t:.3f} sel_ll={base_m.get('logloss',np.nan):.6f}->{best_m.get('logloss',np.nan):.6f} shadow_ll={sb.get('logloss',np.nan):.6f}->{sf.get('logloss',np.nan):.6f}")

    core_ready=bool(base_sel["n"]>=V13_CORE_CALIBRATION_MIN_OOF_ROWS and base_sel["auc"]>=V13_INTERNAL_CORE_MIN_AUC
                    and base_sel["logloss"]<=V13_INTERNAL_CORE_MAX_LOGLOSS and base_sel["brier"]<=V13_INTERNAL_CORE_MAX_BRIER)
    art={"version":V13_CORE_CALIBRATION_VERSION,"status":"READY" if core_ready else "CORE_SANITY_CLOSED","core_ready":core_ready,
         "selected_method":str(selected_spec.get("method","identity")),"active_method":active_method,"selected_spec":selected,
         "active_spec":str(active_spec.get("name","identity_global")),"calibration_active":bool(active_method!="identity" or maturity_temperatures),
         "params":active_params,"transfer_params":transfer_params,"transfer_source":transfer_source,
         "maturity_temperatures":maturity_temperatures,"maturity_results":maturity_results,
         "selection_base_metrics":base_sel,"selection_calibrated_metrics":selected_rec.get("metrics") or base_sel,
         "selection_method_results":{k:{kk:vv for kk,vv in r.items() if kk!="oof"} for k,r in results.items()},
         "shadow_base_metrics":base_shadow,"shadow_calibrated_metrics":sh_met,"shadow_transfer_pass":bool(shadow_transfer),
         "production_fit_rows":int(len(production_fit_idx)),"symmetry_contract":"EXACT_CANONICAL_INVERSE_COMPLEMENT",
         "contract":"CORE_OOF_ONLY__FIXED_T_CHRONOLOGICAL_STABILITY__LATEST_OOF_TRANSFER_FALLBACK__MATERIAL_CALIBRATION_GAIN_WITH_TINY_PROPER_NONINFERIORITY__PRODUCTION_REFIT_ALL_OOF__OUTER_HOLDOUT_UNTOUCHED"}
    bundle["core_calibration"]=art
    if isinstance(bundle.get("production_preview"),dict):
        bundle["production_preview"]["core_calibration_method"]=active_method; bundle["production_preview"]["core_calibration_active"]=bool(art["calibration_active"])
    _sm=(selected_rec.get('metrics') or {})
    log_func(f"[V13.2.13-CORE-CAL] core_ready={'PASS' if core_ready else 'CLOSED'} selected={selected} active={art['active_spec']} transfer_source={transfer_source} "
             f"selection_n={base_sel['n']} raw_auc={base_sel['auc']:.4f} raw_ll={base_sel['logloss']:.6f} raw_brier={base_sel['brier']:.6f} raw_ece={base_sel['ece']:.4f} raw_ici={base_sel.get('ici_smooth',np.nan):.4f} "
             f"cal_ll={_sm.get('logloss',np.nan):.6f} cal_brier={_sm.get('brier',np.nan):.6f} cal_ece={_sm.get('ece',np.nan):.4f} cal_ici={_sm.get('ici_smooth',np.nan):.4f} "
             f"cal_slope={_sm.get('calibration_slope',np.nan):.3f} cal_intercept={_sm.get('calibration_intercept',np.nan):+.3f} transfer={'PASS' if shadow_transfer else 'CLOSED'} "
             f"transfer_ece={sh_met.get('ece',np.nan):.4f} transfer_ici={sh_met.get('ici_smooth',np.nan):.4f} production_fit_rows={len(production_fit_idx)} maturity_active={maturity_temperatures}")
    return bundle,crossfit


def _v1312_apply_fundamental_residual(core,fund,mat,overlay):
    core=np.asarray(core,dtype=float); fund=np.asarray(fund,dtype=float); mat=np.asarray(mat,dtype=object); final=core.copy(); n=len(core)
    profiles=(overlay.get('residual_profiles') or {}) if isinstance(overlay,dict) else {}; center=float((overlay or {}).get('center_prob',0.5) or 0.5); sign,strength,_=_v1312_signal_components(fund,center)
    trust=np.zeros(n); edge=np.zeros(n); active=np.zeros(n,dtype=bool)
    for reg,pr in profiles.items():
        if not isinstance(pr,dict) or not pr.get('gate_pass',False): continue
        m=(mat.astype(str)==str(reg))&np.isfinite(core)&np.isfinite(fund)&(sign!=0)
        if not m.any(): continue
        sc=max(float(pr.get('strength_scale',1.0) or 1.0),0.05); tr=float(np.clip(pr.get('trust',0.0) or 0.0,0,1)); ed=float(max(0,pr.get('shrunk_edge',0.0) or 0.0)); ss=np.clip(strength[m]/sc,0,1.25)
        delta=sign[m]*np.minimum(V13_RESIDUAL_MAX_FAMILY_DELTA,ed*tr*ss); final[m]=np.clip(core[m]+delta,0.01,0.99); trust[m]=tr; edge[m]=ed; active[m]=True
    return final,{'gate_pass':bool(active.any()),'weight':trust,'active':active.astype(np.int8),'contribution':final-core,'fundamental_prob':fund,'center_prob':center,'regime':mat,'residual_edge':edge,'trust':trust}

def _ncaaf_v131_apply_fundamental_overlay(core_prob, fundamental_prob, overlay: dict, maturity=None):
    """Apply residual-qualified Fundamental expert; V13.1.1 weight route is fallback."""
    core=np.asarray(core_prob,dtype=float).reshape(-1); fund=np.asarray(fundamental_prob,dtype=float).reshape(-1)
    if len(fund)!=len(core): fund=np.full(len(core),np.nan,dtype=float)
    mat=np.asarray(maturity if maturity is not None else ["UNKNOWN"]*len(core),dtype=object)
    if isinstance(overlay,dict) and overlay.get('residual_gate_pass',False): return _v1312_apply_fundamental_residual(core,fund,mat,overlay)
    final=core.copy(); gate=bool(isinstance(overlay,dict) and overlay.get("gate_pass",False)); center=float(np.clip((overlay or {}).get("center_prob",0.5) or 0.5,0.01,0.99)) if isinstance(overlay,dict) else 0.5
    rw=(overlay or {}).get("regime_weights") or {} if isinstance(overlay,dict) else {}; legacy=float(np.clip((overlay or {}).get("weight",0.0) or 0.0,0.0,1.0)) if isinstance(overlay,dict) else 0.0; warr=np.zeros(len(core),dtype=float)
    if gate:
        if isinstance(rw,dict) and rw:
            for b,w in rw.items(): warr[mat.astype(str)==str(b)]=float(np.clip(w,0.0,1.0))
        else: warr[:]=legacy
    ok=np.isfinite(core)&np.isfinite(fund); active=ok&(warr>0)
    if active.any():
        ev=_v13_logit(fund[active])-float(_v13_logit([center])[0]); final[active]=_v13_sigmoid(_v13_logit(core[active])+warr[active]*ev)
    return np.clip(final,0.01,0.99),{"gate_pass":gate,"weight":np.where(ok,warr,0.0),"active":active.astype(np.int8),"contribution":np.asarray(final-core,dtype=float),"fundamental_prob":fund,"center_prob":center,"regime":mat}


def _ncaaf_v131_fit_fundamental_overlay(bundle: dict, train_rows: pd.DataFrame, y_train, core_crossfit,
                                         folds, shadow_folds=None, sample_weight=None, log_func=print):
    """Let Fundamental statistics earn maturity-specific rather than all-or-nothing authority."""
    y=np.asarray(y_train,dtype=int).reshape(-1); core=np.asarray(core_crossfit,dtype=float).reshape(-1)
    if train_rows is None or len(y)!=len(train_rows) or len(core)!=len(y):
        art={"version":V13_FUNDAMENTAL_OVERLAY_VERSION,"status":"ROW_ALIGNMENT_MISMATCH","gate_pass":False,"weight":0.0,"regime_weights":{},"center_prob":0.5}
        bundle["fundamental_overlay"]=art; return bundle,core
    sw,groups=_ncaaf_v13_game_balanced_weights(train_rows,sample_weight)
    fund,maturity,match_diag=_ncaaf_v13_preoverlay_oof_for_rows(train_rows,bundle,return_diagnostics=True); maturity=np.asarray(maturity,dtype=object)
    _cgu=(match_diag or {}).get("canonical_game_union") or {}
    if _cgu:
        _by=_cgu.get("by_season") or {}
        _bytxt=" | ".join(f"{yr}:hist={v.get('history',0)},rich={v.get('rich',0)},overlap={v.get('overlap',0)},unique={v.get('unique',0)}" for yr,v in sorted(_by.items()))
        log_func(f"[CANONICAL-GAME-MERGE:FIT-WINDOW] history_unique={_cgu.get('history_unique',0)} rich_unique={_cgu.get('rich_unique',0)} overlap={_cgu.get('overlap',0)} history_only={_cgu.get('history_only',0)} rich_only={_cgu.get('rich_only',0)} unique_union={_cgu.get('unique_union',0)} double_counted=0 by_season={_bytxt}")
    select_mask=np.zeros(len(y),dtype=bool); shadow_mask=np.zeros(len(y),dtype=bool)
    for _,va in list(folds or []): select_mask[np.asarray(va,dtype=int)]=True
    for _,va in list(shadow_folds or []): shadow_mask[np.asarray(va,dtype=int)]=True
    valid=np.isfinite(core)&np.isfinite(fund); sel=select_mask&valid
    if int(sel.sum())<V13_FUNDAMENTAL_MIN_OOF_ROWS:
        art={"version":V13_FUNDAMENTAL_OVERLAY_VERSION,"status":"INSUFFICIENT_OOF","gate_pass":False,"weight":0.0,"regime_weights":{},"center_prob":0.5,"selection_rows":int(sel.sum()),"match_diagnostics":match_diag}
        bundle["fundamental_overlay"]=art; log_func(f"[V13.1-FUNDAMENTAL] gate=CLOSED reason=INSUFFICIENT_OOF rows={int(sel.sum())}"); return bundle,core
    center=float(np.clip(np.average(fund[sel],weights=sw[sel]),0.05,0.95))
    regime_weights={}; regime_results={}; adjusted=core.copy()
    for regime in V13_FUNDAMENTAL_REGIMES:
        rmask=maturity.astype(str)==str(regime); rs=select_mask&valid&rmask; sh=shadow_mask&valid&rmask
        if int(rs.sum())<V13_REGIME_MIN_SELECTION_ROWS or int(sh.sum())<V13_REGIME_MIN_SHADOW_ROWS:
            regime_results[regime]={"gate_pass":False,"reason":"INSUFFICIENT_ROWS","selection_rows":int(rs.sum()),"shadow_rows":int(sh.sum())}; continue
        ridx=np.flatnonzero(rs); rb=_ncaaf_v13_specialist_metrics(y[ridx],core[ridx],sw[ridx]); best_w=0.0; best=rb
        for w in V13_FUNDAMENTAL_WEIGHT_GRID:
            pp=core[ridx].copy(); ev=_v13_logit(fund[ridx])-float(_v13_logit([center])[0]); pp=_v13_sigmoid(_v13_logit(pp)+float(w)*ev)
            mm=_ncaaf_v13_specialist_metrics(y[ridx],pp,sw[ridx])
            if (_ncaaf_v13_calibration_noninferior(rb,mm,V13_FUNDAMENTAL_MAX_ECE_INCREASE,V13_FUNDAMENTAL_MAX_RELIABILITY_INCREASE)
                and mm["logloss"]<=rb["logloss"]+1e-12 and mm["brier"]<=rb["brier"]+1e-12 and mm["objective"]<best["objective"]-1e-12): best_w=float(w); best=mm
        nested=np.full(len(y),np.nan); prior=[]; frec=[]
        for fi,(_tr,va) in enumerate(list(folds or [])):
            va=np.asarray(va,dtype=int); fit=np.asarray(prior,dtype=int)
            fit=fit[valid[fit]&rmask[fit]] if len(fit) else np.asarray([],dtype=int); local=0.0
            if len(fit)>=V13_REGIME_MIN_SELECTION_ROWS:
                bm=_ncaaf_v13_specialist_metrics(y[fit],core[fit],sw[fit]); chosen=bm
                for w in V13_FUNDAMENTAL_WEIGHT_GRID:
                    pp=_v13_sigmoid(_v13_logit(core[fit])+float(w)*(_v13_logit(fund[fit])-float(_v13_logit([center])[0])))
                    mm=_ncaaf_v13_specialist_metrics(y[fit],pp,sw[fit])
                    if (_ncaaf_v13_calibration_noninferior(bm,mm,V13_FUNDAMENTAL_MAX_ECE_INCREASE,V13_FUNDAMENTAL_MAX_RELIABILITY_INCREASE)
                        and mm["logloss"]<=bm["logloss"]+1e-12 and mm["brier"]<=bm["brier"]+1e-12 and mm["objective"]<chosen["objective"]-1e-12): local=float(w); chosen=mm
            vok=va[valid[va]&rmask[va]]
            if len(vok):
                pp=_v13_sigmoid(_v13_logit(core[vok])+local*(_v13_logit(fund[vok])-float(_v13_logit([center])[0]))); nested[vok]=pp
                bm=_ncaaf_v13_specialist_metrics(y[vok],core[vok],sw[vok]); mm=_ncaaf_v13_specialist_metrics(y[vok],pp,sw[vok]); frec.append({"fold":fi,"n":mm["n"],"weight":local,"ll_gain":bm["logloss"]-mm["logloss"],"brier_gain":bm["brier"]-mm["brier"]})
            prior.extend(va.tolist())
        nok=rs&np.isfinite(nested); nb=_ncaaf_v13_specialist_metrics(y[nok],core[nok],sw[nok]); nf=_ncaaf_v13_specialist_metrics(y[nok],nested[nok],sw[nok])
        elig=[r for r in frec if r["n"]>=V13_REGIME_MIN_FOLD_ROWS]; pos=sum(1 for r in elig if r["ll_gain"]>0 and r["brier_gain"]>0); need=max(1,int(np.ceil(V13_REGIME_MIN_POSITIVE_FOLD_FRAC*len(elig)))) if elig else 99
        rll=nb["logloss"]-nf["logloss"]; rbr=nb["brier"]-nf["brier"]
        sidx=np.flatnonzero(sh); sb=_ncaaf_v13_specialist_metrics(y[sidx],core[sidx],sw[sidx]); sp=_v13_sigmoid(_v13_logit(core[sidx])+best_w*(_v13_logit(fund[sidx])-float(_v13_logit([center])[0])))
        sf=_ncaaf_v13_specialist_metrics(y[sidx],sp,sw[sidx]); sll=sb["logloss"]-sf["logloss"]; sbr=sb["brier"]-sf["brier"]
        gate=bool(best_w>0 and len(elig)>=V13_REGIME_MIN_READY_FOLDS and pos>=need and rll>=V13_REGIME_MIN_LL_GAIN and rbr>=V13_REGIME_MIN_BRIER_GAIN
                  and sll>=0 and sbr>=0 and _ncaaf_v13_calibration_noninferior(nb,nf,V13_FUNDAMENTAL_MAX_ECE_INCREASE,V13_FUNDAMENTAL_MAX_RELIABILITY_INCREASE)
                  and _ncaaf_v13_calibration_noninferior(sb,sf,V13_FUNDAMENTAL_MAX_ECE_INCREASE,V13_FUNDAMENTAL_MAX_RELIABILITY_INCREASE))
        if gate:
            regime_weights[regime]=best_w; adjusted[nok]=nested[nok]; adjusted[sidx]=sp
        regime_results[regime]={"gate_pass":gate,"selected_weight":best_w,"selection_rows":int(rs.sum()),"shadow_rows":int(sh.sum()),"rolling_ll_gain":rll,"rolling_brier_gain":rbr,"positive_folds":pos,"required_positive_folds":need,"shadow_ll_gain":sll,"shadow_brier_gain":sbr,"fold_records":frec}
        log_func(f"[V13.1-FUNDAMENTAL-REGIME] regime={regime} gate={'PASS' if gate else 'CLOSED'} weight={best_w:.3f} rolling_ll_gain={rll:+.6f} rolling_brier_gain={rbr:+.6f} positive_folds={pos}/{len(elig)} required={need} shadow_ll_gain={sll:+.6f} shadow_brier_gain={sbr:+.6f}")
    # V13.1.2 residual qualification for the statistical/fundamental opinion. This
    # can discover a modest repeatable core miss even when one fixed logit weight
    # was too unstable to pass globally.
    residual_profiles={}; parent_mask=select_mask&valid; psign,pstrength,_=_v1312_signal_components(fund,center)
    parent_edge=_v1312_weighted_mean(psign[parent_mask]*(y[parent_mask]-core[parent_mask]),sw[parent_mask]) if parent_mask.any() else 0.0
    for regime in V13_FUNDAMENTAL_REGIMES:
        rm=maturity.astype(str)==str(regime); sm=select_mask&valid&rm&(psign!=0); shm=shadow_mask&valid&rm&(psign!=0); ng=_v1312_game_count(sm,groups); shg=_v1312_game_count(shm,groups)
        raw_edge=_v1312_weighted_mean(psign[sm]*(y[sm]-core[sm]),sw[sm]) if sm.any() else np.nan; shadow_edge=_v1312_weighted_mean(psign[shm]*(y[shm]-core[shm]),sw[shm]) if shm.any() else np.nan
        alpha=float(ng/(ng+V13_RESIDUAL_PRIOR_GAMES)) if ng else 0.0; shrunk=float(alpha*raw_edge+(1-alpha)*parent_edge) if np.isfinite(raw_edge) else 0.0; fre=[]
        for fi,(_tr,va) in enumerate(list(folds or [])):
            va=np.asarray(va,dtype=int); vm=va[valid[va]&rm[va]&(psign[va]!=0)]; vg=len(pd.unique(np.asarray(groups,dtype=object)[vm])) if len(vm) else 0; fe=_v1312_weighted_mean(psign[vm]*(y[vm]-core[vm]),sw[vm]) if len(vm) else np.nan
            if vg>=V13_RESIDUAL_MIN_FOLD_GAMES and np.isfinite(fe): fre.append({'fold':fi,'games':int(vg),'edge':float(fe)})
        pos=sum(1 for r in fre if r['edge']>0); need=max(1,int(np.ceil(V13_RESIDUAL_MIN_POSITIVE_FOLD_FRAC*len(fre)))) if fre else 99; frac=pos/len(fre) if fre else 0.0
        transfer_trust=float(np.clip(max(0.0,shadow_edge)/(max(abs(shrunk),0.005)),0.0,1.0)) if np.isfinite(shadow_edge) else 0.0
        trust=float(np.clip((0.45*min(1,ng/250)+0.35*frac+0.20*min(1,shg/75))*transfer_trust,0,1)); sc=max(float(np.nanmedian(pstrength[sm])) if sm.any() and np.isfinite(pstrength[sm]).any() else 1.0,0.05)
        gate=bool(ng>=V13_RESIDUAL_MIN_SELECTION_GAMES and shg>=V13_RESIDUAL_MIN_SHADOW_GAMES and len(fre)>=V13_REGIME_MIN_READY_FOLDS and pos>=need and shrunk>=V13_RESIDUAL_MIN_EDGE and np.isfinite(shadow_edge) and shadow_edge>=0)
        residual_profiles[regime]={'gate_pass':gate,'selection_games':ng,'shadow_games':shg,'raw_edge':float(raw_edge) if np.isfinite(raw_edge) else np.nan,'parent_edge':float(parent_edge),'shrunk_edge':max(0.0,float(shrunk)),'shadow_edge':float(shadow_edge) if np.isfinite(shadow_edge) else np.nan,'positive_folds':pos,'eligible_folds':len(fre),'required_positive_folds':need,'trust':trust if gate else 0.0,'strength_scale':sc,'fold_records':fre}
        log_func(f"[V13.1.2-FUNDAMENTAL-RESIDUAL] regime={regime} gate={'PASS' if gate else 'CLOSED'} games={ng} shadow_games={shg} shrunk_edge={shrunk:+.4f} shadow_edge={shadow_edge:+.4f} positive_folds={pos}/{len(fre)} trust={(trust if gate else 0.0):.3f}")
    residual_gate=any(r.get('gate_pass') for r in residual_profiles.values()); final=bool(regime_weights) or residual_gate; art={"version":V13_FUNDAMENTAL_OVERLAY_VERSION,"status":"PASS" if final else "GATE_CLOSED","gate_pass":final,
        "weight":max(regime_weights.values()) if regime_weights else 0.0,"regime_weights":regime_weights,"regime_results":regime_results,"residual_profiles":residual_profiles,"residual_gate_pass":residual_gate,"center_prob":center,"match_diagnostics":match_diag,
        "contract":"AUTOFS_CORE_PRIMARY__MATURITY_TRIGGER__CORE_RESIDUAL__PARTIAL_POOLING__TEMPORAL_TRUST__BOUNDED_STATISTICAL_CORRECTION"}
    if residual_gate: adjusted,_=_v1312_apply_fundamental_residual(core,fund,maturity,art)
    bundle["fundamental_overlay"]=art
    log_func(f"[V13.1.2-FUNDAMENTAL] gate={'PASS' if final else 'CLOSED'} legacy_active_regimes={regime_weights} residual_active_regimes={[k for k,v in residual_profiles.items() if v.get('gate_pass')]}")
    return bundle,adjusted



def _ncaaf_v131_apply_full_core(rows: pd.DataFrame, bundle: dict, core_prob, return_diagnostics=False):
    """Apply V13.1.2 global + maturity calibration, then maturity-qualified Fundamental overlay."""
    raw=np.asarray(core_prob,dtype=float).reshape(-1); cal_art=(bundle.get("core_calibration") or {}) if isinstance(bundle,dict) else {}
    fund,maturity,diag=_ncaaf_v13_preoverlay_oof_for_rows(rows,bundle,return_diagnostics=True)
    cal=_ncaaf_v131_apply_core_calibration_bundle(raw,cal_art,maturity=maturity)
    adj,finfo=_ncaaf_v131_apply_fundamental_overlay(cal,fund,(bundle.get("fundamental_overlay") or {}) if isinstance(bundle,dict) else {},maturity=maturity)
    info={"raw_core_prob":raw,"calibrated_core_prob":cal,"fundamental_prob":fund,"core_adjusted_prob":adj,"maturity":maturity,
          "match_diagnostics":diag,"fundamental_info":finfo,"core_calibration":cal_art}
    return (adj,info) if return_diagnostics else adj



def _ncaaf_v13_fit_weighted_estimator(model, X, y, weights=None):
    """Fit sklearn/XGB estimators while correctly routing sample weights through pipelines."""
    yy=np.asarray(y,dtype=int)
    ww=None if weights is None else np.asarray(weights,dtype=float)
    if ww is None:
        model.fit(X,yy)
        return model
    try:
        model.fit(X,yy,sample_weight=ww)
        return model
    except (TypeError,ValueError):
        pass
    # sklearn Pipeline requires <last_step>__sample_weight on versions without metadata routing.
    if hasattr(model,"steps") and getattr(model,"steps",None):
        last=str(model.steps[-1][0])
        model.fit(X,yy,**{f"{last}__sample_weight":ww})
    else:
        model.fit(X,yy)
    return model


def _ncaaf_v13_oof_for_estimator(model_proto, X: pd.DataFrame, y, folds, sample_weight=None):
    """OOF predictions for an arbitrary probability estimator; no validation row is fit on itself."""
    from sklearn.base import clone
    yy=np.asarray(y,dtype=int).reshape(-1)
    ww=np.ones(len(yy),dtype=float) if sample_weight is None else np.asarray(sample_weight,dtype=float).reshape(-1)
    out=np.full(len(yy),np.nan,dtype=float)
    for tr,va in list(folds or []):
        tr=np.asarray(tr,dtype=int); va=np.asarray(va,dtype=int)
        if len(tr)<50 or len(va)<20 or np.unique(yy[tr]).size<2:
            continue
        mdl=clone(model_proto)
        try:
            _ncaaf_v13_fit_weighted_estimator(mdl,X.iloc[tr],yy[tr],ww[tr])
            pp=np.asarray(mdl.predict_proba(X.iloc[va])[:,1],dtype=float)
            out[va]=np.clip(pp,0.01,0.99)
        except Exception:
            continue
    return out


def _ncaaf_v13_selection_stability_audit(model_proto, X: pd.DataFrame, y, folds, features,
                                           sample_weight=None, seed=131603):
    """Selection-only conditional permutation stability; shadow folds never choose features.

    One model is fit per chronological selection fold. Each feature is then permuted only
    inside that fold's validation rows. Positive objective_drop means prediction quality
    worsened when the feature was destroyed, i.e. the feature contributed conditional value.
    """
    from sklearn.base import clone
    feats=[str(c) for c in (features or []) if c in X.columns]
    yy=np.asarray(y,dtype=int).reshape(-1)
    ww=np.ones(len(yy),dtype=float) if sample_weight is None else np.asarray(sample_weight,dtype=float).reshape(-1)
    rec={f:[] for f in feats}; valid_folds=0
    rng=np.random.default_rng(int(seed))
    for fi,(tr,va) in enumerate(list(folds or [])):
        tr=np.asarray(tr,dtype=int); va=np.asarray(va,dtype=int)
        if len(tr)<100 or len(va)<30 or np.unique(yy[tr]).size<2 or np.unique(yy[va]).size<2:
            continue
        mdl=clone(model_proto)
        try:
            _ncaaf_v13_fit_weighted_estimator(mdl,X.iloc[tr][feats],yy[tr],ww[tr])
            p0=np.asarray(mdl.predict_proba(X.iloc[va][feats])[:,1],dtype=float)
            m0=_ncaaf_v13_specialist_metrics(yy[va],p0,ww[va])
            if not np.isfinite(m0.get("objective",np.nan)):
                continue
        except Exception:
            continue
        valid_folds+=1
        xv=X.iloc[va][feats].copy()
        for f in feats:
            try:
                xp=xv.copy()
                arr=xp[f].to_numpy(copy=True)
                xp[f]=arr[rng.permutation(len(arr))]
                pp=np.asarray(mdl.predict_proba(xp)[:,1],dtype=float)
                mp=_ncaaf_v13_specialist_metrics(yy[va],pp,ww[va])
                delta=float(mp["objective"]-m0["objective"]) if np.isfinite(mp.get("objective",np.nan)) else np.nan
            except Exception:
                delta=np.nan
            rec[f].append(delta)
    audit=[]; stable=[]
    for f in feats:
        vals=np.asarray(rec.get(f,[]),dtype=float)
        vals=vals[np.isfinite(vals)]
        pos=float(np.mean(vals>0.0)) if len(vals) else np.nan
        mean=float(np.mean(vals)) if len(vals) else np.nan
        ok=bool(len(vals)>=2 and np.isfinite(pos) and pos>=V13_SPECIALIST_STABILITY_MIN_POS_FRAC
                and np.isfinite(mean) and mean>V13_SPECIALIST_STABILITY_MIN_MEAN_OBJECTIVE_DROP)
        if ok: stable.append(f)
        audit.append({"feature":f,"valid_folds":int(len(vals)),"positive_fold_frac":pos,
                      "mean_objective_drop":mean,"stable":ok})
    audit.sort(key=lambda r:(not bool(r["stable"]),-(r["mean_objective_drop"] if np.isfinite(r["mean_objective_drop"]) else -1e9)))
    return stable,audit,int(valid_folds)


def _ncaaf_v13_specialist_model_competition(X: pd.DataFrame, y, folds, shadow_folds, features,
                                              xgb_proto, sample_weight=None, eval_mask=None,
                                              family="Specialist"):
    """Choose XGB vs regularized logistic using selection OOF only; shadow is evaluation-only."""
    from sklearn.pipeline import Pipeline
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import LogisticRegression
    from sklearn.base import clone
    yy=np.asarray(y,dtype=int).reshape(-1)
    ww=np.ones(len(yy),dtype=float) if sample_weight is None else np.asarray(sample_weight,dtype=float).reshape(-1)
    feats=[str(c) for c in (features or []) if c in X.columns]
    if not feats:
        return None
    Xm=X[feats].apply(pd.to_numeric,errors="coerce").replace([np.inf,-np.inf],np.nan).fillna(0.0).astype("float32")
    candidates=[("XGB",xgb_proto)]
    for C in V13_SPECIALIST_LOGISTIC_C_GRID:
        candidates.append((f"LOGISTIC_C{float(C):g}",Pipeline([
            ("scale",StandardScaler()),
            ("logit",LogisticRegression(C=float(C),solver="lbfgs",max_iter=2500,random_state=13160))
        ])))
    em=np.ones(len(yy),dtype=bool) if eval_mask is None else np.asarray(eval_mask,dtype=bool)
    records=[]; best=None
    for label,proto in candidates:
        po=_ncaaf_v13_oof_for_estimator(proto,Xm,yy,folds,ww)
        mask=em&np.isfinite(po)
        met=_ncaaf_v13_specialist_metrics(yy[mask],po[mask],ww[mask]) if mask.any() else _ncaaf_v13_specialist_metrics([],[])
        sel_score=(float(met.get("objective",np.inf))
                   +0.25*float(met.get("ece",np.inf))
                   +0.25*float(met.get("reliability",np.inf)))
        rec={"model":label,"metrics":met,"selection_score":sel_score,"oof":po,"proto":proto}
        records.append(rec)
        if np.isfinite(sel_score):
            if best is None or sel_score < best["selection_score"]-1e-9:
                best=rec
            elif best is not None and abs(sel_score-best["selection_score"])<=0.0005 and label.startswith("LOGISTIC") and not str(best["model"]).startswith("LOGISTIC"):
                # Stability-first tie break: prefer the lower-variance parametric specialist.
                best=rec
    if best is None:
        return None
    chosen_proto=best["proto"]
    pshadow=_ncaaf_v13_oof_for_estimator(chosen_proto,Xm,yy,shadow_folds,ww) if shadow_folds else np.full(len(yy),np.nan)
    final_model=clone(chosen_proto)
    _ncaaf_v13_fit_weighted_estimator(final_model,Xm,yy,ww)
    clean_records=[{"model":r["model"],"selection_score":float(r["selection_score"]),"metrics":r["metrics"]} for r in records]
    return {"model_name":best["model"],"model":final_model,"oof":best["oof"],"shadow_oof":pshadow,
            "metrics":best["metrics"],"competition":clean_records,"feature_cols":feats}


def _ncaaf_v13_apply_autofs_core_bridge(base_prob, core_prob, bridge: dict):
    """Apply only centered Outcome-AutoFS evidence to V13; identity when the bridge gate is closed."""
    base=np.asarray(base_prob,dtype=float); core=np.asarray(core_prob,dtype=float)
    if len(core)!=len(base): core=np.full(len(base),np.nan,dtype=float)
    if not isinstance(bridge,dict) or not bridge.get("gate_pass",False):
        return base,{"gate_pass":False,"weight":np.zeros(len(base)),"contribution":np.zeros(len(base)),"core_prob":core}
    center=float(np.clip(bridge.get("center_prob",0.5) or 0.5,0.01,0.99))
    weight=float(np.clip(bridge.get("weight",0.0) or 0.0,0.0,1.0))
    ok=np.isfinite(base)&np.isfinite(core)
    evidence=np.zeros(len(base),dtype=float)
    evidence[ok]=_v13_logit(np.clip(core[ok],0.01,0.99))-float(_v13_logit([center])[0])
    final=base.copy()
    final[ok]=_v13_sigmoid(_v13_logit(base[ok])+weight*evidence[ok])
    final=np.clip(final,0.01,0.99)
    return final,{"gate_pass":True,"weight":np.where(ok,weight,0.0),"contribution":final-base,"core_prob":core,"center_prob":center}


def _ncaaf_v13_fit_autofs_core_bridge(bundle: dict, train_rows: pd.DataFrame, y_train, core_oof,
                                       folds, shadow_folds=None, sample_weight=None, log_func=print):
    """Admit Outcome AutoFS as a resolution bridge only after nested proper-score + shadow stability."""
    if not isinstance(bundle,dict) or train_rows is None:
        return bundle,np.full(0,np.nan,dtype=float)
    y=np.asarray(y_train,dtype=int).reshape(-1); pc=np.asarray(core_oof,dtype=float).reshape(-1)
    if len(y)!=len(train_rows) or len(pc)!=len(y):
        bundle["autofs_core_bridge"]={"version":V13_AUTOFS_CORE_BRIDGE_VERSION,"gate_pass":False,"status":"ROW_ALIGNMENT_MISMATCH","weight":0.0,"center_prob":0.5}
        return bundle,np.full(len(y),np.nan,dtype=float)
    sw,groups=_ncaaf_v13_game_balanced_weights(train_rows,sample_weight)
    base,maturity,match_diag=_ncaaf_v13_preoverlay_oof_for_rows(train_rows,bundle,return_diagnostics=True)
    select_mask=np.zeros(len(y),dtype=bool); shadow_mask=np.zeros(len(y),dtype=bool)
    for _,va in list(folds or []): select_mask[np.asarray(va,dtype=int)]=True
    for _,va in list(shadow_folds or []): shadow_mask[np.asarray(va,dtype=int)]=True
    sel=select_mask&np.isfinite(base)&np.isfinite(pc)
    if int(sel.sum())<V13_AUTOFS_CORE_MIN_OOF_ROWS:
        art={"version":V13_AUTOFS_CORE_BRIDGE_VERSION,"gate_pass":False,"status":"INSUFFICIENT_OOF","weight":0.0,"center_prob":0.5,
             "selection_rows":int(sel.sum()),"match_diagnostics":match_diag}
        bundle["autofs_core_bridge"]=art
        log_func(f"[V13-AUTOFS-CORE] gate=CLOSED reason=INSUFFICIENT_OOF rows={int(sel.sum())}")
        return bundle,base
    center=float(np.average(np.clip(pc[sel],0.01,0.99),weights=sw[sel]))
    center=float(np.clip(center,0.05,0.95))

    def combine(idx,w,ctr=center):
        idx=np.asarray(idx,dtype=int)
        p0=base[idx]; cp=pc[idx]
        ok=np.isfinite(p0)&np.isfinite(cp)
        out=p0.copy()
        if np.any(ok) and float(w)>0:
            ev=_v13_logit(cp[ok])-float(_v13_logit([ctr])[0])
            out[ok]=_v13_sigmoid(_v13_logit(p0[ok])+float(w)*ev)
        return np.clip(out,0.01,0.99)

    # Deployment weight: learned from all selection OOF rows, then frozen for shadow.
    base_sel=_ncaaf_v13_specialist_metrics(y[sel],base[sel],sw[sel]); best_w=0.0; best_met=base_sel
    sel_idx=np.flatnonzero(sel)
    for w in V13_AUTOFS_CORE_WEIGHT_GRID:
        pred=combine(sel_idx,w)
        met=_ncaaf_v13_specialist_metrics(y[sel_idx],pred,sw[sel_idx])
        if (_ncaaf_v13_calibration_noninferior(base_sel,met,V13_AUTOFS_CORE_MAX_ECE_INCREASE,V13_AUTOFS_CORE_MAX_RELIABILITY_INCREASE)
            and met["logloss"]<=base_sel["logloss"]+1e-12 and met["brier"]<=base_sel["brier"]+1e-12
            and met["objective"]<best_met["objective"]):
            best_w=float(w); best_met=met

    # Nested rolling assessment: each validation block gets a weight learned only on prior blocks.
    second=np.full(len(y),np.nan,dtype=float); prior=[]; fold_records=[]
    for fi,(_tr,va) in enumerate(list(folds or [])):
        va=np.asarray(va,dtype=int); prior_idx=np.asarray(prior,dtype=int)
        chosen=0.0; local_center=center
        fit_idx=prior_idx[np.isfinite(base[prior_idx])&np.isfinite(pc[prior_idx])] if len(prior_idx) else np.asarray([],dtype=int)
        if len(fit_idx)>=250:
            local_center=float(np.clip(np.average(np.clip(pc[fit_idx],0.01,0.99),weights=sw[fit_idx]),0.05,0.95))
            bm=_ncaaf_v13_specialist_metrics(y[fit_idx],base[fit_idx],sw[fit_idx]); best=bm
            for w in V13_AUTOFS_CORE_WEIGHT_GRID:
                p0=base[fit_idx]; cp0=pc[fit_idx]
                ev=_v13_logit(cp0)-float(_v13_logit([local_center])[0])
                pred=np.clip(_v13_sigmoid(_v13_logit(p0)+float(w)*ev),0.01,0.99)
                mm=_ncaaf_v13_specialist_metrics(y[fit_idx],pred,sw[fit_idx])
                if (_ncaaf_v13_calibration_noninferior(bm,mm,V13_AUTOFS_CORE_MAX_ECE_INCREASE,V13_AUTOFS_CORE_MAX_RELIABILITY_INCREASE)
                    and mm["logloss"]<=bm["logloss"]+1e-12 and mm["brier"]<=bm["brier"]+1e-12 and mm["objective"]<best["objective"]):
                    chosen=float(w); best=mm
        vok=va[np.isfinite(base[va])&np.isfinite(pc[va])]
        if len(vok):
            ev=_v13_logit(pc[vok])-float(_v13_logit([local_center])[0])
            second[vok]=np.clip(_v13_sigmoid(_v13_logit(base[vok])+chosen*ev),0.01,0.99)
            bm=_ncaaf_v13_specialist_metrics(y[vok],base[vok],sw[vok]); mm=_ncaaf_v13_specialist_metrics(y[vok],second[vok],sw[vok])
            fold_records.append({"fold":fi,"n":mm["n"],"weight":chosen,
                                 "ll_gain":float(bm["logloss"]-mm["logloss"]),"brier_gain":float(bm["brier"]-mm["brier"])})
        prior.extend(va.tolist())
    sok=np.isfinite(second)&select_mask&np.isfinite(base)
    rb=_ncaaf_v13_specialist_metrics(y[sok],base[sok],sw[sok]); rf=_ncaaf_v13_specialist_metrics(y[sok],second[sok],sw[sok])
    rll=float(rb["logloss"]-rf["logloss"]) if np.isfinite(rf["logloss"]) else np.nan
    rbr=float(rb["brier"]-rf["brier"]) if np.isfinite(rf["brier"]) else np.nan
    eligible=[r for r in fold_records if r["n"]>=20 and np.isfinite(r["ll_gain"]) and np.isfinite(r["brier_gain"])]
    positive=sum(1 for r in eligible if r["ll_gain"]>0 and r["brier_gain"]>0)
    need=max(1,int(np.ceil(V13_AUTOFS_CORE_MIN_POSITIVE_FOLD_FRAC*len(eligible)))) if eligible else 99
    rolling_ok=bool(rf["n"]>=V13_AUTOFS_CORE_MIN_OOF_ROWS and rll>=V13_AUTOFS_CORE_MIN_LL_GAIN and rbr>=V13_AUTOFS_CORE_MIN_BRIER_GAIN
                    and _ncaaf_v13_calibration_noninferior(rb,rf,V13_AUTOFS_CORE_MAX_ECE_INCREASE,V13_AUTOFS_CORE_MAX_RELIABILITY_INCREASE)
                    and positive>=need)

    sh=shadow_mask&np.isfinite(base)&np.isfinite(pc)
    sb=_ncaaf_v13_specialist_metrics(y[sh],base[sh],sw[sh])
    if sh.any():
        sh_idx=np.flatnonzero(sh); sp=combine(sh_idx,best_w)
        sf=_ncaaf_v13_specialist_metrics(y[sh_idx],sp,sw[sh_idx])
    else:
        sf=_ncaaf_v13_specialist_metrics([],[])
    sll=float(sb["logloss"]-sf["logloss"]) if np.isfinite(sf["logloss"]) else np.nan
    sbr=float(sb["brier"]-sf["brier"]) if np.isfinite(sf["brier"]) else np.nan
    shadow_ok=bool(sf["n"]>=200 and sll>=V13_AUTOFS_CORE_MIN_LL_GAIN and sbr>=V13_AUTOFS_CORE_MIN_BRIER_GAIN
                   and _ncaaf_v13_calibration_noninferior(sb,sf,V13_AUTOFS_CORE_MAX_ECE_INCREASE,V13_AUTOFS_CORE_MAX_RELIABILITY_INCREASE))
    final=bool(best_w>0 and rolling_ok and shadow_ok)
    art={"version":V13_AUTOFS_CORE_BRIDGE_VERSION,"status":"PASS" if final else "GATE_CLOSED","gate_pass":final,
         "weight":float(best_w if final else 0.0),"selected_weight":float(best_w),"center_prob":center,
         "selection_base_metrics":base_sel,"selection_candidate_metrics":best_met,
         "rolling_base_metrics":rb,"rolling_final_metrics":rf,"rolling_ll_gain":rll,"rolling_brier_gain":rbr,
         "positive_folds":int(positive),"required_positive_folds":int(need),"fold_records":fold_records,"rolling_gate_pass":rolling_ok,
         "shadow_base_metrics":sb,"shadow_final_metrics":sf,"shadow_ll_gain":sll,"shadow_brier_gain":sbr,"shadow_gate_pass":shadow_ok,
         "selection_rows":int(sel.sum()),"shadow_rows":int(sh.sum()),"match_diagnostics":match_diag,
         "contract":"V13_BASE_PLUS_CENTERED_OUTCOME_AUTOFS_OOF__NESTED_ROLLING_WEIGHT__DISJOINT_SHADOW__PROPER_SCORE_CALIBRATION_GATE"}
    bundle["autofs_core_bridge"]=art
    if isinstance(bundle.get("production_preview"),dict):
        bundle["production_preview"]["autofs_core_bridge_gate_pass"]=final
        bundle["production_preview"]["autofs_core_bridge_weight"]=float(art["weight"])
        bundle["production_preview"]["autofs_core_bridge_center"]=float(center)
    adjusted,_=_ncaaf_v13_apply_autofs_core_bridge(base,pc,art)
    log_func(f"[V13-AUTOFS-CORE] gate={'PASS' if final else 'CLOSED'} selected_weight={best_w:.3f} active_weight={art['weight']:.3f} "
             f"selection_n={int(sel.sum())} rolling_n={rf['n']} rolling_ll_gain={rll:+.6f} rolling_brier_gain={rbr:+.6f} "
             f"positive_folds={positive}/{len(eligible)} required={need} shadow_n={sf['n']} shadow_ll_gain={sll:+.6f} shadow_brier_gain={sbr:+.6f} "
             f"center={center:.4f} match={match_diag.get('match_counts',{})}")
    return bundle,adjusted

def _ncaaf_v13_combine_specialist_probs(base_prob, family_probs: dict, weights: dict, regime_scales=None,
                                         maturity=None, centers=None, rows=None, regime_weights=None, regime_labels=None):
    """Centered logit specialist evidence with optional per-family regime weights."""
    p0=np.asarray(base_prob,dtype=float); z=_v13_logit(p0); centers=centers or {}; regime_scales=regime_scales or {}
    maturity=np.asarray(maturity if maturity is not None else ["UNKNOWN"]*len(p0),dtype=object)
    regime_weights=regime_weights or {}; regime_labels=regime_labels or {}
    for fam in ("Market","Pathi","BigAl"):
        center=float(np.clip(centers.get(fam,0.5) or 0.5,0.01,0.99)); pf=np.asarray(family_probs.get(fam,np.full(len(p0),center)),dtype=float); pf=np.where(np.isfinite(pf),pf,center)
        if isinstance(regime_weights,dict) and isinstance(regime_weights.get(fam),dict) and regime_weights.get(fam):
            labs=np.asarray(regime_labels.get(fam),dtype=object) if fam in regime_labels else _ncaaf_v131_family_regime_labels(rows,fam,maturity)
            warr=np.asarray([float((regime_weights.get(fam) or {}).get(str(x),0.0) or 0.0) for x in labs],dtype=float)
        else:
            w=float((weights or {}).get(fam,0.0) or 0.0); warr=np.full(len(p0),w,dtype=float)
            rs=regime_scales.get(fam,{}) if isinstance(regime_scales,dict) else {}
            if isinstance(rs,dict):
                early=np.isin(maturity,["FIRST_TWO_GAMES"]); warr[early]*=float(rs.get("FIRST_TWO_GAMES",1.0)); warr[~early]*=float(rs.get("MATURE",1.0))
        evidence=_v13_logit(pf)-float(_v13_logit([center])[0]); z=z+warr*evidence
    return np.clip(_v13_sigmoid(z),0.01,0.99)



def _v1312_weighted_mean(x,w):
    x=np.asarray(x,dtype=float); w=np.asarray(w,dtype=float); m=np.isfinite(x)&np.isfinite(w)&(w>0)
    return float(np.average(x[m],weights=w[m])) if m.any() else np.nan


def _v1312_game_count(mask, groups):
    m=np.asarray(mask,dtype=bool); g=np.asarray(groups,dtype=object)
    return int(len(pd.unique(g[m]))) if m.any() else 0


def _v1312_signal_components(prob, center):
    p=np.clip(np.asarray(prob,dtype=float),1e-5,1-1e-5); c=float(np.clip(center,1e-5,1-1e-5))
    ev=_v13_logit(p)-float(_v13_logit([c])[0]); sign=np.sign(ev); strength=np.abs(ev)
    return sign,strength,ev


def _v1312_apply_residual_engine(base_prob, family_probs, labels, centers, engine):
    """Apply shrunken residual edge only in admitted expert domains, with overlap discount."""
    base=np.asarray(base_prob,dtype=float).copy(); n=len(base); total=np.zeros(n,dtype=float); details={}; prev={}
    if not isinstance(engine,dict) or not engine.get('gate_pass',False): return base,details
    profiles=engine.get('profiles') or {}; corr=engine.get('pairwise_corr') or {}; seq=engine.get('sequence') or ['Market','BigAl','Pathi']
    fam_cap=float(engine.get('max_family_delta',V13_RESIDUAL_MAX_FAMILY_DELTA)); total_cap=float(engine.get('max_total_delta',V13_RESIDUAL_MAX_TOTAL_DELTA))
    for fam in seq:
        pf=np.asarray((family_probs or {}).get(fam,np.full(n,np.nan)),dtype=float); lab=np.asarray((labels or {}).get(fam,np.full(n,'OTHER',dtype=object)),dtype=object)
        center=float((centers or {}).get(fam,0.5) or 0.5); sign,strength,ev=_v1312_signal_components(pf,center)
        delta=np.zeros(n,dtype=float); trust=np.zeros(n,dtype=float); edge=np.zeros(n,dtype=float); indep=np.ones(n,dtype=float); active=np.zeros(n,dtype=bool)
        fprof=profiles.get(fam) or {}
        for reg,pr in fprof.items():
            if not isinstance(pr,dict) or not pr.get('gate_pass',False): continue
            m=(lab.astype(str)==str(reg))&np.isfinite(pf)&np.isfinite(base)&(sign!=0)
            if not m.any(): continue
            sc=max(float(pr.get('strength_scale',1.0) or 1.0),1e-4); ss=np.clip(strength[m]/sc,0.0,1.25)
            tr=float(np.clip(pr.get('trust',0.0) or 0.0,0,1)); ed=float(max(0.0,pr.get('shrunk_edge',0.0) or 0.0))
            raw=sign[m]*np.minimum(fam_cap,ed*tr*ss)
            ii=np.ones(np.sum(m),dtype=float)
            for prevfam,pd in prev.items():
                rho=float(max(0.0,(corr.get(fam,{}) or {}).get(prevfam,(corr.get(prevfam,{}) or {}).get(fam,0.0)) or 0.0))
                if rho<=V13_RESIDUAL_CORR_DISCOUNT_START: continue
                same=np.sign(raw)==np.sign(pd['delta'][m]); discount=min(V13_RESIDUAL_CORR_MAX_DISCOUNT,0.5*rho)
                ii[same]*=(1.0-discount)
            raw*=ii; delta[m]=raw; trust[m]=tr; edge[m]=ed; indep[m]=ii; active[m]=True
        proposed=np.clip(total+delta,-total_cap,total_cap); actual=proposed-total; total=proposed
        details[fam]={'contribution':actual,'trust':trust,'residual_edge':edge,'independence':indep,'active':active.astype(np.int8),'regime':lab,'prob':pf}
        prev[fam]={'delta':actual,'evidence':ev}
    final=np.clip(base+total,0.01,0.99)
    return final,details


def _v1312_fit_residual_specialist_engine(y,base,family_probs,family_shadow_probs,labels_by_family,centers,regime_weights,folds,select_mask,shadow_mask,sw,groups,log_func=print):
    """Turn validated named methodologies into shrunken conditional residual experts.

    HF2 fixes two important contracts:
      1) selection OOF probabilities are NEVER reused on later-shadow rows;
      2) passing experts are subset-tested on selection data, then the frozen best
         subset must independently improve the later shadow lane.  A bad companion
         expert therefore cannot automatically zero out a genuinely useful expert.
    """
    import itertools

    y=np.asarray(y,dtype=int); base=np.asarray(base,dtype=float); sw=np.asarray(sw,dtype=float); groups=np.asarray(groups,dtype=object)
    profiles={}; pair_inputs={}; seq=['Market','BigAl','Pathi']
    for fam in seq:
        pf=np.asarray(family_probs.get(fam,np.full(len(y),np.nan)),dtype=float)
        ps=np.asarray(family_shadow_probs.get(fam,np.full(len(y),np.nan)),dtype=float)
        labels=np.asarray(labels_by_family.get(fam,np.full(len(y),'OTHER',dtype=object)),dtype=object)
        center=float(centers.get(fam,0.5) or 0.5)
        sign,strength,ev=_v1312_signal_components(pf,center)
        ssign,sstrength,sev=_v1312_signal_components(ps,center)
        _allowed={
            "Market":{"ACTIVE_MOVE","KEY_ZONE","KEY_MOVE"},
            "Pathi":{"SYSTEM_ACTIVE","KEY_NUMBER"},
            "BigAl":{"SYSTEM_ACTIVE","FAVORITE","ROAD_DOG","HOME_DOG","CONFERENCE_HOME_DOG"},
        }.get(fam,set())
        admitted=[str(r) for r in pd.unique(labels) if str(r) in _allowed]
        profiles[fam]={}
        parent_mask=select_mask&np.isfinite(base)&np.isfinite(pf)&(sign!=0)&np.isin(labels.astype(str),admitted)
        parent_edge=_v1312_weighted_mean(sign[parent_mask]*(y[parent_mask]-base[parent_mask]),sw[parent_mask]) if parent_mask.any() else 0.0
        pair_inputs[fam]=(ev,labels,admitted)
        for reg in admitted:
            rm=labels.astype(str)==str(reg)
            sm=select_mask&rm&np.isfinite(base)&np.isfinite(pf)&(sign!=0)
            shm=shadow_mask&rm&np.isfinite(base)&np.isfinite(ps)&(ssign!=0)
            ng=_v1312_game_count(sm,groups); shg=_v1312_game_count(shm,groups)
            all_rg=_v1312_game_count(rm,groups)
            rg=_v1312_game_count(select_mask&rm&np.isfinite(base),groups); rshg=_v1312_game_count(shadow_mask&rm&np.isfinite(base),groups)
            raw_edge=_v1312_weighted_mean(sign[sm]*(y[sm]-base[sm]),sw[sm]) if sm.any() else np.nan
            shadow_edge=_v1312_weighted_mean(ssign[shm]*(y[shm]-base[shm]),sw[shm]) if shm.any() else np.nan
            alpha=float(ng/(ng+V13_RESIDUAL_PRIOR_GAMES)) if ng>0 else 0.0
            shrunk=float(alpha*raw_edge+(1-alpha)*parent_edge) if np.isfinite(raw_edge) else 0.0
            frec=[]
            for fi,(_tr,va) in enumerate(list(folds or [])):
                va=np.asarray(va,dtype=int)
                vm=va[rm[va]&np.isfinite(base[va])&np.isfinite(pf[va])&(sign[va]!=0)]
                vg=_v1312_game_count(np.isin(np.arange(len(y)),vm),groups) if len(vm) else 0
                fe=_v1312_weighted_mean(sign[vm]*(y[vm]-base[vm]),sw[vm]) if len(vm) else np.nan
                if vg>=V13_RESIDUAL_MIN_FOLD_GAMES and np.isfinite(fe):
                    frec.append({'fold':fi,'games':vg,'edge':fe})
            pos=sum(1 for r in frec if r['edge']>0)
            need=max(1,int(np.ceil(V13_RESIDUAL_MIN_POSITIVE_FOLD_FRAC*len(frec)))) if frec else 99
            frac=(pos/len(frec)) if frec else 0.0
            sample_trust=min(1.0,ng/250.0); shadow_sample=min(1.0,shg/75.0)
            transfer_trust=float(np.clip(max(0.0,shadow_edge)/(max(abs(shrunk),0.005)),0.0,1.0)) if np.isfinite(shadow_edge) else 0.0
            trust=float(np.clip((0.45*sample_trust+0.35*frac+0.20*shadow_sample)*transfer_trust,0,1))
            sc=float(np.nanmedian(strength[sm])) if sm.any() and np.isfinite(strength[sm]).any() else 1.0; sc=max(sc,0.05)
            gate=bool(
                ng>=V13_RESIDUAL_MIN_SELECTION_GAMES
                and shg>=V13_RESIDUAL_MIN_SHADOW_GAMES
                and len(frec)>=V13_REGIME_MIN_READY_FOLDS
                and pos>=need
                and np.isfinite(shrunk) and shrunk>=V13_RESIDUAL_MIN_EDGE
                and np.isfinite(shadow_edge) and shadow_edge>=0
            )
            profiles[fam][str(reg)]={
                'gate_pass':gate,'selection_games':ng,'shadow_games':shg,'all_regime_games':all_rg,'regime_selection_games':rg,'regime_shadow_games':rshg,
                'raw_edge':float(raw_edge) if np.isfinite(raw_edge) else np.nan,
                'parent_edge':float(parent_edge) if np.isfinite(parent_edge) else 0.0,
                'shrunk_edge':float(max(0,shrunk)),
                'shadow_edge':float(shadow_edge) if np.isfinite(shadow_edge) else np.nan,
                'positive_folds':pos,'eligible_folds':len(frec),'required_positive_folds':need,
                'trust':trust if gate else 0.0,'strength_scale':sc,'fold_records':frec
            }
            log_func(
                f"[V13.1.2-RESIDUAL-EXPERT] family={fam} regime={reg} gate={'PASS' if gate else 'CLOSED'} "
                f"all_history_regime_games={all_rg} selection_regime_games={rg} selection_signal_games={ng} shadow_regime_games={rshg} shadow_signal_games={shg} raw_edge={raw_edge:+.4f} parent_edge={parent_edge:+.4f} "
                f"shrunk_edge={shrunk:+.4f} shadow_edge={shadow_edge:+.4f} positive_folds={pos}/{len(frec)} "
                f"trust={(trust if gate else 0.0):.3f}"
            )

    # Correlation is estimated only on selection OOF evidence.
    corr={f:{} for f in seq}
    for i,a in enumerate(seq):
        eva,laba,ra=pair_inputs.get(a,(None,None,[]))
        if eva is None: continue
        ma=select_mask&np.isfinite(eva)&np.isin(laba.astype(str),[str(x) for x in ra])
        for b in seq[:i]:
            evb,labb,rb=pair_inputs.get(b,(None,None,[]))
            mb=select_mask&np.isfinite(evb)&np.isin(labb.astype(str),[str(x) for x in rb]) if evb is not None else np.zeros(len(y),bool)
            m=ma&mb
            rho=float(np.corrcoef(eva[m],evb[m])[0,1]) if int(m.sum())>=50 and np.nanstd(eva[m])>1e-9 and np.nanstd(evb[m])>1e-9 else 0.0
            corr[a][b]=rho; corr[b][a]=rho

    eligible_families=[fam for fam in seq if any(isinstance(pr,dict) and pr.get('gate_pass',False) for pr in (profiles.get(fam) or {}).values())]
    base_engine={
        'version':V13_RESIDUAL_EXPERT_VERSION,'gate_pass':bool(eligible_families),
        'profiles':profiles,'pairwise_corr':corr,'sequence':list(eligible_families),
        'max_family_delta':V13_RESIDUAL_MAX_FAMILY_DELTA,'max_total_delta':V13_RESIDUAL_MAX_TOTAL_DELTA,
        'contract':'TRIGGER__CORE_RESIDUAL__PARTIAL_POOLING__TEMPORAL_TRUST__CORRELATION_DISCOUNT__BOUNDED_DELTA__SUBSET_SELECTION__DISJOINT_SHADOW'
    }

    # Selection-only subset search.  With three expert families there are at most
    # seven non-empty subsets, so this is transparent and cheap.  We deliberately
    # do NOT choose the subset on the shadow period; shadow is validation only.
    subset_records=[]
    select_eval=select_mask&np.isfinite(base)
    base_sel=_ncaaf_v13_specialist_metrics(y[select_eval],base[select_eval],sw[select_eval])
    best_subset=()
    best_obj=float(base_sel.get('objective',np.inf))
    best_sel_metrics=base_sel
    best_sel_pred=np.asarray(base,dtype=float).copy()
    best_sel_details={}

    for r in range(1,len(eligible_families)+1):
        for subset in itertools.combinations(eligible_families,r):
            cand=dict(base_engine); cand['gate_pass']=True; cand['sequence']=list(subset)
            psel,dsel=_v1312_apply_residual_engine(base,family_probs,labels_by_family,centers,cand)
            sm=select_eval&np.isfinite(psel)
            fm=_ncaaf_v13_specialist_metrics(y[sm],psel[sm],sw[sm])
            bm=_ncaaf_v13_specialist_metrics(y[sm],base[sm],sw[sm])
            llg=bm['logloss']-fm['logloss']; brg=bm['brier']-fm['brier']
            obj=float(fm.get('objective',np.inf))
            eligible=bool(np.isfinite(obj) and llg>=0 and brg>=0)
            rec={'subset':list(subset),'selection_n':int(fm.get('n',0)),'selection_ll_gain':float(llg),'selection_brier_gain':float(brg),'objective':obj,'selection_pass':eligible}
            subset_records.append(rec)
            log_func(f"[V13.1.2-RESIDUAL-SUBSET] subset={'+'.join(subset)} selection_pass={eligible} selection_n={rec['selection_n']} ll_gain={llg:+.6f} brier_gain={brg:+.6f} objective={obj:.6f}")
            # Prefer the best proper-score objective. If effectively tied, prefer
            # the simpler subset so one marginal expert cannot add needless variance.
            if eligible:
                materially_better=(obj < best_obj-1e-6)
                tied_simpler=(abs(obj-best_obj)<=1e-6 and (not best_subset or len(subset)<len(best_subset)))
                if materially_better or tied_simpler:
                    best_subset=tuple(subset); best_obj=obj; best_sel_metrics=fm; best_sel_pred=psel; best_sel_details=dsel

    engine=dict(base_engine)
    engine['subset_records']=subset_records
    engine['selected_families']=list(best_subset)
    engine['sequence']=list(best_subset)
    engine['selection_metrics']=best_sel_metrics
    engine['selection_ll_gain']=float(base_sel['logloss']-best_sel_metrics['logloss']) if best_subset else 0.0
    engine['selection_brier_gain']=float(base_sel['brier']-best_sel_metrics['brier']) if best_subset else 0.0

    # True disjoint later-shadow evaluation: use family_shadow_probs, never the
    # selection OOF arrays. This fixes the prior artificial +0.000000 shadow result.
    shadow_eval=shadow_mask&np.isfinite(base)
    base_sh=_ncaaf_v13_specialist_metrics(y[shadow_eval],base[shadow_eval],sw[shadow_eval])
    if best_subset:
        frozen=dict(engine); frozen['gate_pass']=True
        pshadow,dshadow=_v1312_apply_residual_engine(base,family_shadow_probs,labels_by_family,centers,frozen)
        sh=shadow_eval&np.isfinite(pshadow)
        sf=_ncaaf_v13_specialist_metrics(y[sh],pshadow[sh],sw[sh])
        sb=_ncaaf_v13_specialist_metrics(y[sh],base[sh],sw[sh])
        sh_ll=float(sb['logloss']-sf['logloss']); sh_br=float(sb['brier']-sf['brier'])
    else:
        pshadow=np.asarray(base,dtype=float).copy(); dshadow={}; sf=base_sh; sh_ll=0.0; sh_br=0.0

    engine['shadow_metrics']=sf
    engine['shadow_ll_gain']=sh_ll
    engine['shadow_brier_gain']=sh_br
    engine['gate_pass']=bool(
        best_subset
        and engine['selection_ll_gain']>=0
        and engine['selection_brier_gain']>=0
        and sh_ll>=0
        and sh_br>=0
    )
    if not engine['gate_pass']:
        engine['selected_families']=[]
        engine['sequence']=[]

    log_func(
        f"[V13.1.2-RESIDUAL-COMBINE] gate={'PASS' if engine['gate_pass'] else 'CLOSED'} "
        f"selected={'+'.join(best_subset) if best_subset else 'CORE_ONLY'} "
        f"selection_ll_gain={engine['selection_ll_gain']:+.6f} selection_brier_gain={engine['selection_brier_gain']:+.6f} "
        f"shadow_ll_gain={engine['shadow_ll_gain']:+.6f} shadow_brier_gain={engine['shadow_brier_gain']:+.6f} corr={corr}"
    )
    return engine


def _v132_rule_side_groups(rows: pd.DataFrame) -> np.ndarray:
    n=0 if rows is None else len(rows)
    if n==0: return np.asarray([],dtype=object)
    game=None
    for c in ("Game_Key","Merge_Key_Short","_SOURCE_ROW_ID"):
        if c in rows.columns:
            game=rows[c].astype(str).str.lower().str.strip(); break
    if game is None: game=pd.Series([f"row{i}" for i in range(n)],index=rows.index)
    side=None
    for c in ("Outcome_Norm","Outcome","Team_Norm","Team"):
        if c in rows.columns:
            side=rows[c].astype(str).str.lower().str.strip(); break
    if side is None: side=pd.Series("side",index=rows.index)
    return (game.astype(str)+"|"+side.astype(str)).to_numpy(dtype=object)


def _v132_rule_balanced_weights(rows: pd.DataFrame, sample_weight=None) -> np.ndarray:
    n=len(rows); w=np.ones(n,dtype=float) if sample_weight is None else np.asarray(sample_weight,dtype=float).reshape(-1)
    if len(w)!=n: w=np.ones(n,dtype=float)
    g=_v132_rule_side_groups(rows); cnt=pd.Series(g).groupby(pd.Series(g),sort=False).transform("count").to_numpy(dtype=float)
    out=w/np.maximum(cnt,1.0); a=float(np.nansum(w)); b=float(np.nansum(out))
    if a>0 and b>0: out*=a/b
    out[~np.isfinite(out)]=0.0
    return out


def _v132_prepare_rule_rows(rows: pd.DataFrame, log_func=None) -> pd.DataFrame:
    """Rebuild only rules whose exact pregame inputs are available at this row grain.

    V13.2.2 exposed a fail-open problem: calling the full Big Al feature builder on
    repeated market rows could raise late in unrelated consensus logic (for example
    when ``Opponent`` was absent).  Because the function never returned, stale
    stored rule flags survived silently.  V13.2.3 therefore:
      * rebuilds Pathi football key features normally;
      * repairs same-game opponent aliases when both sides are available; and
      * selectively recomputes each NCAAF Big Al rule only on rows where every
        exact rule input is present, preserving an upstream stored flag otherwise.
    """
    if rows is None or rows.empty:
        return rows.copy() if rows is not None else rows
    out=rows.copy()

    def _num(c):
        if c in out.columns:
            return pd.to_numeric(out[c],errors="coerce")
        return pd.Series(np.nan,index=out.index,dtype="float64")

    try:
        out=add_pathi_football_key_features(out)
    except Exception as e:
        if log_func:
            log_func(f"[V13.2-RULE-ROW-REBUILD] Pathi rebuild unavailable: {e}")

    # Same-game opponent mirrors. Do not reconstruct chronology from repeated quote
    # rows; Prev_* and revenge fields are already pregame state at this grain.
    try:
        game_col=next((c for c in ("Game_Key","Merge_Key_Short") if c in out.columns),None)
        team_col=next((c for c in ("Outcome_Norm","Outcome","Team_Norm","Team") if c in out.columns),None)
        opp_col=next((c for c in ("Opponent_Norm","Opponent") if c in out.columns),None)
        if game_col and team_col and opp_col:
            g=out[game_col].astype(str).str.lower().str.strip()
            team=_hc_team_token(out[team_col]); opp=_hc_team_token(out[opp_col])
            mirror=pd.DataFrame({
                "__g":g,"__team":team,
                "__rev":_num("Revenge_Flag_Current"),
                "__rev_recent":_num("Revenge_Flag_CurrentOrPriorSeason"),
                "__ps":_num("Prev_Spread_Value"),
                "__pl":_num("Prev_SU_Loss"),
            })
            mirror=mirror.drop_duplicates(["__g","__team"],keep="last")
            q=pd.DataFrame({"__g":g,"__team":opp},index=out.index)
            got=q.merge(mirror,on=["__g","__team"],how="left",sort=False); got.index=out.index
            for dst,src in (
                ("Opp_Revenge_Flag_Current","__rev"),
                ("Opp_Revenge_Flag_CurrentOrPriorSeason","__rev_recent"),
                ("Opp_Prev_Spread_Value","__ps"),
                ("Opp_Prev_SU_Loss","__pl"),
            ):
                cur=_num(dst)
                out[dst]=cur.where(cur.notna(),pd.to_numeric(got[src],errors="coerce"))
    except Exception as e:
        if log_func:
            log_func(f"[V13.2-RULE-ROW-REBUILD] opponent mirror unavailable: {e}")

    # Re-create helper after opponent fields may have been added.
    def _n(c):
        if c in out.columns:
            return pd.to_numeric(out[c],errors="coerce")
        return pd.Series(np.nan,index=out.index,dtype="float64")

    sport=(out["Sport"].astype(str).str.upper().str.strip() if "Sport" in out.columns
           else pd.Series("NCAAF",index=out.index))
    is_ncaaf=sport.eq("NCAAF")
    regular=_n("Is_Regular_Season").fillna(1).eq(1)
    rebuild_audit=[]

    def _selective_rule(name, ready_mask, signal_mask):
        ready=pd.Series(ready_mask,index=out.index).fillna(False).astype(bool)
        signal=pd.Series(signal_mask,index=out.index).fillna(False).astype(bool)
        old=_n(name) if name in out.columns else pd.Series(np.nan,index=out.index,dtype="float64")
        preserved=(~ready)&old.notna()
        result=old.copy()
        result.loc[ready]=signal.loc[ready].astype(float)
        out[name]=result
        out[name+"_DataReady"]=ready.astype("int8")
        rebuild_audit.append(
            f"{name}:recomputed_rows={int(ready.sum())},preserved_rows={int(preserved.sum())}"
        )

    # CF1: second game, home, prior win scoring >42, nonconference, opponent without
    # current/prior-season revenge. Fall back to legacy opponent revenge only when
    # the new recency-aware field is not present at this row grain.
    cf1_rev_col=(
        "Opp_Revenge_Flag_CurrentOrPriorSeason"
        if (
            "Opp_Revenge_Flag_CurrentOrPriorSeason" in out.columns
            and pd.to_numeric(out["Opp_Revenge_Flag_CurrentOrPriorSeason"],errors="coerce").notna().any()
        )
        else "Opp_Revenge_Flag_Current"
    )
    cf1_req=["Team_Game_Number","Is_Home","Prev_SU_Win","Prev_Points_For","Is_Conference_Game",cf1_rev_col]
    cf1_ready=is_ncaaf.copy()
    for c in cf1_req:
        cf1_ready &= _n(c).notna()
    cf1_sig=(
        is_ncaaf & _n("Team_Game_Number").eq(2) & _n("Is_Home").eq(1)
        & _n("Prev_SU_Win").eq(1) & _n("Prev_Points_For").gt(42)
        & _n("Is_Conference_Game").eq(0) & _n(cf1_rev_col).eq(0)
    )
    _selective_rule("BigAl_CF1_Week2Home42Win",cf1_ready,cf1_sig)

    # CF2: late-season revenge underdog off 50+ points.
    cf2_req=["Team_Game_Number","Revenge_Flag_Current","Spread_Value","Prev_Points_For"]
    cf2_ready=is_ncaaf.copy()
    for c in cf2_req:
        cf2_ready &= _n(c).notna()
    cf2_sig=(
        is_ncaaf & regular & _n("Team_Game_Number").ge(9)
        & _n("Revenge_Flag_Current").eq(1) & _n("Spread_Value").gt(0)
        & _n("Prev_Points_For").gt(50)
    )
    _selective_rule("BigAl_CF2_LateSeasonRevengeDog",cf2_ready,cf2_sig)

    # User-provided 19+ favorite upset-loss fade: the CURRENT side is play-on when
    # its opponent was -19 or more and lost outright in the opponent's prior game.
    cf3_ready=is_ncaaf & _n("Opp_Prev_Spread_Value").notna() & _n("Opp_Prev_SU_Loss").notna()
    cf3_sig=(
        is_ncaaf & regular & _n("Opp_Prev_Spread_Value").le(-19.0)
        & _n("Opp_Prev_SU_Loss").eq(1)
    )
    _selective_rule("BigAl_CF3_Fade19PlusFavoriteUpsetLoss",cf3_ready,cf3_sig)

    # Named Big Al enhancer/tightener candidates used by the V13.2 expert stack.
    revdog_ready=is_ncaaf & _n("Revenge_Flag_Current").notna() & _n("Spread_Value").notna()
    revdog_sig=is_ncaaf & regular & _n("Revenge_Flag_Current").eq(1) & _n("Spread_Value").gt(0)
    _selective_rule("BigAl_CF_Enhancer_RevengeDog",revdog_ready,revdog_sig)

    cf2_flag=_n("BigAl_CF2_LateSeasonRevengeDog")
    away_ready=is_ncaaf & cf2_flag.notna() & _n("Is_Home").notna()
    away_sig=is_ncaaf & cf2_flag.eq(1) & _n("Is_Home").eq(0)
    _selective_rule("BigAl_CF2_Away_Tightener",away_ready,away_sig)

    if log_func:
        try:
            gg=_v132_rule_side_groups(out)
            def gc(mask):
                m=np.asarray(mask,dtype=bool)
                return int(len(pd.unique(gg[m]))) if m.any() else 0
            parts=[]
            for c in (
                "BigAl_CF1_Week2Home42Win","BigAl_CF2_LateSeasonRevengeDog",
                "BigAl_CF_Enhancer_RevengeDog","BigAl_CF2_Away_Tightener",
                "BigAl_CF3_Fade19PlusFavoriteUpsetLoss","Pathi_FB_Dog_TotalSpread_Gap_LE10"
            ):
                if c in out.columns:
                    parts.append(f"{c}={gc(pd.to_numeric(out[c],errors='coerce').fillna(0).eq(1))}")
            spread=(pd.to_numeric(out["Value"],errors="coerce")
                    if "Value" in out.columns else pd.Series(np.nan,index=out.index))
            if "Spread_Value" in out.columns:
                spread=spread.where(spread.notna(),pd.to_numeric(out["Spread_Value"],errors="coerce"))
            for c in ("Pathi_FB_Crossed_Key_Toward_Team","Pathi_FB_Crossed_Key_Away_From_Team"):
                if c in out.columns:
                    m=pd.to_numeric(out[c],errors="coerce").fillna(0).eq(1).to_numpy()
                    sv=spread.to_numpy(dtype=float,na_value=np.nan)
                    parts.append(f"{c}:dog={gc(m&(sv>0))},fav={gc(m&(sv<0))}")
            log_func("[V13.2-RULE-ROW-REBUILD] selective=PASS "+" | ".join(parts))
            log_func("[V13.2-RULE-ROW-REBUILD-DETAIL] "+" | ".join(rebuild_audit))
        except Exception as e:
            log_func(f"[V13.2-RULE-ROW-REBUILD] audit unavailable: {e}")
    return out

def _v132_row_seasons(rows: pd.DataFrame) -> np.ndarray:
    if rows is None or len(rows)==0: return np.asarray([],dtype=float)
    ss=pd.to_numeric(rows.get("Season"),errors="coerce") if "Season" in rows.columns else pd.Series(np.nan,index=rows.index)
    if ss.isna().any():
        gs=pd.to_datetime(rows.get("Game_Start"),errors="coerce",utc=True) if "Game_Start" in rows.columns else pd.Series(pd.NaT,index=rows.index)
        drv=_ncaaf_season_from_timestamp(gs)
        ss=ss.where(ss.notna(),pd.to_numeric(drv,errors="coerce"))
    return ss.to_numpy(dtype=float,na_value=np.nan)



def _v132_history_prior(src: dict, cutoff_season=None, cutoff_date=None, system_name=None) -> dict:
    """Leakage-safe system evidence with source-backed fallback and no ATS shrinkage.

    Internal and source records are NEVER added as independent samples.  For an
    exact source-verified system, the published ATS record is a provisional
    evidence source only after its effective date and only while our internal
    reconstruction is still immature.  Once internal history reaches the configured
    game/season maturity, internal evidence becomes primary.  The selected ATS rate
    is preserved exactly; later Core-incremental scaling controls probability
    influence, not the historical record itself.
    """
    out={
        "beta":0.0,"equiv_games":0.0,"sample":0,"wins":0.0,"posterior":0.5,"raw_ats":np.nan,
        "trust":0.0,"qualified":False,"cutoff_season":None,"cutoff_date":None,
        "evidence_mode":"NONE","internal_sample":0,"internal_wins":0.0,"internal_raw_ats":np.nan,
        "internal_seasons":0,"internal_mature":False,"source_available":False,
        "source_sample":0,"source_wins":0,"source_losses":0,"source_pushes":0,
        "source_raw_ats":np.nan,"source_reported_total":0,"source_name":None,
        "source_url":None,"source_effective_from":None,
    }
    if not isinstance(src,dict) or not bool(src.get("source_validation_pass",True)):
        out["evidence_mode"]="SOURCE_VALIDATION_CLOSED"
        return out

    n=0; wins=0.0; internal_seasons=set()
    occ=list(src.get("occurrences") or [])
    cd=pd.to_datetime(cutoff_date,errors="coerce",utc=True) if cutoff_date is not None else pd.NaT
    try: cut=int(float(cutoff_season))
    except Exception: cut=None

    if occ and pd.notna(cd):
        for rec in occ:
            if not isinstance(rec,dict): continue
            rd=pd.to_datetime(rec.get("date"),errors="coerce",utc=True)
            if pd.isna(rd) or not (rd < cd): continue
            try: y=float(rec.get("ats_win"))
            except Exception: continue
            if not np.isfinite(y): continue
            n+=1; wins+=y
            try:
                internal_seasons.add(int(float(rec.get("season"))))
            except Exception:
                pass
        out["cutoff_date"]=cd.isoformat()
    else:
        ss=src.get("season_stats") or {}
        if cut is not None:
            for ky,rec in ss.items():
                try: yr=int(float(ky))
                except Exception: continue
                if yr>=cut or not isinstance(rec,dict): continue
                nn=int(rec.get("sample",0) or 0); ww=float(rec.get("wins",0.0) or 0.0)
                if nn<=0: continue
                n+=nn; wins+=ww; internal_seasons.add(yr)
            out["cutoff_season"]=cut

    internal_raw=float(wins/n) if n>0 else np.nan
    source=_v132_source_backed_record(system_name)
    source_available=False
    if source:
        eff=pd.to_datetime(source.get("effective_from"),errors="coerce",utc=True)
        eff_season=int(source.get("effective_from_season",9999) or 9999)
        if pd.notna(cd) and pd.notna(eff):
            source_available=bool(cd >= eff)
        elif cut is not None:
            # With no precise date, require a season strictly after the publication
            # season to avoid retroactively injecting a later-published record.
            source_available=bool(cut > eff_season)
        decisions=int(source.get("wins",0) or 0)+int(source.get("losses",0) or 0)
        sats=float(source.get("ats",np.nan))
        out.update({
            "source_available":source_available,
            "source_sample":decisions,
            "source_wins":int(source.get("wins",0) or 0),
            "source_losses":int(source.get("losses",0) or 0),
            "source_pushes":int(source.get("pushes",0) or 0),
            "source_raw_ats":sats,
            "source_reported_total":int(source.get("reported_total",decisions) or decisions),
            "source_name":source.get("source"),"source_url":source.get("source_url"),
            "source_effective_from":source.get("effective_from"),
        })

    min_internal=int(source.get("internal_primary_min_games",V132_RULE_INTERNAL_PRIMARY_MIN_GAMES) if source else V132_RULE_INTERNAL_PRIMARY_MIN_GAMES)
    min_seasons=int(source.get("internal_primary_min_seasons",V132_RULE_INTERNAL_PRIMARY_MIN_SEASONS) if source else V132_RULE_INTERNAL_PRIMARY_MIN_SEASONS)
    internal_mature=bool(n>=min_internal and len(internal_seasons)>=min_seasons)
    internal_qualified=bool(n>=V132_RULE_HIST_MIN_GAMES and np.isfinite(internal_raw) and internal_raw>=V132_RULE_HIST_MIN_ATS)
    out.update({
        "internal_sample":int(n),"internal_wins":float(wins),"internal_raw_ats":internal_raw,
        "internal_seasons":int(len(internal_seasons)),"internal_mature":internal_mature,
    })

    evidence_mode="NONE"; use_n=0; use_wins=0.0; use_ats=np.nan
    if source and source_available and not internal_mature:
        decisions=int(source.get("wins",0) or 0)+int(source.get("losses",0) or 0)
        sats=float(source.get("ats",np.nan))
        if decisions>=V132_RULE_HIST_MIN_GAMES and np.isfinite(sats) and sats>=V132_RULE_HIST_MIN_ATS:
            evidence_mode="SOURCE_BACKED_FALLBACK"; use_n=decisions; use_wins=float(source.get("wins",0) or 0); use_ats=sats
        elif internal_qualified:
            evidence_mode="INTERNAL_ONLY"; use_n=n; use_wins=wins; use_ats=internal_raw
    elif internal_qualified:
        evidence_mode="INTERNAL_PRIMARY" if source and internal_mature else "INTERNAL_ONLY"
        use_n=n; use_wins=wins; use_ats=internal_raw
    else:
        if source and source_available and internal_mature:
            evidence_mode="INTERNAL_MATURE_NOT_QUALIFIED"
        elif n>0:
            evidence_mode="INSUFFICIENT_INTERNAL"
        else:
            evidence_mode="NO_INTERNAL_EVIDENCE"

    qualified=bool(use_n>=V132_RULE_HIST_MIN_GAMES and np.isfinite(use_ats) and use_ats>=V132_RULE_HIST_MIN_ATS)
    beta=float(np.clip(_v13_logit([use_ats])[0]-_v13_logit([0.5])[0],-V132_RULE_HIST_MAX_ABS_BETA,V132_RULE_HIST_MAX_ABS_BETA)) if qualified else 0.0
    out.update({
        "beta":beta,"equiv_games":float(use_n),"sample":int(use_n),"wins":float(use_wins),
        "posterior":float(use_ats) if np.isfinite(use_ats) else 0.5,"raw_ats":float(use_ats) if np.isfinite(use_ats) else np.nan,
        "trust":1.0 if qualified else 0.0,"qualified":qualified,"evidence_mode":evidence_mode,
    })
    return out

def _v132_row_dates(rows: pd.DataFrame) -> pd.Series:
    if rows is None or len(rows)==0:
        return pd.Series([],dtype="datetime64[ns, UTC]")
    for c in ("Game_Start","feat_Game_Start","Game_Date"):
        if c in rows.columns:
            z=pd.to_datetime(rows[c],errors="coerce",utc=True)
            if z.notna().any(): return pd.Series(z,index=rows.index)
    return pd.Series(pd.NaT,index=rows.index,dtype="datetime64[ns, UTC]")


def _v132_history_beta_vector(src: dict, rows: pd.DataFrame, system_name=None) -> tuple[np.ndarray,np.ndarray,np.ndarray]:
    """As-of-date selected evidence beta/sample/ATS for every rich-data row.

    Source-backed fallback obeys the publication effective date and never adds its
    sample to the overlapping internal reconstruction.
    """
    n=len(rows); bet=np.zeros(n,dtype=float); samp=np.zeros(n,dtype=float); ats=np.full(n,np.nan,dtype=float)
    dates=_v132_row_dates(rows); seasons=_v132_row_seasons(rows)
    cache={}
    for i in range(n):
        dt=dates.iloc[i] if i < len(dates) else pd.NaT
        sv=seasons[i] if i < len(seasons) else np.nan
        ky=(str(dt.date()) if pd.notna(dt) else "", int(sv) if np.isfinite(sv) else None)
        if ky not in cache:
            cache[ky]=_v132_history_prior(src,cutoff_season=sv,cutoff_date=dt,system_name=system_name)
        h=cache[ky]; bet[i]=float(h.get("beta",0.0) or 0.0); samp[i]=float(h.get("sample",0) or 0); ats[i]=float(h.get("raw_ats",np.nan))
    return bet,samp,ats

def _v132_canonical_side_keys(rows: pd.DataFrame) -> np.ndarray:
    """Canonical source-agnostic physical game-side key for historical/rich overlap.

    ``Outcome_Norm`` in the market-rich source may be ``home``/``away`` while the
    historical source stores the actual team name.  Resolve those aliases before
    constructing the key so the same physical game-side in two source tables is
    one observation, never two independent samples.
    """
    n=0 if rows is None else len(rows)
    if n==0: return np.asarray([],dtype=object)
    dates=_v132_row_dates(rows); seasons=_v132_row_seasons(rows)
    home=_hc_team_token(rows.get("Home_Team_Norm",rows.get("Home_Team",pd.Series("",index=rows.index))))
    away=_hc_team_token(rows.get("Away_Team_Norm",rows.get("Away_Team",pd.Series("",index=rows.index))))

    raw_side=None
    for c in ("Outcome_Norm","Outcome","Team_Norm","Team"):
        if c in rows.columns:
            raw_side=pd.Series(rows[c],index=rows.index).astype("string").fillna("").str.lower().str.strip(); break
    if raw_side is None:
        raw_side=pd.Series("",index=rows.index,dtype="string")
    token_side=_hc_team_token(raw_side)
    side=pd.Series(np.where(raw_side.eq("home"),home,np.where(raw_side.eq("away"),away,token_side)),index=rows.index,dtype="string")

    opp_col=next((c for c in ("Opponent_Norm","Opponent") if c in rows.columns),None)
    opp=_hc_team_token(rows[opp_col]) if opp_col else pd.Series("",index=rows.index,dtype="string")
    inferred_opp=pd.Series(np.where(side.eq(home),away,np.where(side.eq(away),home,"")),index=rows.index,dtype="string")
    # Prefer explicit opponent when valid, otherwise infer from home/away pair.
    opp=pd.Series(np.where(opp.astype(str).str.len().gt(0),opp,inferred_opp),index=rows.index,dtype="string")

    out=[]
    for i in range(n):
        sv=int(seasons[i]) if np.isfinite(seasons[i]) else ""
        ds=dates.iloc[i].strftime("%Y-%m-%d") if i < len(dates) and pd.notna(dates.iloc[i]) else ""
        out.append(f"{sv}|{ds}|{side.iloc[i]}|{opp.iloc[i]}")
    return np.asarray(out,dtype=object)


def _v132_canonical_game_keys(rows: pd.DataFrame) -> np.ndarray:
    """Source-agnostic physical GAME key; side/snapshot multiplicity collapses to one game."""
    n=0 if rows is None else len(rows)
    if n==0: return np.asarray([],dtype=object)
    dates=_v132_row_dates(rows); seasons=_v132_row_seasons(rows)
    home=_hc_team_token(rows.get("Home_Team_Norm",rows.get("Home_Team",pd.Series("",index=rows.index))))
    away=_hc_team_token(rows.get("Away_Team_Norm",rows.get("Away_Team",pd.Series("",index=rows.index))))
    team=_hc_team_token(rows.get("Team_Norm",rows.get("Team",pd.Series("",index=rows.index))))
    opp=_hc_team_token(rows.get("Opponent_Norm",rows.get("Opponent",pd.Series("",index=rows.index))))
    out=[]
    for i in range(n):
        sv=int(seasons[i]) if np.isfinite(seasons[i]) else ""
        ds=dates.iloc[i].strftime("%Y-%m-%d") if i < len(dates) and pd.notna(dates.iloc[i]) else ""
        a=str(home.iloc[i]); b=str(away.iloc[i])
        if not a or not b:
            a=str(team.iloc[i]); b=str(opp.iloc[i])
        pair=sorted([x for x in (a,b) if x])
        if len(pair)<2: out.append("")
        else: out.append(f"{sv}|{ds}|{pair[0]}|{pair[1]}")
    return np.asarray(out,dtype=object)


def _v132_collect_rich_rule_occurrences(rows: pd.DataFrame, log_func=print) -> dict:
    """Collect one canonical occurrence per rule/game-side from ALL available rich rows.

    This registry is evidence metadata only.  It does not add current/future rows to
    the chronological modifier fit.  It exists so 2025/2026 rich information is
    recognized as enrichment of the same physical games already present in history.
    """
    if rows is None or rows.empty: return {}
    rr=rows.copy().reset_index(drop=True)
    specs=_v132_rule_specs(rr); keys=_v132_canonical_side_keys(rr); seasons=_v132_row_seasons(rr); dates=_v132_row_dates(rr)
    result={}
    for sp in specs:
        name=sp["name"]
        try: trig=np.asarray(_v132_rule_trigger(rr,sp),dtype=bool)
        except Exception: continue
        recs={}
        for i in np.flatnonzero(trig):
            key=str(keys[i]) if i < len(keys) else ""
            if not key or not key.strip("|"): continue
            sv=int(seasons[i]) if i < len(seasons) and np.isfinite(seasons[i]) else None
            ds=dates.iloc[i].strftime("%Y-%m-%d") if i < len(dates) and pd.notna(dates.iloc[i]) else ""
            recs[key]={"key":key,"season":sv,"date":ds}
        if recs: result[name]=list(recs.values())
    if log_func:
        all_keys=set()
        by={}
        for recs in result.values():
            for r in recs:
                k=str(r.get("key",'')); all_keys.add(k)
                yr=r.get("season")
                if yr is not None: by[int(yr)]=by.get(int(yr),0)+1
        log_func(f"[V13.2-RICH-RULE-REGISTRY] rules={len(result)} unique_rule_side_keys={len(all_keys)} by_season_rule_occurrences={dict(sorted(by.items()))} role=EVIDENCE_ENRICHMENT_NOT_MODIFIER_TUNING")
    return result


def _v132_system_evidence_audit(name, src, trig, rows, groups, log_func=print):
    hist={str(r.get("key")) for r in list((src or {}).get("occurrences") or []) if isinstance(r,dict) and r.get("key")}
    rkeys=_v132_canonical_side_keys(rows); fit_rich={str(k) for k,m in zip(rkeys,np.asarray(trig,dtype=bool)) if m and str(k).strip("|")}
    registry_rich={str(r.get("key")) for r in list((src or {}).get("rich_occurrences") or []) if isinstance(r,dict) and r.get("key")}
    rich=fit_rich | registry_rich
    overlap=hist & rich; union=hist | rich
    by={}
    for key in union:
        try: yr=str(key).split("|",1)[0]
        except Exception: yr=""
        if yr:
            rec=by.setdefault(yr,{"history":0,"rich":0,"overlap":0,"unique":0})
            rec["history"]+=int(key in hist); rec["rich"]+=int(key in rich); rec["overlap"]+=int(key in overlap); rec["unique"]+=1
    log_func(f"[SYSTEM-EVIDENCE] system={name} history_unique={len(hist)} rich_fit_unique={len(fit_rich)} rich_registry_unique={len(rich)} overlap={len(overlap)} history_only={len(hist-overlap)} rich_only={len(rich-overlap)} unique_union={len(union)} double_counted=0")
    if by:
        log_func(f"[SYSTEM-EVIDENCE-BY-SEASON] system={name} "+" | ".join(f"{yr}:hist={v['history']},rich={v['rich']},overlap={v['overlap']},unique={v['unique']}" for yr,v in sorted(by.items())))
    return {"history_unique":len(hist),"rich_fit_unique":len(fit_rich),"rich_unique":len(rich),"overlap":len(overlap),"history_only":len(hist-overlap),"rich_only":len(rich-overlap),"unique_union":len(union),"by_season":by}



def _v132_combine_priors(family_beta: float, family_games: float, hist: dict) -> tuple[float,float]:
    """Compatibility shim: named-system history is never pooled with family history."""
    if isinstance(hist,dict) and bool(hist.get("qualified",False)):
        return float(hist.get("beta",0.0) or 0.0), float(hist.get("sample",0) or 0.0)
    return 0.0,0.0


def _v132_rule_specs(rows: pd.DataFrame) -> list[dict]:
    specs=[]
    if rows is None: return specs
    # Pathi football: keep every directional concept distinct. Symmetric context
    # events remain available as interaction ingredients but never vote alone.
    for c in PATHI_DIRECTIONAL_MEMORY_COLS:
        if c in rows.columns:
            _src=("USER_PROVIDED_PATHI_RULE_2026_09_11" if c=="Pathi_FB_Dog_TotalSpread_Gap_LE10" else "PATHI_FOOTBALL_DIRECTIONAL_CONCEPT")
            specs.append({"name":c,"family":"Pathi","kind":"column","columns":[c],"source":_src})
    # Big Al: only named NCAAF systems/enhancers/tighteners, never broad context.
    inv=list(BIGAL_EXACT_SIGNAL_COLS)+list(BIGAL_ENHANCER_COLS)+list(BIGAL_TIGHTENER_PARENT.keys())
    for c in dict.fromkeys(inv):
        if c in rows.columns and _system_feature_valid_for_sport(c,"NCAAF") and not _is_retired_bigal_feature_name(c):
            _src=("USER_PROVIDED_BIGAL_RULE_2026_09_11" if c=="BigAl_CF3_Fade19PlusFavoriteUpsetLoss" else "BIGAL_NAMED_RULE")
            specs.append({"name":c,"family":"BigAl","kind":"column","columns":[c],"source":_src})
    # Curated multi-hot Pathi interactions. They are independent candidate experts,
    # not replacements for the parent triggers, and survive only with OOF+shadow gain.
    for base in ("Pathi_FB_Crossed_Key_Toward_Team","Pathi_FB_Crossed_Key_Away_From_Team"):
        if base in rows.columns:
            specs.append({"name":base+"__DOG","family":"Pathi","kind":"column_role","columns":[base],"role":"DOG","source":"PATHI_INTERACTION"})
            specs.append({"name":base+"__FAVORITE","family":"Pathi","kind":"column_role","columns":[base],"role":"FAVORITE","source":"PATHI_INTERACTION"})
    return specs


def _v132_rule_trigger(rows: pd.DataFrame, spec: dict) -> np.ndarray:
    n=0 if rows is None else len(rows)
    if n==0: return np.zeros(0,dtype=bool)
    m=np.ones(n,dtype=bool)
    for c in list(spec.get("columns") or []):
        if c not in rows.columns: return np.zeros(n,dtype=bool)
        z=pd.to_numeric(rows[c],errors="coerce").fillna(0).to_numpy(dtype=float)
        m &= np.abs(z)>0.5
    if spec.get("kind")=="column_role":
        spread=None
        # Match add_pathi_football_key_features(): current row Value is the
        # authoritative selected-team line, then fall back to engineered aliases.
        for c in ("Value","Spread_Value","Outcome_Market_Spread","Opening_Spread"):
            if c in rows.columns:
                spread=pd.to_numeric(rows[c],errors="coerce").to_numpy(dtype=float,na_value=np.nan); break
        if spread is None: return np.zeros(n,dtype=bool)
        role=str(spec.get("role") or "").upper()
        m &= (spread>0) if role=="DOG" else ((spread<0) if role=="FAVORITE" else np.ones(n,dtype=bool))
    return m


def _v132_group_count(mask, groups) -> int:
    m=np.asarray(mask,dtype=bool); g=np.asarray(groups,dtype=object)
    return int(len(pd.unique(g[m]))) if m.any() else 0


def _v132_subset_group_weights(w,mask,groups) -> np.ndarray:
    """Give each physical game-side its full mass inside a sparse active subset.

    The outer weights are already game-side balanced across all quote/snapshot rows.
    A rule that fires on only one of twenty snapshots must not receive 1/20 the
    authority of a rule that happens to stay active on all twenty.  Reallocate each
    side's original total mass equally across only its ACTIVE rows.
    """
    ww=np.asarray(w,dtype=float).reshape(-1); mm=np.asarray(mask,dtype=bool); gg=np.asarray(groups,dtype=object)
    out=np.zeros(len(ww),dtype=float)
    if len(ww)==0 or len(gg)!=len(ww) or not mm.any(): return out
    frame=pd.DataFrame({"g":gg,"w":np.where(np.isfinite(ww)&(ww>0),ww,0.0),"m":mm})
    mass=frame.groupby("g",sort=False,dropna=False)["w"].transform("sum").to_numpy(dtype=float)
    ac=frame["m"].astype(int).groupby(frame["g"],sort=False,dropna=False).transform("sum").to_numpy(dtype=float)
    use=mm&(ac>0)&np.isfinite(mass)
    out[use]=mass[use]/ac[use]
    return out


def _v132_prob_metrics(y,p,w,mask,groups=None) -> dict:
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float); ww=np.asarray(w,dtype=float); mm=np.asarray(mask,dtype=bool)
    ok=mm&np.isfinite(pp)&np.isfinite(ww)&(ww>0)
    if not ok.any(): return {"n":0,"logloss":np.nan,"brier":np.nan,"hit":np.nan}
    usew=_v132_subset_group_weights(ww,ok,groups) if groups is not None else ww
    ok &= np.isfinite(usew)&(usew>0)
    if not ok.any(): return {"n":0,"logloss":np.nan,"brier":np.nan,"hit":np.nan}
    yy=yy[ok]; pp=np.clip(pp[ok],1e-6,1-1e-6); ww=usew[ok]
    ll=float(np.average(-(yy*np.log(pp)+(1-yy)*np.log(1-pp)),weights=ww)); br=float(np.average((pp-yy)**2,weights=ww))
    hit=float(np.average(((pp>=0.5)==yy).astype(float),weights=ww))
    return {"n":int(len(yy)),"logloss":ll,"brier":br,"hit":hit}


def _v132_scale_rule_prediction(base, rule_pred, scale):
    """Scale only the RULE STACK'S incremental log-odds contribution.

    This does not change any historical ATS record.  ``scale=1`` applies the full
    system-derived probability move, while ``scale=0`` leaves Core unchanged.
    A scalar or row vector is accepted so chronological folds can use coefficients
    learned only from earlier OOF folds.
    """
    b=np.asarray(base,dtype=float).reshape(-1); r=np.asarray(rule_pred,dtype=float).reshape(-1)
    if len(b)!=len(r): return b.copy()
    sc=np.asarray(scale,dtype=float)
    if sc.ndim==0:
        sc=np.full(len(b),float(sc),dtype=float)
    else:
        sc=sc.reshape(-1)
        if len(sc)!=len(b): sc=np.full(len(b),1.0,dtype=float)
    sc=np.clip(np.where(np.isfinite(sc),sc,0.0),0.0,1.0)
    out=b.copy(); ok=np.isfinite(b)&np.isfinite(r)
    if ok.any():
        db=_v13_logit(np.clip(r[ok],1e-6,1-1e-6))-_v13_logit(np.clip(b[ok],1e-6,1-1e-6))
        out[ok]=_v13_sigmoid(_v13_logit(np.clip(b[ok],1e-6,1-1e-6))+sc[ok]*db)
    return np.clip(out,0.01,0.99)


def _v132_choose_incremental_rule_scale(y,base,rule_pred,mask,w,groups):
    """Choose incremental system-to-Core influence on ACTIVE physical game-sides.

    Historical win rates remain untouched.  The coefficient answers a different
    question: how much of that predeclared system edge is incremental to Core?
    Selection requires both LogLoss and Brier to be non-inferior to Core.
    """
    yy=np.asarray(y,dtype=int); bb=np.asarray(base,dtype=float); rr=np.asarray(rule_pred,dtype=float)
    mm=np.asarray(mask,dtype=bool)&np.isfinite(bb)&np.isfinite(rr)
    if len(bb)!=len(rr):
        return 0.0,0,{},{}
    active=mm&(np.abs(_v13_logit(np.clip(rr,1e-6,1-1e-6))-_v13_logit(np.clip(bb,1e-6,1-1e-6)))>1e-10)
    ng=_v132_group_count(active,groups)
    bm=_v132_prob_metrics(yy,bb,w,active,groups)
    if ng<=0 or not np.isfinite(bm.get("logloss",np.nan)):
        return 0.0,ng,bm,bm
    best_scale=0.0; best=bm; best_obj=float(bm["logloss"]+bm["brier"])
    for sc in V132_RULE_INCREMENTAL_SCALE_GRID:
        pp=_v132_scale_rule_prediction(bb,rr,float(sc))
        mmx=_v132_prob_metrics(yy,pp,w,active,groups)
        if not np.isfinite(mmx.get("logloss",np.nan)) or not np.isfinite(mmx.get("brier",np.nan)):
            continue
        # The coefficient may reduce influence, but never worsens both proper scores
        # merely to preserve nominal system authority.  Historical evidence remains
        # in the artifact even if the incremental Core coefficient is zero.
        if mmx["logloss"]<=bm["logloss"]+1e-12 and mmx["brier"]<=bm["brier"]+1e-12:
            obj=float(mmx["logloss"]+mmx["brier"]);
            if obj<best_obj-1e-12 or (abs(obj-best_obj)<=1e-12 and float(sc)<best_scale):
                best_scale=float(sc); best=mmx; best_obj=obj
    return best_scale,ng,bm,best


def _v132_fit_offset_beta(y,base,active,w,groups,prior_beta=0.0,prior_games=0.0) -> tuple[float,int]:
    yy=np.asarray(y,dtype=int); bb=np.asarray(base,dtype=float); aa=np.asarray(active,dtype=bool); ww=np.asarray(w,dtype=float)
    ok=aa&np.isfinite(bb)&np.isfinite(ww)&(ww>0); ng=_v132_group_count(ok,groups)
    if ng<=0: return 0.0,0
    subw=_v132_subset_group_weights(ww,ok,groups); ok &= np.isfinite(subw)&(subw>0)
    if not ok.any(): return 0.0,0
    z=_v13_logit(bb[ok]); yv=yy[ok]; wv=subw[ok]; ps=float(max(0.0,prior_games)); pb=float(np.clip(prior_beta,-V132_RULE_BETA_LIMIT,V132_RULE_BETA_LIMIT))
    best=(float("inf"),0.0)
    for beta in np.linspace(-V132_RULE_BETA_LIMIT,V132_RULE_BETA_LIMIT,101):
        p=_v13_sigmoid(z+float(beta)); ll=float(np.average(-(yv*np.log(np.clip(p,1e-8,1))+(1-yv)*np.log(np.clip(1-p,1e-8,1))),weights=wv))
        penalty=(ps/max(float(ng)+ps,1.0))*0.50*(float(beta)-pb)**2
        score=ll+penalty
        if score<best[0]-1e-12: best=(score,float(beta))
    return float(best[1]),int(ng)


def _v132_family_prior_beta(y,base,triggers,family,specs,idx,w,groups) -> float:
    mask=np.zeros(len(y),dtype=bool)
    for sp in specs:
        if sp.get("family")==family:
            mask |= triggers[sp["name"]]
    use=np.zeros(len(y),dtype=bool); use[np.asarray(idx,dtype=int)]=True; mask &= use
    beta,ng=_v132_fit_offset_beta(y,base,mask,w,groups,0.0,0.0)
    return float(beta) if ng>=5 else 0.0




def _v13210_default_scale_for_evidence(full_hist: dict) -> tuple[float,str]:
    """Default influence only when OOF overlap is too small to learn a scale.

    Evidence rates stay unshrunk.  Source-backed records may retain full provisional
    influence; small internal-only records receive a sample-size maturity scale
    until either internal history reaches 100 games/3 seasons or OOF data learns a
    scale directly.
    """
    h=full_hist or {}; mode=str(h.get("evidence_mode","NONE")); n=int(h.get("internal_sample",0) or 0)
    mature=bool(h.get("internal_mature",False))
    if mode=="SOURCE_BACKED_FALLBACK": return 1.0,"SOURCE_BACKED_DEFAULT_FULL"
    if mode in {"INTERNAL_PRIMARY"} or mature: return 1.0,"INTERNAL_MATURE_DEFAULT_FULL"
    if mode=="INTERNAL_ONLY":
        raw=float(np.clip(n/max(float(V132_RULE_INTERNAL_PRIMARY_MIN_GAMES),1.0),0.0,1.0))
        grid=np.asarray(V132_RULE_INCREMENTAL_SCALE_GRID,dtype=float)
        # floor to a declared grid point so sparse samples never receive more
        # provisional influence than their maturity ratio supports.
        eligible=grid[grid<=raw+1e-12]
        sc=float(np.max(eligible)) if len(eligible) else 0.0
        return sc,"PROVISIONAL_INTERNAL_SAMPLE_MATURITY"
    return 0.0,"NO_DEFAULT_AUTHORITY"

def _v132_apply_rule_engine(base_prob, rows: pd.DataFrame, engine: dict, beta_overrides: dict|None=None, scale_overrides: dict|None=None, stack_scale_override=None):
    """Apply named systems with an independent Core-incremental scale per system.

    V13.2.8 removes the global system-stack kill switch.  Every rule keeps its own
    evidence record and its own incremental-to-Core coefficient.  One system's
    shadow failure therefore cannot erase unrelated Big Al/Pathi evidence.  The
    later full-stack safety contract still evaluates the exact combined probability.
    """
    rows=_v132_prepare_rule_rows(rows,log_func=None)
    base=np.asarray(base_prob,dtype=float).copy(); n=len(base); final=base.copy()
    detail={
        "Pathi":{"contribution":np.zeros(n),"weight":np.zeros(n),"active":np.zeros(n,dtype=np.int8),"residual_edge":np.zeros(n),"independence":np.ones(n),"incremental_scale":np.zeros(n),"names":np.full(n,"OTHER",dtype=object)},
        "BigAl":{"contribution":np.zeros(n),"weight":np.zeros(n),"active":np.zeros(n,dtype=np.int8),"residual_edge":np.zeros(n),"independence":np.ones(n),"incremental_scale":np.zeros(n),"names":np.full(n,"OTHER",dtype=object)},
    }
    if not isinstance(engine,dict) or not engine.get("gate_pass",False):
        for fam in ("Pathi","BigAl"): detail[fam]["prob"]=base.copy(); detail[fam]["regime"]=detail[fam].pop("names")
        return final,detail
    specs={sp.get("name"):sp for sp in list(engine.get("specs") or []) if isinstance(sp,dict)}; profiles=engine.get("profiles") or {}; selected=list(engine.get("selected_experts") or [])
    corr=engine.get("pairwise_corr") or {}; fam_used={"Pathi":np.zeros(n),"BigAl":np.zeros(n)}; total_used=np.zeros(n); prev=[]
    legacy_global=float(np.clip(stack_scale_override,0.0,1.0)) if stack_scale_override is not None else 1.0
    for name in selected:
        pr=profiles.get(name) or {}; sp=specs.get(name)
        if sp is None or not pr.get("gate_pass",False): continue
        active=_v132_rule_trigger(rows,sp)&np.isfinite(final)
        if not active.any(): continue
        fam=str(sp.get("family")); hist_auth=bool(pr.get("historical_authority",False))
        if beta_overrides is not None and name in beta_overrides:
            _braw=beta_overrides[name]
        else:
            if hist_auth and pr.get("historical_source"):
                hb,_,_=_v132_history_beta_vector(pr.get("historical_source") or {},rows,system_name=name)
            else:
                hb=np.zeros(n,dtype=float)
            mb=float(pr.get("modern_modifier_beta",pr.get("final_beta",0.0)) or 0.0) if bool(pr.get("modern_modifier_gate",False)) else (0.0 if hist_auth else float(pr.get("final_beta",0.0) or 0.0))
            _braw=hb+mb
        if np.ndim(_braw)>0 and not np.isscalar(_braw):
            _ba=np.asarray(_braw,dtype=float).reshape(-1)
            if len(_ba)!=n: continue
            active &= np.isfinite(_ba)
            if not active.any(): continue
            beta_active=_ba[active]
        else:
            beta_active=np.full(int(active.sum()),float(_braw),dtype=float)

        # Independent Core-incremental authority for this named system.
        if scale_overrides is not None and name in scale_overrides:
            _scraw=scale_overrides[name]
        else:
            _scraw=pr.get("active_incremental_scale",pr.get("incremental_scale",1.0))
        if np.ndim(_scraw)>0 and not np.isscalar(_scraw):
            _sca=np.asarray(_scraw,dtype=float).reshape(-1)
            if len(_sca)!=n: continue
            active &= np.isfinite(_sca)
            if not active.any(): continue
            scale_active=np.clip(_sca[active],0.0,1.0)*legacy_global
            # beta_active must be realigned if active changed after finite scale mask.
            if np.ndim(_braw)>0 and not np.isscalar(_braw):
                beta_active=np.asarray(_braw,dtype=float).reshape(-1)[active]
            else:
                beta_active=np.full(int(active.sum()),float(_braw),dtype=float)
        else:
            scale_active=np.full(int(active.sum()),float(np.clip(_scraw,0.0,1.0))*legacy_global,dtype=float)
        beta_active=np.asarray(beta_active,dtype=float)*scale_active
        if not np.any(np.abs(beta_active)>1e-12):
            continue

        proposal=_v13_sigmoid(_v13_logit(final[active])+beta_active)
        raw=np.clip(proposal-final[active],-V132_RULE_MAX_SINGLE_PROB_DELTA,V132_RULE_MAX_SINGLE_PROB_DELTA)
        indep=np.ones(raw.size,dtype=float)
        if not hist_auth:
            for prev_name,prev_mask,prev_delta,prev_hist in prev:
                if prev_hist: continue
                rho=float(max(0.0,(corr.get(name,{}) or {}).get(prev_name,(corr.get(prev_name,{}) or {}).get(name,0.0)) or 0.0))
                if rho>V132_RULE_CORR_DISCOUNT_START:
                    overlap=prev_mask[active]; same=overlap&(np.sign(raw)==np.sign(prev_delta[active])); indep[same]*=(1.0-min(V132_RULE_CORR_MAX_DISCOUNT,0.5*rho))
        raw*=indep
        idx=np.flatnonzero(active); fam_room=np.maximum(0.0,V132_RULE_MAX_FAMILY_PROB_DELTA-np.abs(fam_used[fam][idx])); total_room=np.maximum(0.0,V132_RULE_MAX_TOTAL_PROB_DELTA-np.abs(total_used[idx])); cap=np.minimum(fam_room,total_room); raw=np.sign(raw)*np.minimum(np.abs(raw),cap)
        before=final[idx].copy(); final[idx]=np.clip(final[idx]+raw,0.01,0.99); actual=final[idx]-before
        fam_used[fam][idx]+=actual; total_used[idx]+=actual
        dd=detail[fam]; dd["contribution"][idx]+=actual; dd["weight"][idx]=np.maximum(dd["weight"][idx],1.0 if hist_auth else float(np.clip(pr.get("trust",0.0) or 0.0,0,1))); dd["active"][idx]=1; dd["residual_edge"][idx]=np.maximum(dd["residual_edge"][idx],np.abs(beta_active)); dd["independence"][idx]=np.minimum(dd["independence"][idx],indep); dd["incremental_scale"][idx]=np.maximum(dd["incremental_scale"][idx],scale_active)
        names=dd["names"]
        for j in idx: names[j]=name if names[j]=="OTHER" else str(names[j])+"+"+name
        full_delta=np.zeros(n); full_delta[idx]=actual; prev.append((name,active,full_delta,hist_auth))

    for fam in ("Pathi","BigAl"):
        detail[fam]["prob"]=np.clip(base+detail[fam]["contribution"],0.01,0.99)
        detail[fam]["regime"]=detail[fam].pop("names")
    return np.clip(final,0.01,0.99),detail

def _v132_fit_rule_expert_engine(y,base,rows,folds,shadow_folds,sample_weight=None,source_history=None,log_func=print):
    """Fit named handicap systems with evidence-source and influence separation.

    V13.2.13 contracts:
      * 2022-2026 is one canonical game history; rich rows only add columns.
      * Historical ATS evidence is never shrunken toward 50%.
      * A verified published ATS record may temporarily replace a still-small
        internal reconstruction, but the samples are never added together.
      * Every named system gets its OWN incremental-to-Core coefficient.  One
        system's shadow failure cannot zero unrelated Big Al/Pathi systems.
      * Rich-data modifiers remain separately OOF/shadow gated.
      * The later exact full-stack safety and outer champion gate remain intact.
    """
    y=np.asarray(y,dtype=int); base=np.asarray(base,dtype=float); n=len(y)
    rule_rows=_v132_prepare_rule_rows(rows,log_func=log_func)
    specs=_v132_rule_specs(rule_rows); groups=_v132_rule_side_groups(rule_rows); w=_v132_rule_balanced_weights(rule_rows,sample_weight); seasons=_v132_row_seasons(rule_rows)
    select=np.zeros(n,dtype=bool); shadow=np.zeros(n,dtype=bool)
    for _,va in list(folds or []): select[np.asarray(va,dtype=int)]=True
    for _,va in list(shadow_folds or []): shadow[np.asarray(va,dtype=int)]=True
    triggers={sp["name"]:_v132_rule_trigger(rule_rows,sp) for sp in specs}; profiles={}; beta_oof={}; scale_oof={}; source_history=source_history or {}
    _fam_counts={fam:sum(1 for sp in specs if sp.get("family")==fam) for fam in ("Pathi","BigAl")}
    log_func(f"[V13.2-RULE-INVENTORY] total={len(specs)} Pathi={_fam_counts['Pathi']} BigAl={_fam_counts['BigAl']} grain=CANONICAL_PHYSICAL_GAME_SIDE historical_role=EVIDENCE_AUTHORITY rich_role=OPTIONAL_CONTEXT_MODIFIER influence_role=PER_SYSTEM_INCREMENTAL_TO_CORE double_count=ZERO")

    _row_dates=_v132_row_dates(rule_rows)
    _latest_date=(_row_dates.max()+pd.Timedelta(days=1)) if len(_row_dates) and _row_dates.notna().any() else None
    _full_cut_season=(int(np.nanmax(seasons))+1 if np.isfinite(seasons).any() else None)

    for sp in specs:
        name=sp["name"]; fam=sp["family"]; trig=triggers[name]; parent=name.split("__",1)[0]
        src=(source_history.get(name) or {}) if sp.get("kind")=="column_role" else (source_history.get(name) or source_history.get(parent) or {})
        source_pass=bool(src.get("source_validation_pass",True))
        evidence=_v132_system_evidence_audit(name,src,trig,rule_rows,groups,log_func=log_func)
        hist_beta_vec,hist_n_vec,hist_ats_vec=_v132_history_beta_vector(src,rule_rows,system_name=name) if src else (np.zeros(n),np.zeros(n),np.full(n,np.nan))
        full_hist=_v132_history_prior(src,cutoff_season=_full_cut_season,cutoff_date=_latest_date,system_name=name) if src else {"qualified":False,"sample":0,"raw_ats":np.nan,"beta":0.0,"evidence_mode":"NONE","internal_sample":0,"internal_raw_ats":np.nan,"internal_seasons":0}
        hist_authority=bool(source_pass and full_hist.get("qualified",False))
        source_record=_v132_source_backed_record(name)

        log_func(
            f"[SYSTEM-EVIDENCE-SOURCE] system={name} mode={full_hist.get('evidence_mode','NONE')} "
            f"evidence_n={int(full_hist.get('sample',0) or 0)} evidence_ats={float(full_hist.get('raw_ats',np.nan)):.4f} "
            f"internal_n={int(full_hist.get('internal_sample',0) or 0)} internal_ats={float(full_hist.get('internal_raw_ats',np.nan)):.4f} "
            f"internal_seasons={int(full_hist.get('internal_seasons',0) or 0)} internal_mature={bool(full_hist.get('internal_mature',False))} "
            f"source_n={int(full_hist.get('source_sample',0) or 0)} source_ats={float(full_hist.get('source_raw_ats',np.nan)):.4f} "
            f"source_available={bool(full_hist.get('source_available',False))} no_sample_addition=TRUE"
        )

        # ------------------------------
        # Rich-data modifier OOF
        # ------------------------------
        bo=np.full(n,np.nan,dtype=float); bvec=np.full(n,np.nan,dtype=float); frec=[]
        for fi,(tr,va) in enumerate(list(folds or [])):
            tr=np.asarray(tr,dtype=int); va=np.asarray(va,dtype=int)
            train_base=np.asarray(base,dtype=float).copy(); ta=trig[tr]&np.isfinite(train_base[tr])
            if ta.any():
                tidx=tr[ta]; train_base[tidx]=_v13_sigmoid(_v13_logit(train_base[tidx])+hist_beta_vec[tidx])
            trm=np.zeros(n,dtype=bool); trm[tr]=True
            modifier,ng=_v132_fit_offset_beta(y,train_base,trig&trm,w,groups,0.0,0.0)
            vm=np.zeros(n,dtype=bool); vm[va]=True; act=trig&vm&np.isfinite(base); vg=_v132_group_count(act,groups)
            if act.any():
                total_beta=hist_beta_vec[act]+modifier
                bo[act]=_v13_sigmoid(_v13_logit(base[act])+total_beta); bvec[act]=total_beta
            if vg>=V132_RULE_MIN_FOLD_GAMES:
                hpred=np.asarray(base,dtype=float).copy(); hpred[act]=_v13_sigmoid(_v13_logit(base[act])+hist_beta_vec[act])
                bm=_v132_prob_metrics(y,hpred,w,act,groups); fm=_v132_prob_metrics(y,bo,w,act,groups)
                llg=bm["logloss"]-fm["logloss"]; brg=bm["brier"]-fm["brier"]
                frec.append({"fold":fi,"games":vg,"train_games":ng,"modifier_beta":modifier,"ll_gain":llg,"brier_gain":brg,"positive":bool(llg>0 and brg>0)})

        sm=select&trig&np.isfinite(base)&np.isfinite(bo); sel_games=_v132_group_count(sm,groups)
        hist_sel=np.asarray(base,dtype=float).copy(); hist_sel[sm]=_v13_sigmoid(_v13_logit(base[sm])+hist_beta_vec[sm])
        sb=_v132_prob_metrics(y,hist_sel,w,sm,groups); sf=_v132_prob_metrics(y,bo,w,sm,groups)
        selll=(sb["logloss"]-sf["logloss"]) if np.isfinite(sb["logloss"]) and np.isfinite(sf["logloss"]) else np.nan
        selbr=(sb["brier"]-sf["brier"]) if np.isfinite(sb["brier"]) and np.isfinite(sf["brier"]) else np.nan
        pos=sum(1 for r in frec if r["positive"]); need=max(1,int(np.ceil(V132_RULE_MIN_POSITIVE_FOLD_FRAC*len(frec)))) if frec else 99

        fit_idx=np.flatnonzero(select&np.isfinite(base)); fitmask=np.zeros(n,dtype=bool); fitmask[fit_idx]=True
        fit_base=np.asarray(base,dtype=float).copy(); fm=trig&fitmask&np.isfinite(base); fit_base[fm]=_v13_sigmoid(_v13_logit(base[fm])+hist_beta_vec[fm])
        modifier_beta,fit_games=_v132_fit_offset_beta(y,fit_base,trig&fitmask,w,groups,0.0,0.0)
        shm=shadow&trig&np.isfinite(base); sh_games=_v132_group_count(shm,groups)
        hist_sh=np.asarray(base,dtype=float).copy(); hist_sh[shm]=_v13_sigmoid(_v13_logit(base[shm])+hist_beta_vec[shm])
        shp=hist_sh.copy(); shp[shm]=_v13_sigmoid(_v13_logit(hist_sh[shm])+modifier_beta)
        shb=_v132_prob_metrics(y,hist_sh,w,shm,groups); shf=_v132_prob_metrics(y,shp,w,shm,groups)
        shll=(shb["logloss"]-shf["logloss"]) if np.isfinite(shb["logloss"]) and np.isfinite(shf["logloss"]) else np.nan
        shbr=(shb["brier"]-shf["brier"]) if np.isfinite(shb["brier"]) and np.isfinite(shf["brier"]) else np.nan

        modifier_reasons=[]
        if sel_games<V132_RULE_MIN_SELECTION_GAMES: modifier_reasons.append(f"SELECTION_GAMES<{V132_RULE_MIN_SELECTION_GAMES}")
        if sh_games<V132_RULE_MIN_SHADOW_GAMES: modifier_reasons.append(f"SHADOW_GAMES<{V132_RULE_MIN_SHADOW_GAMES}")
        if len(frec)<V132_RULE_MIN_READY_FOLDS: modifier_reasons.append(f"READY_FOLDS<{V132_RULE_MIN_READY_FOLDS}")
        if pos<need: modifier_reasons.append(f"POSITIVE_FOLDS<{need}")
        if not np.isfinite(selll) or selll<=0: modifier_reasons.append("SELECTION_LOGLOSS")
        if not np.isfinite(selbr) or selbr<=0: modifier_reasons.append("SELECTION_BRIER")
        if not np.isfinite(shll) or shll<0: modifier_reasons.append("SHADOW_LOGLOSS")
        if not np.isfinite(shbr) or shbr<0: modifier_reasons.append("SHADOW_BRIER")
        modifier_gate=not modifier_reasons

        modern_only_gate=bool((not hist_authority) and source_pass and modifier_gate and np.isfinite(modifier_beta) and modifier_beta>=V132_RULE_MIN_FINAL_BETA)
        gate=bool(hist_authority or modern_only_gate)
        gate_reasons=[] if gate else (["SOURCE_VALIDATION"] if not source_pass else ["NO_HISTORICAL_AUTHORITY"]+modifier_reasons)
        frac=(pos/len(frec)) if frec else 0.0
        mod_trust=float(np.clip(0.35*min(1,sel_games/40)+0.35*frac+0.30*min(1,sh_games/15),0,1)) if modifier_gate else 0.0
        all_games=_v132_group_count(trig&np.isfinite(base),groups)

        # The OOF beta represents the rule proposal BEFORE incremental-to-Core
        # influence scaling.  A failed rich modifier falls back to historical base.
        if hist_authority:
            raw_beta_oof=bvec if modifier_gate else hist_beta_vec.copy()
            shadow_beta=hist_beta_vec + (float(modifier_beta) if modifier_gate else 0.0)
        else:
            raw_beta_oof=bvec
            shadow_beta=np.full(n,float(modifier_beta if modern_only_gate else 0.0),dtype=float)

        # ------------------------------
        # Per-system chronological Core-incremental scale
        # ------------------------------
        scale_vec=np.ones(n,dtype=float); scale_fold_records=[]; prior_val=[]
        for fi,(_tr,va) in enumerate(list(folds or [])):
            va=np.asarray(va,dtype=int); pm=np.zeros(n,dtype=bool)
            if prior_val: pm[np.asarray(prior_val,dtype=int)]=True
            raw_prior=np.asarray(base,dtype=float).copy()
            act_prior=pm&trig&np.isfinite(base)&np.isfinite(raw_beta_oof)
            if act_prior.any(): raw_prior[act_prior]=_v13_sigmoid(_v13_logit(base[act_prior])+raw_beta_oof[act_prior])
            sc,ng,bm,mm=_v132_choose_incremental_rule_scale(y,base,raw_prior,pm,w,groups)
            if ng < V132_RULE_INCREMENTAL_SCALE_MIN_PRIOR_GAMES:
                sc=1.0; status="EVIDENCE_DEFAULT_FULL_INSUFFICIENT_PRIOR_OOF" if hist_authority else "MODERN_GATE_DEFAULT_FULL"
            else:
                status="LEARNED_FROM_PRIOR_OOF"
            scale_vec[va]=float(sc)
            scale_fold_records.append({"fold":fi,"prior_active_games":int(ng),"scale":float(sc),"status":status,
                                       "prior_base_logloss":float(bm.get("logloss",np.nan)),"prior_scaled_logloss":float(mm.get("logloss",np.nan)),
                                       "prior_base_brier":float(bm.get("brier",np.nan)),"prior_scaled_brier":float(mm.get("brier",np.nan))})
            prior_val.extend(va.tolist())

        raw_sel_pred=np.asarray(base,dtype=float).copy()
        _selact=select&trig&np.isfinite(base)&np.isfinite(raw_beta_oof)
        if _selact.any(): raw_sel_pred[_selact]=_v13_sigmoid(_v13_logit(base[_selact])+raw_beta_oof[_selact])
        selected_scale,sel_scale_games,sel_scale_base,sel_scale_met=_v132_choose_incremental_rule_scale(y,base,raw_sel_pred,select,w,groups)
        if gate and sel_scale_games < V132_RULE_PER_SYSTEM_SCALE_MIN_SELECTION_GAMES:
            if hist_authority:
                selected_scale,selected_scale_status=_v13210_default_scale_for_evidence(full_hist)
            else:
                selected_scale=1.0; selected_scale_status="MODERN_GATE_DEFAULT_FULL"
            sel_scaled_pred=_v132_scale_rule_prediction(base,raw_sel_pred,selected_scale)
            sel_scale_met=_v132_prob_metrics(y,sel_scaled_pred,w,_selact,groups)
            sel_scale_base=_v132_prob_metrics(y,base,w,_selact,groups)
        else:
            selected_scale_status="LEARNED_SELECTION_OOF"

        raw_shadow_pred=np.asarray(base,dtype=float).copy()
        _shact=shadow&trig&np.isfinite(base)&np.isfinite(shadow_beta)
        if _shact.any(): raw_shadow_pred[_shact]=_v13_sigmoid(_v13_logit(base[_shact])+shadow_beta[_shact])
        sh_trial=_v132_scale_rule_prediction(base,raw_shadow_pred,selected_scale)
        sh_scale_games=_v132_group_count(_shact,groups)
        sh_scale_base=_v132_prob_metrics(y,base,w,_shact,groups); sh_scale_met=_v132_prob_metrics(y,sh_trial,w,_shact,groups)
        if not gate:
            shadow_transfer=False; shadow_scale_status="NO_RULE_AUTHORITY"
        elif sh_scale_games < V132_RULE_PER_SYSTEM_SCALE_MIN_SHADOW_GAMES:
            # Sparse modern overlap cannot erase the evidence record, but small
            # INTERNAL_ONLY samples no longer receive automatic full influence.
            shadow_transfer=bool(selected_scale>0); shadow_scale_status=(
                "SOURCE_OR_MATURE_EVIDENCE_PROVISIONAL_SHADOW" if hist_authority and selected_scale>=1.0
                else "PROVISIONAL_INTERNAL_INFLUENCE" if hist_authority and selected_scale>0
                else "MODERN_GATE_ALREADY_VALIDATED" if not hist_authority
                else "PROVISIONAL_INTERNAL_ZERO"
            )
        else:
            shadow_transfer=bool(
                np.isfinite(sh_scale_base.get("logloss",np.nan)) and np.isfinite(sh_scale_met.get("logloss",np.nan))
                and np.isfinite(sh_scale_base.get("brier",np.nan)) and np.isfinite(sh_scale_met.get("brier",np.nan))
                and sh_scale_met["logloss"]<=sh_scale_base["logloss"]+1e-12
                and sh_scale_met["brier"]<=sh_scale_base["brier"]+1e-12
            )
            shadow_scale_status="PASS" if shadow_transfer else "SHADOW_VETO_THIS_SYSTEM_ONLY"
        active_scale=float(selected_scale if shadow_transfer else 0.0)

        profiles[name]={
            "family":fam,"source":sp.get("source"),"gate_pass":gate,"gate_reasons":gate_reasons,"source_validation_pass":source_pass,
            "historical_authority":hist_authority,"historical_source":src if hist_authority else {},"source_backed_record":source_record,
            "evidence_mode":full_hist.get("evidence_mode","NONE"),
            "historical_sample":int(full_hist.get("sample",0) or 0),"historical_raw_ats":float(full_hist.get("raw_ats",np.nan)),"historical_base_beta":float(full_hist.get("beta",0.0) or 0.0),
            "internal_historical_sample":int(full_hist.get("internal_sample",0) or 0),"internal_historical_raw_ats":float(full_hist.get("internal_raw_ats",np.nan)),"internal_historical_seasons":int(full_hist.get("internal_seasons",0) or 0),"internal_historical_mature":bool(full_hist.get("internal_mature",False)),
            "source_historical_sample":int(full_hist.get("source_sample",0) or 0),"source_historical_raw_ats":float(full_hist.get("source_raw_ats",np.nan)),"source_historical_available":bool(full_hist.get("source_available",False)),
            "modern_modifier_gate":bool(modifier_gate),"modern_modifier_beta":float(modifier_beta if modifier_gate else 0.0),"modern_modifier_trust":mod_trust,
            "final_beta":float(modifier_beta if modern_only_gate else 0.0),"trust":1.0 if hist_authority else mod_trust,
            "all_trigger_games":all_games,"selection_games":sel_games,"shadow_games":sh_games,"fit_games":fit_games,
            "selection_ll_gain":float(selll) if np.isfinite(selll) else np.nan,"selection_brier_gain":float(selbr) if np.isfinite(selbr) else np.nan,
            "shadow_ll_gain":float(shll) if np.isfinite(shll) else np.nan,"shadow_brier_gain":float(shbr) if np.isfinite(shbr) else np.nan,
            "positive_folds":pos,"eligible_folds":len(frec),"required_positive_folds":need,"fold_records":frec,"canonical_evidence":evidence,
            "selected_incremental_scale":float(selected_scale),"active_incremental_scale":float(active_scale),
            "incremental_scale_selection_games":int(sel_scale_games),"incremental_scale_shadow_games":int(sh_scale_games),
            "incremental_scale_selection_status":selected_scale_status,"incremental_scale_shadow_status":shadow_scale_status,
            "incremental_scale_shadow_transfer_pass":bool(shadow_transfer),"incremental_scale_fold_records":scale_fold_records,
            "incremental_selection_ll_gain":float(sel_scale_base.get("logloss",np.nan)-sel_scale_met.get("logloss",np.nan)) if np.isfinite(sel_scale_base.get("logloss",np.nan)) and np.isfinite(sel_scale_met.get("logloss",np.nan)) else np.nan,
            "incremental_selection_brier_gain":float(sel_scale_base.get("brier",np.nan)-sel_scale_met.get("brier",np.nan)) if np.isfinite(sel_scale_base.get("brier",np.nan)) and np.isfinite(sel_scale_met.get("brier",np.nan)) else np.nan,
            "incremental_shadow_ll_gain":float(sh_scale_base.get("logloss",np.nan)-sh_scale_met.get("logloss",np.nan)) if np.isfinite(sh_scale_base.get("logloss",np.nan)) and np.isfinite(sh_scale_met.get("logloss",np.nan)) else np.nan,
            "incremental_shadow_brier_gain":float(sh_scale_base.get("brier",np.nan)-sh_scale_met.get("brier",np.nan)) if np.isfinite(sh_scale_base.get("brier",np.nan)) and np.isfinite(sh_scale_met.get("brier",np.nan)) else np.nan,
        }
        beta_oof[name]=raw_beta_oof
        scale_oof[name]=scale_vec
        log_func(
            f"[V13.2-RULE-EXPERT] family={fam} expert={name} gate={'PASS' if gate else 'CLOSED'} historical_authority={hist_authority} "
            f"evidence_mode={profiles[name]['evidence_mode']} hist_n={profiles[name]['historical_sample']} hist_ats={profiles[name]['historical_raw_ats']:.4f} "
            f"internal_n={profiles[name]['internal_historical_sample']} internal_ats={profiles[name]['internal_historical_raw_ats']:.4f} "
            f"hist_beta={profiles[name]['historical_base_beta']:+.4f} rich_fit_games={all_games} rich_registry={evidence.get('rich_unique',all_games)} overlap={evidence.get('overlap',0)} "
            f"modifier_gate={modifier_gate} modifier_beta={(modifier_beta if np.isfinite(modifier_beta) else np.nan):+.4f} sel_games={sel_games} shadow_games={sh_games} reasons={gate_reasons or modifier_reasons or ['PASS']}"
        )
        log_func(
            f"[V13.2-SYSTEM-INCREMENTAL-SCALE] system={name} evidence_mode={profiles[name]['evidence_mode']} selected_scale={selected_scale:.2f} active_scale={active_scale:.2f} "
            f"selection_active_games={sel_scale_games} shadow_active_games={sh_scale_games} "
            f"selection_ll={profiles[name]['incremental_selection_ll_gain']:+.6f} selection_br={profiles[name]['incremental_selection_brier_gain']:+.6f} "
            f"shadow_ll={profiles[name]['incremental_shadow_ll_gain']:+.6f} shadow_br={profiles[name]['incremental_shadow_brier_gain']:+.6f} "
            f"selection_status={selected_scale_status} shadow_status={shadow_scale_status} evidence_record=UNSHRUNK"
        )

    historical_selected=[nm for nm,p in profiles.items() if p.get("gate_pass") and p.get("historical_authority")]
    modern_candidates=[nm for nm,p in profiles.items() if p.get("gate_pass") and not p.get("historical_authority")]
    selected=list(historical_selected)
    corr={nm:{} for nm in historical_selected+modern_candidates}
    for i,a in enumerate(historical_selected+modern_candidates):
        xa=triggers[a][select].astype(float)
        for b in (historical_selected+modern_candidates)[:i]:
            xb=triggers[b][select].astype(float); rho=float(np.corrcoef(xa,xb)[0,1]) if len(xa)>=20 and np.std(xa)>0 and np.std(xb)>0 else 0.0
            if not np.isfinite(rho): rho=0.0
            corr[a][b]=rho; corr[b][a]=rho

    # Historical evidence enters first with each rule's leakage-safe OOF scale.
    # Modern-only candidates are still greedily screened for additional selection gain.
    greedy_records=[]
    current_engine={"version":V132_RULE_EXPERT_VERSION,"gate_pass":bool(selected),"specs":specs,"profiles":profiles,"selected_experts":selected,"pairwise_corr":corr,"rule_stack_incremental_scale":1.0}
    current_oof,_=_v132_apply_rule_engine(base,rule_rows,current_engine,beta_overrides=beta_oof,scale_overrides=scale_oof) if selected else (np.asarray(base,dtype=float).copy(),{})
    sel_all=select&np.isfinite(base); current_metrics=_ncaaf_v13_specialist_metrics(y[sel_all],current_oof[sel_all],w[sel_all])
    modern_candidates.sort(key=lambda nm:(profiles[nm].get("selection_ll_gain",0),profiles[nm].get("selection_games",0)),reverse=True)
    for cand_name in modern_candidates:
        trial_names=selected+[cand_name]
        trial_engine={"version":V132_RULE_EXPERT_VERSION,"gate_pass":True,"specs":specs,"profiles":profiles,"selected_experts":trial_names,"pairwise_corr":corr,"rule_stack_incremental_scale":1.0}
        trial_oof,_=_v132_apply_rule_engine(base,rule_rows,trial_engine,beta_overrides=beta_oof,scale_overrides=scale_oof)
        tm=_ncaaf_v13_specialist_metrics(y[sel_all],trial_oof[sel_all],w[sel_all])
        llg=float(current_metrics.get("logloss",np.nan)-tm.get("logloss",np.nan)); brg=float(current_metrics.get("brier",np.nan)-tm.get("brier",np.nan))
        accept=bool(np.isfinite(llg) and np.isfinite(brg) and llg>=-1e-12 and brg>=-1e-12 and (llg>1e-10 or brg>1e-10))
        greedy_records.append({"expert":cand_name,"accepted":accept,"incremental_selection_ll_gain":llg,"incremental_selection_brier_gain":brg})
        log_func(f"[V13.2-RULE-PORTFOLIO] expert={cand_name} {'KEEP' if accept else 'REJECT'} incremental_sel_ll={llg:+.6f} incremental_sel_br={brg:+.6f} per_system_scale={profiles[cand_name].get('active_incremental_scale',0.0):.2f}")
        if accept:
            selected.append(cand_name); current_oof=trial_oof; current_metrics=tm

    for _name,_pr in profiles.items():
        if isinstance(_pr,dict): _pr["stack_selected"]=bool(_name in set(selected))

    # Selection diagnostics use leakage-safe OOF scales.  Shadow/runtime use each
    # system's independent active scale; there is no aggregate shadow kill switch.
    eval_engine={"version":V132_RULE_EXPERT_VERSION,"gate_pass":bool(selected),"specs":specs,"profiles":profiles,"selected_experts":selected,"pairwise_corr":corr,"rule_stack_incremental_scale":1.0}
    oof=np.asarray(base,dtype=float).copy(); sh=np.asarray(base,dtype=float).copy()
    if selected:
        oof,_=_v132_apply_rule_engine(base,rule_rows,eval_engine,beta_overrides=beta_oof,scale_overrides=scale_oof)
        sh,_=_v132_apply_rule_engine(base,rule_rows,eval_engine)

    active_selected=[nm for nm in selected if float((profiles.get(nm) or {}).get("active_incremental_scale",1.0 if not (profiles.get(nm) or {}).get("historical_authority") else 0.0) or 0.0)>0]
    inactive_evidence=[nm for nm in historical_selected if nm not in active_selected]
    per_scales={nm:float((profiles.get(nm) or {}).get("active_incremental_scale",0.0) or 0.0) for nm in selected}
    engine={
        "version":V132_RULE_EXPERT_VERSION,"gate_pass":bool(active_selected),"specs":specs,"profiles":profiles,
        "selected_experts":selected,"active_selected_experts":active_selected,"historical_base_experts":historical_selected,
        "inactive_historical_evidence":inactive_evidence,"modern_only_experts":[nm for nm in selected if nm not in historical_selected],
        "portfolio_selection_records":greedy_records,"pairwise_corr":corr,
        "rule_stack_incremental_scale":1.0,"per_system_incremental_scales":per_scales,"per_system_incremental_scaling":True,
        "historical_evidence_preserved":True,"source_backed_fallback_enabled":True,
        "canonical_evidence_contract":"HISTORY_AND_RICH_SAME_GAME_SIDE_UNION__NO_DOUBLE_COUNT",
        "contract":"SOURCE_BACKED_OR_INTERNAL_UNSHRUNK_SYSTEM_EVIDENCE__NO_SAMPLE_ADDITION__PER_SYSTEM_OOF_INCREMENTAL_CORE_SCALE__PER_SYSTEM_SHADOW_VETO__RICH_CONTEXT_MODIFIER__FULL_STACK_SAFETY_RETAINED",
    }

    selm=select&np.isfinite(oof)&np.isfinite(base); shm=shadow&np.isfinite(sh)&np.isfinite(base)
    bsel=_ncaaf_v13_specialist_metrics(y[selm],base[selm],w[selm]); fsel=_ncaaf_v13_specialist_metrics(y[selm],oof[selm],w[selm])
    bsh=_ncaaf_v13_specialist_metrics(y[shm],base[shm],w[shm]); fsh=_ncaaf_v13_specialist_metrics(y[shm],sh[shm],w[shm])
    engine.update({
        "selection_metrics":fsel,"shadow_metrics":fsh,
        "selection_ll_gain":float(bsel.get('logloss',np.nan)-fsel.get('logloss',np.nan)) if np.isfinite(bsel.get('logloss',np.nan)) and np.isfinite(fsel.get('logloss',np.nan)) else np.nan,
        "selection_brier_gain":float(bsel.get('brier',np.nan)-fsel.get('brier',np.nan)) if np.isfinite(bsel.get('brier',np.nan)) and np.isfinite(fsel.get('brier',np.nan)) else np.nan,
        "shadow_ll_gain":float(bsh.get('logloss',np.nan)-fsh.get('logloss',np.nan)) if np.isfinite(bsh.get('logloss',np.nan)) and np.isfinite(fsh.get('logloss',np.nan)) else np.nan,
        "shadow_brier_gain":float(bsh.get('brier',np.nan)-fsh.get('brier',np.nan)) if np.isfinite(bsh.get('brier',np.nan)) and np.isfinite(fsh.get('brier',np.nan)) else np.nan,
    })
    log_func(
        f"[V13.2-RULE-STACK] gate={'PASS' if engine.get('gate_pass') else 'CLOSED'} historical_evidence={historical_selected} active_systems={active_selected} "
        f"inactive_historical_evidence={inactive_evidence} modern_selected={engine.get('modern_only_experts')} per_system_scales={per_scales} "
        f"selection_ll={engine.get('selection_ll_gain',np.nan):+.6f} selection_br={engine.get('selection_brier_gain',np.nan):+.6f} "
        f"shadow_ll={engine.get('shadow_ll_gain',np.nan):+.6f} shadow_br={engine.get('shadow_brier_gain',np.nan):+.6f} "
        f"historical_evidence_preserved=TRUE global_system_kill_switch=REMOVED"
    )
    return engine,oof,sh


# -----------------------------------------------------------------------------
# V13.2.13 MARKET MOVE INTELLIGENCE (MMI) — RESEARCH ONLY
# -----------------------------------------------------------------------------
# Objective: determine whether pregame movement toward a team contains a repeatable
# ATS/SU signal, and whether known key-number / Big Al / Pathi conditions explain
# or strengthen that signal.  This layer has ZERO production probability authority
# in V13.2.13.  Thresholds below are predeclared and are not tuned on the outer
# champion holdout.
V13213_MMI_VERSION = "2026-09-12-v13.2.13-bigal-style-market-move-discovery-research"
V13213_MMI_BETA_GRID = (0.00, 0.05, 0.10, 0.15, 0.20, 0.30, 0.40, -0.05, -0.10, -0.15, -0.20, -0.30, -0.40)
V13213_MMI_MIN_TOTAL_GAMES = 20
V13213_MMI_MIN_SELECTION_GAMES = 20
V13213_MMI_MIN_SHADOW_GAMES = 10
V13213_MMI_MIN_INTERACTION_TOTAL_GAMES = 8
V13213_MMI_BREAK_EVEN = 0.5238
# Big-Al-style discovery is deliberately bounded to control combinatorial search.
# Candidate ranking uses chronological selection data only; shadow is validation only.
V13213_MMI_BIGAL_MAX_CONTEXT_CLAUSES = 4
V13213_MMI_BIGAL_BEAM_WIDTH = 12
V13213_MMI_BIGAL_FINALISTS_PER_ANCHOR = 8
V13213_MMI_BIGAL_MAX_LOGGED_RULES = 30
V13213_MMI_BIGAL_MIN_ATOM_GAMES = 8
V13213_MMI_BIGAL_MIN_TEAM_GAMES = 8
V13213_MMI_BIGAL_MAX_TEAM_ATOMS = 40
V13213_MMI_BIGAL_MIN_DISCOVERY_SELECTION_GAMES = 24
V13213_MMI_BIGAL_EXTRA_GAMES_PER_CLAUSE = 4
V13213_MMI_BIGAL_TEAM_EXTRA_SELECTION_GAMES = 8
V13213_MMI_BIGAL_MIN_DISCOVERY_SHADOW_GAMES = 12
V13213_MMI_BIGAL_MIN_DISCOVERY_TOTAL_GAMES = 40
V13213_MMI_BIGAL_MIN_SELECTION_DIRECTIONAL_ATS = 0.54
V13213_MMI_BIGAL_MIN_DISTINCT_SEASONS = 2
V13213_MMI_BIGAL_TEAM_MIN_TOTAL_FOR_VALIDATION = 50


def _v13213_american_implied_prob(v):
    x=pd.to_numeric(v,errors="coerce")
    out=pd.Series(np.nan,index=x.index,dtype="float64") if isinstance(x,pd.Series) else np.full(len(np.atleast_1d(x)),np.nan,dtype=float)
    if isinstance(x,pd.Series):
        neg=x.lt(0); pos=x.gt(0)
        out.loc[neg]=(-x.loc[neg])/((-x.loc[neg])+100.0)
        out.loc[pos]=100.0/(x.loc[pos]+100.0)
        return out
    a=np.asarray(x,dtype=float); neg=a<0; pos=a>0
    out[neg]=(-a[neg])/((-a[neg])+100.0); out[pos]=100.0/(a[pos]+100.0)
    return out


def _v13213_wilson_interval(wins: int, n: int, z: float=1.959963984540054):
    n=int(n or 0); wins=int(wins or 0)
    if n<=0: return (np.nan,np.nan)
    p=float(wins)/float(n); den=1.0+(z*z/n)
    center=(p+(z*z/(2*n)))/den
    half=(z*np.sqrt((p*(1-p)/n)+(z*z/(4*n*n))))/den
    return (float(max(0.0,center-half)),float(min(1.0,center+half)))


def _v13213_move_research_metrics(y,p,w=None):
    yy=np.asarray(y,dtype=int); pp=np.asarray(p,dtype=float)
    ww=np.ones(len(yy),dtype=float) if w is None else np.asarray(w,dtype=float)
    ok=np.isfinite(pp)&np.isfinite(ww)&(ww>0)
    if int(ok.sum())<2: return {"n":int(ok.sum()),"logloss":np.nan,"brier":np.nan,"auc":np.nan,"accuracy":np.nan}
    return _ncaaf_v13_specialist_metrics(yy[ok],np.clip(pp[ok],1e-6,1-1e-6),ww[ok])


def _v13213_choose_move_beta(y,base,w):
    yy=np.asarray(y,dtype=int); bb=np.asarray(base,dtype=float); ww=np.asarray(w,dtype=float)
    ok=np.isfinite(bb)&np.isfinite(ww)&(ww>0)
    if int(ok.sum())<V13213_MMI_MIN_SELECTION_GAMES:
        return 0.0,_v13213_move_research_metrics(yy[ok],bb[ok],ww[ok]),_v13213_move_research_metrics(yy[ok],bb[ok],ww[ok])
    yy=yy[ok]; bb=np.clip(bb[ok],1e-5,1-1e-5); ww=ww[ok]
    base_met=_v13213_move_research_metrics(yy,bb,ww); best_beta=0.0; best_met=base_met
    for beta in [b for b in V13213_MMI_BETA_GRID if abs(float(b))>1e-12]:
        pp=_v13_sigmoid(_v13_logit(bb)+float(beta))
        met=_v13213_move_research_metrics(yy,pp,ww)
        llg=float(base_met.get("logloss",np.nan)-met.get("logloss",np.nan))
        brg=float(base_met.get("brier",np.nan)-met.get("brier",np.nan))
        if np.isfinite(llg) and np.isfinite(brg) and llg>=-1e-12 and brg>=-1e-12:
            old_ll=float(best_met.get("logloss",np.inf)); new_ll=float(met.get("logloss",np.inf))
            old_br=float(best_met.get("brier",np.inf)); new_br=float(met.get("brier",np.inf))
            if (new_ll < old_ll-1e-12) or (abs(new_ll-old_ll)<=1e-12 and new_br<old_br-1e-12):
                best_beta=float(beta); best_met=met
    return best_beta,base_met,best_met


def _v13213_fit_market_move_intelligence(y,base,rows,folds,shadow_folds,rule_engine=None,sample_weight=None,log_func=print):
    """Research-only Big-Al-style market-move system discovery.

    The engine starts from predeclared market-move anchors and searches bounded,
    human-readable situational conjunctions using ONLY pregame/as-of state.  Rule
    discovery/ranking happens on chronological selection folds; the disjoint shadow
    lane is used only to validate the frozen rule.  The untouched outer champion
    holdout is never used.  Production authority remains zero in V13.2.13.

    Spread convention is team-specific: a numerically LOWER spread is movement
    toward the selected team (+7 -> +5.5, -3 -> -4).  The engine may discover
    either PLAY_ON_MOVED_TEAM rules or FADE_MOVED_TEAM rules.  No causal claim is
    made about Big Al, Pathi, syndicates, or any bettor causing the move.
    """
    if rows is None or rows.empty:
        return {"version":V13213_MMI_VERSION,"status":"NO_ROWS","authority":"RESEARCH_ONLY","production_weight":0.0}
    n=len(rows); yy=np.asarray(y,dtype=int).reshape(-1); bb=np.asarray(base,dtype=float).reshape(-1)
    if len(yy)!=n or len(bb)!=n:
        return {"version":V13213_MMI_VERSION,"status":"ROW_ALIGNMENT_MISMATCH","authority":"RESEARCH_ONLY","production_weight":0.0}
    ww=np.ones(n,dtype=float) if sample_weight is None else np.asarray(sample_weight,dtype=float).reshape(-1)
    if len(ww)!=n: ww=np.ones(n,dtype=float)
    select=np.zeros(n,dtype=bool); shadow=np.zeros(n,dtype=bool)
    for _,va in list(folds or []): select[np.asarray(va,dtype=int)]=True
    for _,va in list(shadow_folds or []): shadow[np.asarray(va,dtype=int)]=True

    rr=_v132_prepare_rule_rows(rows,log_func=None)
    side_group=_v132_rule_side_groups(rr)
    game_col=next((c for c in ("Game_Key","Merge_Key_Short","_SOURCE_ROW_ID") if c in rr.columns),None)
    games=(rr[game_col].astype(str).str.lower().str.strip().to_numpy(dtype=object)
           if game_col else np.asarray([str(g).split("|")[0] for g in side_group],dtype=object))

    def num(*cols):
        for c in cols:
            if c in rr.columns:
                z=pd.to_numeric(rr[c],errors="coerce")
                if z.notna().any(): return z
        return pd.Series(np.nan,index=rr.index,dtype="float64")

    def txt(*cols):
        for c in cols:
            if c in rr.columns:
                z=rr[c].astype("string").fillna("").str.lower().str.strip()
                if z.ne("").any(): return z
        return pd.Series("",index=rr.index,dtype="string")

    line_open=num("Line_Move_From_Open")
    line60=num("Line_Move_60m","Line_Move_Last60m")
    sharp60=num("Sharp_Book_Move_60m")
    sharp_lead=num("Sharp_Move_Before_Market").fillna(0)
    reversed_flag=num("Key_Cross_Reversed").fillna(0)
    persistence=num("Key_Cross_Persistence")
    sharp_confirm=num("Key_Cross_Confirmed_By_Sharp_Books").fillna(0)
    odds_now=num("Odds_Price")
    odds_open=num("First_Odds","First_Odds_Price","Open_Odds","Old_Odds")
    price_delta=_v13213_american_implied_prob(odds_now)-_v13213_american_implied_prob(odds_open)
    su=num("SU_Win")
    if su.notna().sum()==0:
        ts=num("Team_Score","Points_For"); os=num("Opponent_Score","Points_Against")
        su=pd.Series(np.where(ts.notna()&os.notna(),(ts>os).astype(float),np.nan),index=rr.index,dtype="float64")

    key_cols={k:num(f"Crossed_Key_{k}_Last60m") for k in (3,7,10,14)}
    is_home=num("Is_Home")
    home_team=txt("Home_Team_Norm","Home_Team")
    away_team=txt("Away_Team_Norm","Away_Team")
    team_txt=pd.Series(np.where(is_home.eq(1),home_team,away_team),index=rr.index,dtype="string").str.lower().str.strip()
    opp_txt=pd.Series(np.where(is_home.eq(1),away_team,home_team),index=rr.index,dtype="string").str.lower().str.strip()
    home_conf=txt("Home_Conference"); away_conf=txt("Away_Conference")
    team_conf=pd.Series(np.where(is_home.eq(1),home_conf,away_conf),index=rr.index,dtype="string").str.lower().str.strip()
    opp_conf=pd.Series(np.where(is_home.eq(1),away_conf,home_conf),index=rr.index,dtype="string").str.lower().str.strip()

    # Canonical context inventory. Every field is already pregame/as-of state from
    # the team-game builder or the as-of conference context join. Missing inputs do
    # not fail open; their atoms simply do not exist for this run.
    ctx_aliases={
        "Season":("Season",), "Week_Number":("Week_Number","Week","Game_Week"),
        "Team_Game_Number":("Team_Game_Number",), "Is_Home":("Is_Home",),
        "Is_Regular_Season":("Is_Regular_Season",), "Is_Bowl":("Is_Bowl",), "Is_Postseason":("Is_Postseason","Is_Playoffs"),
        "MMI_First_Home_Game_System":("MMI_First_Home_Game_System",), "MMI_First_Road_Game_System":("MMI_First_Road_Game_System",),
        "Days_Since_Last_Game_System":("Days_Since_Last_Game_System","Days_Since_Last_Game"),
        "Opp_Days_Since_Last_Game_System":("Opp_Days_Since_Last_Game_System","Opp_Days_Since_Last_Game"),
        "Had_Bye_Last_Game_System":("Had_Bye_Last_Game_System",), "Opp_Had_Bye_Last_Game_System":("Opp_Had_Bye_Last_Game_System",),
        "SU_Win_Streak_Prior":("SU_Win_Streak_Prior",), "SU_Loss_Streak_Prior":("SU_Loss_Streak_Prior",),
        "ATS_Win_Streak_Prior":("ATS_Win_Streak_Prior",), "ATS_Loss_Streak_Prior":("ATS_Loss_Streak_Prior",),
        "Prev_SU_Win":("Prev_SU_Win",), "Prev_SU_Loss":("Prev_SU_Loss",), "Prev_SU_Margin":("Prev_SU_Margin",),
        "Prev_Points_For":("Prev_Points_For",), "Prev_ATS_Win":("Prev_ATS_Win",), "Prev_ATS_Loss":("Prev_ATS_Loss",),
        "Prev_Is_ML_Dog":("Prev_Is_ML_Dog",), "Prev_Is_ML_Favorite":("Prev_Is_ML_Favorite",),
        "Prev2_SU_Win":("Prev2_SU_Win",), "Prev3_SU_Win":("Prev3_SU_Win",),
        "Prev2_ATS_Win":("Prev2_ATS_Win",), "Prev3_ATS_Win":("Prev3_ATS_Win",),
        "Prev2_Is_ML_Dog":("Prev2_Is_ML_Dog",), "Prev3_Is_ML_Dog":("Prev3_Is_ML_Dog",),
        "Revenge_Flag_Current":("Revenge_Flag_Current",), "Opp_Revenge_Flag_Current":("Opp_Revenge_Flag_Current",),
        "Last_Matchup_SU_Margin_System":("Last_Matchup_SU_Margin_System",),
        "MMI_Last_Matchup_Is_Home_System":("MMI_Last_Matchup_Is_Home_System",),
        "MMI_Last_Matchup_Points_For_System":("MMI_Last_Matchup_Points_For_System",),
        "Spread_Value":("Spread_Value","Value"), "WinPct_Prior_System":("WinPct_Prior_System",),
        "Opp_WinPct_Prior_System":("Opp_WinPct_Prior_System",),
        "MMI_ATS_WinPct_Prior_System":("MMI_ATS_WinPct_Prior_System",),
        "MMI_Opp_ATS_WinPct_Prior_System":("MMI_Opp_ATS_WinPct_Prior_System","Opp_MMI_ATS_WinPct_Prior_System"),
        "Team_Prior_Season_Playoff":("Team_Prior_Season_Playoff",),
        "Opponent_Prior_Season_Playoff":("Opponent_Prior_Season_Playoff","Opp_Team_Prior_Season_Playoff"),
        "Opp_Prev_SU_Win":("Opp_Prev_SU_Win",), "Opp_Prev_SU_Loss":("Opp_Prev_SU_Loss",),
        "Opp_Prev_ATS_Win":("Opp_Prev_ATS_Win",), "Opp_Prev_ATS_Loss":("Opp_Prev_ATS_Loss",),
    }

    z=pd.DataFrame({
        "side_group":side_group,"game":games,"y":yy,"base":bb,"w":ww,
        "selection":select,"shadow":shadow,"line_open":line_open.to_numpy(float),
        "line60":line60.to_numpy(float),"sharp60":sharp60.to_numpy(float),
        "sharp_lead":sharp_lead.to_numpy(float),"reversed":reversed_flag.to_numpy(float),
        "persistence":persistence.to_numpy(float),"sharp_confirm":sharp_confirm.to_numpy(float),
        "price_delta":price_delta.to_numpy(float),"su":su.to_numpy(float),
        "team":team_txt.to_numpy(dtype=object),"opponent":opp_txt.to_numpy(dtype=object),
        "team_conf":team_conf.to_numpy(dtype=object),"opp_conf":opp_conf.to_numpy(dtype=object),
    })
    for k,v in key_cols.items(): z[f"key{k}"]=v.to_numpy(float)
    for canon,aliases in ctx_aliases.items(): z[canon]=num(*aliases).to_numpy(float)

    agg={
        "game":"first","y":"first","base":"median","w":"sum","selection":"max","shadow":"max",
        "line_open":"median","line60":"median","sharp60":"median","sharp_lead":"max","reversed":"max",
        "persistence":"median","sharp_confirm":"max","price_delta":"median","su":"first",
        "team":"first","opponent":"first","team_conf":"first","opp_conf":"first",
        **{f"key{k}":"max" for k in (3,7,10,14)},
        **{c:"median" for c in ctx_aliases},
    }
    g=z.groupby("side_group",sort=False,dropna=False).agg(agg).reset_index()
    g["w"]=1.0
    overlap=int((g["selection"].astype(bool)&g["shadow"].astype(bool)).sum())
    log_func(f"[MMI-CONTRACT] version={V13213_MMI_VERSION} authority=RESEARCH_ONLY production_weight=0 outer_holdout_used=FALSE grain=ONE_SIDE_PER_PHYSICAL_GAME_CANDIDATE spread_toward_team=NUMERICALLY_LOWER discovery=BIGAL_STYLE_BOUNDED_BEAM conference_membership=AS_OF_GAME_CONTEXT causality=NOT_INFERRED side_groups={len(g)} selection_shadow_overlap={overlap}")

    key_any=np.zeros(len(g),dtype=bool)
    for k in (3,7,10,14): key_any |= pd.to_numeric(g[f"key{k}"],errors="coerce").fillna(0).gt(0).to_numpy()
    lo=pd.to_numeric(g["line_open"],errors="coerce").to_numpy(float)
    l60=pd.to_numeric(g["line60"],errors="coerce").to_numpy(float)
    s60=pd.to_numeric(g["sharp60"],errors="coerce").to_numpy(float)
    pdlt=pd.to_numeric(g["price_delta"],errors="coerce").to_numpy(float)
    lead=pd.to_numeric(g["sharp_lead"],errors="coerce").fillna(0).to_numpy(float)
    rev=pd.to_numeric(g["reversed"],errors="coerce").fillna(0).to_numpy(float)
    pers=pd.to_numeric(g["persistence"],errors="coerce").to_numpy(float)
    conf=pd.to_numeric(g["sharp_confirm"],errors="coerce").fillna(0).to_numpy(float)
    patterns={
        "LINE_TOWARD_TEAM_GE_0_5":(np.isfinite(lo)&(lo<=-0.50),np.where(np.isfinite(lo),-lo,0.0)),
        "LINE_TOWARD_TEAM_GE_1_0":(np.isfinite(lo)&(lo<=-1.00),np.where(np.isfinite(lo),-lo,0.0)),
        "RECENT_60M_TOWARD_GE_0_5":(np.isfinite(l60)&(l60<=-0.50),np.where(np.isfinite(l60),-l60,0.0)),
        "SHARP_60M_TOWARD_GE_0_25":(np.isfinite(s60)&(s60<=-0.25),np.where(np.isfinite(s60),-s60,0.0)),
        "SHARP_LEAD_TOWARD":((lead>0.5)&np.isfinite(s60)&(s60<0),np.where(np.isfinite(s60),-s60,0.0)+lead),
        "KEY_CROSS_TOWARD":(key_any&np.isfinite(l60)&(l60<0),np.where(np.isfinite(l60),-l60,0.0)+key_any.astype(float)),
        "SHARP_KEY_CROSS_TOWARD":((conf>0.5)&np.isfinite(s60)&(s60<0),np.where(np.isfinite(s60),-s60,0.0)+conf),
        "PERSISTENT_LINE_TOWARD":(np.isfinite(lo)&(lo<=-0.50)&(rev<0.5)&np.isfinite(pers)&(pers>=0.50),np.where(np.isfinite(lo),-lo,0.0)+np.nan_to_num(pers)),
        "PRICE_TOWARD_TEAM_GE_1PCT":(np.isfinite(pdlt)&(pdlt>=0.01),np.where(np.isfinite(pdlt),pdlt*100.0,0.0)),
        "LINE_OR_PRICE_TOWARD":((np.isfinite(lo)&(lo<=-0.50))|(np.isfinite(pdlt)&(pdlt>=0.01)),np.maximum(np.where(np.isfinite(lo),-lo,0.0),np.where(np.isfinite(pdlt),pdlt*100.0,0.0))),
    }

    def _dedup(mask,score):
        m=np.asarray(mask,dtype=bool)&np.isfinite(g["base"].to_numpy(float))
        if not m.any(): return g.iloc[0:0].copy()
        sub=g.loc[m].copy(); sub["__score"]=np.asarray(score,dtype=float)[m]
        return (sub.sort_values(["game","__score"],ascending=[True,False],kind="stable")
                   .drop_duplicates("game",keep="first"))

    def evaluate(name,mask,score,kind="MOVE",parent=None):
        sub=_dedup(mask,score)
        if sub.empty:
            return {"name":name,"kind":kind,"parent":parent,"games":0,"status":"NO_OCCURRENCES","incremental_status":"NO_DATA"}
        yv=pd.to_numeric(sub["y"],errors="coerce"); valid=yv.isin([0,1]); sub=sub.loc[valid].copy(); yv=yv.loc[valid].astype(int).to_numpy()
        if len(sub)==0: return {"name":name,"kind":kind,"parent":parent,"games":0,"status":"NO_GRADED_GAMES","incremental_status":"NO_DATA"}
        raw_hit=float(yv.mean()); sm=sub["selection"].astype(bool).to_numpy(); hm=sub["shadow"].astype(bool).to_numpy()
        sel_n=int(sm.sum()); sh_n=int(hm.sum()); sel_raw=float(yv[sm].mean()) if sel_n else np.nan; sh_raw=float(yv[hm].mean()) if sh_n else np.nan
        # Direction is frozen from selection only. This lets the engine discover a
        # contrarian fade without peeking at shadow outcomes.
        direction="PLAY_ON_MOVED_TEAM" if (not np.isfinite(sel_raw) or sel_raw>=0.50) else "FADE_MOVED_TEAM"
        ydir=yv if direction=="PLAY_ON_MOVED_TEAM" else (1-yv)
        hit=float(ydir.mean()); sel_hit=float(ydir[sm].mean()) if sel_n else np.nan; sh_hit=float(ydir[hm].mean()) if sh_n else np.nan
        wins=int(ydir.sum()); nall=len(ydir); ci=_v13213_wilson_interval(wins,nall)
        suvals=pd.to_numeric(sub["su"],errors="coerce"); suok=suvals.isin([0,1]); su_raw=float(suvals.loc[suok].mean()) if suok.any() else np.nan
        su_hit=(su_raw if direction=="PLAY_ON_MOVED_TEAM" else (1.0-su_raw if np.isfinite(su_raw) else np.nan))
        p0=pd.to_numeric(sub["base"],errors="coerce").to_numpy(float); wt=np.ones(nall,dtype=float)
        beta,bsel,fsel=_v13213_choose_move_beta(yv[sm],p0[sm],wt[sm]) if sel_n else (0.0,{"logloss":np.nan,"brier":np.nan},{"logloss":np.nan,"brier":np.nan})
        # A discovered direction and the learned Core correction must agree.
        if direction=="PLAY_ON_MOVED_TEAM" and beta<0: beta=0.0
        if direction=="FADE_MOVED_TEAM" and beta>0: beta=0.0
        psh=_v13_sigmoid(_v13_logit(np.clip(p0[hm],1e-5,1-1e-5))+beta) if sh_n else np.asarray([])
        bsh=_v13213_move_research_metrics(yv[hm],p0[hm],wt[hm]) if sh_n else {"logloss":np.nan,"brier":np.nan}
        fsh=_v13213_move_research_metrics(yv[hm],psh,wt[hm]) if sh_n else {"logloss":np.nan,"brier":np.nan}
        # Recompute selection candidate after direction clamp when necessary.
        psel=_v13_sigmoid(_v13_logit(np.clip(p0[sm],1e-5,1-1e-5))+beta) if sel_n else np.asarray([])
        bsel=_v13213_move_research_metrics(yv[sm],p0[sm],wt[sm]) if sel_n else {"logloss":np.nan,"brier":np.nan}
        fsel=_v13213_move_research_metrics(yv[sm],psel,wt[sm]) if sel_n else {"logloss":np.nan,"brier":np.nan}
        sel_ll=float(bsel.get("logloss",np.nan)-fsel.get("logloss",np.nan)) if np.isfinite(bsel.get("logloss",np.nan)) and np.isfinite(fsel.get("logloss",np.nan)) else np.nan
        sel_br=float(bsel.get("brier",np.nan)-fsel.get("brier",np.nan)) if np.isfinite(bsel.get("brier",np.nan)) and np.isfinite(fsel.get("brier",np.nan)) else np.nan
        sh_ll=float(bsh.get("logloss",np.nan)-fsh.get("logloss",np.nan)) if np.isfinite(bsh.get("logloss",np.nan)) and np.isfinite(fsh.get("logloss",np.nan)) else np.nan
        sh_br=float(bsh.get("brier",np.nan)-fsh.get("brier",np.nan)) if np.isfinite(bsh.get("brier",np.nan)) and np.isfinite(fsh.get("brier",np.nan)) else np.nan
        seasons=sorted({int(x) for x in pd.to_numeric(sub.get("Season"),errors="coerce").dropna().unique()}) if "Season" in sub.columns else []
        standalone=(nall>=40 and sel_n>=V13213_MMI_MIN_SELECTION_GAMES and sh_n>=V13213_MMI_MIN_SHADOW_GAMES and
                    np.isfinite(sel_hit) and sel_hit>V13213_MMI_BREAK_EVEN and np.isfinite(sh_hit) and sh_hit>V13213_MMI_BREAK_EVEN and
                    np.isfinite(ci[0]) and ci[0]>0.50)
        promising=(nall>=V13213_MMI_MIN_TOTAL_GAMES and hit>V13213_MMI_BREAK_EVEN and
                   ((np.isfinite(sel_hit) and sel_hit>V13213_MMI_BREAK_EVEN) or (np.isfinite(sh_hit) and sh_hit>V13213_MMI_BREAK_EVEN)))
        incr=(abs(beta)>1e-12 and sel_n>=V13213_MMI_MIN_SELECTION_GAMES and sh_n>=V13213_MMI_MIN_SHADOW_GAMES and
              np.isfinite(sel_ll) and sel_ll>=-1e-12 and np.isfinite(sel_br) and sel_br>=-1e-12 and
              np.isfinite(sh_ll) and sh_ll>=-1e-12 and np.isfinite(sh_br) and sh_br>=-1e-12)
        status="LEGIT_MODEL_CANDIDATE" if (standalone and incr) else ("VALIDATED_STANDALONE_EDGE" if standalone else ("PROMISING_NOT_PROVEN" if promising else "NO_VALIDATED_EDGE"))
        inc_status="PASS" if incr else ("INSUFFICIENT_SHADOW" if sh_n<V13213_MMI_MIN_SHADOW_GAMES else ("INSUFFICIENT_SELECTION" if sel_n<V13213_MMI_MIN_SELECTION_GAMES else "CLOSED"))
        return {"name":name,"kind":kind,"parent":parent,"games":int(nall),"ats":raw_hit,"direction":direction,"directional_ats":hit,"ats_ci95":[ci[0],ci[1]],
                "su_n":int(suok.sum()),"su_hit":su_hit,"selection_games":sel_n,"selection_ats":sel_raw,"selection_directional_ats":sel_hit,
                "shadow_games":sh_n,"shadow_ats":sh_raw,"shadow_directional_ats":sh_hit,"selected_beta":float(beta),
                "selection_ll_gain":sel_ll,"selection_brier_gain":sel_br,"shadow_ll_gain":sh_ll,"shadow_brier_gain":sh_br,
                "seasons":seasons,"status":status,"incremental_status":inc_status,"legit_model_candidate":bool(standalone and incr)}

    records=[]
    for name,(mask,score) in patterns.items():
        r=evaluate(name,mask,score,"MOVE"); records.append(r)
        log_func(f"[MMI-MOVE-PATTERN] pattern={name} games={r.get('games',0)} direction={r.get('direction')} ats={r.get('ats',np.nan):.4f} directional_ats={r.get('directional_ats',np.nan):.4f} ci95={r.get('ats_ci95')} su_n={r.get('su_n',0)} su_hit={r.get('su_hit',np.nan):.4f} sel_games={r.get('selection_games',0)} sel_dir_ats={r.get('selection_directional_ats',np.nan):.4f} shadow_games={r.get('shadow_games',0)} shadow_dir_ats={r.get('shadow_directional_ats',np.nan):.4f} beta={r.get('selected_beta',0.0):+.2f} sel_ll={r.get('selection_ll_gain',np.nan):+.6f} shadow_ll={r.get('shadow_ll_gain',np.nan):+.6f} status={r.get('status')} incremental={r.get('incremental_status')}")

    # Existing key-number diagnostics.
    key_records=[]; base_mask,base_score=patterns["LINE_TOWARD_TEAM_GE_0_5"]
    for k in (3,7,10,14):
        km=pd.to_numeric(g[f"key{k}"],errors="coerce").fillna(0).gt(0).to_numpy()
        r=evaluate(f"LINE_TOWARD_TEAM_X_KEY_{k}",base_mask&km,base_score+km.astype(float),"KEY",parent="LINE_TOWARD_TEAM_GE_0_5")
        key_records.append(r)
        if r.get("games",0)>=V13213_MMI_MIN_INTERACTION_TOTAL_GAMES:
            log_func(f"[MMI-KEY-INTERACTION] key={k} games={r.get('games')} direction={r.get('direction')} dir_ats={r.get('directional_ats',np.nan):.4f} sel_games={r.get('selection_games',0)} shadow_games={r.get('shadow_games',0)} beta={r.get('selected_beta',0.0):+.2f} status={r.get('status')} incremental={r.get('incremental_status')}")

    # Precompute exact known-system masks. Overlap reporting is by occurrence count,
    # never by outcome, so it cannot leak shadow results into discovery ranking.
    specs=list((rule_engine or {}).get("specs") or _v132_rule_specs(rr))
    known_system_masks={}; known_system_family={}
    for sp in specs:
        nm=str(sp.get("name") or ""); fam=str(sp.get("family") or "")
        trig=_v132_rule_trigger(rr,sp)
        tgmask=pd.DataFrame({"side_group":side_group,"t":trig.astype(int)}).groupby("side_group",sort=False)["t"].max()
        known_system_masks[nm]=g["side_group"].map(tgmask).fillna(0).gt(0).to_numpy(); known_system_family[nm]=fam

    # Exact system interactions retained from V13.2.12.
    system_records=[]
    interaction_patterns=("LINE_TOWARD_TEAM_GE_0_5","SHARP_LEAD_TOWARD","PERSISTENT_LINE_TOWARD")
    for nm,sysmask in known_system_masks.items():
        if not sysmask.any(): continue
        fam=known_system_family.get(nm,"")
        for pn in interaction_patterns:
            pm,pscore=patterns[pn]
            r=evaluate(f"{pn}__{nm}",pm&sysmask,pscore+sysmask.astype(float),"SYSTEM",parent=pn)
            r["system"]=nm; r["family"]=fam; system_records.append(r)
    kept_system=[r for r in system_records if int(r.get("games",0) or 0)>=V13213_MMI_MIN_INTERACTION_TOTAL_GAMES]
    kept_system.sort(key=lambda r:(bool(r.get("legit_model_candidate")),float(r.get("directional_ats",-1) if np.isfinite(r.get("directional_ats",np.nan)) else -1),int(r.get("games",0))),reverse=True)
    for r in kept_system[:30]:
        log_func(f"[MMI-SYSTEM-INTERACTION] move={r.get('parent')} family={r.get('family')} system={r.get('system')} games={r.get('games')} direction={r.get('direction')} dir_ats={r.get('directional_ats',np.nan):.4f} sel_games={r.get('selection_games',0)} sel_dir_ats={r.get('selection_directional_ats',np.nan):.4f} shadow_games={r.get('shadow_games',0)} shadow_dir_ats={r.get('shadow_directional_ats',np.nan):.4f} beta={r.get('selected_beta',0.0):+.2f} status={r.get('status')} incremental={r.get('incremental_status')} causality=NOT_INFERRED")

    # ------------------------------------------------------------------
    # Big-Al-style bounded system discovery.
    # ------------------------------------------------------------------
    def ncol(c): return pd.to_numeric(g.get(c,pd.Series(np.nan,index=g.index)),errors="coerce")
    atoms=[]
    def add_atom(name,category,mask,description=None,team_specific=False):
        mm=np.asarray(mask,dtype=bool)
        if len(mm)!=len(g) or int(mm.sum())<V13213_MMI_BIGAL_MIN_ATOM_GAMES: return
        atoms.append({"name":name,"category":category,"mask":mm,"description":description or name,"team_specific":bool(team_specific)})

    week=ncol("Week_Number"); game_no=ncol("Team_Game_Number"); home=ncol("Is_Home"); spread=ncol("Spread_Value")
    regular=ncol("Is_Regular_Season"); bowl=ncol("Is_Bowl"); post=ncol("Is_Postseason")
    rest=ncol("Days_Since_Last_Game_System"); opp_rest=ncol("Opp_Days_Since_Last_Game_System")
    bye=ncol("Had_Bye_Last_Game_System"); suws=ncol("SU_Win_Streak_Prior"); suls=ncol("SU_Loss_Streak_Prior"); atsw=ncol("ATS_Win_Streak_Prior"); atsl=ncol("ATS_Loss_Streak_Prior")
    psuw=ncol("Prev_SU_Win"); psul=ncol("Prev_SU_Loss"); pmar=ncol("Prev_SU_Margin"); ppf=ncol("Prev_Points_For"); patsw=ncol("Prev_ATS_Win"); patsl=ncol("Prev_ATS_Loss")
    pdog=ncol("Prev_Is_ML_Dog"); pfav=ncol("Prev_Is_ML_Favorite")
    revcur=ncol("Revenge_Flag_Current"); opprev=ncol("Opp_Revenge_Flag_Current"); h2hm=ncol("Last_Matchup_SU_Margin_System"); h2hhome=ncol("MMI_Last_Matchup_Is_Home_System"); h2hpf=ncol("MMI_Last_Matchup_Points_For_System")
    oppwin=ncol("Opp_Prev_SU_Win"); opploss=ncol("Opp_Prev_SU_Loss"); oppatsloss=ncol("Opp_Prev_ATS_Loss"); oppwp=ncol("Opp_WinPct_Prior_System"); oppats=ncol("MMI_Opp_ATS_WinPct_Prior_System")
    oppplay=ncol("Opponent_Prior_Season_Playoff"); first_home=ncol("MMI_First_Home_Game_System"); first_road=ncol("MMI_First_Road_Game_System")

    # Schedule position.
    add_atom("GAME_1","schedule",game_no.eq(1),"team game 1")
    add_atom("GAME_2","schedule",game_no.eq(2),"team game 2")
    add_atom("GAME_7_PLUS","schedule",game_no.ge(7),"team game 7+")
    add_atom("FIRST_HOME_GAME","schedule_location",first_home.eq(1),"first home game of season")
    add_atom("FIRST_ROAD_GAME","schedule_location",first_road.eq(1),"first road game / travel opener")
    add_atom("WEEK_1","week",week.eq(1),"Week 1")
    add_atom("WEEK_2","week",week.eq(2),"Week 2")
    add_atom("REGULAR_SEASON","season_stage",regular.eq(1)&post.fillna(0).ne(1),"regular season")
    add_atom("BOWL_OR_CFP","season_stage",bowl.eq(1)|post.eq(1),"bowl/CFP/postseason")

    # Rest and sequencing.
    add_atom("REST_8_PLUS","rest",rest.ge(8),"8+ days rest")
    add_atom("SHORT_REST_6_OR_LESS","rest",rest.le(6)&rest.notna(),"6 or fewer days rest")
    add_atom("OFF_BYE","rest",bye.eq(1),"off a bye/extra-rest game")
    add_atom("REST_ADVANTAGE_2_PLUS","rest_matchup",rest.notna()&opp_rest.notna()&(rest-opp_rest).ge(2),"2+ day rest advantage")
    add_atom("OPP_SHORT_REST_6_OR_LESS","opponent_activity",opp_rest.le(6)&opp_rest.notna(),"opponent active on short rest")
    add_atom("SU_WIN_STREAK_2_PLUS","sequence",suws.ge(2),"2+ straight SU wins")
    add_atom("SU_LOSS_STREAK_2_PLUS","sequence",suls.ge(2),"2+ straight SU losses")

    # Prior SU result.
    add_atom("OFF_SU_WIN","prior_su",psuw.eq(1),"off SU win")
    add_atom("OFF_SU_LOSS","prior_su",psul.eq(1),"off SU loss")
    add_atom("OFF_UPSET_WIN","prior_su_role",psuw.eq(1)&pdog.eq(1),"off upset win as underdog")
    add_atom("OFF_UPSET_LOSS_AS_FAVORITE","prior_su_role",psul.eq(1)&pfav.eq(1),"off upset loss as favorite")
    add_atom("OFF_BLOWOUT_WIN_14_PLUS","prior_margin",pmar.ge(14),"off SU win by 14+")
    add_atom("OFF_BLOWOUT_LOSS_14_PLUS","prior_margin",pmar.le(-14),"off SU loss by 14+")
    add_atom("OFF_BLOWOUT_LOSS_21_PLUS","prior_margin",pmar.le(-21),"off SU loss by 21+")
    add_atom("OFF_SHUTOUT_LOSS","prior_margin",psul.eq(1)&ppf.eq(0),"off shutout loss")
    three_upset=(psuw.eq(1)&ncol("Prev2_SU_Win").eq(1)&ncol("Prev3_SU_Win").eq(1)&pdog.eq(1)&ncol("Prev2_Is_ML_Dog").eq(1)&ncol("Prev3_Is_ML_Dog").eq(1))
    add_atom("THREE_STRAIGHT_UPSET_WINS","prior_sequence",three_upset,"three consecutive upset wins")

    # Prior ATS result / combined sequences.
    add_atom("OFF_ATS_WIN","prior_ats",patsw.eq(1),"off ATS win")
    add_atom("OFF_ATS_LOSS","prior_ats",patsl.eq(1),"off ATS loss")
    add_atom("OFF_SU_AND_ATS_WIN","prior_combo",psuw.eq(1)&patsw.eq(1),"off SU + ATS win")
    add_atom("OFF_SU_AND_ATS_LOSS","prior_combo",psul.eq(1)&patsl.eq(1),"off SU + ATS loss")
    add_atom("BACK_TO_BACK_ATS_LOSSES","prior_ats_sequence",atsl.ge(2),"back-to-back ATS losses")
    three_suats=(psuw.eq(1)&ncol("Prev2_SU_Win").eq(1)&ncol("Prev3_SU_Win").eq(1)&patsw.eq(1)&ncol("Prev2_ATS_Win").eq(1)&ncol("Prev3_ATS_Win").eq(1))
    add_atom("THREE_STRAIGHT_SU_ATS_WINS","prior_ats_sequence",three_suats,"three straight SU + ATS wins")

    # Revenge.
    add_atom("REVENGE","revenge",revcur.eq(1),"revenge for prior loss to same opponent")
    add_atom("REVENGE_PRIOR_HOME_LOSS","revenge_detail",revcur.eq(1)&h2hhome.eq(1)&h2hm.lt(0),"revenge after prior home loss")
    add_atom("REVENGE_BLOWOUT_14_PLUS","revenge_detail",revcur.eq(1)&h2hm.le(-14),"revenge after 14+ point loss")
    add_atom("REVENGE_SHUTOUT","revenge_detail",revcur.eq(1)&h2hpf.eq(0)&h2hm.lt(0),"revenge after being shut out")
    add_atom("OPPONENT_ALSO_REVENGE","opponent_revenge",opprev.eq(1),"opponent also has revenge")

    # Current market role.
    add_atom("CURRENT_DOG","market_role",spread.gt(0),"current underdog")
    add_atom("CURRENT_FAVORITE","market_role",spread.lt(0),"current favorite")
    add_atom("CURRENT_PICKEM","market_role",spread.abs().le(0.5)&spread.notna(),"pick'em / near PK")
    add_atom("HOME","location",home.eq(1),"home team")
    add_atom("ROAD","location",home.eq(0),"road team")
    add_atom("DOG_9_5_OR_LESS","market_band",spread.gt(0)&spread.le(9.5),"underdog +9.5 or less")
    add_atom("FAVORITE_7_PLUS","market_band",spread.le(-7),"favorite -7 or more")
    add_atom("POSTSEASON_DOG_OVER_18","market_band",post.eq(1)&spread.gt(18),"postseason dog > +18")
    add_atom("SPREAD_GREATER_THAN_MINUS14","market_constraint",spread.gt(-14)&spread.notna(),"spread > -14")

    # Opponent state.
    add_atom("OPP_OFF_SU_WIN","opponent_state",oppwin.eq(1),"opponent off SU win")
    add_atom("OPP_OFF_SU_LOSS","opponent_state",opploss.eq(1),"opponent off SU loss")
    add_atom("OPP_OFF_SU_ATS_LOSS","opponent_combo",opploss.eq(1)&oppatsloss.eq(1),"opponent off SU + ATS loss")
    add_atom("OPP_WINNING_RECORD","opponent_record",oppwp.ge(0.5),"opponent winning record")
    add_atom("OPP_LOSING_RECORD","opponent_record",oppwp.lt(0.5)&oppwp.notna(),"opponent losing record")
    add_atom("OPP_PRIOR_PLAYOFF_TEAM","opponent_status",oppplay.eq(1),"opponent prior-season playoff team")
    add_atom("OPP_ATS_55_PLUS","opponent_ats",oppats.ge(0.55),"opponent prior ATS >=55%")
    add_atom("OPP_ATS_45_OR_LESS","opponent_ats",oppats.le(0.45)&oppats.notna(),"opponent prior ATS <=45%")

    # Key-number state may become a contextual filter in a discovered system.
    for k in (3,7,10,14):
        add_atom(f"CROSSED_KEY_{k}_60M","key",ncol(f"key{k}").gt(0),f"crossed key {k} in last 60m")

    def conf_norm(vals):
        s=pd.Series(vals,index=g.index,dtype="string").fillna("").str.lower().str.replace("_"," ",regex=False).str.replace("-"," ",regex=False).str.strip()
        out=pd.Series("OTHER",index=g.index,dtype="string")
        out.loc[s.str.contains(r"\bacc\b|atlantic coast",regex=True)]= "ACC"
        out.loc[s.str.contains(r"big\s*12|big twelve",regex=True)]= "BIG12"
        out.loc[s.str.contains(r"\bsec\b|southeastern",regex=True)]= "SEC"
        out.loc[s.str.contains(r"sun\s*belt",regex=True)]= "SUNBELT"
        out.loc[s.str.contains(r"conference\s*usa|c\s*usa|\bcusa\b",regex=True)]= "CUSA"
        out.loc[s.str.contains(r"pac\s*10",regex=True)]= "PAC10"
        out.loc[s.str.contains(r"pac\s*12",regex=True)]= "PAC12"
        return out
    tc=conf_norm(g["team_conf"]); oc=conf_norm(g["opp_conf"])
    for c in ("ACC","BIG12","SEC","SUNBELT","CUSA","PAC10","PAC12"):
        add_atom(f"TEAM_CONF_{c}","team_conference",tc.eq(c),f"team conference={c}")
        add_atom(f"OPP_CONF_{c}","opp_conference",oc.eq(c),f"opponent conference={c}")
    add_atom("TEAM_BIG12_VS_SEC","conference_matchup",tc.eq("BIG12")&oc.eq("SEC"),"Big 12 team vs SEC opponent")
    add_atom("TEAM_SEC_VS_BIG12","conference_matchup",tc.eq("SEC")&oc.eq("BIG12"),"SEC team vs Big 12 opponent")

    # Team identity is allowed as a database filter, Big-Al style, but it carries a
    # higher validation burden and cannot become production-authoritative here.
    team_series=pd.Series(g["team"],index=g.index,dtype="string").fillna("").str.lower().str.strip()
    counts=team_series.value_counts()
    for team_token,cnt in counts.head(V13213_MMI_BIGAL_MAX_TEAM_ATOMS).items():
        if not team_token or int(cnt)<V13213_MMI_BIGAL_MIN_TEAM_GAMES: continue
        label=re.sub(r"[^a-z0-9]+","_",str(team_token)).strip("_").upper()[:42]
        add_atom(f"TEAM_{label}","team_identity",team_series.eq(team_token),f"team={team_token}",team_specific=True)

    cat_counts={}
    for a in atoms: cat_counts[a["category"]]=cat_counts.get(a["category"],0)+1
    log_func(f"[MMI-BIGAL-ATOM-INVENTORY] atoms={len(atoms)} categories={cat_counts} team_identity_atoms={sum(int(a['team_specific']) for a in atoms)} conference_membership=AS_OF_GAME_CONTEXT leakage_contract=PRE_GAME_ONLY")

    def selection_rank(mask,score,clause_count,team_specific=False):
        sub=_dedup(mask,score)
        if sub.empty: return None
        sub=sub.loc[sub["selection"].astype(bool)].copy()
        yv=pd.to_numeric(sub["y"],errors="coerce"); sub=sub.loc[yv.isin([0,1])].copy(); yv=pd.to_numeric(sub["y"],errors="coerce").astype(int).to_numpy()
        min_n=V13213_MMI_BIGAL_MIN_DISCOVERY_SELECTION_GAMES + V13213_MMI_BIGAL_EXTRA_GAMES_PER_CLAUSE*max(0,int(clause_count)-1)
        if team_specific: min_n+=V13213_MMI_BIGAL_TEAM_EXTRA_SELECTION_GAMES
        if len(yv)<min_n: return None
        raw=float(yv.mean()); direction="PLAY_ON_MOVED_TEAM" if raw>=0.50 else "FADE_MOVED_TEAM"; yd=yv if direction=="PLAY_ON_MOVED_TEAM" else 1-yv
        hit=float(yd.mean()); ci=_v13213_wilson_interval(int(yd.sum()),len(yd))
        p0=pd.to_numeric(sub["base"],errors="coerce").to_numpy(float); wt=np.ones(len(yd),dtype=float)
        beta,bm,fm=_v13213_choose_move_beta(yv,p0,wt)
        if direction=="PLAY_ON_MOVED_TEAM" and beta<0: beta=0.0
        if direction=="FADE_MOVED_TEAM" and beta>0: beta=0.0
        p1=_v13_sigmoid(_v13_logit(np.clip(p0,1e-5,1-1e-5))+beta)
        fm=_v13213_move_research_metrics(yv,p1,wt); bm=_v13213_move_research_metrics(yv,p0,wt)
        llg=float(bm.get("logloss",np.nan)-fm.get("logloss",np.nan)); brg=float(bm.get("brier",np.nan)-fm.get("brier",np.nan))
        # Selection-only beam score. Complexity and team-identity filters are penalized
        # so the search prefers broad, reproducible situations over tiny curiosities.
        quality=(hit-0.50)*np.sqrt(len(yd))*5.0 + max(0.0,llg if np.isfinite(llg) else 0.0)*120.0 + max(0.0,brg if np.isfinite(brg) else 0.0)*160.0
        quality-=0.10*float(clause_count); quality-=0.20*float(team_specific)
        if hit<V13213_MMI_BIGAL_MIN_SELECTION_DIRECTIONAL_ATS: quality-=0.50
        return {"selection_games":int(len(yd)),"selection_directional_ats":hit,"selection_ci95":ci,"direction":direction,"beta":float(beta),"selection_ll_gain":llg,"selection_brier_gain":brg,"quality":float(quality)}

    discovery_anchors=("LINE_TOWARD_TEAM_GE_0_5","SHARP_LEAD_TOWARD","PERSISTENT_LINE_TOWARD","KEY_CROSS_TOWARD","PRICE_TOWARD_TEAM_GE_1PCT")
    discovered=[]; tested_candidates=0
    for anchor in discovery_anchors:
        amask,ascore=patterns[anchor]
        beam=[]; seen=set(); all_survivors=[]
        # Depth 1.
        for i,a in enumerate(atoms):
            mask=amask&a["mask"]
            rec=selection_rank(mask,ascore+a["mask"].astype(float),1,a["team_specific"]); tested_candidates+=1
            if rec is None: continue
            state={"atom_idx":(i,),"atoms":(a["name"],),"categories":(a["category"],),"mask":mask,"score":ascore+a["mask"].astype(float),"team_specific":a["team_specific"],**rec}
            beam.append(state); seen.add(state["atoms"])
        beam=sorted(beam,key=lambda r:(r["quality"],r["selection_games"]),reverse=True)[:V13213_MMI_BIGAL_BEAM_WIDTH]
        all_survivors.extend(beam)
        # Add one new category at a time; no same-category stacking such as HOME+ROAD.
        for depth in range(2,V13213_MMI_BIGAL_MAX_CONTEXT_CLAUSES+1):
            nxt=[]
            for state in beam:
                used=set(state["categories"])
                for i,a in enumerate(atoms):
                    if a["category"] in used or i in state["atom_idx"]: continue
                    names=tuple(sorted(state["atoms"]+(a["name"],)))
                    if names in seen: continue
                    seen.add(names)
                    mask=state["mask"]&a["mask"]
                    team_specific=bool(state["team_specific"] or a["team_specific"])
                    score=state["score"]+a["mask"].astype(float)
                    rec=selection_rank(mask,score,depth,team_specific); tested_candidates+=1
                    if rec is None: continue
                    nxt.append({"atom_idx":state["atom_idx"]+(i,),"atoms":state["atoms"]+(a["name"],),"categories":state["categories"]+(a["category"],),"mask":mask,"score":score,"team_specific":team_specific,**rec})
            beam=sorted(nxt,key=lambda r:(r["quality"],r["selection_games"]),reverse=True)[:V13213_MMI_BIGAL_BEAM_WIDTH]
            if not beam: break
            all_survivors.extend(beam)
        # Shadow-evaluate only the top selection-discovered rules per anchor.
        finalists=sorted(all_survivors,key=lambda r:(r["quality"],r["selection_games"]),reverse=True)[:V13213_MMI_BIGAL_FINALISTS_PER_ANCHOR]
        for rank,state in enumerate(finalists,1):
            rule_name=f"{anchor}__"+"__".join(state["atoms"])
            r=evaluate(rule_name,state["mask"],state["score"],"DISCOVERED_SYSTEM",parent=anchor)
            r.update({"anchor":anchor,"conditions":list(state["atoms"]),"categories":list(state["categories"]),"selection_discovery_rank":int(rank),"selection_discovery_score":float(state["quality"]),"team_specific":bool(state["team_specific"])})
            # Known-system overlap by occurrence count only.
            overlaps=[]
            for nm,smask in known_system_masks.items():
                cnt=int(np.sum(np.asarray(state["mask"],dtype=bool)&np.asarray(smask,dtype=bool)))
                if cnt>0: overlaps.append((cnt,known_system_family.get(nm,""),nm))
            overlaps=sorted(overlaps,reverse=True)[:5]
            r["known_system_overlaps"]=[{"system":nm,"family":fam,"games":cnt} for cnt,fam,nm in overlaps]
            # Independent legitimacy contract for newly discovered systems.
            sel_ok=(r.get("selection_games",0)>=V13213_MMI_BIGAL_MIN_DISCOVERY_SELECTION_GAMES and np.isfinite(r.get("selection_directional_ats",np.nan)) and r.get("selection_directional_ats",0)>=V13213_MMI_BIGAL_MIN_SELECTION_DIRECTIONAL_ATS and abs(r.get("selected_beta",0.0))>1e-12 and np.isfinite(r.get("selection_ll_gain",np.nan)) and r.get("selection_ll_gain",-1)>=0 and np.isfinite(r.get("selection_brier_gain",np.nan)) and r.get("selection_brier_gain",-1)>=0)
            sh_ok=(r.get("shadow_games",0)>=V13213_MMI_BIGAL_MIN_DISCOVERY_SHADOW_GAMES and np.isfinite(r.get("shadow_directional_ats",np.nan)) and r.get("shadow_directional_ats",0)>V13213_MMI_BREAK_EVEN and np.isfinite(r.get("shadow_ll_gain",np.nan)) and r.get("shadow_ll_gain",-1)>=0 and np.isfinite(r.get("shadow_brier_gain",np.nan)) and r.get("shadow_brier_gain",-1)>=0)
            season_ok=len(r.get("seasons") or [])>=V13213_MMI_BIGAL_MIN_DISTINCT_SEASONS
            team_ok=(not r.get("team_specific")) or (r.get("games",0)>=V13213_MMI_BIGAL_TEAM_MIN_TOTAL_FOR_VALIDATION and len(r.get("seasons") or [])>=3)
            r["new_system_legit_candidate"]=bool(sel_ok and sh_ok and season_ok and team_ok and r.get("games",0)>=V13213_MMI_BIGAL_MIN_DISCOVERY_TOTAL_GAMES)
            if r["new_system_legit_candidate"]: r["discovery_status"]="LEGIT_NEW_SYSTEM_CANDIDATE_REQUIRES_INDEPENDENT_RETEST"
            elif sel_ok and not sh_ok: r["discovery_status"]="SELECTION_EDGE_FAILED_OR_INSUFFICIENT_SHADOW"
            elif sel_ok: r["discovery_status"]="SELECTION_EDGE_NOT_FULLY_VALIDATED"
            else: r["discovery_status"]="EXPLORATORY_ONLY"
            discovered.append(r)

    discovered.sort(key=lambda r:(bool(r.get("new_system_legit_candidate")),float(r.get("shadow_directional_ats",-1) if np.isfinite(r.get("shadow_directional_ats",np.nan)) else -1),float(r.get("selection_discovery_score",-999))),reverse=True)
    for r in discovered[:V13213_MMI_BIGAL_MAX_LOGGED_RULES]:
        cond=" AND ".join(r.get("conditions") or [])
        ovs=",".join(f"{x['system']}:{x['games']}" for x in (r.get("known_system_overlaps") or [])) or "NONE"
        log_func(f"[MMI-BIGAL-DISCOVERY] rank={r.get('selection_discovery_rank')} anchor={r.get('anchor')} direction={r.get('direction')} conditions=\"{cond}\" games={r.get('games',0)} seasons={r.get('seasons')} sel_games={r.get('selection_games',0)} sel_dir_ats={r.get('selection_directional_ats',np.nan):.4f} shadow_games={r.get('shadow_games',0)} shadow_dir_ats={r.get('shadow_directional_ats',np.nan):.4f} beta={r.get('selected_beta',0.0):+.2f} sel_ll={r.get('selection_ll_gain',np.nan):+.6f} shadow_ll={r.get('shadow_ll_gain',np.nan):+.6f} known_system_overlap={ovs} status={r.get('discovery_status')} production_authority=0")

    legit_new=[r["name"] for r in discovered if bool(r.get("new_system_legit_candidate"))]
    promising_new=[r["name"] for r in discovered if r.get("discovery_status") in {"SELECTION_EDGE_NOT_FULLY_VALIDATED","SELECTION_EDGE_FAILED_OR_INSUFFICIENT_SHADOW"}][:30]
    legit=[r["name"] for r in records+key_records+kept_system if bool(r.get("legit_model_candidate"))]
    promising=[r["name"] for r in records+key_records+kept_system if r.get("status") in {"PROMISING_NOT_PROVEN","VALIDATED_STANDALONE_EDGE"}]
    log_func(f"[MMI-BIGAL-DISCOVERY-SUMMARY] tested_candidates={tested_candidates} finalists={len(discovered)} legit_new_system_candidates={legit_new} promising_new_systems={promising_new} search_max_context_clauses={V13213_MMI_BIGAL_MAX_CONTEXT_CLAUSES} beam_width={V13213_MMI_BIGAL_BEAM_WIDTH} selection_only_discovery=TRUE shadow_only_validation=TRUE outer_holdout_used=FALSE production_authority=0")
    log_func(f"[MMI-DISCOVERY-SUMMARY] legit_model_candidates={legit} promising_not_admitted={promising[:20]} legit_new_system_candidates={legit_new} tested_move_patterns={len(records)} tested_key_interactions={len(key_records)} retained_system_interactions={len(kept_system)} production_authority=0 next_step={'INDEPENDENT_RETEST' if (legit or legit_new) else 'ACCUMULATE_MORE_GAMES'}")
    return {"version":V13213_MMI_VERSION,"status":"RESEARCH_COMPLETE","authority":"RESEARCH_ONLY","production_weight":0.0,
            "outer_holdout_used":False,"causality_claim":"NONE","grain":"ONE_SIDE_PER_PHYSICAL_GAME_CANDIDATE",
            "conference_membership_contract":"AS_OF_GAME_CONTEXT","selection_only_discovery":True,"shadow_only_validation":True,
            "move_patterns":records,"key_interactions":key_records,"system_interactions":kept_system[:100],
            "bigal_style_atoms":{"count":len(atoms),"categories":cat_counts},"discovered_systems":discovered[:100],
            "legit_new_system_candidates":legit_new,"promising_new_systems":promising_new,
            "legit_model_candidates":legit,"promising_candidates":promising[:100],
            "admission_contract":"PREDECLARED_MOVE_ANCHOR__BIGAL_STYLE_CONTEXT_ATOMS__BOUNDED_SELECTION_ONLY_BEAM__PHYSICAL_GAME_DEDUP__DIRECTION_FROZEN_ON_SELECTION__DISJOINT_SHADOW__ATS_AND_PROPER_SCORE_TRANSFER__OUTER_HOLDOUT_UNTOUCHED"}

def _v132_fit_post_stack_calibration(y,selection_pred,shadow_pred,select_mask,shadow_mask,w,log_func=print,component_any=True):
    y=np.asarray(y,dtype=int); ps=np.asarray(selection_pred,dtype=float); ph=np.asarray(shadow_pred,dtype=float); w=np.asarray(w,dtype=float)
    sm=np.asarray(select_mask,dtype=bool)&np.isfinite(ps); hm=np.asarray(shadow_mask,dtype=bool)&np.isfinite(ph)
    base_sel=_ncaaf_v131_calibration_metrics(y[sm],ps[sm],w[sm]); base_sh=_ncaaf_v131_calibration_metrics(y[hm],ph[hm],w[hm])
    if not component_any:
        return {"version":"2026-09-12-v13.2.13-post-stack-temperature","temperature":1.0,"selected_temperature":1.0,"shadow_transfer_pass":True,"skipped_no_active_components":True,"selection_base_metrics":base_sel,"selection_calibrated_metrics":base_sel,"shadow_base_metrics":base_sh,"shadow_calibrated_metrics":base_sh}
    best_t=1.0; best=base_sel
    for t in V132_RULE_POSTSTACK_TEMPERATURE_GRID:
        cand=_ncaaf_v131_calibration_metrics(y[sm],_ncaaf_v13_apply_temperature(ps[sm],t),w[sm])
        if _ncaaf_v131_calibration_gate(base_sel,cand) and _ncaaf_v131_calibration_rank(cand)<_ncaaf_v131_calibration_rank(best):
            best_t=float(t); best=cand
    shcand=_ncaaf_v131_calibration_metrics(y[hm],_ncaaf_v13_apply_temperature(ph[hm],best_t),w[hm]) if hm.any() else base_sh
    transfer=bool(best_t==1.0 or (hm.any() and _ncaaf_v131_calibration_gate(base_sh,shcand)))
    active_t=best_t if transfer else 1.0
    log_func(f"[V13.2.13-POST-STACK-CAL] selected_T={best_t:.2f} active_T={active_t:.2f} shadow_transfer={'PASS' if transfer else 'CLOSED'} sel_ll={base_sel.get('logloss',np.nan):.6f}->{best.get('logloss',np.nan):.6f} sel_ece={base_sel.get('ece',np.nan):.4f}->{best.get('ece',np.nan):.4f} shadow_ll={base_sh.get('logloss',np.nan):.6f}->{shcand.get('logloss',np.nan):.6f} shadow_ece={base_sh.get('ece',np.nan):.4f}->{shcand.get('ece',np.nan):.4f}")
    return {"version":"2026-09-12-v13.2.13-post-stack-temperature","temperature":float(active_t),"selected_temperature":float(best_t),"shadow_transfer_pass":bool(transfer),"skipped_no_active_components":False,"selection_base_metrics":base_sel,"selection_calibrated_metrics":best,"shadow_base_metrics":base_sh,"shadow_calibrated_metrics":shcand}


def _ncaaf_v13_fit_specialist_overlays(bundle: dict, train_rows: pd.DataFrame, X_train: pd.DataFrame,
                                        y_train, folds, shadow_folds=None, sample_weight=None, log_func=print,
                                        base_override=None):
    """Fit Market/Pathi/BigAl specialists and admit only incremental OOS authority.

    AutoFS sees only one family at a time. Selection folds are physical-game
    grouped and chronological. The final combiner must then improve proper scores
    on a later, disjoint physical-game shadow lane or every specialist weight is
    zeroed.
    """
    if not isinstance(bundle,dict) or train_rows is None or X_train is None or X_train.empty:
        return bundle
    y=np.asarray(y_train,dtype=int).reshape(-1)
    if len(y)!=len(X_train) or len(y)!=len(train_rows):
        log_func("[V13-SPECIALISTS] skipped=ROW_ALIGNMENT_MISMATCH")
        return bundle
    sw=np.ones(len(y),dtype=float) if sample_weight is None else np.asarray(sample_weight,dtype=float).reshape(-1)
    if len(sw)!=len(y): sw=np.ones(len(y),dtype=float)

    # A physical game can have many side/book/snapshot rows. Without balancing,
    # games with more captured market observations get more influence over AutoFS,
    # specialist fitting, and proper-score gates. Preserve the existing reliability
    # weights while making total weight approximately equal per physical game.
    if "Merge_Key_Short" in train_rows.columns:
        _spec_groups=train_rows["Merge_Key_Short"].astype(str).str.lower().str.strip().to_numpy(dtype=object)
    elif "Game_Key" in train_rows.columns:
        _spec_groups=train_rows["Game_Key"].astype(str).str.lower().str.strip().to_numpy(dtype=object)
    else:
        _spec_groups=np.asarray([f"row_{i}" for i in range(len(y))],dtype=object)
    _spec_counts=pd.Series(_spec_groups).groupby(pd.Series(_spec_groups),sort=False).transform("count").to_numpy(dtype=float)
    sw_spec=sw/np.maximum(_spec_counts,1.0)
    _sw_sum=float(np.sum(sw)); _sws_sum=float(np.sum(sw_spec))
    if _sws_sum>0 and _sw_sum>0:
        sw_spec=sw_spec*(_sw_sum/_sws_sum)
    log_func(
        f"[V13-SPECIALIST-WEIGHTING] rows={len(y)} physical_games={len(pd.unique(_spec_groups))} "
        f"mode=BASE_WEIGHT_X_INVERSE_GAME_ROW_COUNT mean_rows_per_game={float(np.mean(_spec_counts)):.2f}"
    )

    base,maturity=_ncaaf_v13_preoverlay_oof_for_rows(train_rows,bundle)
    if base_override is not None:
        _bo=np.asarray(base_override,dtype=float).reshape(-1)
        if len(_bo)==len(base):
            _use=np.isfinite(_bo)
            base=np.where(_use,_bo,base)
            log_func(f"[V13-SPECIALIST-BASE] source=V13_PLUS_AUTOFS_CORE rows={int(_use.sum())}/{len(base)}")
    select_mask=np.zeros(len(y),dtype=bool); shadow_mask=np.zeros(len(y),dtype=bool)
    for _,va in list(folds or []): select_mask[np.asarray(va,dtype=int)]=True
    for _,va in list(shadow_folds or []): shadow_mask[np.asarray(va,dtype=int)]=True
    base_ok=np.isfinite(base)
    selection_base_ok=base_ok&select_mask
    if int(selection_base_ok.sum())<V13_SPECIALIST_MIN_OOF_ROWS:
        log_func(f"[V13-SPECIALISTS] gate=CLOSED reason=INSUFFICIENT_V13_BASE_OOF matched={int(selection_base_ok.sum())}/{len(base)}")
        bundle["specialist_overlays"]={"version":V13_SPECIALIST_OVERLAY_VERSION,"gate_pass":False,"final_gate_pass":False,
            "status":"INSUFFICIENT_V13_BASE_OOF","weights":{"Market":0.0,"Pathi":0.0,"BigAl":0.0},"centers":{"Market":0.5,"Pathi":0.5,"BigAl":0.5},"families":{}}
        return bundle

    try:
        threads=max(1,int(os.getenv("AUTOFS_XGB_THREADS",str(min(4,os.cpu_count() or 1)))))
    except Exception:
        threads=min(4,os.cpu_count() or 1)

    family_probs={}; family_shadow_probs={}; family_artifacts={}; family_centers={}
    max_feats={"Market":36,"Pathi":24,"BigAl":24}

    # Source boundary:
    #   Market  -> ONLY the already-vetted deployment matrix.
    #   Pathi/BigAl -> deployment matrix plus vetted raw named-system predictors.
    # This prevents future Brain_Target_* / closing/oracle columns in train_rows
    # from ever reaching the V13 specialist selector.
    _x_cols=list(X_train.columns)
    _named_safe_extra=[
        c for c in pathi_bigal_numeric_feature_cols(train_rows)
        if c not in X_train.columns
    ]
    _brain_targets_present=[c for c in train_rows.columns if str(c).startswith("Brain_Target_")]
    log_func(
        f"[V13-SPECIALIST-SOURCE-CONTRACT] xtrain_cols={len(_x_cols)} "
        f"named_safe_extras={len(_named_safe_extra)} brain_future_targets_present={len(_brain_targets_present)} "
        f"brain_future_targets_eligible=0 market_train_rows_extras=0"
    )

    for fam in ("Market","Pathi","BigAl"):
        _source_pairs=[(c,"X_train") for c in _x_cols]
        if fam in ("Pathi","BigAl"):
            _source_pairs += [(c,"train_rows_named_safe") for c in _named_safe_extra]
        _seen=set(); _eligible_pairs=[]; _blocked_names=[]
        for c,_source in _source_pairs:
            if c in _seen:
                continue
            _seen.add(c)
            if _ncaaf_v13_specialist_family(c)!=fam:
                continue
            if _head_forbidden_feature(c,"outcome") or _is_hard_leak_feature(c):
                _blocked_names.append(str(c)); continue
            if not _ncaaf_v13_specialist_feature_safe(c,fam,_source):
                _blocked_names.append(str(c)); continue
            _eligible_pairs.append((c,_source))
        candidates=[c for c,_ in _eligible_pairs]
        _candidate_source={c:s for c,s in _eligible_pairs}
        log_func(
            f"[V13-SPECIALIST-SOURCE] family={fam} eligible={len(candidates)} "
            f"blocked={len(_blocked_names)} from_xtrain={sum(1 for c in candidates if _candidate_source.get(c)=='X_train')} "
            f"from_named_safe={sum(1 for c in candidates if _candidate_source.get(c)=='train_rows_named_safe')}"
        )
