    def _prep_team_context(df):
        # LOO/streak/schedule context does not need the hundreds of columns in the
        # full training view.  For one-market Cloud Run jobs, slice the market
        # BEFORE copying and retain only the columns these calculations consume.
        base = df
        if return_artifacts:
            _requested_ctx = _norm_market(str(market).lower())
            base = base.loc[base['Market'].astype(str).str.lower().str.strip().map(_norm_market).eq(_requested_ctx)]

        _prob_candidates_local = [
            'Model_Sharp_Win_Prob', 'Model_Outcome_Prob', 'Model_Prob', 'Pred_Prob'
        ]
        _need = [
            'Sport','Market','Game_Key','Outcome','Home_Team_Norm','Away_Team_Norm',
            'Value','Odds_Price','Game_Start','feat_Game_Start','Snapshot_Timestamp',
            'SHARP_HIT_BOOL','Is_ML_Favorite'
        ] + _prob_candidates_local
        _keep = [c for c in dict.fromkeys(_need) if c in base.columns]
        out = base.loc[:, _keep].copy()
        out['Market']         = out['Market'].astype(str).str.lower().str.strip()
        out['Outcome_Norm']   = out['Outcome'].astype(str).str.lower().str.strip()
        out['Home_Team_Norm'] = out['Home_Team_Norm'].astype(str).str.lower().str.strip()
        out['Away_Team_Norm'] = out['Away_Team_Norm'].astype(str).str.lower().str.strip()
    
        is_totals = out['Market'].eq('totals')
        # Team identity (consistent with your training logic)
        out['Team'] = out['Outcome_Norm'].where(~is_totals, out['Home_Team_Norm']).astype(str).str.strip()
        out['Is_Home'] = np.where(is_totals, 1, (out['Team'] == out['Home_Team_Norm']).astype(int)).astype(int)
    
        # Favorite context:
        #   spreads -> signed spread value
        #   h2h     -> paired/de-vig role from Pathi/BigAl state when available,
        #              otherwise American-price sign as a fallback
        #   totals  -> OVER as the canonical side
        is_h2h = out['Market'].eq('h2h')
        spread_fav = (pd.to_numeric(out['Value'], errors='coerce') < 0).astype(int)
        if 'Is_ML_Favorite' in out.columns:
            h2h_fav = pd.to_numeric(out['Is_ML_Favorite'], errors='coerce')
        else:
            h2h_fav = pd.Series(np.nan, index=out.index)
        h2h_fav = h2h_fav.where(
            h2h_fav.notna(),
            (pd.to_numeric(out.get('Odds_Price'), errors='coerce') < 0).astype(float)
        ).fillna(0).astype(int)
        out['Is_Favorite_Context'] = np.select(
            [is_totals, is_h2h],
            [(out['Outcome_Norm'] == 'over').astype(int), h2h_fav],
            default=spread_fav
        ).astype(int)
        return out
    
