        # ================================================================
        # V11 AI BRAIN AUDIT — feature population, logic, targets, examples
        # ================================================================
        def _audit_ai_brain_frame(df_audit: pd.DataFrame, market_name: str, max_review_rows: int = 30):
            """Diagnostic-only audit for V11 Brain_* features and training targets.

            This function NEVER mutates training data and its outputs are not offered
            to AutoFS.  It is intentionally verbose so Cloud Run logs can verify that
            the AI-brain layer attached and populated correctly before model fitting.
            """
            try:
                if df_audit is None:
                    print("[BRAIN-AUDIT] SKIP - dataframe is None")
                    return

                brain_cols_all = [c for c in df_audit.columns if str(c).startswith("Brain_")]
                target_cols = [c for c in brain_cols_all if str(c).startswith("Brain_Target_")]
                predictor_brain_cols = [c for c in brain_cols_all if c not in target_cols]

                print("\n" + "=" * 100)
                print(f"AI BRAIN AUDIT | market={str(market_name).upper()} | rows={len(df_audit):,}")
                print("=" * 100)
                print(f"[BRAIN-QUICK] Brain columns found={len(brain_cols_all)} predictors={len(predictor_brain_cols)} targets={len(target_cols)}")

                # 1) Duplicate / merge-corruption check.
                dup_named = [c for c in df_audit.columns if str(c).endswith("_x") or str(c).endswith("_y")]
                duplicate_labels = df_audit.columns[df_audit.columns.duplicated()].tolist()
                print("\n[BRAIN-AUDIT:DUPLICATES]")
                print(f"_x/_y columns={len(dup_named)}" + (f" sample={dup_named[:20]}" if dup_named else " PASS"))
                print(f"duplicate column labels={len(duplicate_labels)}" + (f" sample={duplicate_labels[:20]}" if duplicate_labels else " PASS"))

                # 2) Population / distribution check for every Brain predictor.
                print("\n[BRAIN-AUDIT:POPULATION]")
                pop_rows = []
                for c in predictor_brain_cols:
                    s = pd.to_numeric(df_audit[c], errors="coerce")
                    pop_rows.append({
                        "Feature": c,
                        "NonNullPct": round(float(s.notna().mean() * 100.0), 2),
                        "NonZeroPct": round(float((s.fillna(0) != 0).mean() * 100.0), 2),
                        "Min": float(s.min()) if s.notna().any() else np.nan,
                        "Mean": float(s.mean()) if s.notna().any() else np.nan,
                        "Max": float(s.max()) if s.notna().any() else np.nan,
                        "Unique": int(s.nunique(dropna=True)),
                    })
                if pop_rows:
                    pop_df = pd.DataFrame(pop_rows).sort_values("Feature")
                    print(pop_df.to_string(index=False))
                    dead = pop_df[(pop_df["NonNullPct"] == 0) | (pop_df["NonZeroPct"] == 0)]
                    if len(dead):
                        print("[BRAIN-AUDIT:POPULATION-WARN] zero/unpopulated features:")
                        print(dead[["Feature","NonNullPct","NonZeroPct"]].to_string(index=False))
                else:
                    print("FAIL - no non-target Brain_* predictor columns found")

                # 3) Mechanical range checks. Current V11 strength measures are unsigned 0..1.
                binary_cols = [
                    "Brain_Regime_EarlySeason", "Brain_Regime_MatureSeason", "Brain_Regime_LateSeason",
                    "Brain_Regime_QuietMarket", "Brain_Regime_ActiveMarket", "Brain_Regime_SteamMarket",
                    "Brain_Regime_KeyNumberMarket", "Brain_BigAl_Pathi_Agreement", "Brain_BigAl_Pathi_Conflict",
                    "Brain_BigAl_Market_Agreement", "Brain_BigAl_Market_Conflict",
                    "Brain_Pathi_Market_Agreement", "Brain_Pathi_Market_Conflict",
                    "Brain_AllIndependent_Agree",
                    "Brain_Expert_BigAl_Active", "Brain_Expert_Pathi_Active", "Brain_Expert_Market_Active",
                    "Brain_Expert_Power_Active", "Brain_Expert_Form_Active", "Brain_Expert_Schedule_Active",
                    "Brain_Expert_Price_Active", "Brain_Expert_Historical_Active",
                ]
                unit_cols = [
                    "Brain_Expert_BigAl_Strength", "Brain_Expert_BigAl_Readiness",
                    "Brain_Expert_Pathi_Strength", "Brain_Expert_Market_Strength",
                    "Brain_Expert_Power_Strength", "Brain_Expert_Form_Strength",
                    "Brain_Expert_Schedule_Strength", "Brain_Expert_Price_Strength", "Brain_Expert_Historical_Strength",
                    "Brain_Expert_Mean_Strength", "Brain_Expert_Max_Strength",
                    "Brain_Expert_Dispersion", "Brain_Uncertainty_Proxy",
                    "Brain_Decision_Readiness", "Brain_Current_Implied_Prob",
                    "Brain_Expert_BigAl_Intensity", "Brain_Expert_Pathi_Intensity", "Brain_Expert_Market_Intensity",
                    "Brain_Expert_Power_Intensity", "Brain_Expert_Form_Intensity", "Brain_Expert_Schedule_Intensity",
                    "Brain_Expert_Price_Intensity", "Brain_Expert_Historical_Intensity", "Brain_Directional_Agreement_Rate",
                ]

                def _range_check(col, lo, hi):
                    if col not in df_audit.columns:
                        print(f"MISSING - {col}")
                        return
                    s = pd.to_numeric(df_audit[col], errors="coerce")
                    bad = s.notna() & ((s < lo) | (s > hi))
                    if bad.any():
                        print(f"FAIL - {col}: bad={int(bad.sum())} expected=[{lo},{hi}] min={s.min()} max={s.max()}")
                    else:
                        print(f"PASS - {col} range=[{lo},{hi}] observed_min={s.min()} observed_max={s.max()}")

                print("\n[BRAIN-AUDIT:RANGES]")
                for c in binary_cols:
                    _range_check(c, 0, 1)
                for c in unit_cols:
                    _range_check(c, 0, 1)
                for c in [
                    "Brain_Expert_BigAl_Direction", "Brain_Expert_Pathi_Direction", "Brain_Expert_Market_Direction",
                    "Brain_Expert_Power_Direction", "Brain_Expert_Form_Direction", "Brain_Expert_Schedule_Direction",
                    "Brain_Expert_Price_Direction", "Brain_Expert_Historical_Direction",
                ]:
                    _range_check(c, -1, 1)
                _range_check("Brain_Conflict_Count", 0, 3)
                _range_check("Brain_Directional_Pair_Count", 0, 3)
                _range_check("Brain_Expert_Active_Count", 0, 8)
                _range_check("Brain_Edge_Durability", 0, 100)

                # 4) Internal logic contradictions.
                print("\n[BRAIN-AUDIT:LOGIC]")
                season_cols = ["Brain_Regime_EarlySeason", "Brain_Regime_MatureSeason", "Brain_Regime_LateSeason"]
                if all(c in df_audit.columns for c in season_cols):
                    season_sum = df_audit[season_cols].apply(pd.to_numeric, errors="coerce").fillna(0).sum(axis=1)
                    print(f"season-stage rows with >1 active regime={int((season_sum > 1).sum())}")
                if {"Brain_Regime_QuietMarket", "Brain_Regime_ActiveMarket"}.issubset(df_audit.columns):
                    q = pd.to_numeric(df_audit["Brain_Regime_QuietMarket"], errors="coerce").fillna(0).eq(1)
                    a = pd.to_numeric(df_audit["Brain_Regime_ActiveMarket"], errors="coerce").fillna(0).eq(1)
                    print(f"rows both Quiet AND Active={int((q & a).sum())}")
                for agree, conflict in [
                    ("Brain_BigAl_Pathi_Agreement", "Brain_BigAl_Pathi_Conflict"),
                    ("Brain_BigAl_Market_Agreement", "Brain_BigAl_Market_Conflict"),
                    ("Brain_Pathi_Market_Agreement", "Brain_Pathi_Market_Conflict"),
                ]:
                    if agree in df_audit.columns and conflict in df_audit.columns:
                        aa = pd.to_numeric(df_audit[agree], errors="coerce").fillna(0).eq(1)
                        cc = pd.to_numeric(df_audit[conflict], errors="coerce").fillna(0).eq(1)
                        print(f"{agree} AND {conflict} simultaneously={int((aa & cc).sum())}")

                # 5) Historical target availability and oracle distribution.
                print("\n[BRAIN-AUDIT:TARGETS]")
                if target_cols:
                    for c in sorted(target_cols):
                        s = pd.to_numeric(df_audit[c], errors="coerce")
                        print(
                            f"{c}: nonnull={int(s.notna().sum()):,}/{len(s):,} ({s.notna().mean()*100:.2f}%) "
                            f"min={s.min()} mean={s.mean()} max={s.max()}"
                        )
                else:
                    print("No Brain_Target_* columns found")
                if "Brain_Target_Action_Oracle" in df_audit.columns:
                    _oracle_num = pd.to_numeric(df_audit["Brain_Target_Action_Oracle"], errors="coerce")
                    if _oracle_num.notna().any():
                        print("Oracle action distribution (0=PASS, 1=WAIT, 2=BET_NOW):")
                        print(_oracle_num.value_counts(dropna=False).sort_index().to_string())
                        if "Sport" in df_audit.columns:
                            _oracle_view = df_audit[["Sport"]].copy()
                            _oracle_view["Brain_Target_Action_Oracle"] = _oracle_num
                            print("Oracle action distribution by sport:")
                            print(pd.crosstab(_oracle_view["Sport"], _oracle_view["Brain_Target_Action_Oracle"], dropna=False).to_string())
                    else:
                        print("Oracle action targets: SKIPPED/UNAVAILABLE (all NaN; no valid future timestamp path in this slice)")

                # 6) By-sport expert summary catches routing/population failures.
                expert_summary_cols = [c for c in [
                    "Brain_Expert_BigAl_Strength", "Brain_Expert_BigAl_Readiness",
                    "Brain_Expert_Pathi_Strength", "Brain_Expert_Market_Strength",
                    "Brain_Expert_Power_Strength", "Brain_Expert_Form_Strength",
                    "Brain_Expert_Schedule_Strength", "Brain_Expert_Price_Strength",
                    "Brain_Expert_Active_Count", "Brain_Conflict_Count",
                    "Brain_Uncertainty_Proxy", "Brain_Edge_Durability", "Brain_Decision_Readiness",
                ] if c in df_audit.columns]
                if "Sport" in df_audit.columns and expert_summary_cols:
                    print("\n[BRAIN-AUDIT:BY-SPORT]")
                    tmp = df_audit[["Sport"] + expert_summary_cols].copy()
                    for c in expert_summary_cols:
                        tmp[c] = pd.to_numeric(tmp[c], errors="coerce")
                    print(tmp.groupby("Sport", dropna=False)[expert_summary_cols].agg(["mean", "median", "max"]).round(4).to_string())

                # 7) Representative rows for visual sanity-checking.
                review_cols = [c for c in [
                    "Sport", "Game_Key", "Team", "Opponent", "Market", "Outcome", "Value", "Odds_Price",
                    "BigAl_System_Count", "BigAl_Tightener_Count", "BigAl_Enhancer_Count", "BigAl_DataReady_Count",
                    "System_Net_Signal", "System_Consensus_Ratio",
                    "Brain_Regime_EarlySeason", "Brain_Regime_MatureSeason", "Brain_Regime_LateSeason",
                    "Brain_Regime_QuietMarket", "Brain_Regime_ActiveMarket", "Brain_Regime_SteamMarket",
                    "Brain_Regime_KeyNumberMarket", "Brain_Expert_BigAl_Strength", "Brain_Expert_BigAl_Readiness",
                    "Brain_Expert_BigAl_Active", "Brain_Expert_BigAl_Direction", "Brain_Expert_BigAl_Intensity",
                    "Brain_Expert_Pathi_Active", "Brain_Expert_Pathi_Direction", "Brain_Expert_Pathi_Intensity",
                    "Brain_Expert_Market_Active", "Brain_Expert_Market_Direction", "Brain_Expert_Market_Intensity",
                    "Brain_Expert_Pathi_Strength", "Brain_Expert_Market_Strength", "Brain_Expert_Power_Strength",
                    "Brain_Expert_Form_Strength", "Brain_Expert_Schedule_Strength", "Brain_Expert_Price_Strength",
                    "Brain_BigAl_Pathi_Agreement", "Brain_BigAl_Pathi_Conflict",
                    "Brain_BigAl_Market_Agreement", "Brain_BigAl_Market_Conflict",
                    "Brain_Pathi_Market_Agreement", "Brain_Pathi_Market_Conflict",
                    "Brain_Expert_Active_Count", "Brain_Conflict_Count", "Brain_Uncertainty_Proxy",
                    "Brain_Edge_Durability", "Brain_Decision_Readiness",
                    "Brain_Target_Close_Value_Delta", "Brain_Target_Close_ImpliedProb_Delta",
                    "Brain_Target_Positive_CLV", "Brain_Target_Future_Best_Value", "Brain_Target_Action_Oracle",
                ] if c in df_audit.columns]
                if review_cols and len(df_audit):
                    n = min(int(max_review_rows), len(df_audit))
                    # Use latest rows when timestamps exist; otherwise tail preserves current ordering.
                    if "Snapshot_Timestamp" in df_audit.columns:
                        order = pd.to_datetime(df_audit["Snapshot_Timestamp"], errors="coerce", utc=True).sort_values().index
                        review = df_audit.loc[order, review_cols].tail(n)
                    else:
                        review = df_audit[review_cols].tail(n)
                    print(f"\n[BRAIN-AUDIT:REPRESENTATIVE-ROWS] last {n} rows")
                    print(review.to_string(index=False))

                print("=" * 100 + "\n")
            except Exception as e:
                # Diagnostics must never abort production training.
                print(f"[BRAIN-AUDIT] WARNING - audit failed but training will continue: {type(e).__name__}: {e}")



        def _audit_pathi_bigal_brain_integrity(df_audit: pd.DataFrame, market_name: str, max_rows: int = 12):
            """Cross-check raw Pathi + Big Al system layers against the V11.2 Brain state.

            Diagnostic only.  It does not mutate the frame and never becomes a model feature.
            """
            try:
                print("\n" + "="*100)
                print(f"PATHI + BIG AL + BRAIN INTEGRITY AUDIT | V12.0.2 NCAAF STAT + NULLABLE STATE + PAIRED PROMOTION + AUDIT | market={str(market_name).upper()} | rows={len(df_audit):,}")
                print("="*100)

                def nser(c, default=0.0):
                    if c in df_audit.columns:
                        return pd.to_numeric(df_audit[c], errors='coerce').fillna(default)
                    return pd.Series(default, index=df_audit.index, dtype='float64')

                def nonzero(c):
                    s=nser(c)
                    return int(s.ne(0).sum())

                # ---------- inventory ----------
                pathi_cols=[c for c in df_audit.columns if str(c).startswith('Pathi_')]
                bigal_cols=[c for c in df_audit.columns if str(c).startswith('BigAl_') and not _is_retired_bigal_feature_name(c)]
                brain_cols=[c for c in df_audit.columns if str(c).startswith('Brain_') and not str(c).startswith('Brain_Target_')]
                print("[PBB-AUDIT:INVENTORY]")
                print(f"Pathi columns={len(pathi_cols)} | BigAl active-contract columns={len(bigal_cols)} | Brain predictors={len(brain_cols)}")

                # ---------- exact aggregate-count reconstruction ----------
                pathi_signals=[c for c in PATHI_EXACT_SIGNAL_COLS if c in df_audit.columns]
                bigal_exact=[c for c in [
                    'BigAl_NFL1_Week1FadePlayoffTeam','BigAl_NFL2_LateSeasonHomeDog','BigAl_NFL3_PlayoffHighScoreFade',
                    'BigAl_NFL4_PreseasonContrarianMove','BigAl_NFL5_PreseasonLowOffenseOver',
                    'BigAl_CF1_Week2Home42Win','BigAl_CF2_LateSeasonRevengeDog',
                    'BigAl_NBA1_B2BRematchRoadDog','BigAl_NBA2_ThreeMassiveCovers','BigAl_NBA3_FadeHomeAfterChampUpset',
                    'BigAl_NBA4_FinalHomeFavRevenge','BigAl_NBA5_PlayoffBigDogVsChamp','BigAl_NBA6_FinalsGame4',
                    'BigAl_NBA7_TwoTeamEliminationUnder','BigAl_NBA8_Revenge145FadeFavorite',
                    'BigAl_CBB1_UglyDog20Losses','BigAl_CBB2_Fade10WinStreakFavorite','BigAl_CBB3_HomeRevenge27',
                    'BigAl_CFL1_SecondMeetingUnder','BigAl_CFL2_EliteDogFade','BigAl_CFL3_ThirdMeetingAwayDogLostFirstTwo'
                ] if c in df_audit.columns and not _is_retired_bigal_feature_name(c)]
                bigal_tight=[c for c in df_audit.columns if str(c).startswith('BigAl_') and str(c).endswith('_Tightener') and not _is_retired_bigal_feature_name(c)]
                bigal_enh=[c for c in BIGAL_ENHANCER_COLS if c in df_audit.columns]

                print("[PBB-AUDIT:AGGREGATE-COUNTS]")
                if pathi_signals and 'Pathi_System_Count' in df_audit.columns:
                    calc=df_audit[pathi_signals].apply(pd.to_numeric,errors='coerce').fillna(0).sum(axis=1)
                    stored=nser('Pathi_System_Count')
                    bad=~np.isclose(calc.to_numpy(float),stored.to_numpy(float))
                    print(f"[LEGACY-UI-COUNT-AUDIT] family=Pathi mismatch_rows={int(bad.sum())} fires={int((stored>0).sum()):,} status=DIAGNOSTIC_ONLY_NOT_MODEL_GATE")
                else:
                    print("Pathi_System_Count reconstruction unavailable")
                if bigal_exact and 'BigAl_System_Count' in df_audit.columns:
                    calc=df_audit[bigal_exact].apply(pd.to_numeric,errors='coerce').fillna(0).sum(axis=1)
                    stored=nser('BigAl_System_Count')
                    bad=~np.isclose(calc.to_numpy(float),stored.to_numpy(float))
                    print(f"[LEGACY-UI-COUNT-AUDIT] family=BigAl mismatch_rows={int(bad.sum())} exact_fires={int((stored>0).sum()):,} status=DIAGNOSTIC_ONLY_NOT_MODEL_GATE")
                else:
                    print("BigAl_System_Count reconstruction unavailable")
                if 'BigAl_Tightener_Count' in df_audit.columns:
                    calc=df_audit[bigal_tight].apply(pd.to_numeric,errors='coerce').fillna(0).sum(axis=1) if bigal_tight else pd.Series(0,index=df_audit.index)
                    stored=nser('BigAl_Tightener_Count'); bad=~np.isclose(calc.to_numpy(float),stored.to_numpy(float))
                    print(f"BigAl_Tightener_Count mismatch rows={int(bad.sum())} {'PASS' if not bad.any() else 'FAIL'} | tightener rows={int((stored>0).sum()):,}")
                if 'BigAl_Enhancer_Count' in df_audit.columns:
                    calc=df_audit[bigal_enh].apply(pd.to_numeric,errors='coerce').fillna(0).sum(axis=1) if bigal_enh else pd.Series(0,index=df_audit.index)
                    stored=nser('BigAl_Enhancer_Count'); bad=~np.isclose(calc.to_numpy(float),stored.to_numpy(float))
                    print(f"BigAl_Enhancer_Count mismatch rows={int(bad.sum())} {'PASS' if not bad.any() else 'FAIL'} | enhancer rows={int((stored>0).sum()):,}")

                # ---------- population and routing ----------
                print("[PBB-AUDIT:PATHI-POPULATION]")
                if pathi_signals:
                    pstats=[]
                    for c in pathi_signals:
                        s=nser(c); pstats.append((c,int(s.eq(1).sum())))
                    print(" | ".join(f"{c}={v}" for c,v in pstats))
                print(f"Pathi_System_Count active rows={int(nser('Pathi_System_Count').gt(0).sum()):,}")

                print("[PBB-AUDIT:BIGAL-POPULATION]")
                if bigal_exact:
                    bstats=[(c,int(nser(c).eq(1).sum())) for c in bigal_exact]
                    print(" | ".join(f"{c}={v}" for c,v in bstats))
                print(f"BigAl exact active rows={int(nser('BigAl_System_Count').gt(0).sum()):,} | tightener rows={int(nser('BigAl_Tightener_Count').gt(0).sum()):,} | enhancer rows={int(nser('BigAl_Enhancer_Count').gt(0).sum()):,} | data-ready rows={int(nser('BigAl_DataReady_Count').gt(0).sum()):,}")

                # Sport routing checks for the families most vulnerable to prefix collisions.
                if 'Sport' in df_audit.columns:
                    sp=df_audit['Sport'].astype(str).str.upper().str.strip()
                    cfl=[c for c in bigal_cols if str(c).startswith('BigAl_CFL') and pd.api.types.is_numeric_dtype(df_audit[c])]
                    cf=[c for c in bigal_cols if str(c).startswith('BigAl_CF') and not str(c).startswith('BigAl_CFL') and pd.api.types.is_numeric_dtype(df_audit[c])]
                    wnba=[c for c in bigal_cols if str(c).startswith('BigAl_WNBA') and pd.api.types.is_numeric_dtype(df_audit[c])]
                    def routed_bad(cols, allowed):
                        if not cols: return 0
                        anyon=df_audit[cols].apply(pd.to_numeric,errors='coerce').fillna(0).ne(0).any(axis=1)
                        return int((anyon & ~sp.isin(allowed)).sum())
                    print("[PBB-AUDIT:SPORT-ROUTING]")
                    print(f"CFL-on-nonCFL rows={routed_bad(cfl,['CFL'])} | CF-on-nonNCAAF rows={routed_bad(cf,['NCAAF'])} | WNBA-on-nonWNBA rows={routed_bad(wnba,['WNBA'])}")

                # ---------- Big Al tightener + enhancer integrity ----------
                print("[PBB-AUDIT:BIGAL-TIGHTENERS]")
                active_tighteners=[]
                parent_violations=0
                tightener_population=[]
                for tc,parent in BIGAL_TIGHTENER_PARENT.items():
                    if tc not in df_audit.columns or _is_retired_bigal_feature_name(tc) or _is_retired_bigal_feature_name(parent):
                        continue
                    fires=int(nser(tc).gt(0).sum())
                    tightener_population.append((tc,fires))
                    if fires:
                        active_tighteners.append(tc)
                    if parent in df_audit.columns:
                        bad=int((nser(tc).gt(0) & ~nser(parent).gt(0)).sum())
                        parent_violations += bad
                        print(f"{tc}: fires={fires:,} parent={parent} parent_violation_rows={bad} {'PASS' if bad==0 else 'FAIL'}")
                    else:
                        print(f"{tc}: fires={fires:,} parent={parent} parent=MISSING")
                calc_tight=sum((nser(c) for c,_ in tightener_population), start=pd.Series(0.0,index=df_audit.index)) if tightener_population else pd.Series(0.0,index=df_audit.index)
                if 'BigAl_Tightener_Count' in df_audit.columns:
                    bad=~np.isclose(calc_tight.to_numpy(float),nser('BigAl_Tightener_Count').to_numpy(float))
                    print(f"canonical tightener-count mismatch rows={int(bad.sum())} {'PASS' if not bad.any() else 'FAIL'} | parent violations={parent_violations}")

                print("[PBB-AUDIT:BIGAL-ENHANCERS]")
                enh_present=[c for c in BIGAL_ENHANCER_COLS if c in df_audit.columns]
                for c in enh_present:
                    print(f"{c}={int(nser(c).gt(0).sum()):,}")
                calc_enh=sum((nser(c) for c in enh_present), start=pd.Series(0.0,index=df_audit.index)) if enh_present else pd.Series(0.0,index=df_audit.index)
                if 'BigAl_Enhancer_Count' in df_audit.columns:
                    bad=~np.isclose(calc_enh.to_numpy(float),nser('BigAl_Enhancer_Count').to_numpy(float))
                    print(f"canonical enhancer-count mismatch rows={int(bad.sum())} {'PASS' if not bad.any() else 'FAIL'} | canonical flags present={len(enh_present)}/{len(BIGAL_ENHANCER_COLS)}")
                    # Enhancers must remain separate from exact counts. A row may have both,
                    # but enhancer-only rows may not inflate BigAl_System_Count.
                    enh_only=calc_enh.gt(0) & nser('BigAl_System_Count').eq(0)
                    print(f"enhancer-only rows={int(enh_only.sum()):,} | enhancer flags never directly included in exact reconstruction=PASS")

                # ---------- Pathi expert-family decomposition ----------
                print("[PBB-AUDIT:PATHI-EXPERT-DECOMPOSITION]")
                exact_active=(df_audit[pathi_signals].apply(pd.to_numeric,errors='coerce').fillna(0).ne(0).any(axis=1) if pathi_signals else pd.Series(False,index=df_audit.index))
                key_cols=[c for c in PATHI_KEY_EVENT_COLS if c in df_audit.columns]
                role_cols=[c for c in PATHI_ROLE_CONTEXT_COLS if c in df_audit.columns]
                key_active=(df_audit[key_cols].apply(pd.to_numeric,errors='coerce').fillna(0).ne(0).any(axis=1) if key_cols else pd.Series(False,index=df_audit.index))
                role_active=(df_audit[role_cols].apply(pd.to_numeric,errors='coerce').fillna(0).ne(0).any(axis=1) if role_cols else pd.Series(False,index=df_audit.index))
                expert_active=nser('Brain_Expert_Pathi_Active').eq(1) if 'Brain_Expert_Pathi_Active' in df_audit.columns else pd.Series(False,index=df_audit.index)
                print(f"exact-system active={int(exact_active.sum()):,} | key-event active={int(key_active.sum()):,} | role-context active={int(role_active.sum()):,} | Brain Pathi active={int(expert_active.sum()):,}")
                print(f"Pathi active explained by exact-or-key={int((expert_active & (exact_active|key_active)).sum()):,}/{int(expert_active.sum()):,} | role-context overlap={int((expert_active&role_active).sum()):,}")
                unexplained=expert_active & ~(exact_active|key_active)
                print(f"Pathi expert active unexplained by configured activation contract={int(unexplained.sum())} {'PASS' if not unexplained.any() else 'FAIL'}")

                # ---------- Expert independence diagnostic (diagnostic only) ----------
                print("[PBB-AUDIT:EXPERT-INDEPENDENCE]")
                if all(c in df_audit.columns for c in ['Brain_Expert_Pathi_Active','Brain_Expert_Market_Active','Brain_Expert_Pathi_Direction','Brain_Expert_Market_Direction']):
                    pa=nser('Brain_Expert_Pathi_Active').eq(1); ma=nser('Brain_Expert_Market_Active').eq(1)
                    pdire=nser('Brain_Expert_Pathi_Direction'); mdire=nser('Brain_Expert_Market_Direction')
                    joint=pa&ma&pdire.ne(0)&mdire.ne(0)
                    agree=joint&pdire.eq(mdire)
                    print(f"Pathi+Market directional overlap={int(joint.sum()):,} | same-direction={int(agree.sum()):,} ({(100*agree.sum()/joint.sum() if joint.sum() else 0):.2f}%)")
                    print("NOTE: overlap is diagnostic, not counted as independent credibility yet")

                # ---------- Brain expert-state consistency ----------
                print("[PBB-AUDIT:BRAIN-EXPERT-STATE]")
                experts=['BigAl','Pathi','Market','Power','Form','Schedule','Price','Historical']
                if all(c in df_audit.columns for c in [
                    'Brain_Expert_NCAAFStat_Active','Brain_Expert_NCAAFStat_Direction','Brain_Expert_NCAAFStat_Intensity'
                ]):
                    experts.append('NCAAFStat')
                for name in experts:
                    ac=f'Brain_Expert_{name}_Active'; dc=f'Brain_Expert_{name}_Direction'; ic=f'Brain_Expert_{name}_Intensity'
                    if all(c in df_audit.columns for c in [ac,dc,ic]):
                        a=nser(ac); d=nser(dc); inten=nser(ic)
                        bad_inactive_dir=int(((a==0)&(d!=0)).sum())
                        bad_inactive_int=int(((a==0)&(inten!=0)).sum())
                        bad_dir=int((~d.isin([-1,0,1])).sum())
                        print(f"{name}: active={int((a==1).sum()):,} dir(+/-/0)={int((d>0).sum()):,}/{int((d<0).sum()):,}/{int((d==0).sum()):,} intensity_mean={inten.mean():.4f} inactive_dir_bad={bad_inactive_dir} inactive_intensity_bad={bad_inactive_int} dir_domain_bad={bad_dir}")
                    else:
                        print(f"{name}: MISSING expert-state columns")

                # ---------- V11.4 ensemble-summary reconstruction ----------
                print("[PBB-AUDIT:ENSEMBLE-SUMMARY]")
                _enames=['BigAl','Pathi','Market','Power','Form','Schedule','Price','Historical']
                if all(c in df_audit.columns for c in [
                    'Brain_Expert_NCAAFStat_Active','Brain_Expert_NCAAFStat_Intensity'
                ]):
                    _enames.append('NCAAFStat')
                _icols=[f'Brain_Expert_{x}_Intensity' for x in _enames]
                _acols=[f'Brain_Expert_{x}_Active' for x in _enames]
                if all(c in df_audit.columns for c in _icols+_acols):
                    _ex=df_audit[_icols].apply(pd.to_numeric,errors='coerce').fillna(0.0)
                    _ac=df_audit[_acols].apply(pd.to_numeric,errors='coerce').fillna(0).gt(0)
                    _exa=_ex.where(_ac.to_numpy())
                    _mean=_exa.mean(axis=1,skipna=True).fillna(0)
                    _disp=_exa.std(axis=1,ddof=0,skipna=True).fillna(0)
                    _max=_ex.where(_ac.to_numpy(),0.0).max(axis=1)
                    _bad_mean=int((~np.isclose(_mean.to_numpy(float),nser('Brain_Expert_Mean_Strength').to_numpy(float),atol=1e-6,equal_nan=True)).sum())
                    _bad_disp=int((~np.isclose(_disp.to_numpy(float),nser('Brain_Expert_Dispersion').to_numpy(float),atol=1e-6,equal_nan=True)).sum())
                    _bad_max=int((~np.isclose(_max.to_numpy(float),nser('Brain_Expert_Max_Strength').to_numpy(float),atol=1e-6,equal_nan=True)).sum())
                    print(f"Mean Strength reconstruction mismatch={_bad_mean} {'PASS' if _bad_mean==0 else 'FAIL'} | mean={_mean.mean():.4f}")
                    print(f"Dispersion reconstruction mismatch={_bad_disp} {'PASS' if _bad_disp==0 else 'FAIL'} | mean={_disp.mean():.4f} max={_disp.max():.4f}")
                    print(f"Max Strength reconstruction mismatch={_bad_max} {'PASS' if _bad_max==0 else 'FAIL'} | mean={_max.mean():.4f}")
                else:
                    print("Ensemble-summary reconstruction unavailable: expert state columns missing")

                # ---------- V11.4 schedule-source symmetry ----------
                print("[PBB-AUDIT:SCHEDULE-SOURCES]")
                _sched_req=['Brain_Expert_Schedule_Active','Brain_Expert_Schedule_Direction','Brain_Expert_Schedule_Intensity']
                if all(c in df_audit.columns for c in _sched_req):
                    _sa=nser('Brain_Expert_Schedule_Active').eq(1)
                    _sd=nser('Brain_Expert_Schedule_Direction')
                    print(f"Schedule active={int(_sa.sum()):,} | positive={int((_sa&_sd.gt(0)).sum()):,} | negative={int((_sa&_sd.lt(0)).sum()):,} | active-neutral={int((_sa&_sd.eq(0)).sum()):,}")
                    if 'Brain_Schedule_Rest_Diff_Days' in df_audit.columns:
                        _rd=pd.to_numeric(df_audit['Brain_Schedule_Rest_Diff_Days'],errors='coerce')
                        print(f"Brain rest-diff nonzero={int(_rd.ne(0).sum()):,} positive(>=1d)={int(_rd.ge(1).sum()):,} negative(<=-1d)={int(_rd.le(-1).sum()):,} median={_rd.median()}")
                    if all(c in df_audit.columns for c in ['Days_Since_Last_Game_System','Opp_Days_Since_Last_Game_System']):
                        _cur_rest=pd.to_numeric(df_audit['Days_Since_Last_Game_System'],errors='coerce')
                        _opp_rest=pd.to_numeric(df_audit['Opp_Days_Since_Last_Game_System'],errors='coerce')
                        _pair=_cur_rest.notna()&_opp_rest.notna()
                        _raw_diff=(_cur_rest-_opp_rest).where(_pair)
                        print(f"raw paired rest ready={int(_pair.sum()):,} diff_pos={int(_raw_diff.ge(1).sum()):,} diff_neg={int(_raw_diff.le(-1).sum()):,}")
                    for _c in ['Brain_Schedule_Current_B2B','Brain_Schedule_Opp_B2B','Brain_Schedule_Current_3in4','Brain_Schedule_Opp_3in4','Brain_Schedule_Current_ByeProxy','Brain_Schedule_Opp_ByeProxy']:
                        if _c in df_audit.columns:
                            print(f"{_c}={int(nser(_c).eq(1).sum()):,}")
                    if all(c in df_audit.columns for c in ['Had_Bye_Last_Game_System','Opp_Had_Bye_Last_Game_System']):
                        _cb=pd.to_numeric(df_audit['Had_Bye_Last_Game_System'],errors='coerce')
                        _ob=pd.to_numeric(df_audit['Opp_Had_Bye_Last_Game_System'],errors='coerce')
                        _br=_cb.notna()&_ob.notna()
                        print(f"raw recent-bye paired ready={int(_br.sum()):,} current_only={int((_br&_cb.eq(1)&_ob.eq(0)).sum()):,} opp_only={int((_br&_cb.eq(0)&_ob.eq(1)).sum()):,}")
                    _sym_ok = bool(((_sa&_sd.gt(0)).any() and (_sa&_sd.lt(0)).any()) or (not _sa.any()))
                    print(f"schedule two-sided directional evidence={'PASS' if _sym_ok else 'WARN'}")
                else:
                    print("Schedule-source audit unavailable: expert state columns missing")

                # Direct raw->Brain activation reconciliation.
                print("[PBB-AUDIT:CROSS-LAYER]")
                if 'Brain_Expert_BigAl_Active' in df_audit.columns:
                    expected=(nser('BigAl_System_Count')+nser('BigAl_Tightener_Count')+nser('BigAl_Enhancer_Count')).gt(0)
                    actual=nser('Brain_Expert_BigAl_Active').eq(1)
                    print(f"[LEGACY-BRAIN-ACTIVE-AUDIT] family=BigAl mismatch_rows={int((expected!=actual).sum())} status=RETIRED_FROM_MODEL_GATE")
                if 'Brain_Expert_Pathi_Active' in df_audit.columns:
                    keyev=(nser('Pathi_FB_Moved_Through_Key').gt(0)|nser('Pathi_FB_Crossed_Key_Toward_Team').gt(0)|nser('Pathi_FB_Crossed_Key_Away_From_Team').gt(0)|nser('Pathi_FB_Moved_Onto_Key').gt(0)|nser('Pathi_FB_Moved_Off_Key').gt(0))
                    expected=nser('Pathi_System_Count').gt(0)|keyev
                    actual=nser('Brain_Expert_Pathi_Active').eq(1)
                    print(f"[LEGACY-BRAIN-ACTIVE-AUDIT] family=Pathi mismatch_rows={int((expected!=actual).sum())} status=RETIRED_FROM_MODEL_GATE")

                # Agreement flags must correspond to active directional experts.
                print("[PBB-AUDIT:AGREEMENT-INTEGRITY]")
                pair_defs=[
                    ('BigAl','Pathi','Brain_BigAl_Pathi_Agreement','Brain_BigAl_Pathi_Conflict'),
                    ('BigAl','Market','Brain_BigAl_Market_Agreement','Brain_BigAl_Market_Conflict'),
                    ('Pathi','Market','Brain_Pathi_Market_Agreement','Brain_Pathi_Market_Conflict'),
                    ('BigAl','Historical','Brain_BigAl_Historical_Agreement','Brain_BigAl_Historical_Conflict'),
                    ('Pathi','Historical','Brain_Pathi_Historical_Agreement','Brain_Pathi_Historical_Conflict'),
                    ('Market','Historical','Brain_Market_Historical_Agreement','Brain_Market_Historical_Conflict'),
                ]
                for a,b,agree,conf in pair_defs:
                    req=[f'Brain_Expert_{a}_Active',f'Brain_Expert_{a}_Direction',f'Brain_Expert_{b}_Active',f'Brain_Expert_{b}_Direction',agree,conf]
                    if all(c in df_audit.columns for c in req):
                        aa=nser(req[0]).eq(1); ab=nser(req[2]).eq(1); da=nser(req[1]); db=nser(req[3]); eligible=aa&ab&da.ne(0)&db.ne(0)
                        exp_ag=eligible&da.eq(db); exp_cf=eligible&da.eq(-db)
                        bad_ag=int((nser(agree).eq(1)!=exp_ag).sum()); bad_cf=int((nser(conf).eq(1)!=exp_cf).sum())
                        print(f"{a}-{b}: eligible={int(eligible.sum()):,} agree={int(exp_ag.sum()):,} conflict={int(exp_cf.sum()):,} agree_mismatch={bad_ag} conflict_mismatch={bad_cf}")

                # Regime sanity.
                print("[PBB-AUDIT:REGIMES]")
                if all(c in df_audit.columns for c in ['Brain_Regime_EarlySeason','Brain_Regime_MatureSeason','Brain_Regime_LateSeason']):
                    ss=df_audit[['Brain_Regime_EarlySeason','Brain_Regime_MatureSeason','Brain_Regime_LateSeason']].apply(pd.to_numeric,errors='coerce').fillna(0).sum(axis=1)
                    print(f"season overlap rows={int((ss>1).sum())} {'PASS' if not (ss>1).any() else 'FAIL'}")
                if all(c in df_audit.columns for c in ['Brain_Regime_QuietMarket','Brain_Regime_ActiveMarket','Brain_Regime_SteamMarket']):
                    q=nser('Brain_Regime_QuietMarket').eq(1); a=nser('Brain_Regime_ActiveMarket').eq(1); st=nser('Brain_Regime_SteamMarket').eq(1)
                    print(f"quiet&active={int((q&a).sum())} | steam_without_active={int((st&~a).sum())} | quiet={int(q.sum()):,} active={int(a.sum()):,} steam={int(st.sum()):,}")

                # Candidate availability confirms all three layers actually reach AutoFS inventory.
                modelish=pathi_bigal_numeric_feature_cols(df_audit)
                print("[PBB-AUDIT:MODEL-CANDIDATES]")
                print(f"Pathi candidates={sum(str(c).startswith('Pathi_') for c in modelish)} | BigAl candidates={sum(str(c).startswith('BigAl_') for c in modelish)} | Brain candidates={sum(str(c).startswith('Brain_') and not str(c).startswith('Brain_Target_') for c in modelish)}")
                leaked=[c for c in modelish if str(c).startswith('Brain_Target_')]
                print(f"Brain target leakage candidates={len(leaked)} {'PASS' if not leaked else 'FAIL '+str(leaked[:10])}")

                # Representative ACTIVE rows only, much more useful than a tail full of zeros.
                base_cols=[c for c in ['Sport','Game_Key','Team','Opponent','Market','Outcome','Value','Odds_Price'] if c in df_audit.columns]
                for fam,rawc,actc in [
                    ('BIGAL','BigAl_System_Count','Brain_Expert_BigAl_Active'),
                    ('PATHI','Pathi_System_Count','Brain_Expert_Pathi_Active'),
                    ('BRAIN',None,'Brain_Expert_Active_Count')
                ]:
                    if actc not in df_audit.columns: continue
                    mask=nser(actc).gt(0)
                    if not mask.any():
                        print(f"[PBB-AUDIT:{fam}-EXAMPLES] none active in this slice")
                        continue
                    extra=[c for c in [rawc,'BigAl_Tightener_Count','BigAl_Enhancer_Count','Brain_Expert_BigAl_Active','Brain_Expert_BigAl_Direction','Brain_Expert_BigAl_Intensity','Brain_Expert_Pathi_Active','Brain_Expert_Pathi_Direction','Brain_Expert_Pathi_Intensity','Brain_Expert_Market_Active','Brain_Expert_Market_Direction','Brain_Expert_Market_Intensity','Brain_Conflict_Count','Brain_Edge_Durability','Brain_Decision_Readiness'] if c and c in df_audit.columns]
                    cols=[]
                    for c in base_cols+extra:
                        if c not in cols: cols.append(c)
                    print(f"[PBB-AUDIT:{fam}-EXAMPLES] showing {min(max_rows,int(mask.sum()))} active rows")
                    print(df_audit.loc[mask,cols].tail(max_rows).to_string(index=False))

                print("="*100+"\n")
            except Exception as e:
                print(f"[PBB-AUDIT] WARNING - integrity audit failed but training will continue: {type(e).__name__}: {e}")

        _audit_ai_brain_frame(df_market, market)
        _audit_pathi_bigal_brain_integrity(df_market, market)
        
        # Stable identity shared by all head-specific frames
        df_market = df_market.copy()
        df_market["_SOURCE_ROW_ID"] = np.arange(
            len(df_market),
            dtype=np.int64,
        )
        
        # 3) head-specific valid frames
        df_outcome = _filter_for_training_head(df_market, "outcome")
        df_situation = _filter_for_training_head(df_market, "situation")
        df_value = _filter_for_training_head(df_market, "value")        
        # 3) head-specific valid frames
        df_outcome = _filter_for_training_head(df_market, "outcome")
        df_situation = _filter_for_training_head(df_market, "situation")
        df_value = _filter_for_training_head(df_market, "value")
        
        print(f"{market} outcome rows:   {len(df_outcome)}")
        print(f"{market} situation rows: {len(df_situation)}")
        print(f"{market} value rows:     {len(df_value)}")
        
        # ----------------------------
        # Canonical head-specific base frames
        # ----------------------------
        df_outcome_valid = df_outcome.reset_index(drop=True)
        df_situation_valid = df_situation.reset_index(drop=True)
        df_value_valid = df_value.reset_index(drop=True)
        
        if df_outcome_valid.empty:
            st.warning(f"⚠️ Skipping {market.upper()} — no valid rows after outcome-target filtering.")
            return None
        
        # Keep outcome frame as the main canonical frame for outcome pipeline
        df_valid = df_outcome_valid
        
        # ----------------------------
        # Outcome target
