def _portable_calibrator(cal):
    """
    Convert calibrator / adapter objects into a pickle-portable representation.
    Goal: avoid pickling anything defined in Streamlit UI modules.
    """
    if cal is None:
        return None

    # If it's already a simple dict, keep it
    if isinstance(cal, dict):
        return cal

    # If it's a tuple like ("iso", obj) or ("platt", obj) keep name + try to serialize obj safely
    if isinstance(cal, (tuple, list)) and len(cal) == 2 and isinstance(cal[0], str):
        name, obj = cal
        return {"type": str(name), "obj": _portable_calibrator(obj)}

    # If it's identity-ish (your H2H case), store a tag instead of the object
    cls = cal.__class__
    mod = getattr(cls, "__module__", "")
    name = getattr(cls, "__name__", "")

    # Anything coming from Streamlit UI module is NOT portable
    if mod in {"sharp_line_dashboard", "__main__"}:
        # preserve minimal behavior: identity transform
        return {"type": "identity", "eps": float(getattr(cal, "eps", 1e-6))}

    # If it looks like an identity calibrator regardless of module
    if name.lower() in {"_identityisocal", "identityisocal", "identity"}:
        return {"type": "identity", "eps": float(getattr(cal, "eps", 1e-6))}

    # If it's a sklearn calibrator or something pickle-safe, allow it through
    return cal


def save_model_to_gcs(
    model,
    sport,
    market,
    bucket_name="sharp-models",
    calibrator=None,
    team_feature_map=None,
    book_reliability_map=None,
    feature_list=None,
    **kwargs,
):
    """
    Saves a *portable* dict bundle.
    Never pickle custom wrapper objects as the top-level 'model' unless unavoidable.
    """
    try:
        import cloudpickle as pickler
    except ImportError:
        import pickle as pickler

    sport_l  = str(sport).lower().strip()
    market_l = str(market).lower().strip()
    canonical_filename = f"sharp_win_model_{sport_l}_{market_l}.pkl"
    filename = str(kwargs.pop("object_name", "") or canonical_filename).strip()

    # ---- normalize what we save ----
    # If caller passed an already-built bundle, keep it.
    if isinstance(model, dict):
        payload = dict(model)
        payload.setdefault("schema_version", 2)
        payload.setdefault("sport", sport_l)
        payload.setdefault("market", market_l)
        if calibrator is not None and "iso_blend" not in payload:
            payload["iso_blend"] = _portable_calibrator(calibrator)
        if team_feature_map is not None and "team_feature_map" not in payload:
            payload["team_feature_map"] = team_feature_map
        if book_reliability_map is not None and "book_reliability_map" not in payload:
            payload["book_reliability_map"] = book_reliability_map
        if feature_list is not None and "feature_list" not in payload:
            payload["feature_list"] = feature_list
    else:
        # Prefer saving the estimator itself, not an adapter wrapper.
        # If model has attributes like .model or .estimator, unwrap it.
        base_model = getattr(model, "model", None) or getattr(model, "estimator", None) or model

        payload = {
            "schema_version": 2,
            "sport": sport_l,
            "market": market_l,
            "model": base_model,              # single estimator OR timing model
            "iso_blend": calibrator,          # calibrator object or dict
            "team_feature_map": team_feature_map,
            "book_reliability_map": book_reliability_map,
        }
        if feature_list is not None:
            payload["feature_list"] = feature_list

    # ---- serialize & upload ----
    try:
        buffer = BytesIO()
        pickler.dump(payload, buffer)
        buffer.seek(0)

        client = storage.Client()
        bucket = client.bucket(bucket_name)
        blob = bucket.blob(filename)
        blob.upload_from_file(buffer, content_type="application/octet-stream")

        print(f"✅ Saved model artifact to GCS: gs://{bucket_name}/{filename}")
        return {"bucket": bucket_name, "path": filename}
    except Exception as e:
        logging.error(f"❌ Failed to save model to GCS: {e}", exc_info=True)
        raise

