            # ✅ UI filters (run before any normalization)
            if selected_market != "All":
                filtered_df = filtered_df[filtered_df['Market'] == selected_market]
            if selected_date != "All":
                filtered_df = filtered_df[filtered_df['Event_Date_Only'] == selected_date]
            
    
    
          
            #st.write("🧪 Columns ibefore soummary group:")
            #st.write(filtered_df.columns.tolist())
                
            
            # Step 5: Group from merged filtered_df to produce summary
            if 'System_Signals_Text' not in filtered_df.columns:
                filtered_df['System_Signals_Text'] = '—'
            if 'Pathi_Active_Text' not in filtered_df.columns:
                filtered_df['Pathi_Active_Text'] = '—'
            if 'BigAl_Active_Text' not in filtered_df.columns:
                filtered_df['BigAl_Active_Text'] = '—'

            # Explicit UI probability provenance. Scoring_Market is the authoritative
            # runtime indicator because V13_Cover_Prob may be calculated in shadow even
            # while the incumbent V12 probability continues to drive the UI.
            def _ui_probability_source_row(r):
                _scoring = str(r.get('Scoring_Market', '') or '').strip().lower()
                _market = str(r.get('Market', '') or '').strip().lower()
                if 'v13_promoted' in _scoring:
                    _ver = str(r.get('V13_Version', '') or '').strip()
                    # Keep the table compact even when V13_Version contains a dated build label.
                    return 'V13.2.0' if '13.2' in _ver else ('V13.1.2' if ('13.1.2' in _ver or '13.1.1' in _ver or '13.1.0' in _ver or not _ver) else _ver)
                if _market in ('spread', 'spreads') and pd.notna(r.get('V12_Legacy_Model_Prob', np.nan)):
                    return 'V12 Champion'
                return 'Current Champion'

            def _ui_v13_overlay_status_row(r):
                _scoring = str(r.get('Scoring_Market', '') or '').strip().lower()
                if 'v13_promoted' not in _scoring:
                    return 'Not driving UI'
                _parts = ['AutoFS Core PRIMARY · residual experts']
                _cal = str(r.get('V13_Core_Calibration_Method', 'identity') or 'identity').upper()
                _cal_active = pd.to_numeric(pd.Series([r.get('V13_Core_Calibration_Active', 0)]), errors='coerce').fillna(0).iloc[0] > 0
                _parts.append(f'Cal {_cal}' if _cal_active else 'Cal IDENTITY')
                _is_residual_v = '13.1.2' in str(r.get('V13_Version', '') or '')
                _f_active = pd.to_numeric(pd.Series([r.get('V13_Fundamental_Overlay_Active', 0)]), errors='coerce').fillna(0).iloc[0] > 0
                _f_weight = pd.to_numeric(pd.Series([r.get('V13_Fundamental_Overlay_Weight', 0.0)]), errors='coerce').fillna(0).iloc[0]
                if _f_active and float(_f_weight) > 0:
                    _freg = str(r.get('V13_Fundamental_Overlay_Regime', '') or '').strip()
                    if _is_residual_v:
                        _edge = pd.to_numeric(pd.Series([r.get('V13_Fundamental_Residual_Edge', 0.0)]), errors='coerce').fillna(0).iloc[0]
                        _trust = pd.to_numeric(pd.Series([r.get('V13_Fundamental_Residual_Trust', _f_weight)]), errors='coerce').fillna(0).iloc[0]
                        _parts.append(f'Fundamental ON (Trust {float(_trust)*100:.0f}% · Edge {float(_edge)*100:+.1f}pp{" · " + _freg if _freg else ""})')
                    else:
                        _parts.append(f'Fundamental ON ({float(_f_weight)*100:.1f}%{" · " + _freg if _freg else ""})')
                else:
                    _parts.append('Fundamental OFF')
                for _fam, _label in [('Market','Market'), ('BigAl','Big Al'), ('Pathi','Pathi')]:
                    _active = pd.to_numeric(pd.Series([r.get(f'V13_{_fam}_Overlay_Active', 0)]), errors='coerce').fillna(0).iloc[0] > 0
                    _weight = pd.to_numeric(pd.Series([r.get(f'V13_{_fam}_Overlay_Weight', 0.0)]), errors='coerce').fillna(0).iloc[0]
                    if _active and float(_weight) > 0:
                        _reg = str(r.get(f'V13_{_fam}_Overlay_Regime', '') or '').strip()
                        if _is_residual_v:
                            _edge = pd.to_numeric(pd.Series([r.get(f'V13_{_fam}_Residual_Edge', 0.0)]), errors='coerce').fillna(0).iloc[0]
                            _trust = pd.to_numeric(pd.Series([r.get(f'V13_{_fam}_Residual_Trust', _weight)]), errors='coerce').fillna(0).iloc[0]
                            _ind = pd.to_numeric(pd.Series([r.get(f'V13_{_fam}_Independence', 1.0)]), errors='coerce').fillna(1).iloc[0]
                            _ind_txt = f' · Indep {float(_ind)*100:.0f}%' if float(_ind) < 0.999 else ''
                            _parts.append(f'{_label} ON (Trust {float(_trust)*100:.0f}% · Edge {float(_edge)*100:+.1f}pp{_ind_txt}{" · " + _reg if _reg else ""})')
                        else:
                            _parts.append(f'{_label} ON ({float(_weight)*100:.1f}%{" · " + _reg if _reg else ""})')
                    else:
                        _parts.append(f'{_label} OFF')
                return ' | '.join(_parts)

            filtered_df['Probability Source'] = filtered_df.apply(_ui_probability_source_row, axis=1)
            filtered_df['V13 Overlays'] = filtered_df.apply(_ui_v13_overlay_status_row, axis=1)

            _summary_agg = {
                'Rec Line': 'mean',
                'Sharp Line': 'mean',
                'Rec Odds': 'first',
                'Sharp Odds': 'first',
                'Rec Move': 'mean',
                'Sharp Move': 'mean',
                'Model Prob': 'mean',
                'Probability Source': 'first',
                'V13 Overlays': 'first',
                'Timing_Opportunity_Score': 'first',
                'Timing_Stage': 'first',
                'Confidence Tier': lambda x: x.mode().iloc[0] if not x.mode().empty else (x.iloc[0] if not x.empty else "⚠️ Missing"),
                'Confidence Trend': 'first',
                'Tier Δ': 'first',
                'Line/Model Direction': 'first',
                'Why Model Likes It': 'first',
                'System_Signals_Text': 'first',
                'Pathi_Active_Text': 'first',
                'BigAl_Active_Text': 'first',
                'Confidence Spark':'first',
            }
            # Fair_Line / reliability-adjusted threshold remain optional.  Edge, EV and
            # BET/PASS below are always derived locally from Model Prob + Rec Odds.
            for _c, _fn in {'Fair_Line':'mean', 'Bet_Edge_Threshold':'mean'}.items():
                if _c in filtered_df.columns:
                    _summary_agg[_c] = _fn

            summary_grouped = (
                filtered_df
                .groupby(['Game_Key', 'Matchup', 'Market', 'Outcome'], as_index=False)
                .agg(_summary_agg)
            )

            # === UI-local fair value calculations ===
            # Actionable price = recreational consensus.  If it is unavailable, fall
            # back to sharp consensus so the row remains informative rather than blank.
            _p_model = pd.to_numeric(summary_grouped['Model Prob'], errors='coerce')
            _rec_odds = pd.to_numeric(summary_grouped.get('Rec Odds'), errors='coerce')
            _sharp_odds = pd.to_numeric(summary_grouped.get('Sharp Odds'), errors='coerce')
            _price = _rec_odds.where(_rec_odds.notna(), _sharp_odds)

            def _ui_implied_prob_from_american(odds):
                o = pd.to_numeric(odds, errors='coerce')
                out = pd.Series(np.nan, index=o.index, dtype='float64')
                neg = o < 0
                pos = o > 0
                out.loc[neg] = (-o.loc[neg]) / ((-o.loc[neg]) + 100.0)
                out.loc[pos] = 100.0 / (o.loc[pos] + 100.0)
                return out

            def _ui_profit_per_dollar(odds):
                o = pd.to_numeric(odds, errors='coerce')
                out = pd.Series(np.nan, index=o.index, dtype='float64')
                neg = o < 0
                pos = o > 0
                out.loc[neg] = 100.0 / (-o.loc[neg])
                out.loc[pos] = o.loc[pos] / 100.0
                return out

            def _ui_prob_to_american(p):
                p = pd.to_numeric(p, errors='coerce')
                out = pd.Series(np.nan, index=p.index, dtype='float64')
                good = p.gt(0) & p.lt(1)
                fav = good & p.ge(0.5)
                dog = good & p.lt(0.5)
                out.loc[fav] = -100.0 * p.loc[fav] / (1.0 - p.loc[fav])
                out.loc[dog] = 100.0 * (1.0 - p.loc[dog]) / p.loc[dog]
                return out

            _p_break = _ui_implied_prob_from_american(_price)
            _edge = _p_model - _p_break
            _win_profit = _ui_profit_per_dollar(_price)
            _ev = (_p_model * _win_profit) - ((1.0 - _p_model) * 1.0)
            _fair_odds = _ui_prob_to_american(_p_model)

            # If the new backend supplies its reliability-adjusted hurdle, honor it;
            # otherwise use the transparent baseline of +2 percentage points.
            if 'Bet_Edge_Threshold' in summary_grouped.columns:
                _threshold = pd.to_numeric(summary_grouped['Bet_Edge_Threshold'], errors='coerce').fillna(0.02)
            else:
                _threshold = pd.Series(0.02, index=summary_grouped.index, dtype='float64')

            _valid_value = _p_model.notna() & _price.notna() & _p_break.notna() & _ev.notna()
            _is_bet = _valid_value & _edge.ge(_threshold) & _ev.ge(0.02)
            summary_grouped['Bet/Pass'] = np.where(_valid_value, np.where(_is_bet, 'BET', 'PASS'), '—')
            summary_grouped['Edge'] = _edge.apply(lambda x: f"{x*100:+.1f}%" if pd.notna(x) else "—")
            summary_grouped['EV / $1'] = _ev.apply(lambda x: f"{x:+.3f}" if pd.notna(x) else "—")
            summary_grouped['Fair Odds'] = _fair_odds.apply(lambda x: f"{x:+.0f}" if pd.notna(x) else "—")

            # Preserve the existing Fair Line display when the backend supplies a true
            # fair spread/total.  For H2H the model probability itself implies fair ML
            # odds, so use Fair Odds even with an older backend.
            def _fmt_fair_row(r):
                mk = str(r.get('Market','')).lower()
                if mk in ('h2h','moneyline','ml','headtohead'):
                    return r.get('Fair Odds', '—')
                v = pd.to_numeric(pd.Series([r.get('Fair_Line', np.nan)]), errors='coerce').iloc[0]
                if pd.isna(v):
                    return '—'
                return f"{v:+.1f}" if mk in ('spread','spreads') else f"{v:.1f}"
            summary_grouped['Fair Line'] = summary_grouped.apply(_fmt_fair_row, axis=1)

            # Format consensus American prices only after all arithmetic is complete.
            for _odds_col in ('Rec Odds','Sharp Odds'):
                summary_grouped[_odds_col] = pd.to_numeric(summary_grouped[_odds_col], errors='coerce').apply(
                    lambda x: f"{x:+.0f}" if pd.notna(x) else '—'
                )

            #st.markdown("### 🧪 Summary Grouped Debug View")
            # Round Rec Line and Sharp Line to 1 decimal
            summary_grouped['Rec Line'] = summary_grouped['Rec Line'].round(1)
            summary_grouped['Sharp Line'] = summary_grouped['Sharp Line'].round(1)
            # Print column list
            #st.code(f"🧩 Columns in summary_grouped:\n{summary_grouped.columns.tolist()}")
    
            # Step 6: Add back timestamp if available
            if 'Date + Time (EST)' in summary_df.columns:
                summary_grouped = summary_grouped.merge(
                    summary_df[['Game_Key', 'Date + Time (EST)']].drop_duplicates(),
                    on='Game_Key',
                    how='left'
                )
            
        
            required_cols = ['Model Prob', 'Confidence Tier']
                       
            # === Re-merge diagnostics AFTER groupby
           
    
            
            # ✅ Resolve _y suffixes (only if collision occurred)
            for col in ['Confidence Trend', 'Tier Δ', 'Line/Model Direction', 'Why Model Likes It']:
                if f"{col}_y" in summary_grouped.columns:
                    summary_grouped[col] = summary_grouped[f"{col}_y"]
                    summary_grouped.drop(columns=[f"{col}_x", f"{col}_y"], inplace=True, errors='ignore')
            
            # Fill empty diagnostics with ⚠️ Missing
            diagnostic_fields = ['Confidence Trend', 'Tier Δ', 'Line/Model Direction', 'Why Model Likes It']
            for col in diagnostic_fields:
                summary_grouped[col] = summary_grouped[col].fillna("⚠️ Missing")
    
